// محاكاة يدوية لـ @sentry/nextjs في بيئة الاختبار
export const captureMessage = () => {};
export const captureException = () => {};
export const init = () => {};
export const setUser = () => {};
export const setTag = () => {};
export const setExtra = () => {};
export const withScope = (cb: (scope: unknown) => void) => cb({});

import { PluginManager } from "./src/app/(main)/art-director/core/PluginManager";
import {
  Plugin,
  PluginCategory,
} from "./src/app/(main)/art-director/types/index";

class MockPlugin implements Plugin {
  id: string;
  name: string;
  nameAr: string;
  version = "1.0.0";
  description = "Mock Plugin";
  descriptionAr = "إضافة وهمية";
  category: PluginCategory = "ai-analytics";
  delay: number;

  constructor(id: string, name: string, delay: number) {
    this.id = id;
    this.name = name;
    this.nameAr = name;
    this.delay = delay;
  }

  async initialize(): Promise<void> {
    await new Promise((resolve) => setTimeout(resolve, this.delay));
  }

  async execute(): Promise<any> {
    return { success: true };
  }

  async shutdown(): Promise<void> {
    await new Promise((resolve) => setTimeout(resolve, this.delay));
  }
}

async function runBenchmark() {
  const pm = new PluginManager();
  const pluginCount = 10;
  const delay = 100; // 100ms delay per plugin

  for (let i = 0; i < pluginCount; i++) {
    pm.registerPlugin(new MockPlugin(`p${i}`, `Plugin ${i}`, delay));
  }

  console.log(
    `--- Benchmarking with ${pluginCount} plugins, each having ${delay}ms delay ---`
  );

  // Measure initializeAll
  console.log("Measuring initializeAll...");
  const startInit = Date.now();
  await pm.initializeAll();
  const endInit = Date.now();
  const initDuration = endInit - startInit;
  console.log(`initializeAll took ${initDuration}ms`);

  // Measure shutdownAll
  console.log("Measuring shutdownAll...");
  const startShutdown = Date.now();
  await pm.shutdownAll();
  const endShutdown = Date.now();
  const shutdownDuration = endShutdown - startShutdown;
  console.log(`shutdownAll took ${shutdownDuration}ms`);

  console.log("--- Results ---");
  console.log(`Total time: ${initDuration + shutdownDuration}ms`);

  // Theoretical parallel time should be around delay (+ overhead)
  // Theoretical sequential time should be around delay * pluginCount
  const expectedSequential = delay * pluginCount;
  console.log(
    `Expected sequential time: ~${expectedSequential}ms per operation`
  );
}

runBenchmark().catch(console.error);

/**
 * اختبارات End-to-End لأداة brain-storm-ai
 * يختبر التدفق الكامل من منظور المستخدم النهائي
 */

import { test, expect } from "@playwright/test";

test.describe("E2E: brain-storm-ai — تدفق تشغيلي كامل", () => {
  test.setTimeout(60000); // 60 ثانية للاختبارات الطويلة

  test.beforeEach(async ({ page }) => {
    // تنظيف localStorage قبل كل اختبار
    await page.addInitScript(() => {
      localStorage.clear();
    });

    // الذهاب إلى الصفحة
    await page.goto("/brain-storm-ai");
  });

  test("يجتاز تدفق عصف ذهني كامل من البداية إلى النهاية", async ({ page }) => {
    // انتظار تحميل الصفحة
    await expect(page.locator("text=منصة العصف الذهني الذكي")).toBeVisible();

    // إدخال فكرة إبداعية
    const briefInput = page
      .locator('textarea[placeholder*="اكتب فكرتك"]')
      .first();
    await expect(briefInput).toBeVisible();
    await briefInput.fill(
      "فكرة لتطبيق تعليمي تفاعلي باستخدام الذكاء الاصطناعي لمساعدة الطلاب في التعلم"
    );

    // بدء الجلسة
    const startButton = page.locator('button:has-text("ابدأ الجلسة")').first();
    await expect(startButton).toBeVisible();
    await startButton.click();

    // انتظار بدء المعالجة
    await expect(page.locator("text=جاري المعالجة")).toBeVisible({
      timeout: 10000,
    });

    // انتظار ظهور شريط التقدم
    await expect(page.locator("text=التقدم الكلي")).toBeVisible({
      timeout: 15000,
    });

    // مراقبة تطور التقدم عبر المراحل
    let previousProgress = 0;
    for (let attempt = 0; attempt < 10; attempt++) {
      const progressText = await page
        .locator("text=/\\d+\\.\\d+%/")
        .textContent();
      if (progressText) {
        const currentProgress = parseFloat(progressText.replace("%", ""));
        console.log(`التقدم الحالي: ${currentProgress}%`);

        // التأكد من أن التقدم يتزايد أو يظل كما هو (ليس يتناقص)
        expect(currentProgress).toBeGreaterThanOrEqual(previousProgress);
        previousProgress = currentProgress;

        // إذا وصل إلى 100% أو اكتملت الجلسة، نخرج
        if (currentProgress >= 100) {
          break;
        }
      }

      // انتظار قليل قبل التحقق التالي
      await page.waitForTimeout(2000);
    }

    // انتظار ظهور النتيجة النهائية
    await expect(
      page.locator("text=✅ تم إكمال جلسة العصف الذهني")
    ).toBeVisible({
      timeout: 30000,
    });

    // التحقق من وجود القرار النهائي
    await expect(page.locator("text=القرار النهائي:")).toBeVisible();

    // التحقق من وجود أزرار التصدير
    await expect(page.locator('button:has-text("JSON")')).toBeVisible();
    await expect(page.locator('button:has-text("Markdown")')).toBeVisible();
    await expect(page.locator('button:has-text("نسخ")')).toBeVisible();

    // التقاط screenshot للتوثيق
    await page.screenshot({
      path: `test-results/brainstorm-complete-${Date.now()}.png`,
      fullPage: true,
    });
  });

  test("يحفظ الجلسة ويسترجعها بعد إعادة التحميل", async ({ page }) => {
    // إنشاء جلسة وانتظار اكتمالها جزئياً
    await expect(page.locator("text=منصة العصف الذهني الذكي")).toBeVisible();

    const briefInput = page
      .locator('textarea[placeholder*="اكتب فكرتك"]')
      .first();
    await briefInput.fill("فكرة لاختبار الحفظ والاسترجاع");

    const startButton = page.locator('button:has-text("ابدأ الجلسة")').first();
    await startButton.click();

    // انتظار بدء المعالجة
    await expect(page.locator("text=جاري المعالجة")).toBeVisible();

    // انتظار حفظ الجلسة (سيحدث تلقائياً)
    await page.waitForTimeout(3000);

    // إعادة تحميل الصفحة
    await page.reload();

    // انتظار إعادة التحميل
    await expect(page.locator("text=منصة العصف الذهني الذكي")).toBeVisible();

    // التحقق من وجود الجلسة المحفوظة
    await expect(
      page.locator("text=فكرة لاختبار الحفظ والاسترجاع")
    ).toBeVisible();
  });

  test("يصدر الجلسة بتنسيقات مختلفة", async ({ page }) => {
    // انتظار تحميل وإنشاء جلسة مكتملة
    await expect(page.locator("text=منصة العصف الذهني الذكي")).toBeVisible();

    const briefInput = page
      .locator('textarea[placeholder*="اكتب فكرتك"]')
      .first();
    await briefInput.fill("فكرة لاختبار التصدير");

    const startButton = page.locator('button:has-text("ابدأ الجلسة")').first();
    await startButton.click();

    // انتظار اكتمال الجلسة
    await expect(
      page.locator("text=✅ تم إكمال جلسة العصف الذهني")
    ).toBeVisible({
      timeout: 45000,
    });

    // تجربة تصدير JSON
    const jsonButton = page.locator('button:has-text("JSON")');
    await expect(jsonButton).toBeVisible();

    // مراقبة التحميلات (سنحتاج إلى التعامل مع dialog التحميل)
    const downloadPromise = page.waitForEvent("download");
    await jsonButton.click();

    const download = await downloadPromise;
    expect(download.suggestedFilename()).toMatch(/brainstorm_.*\.json/);

    // تجربة تصدير Markdown
    const mdButton = page.locator('button:has-text("Markdown")');
    const mdDownloadPromise = page.waitForEvent("download");
    await mdButton.click();

    const mdDownload = await mdDownloadPromise;
    expect(mdDownload.suggestedFilename()).toMatch(/brainstorm_.*\.md/);

    // تجربة النسخ للحافظة
    const copyButton = page.locator('button:has-text("نسخ")');
    await copyButton.click();

    // التحقق من ظهور تأكيد النسخ
    await expect(page.locator('button:has-text("تم النسخ!")')).toBeVisible();
  });

  test("يتعامل مع حالات الفشل بشكل صحيح", async ({ page }) => {
    // محاكاة فشل الشبكة أو API
    await page.route("**/api/brainstorm", (route) => route.abort());

    await expect(page.locator("text=منصة العصف الذهني الذكي")).toBeVisible();

    const briefInput = page
      .locator('textarea[placeholder*="اكتب فكرتك"]')
      .first();
    await briefInput.fill("فكرة ستفشل بسبب مشكلة فنية");

    const startButton = page.locator('button:has-text("ابدأ الجلسة")').first();
    await startButton.click();

    // انتظار ظهور رسالة الخطأ
    await expect(page.locator("text=فشل في الاتصال")).toBeVisible({
      timeout: 10000,
    });

    // التأكد من عدم تجمد الواجهة
    await expect(startButton).toBeEnabled();

    // التقاط screenshot للخطأ
    await page.screenshot({
      path: `test-results/brainstorm-error-${Date.now()}.png`,
      fullPage: true,
    });
  });

  test("يعرض المراحل والتقدم بوضوح", async ({ page }) => {
    await expect(page.locator("text=منصة العصف الذهني الذكي")).toBeVisible();

    const briefInput = page
      .locator('textarea[placeholder*="اكتب فكرتك"]')
      .first();
    await briefInput.fill("فكرة لاختبار عرض المراحل");

    const startButton = page.locator('button:has-text("ابدأ الجلسة")').first();
    await startButton.click();

    // انتظار ظهور لوحة المراحل
    await expect(page.locator("text=التحليل الأولي")).toBeVisible({
      timeout: 10000,
    });

    // التحقق من وجود جميع المراحل
    await expect(page.locator("text=التحليل الأولي")).toBeVisible();
    await expect(page.locator("text=التوسع الإبداعي")).toBeVisible();
    await expect(page.locator("text=التحقق والتدقيق")).toBeVisible();
    await expect(page.locator("text=النقاش والتوافق")).toBeVisible();
    await expect(page.locator("text=التقييم النهائي")).toBeVisible();

    // التحقق من وجود شريط التقدم الكلي
    await expect(page.locator("text=التقدم الكلي")).toBeVisible();

    // التقاط screenshot للمراحل
    await page.screenshot({
      path: `test-results/brainstorm-phases-${Date.now()}.png`,
      fullPage: true,
    });
  });

  test("يحافظ على الاتساق بعد إعادة التحميل في جلسة مكتملة", async ({
    page,
  }) => {
    // إنشاء جلسة كاملة
    await expect(page.locator("text=منصة العصف الذهني الذكي")).toBeVisible();

    const briefInput = page
      .locator('textarea[placeholder*="اكتب فكرتك"]')
      .first();
    await briefInput.fill("فكرة لاختبار الاتساق بعد إعادة التحميل");

    const startButton = page.locator('button:has-text("ابدأ الجلسة")').first();
    await startButton.click();

    // انتظار اكتمال الجلسة
    await expect(
      page.locator("text=✅ تم إكمال جلسة العصف الذهني")
    ).toBeVisible({
      timeout: 45000,
    });

    // التحقق من وجود النتيجة النهائية
    await expect(page.locator("text=القرار النهائي:")).toBeVisible();

    // إعادة تحميل الصفحة
    await page.reload();

    // التأكد من الاحتفاظ بالنتيجة
    await expect(
      page.locator("text=✅ تم إكمال جلسة العصف الذهني")
    ).toBeVisible();
    await expect(page.locator("text=القرار النهائي:")).toBeVisible();

    // التقاط screenshot للتحقق من الاتساق
    await page.screenshot({
      path: `test-results/brainstorm-consistency-${Date.now()}.png`,
      fullPage: true,
    });
  });
});

import path from "path";

import bundleAnalyzer from "@next/bundle-analyzer";
import { withSentryConfig } from "@sentry/nextjs";

const isWindowsHost = process.platform === "win32";
const enableStandaloneOutput =
  process.env["NEXT_OUTPUT_MODE"] === "standalone" || !isWindowsHost;

const parsePositiveInt = (value: string | undefined): number | undefined => {
  if (!value) return undefined;
  const parsed = Number.parseInt(value, 10);
  return Number.isFinite(parsed) && parsed > 0 ? parsed : undefined;
};

const buildCpuCount = parsePositiveInt(process.env["NEXT_BUILD_CPUS"]);
const staticGenerationConcurrency = parsePositiveInt(
  process.env["NEXT_STATIC_GENERATION_MAX_CONCURRENCY"]
);
const enableWebpackMemoryOptimizations =
  process.env["NEXT_WEBPACK_MEMORY_OPTIMIZATIONS"] === "true";

// Remote image patterns configuration
const remoteImagePatterns = process.env["NEXT_IMAGE_REMOTE_PATTERNS"]
  ? JSON.parse(process.env["NEXT_IMAGE_REMOTE_PATTERNS"])
  : [
      {
        protocol: "https",
        hostname: "hebbkx1anhila5yf.public.blob.vercel-storage.com",
        port: "",
        pathname: "/**",
      },
      {
        protocol: "https",
        hostname: "*.public.blob.vercel-storage.com",
        port: "",
        pathname: "/**",
      },
      {
        protocol: "https",
        hostname: "placehold.co",
        port: "",
        pathname: "/**",
      },
      {
        protocol: "https",
        hostname: "images.unsplash.com",
        port: "",
        pathname: "/**",
      },
      {
        protocol: "https",
        hostname: "picsum.photos",
        port: "",
        pathname: "/**",
      },
    ];

const withBundleAnalyzer = bundleAnalyzer({
  enabled: process.env["ANALYZE"] === "true",
});

// CDN Configuration
const cdnUrl = process.env["NEXT_PUBLIC_CDN_URL"];
const enableCdn = process.env["NEXT_PUBLIC_ENABLE_CDN"] === "true";
const assetPrefix = enableCdn && cdnUrl ? cdnUrl : undefined;

const nextConfig = {
  ...(enableStandaloneOutput ? { output: "standalone" as const } : {}),
  reactStrictMode: true,
  transpilePackages: ["@the-copy/breakapp", "@the-copy/prompt-engineering"],
  poweredByHeader: false,
  compress: true,

  allowedDevOrigins: ["127.0.0.1", "localhost"],

  // Force @google/genai to only be loaded server-side
  serverExternalPackages: ["@google/genai", "puppeteer", "sharp"],

  // Disable production browser sourcemaps (security best practice)
  productionBrowserSourceMaps: false,

  // Ensure correct root when multiple lockfiles exist (silences Next.js warning)
  // يؤشر إلى جذر الـ monorepo لتتبع الملفات من packages/ و apps/ معًا
  outputFileTracingRoot: path.join(__dirname, "../.."),

  // CDN support for static assets
  assetPrefix,

  // Performance optimizations
  typescript: {
    ignoreBuildErrors: false,
  },
  compiler: {
    removeConsole: process.env["NODE_ENV"] === "production",
  },

  experimental: {
    ...(buildCpuCount ? { cpus: buildCpuCount } : {}),
    ...(staticGenerationConcurrency
      ? { staticGenerationMaxConcurrency: staticGenerationConcurrency }
      : {}),
    ...(enableWebpackMemoryOptimizations
      ? { webpackMemoryOptimizations: true }
      : {}),
    // SRI disabled: incompatible with standalone output in Next.js 16
    // sri: { algorithm: "sha256" },
    optimizePackageImports: [
      "@radix-ui/react-accordion",
      "@radix-ui/react-alert-dialog",
      "@radix-ui/react-avatar",
      "@radix-ui/react-checkbox",
      "@radix-ui/react-collapsible",
      "@radix-ui/react-dialog",
      "@radix-ui/react-dropdown-menu",
      "@radix-ui/react-label",
      "@radix-ui/react-menubar",
      "@radix-ui/react-popover",
      "@radix-ui/react-progress",
      "@radix-ui/react-radio-group",
      "@radix-ui/react-scroll-area",
      "@radix-ui/react-select",
      "@radix-ui/react-separator",
      "@radix-ui/react-slider",
      "@radix-ui/react-slot",
      "@radix-ui/react-switch",
      "@radix-ui/react-tabs",
      "@radix-ui/react-toast",
      "@radix-ui/react-tooltip",
      "lucide-react",
      "recharts",
    ],
  },

  async rewrites() {
    return [
      {
        source: "/api/__health",
        destination: "/api/healthz",
      },
    ];
  },

  async headers() {
    const isDev = process.env["NODE_ENV"] !== "production";

    // In development: force no-cache on all routes so browser always fetches fresh content
    if (isDev) {
      return [
        {
          source: "/(.*)",
          headers: [
            {
              key: "Cache-Control",
              value: "no-store, no-cache, must-revalidate, proxy-revalidate",
            },
            {
              key: "Pragma",
              value: "no-cache",
            },
            {
              key: "Expires",
              value: "0",
            },
          ],
        },
      ];
    }

    // Production headers — security + aggressive caching
    return [
      {
        source: "/(.*)",
        headers: [
          {
            key: "Strict-Transport-Security",
            value: "max-age=31536000; includeSubDomains; preload",
          },
          {
            key: "X-Content-Type-Options",
            value: "nosniff",
          },
          {
            key: "X-Frame-Options",
            value: "DENY",
          },
          {
            key: "X-XSS-Protection",
            value: "1; mode=block",
          },
          {
            key: "Referrer-Policy",
            value: "strict-origin-when-cross-origin",
          },
          {
            // Permissions-Policy: السماح لنفس الـ origin فقط بالوصول إلى الكاميرا والموقع
            // السبب: مسار BreakApp QR login يحتاج getUserMedia للكاميرا، وخريطة BreakApp تحتاج geolocation
            // الحظر السابق "camera=()" كان يمنع تشغيل الكاميرا نهائياً في الإنتاج — السبب الجذري للعطل
            // الصيغة "(self)" تسمح للـ origin الحالي فقط، وتمنع أي iframe خارجي من الاستفادة
            key: "Permissions-Policy",
            value: [
              "camera=(self)",
              "microphone=()",
              "geolocation=(self)",
              "interest-cohort=()",
              "payment=()",
              "usb=()",
            ].join(", "),
          },
        ],
      },
      // Keep font access permissive without overriding framework cache policy.
      {
        source: "/fonts/:path*",
        headers: [
          {
            key: "Cross-Origin-Resource-Policy",
            value: "cross-origin",
          },
        ],
      },
    ];
  },

  images: {
    remotePatterns: remoteImagePatterns,
  },

  // Turbopack configuration for Next.js 16
  turbopack: {
    resolveAlias: {
      "@editor/*": "./src/app/(main)/editor/src/*",
    },
  },

  // Webpack configuration for handling Node.js built-in modules and critical dependency warnings
  // Note: In Next.js 16, Turbopack is default. Webpack config is kept for fallback compatibility.
  webpack: (config: any, { isServer }: { isServer: boolean }) => {
    if (!isServer) {
      // Don't resolve Node.js modules on client side
      config.resolve.fallback = {
        ...config.resolve.fallback,
        fs: false,
        net: false,
        tls: false,
        dns: false,
        http2: false,
        child_process: false,
        stream: false,
        crypto: false,
        path: false,
        os: false,
        dgram: false,
        async_hooks: false,
        "node:async_hooks": false,
        "graceful-fs": false,
      };
    }

    // Suppress critical dependency warnings from OpenTelemetry and Sentry
    config.ignoreWarnings = [
      // Ignore OpenTelemetry instrumentation warnings
      {
        module: /@opentelemetry\/instrumentation/,
        message:
          /Critical dependency: the request of a dependency is an expression/,
      },
      {
        module: /require-in-the-middle/,
        message:
          /Critical dependency: require function is used in a way in which dependencies cannot be statically extracted/,
      },
      // Ignore Sentry related warnings
      {
        module: /@sentry/,
        message: /Critical dependency/,
      },
      // Ignore all OpenTelemetry related warnings
      {
        module: /@opentelemetry/,
      },
      // Generic critical dependency warnings from known safe modules (scoped)
      {
        module: /node_modules\/(import-in-the-middle|require-in-the-middle)/,
        message: /Critical dependency/,
      },
      // Ignore ESLint configuration warnings
      {
        message: /Unknown options: useEslintrc, extensions/,
      },
    ];

    // Additional webpack optimizations to reduce warnings
    config.stats = {
      ...config.stats,
      warnings: false,
      warningsFilter: [
        /Critical dependency/,
        /Unknown options/,
        /@opentelemetry/,
        /@sentry/,
      ],
    };

    return config;
  },
};

// Sentry configuration
const sentryOrg = process.env["SENTRY_ORG"];
const sentryProject = process.env["SENTRY_PROJECT"];
const sentryConfig =
  sentryOrg && sentryProject
    ? {
        org: sentryOrg,
        project: sentryProject,
        silent: !process.env["CI"],
        widenClientFileUpload: true,
        hideSourceMaps: process.env["NODE_ENV"] === "production",
        tunnelRoute: "/monitoring",
        sourcemaps: {
          disable: false,
          ignore: ["**/*manifest*.js", "**/*reference-manifest*.js"],
        },
      }
    : null;

// Export config with Sentry wrapper if configured
const configWithAnalyzer = withBundleAnalyzer(
  nextConfig as Parameters<typeof withBundleAnalyzer>[0]
);
export default sentryConfig
  ? withSentryConfig(configWithAnalyzer, sentryConfig)
  : configWithAnalyzer;

import path from "node:path";

import ts from "typescript";

const TARGET_CODES = new Set([6133, 6192, 6196]);
const MAX_PASSES = 5;

interface FileEdit {
  fileName: string;
  spanStart: number;
  spanLength: number;
  newText: string;
}

function loadTsConfig(configPath: string) {
  const configFile = ts.readConfigFile(configPath, ts.sys.readFile);
  if (configFile.error) {
    throw new Error(
      ts.flattenDiagnosticMessageText(configFile.error.messageText, "\n")
    );
  }

  return ts.parseJsonConfigFileContent(
    configFile.config,
    ts.sys,
    path.dirname(configPath)
  );
}

function createLanguageService(
  parsed: ts.ParsedCommandLine,
  currentDirectory: string
) {
  const serviceHost: ts.LanguageServiceHost = {
    getScriptFileNames: () => parsed.fileNames,
    getScriptVersion: () => "0",
    getScriptSnapshot: (fileName) => {
      const content = ts.sys.readFile(fileName);
      return content === undefined
        ? undefined
        : ts.ScriptSnapshot.fromString(content);
    },
    getCurrentDirectory: () => currentDirectory,
    getCompilationSettings: () => parsed.options,
    getDefaultLibFileName: (options) => ts.getDefaultLibFilePath(options),
    fileExists: ts.sys.fileExists,
    readFile: ts.sys.readFile,
    readDirectory: ts.sys.readDirectory,
    directoryExists: ts.sys.directoryExists,
    getDirectories: ts.sys.getDirectories,
  };

  return ts.createLanguageService(serviceHost, ts.createDocumentRegistry());
}

function collectUnusedIdentifierEdits(
  service: ts.LanguageService,
  diagnostics: readonly ts.Diagnostic[]
): FileEdit[] {
  const formatSettings: ts.FormatCodeSettings = {
    indentSize: 2,
    tabSize: 2,
    convertTabsToSpaces: true,
    semicolons: ts.SemicolonPreference.Insert,
    newLineCharacter: "\n",
  };

  const userPreferences: ts.UserPreferences = {};
  const edits: FileEdit[] = [];

  for (const diagnostic of diagnostics) {
    if (
      !diagnostic.file ||
      diagnostic.start === undefined ||
      diagnostic.length === undefined
    ) {
      continue;
    }

    const fixes = service.getCodeFixesAtPosition(
      diagnostic.file.fileName,
      diagnostic.start,
      diagnostic.start + diagnostic.length,
      [diagnostic.code],
      formatSettings,
      userPreferences
    );

    for (const fix of fixes) {
      if (fix.fixName !== "unusedIdentifier") {
        continue;
      }

      for (const change of fix.changes) {
        for (const textChange of change.textChanges) {
          edits.push({
            fileName: change.fileName,
            spanStart: textChange.span.start,
            spanLength: textChange.span.length,
            newText: textChange.newText,
          });
        }
      }
    }
  }

  return edits;
}

function applyEdits(edits: FileEdit[]): number {
  const editsByFile = new Map<string, FileEdit[]>();
  for (const edit of edits) {
    const fileEdits = editsByFile.get(edit.fileName) ?? [];
    fileEdits.push(edit);
    editsByFile.set(edit.fileName, fileEdits);
  }

  let filesChanged = 0;

  for (const [fileName, fileEdits] of editsByFile.entries()) {
    const originalText = ts.sys.readFile(fileName);
    if (originalText === undefined) {
      continue;
    }

    const uniqueEdits = [
      ...new Map(
        fileEdits.map((edit) => [
          `${edit.spanStart}:${edit.spanLength}:${edit.newText}`,
          edit,
        ])
      ).values(),
    ].sort((left, right) => right.spanStart - left.spanStart);

    let nextBlockedStart = Number.POSITIVE_INFINITY;
    let updatedText = originalText;
    let appliedChanges = 0;

    for (const edit of uniqueEdits) {
      const editEnd = edit.spanStart + edit.spanLength;
      if (editEnd > nextBlockedStart) {
        continue;
      }

      updatedText =
        updatedText.slice(0, edit.spanStart) +
        edit.newText +
        updatedText.slice(editEnd);

      nextBlockedStart = edit.spanStart;
      appliedChanges += 1;
    }

    if (appliedChanges === 0 || updatedText === originalText) {
      continue;
    }

    ts.sys.writeFile(fileName, updatedText);
    filesChanged += 1;
  }

  return filesChanged;
}

async function main(): Promise<void> {
  const configPath = path.resolve(process.cwd(), "tsconfig.json");
  const parsed = loadTsConfig(configPath);
  const currentDirectory = path.dirname(configPath);

  let totalChangedFiles = 0;

  for (let pass = 1; pass <= MAX_PASSES; pass += 1) {
    const service = createLanguageService(parsed, currentDirectory);
    const program = service.getProgram();
    if (!program) {
      throw new Error("Failed to create TypeScript program.");
    }

    const diagnostics = ts
      .getPreEmitDiagnostics(program)
      .filter(
        (diagnostic) =>
          TARGET_CODES.has(diagnostic.code) &&
          Boolean(diagnostic.file) &&
          !diagnostic.file?.isDeclarationFile
      );

    if (diagnostics.length === 0) {
      console.log(`No unused diagnostics left after pass ${pass - 1}.`);
      break;
    }

    const edits = collectUnusedIdentifierEdits(service, diagnostics);
    if (edits.length === 0) {
      console.log(`No code fixes available on pass ${pass}.`);
      break;
    }

    const changedFiles = applyEdits(edits);
    totalChangedFiles += changedFiles;
    console.log(
      `Pass ${pass}: applied unused-identifier fixes in ${changedFiles} files.`
    );

    if (changedFiles === 0) {
      break;
    }
  }

  console.log(`Finished. Files changed: ${totalChangedFiles}.`);
}

main().catch((error) => {
  console.error("Failed to apply TypeScript unused fixes.", error);
  process.exit(1);
});

