    fs.writeFileSync(reportPath, JSON.stringify(results, null, 2));
    logSuccess(`\nDetailed report saved to: ${reportPath}`);
  } catch (error) {
    logError(`Error running analysis: ${error.message}`);
    console.error(error);
    process.exit(1);
  }
}

// Run
if (require.main === module) {
