  const [editValue, setEditValue] = useState<string>("");

  const filteredItems = useMemo(() => {
    if (!searchTerm) return null;

    const results: {
      section: string;
      category: string;
      item: LineItem;
    }[] = [];
    budget.sections.forEach((section) => {
      section.categories.forEach((category) => {
        category.items.forEach((item) => {
          if (
            item.description.toLowerCase().includes(searchTerm.toLowerCase()) ||
            item.code.toLowerCase().includes(searchTerm.toLowerCase()) ||
            category.name.toLowerCase().includes(searchTerm.toLowerCase())
          ) {
            results.push({
              section: section.name,
              category: category.name,
              item,
            });
          }
        });
      });
    });
    return results;
  }, [budget, searchTerm]);

  const toggleSection = (sectionId: string) => {
    const newExpanded = new Set(expandedSections);
    if (newExpanded.has(sectionId)) {
      newExpanded.delete(sectionId);
    } else {
      newExpanded.add(sectionId);
    }
    setExpandedSections(newExpanded);
  };

  const startEditing = (
    sectionId: string,
    categoryCode: string,
    itemCode: string,
    field: keyof LineItem,
    currentValue: string | number
  ) => {
    setEditing({ sectionId, categoryCode, itemCode, field });
    setEditValue(currentValue.toString());
  };

  const saveEdit = () => {
    if (editing) {
      const { sectionId, categoryCode, itemCode, field } = editing;
      const value =
        field === "amount" || field === "rate"
          ? parseFloat(editValue) || 0
          : editValue;
      onUpdateLineItem(sectionId, categoryCode, itemCode, field, value);
      setEditing(null);
    }
  };

  const cancelEdit = () => {
    setEditing(null);
    setEditValue("");
  };

  const formatCurrency = (value: number) =>
    new Intl.NumberFormat("en-US", {
      style: "currency",
      currency: "USD",
      minimumFractionDigits: 0,
      maximumFractionDigits: 0,
    }).format(value);

  const containerVariants = {
    hidden: { opacity: 0 },
    visible: {
      opacity: 1,
      transition: {
        staggerChildren: 0.05,
      },
    },
  };

  const sectionVariants = {
    hidden: { opacity: 0, y: 20 },
    visible: { opacity: 1, y: 0 },
  };

  return (
    <motion.div
      variants={containerVariants}
      initial="hidden"
      animate="visible"
      className={`rounded-xl shadow-lg border overflow-hidden ${
        theme === "dark"
          ? "bg-black/18 border-white/8"
          : "bg-white/[0.04] border-white/8"
      }`}
    >
      <div className="bg-gradient-to-r from-indigo-800 to-purple-800 text-white p-6">
        <h2 className="text-xl font-bold uppercase tracking-wide flex items-center gap-2">
          <div className="w-1 h-6 bg-white/[0.04] rounded"></div>
          Detailed Budget Breakdown
        </h2>
        <p className="text-sm text-indigo-200 mt-1">
          Complete line-item budget with editing capabilities
        </p>
      </div>

      {/* Search Bar */}
      <div className="p-4 border-b border-white/8 dark:border-white/8">
        <div className="relative">
          <Search
            size={16}
            className="absolute left-3 top-1/2 transform -translate-y-1/2 text-white/55"
          />
          <input
            type="text"
            value={searchTerm}
            onChange={(e) => setSearchTerm(e.target.value)}
            placeholder="Search line items..."
            className={`w-full pl-10 pr-3 py-2 border rounded-lg focus:ring-2 focus:ring-indigo-500 ${
              theme === "dark"
                ? "bg-black/22 border-white/8 text-white"
                : "border-white/8"
            }`}
          />
        </div>
      </div>

      {/* Search Results */}
      <AnimatePresence>
        {searchTerm && filteredItems && (
          <motion.div
            initial={{ opacity: 0, height: 0 }}
            animate={{ opacity: 1, height: "auto" }}
            exit={{ opacity: 0, height: 0 }}
            className={`p-4 border-b ${
              theme === "dark"
                ? "border-white/8 bg-black/14"
                : "border-white/8 bg-white/[0.04]"
            }`}
          >
            <h3 className="font-semibold mb-3">
              Search Results ({filteredItems.length})
            </h3>
            <div className="space-y-2 max-h-64 overflow-y-auto">
              {filteredItems.map((result) => (
                <div
                  key={`${result.section}-${result.category}-${result.item.code}`}
                  className={`p-3 rounded-[22px] border ${
                    theme === "dark"
                      ? "bg-black/18 border-white/8"
                      : "bg-white/[0.04] border-white/8"
                  }`}
                >
                  <div className="flex justify-between items-start">
                    <div>
                      <div className="font-medium">
                        {result.item.description}
                      </div>
                      <div className="text-sm text-white/45">
                        {result.section} • {result.category} •{" "}
                        {result.item.code}
                      </div>
                    </div>
                    <div className="text-right">
                      <div className="font-semibold">
                        {formatCurrency(result.item.total)}
                      </div>
                      <div className="text-sm text-white/45">
                        {result.item.amount} ×{" "}
                        {formatCurrency(result.item.rate)}
                      </div>
                    </div>
                  </div>
                </div>
              ))}
            </div>
          </motion.div>
        )}
      </AnimatePresence>

      {/* Budget Sections */}
      <div className="overflow-x-auto">
        <table className="w-full text-sm">
          <thead
            className={`${
              theme === "dark" ? "bg-black/22" : "bg-white/[0.04]"
            } text-white/55 uppercase text-xs`}
          >
            <tr>
              <th
                className={`px-6 py-3 text-left ${
                  theme === "dark" ? "text-white/68" : "text-white/55"
                }`}
              >
                Code
              </th>
              <th
                className={`px-6 py-3 text-left ${
                  theme === "dark" ? "text-white/68" : "text-white/55"
                }`}
              >
                Description
              </th>
              <th
                className={`px-6 py-3 text-right ${
                  theme === "dark" ? "text-white/68" : "text-white/55"
                }`}
              >
                Amount
              </th>
              <th
                className={`px-6 py-3 text-left ${
                  theme === "dark" ? "text-white/68" : "text-white/55"
                }`}
              >
                Unit
              </th>
              <th
                className={`px-6 py-3 text-right ${
                  theme === "dark" ? "text-white/68" : "text-white/55"
                }`}
              >
                Rate
              </th>
              <th
                className={`px-6 py-3 text-right ${
                  theme === "dark" ? "text-white/68" : "text-white/55"
                }`}
              >
                Total
              </th>
            </tr>
          </thead>

          <tbody>
            {budget.sections.map((section) => (
              <React.Fragment key={section.id}>
                {/* Section Header */}
                <motion.tr
                  variants={sectionVariants}
                  onClick={() => toggleSection(section.id)}
                  className={`${
                    theme === "dark" ? "bg-black/22" : "bg-white/6"
                  } font-semibold cursor-pointer hover:${
                    theme === "dark" ? "bg-black/28" : "bg-white/8"
                  } transition-colors`}
                >
                  <td className="px-6 py-3 text-indigo-600" colSpan={6}>
                    <div className="flex items-center justify-between">
                      <div className="flex items-center gap-2">
                        <div className="w-1 h-4 bg-indigo-600 rounded"></div>
                        {section.name}
                      </div>
                      <div className="flex items-center gap-2">
                        <span className="text-sm font-normal text-white/45">
                          {formatCurrency(section.total)}
                        </span>
                        {expandedSections.has(section.id) ? (
                          <ChevronUp size={16} />
                        ) : (
                          <ChevronDown size={16} />
                        )}
                      </div>
                    </div>
                  </td>
                </motion.tr>

                {/* Categories and Items */}
                <AnimatePresence>
                  {expandedSections.has(section.id) && (
                    <motion.tr
                      initial={{ opacity: 0, height: 0 }}
                      animate={{ opacity: 1, height: "auto" }}
                      exit={{ opacity: 0, height: 0 }}
                    >
                      <td colSpan={6} className="p-0">
                        {section.categories.map((category) => (
                          <div key={category.code}>
                            {/* Category Header */}
                            <div
                              className={`px-6 py-2 font-medium ${
                                theme === "dark"
                                  ? "bg-black/28 text-indigo-300"
                                  : "bg-indigo-50 text-indigo-700"
                              }`}
                            >
                              {category.code} - {category.name}
                              <span className="float-right">
                                {formatCurrency(category.total)}
                              </span>
                            </div>

                            {/* Line Items */}
                            {category.items.map((item) => (
                              <div
                                key={item.code}
                                className={`grid grid-cols-6 gap-4 px-6 py-2 hover:${
                                  theme === "dark"
                                    ? "bg-black/22"
                                    : "bg-white/[0.04]"
                                } transition-colors border-b ${
                                  theme === "dark"
                                    ? "border-white/8"
                                    : "border-white/8"
                                }`}
                              >
                                <div className="font-medium text-white/45">
                                  {item.code}
                                </div>
                                <div className="text-white/68 dark:text-white/68">
                                  {item.description}
                                </div>
                                <div className="text-right">
                                  {editing?.itemCode === item.code &&
                                  editing?.field === "amount" ? (
                                    <div className="flex items-center gap-1">
                                      <input
                                        type="number"
                                        value={editValue}
                                        onChange={(e) =>
                                          setEditValue(e.target.value)
                                        }
                                        onKeyPress={(e) =>
                                          e.key === "Enter" && saveEdit()
                                        }
                                        className={`w-20 p-1 border rounded text-right ${
                                          theme === "dark"
                                            ? "bg-black/22 border-white/8 text-white"
                                            : "border-white/8"
                                        }`}
                                        autoFocus
                                      />
                                      <button
                                        onClick={saveEdit}
                                        className="text-green-600"
                                      >
                                        <Save size={14} />
                                      </button>
                                      <button
                                        onClick={cancelEdit}
                                        className="text-red-600"
                                      >
                                        <X size={14} />
                                      </button>
                                    </div>
                                  ) : (
                                    <div
                                      className="cursor-pointer hover:bg-white/8 dark:hover:bg-black/28 p-1 rounded flex items-center justify-end gap-1"
                                      onClick={() =>
                                        startEditing(
                                          section.id,
                                          category.code,
                                          item.code,
                                          "amount",
                                          item.amount
                                        )
                                      }
                                    >
                                      {item.amount.toLocaleString()}
                                      <Edit2 size={12} className="opacity-50" />
                                    </div>
                                  )}
                                </div>
                                <div className="text-white/55 dark:text-white/55">
                                  {item.unit}
                                </div>
                                <div className="text-right">
                                  {editing?.itemCode === item.code &&
                                  editing?.field === "rate" ? (
                                    <div className="flex items-center gap-1">
                                      <input
                                        type="number"
                                        value={editValue}
                                        onChange={(e) =>
                                          setEditValue(e.target.value)
                                        }
                                        onKeyPress={(e) =>
                                          e.key === "Enter" && saveEdit()
                                        }
                                        className={`w-24 p-1 border rounded text-right ${
                                          theme === "dark"
                                            ? "bg-black/22 border-white/8 text-white"
                                            : "border-white/8"
                                        }`}
                                        autoFocus
                                      />
                                      <button
                                        onClick={saveEdit}
                                        className="text-green-600"
                                      >
                                        <Save size={14} />
                                      </button>
                                      <button
                                        onClick={cancelEdit}
                                        className="text-red-600"
                                      >
                                        <X size={14} />
                                      </button>
                                    </div>
                                  ) : (
                                    <div
                                      className="cursor-pointer hover:bg-white/8 dark:hover:bg-black/28 p-1 rounded flex items-center justify-end gap-1"
                                      onClick={() =>
                                        startEditing(
                                          section.id,
                                          category.code,
                                          item.code,
                                          "rate",
                                          item.rate
                                        )
                                      }
                                    >
                                      {formatCurrency(item.rate)}
                                      <Edit2 size={12} className="opacity-50" />
                                    </div>
                                  )}
                                </div>
                                <div className="text-right font-semibold">
                                  {formatCurrency(item.total)}
                                </div>
                              </div>
                            ))}
                          </div>
                        ))}
                      </td>
                    </motion.tr>
                  )}
                </AnimatePresence>
              </React.Fragment>
            ))}
          </tbody>
        </table>
      </div>
    </motion.div>
  );
};

import { motion } from "framer-motion";
import React, { useMemo } from "react";
import {
  PieChart,
  Pie,
  Cell,
  ResponsiveContainer,
  BarChart,
  Bar,
  XAxis,
  YAxis,
  CartesianGrid,
  Tooltip,
  Legend,
  AreaChart,
  Area,
} from "recharts";

import { COLOR_PALETTE } from "../lib/constants";
import { Budget } from "../lib/types";

interface EnhancedChartProps {
  budget: Budget;
  theme: "light" | "dark";
}

export const EnhancedChart: React.FC<EnhancedChartProps> = ({
  budget,
  theme,
}) => {
  const chartData = useMemo(() => {
    // Section data for pie chart
    const sectionData = budget.sections
      .map((section) => ({
        name: section.name,
        value: section.total,
        percentage:
          budget.grandTotal > 0
            ? ((section.total / budget.grandTotal) * 100).toFixed(1)
            : "0",
        color: section.color ?? "#3B82F6",
      }))
      .filter((item) => item.value > 0);

    // Top categories data
    const allCategories = budget.sections
      .flatMap((section) =>
        section.categories.map((cat) => ({
          name: cat.name,
          section: section.name,
          value: cat.total,
          code: cat.code,
          color: section.color ?? "#3B82F6",
        }))
      )
      .filter((cat) => cat.value > 0)
      .sort((a, b) => b.value - a.value)
      .slice(0, 15);

    // Section comparison over time (simulated historical data)
    const historicalData = [
      {
        name: "Pre-Production",
        atl: 120000,
        production: 45000,
        post: 25000,
        other: 15000,
      },
      {
        name: "Production",
        atl: 120000,
        production: 650000,
        post: 45000,
        other: 35000,
      },
      {
        name: "Post-Production",
        atl: 120000,
        production: 650000,
        post: 180000,
        other: 50000,
      },
      {
        name: "Final",
        atl: budget.sections.find((s) => s.id === "atl")?.total ?? 0,
        production:
          budget.sections.find((s) => s.id === "production")?.total ?? 0,
        post: budget.sections.find((s) => s.id === "post")?.total ?? 0,
        other: budget.sections.find((s) => s.id === "other")?.total ?? 0,
      },
    ];

    return { sectionData, allCategories, historicalData };
  }, [budget]);

  const formatCurrency = (value: number) =>
    new Intl.NumberFormat("en-US", {
      style: "currency",
      currency: "USD",
      minimumFractionDigits: 0,
      maximumFractionDigits: 0,
    }).format(value);

  const formatShort = (value: number) => {
    if (value >= 1000000) return `$${(value / 1000000).toFixed(1)}M`;
    if (value >= 1000) return `$${(value / 1000).toFixed(0)}K`;
    return `$${value}`;
  };

  const CustomTooltip = ({ active, payload, label }: any) => {
    if (active && payload?.length) {
      return (
        <div
          className={`p-3 rounded-[22px] shadow-lg border ${
            theme === "dark"
              ? "bg-black/18 border-white/8 text-white"
              : "bg-white/[0.04] border-white/8"
          }`}
        >
          <p className="font-semibold">{label}</p>
          {payload.map((entry: any, index: number) => (
            <p key={index} style={{ color: entry.color }}>
              {entry.name}: {formatCurrency(entry.value)}
            </p>
          ))}
        </div>
      );
    }
    return null;
  };

  const containerVariants = {
    hidden: { opacity: 0 },
    visible: {
      opacity: 1,
      transition: {
        staggerChildren: 0.2,
      },
    },
  };

  const chartVariants = {
    hidden: { opacity: 0, y: 20 },
    visible: { opacity: 1, y: 0 },
  };

  return (
    <motion.div
      variants={containerVariants}
      initial="hidden"
      animate="visible"
      className="p-6"
    >
      <h3
        className={`text-lg font-bold mb-6 ${
          theme === "dark" ? "text-white" : "text-white"
        }`}
      >
        Budget Visualization & Analytics
      </h3>

      <div className="grid grid-cols-1 lg:grid-cols-2 gap-8 mb-8">
        {/* Pie Chart */}
        <motion.div
          variants={chartVariants}
          className={`p-6 rounded-xl border ${
            theme === "dark"
              ? "bg-black/18 border-white/8"
              : "bg-white/[0.04] border-white/8"
          } shadow-md`}
        >
          <h4
            className={`text-lg font-semibold mb-4 ${
              theme === "dark" ? "text-white" : "text-white"
            }`}
          >
            Budget Distribution by Section
          </h4>
          <ResponsiveContainer width="100%" height={300}>
            <PieChart>
              <Pie
                data={chartData.sectionData}
                cx="50%"
                cy="50%"
                labelLine={false}
                label={({
                  name,
                  percent,
                }: {
                  name?: string;
                  percent?: number;
                }) => `${name ?? ""}: ${((percent ?? 0) * 100).toFixed(0)}%`}
                outerRadius={80}
                fill="#8884d8"
                dataKey="value"
              >
                {chartData.sectionData.map((_entry, index) => (
                  <Cell
                    key={`cell-${index}`}
                    fill={
                      COLOR_PALETTE.charts[
                        index % COLOR_PALETTE.charts.length
                      ] ?? "#3B82F6"
                    }
                  />
                ))}
              </Pie>
              <Tooltip content={<CustomTooltip />} />
            </PieChart>
          </ResponsiveContainer>
        </motion.div>

        {/* Bar Chart - Top Categories */}
        <motion.div
          variants={chartVariants}
          className={`p-6 rounded-xl border ${
            theme === "dark"
              ? "bg-black/18 border-white/8"
              : "bg-white/[0.04] border-white/8"
          } shadow-md`}
        >
          <h4
            className={`text-lg font-semibold mb-4 ${
              theme === "dark" ? "text-white" : "text-white"
            }`}
          >
            Top 15 Categories by Cost
          </h4>
          <ResponsiveContainer width="100%" height={300}>
            <BarChart data={chartData.allCategories} layout="vertical">
              <CartesianGrid
                strokeDasharray="3 3"
                stroke={theme === "dark" ? "#374151" : "#E5E7EB"}
              />
              <XAxis
                type="number"
                tickFormatter={formatShort}
                stroke={theme === "dark" ? "#9CA3AF" : "#6B7280"}
              />
              <YAxis
                type="category"
                dataKey="name"
                width={120}
                tick={{ fontSize: 10 }}
                stroke={theme === "dark" ? "#9CA3AF" : "#6B7280"}
              />
              <Tooltip content={<CustomTooltip />} />
              <Bar dataKey="value" fill="#3B82F6" />
            </BarChart>
          </ResponsiveContainer>
        </motion.div>
      </div>

      {/* Historical Comparison */}
      <motion.div
        variants={chartVariants}
        className={`p-6 rounded-xl border mb-8 ${
          theme === "dark"
            ? "bg-black/18 border-white/8"
            : "bg-white/[0.04] border-white/8"
        } shadow-md`}
      >
        <h4
          className={`text-lg font-semibold mb-4 ${
            theme === "dark" ? "text-white" : "text-white"
          }`}
        >
          Budget Evolution by Phase
        </h4>
        <ResponsiveContainer width="100%" height={300}>
          <AreaChart data={chartData.historicalData}>
            <CartesianGrid
              strokeDasharray="3 3"
              stroke={theme === "dark" ? "#374151" : "#E5E7EB"}
            />
            <XAxis
              dataKey="name"
              stroke={theme === "dark" ? "#9CA3AF" : "#6B7280"}
            />
            <YAxis
              tickFormatter={formatShort}
              stroke={theme === "dark" ? "#9CA3AF" : "#6B7280"}
            />
            <Tooltip content={<CustomTooltip />} />
            <Legend />
            <Area
              type="monotone"
              dataKey="atl"
              stackId="1"
              stroke="#3B82F6"
              fill="#3B82F6"
              fillOpacity={0.6}
              name="Above The Line"
            />
            <Area
              type="monotone"
              dataKey="production"
              stackId="1"
              stroke="#8B5CF6"
              fill="#8B5CF6"
              fillOpacity={0.6}
              name="Production"
            />
            <Area
              type="monotone"
              dataKey="post"
              stackId="1"
              stroke="#EC4899"
              fill="#EC4899"
              fillOpacity={0.6}
              name="Post Production"
            />
            <Area
              type="monotone"
              dataKey="other"
              stackId="1"
              stroke="#F59E0B"
              fill="#F59E0B"
              fillOpacity={0.6}
              name="Other"
            />
          </AreaChart>
        </ResponsiveContainer>
      </motion.div>

      {/* Summary Stats */}
      <motion.div
        variants={chartVariants}
        className="grid grid-cols-2 md:grid-cols-4 gap-4"
      >
        <div
          className={`p-4 rounded-xl border text-center ${
            theme === "dark"
              ? "bg-black/18 border-white/8"
              : "bg-white/[0.04] border-white/8"
          }`}
        >
          <div
            className={`text-2xl font-bold ${
              theme === "dark" ? "text-white" : "text-white"
            }`}
          >
            {formatCurrency(budget.grandTotal)}
          </div>
          <div
            className={`text-sm ${
              theme === "dark" ? "text-white/55" : "text-white/55"
            }`}
          >
            Total Budget
          </div>
        </div>
        <div
          className={`p-4 rounded-xl border text-center ${
            theme === "dark"
              ? "bg-black/18 border-white/8"
              : "bg-white/[0.04] border-white/8"
          }`}
        >
          <div className={`text-2xl font-bold text-indigo-600`}>
            {budget.sections.length}
          </div>
          <div
            className={`text-sm ${
              theme === "dark" ? "text-white/55" : "text-white/55"
            }`}
          >
            Sections
          </div>
        </div>
        <div
          className={`p-4 rounded-xl border text-center ${
            theme === "dark"
              ? "bg-black/18 border-white/8"
              : "bg-white/[0.04] border-white/8"
          }`}
        >
          <div className={`text-2xl font-bold text-purple-600`}>
            {budget.sections.reduce(
              (sum, section) => sum + section.categories.length,
              0
            )}
          </div>
          <div
            className={`text-sm ${
              theme === "dark" ? "text-white/55" : "text-white/55"
            }`}
          >
            Categories
          </div>
        </div>
        <div
          className={`p-4 rounded-xl border text-center ${
            theme === "dark"
              ? "bg-black/18 border-white/8"
              : "bg-white/[0.04] border-white/8"
          }`}
        >
          <div className={`text-2xl font-bold text-green-600`}>
            {budget.sections.reduce(
              (sum, section) =>
                sum +
                section.categories.reduce(
                  (catSum, cat) =>
                    catSum + cat.items.filter((item) => item.total > 0).length,
                  0
                ),
              0
            )}
          </div>
          <div
            className={`text-sm ${
              theme === "dark" ? "text-white/55" : "text-white/55"
            }`}
          >
            Active Items
          </div>
        </div>
      </motion.div>
    </motion.div>
  );
};

import { motion, AnimatePresence } from "framer-motion";
import html2canvas from "html2canvas";
import jsPDF from "jspdf";
import {
  X,
  Download,
  FileSpreadsheet,
  FileJson,
  FileImage,
} from "lucide-react";
import React, { useState, useMemo } from "react";

import { logger } from "@/lib/ai/utils/logger";


import { Budget, ExportOptions } from "../lib/types";


interface ExportModalProps {
  isOpen: boolean;
  onClose: () => void;
  budget: Budget;
  budgetName: string;
  theme: "light" | "dark";
}

export const ExportModal: React.FC<ExportModalProps> = ({
  isOpen,
  onClose,
  budget,
  budgetName,
  theme,
}) => {
  const [exportOptions, setExportOptions] = useState<ExportOptions>({
    format: "csv",
    includeZeroValues: false,
    includeDetails: true,
    includeCharts: false,
  });
  const [exporting, setExporting] = useState(false);

  const formatCurrency = (value: number) =>
    new Intl.NumberFormat("en-US", {
      style: "currency",
      currency: "USD",
      minimumFractionDigits: 0,
      maximumFractionDigits: 0,
    }).format(value);

  const stats = useMemo(() => {
    const totalItems = budget.sections.reduce(
      (sum, section) =>
        sum +
        section.categories.reduce(
          (catSum, cat) => catSum + cat.items.length,
          0
        ),
      0
    );

    const activeItems = budget.sections.reduce(
      (sum, section) =>
        sum +
        section.categories.reduce(
          (catSum, cat) =>
            catSum + cat.items.filter((item) => item.total > 0).length,
          0
        ),
      0
    );

    return { totalItems, activeItems };
  }, [budget]);

  const containerVariants = {
    hidden: { opacity: 0 },
    visible: { opacity: 1 },
    exit: { opacity: 0 },
  };

  const modalVariants = {
    hidden: { scale: 0.9, opacity: 0 },
    visible: { scale: 1, opacity: 1 },
    exit: { scale: 0.9, opacity: 0 },
  };

  const exportToCSV = () => {
    const headers = [
      "Section",
      "Category",
      "Code",
      "Description",
      "Amount",
      "Unit",
      "Rate",
      "Total",
    ];
    const rows: any[][] = [];

    budget.sections.forEach((section) => {
      section.categories.forEach((category) => {
        category.items.forEach((item) => {
          if (!exportOptions.includeZeroValues && item.total === 0) return;
          rows.push([
            section.name,
            category.name,
            item.code,
            item.description,
            item.amount,
            item.unit,
            item.rate,
            item.total,
          ]);
        });
      });
    });

    const csvContent = [headers, ...rows]
      .map((row) => row.map((field) => `"${field}"`).join(","))
      .join("\n");

    downloadFile(csvContent, `${budgetName}_budget.csv`, "text/csv");
  };

  const exportToExcel = async () => {
    try {
      setExporting(true);
      // Use the API endpoint which uses exceljs (safer than xlsx)
      const response = await fetch("/api/budget/export", {
        method: "POST",
        headers: {
          "Content-Type": "application/json",
        },
        body: JSON.stringify({
          budget: budget,
          format: "excel",
        }),
      });

      if (!response.ok) {
        throw new Error("Failed to export budget");
      }

      const blob = await response.blob();
      const url = window.URL.createObjectURL(blob);
      const a = document.createElement("a");
      a.href = url;
      a.download = `${budgetName}_budget.xlsx`;
      document.body.appendChild(a);
      a.click();
      window.URL.revokeObjectURL(url);
      document.body.removeChild(a);
    } catch (error) {
      logger.error("Export error:", error);
      alert("فشل تصدير الميزانية. الرجاء المحاولة مرة أخرى.");
    } finally {
      setExporting(false);
    }
  };

  const exportToJSON = () => {
    const jsonData = {
      budgetName,
      exportDate: new Date().toISOString(),
      total: budget.grandTotal,
      sections: budget.sections.map((section) => ({
        name: section.name,
        total: section.total,
        categories: section.categories.map((category) => ({
          name: category.name,
          code: category.code,
          total: category.total,
          items: category.items.filter(
            (item) => exportOptions.includeZeroValues || item.total > 0
          ),
        })),
      })),
    };

    downloadFile(
      JSON.stringify(jsonData, null, 2),
      `${budgetName}_budget.json`,
      "application/json"
    );
  };

  const exportToPDF = async () => {
    setExporting(true);
    try {
      const element = document.getElementById("budget-content");
      if (element) {
        const canvas = await html2canvas(element, {
          backgroundColor:
            theme === "dark" ? "rgba(0,0,0,0.18)" : "rgba(255,255,255,0.04)",
          scale: 2,
        });

        const imgData = canvas.toDataURL("image/png");
        const pdf = new jsPDF("p", "mm", "a4");

        const imgWidth = 210;
        const pageHeight = 295;
        const imgHeight = (canvas.height * imgWidth) / canvas.width;
        let heightLeft = imgHeight;

        let position = 0;

        pdf.addImage(imgData, "PNG", 0, position, imgWidth, imgHeight);
        heightLeft -= pageHeight;

        while (heightLeft >= 0) {
          position = heightLeft - imgHeight;
          pdf.addPage();
          pdf.addImage(imgData, "PNG", 0, position, imgWidth, imgHeight);
          heightLeft -= pageHeight;
        }

        pdf.save(`${budgetName}_budget.pdf`);
      }
    } catch (error) {
      logger.error("PDF export failed:", error);
    } finally {
      setExporting(false);
    }
  };

  const downloadFile = (
    content: string,
    filename: string,
    mimeType: string
  ) => {
    const blob = new Blob([content], { type: mimeType });
    const url = URL.createObjectURL(blob);
    const link = document.createElement("a");
    link.href = url;
    link.download = filename;
    document.body.appendChild(link);
    link.click();
    document.body.removeChild(link);
    URL.revokeObjectURL(url);
  };

  const handleExport = () => {
    switch (exportOptions.format) {
      case "csv":
        exportToCSV();
        break;
      case "excel":
        exportToExcel();
        break;
      case "json":
        exportToJSON();
        break;
      case "pdf":
        exportToPDF();
        break;
    }
    onClose();
  };

  if (!isOpen) return null;

  return (
    <AnimatePresence>
      <motion.div
        variants={containerVariants}
        initial="hidden"
        animate="visible"
        exit="exit"
        className="fixed inset-0 bg-black/50 flex items-center justify-center z-50 p-4"
        onClick={onClose}
      >
        <motion.div
          variants={modalVariants}
          initial="hidden"
          animate="visible"
          exit="exit"
          transition={{ type: "spring", damping: 25 }}
          className={`max-w-2xl w-full rounded-xl shadow-2xl overflow-hidden ${
            theme === "dark"
              ? "bg-black/18 border border-white/8"
              : "bg-white/[0.04]"
          }`}
          onClick={(e: React.MouseEvent<HTMLDivElement>) => e.stopPropagation()}
        >
          <div className="flex justify-between items-center p-6 border-b border-white/8 dark:border-white/8">
            <h2
              className={`text-2xl font-bold ${
                theme === "dark" ? "text-white" : "text-white"
              }`}
            >
              Export Budget
            </h2>
            <button
              onClick={onClose}
              className={`p-2 rounded-lg transition-colors ${
                theme === "dark"
                  ? "text-white/55 hover:text-white hover:bg-black/22"
                  : "text-white/55 hover:text-white hover:bg-white/8/6"
              }`}
            >
              <X size={20} />
            </button>
          </div>

          <div className="p-6">
            {/* Format Selection */}
            <div className="mb-6">
              <h3
                className={`text-lg font-semibold mb-3 ${
                  theme === "dark" ? "text-white" : "text-white"
                }`}
              >
                Export Format
              </h3>
              <div className="grid grid-cols-2 md:grid-cols-4 gap-3">
                <button
                  onClick={() =>
                    setExportOptions({ ...exportOptions, format: "csv" })
                  }
                  className={`p-4 rounded-lg border transition-all flex flex-col items-center gap-2 ${
                    exportOptions.format === "csv"
                      ? "border-indigo-500 bg-indigo-50 text-indigo-700"
                      : theme === "dark"
                        ? "border-white/8 bg-black/22 text-white/68 hover:bg-black/28"
                        : "border-white/8 bg-white/[0.04] text-white/55 hover:bg-white/8/6"
                  }`}
                >
                  <FileSpreadsheet size={24} />
                  <span className="text-sm font-medium">CSV</span>
                </button>

                <button
                  onClick={() =>
                    setExportOptions({ ...exportOptions, format: "excel" })
                  }
                  className={`p-4 rounded-lg border transition-all flex flex-col items-center gap-2 ${
                    exportOptions.format === "excel"
                      ? "border-indigo-500 bg-indigo-50 text-indigo-700"
                      : theme === "dark"
                        ? "border-white/8 bg-black/22 text-white/68 hover:bg-black/28"
                        : "border-white/8 bg-white/[0.04] text-white/55 hover:bg-white/8/6"
                  }`}
                >
                  <FileSpreadsheet size={24} />
                  <span className="text-sm font-medium">Excel</span>
                </button>

                <button
                  onClick={() =>
                    setExportOptions({ ...exportOptions, format: "json" })
                  }
                  className={`p-4 rounded-lg border transition-all flex flex-col items-center gap-2 ${
                    exportOptions.format === "json"
                      ? "border-indigo-500 bg-indigo-50 text-indigo-700"
                      : theme === "dark"
                        ? "border-white/8 bg-black/22 text-white/68 hover:bg-black/28"
                        : "border-white/8 bg-white/[0.04] text-white/55 hover:bg-white/8/6"
                  }`}
                >
                  <FileJson size={24} />
                  <span className="text-sm font-medium">JSON</span>
                </button>

                <button
                  onClick={() =>
                    setExportOptions({ ...exportOptions, format: "pdf" })
                  }
                  className={`p-4 rounded-lg border transition-all flex flex-col items-center gap-2 ${
                    exportOptions.format === "pdf"
                      ? "border-indigo-500 bg-indigo-50 text-indigo-700"
                      : theme === "dark"
                        ? "border-white/8 bg-black/22 text-white/68 hover:bg-black/28"
                        : "border-white/8 bg-white/[0.04] text-white/55 hover:bg-white/8/6"
                  }`}
                >
                  <FileImage size={24} />
                  <span className="text-sm font-medium">PDF</span>
                </button>
              </div>
            </div>

            {/* Options */}
            <div className="mb-6">
              <h3
                className={`text-lg font-semibold mb-3 ${
                  theme === "dark" ? "text-white" : "text-white"
                }`}
              >
                Export Options
              </h3>
              <div className="space-y-3">
                <label className="flex items-center gap-3">
                  <input
                    type="checkbox"
                    checked={exportOptions.includeZeroValues}
                    onChange={(e) =>
                      setExportOptions({
                        ...exportOptions,
                        includeZeroValues: e.target.checked,
                      })
                    }
                    className="w-4 h-4 text-indigo-600 rounded focus:ring-indigo-500"
                  />
                  <span
                    className={`text-sm ${
                      theme === "dark" ? "text-white/68" : "text-white/68"
                    }`}
                  >
                    Include items with zero values
                  </span>
                </label>

                <label className="flex items-center gap-3">
                  <input
                    type="checkbox"
                    checked={exportOptions.includeDetails}
                    onChange={(e) =>
                      setExportOptions({
                        ...exportOptions,
                        includeDetails: e.target.checked,
                      })
                    }
                    className="w-4 h-4 text-indigo-600 rounded focus:ring-indigo-500"
                  />
                  <span
                    className={`text-sm ${
                      theme === "dark" ? "text-white/68" : "text-white/68"
                    }`}
                  >
                    Include detailed breakdown
                  </span>
                </label>

                {exportOptions.format === "excel" && (
                  <label className="flex items-center gap-3">
                    <input
                      type="checkbox"
                      checked={exportOptions.includeCharts}
                      onChange={(e) =>
                        setExportOptions({
                          ...exportOptions,
                          includeCharts: e.target.checked,
                        })
                      }
                      className="w-4 h-4 text-indigo-600 rounded focus:ring-indigo-500"
                    />
                    <span
                      className={`text-sm ${
                        theme === "dark" ? "text-white/68" : "text-white/68"
                      }`}
                    >
                      Include charts and visualizations
                    </span>
                  </label>
                )}
              </div>
            </div>

            {/* Preview */}
            <div className="mb-6">
              <h3
                className={`text-lg font-semibold mb-3 ${
                  theme === "dark" ? "text-white" : "text-white"
                }`}
              >
                Export Preview
              </h3>
              <div
                className={`p-4 rounded-[22px] border ${
                  theme === "dark"
                    ? "bg-black/22 border-white/8"
                    : "bg-white/[0.04] border-white/8"
                }`}
              >
                <div className="text-sm space-y-1">
                  <div>
                    <strong>File name:</strong> {budgetName}_budget.
                    {exportOptions.format}
                  </div>
                  <div>
                    <strong>Total items:</strong>{" "}
                    {exportOptions.includeZeroValues
                      ? stats.totalItems
                      : stats.activeItems}
                  </div>
                  <div>
                    <strong>Total budget:</strong>{" "}
                    {formatCurrency(budget.grandTotal)}
                  </div>
                </div>
              </div>
            </div>

            {/* Actions */}
            <div className="flex justify-end gap-3">
              <button
                onClick={onClose}
                className={`px-4 py-2 rounded-lg border transition-colors ${
                  theme === "dark"
                    ? "border-white/8 text-white/68 hover:bg-black/22"
                    : "border-white/8 text-white/68 hover:bg-white/[0.04]"
                }`}
              >
                Cancel
              </button>
              <button
                onClick={handleExport}
                disabled={exporting}
                className="px-6 py-2 bg-indigo-600 hover:bg-indigo-700 text-white rounded-lg font-medium transition-colors flex items-center gap-2"
              >
                {exporting ? (
                  <>
                    <div className="w-4 h-4 border-2 border-white border-t-transparent rounded-full animate-spin"></div>
                    Exporting...
                  </>
                ) : (
                  <>
                    <Download size={16} />
                    Export
                  </>
                )}
              </button>
            </div>
          </div>
        </motion.div>
      </motion.div>
    </AnimatePresence>
  );
};

