    score: 92,
    status: "completed",
    source: "sample",
  },
];

function delay(milliseconds: number): Promise<void> {
  return new Promise((resolve) => {
    setTimeout(resolve, milliseconds);
  });
}

function clamp(value: number, min: number, max: number): number {
  return Math.min(max, Math.max(min, value));
}

function cloneSampleTakes(): Take[] {
  return SAMPLE_TAKES.map((take) => ({
    ...take,
    notes: take.notes.map((note) => ({ ...note })),
  }));
}

function formatTime(seconds: number): string {
  const minutes = Math.floor(seconds / 60);
  const remainder = seconds % 60;
  return `${minutes.toString().padStart(2, "0")}:${remainder
    .toString()
    .padStart(2, "0")}`;
}

function formatRecordedAt(value: string): string {
  return new Date(value).toLocaleString("ar-EG", {
    hour: "2-digit",
    minute: "2-digit",
    year: "numeric",
    month: "short",
    day: "numeric",
  });
}

function toPersistedTake(take: Take): PersistedSelfTapeTake {
  const { videoUrl: _videoUrl, mimeType, score, ...baseTake } = take;

  return {
    ...baseTake,
    ...(typeof mimeType === "string" ? { mimeType } : {}),
    ...(typeof score === "number" ? { score } : {}),
  };
}

function createNotesFromInsights(
  notes: {
    type: "timing" | "delivery" | "improvement";
    severity: NoteSeverity;
    content: string;
  }[],
  duration: number
): TakeNote[] {
  const safeDuration = Math.max(duration, 1);
  const slots = Math.max(notes.length, 1);

  return notes.map((note, index) => ({
    id: `note-${Date.now()}-${index}`,
    timestamp: clamp(
      Math.round((safeDuration / slots) * (index + 0.5)),
      0,
      safeDuration
    ),
    type: note.type,
    severity: note.severity,
    content: note.content,
    autoGenerated: true,
  }));
}

function getSeverityContainerClass(severity: NoteSeverity): string {
  switch (severity) {
    case "positive":
      return "bg-green-500/10 border-green-500/30";
    case "needs_work":
      return "bg-yellow-500/10 border-yellow-500/30";
    default:
      return "bg-black/14 border-purple-500/30";
  }
}

function getScoreColor(score: number | undefined): string {
  if (!score) {
    return "text-white/55";
  }

  if (score >= 85) {
    return "text-green-400";
  }

  if (score >= 70) {
    return "text-yellow-400";
  }

  return "text-red-400";
}

function loadInitialTakes(): Take[] {
  const fallback = cloneSampleTakes().map(toPersistedTake);
  return readStoredSelfTapeTakes(fallback).map((take) => ({
    ...take,
    notes: take.notes.map((note) => ({ ...note })),
  }));
}

export const SelfTapeSuite: React.FC = () => {
  const [activeTool, setActiveTool] = useState<ActiveTool>("teleprompter");
  const [scriptText, setScriptText] = useState(SAMPLE_SCRIPT);
  const [takes, setTakes] = useState<Take[]>(loadInitialTakes);
  const [isRemoteStateReady, setIsRemoteStateReady] = useState(false);
  const [notification, setNotification] = useState<NotificationState>(null);
  const [teleprompterSettings, setTeleprompterSettings] =
    useState<TeleprompterSettings>({
      speed: 50,
      fontSize: 32,
      mirrorMode: false,
      highlightCurrentLine: true,
      autoScroll: true,
      countdownSeconds: 5,
    });
  const [teleprompterRunning, setTeleprompterRunning] = useState(false);
  const [teleprompterPosition, setTeleprompterPosition] = useState(0);
  const [countdown, setCountdown] = useState(0);
  const [cameraState, setCameraState] = useState<CameraState>("idle");
  const [cameraError, setCameraError] = useState("");
  const [isRecording, setIsRecording] = useState(false);
  const [isFinalizingTake, setIsFinalizingTake] = useState(false);
  const [recordingTime, setRecordingTime] = useState(0);
  const [comparisonView, setComparisonView] = useState<ComparisonView>({
    leftTakeId: null,
    rightTakeId: null,
    syncPlayback: true,
  });
  const [exportSettings, setExportSettings] = useState<ExportSettings>({
    quality: "casting",
    format: "webm",
    includeSlate: true,
    slateDuration: 5,
    actorName: "",
    projectName: "",
    roleName: "",
    agencyName: "",
  });
  const [exportingTakeId, setExportingTakeId] = useState<string | null>(null);
  const [exportProgress, setExportProgress] = useState(0);
  const [notesTakeId, setNotesTakeId] = useState<string | null>(null);
  const [manualNoteDrafts, setManualNoteDrafts] = useState<
    Record<string, string>
  >({});
  const [manualNoteTypes, setManualNoteTypes] = useState<
    Record<string, NoteType>
  >({});

  const previewVideoRef = useRef<HTMLVideoElement | null>(null);
  const recordingIntervalRef = useRef<ReturnType<typeof setInterval> | null>(
    null
  );
  const teleprompterIntervalRef = useRef<ReturnType<typeof setInterval> | null>(
    null
  );
  const countdownIntervalRef = useRef<ReturnType<typeof setInterval> | null>(
    null
  );
  const mediaStreamRef = useRef<MediaStream | null>(null);
  const mediaRecorderRef = useRef<MediaRecorder | null>(null);
  const recordedChunksRef = useRef<Blob[]>([]);
  const recordingTimeRef = useRef(0);
  const pendingTakeRef = useRef<PendingTake | null>(null);
  const blobRegistryRef = useRef<Map<string, Blob>>(new Map());
  const sessionUrlRegistryRef = useRef<Map<string, string>>(new Map());

  const mediaCaptureSupported = supportsMediaCapture();
  const availableTakes = useMemo(
    () => takes.filter((take) => take.status !== "recording"),
    [takes]
  );
  const totalDuration = useMemo(
    () => availableTakes.reduce((sum, take) => sum + take.duration, 0),
    [availableTakes]
  );
  const bestScore = useMemo(
    () => Math.max(...availableTakes.map((take) => take.score ?? 0), 0),
    [availableTakes]
  );
  const bestExportableTake = useMemo(() => {
    return [...availableTakes]
      .filter((take) => blobRegistryRef.current.has(take.id))
      .sort((left, right) => (right.score ?? 0) - (left.score ?? 0))[0];
  }, [availableTakes]);
  const promptLines = useMemo(
    () =>
      scriptText
        .split("\n")
        .map((line) => line.trim())
        .filter(Boolean),
    [scriptText]
  );
  const currentPromptLine = useMemo(() => {
    if (promptLines.length === 0) {
      return "أدخل نصاً لعرضه على التلقين.";
    }

    const lineIndex = clamp(
      Math.floor((teleprompterPosition / 100) * promptLines.length),
      0,
      promptLines.length - 1
    );
    return promptLines[lineIndex] ?? promptLines[0] ?? "";
  }, [promptLines, teleprompterPosition]);

  useEffect(() => {
    let cancelled = false;

    void loadRemoteAppState<SelfTapeSuiteSnapshot>("actorai-arabic-self-tape")
      .then((snapshot) => {
        if (cancelled || !snapshot) {
          return;
        }

        if (snapshot.scriptText) {
          setScriptText(snapshot.scriptText);
        }

        if (Array.isArray(snapshot.takes) && snapshot.takes.length > 0) {
          setTakes(
            snapshot.takes.map((take) => ({
              ...take,
              notes: take.notes.map((note) => ({ ...note })),
            }))
          );
        }

        if (snapshot.activeTool) {
          setActiveTool(snapshot.activeTool);
        }

        if (snapshot.teleprompterSettings) {
          setTeleprompterSettings(snapshot.teleprompterSettings);
        }

        if (snapshot.exportSettings) {
          setExportSettings(snapshot.exportSettings);
        }

        if (snapshot.comparisonView) {
          setComparisonView(snapshot.comparisonView);
        }

        if (snapshot.notesTakeId !== undefined) {
          setNotesTakeId(snapshot.notesTakeId);
        }
      })
      .catch(() => {})
      .finally(() => {
        if (!cancelled) {
          setIsRemoteStateReady(true);
        }
      });

    return () => {
      cancelled = true;
    };
  }, []);

  useEffect(() => {
    recordingTimeRef.current = recordingTime;
  }, [recordingTime]);

  useEffect(() => {
    writeStoredSelfTapeTakes(takes.map(toPersistedTake));
  }, [takes]);

  useEffect(() => {
    if (!isRemoteStateReady) {
      return;
    }

    const timeoutId = window.setTimeout(() => {
      void persistRemoteAppState<SelfTapeSuiteSnapshot>(
        "actorai-arabic-self-tape",
        {
          scriptText,
          takes: takes.map(toPersistedTake),
          activeTool,
          teleprompterSettings,
          exportSettings,
          comparisonView,
          notesTakeId,
        }
      ).catch(() => {});
    }, 400);

    return () => {
      window.clearTimeout(timeoutId);
    };
  }, [
    activeTool,
    comparisonView,
    exportSettings,
    isRemoteStateReady,
    notesTakeId,
    scriptText,
    takes,
    teleprompterSettings,
  ]);

  useEffect(() => {
    if (!notification) {
      return undefined;
    }

    const timeoutId = setTimeout(() => setNotification(null), 4500);
    return () => clearTimeout(timeoutId);
  }, [notification]);

  useEffect(() => {
    if (availableTakes.length === 0) {
      setNotesTakeId(null);
      return;
    }

    setNotesTakeId((current) => {
      if (current && availableTakes.some((take) => take.id === current)) {
        return current;
      }
      return availableTakes[0]?.id ?? null;
    });
  }, [availableTakes]);

  useEffect(() => {
    const takeIds = new Set(availableTakes.map((take) => take.id));

    setComparisonView((current) => {
      const nextLeft =
        current.leftTakeId && takeIds.has(current.leftTakeId)
          ? current.leftTakeId
          : (availableTakes[0]?.id ?? null);
      const nextRight =
        current.rightTakeId && takeIds.has(current.rightTakeId)
          ? current.rightTakeId
          : (availableTakes.find((take) => take.id !== nextLeft)?.id ?? null);

      if (
        nextLeft === current.leftTakeId &&
        nextRight === current.rightTakeId
      ) {
        return current;
      }

      return {
        ...current,
        leftTakeId: nextLeft,
        rightTakeId: nextRight,
      };
    });
  }, [availableTakes]);

  useEffect(() => {
    if (!teleprompterRunning || !teleprompterSettings.autoScroll) {
      if (teleprompterIntervalRef.current) {
        clearInterval(teleprompterIntervalRef.current);
        teleprompterIntervalRef.current = null;
      }
      return undefined;
    }

    teleprompterIntervalRef.current = setInterval(() => {
      setTeleprompterPosition((previous) => {
        const nextPosition = previous + teleprompterSettings.speed / 500;
        if (nextPosition >= 100) {
          setTeleprompterRunning(false);
          return 100;
        }
        return nextPosition;
      });
    }, 100);

    return () => {
      if (teleprompterIntervalRef.current) {
        clearInterval(teleprompterIntervalRef.current);
        teleprompterIntervalRef.current = null;
      }
    };
  }, [
    teleprompterRunning,
    teleprompterSettings.autoScroll,
    teleprompterSettings.speed,
  ]);

  const showNotification = useCallback(
    (type: "success" | "error" | "info", message: string) => {
      setNotification({ type, message });
    },
    []
  );

  const clearCountdownInterval = useCallback(() => {
    if (countdownIntervalRef.current) {
      clearInterval(countdownIntervalRef.current);
      countdownIntervalRef.current = null;
    }
  }, []);

  const clearRecordingInterval = useCallback(() => {
    if (recordingIntervalRef.current) {
      clearInterval(recordingIntervalRef.current);
      recordingIntervalRef.current = null;
    }
  }, []);

  const stopCameraTracks = useCallback((stream?: MediaStream | null) => {
    stream?.getTracks().forEach((track) => {
      track.stop();
    });
  }, []);

  const revokeTakeResources = useCallback((takeId: string) => {
    const sessionUrl = sessionUrlRegistryRef.current.get(takeId);
    if (sessionUrl) {
      URL.revokeObjectURL(sessionUrl);
      sessionUrlRegistryRef.current.delete(takeId);
    }
    blobRegistryRef.current.delete(takeId);
  }, []);

  const stopTeleprompter = useCallback(() => {
    clearCountdownInterval();
    setCountdown(0);
    setTeleprompterRunning(false);
    if (teleprompterIntervalRef.current) {
      clearInterval(teleprompterIntervalRef.current);
      teleprompterIntervalRef.current = null;
    }
  }, [clearCountdownInterval]);

  const resetTeleprompter = useCallback(() => {
    stopTeleprompter();
    setTeleprompterPosition(0);
  }, [stopTeleprompter]);

  const startTeleprompter = useCallback(() => {
    clearCountdownInterval();

    if (teleprompterSettings.countdownSeconds <= 0) {
      setCountdown(0);
      setTeleprompterRunning(true);
      return;
    }

    setTeleprompterRunning(false);
    setCountdown(teleprompterSettings.countdownSeconds);
    countdownIntervalRef.current = setInterval(() => {
      setCountdown((previous) => {
        if (previous <= 1) {
          clearCountdownInterval();
          setTeleprompterRunning(true);
          return 0;
        }
        return previous - 1;
      });
    }, 1000);
  }, [clearCountdownInterval, teleprompterSettings.countdownSeconds]);

  const attachStreamToPreview = useCallback(async (stream: MediaStream) => {
    const preview = previewVideoRef.current;
    if (!preview) {
      return;
    }

    preview.srcObject = stream;
    preview.muted = true;
    preview.playsInline = true;

    try {
      await preview.play();
    } catch {
      // لا نرفع خطأ لأن بعض بيئات الاختبار تمنع التشغيل التلقائي.
    }
  }, []);

  const requestCameraAccess =
    useCallback(async (): Promise<MediaStream | null> => {
      if (
        typeof navigator === "undefined" ||
        !navigator.mediaDevices?.getUserMedia
      ) {
        const errorMessage =
          "هذه البيئة لا تدعم الوصول المباشر إلى الكاميرا والميكروفون.";
        setCameraState("error");
        setCameraError(errorMessage);
        showNotification("error", errorMessage);
        return null;
      }

      setCameraState("requesting");
      setCameraError("");

      try {
        const stream = await navigator.mediaDevices.getUserMedia({
          video: {
            facingMode: "user",
            width: { ideal: 1280 },
            height: { ideal: 720 },
          },
          audio: true,
        });
        stopCameraTracks(mediaStreamRef.current);
        mediaStreamRef.current = stream;
        await attachStreamToPreview(stream);
        setCameraState("ready");
        showNotification("success", "تم تفعيل الكاميرا والميكروفون بنجاح.");
        return stream;
      } catch {
        const errorMessage =
          "تعذر الوصول إلى الكاميرا أو الميكروفون. تحقق من الأذونات ثم أعد المحاولة.";
        setCameraState("error");
        setCameraError(errorMessage);
        showNotification("error", errorMessage);
        return null;
      }
    }, [attachStreamToPreview, showNotification, stopCameraTracks]);

  useEffect(() => {
    if (activeTool === "recorder" && cameraState === "idle") {
      void requestCameraAccess();
    }
  }, [activeTool, cameraState, requestCameraAccess]);

  useEffect(() => {
    if (mediaStreamRef.current) {
      void attachStreamToPreview(mediaStreamRef.current);
    }
  }, [activeTool, attachStreamToPreview]);

  useEffect(() => {
    return () => {
      clearCountdownInterval();
      clearRecordingInterval();
      if (teleprompterIntervalRef.current) {
        clearInterval(teleprompterIntervalRef.current);
      }
      if (mediaRecorderRef.current?.state === "recording") {
        try {
          mediaRecorderRef.current.stop();
        } catch {
          // تجاهل أخطاء الإيقاف أثناء التفكيك.
        }
      }
      stopCameraTracks(mediaStreamRef.current);
      mediaStreamRef.current = null;
      sessionUrlRegistryRef.current.forEach((url) => {
        URL.revokeObjectURL(url);
      });
      sessionUrlRegistryRef.current.clear();
      blobRegistryRef.current.clear();
    };
  }, [clearCountdownInterval, clearRecordingInterval, stopCameraTracks]);

  const finalizeRecordedTake = useCallback(
    (pendingTake: PendingTake) => {
      const duration = Math.max(recordingTimeRef.current, 1);
      const primaryChunk = recordedChunksRef.current[0];
      const blob =
        recordedChunksRef.current.length > 0
          ? new Blob(recordedChunksRef.current, {
              type: pendingTake.mimeType || primaryChunk?.type ?? "video/webm",
            })
          : null;
      const videoUrl =
        blob && typeof URL.createObjectURL === "function"
          ? URL.createObjectURL(blob)
          : undefined;

      if (blob && videoUrl) {
        blobRegistryRef.current.set(pendingTake.id, blob);
        sessionUrlRegistryRef.current.set(pendingTake.id, videoUrl);
      }

      const insights = buildTakeInsights({
        durationSeconds: duration,
        scriptText,
        teleprompterUsed: pendingTake.teleprompterUsed,
        hadRetake: takes.some((take) => take.source === "captured"),
      });

      const take: Take = {
        id: pendingTake.id,
        name: pendingTake.name,
        duration,
        recordedAt: pendingTake.recordedAt,
        notes: createNotesFromInsights(insights.notes, duration),
        score: insights.score,
        status: "completed",
        mimeType: blob?.type ?? pendingTake.mimeType,
        source: "captured",
        ...(videoUrl ? { videoUrl } : {}),
      };

      setTakes((previous) => [take, ...previous]);
      setNotesTakeId(take.id);
      setComparisonView((previous) => ({
        ...previous,
        leftTakeId: take.id,
        rightTakeId:
          previous.leftTakeId && previous.leftTakeId !== take.id
            ? previous.leftTakeId
            : previous.rightTakeId && previous.rightTakeId !== take.id
              ? previous.rightTakeId
              : previous.leftTakeId,
      }));
      setIsFinalizingTake(false);
      pendingTakeRef.current = null;
      recordedChunksRef.current = [];

      if (blob) {
        showNotification(
          "success",
          `تم حفظ ${take.name} وتوليد تقييمه المحلي بنجاح.`
        );
        return;
      }

      showNotification(
        "error",
        "انتهى التسجيل لكن المتصفح لم يسلم ملف فيديو قابلاً للتصدير."
      );
    },
    [scriptText, showNotification, takes]
  );

  const startRecording = useCallback(async () => {
    if (!scriptText.trim()) {
      showNotification("error", "أدخل نصاً قبل بدء التسجيل.");
      return;
    }

    if (isRecording || isFinalizingTake) {
      return;
    }

    let stream = mediaStreamRef.current;
    if (!stream) {
      stream = await requestCameraAccess();
    }

    if (!stream) {
      return;
    }

    if (typeof MediaRecorder === "undefined") {
      showNotification(
        "error",
        "المتصفح الحالي لا يدعم MediaRecorder، لذا لا يمكن تسجيل فيديو فعلي."
      );
      return;
    }

    const preferredMimeType = pickSupportedMimeType(RECORDING_MIME_CANDIDATES);
    let recorder: MediaRecorder;

    try {
      recorder = preferredMimeType
        ? new MediaRecorder(stream, { mimeType: preferredMimeType })
        : new MediaRecorder(stream);
    } catch {
      recorder = new MediaRecorder(stream);
    }

    recordedChunksRef.current = [];
    clearRecordingInterval();
    setRecordingTime(0);
    recordingTimeRef.current = 0;

    const takeNumber =
      takes.filter((take) => take.source === "captured").length + 1;
    const pendingTake: PendingTake = {
      id: `take-${Date.now()}`,
      name: `Take ${takeNumber}`,
      recordedAt: new Date().toISOString(),
      mimeType: recorder.mimeType || preferredMimeType,
      teleprompterUsed: teleprompterSettings.autoScroll,
    };

    pendingTakeRef.current = pendingTake;
    recorder.ondataavailable = (event: BlobEvent) => {
      if (event.data && event.data.size > 0) {
        recordedChunksRef.current.push(event.data);
      }
    };
    recorder.onstop = () => {
      if (pendingTakeRef.current) {
        finalizeRecordedTake(pendingTakeRef.current);
      }
    };
    recorder.onerror = () => {
      pendingTakeRef.current = null;
      recordedChunksRef.current = [];
      setIsRecording(false);
      setIsFinalizingTake(false);
      showNotification("error", "تعذر إتمام التسجيل. حاول مرة أخرى.");
    };

    try {
      recorder.start(1000);
      mediaRecorderRef.current = recorder;
      setIsRecording(true);
      setIsFinalizingTake(false);
      startTeleprompter();
      recordingIntervalRef.current = setInterval(() => {
        setRecordingTime((previous) => {
          const next = previous + 1;
          recordingTimeRef.current = next;
          return next;
        });
      }, 1000);
      showNotification("info", "بدأ التسجيل الفعلي ويمكنك إنهاؤه متى شئت.");
    } catch {
      pendingTakeRef.current = null;
      showNotification(
        "error",
        "فشل بدء التسجيل في هذه البيئة رغم توفر الكاميرا."
      );
    }
  }, [
    clearRecordingInterval,
    finalizeRecordedTake,
    isFinalizingTake,
    isRecording,
    requestCameraAccess,
    scriptText,
    showNotification,
    startTeleprompter,
    takes,
    teleprompterSettings.autoScroll,
  ]);

  const stopRecording = useCallback(() => {
    const recorder = mediaRecorderRef.current;
    if (!recorder || recorder.state === "inactive") {
      return;
    }

    setIsRecording(false);
    setIsFinalizingTake(true);
    clearRecordingInterval();
    stopTeleprompter();
    showNotification("info", "جاري إنهاء الملف وتحليل التسجيل...");

    try {
      recorder.stop();
    } catch {
      pendingTakeRef.current = null;
      setIsFinalizingTake(false);
      showNotification("error", "تعذر إيقاف التسجيل بشكل صحيح.");
    }
  }, [clearRecordingInterval, showNotification, stopTeleprompter]);

  const deleteTake = useCallback(
    (takeId: string) => {
      revokeTakeResources(takeId);
      setTakes((previous) => previous.filter((take) => take.id !== takeId));
      showNotification("info", "تم حذف التسجيل المختار.");
    },
    [revokeTakeResources, showNotification]
  );

  const addManualNote = useCallback(
    (takeId: string) => {
      const draft = manualNoteDrafts[takeId]?.trim();
      if (!draft) {
        showNotification("error", "اكتب الملاحظة أولاً قبل إضافتها.");
        return;
      }

      const noteType = manualNoteTypes[takeId] ?? "improvement";

      setTakes((previous) =>
        previous.map((take) => {
          if (take.id !== takeId) {
            return take;
          }

          const manualNote: TakeNote = {
            id: `manual-${Date.now()}`,
            timestamp: Math.round(take.duration / 2),
            type: noteType,
            severity: "neutral",
            content: draft,
            autoGenerated: false,
          };

          return {
            ...take,
            notes: [manualNote, ...take.notes],
          };
        })
      );

      setManualNoteDrafts((previous) => ({
        ...previous,
        [takeId]: "",
      }));
      showNotification("success", "تمت إضافة الملاحظة اليدوية.");
    },
    [manualNoteDrafts, manualNoteTypes, showNotification]
  );

  const exportTake = useCallback(
    async (takeId: string) => {
      const take = takes.find((currentTake) => currentTake.id === takeId);
      const blob = blobRegistryRef.current.get(takeId);

      if (!take || !blob) {
        showNotification(
          "error",
          "هذا التسجيل متاح كبيانات وصفية فقط. أعد التسجيل للحصول على ملف قابل للتنزيل."
        );
        return;
      }

      setExportingTakeId(takeId);
      setExportProgress(15);
      await delay(80);

      const recordedExtension = inferExtensionFromMimeType(
        take.mimeType ?? blob.type
      );
      const selectedExtension = exportSettings.format;
      const finalExtension =
        selectedExtension === recordedExtension
          ? selectedExtension
          : recordedExtension;
      const fileName = buildExportFileName({
        actorName: exportSettings.actorName || "actor",
        projectName: exportSettings.projectName || "self-tape",
        roleName: exportSettings.roleName || "scene",
        takeName: take.name,
        extension: finalExtension,
      });

