function isRecord(value: unknown): value is Record<string, unknown> {
  return typeof value === "object" && value !== null && !Array.isArray(value);
}

function isStringArray(value: unknown): value is string[] {
  return (
    Array.isArray(value) && value.every((item) => typeof item === "string")
  );
}

function isPalette(value: unknown): value is ColorPaletteInspiration {
  return (
    isRecord(value) &&
    typeof value["name"] === "string" &&
    typeof value["nameAr"] === "string" &&
    isStringArray(value["colors"])
  );
}

function isMoodBoard(value: unknown): value is MoodBoard {
  return (
    isRecord(value) &&
    typeof value["theme"] === "string" &&
    typeof value["themeAr"] === "string" &&
    isStringArray(value["keywords"]) &&
    (value["suggestedPalette"] === undefined ||
      isPalette(value["suggestedPalette"]))
  );
}

export default function Inspiration() {
  const { state, updateInspirationState } = useArtDirectorPersistence();
  const { sceneDescription, mood, era } = state.inspiration;
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const result = useMemo(
    () =>
      isMoodBoard(state.inspiration.result) ? state.inspiration.result : null,
    [state.inspiration.result]
  );
  const palettes = useMemo<ColorPaletteInspiration[]>(
    () => state.inspiration.palettes.filter(isPalette),
    [state.inspiration.palettes]
  );

  const handleAnalyze = useCallback(async () => {
    if (!sceneDescription.trim()) return;

    setLoading(true);
    setError(null);

    try {
      const data = await fetchArtDirectorJson<AnalysisApiResponse>(
        "/inspiration/analyze",
        {
          method: "POST",
          headers: { "Content-Type": "application/json" },
          body: JSON.stringify({
            sceneDescription,
            mood: mood || undefined,
            era: era || undefined,
          }),
        }
      );

      if (data.success && data.data) {
        updateInspirationState({ result: data.data });
      } else {
        setError(data.error ?? "فشل في تحليل المشهد");
      }
    } catch (err) {
      const errorMessage =
        err instanceof Error ? err.message : "حدث خطأ غير متوقع";
      setError(errorMessage);
    } finally {
      setLoading(false);
    }
  }, [era, mood, sceneDescription, updateInspirationState]);

  const handleGeneratePalette = useCallback(async () => {
    if (!mood) return;

    setLoading(true);
    setError(null);

    try {
      const data = await fetchArtDirectorJson<PaletteApiResponse>(
        "/inspiration/palette",
        {
          method: "POST",
          headers: { "Content-Type": "application/json" },
          body: JSON.stringify({ mood, count: 3 }),
        }
      );

      if (data.success && data.data?.palettes) {
        updateInspirationState({ palettes: data.data.palettes });
      } else {
        setError(data.error ?? "فشل في توليد الباليتات");
      }
    } catch (err) {
      const errorMessage =
        err instanceof Error ? err.message : "حدث خطأ غير متوقع";
      setError(errorMessage);
    } finally {
      setLoading(false);
    }
  }, [mood, updateInspirationState]);

  return (
    <div className="art-director-page">
      <header className="art-page-header">
        <Palette size={32} className="header-icon" aria-hidden="true" />
        <div>
          <h1>الإلهام البصري</h1>
          <p>إنشاء لوحات مزاجية وباليتات ألوان للمشاهد</p>
        </div>
      </header>

      <div className="art-grid-2" style={{ gap: "24px" }}>
        <CardSpotlight className="overflow-hidden rounded-[24px] border border-white/8 bg-white/[0.04] p-5 backdrop-blur-xl">
          <section>
            <h2
              style={{
                display: "flex",
                alignItems: "center",
                gap: "8px",
                marginBottom: "20px",
              }}
            >
              <Wand2 size={20} aria-hidden="true" /> تحليل المشهد
            </h2>

            <div className="art-form-group">
              <label htmlFor="scene-description">وصف المشهد</label>
              <textarea
                id="scene-description"
                className="art-input"
                placeholder="صف المشهد بالتفصيل... مثال: مشهد رومانسي في مقهى قديم بباريس في الثلاثينيات"
                value={sceneDescription}
                onChange={(e) =>
                  updateInspirationState({
                    sceneDescription: e.target.value,
                  })
                }
                rows={4}
                style={{ resize: "none" }}
              />
            </div>

            <div className="art-form-grid">
              <div className="art-form-group">
                <label htmlFor="mood-select">المزاج العام</label>
                <select
                  id="mood-select"
                  className="art-input"
                  value={mood}
                  onChange={(e) =>
                    updateInspirationState({ mood: e.target.value })
                  }
                >
                  <option value="">اختر المزاج</option>
                  <option value="romantic">رومانسي</option>
                  <option value="dramatic">درامي</option>
                  <option value="mysterious">غامض</option>
                  <option value="cheerful">مرح</option>
                  <option value="melancholic">حزين</option>
                  <option value="tense">متوتر</option>
                </select>
              </div>

              <div className="art-form-group">
                <label htmlFor="era-select">الحقبة الزمنية</label>
                <select
                  id="era-select"
                  className="art-input"
                  value={era}
                  onChange={(e) =>
                    updateInspirationState({ era: e.target.value })
                  }
                >
                  <option value="">اختر الحقبة</option>
                  <option value="ancient">قديمة</option>
                  <option value="medieval">عصور وسطى</option>
                  <option value="victorian">فيكتورية</option>
                  <option value="1920s">العشرينيات</option>
                  <option value="1950s">الخمسينيات</option>
                  <option value="1980s">الثمانينيات</option>
                  <option value="modern">حديثة</option>
                  <option value="futuristic">مستقبلية</option>
                </select>
              </div>
            </div>

            {error ? (
              <div
                className="rounded-2xl border border-red-500/20 bg-red-500/10 p-4 text-sm leading-7 text-red-100"
                style={{ marginTop: "12px" }}
                role="alert"
              >
                {error}
              </div>
            ) : null}

            <div style={{ display: "flex", gap: "12px", marginTop: "20px" }}>
              <button
                className="art-btn"
                onClick={handleAnalyze}
                disabled={loading || !sceneDescription.trim()}
                type="button"
              >
                <Sparkles size={18} aria-hidden="true" />
                {loading ? "جاري التحليل..." : "تحليل المشهد"}
              </button>
              <button
                className="art-btn art-btn-secondary"
                onClick={handleGeneratePalette}
                disabled={loading || !mood}
                type="button"
              >
                <Palette size={18} aria-hidden="true" />
                اقتراح ألوان
              </button>
            </div>
          </section>
        </CardSpotlight>

        <section className="space-y-6">
          {result ? <AnalysisResult result={result} /> : null}
          <PalettesGrid palettes={palettes} />
        </section>
      </div>
    </div>
  );
}

"use client";

/**
 * الصفحة: art-director / Productivity
 * الهوية: تحليل إنتاجية داخلي بطابع تشغيلي/بياني متسق مع shell مدير الفن
 * المتغيرات الخاصة المضافة: تعتمد على متغيرات art-director.css المحقونة من الطبقة الأعلى
 * مكونات Aceternity المستخدمة: CardSpotlight
 */

import {
  BarChart3,
  Clock,
  AlertTriangle,
  TrendingUp,
  Plus,
  CheckCircle2,
  TimerReset,
} from "lucide-react";
import { useState, useCallback, useEffect, useMemo } from "react";

import { CardSpotlight } from "@/components/aceternity/card-spotlight";

import { fetchArtDirectorJson } from "../lib/api-client";

import type { ApiResponse } from "../types";



interface TimeFormData {
  task: string;
  hours: string;
  category: string;
}

interface DelayFormData {
  reason: string;
  impact: string;
  hoursLost: string;
}

interface ChartItem {
  name: string;
  hours: number;
  color: string;
}

interface PieItem {
  name: string;
  value: number;
  color: string;
}

interface ProductivityAnalysis {
  period: string;
  department: string;
  totalHours: number;
  taskCount: number;
  delayHours: number;
  completionRate: number;
}

interface ProductivitySummaryResponse {
  chartData: ChartItem[];
  pieData: PieItem[];
}

const DEFAULT_TIME_FORM: TimeFormData = {
  task: "",
  hours: "",
  category: "design",
};

const DEFAULT_DELAY_FORM: DelayFormData = {
  reason: "",
  impact: "low",
  hoursLost: "",
};

const EMPTY_ANALYSIS: ProductivityAnalysis = {
  period: "weekly",
  department: "all",
  totalHours: 0,
  taskCount: 0,
  delayHours: 0,
  completionRate: 0,
};

interface ProgressBarProps {
  item: ChartItem;
  maxHours: number;
}

function ProgressBar({ item, maxHours }: ProgressBarProps) {
  const percentage = useMemo(
    () => (item.hours / maxHours) * 100,
    [item.hours, maxHours]
  );

  return (
    <div style={{ display: "flex", alignItems: "center", gap: "12px" }}>
      <span style={{ width: "80px", fontSize: "14px" }}>{item.name}</span>
      <div
        style={{
          flex: 1,
          height: "24px",
          background: "rgba(255,255,255,0.1)",
          borderRadius: "4px",
          overflow: "hidden",
        }}
      >
        <div
          style={{
            width: `${percentage}%`,
            height: "100%",
            background: item.color,
            borderRadius: "4px",
            transition: "width 0.3s ease",
          }}
          role="progressbar"
          aria-valuenow={item.hours}
          aria-valuemin={0}
          aria-valuemax={maxHours}
        />
      </div>
      <span style={{ width: "40px", fontSize: "14px", textAlign: "left" }}>
        {item.hours}h
      </span>
    </div>
  );
}

interface PieChartItemProps {
  item: PieItem;
}

function PieChartItem({ item }: PieChartItemProps) {
  return (
    <div style={{ textAlign: "center" }}>
      <div
        style={{
          width: "80px",
          height: "80px",
          borderRadius: "50%",
          background: `conic-gradient(${item.color} 0% ${item.value}%, rgba(255,255,255,0.1) ${item.value}% 100%)`,
          display: "flex",
          alignItems: "center",
          justifyContent: "center",
          marginBottom: "8px",
        }}
        role="img"
        aria-label={`${item.name}: ${item.value}%`}
      >
        <div
          style={{
            width: "60px",
            height: "60px",
            borderRadius: "50%",
            background: "var(--art-card)",
            display: "flex",
            alignItems: "center",
            justifyContent: "center",
            fontWeight: 700,
          }}
        >
          {item.value}%
        </div>
      </div>
      <span style={{ fontSize: "14px", color: item.color }}>{item.name}</span>
    </div>
  );
}

interface TimeFormProps {
  formData: TimeFormData;
  onFormChange: (data: Partial<TimeFormData>) => void;
  onSubmit: () => void;
  onCancel: () => void;
}

function TimeForm({
  formData,
  onFormChange,
  onSubmit,
  onCancel,
}: TimeFormProps) {
  return (
    <CardSpotlight className="overflow-hidden rounded-[24px] border border-white/8 bg-white/[0.04] p-5 backdrop-blur-xl">
      <div style={{ animation: "fadeIn 0.3s ease-in-out" }}>
        <h3
          style={{
            display: "flex",
            alignItems: "center",
            gap: "8px",
            marginBottom: "20px",
          }}
        >
          <Clock size={20} aria-hidden="true" /> تسجيل وقت العمل
        </h3>
        <div className="art-form-grid">
          <div className="art-form-group">
            <label htmlFor="time-task">المهمة</label>
            <input
              id="time-task"
              type="text"
              className="art-input"
              placeholder="وصف المهمة"
              value={formData.task}
              onChange={(e) => onFormChange({ task: e.target.value })}
            />
          </div>
          <div className="art-form-group">
            <label htmlFor="time-hours">الساعات</label>
            <input
              id="time-hours"
              type="number"
              className="art-input"
              placeholder="عدد الساعات"
              value={formData.hours}
              onChange={(e) => onFormChange({ hours: e.target.value })}
            />
          </div>
          <div className="art-form-group">
            <label htmlFor="time-category">الفئة</label>
            <select
              id="time-category"
              className="art-input"
              value={formData.category}
              onChange={(e) => onFormChange({ category: e.target.value })}
            >
              <option value="design">تصميم</option>
              <option value="construction">بناء</option>
              <option value="painting">طلاء</option>
              <option value="lighting">إضاءة</option>
              <option value="meetings">اجتماعات</option>
            </select>
          </div>
        </div>
        <div className="art-form-actions">
          <button className="art-btn" onClick={onSubmit} type="button">
            <Plus size={18} aria-hidden="true" /> تسجيل
          </button>
          <button
            className="art-btn art-btn-secondary"
            onClick={onCancel}
            type="button"
          >
            إلغاء
          </button>
        </div>
      </div>
    </CardSpotlight>
  );
}

interface DelayFormProps {
  formData: DelayFormData;
  onFormChange: (data: Partial<DelayFormData>) => void;
  onSubmit: () => void;
  onCancel: () => void;
}

function DelayForm({
  formData,
  onFormChange,
  onSubmit,
  onCancel,
}: DelayFormProps) {
  return (
    <CardSpotlight className="overflow-hidden rounded-[24px] border border-white/8 bg-white/[0.04] p-5 backdrop-blur-xl">
      <div style={{ animation: "fadeIn 0.3s ease-in-out" }}>
        <h3
          style={{
            display: "flex",
            alignItems: "center",
            gap: "8px",
            marginBottom: "20px",
          }}
        >
          <AlertTriangle size={20} aria-hidden="true" /> الإبلاغ عن تأخير
        </h3>
        <div className="art-form-grid">
          <div className="art-form-group full-width">
            <label htmlFor="delay-reason">سبب التأخير</label>
            <textarea
              id="delay-reason"
              className="art-input"
              placeholder="وصف سبب التأخير"
              value={formData.reason}
              onChange={(e) => onFormChange({ reason: e.target.value })}
              rows={3}
              style={{ resize: "none" }}
            />
          </div>
          <div className="art-form-group">
            <label htmlFor="delay-impact">مستوى التأثير</label>
            <select
              id="delay-impact"
              className="art-input"
              value={formData.impact}
              onChange={(e) => onFormChange({ impact: e.target.value })}
            >
              <option value="low">منخفض</option>
              <option value="medium">متوسط</option>
              <option value="high">مرتفع</option>
              <option value="critical">حرج</option>
            </select>
          </div>
          <div className="art-form-group">
            <label htmlFor="delay-hours">الساعات المفقودة</label>
            <input
              id="delay-hours"
              type="number"
              className="art-input"
              placeholder="عدد الساعات"
              value={formData.hoursLost}
              onChange={(e) => onFormChange({ hoursLost: e.target.value })}
            />
          </div>
        </div>
        <div className="art-form-actions">
          <button className="art-btn" onClick={onSubmit} type="button">
            <AlertTriangle size={18} aria-hidden="true" /> إبلاغ
          </button>
          <button
            className="art-btn art-btn-secondary"
            onClick={onCancel}
            type="button"
          >
            إلغاء
          </button>
        </div>
      </div>
    </CardSpotlight>
  );
}

interface RecommendationsListProps {
  recommendations: string[];
}

function RecommendationsList({ recommendations }: RecommendationsListProps) {
  if (recommendations.length === 0) return null;

  return (
    <CardSpotlight className="overflow-hidden rounded-[24px] border border-white/8 bg-white/[0.04] p-5 backdrop-blur-xl">
      <div style={{ animation: "fadeIn 0.3s ease-in-out" }}>
        <h3
          style={{
            display: "flex",
            alignItems: "center",
            gap: "8px",
            marginBottom: "16px",
          }}
        >
          <TrendingUp size={20} aria-hidden="true" /> توصيات التحسين
        </h3>
        <ul style={{ listStyle: "none", padding: 0, margin: 0 }} role="list">
          {recommendations.map((rec, index) => (
            <li
              key={index}
              style={{
                padding: "12px",
                background: "rgba(74, 222, 128, 0.1)",
                borderRadius: "8px",
                marginBottom: "8px",
              }}
            >
              {rec}
            </li>
          ))}
        </ul>
      </div>
