export default function Sets() {
  const { state, updateSetsState } = useArtDirectorPersistence();
  const [pieces, setPieces] = useState<SetPiece[]>([]);
  const [report, setReport] = useState<SustainabilityReport | null>(null);
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const { showAddForm, formData } = state.sets;

  const handleAddPiece = useCallback(async () => {
    setLoading(true);
    setError(null);

    try {
      const data = await fetchArtDirectorJson<ApiResponse>("/sets/add-piece", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify(formData),
      });

      if (data.success) {
        updateSetsState({
          showAddForm: false,
          formData: DEFAULT_FORM_DATA,
        });
        await loadInventory();
        await loadSustainabilityReport();
      } else {
        setError(data.error ?? "فشل في إضافة القطعة");
      }
    } catch (err) {
      const errorMessage =
        err instanceof Error ? err.message : "حدث خطأ أثناء الإضافة";
      setError(errorMessage);
    } finally {
      setLoading(false);
    }
  }, [formData, updateSetsState]);

  const loadInventory = useCallback(async () => {
    setError(null);

    try {
      const data = await fetchArtDirectorJson<
        ApiResponse<{ pieces: SetPiece[] }>
      >("/sets/inventory", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({}),
      });

      if (data.success && data.data?.pieces) {
        setPieces(data.data.pieces);
      } else {
        if (data.error) setError(data.error);
      }
    } catch (err) {
      const errorMessage =
        err instanceof Error ? err.message : "حدث خطأ أثناء تحميل المخزون";
      setError(errorMessage);
    }
  }, []);

  const loadSustainabilityReport = useCallback(async () => {
    setLoading(true);
    setError(null);

    try {
      const data = await fetchArtDirectorJson<
        ApiResponse<SustainabilityReport>
      >("/sets/sustainability-report", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({}),
      });

      if (data.success && data.data) {
        setReport(data.data);
      } else {
        setError(data.error ?? "فشل في تحميل التقرير");
      }
    } catch (err) {
      const errorMessage =
        err instanceof Error ? err.message : "حدث خطأ أثناء تحميل التقرير";
      setError(errorMessage);
    } finally {
      setLoading(false);
    }
  }, []);

  const handleFormChange = useCallback(
    (data: Partial<SetPieceFormData>) => {
      updateSetsState({
        formData: {
          ...formData,
          ...data,
        },
      });
    },
    [formData, updateSetsState]
  );

  const handleCancelForm = useCallback(() => {
    updateSetsState({
      showAddForm: false,
      formData: DEFAULT_FORM_DATA,
    });
  }, [updateSetsState]);

  const piecesContent = useMemo(() => {
    if (pieces.length === 0) {
      return <EmptyState />;
    }

    return pieces.map((piece) => <SetPieceCard key={piece.id} piece={piece} />);
  }, [pieces]);

  useEffect(() => {
    void loadInventory();
    void loadSustainabilityReport();
  }, [loadInventory, loadSustainabilityReport]);

  return (
    <div className="art-director-page">
      <header className="art-page-header">
        <Boxes size={32} className="header-icon" aria-hidden="true" />
        <div>
          <h1>إدارة الديكورات</h1>
          <p>تتبع قطع الديكور وتحليل إعادة الاستخدام</p>
        </div>
      </header>

      <div className="art-toolbar">
        <button
          className="art-btn"
          onClick={() => updateSetsState({ showAddForm: true })}
          type="button"
        >
          <Plus size={18} aria-hidden="true" />
          إضافة قطعة
        </button>
        <button
          className="art-btn art-btn-secondary"
          onClick={loadInventory}
          type="button"
        >
          <Boxes size={18} aria-hidden="true" />
          عرض المخزون
        </button>
        <button
          className="art-btn art-btn-secondary"
          onClick={loadSustainabilityReport}
          disabled={loading}
          type="button"
        >
          <Leaf size={18} aria-hidden="true" />
          {loading ? "جاري التحميل..." : "تقرير الاستدامة"}
        </button>
      </div>

      {error ? (
        <div
          className="rounded-2xl border border-red-500/20 bg-red-500/10 p-4 text-sm leading-7 text-red-100"
          style={{ marginBottom: "24px" }}
          role="alert"
        >
          {error}
        </div>
      ) : null}

      {showAddForm ? (
        <AddPieceForm
          formData={formData}
          loading={loading}
          onFormChange={handleFormChange}
          onSubmit={handleAddPiece}
          onCancel={handleCancelForm}
        />
      ) : null}

      {report ? <SustainabilityReportCard report={report} /> : null}

      <div className="art-grid-4">{piecesContent}</div>
    </div>
  );
}

import { describe, it, expect } from "vitest";

import { PluginManager } from "../core/PluginManager";
import { Plugin, PluginCategory } from "../types";

class MockPlugin implements Plugin {
  id: string;
  name: string;
  nameAr: string;
  version = "1.0.0";
  description = "Mock Plugin";
  descriptionAr = "إضافة وهمية";
  category: PluginCategory = "ai-analytics";
  delay: number;

  constructor(id: string, name: string, delay: number) {
    this.id = id;
    this.name = name;
    this.nameAr = name;
    this.delay = delay;
  }

  async initialize(): Promise<void> {
    await new Promise((resolve) => setTimeout(resolve, this.delay));
  }

  async execute(): Promise<any> {
    return { success: true };
  }

  async shutdown(): Promise<void> {
    await new Promise((resolve) => setTimeout(resolve, this.delay));
  }
}

describe("PluginManager Performance", () => {
  it("should measure parallel shutdown (optimized)", async () => {
    const pm = new PluginManager();
    const pluginCount = 5;
    const delay = 100;

    for (let i = 0; i < pluginCount; i++) {
      await pm.registerPlugin(new MockPlugin(`p${i}`, `Plugin ${i}`, delay));
    }

    const start = Date.now();
    await pm.shutdownAll();
    const duration = Date.now() - start;

    console.log(`Parallel shutdown with 5 plugins took ${duration}ms`);
    // Parallel should be faster than sequential (pluginCount * delay)
    // It should be around delay + overhead
    expect(duration).toBeLessThan(pluginCount * delay);
    expect(duration).toBeGreaterThanOrEqual(delay);
  });

  it("should measure parallel initialization (optimized)", async () => {
    const pm = new PluginManager();
    const pluginCount = 5;
    const delay = 100;

    for (let i = 0; i < pluginCount; i++) {
      await pm.registerPlugin(new MockPlugin(`p${i}`, `Plugin ${i}`, delay));
    }

    const start = Date.now();
    await pm.initializeAll();
    const duration = Date.now() - start;

    console.log(`Parallel initialization with 5 plugins took ${duration}ms`);
    // Parallel should be faster than sequential (pluginCount * delay)
    expect(duration).toBeLessThan(pluginCount * delay);
    expect(duration).toBeGreaterThanOrEqual(delay);
  });
});

// CineArchitect AI - Plugin Manager
// مدير الإضافات

import { Plugin, PluginInput, PluginOutput, PluginCategory } from "../types";

export class PluginManager {
  private plugins = new Map<string, Plugin>();
  private initialized = false;

  async registerPlugin(plugin: Plugin): Promise<void> {
    if (this.plugins.has(plugin.id)) {
      throw new Error(`Plugin with ID "${plugin.id}" is already registered`);
    }

    this.plugins.set(plugin.id, plugin);
    console.log(
      `[PluginManager] Registered plugin: ${plugin.name} (${plugin.nameAr})`
    );
  }

  async unregisterPlugin(pluginId: string): Promise<void> {
    const plugin = this.plugins.get(pluginId);
    if (!plugin) {
      throw new Error(`Plugin with ID "${pluginId}" not found`);
    }

    await plugin.shutdown();
    this.plugins.delete(pluginId);
    console.log(`[PluginManager] Unregistered plugin: ${plugin.name}`);
  }

  async initializeAll(): Promise<void> {
    console.log("[PluginManager] Initializing all plugins in parallel...");

    const initializationPromises = Array.from(this.plugins.values()).map(
      async (plugin) => {
        try {
          await plugin.initialize();
          console.log(`[PluginManager] Initialized: ${plugin.name}`);
        } catch (error) {
          console.error(
            `[PluginManager] Failed to initialize ${plugin.name}:`,
            error
          );
        }
      }
    );

    await Promise.all(initializationPromises);

    this.initialized = true;
    console.log(
      `[PluginManager] All plugins initialization attempted (${this.plugins.size} total)`
    );
  }

  async shutdownAll(): Promise<void> {
    console.log("[PluginManager] Shutting down all plugins in parallel...");

    const shutdownPromises = Array.from(this.plugins.values()).map(
      async (plugin) => {
        try {
          await plugin.shutdown();
          console.log(`[PluginManager] Shut down: ${plugin.name}`);
        } catch (error) {
          console.error(
            `[PluginManager] Failed to shut down ${plugin.name}:`,
            error
          );
        }
      }
    );

    await Promise.all(shutdownPromises);

    this.initialized = false;
    console.log(
      `[PluginManager] All plugins shutdown attempted (${this.plugins.size} total)`
    );
  }

  async executePlugin(
    pluginId: string,
    input: PluginInput
  ): Promise<PluginOutput> {
    const plugin = this.plugins.get(pluginId);
    if (!plugin) {
      return {
        success: false,
        error: `Plugin with ID "${pluginId}" not found`,
      };
    }

    try {
      return await plugin.execute(input);
    } catch (error) {
      return {
        success: false,
        error: error instanceof Error ? error.message : "Unknown error",
      };
    }
  }

  getPlugin(pluginId: string): Plugin | undefined {
    return this.plugins.get(pluginId);
  }

  getAllPlugins(): Plugin[] {
    return Array.from(this.plugins.values());
  }

  getPluginsByCategory(category: PluginCategory): Plugin[] {
    return this.getAllPlugins().filter((p) => p.category === category);
  }

  getPluginInfo(): {
    id: string;
    name: string;
    nameAr: string;
    version: string;
    category: PluginCategory;
  }[] {
    return this.getAllPlugins().map((p) => ({
      id: p.id,
      name: p.name,
      nameAr: p.nameAr,
      version: p.version,
      category: p.category,
    }));
  }

  isInitialized(): boolean {
    return this.initialized;
  }
}

// Singleton instance
export const pluginManager = new PluginManager();

