interface ProductionBook {
  title: string;
  titleAr: string;
  sections: string[];
  createdAt: string;
}

interface StyleGuide {
  name: string;
  nameAr: string;
  elements: string[];
}

function Documentation() {
  const [showBookForm, setShowBookForm] = useState(false);
  const [showDecisionForm, setShowDecisionForm] = useState(false);
  const [productionBook, setProductionBook] = useState<ProductionBook | null>(
    null
  );
  const [styleGuide, setStyleGuide] = useState<StyleGuide | null>(null);
  const [loading, setLoading] = useState(false);

  const [bookForm, setBookForm] = useState({
    projectName: "",
    projectNameAr: "",
    director: "",
    productionCompany: "",
  });

  const [decisionForm, setDecisionForm] = useState({
    title: "",
    description: "",
    category: "color",
    rationale: "",
  });

  const handleGenerateBook = async () => {
    setLoading(true);
    try {
      const response = await fetch(
        artDirectorApiPath("/documentation/generate"),
        {
          method: "POST",
          headers: { "Content-Type": "application/json" },
          body: JSON.stringify(bookForm),
        }
      );
      const data = await response.json();
      if (data.success && data.data) {
        setProductionBook(data.data);
        setShowBookForm(false);
      }
    } catch (error) {
      console.error("Error:", error);
    }
    setLoading(false);
  };

  const handleGenerateStyleGuide = async () => {
    setLoading(true);
    try {
      const response = await fetch(
        artDirectorApiPath("/documentation/style-guide"),
        {
          method: "POST",
          headers: { "Content-Type": "application/json" },
          body: JSON.stringify({
            projectName: bookForm.projectName || "مشروع جديد",
          }),
        }
      );
      const data = await response.json();
      if (data.success && data.data) {
        setStyleGuide(data.data);
      }
    } catch (error) {
      console.error("Error:", error);
    }
    setLoading(false);
  };

  const handleLogDecision = async () => {
    setLoading(true);
    try {
      const response = await fetch(
        artDirectorApiPath("/documentation/log-decision"),
        {
          method: "POST",
          headers: { "Content-Type": "application/json" },
          body: JSON.stringify(decisionForm),
        }
      );
      const data = await response.json();
      if (data.success) {
        setShowDecisionForm(false);
        setDecisionForm({
          title: "",
          description: "",
          category: "color",
          rationale: "",
        });
      }
    } catch (error) {
      console.error("Error:", error);
    }
    setLoading(false);
  };

  const handleExport = async (format: string) => {
    try {
      const response = await fetch(
        artDirectorApiPath("/documentation/export"),
        {
          method: "POST",
          headers: { "Content-Type": "application/json" },
          body: JSON.stringify({ format }),
        }
      );
      const data = await response.json();
      if (data.success) {
        alert(`تم تصدير التوثيق بصيغة ${format.toUpperCase()}`);
      }
    } catch (error) {
      console.error("Error:", error);
    }
  };

  return (
    <div className="documentation-page fade-in">
      <header className="page-header">
        <FileText size={32} className="header-icon" />
        <div>
          <h1>التوثيق التلقائي</h1>
          <p>إنشاء كتب الإنتاج وأدلة الأسلوب</p>
        </div>
      </header>

      <div className="documentation-toolbar">
        <button className="btn" onClick={() => setShowBookForm(true)}>
          <Book size={18} />
          إنشاء كتاب إنتاج
        </button>
        <button
          className="btn btn-secondary"
          onClick={handleGenerateStyleGuide}
          disabled={loading}
        >
          <PenTool size={18} />
          دليل الأسلوب
        </button>
        <button
          className="btn btn-secondary"
          onClick={() => setShowDecisionForm(true)}
        >
          <Plus size={18} />
          توثيق قرار
        </button>
      </div>

      {showBookForm && (
        <div className="form-modal card fade-in">
          <h3>
            <Book size={20} /> إنشاء كتاب الإنتاج
          </h3>
          <div className="form-grid">
            <div className="form-group">
              <label>اسم المشروع (عربي)</label>
              <input
                type="text"
                className="input"
                placeholder="مثال: رحلة إلى المجهول"
                value={bookForm.projectNameAr}
                onChange={(e) =>
                  setBookForm({ ...bookForm, projectNameAr: e.target.value })
                }
              />
            </div>
            <div className="form-group">
              <label>اسم المشروع (إنجليزي)</label>
              <input
                type="text"
                className="input"
                placeholder="Example: Journey to the Unknown"
                value={bookForm.projectName}
                onChange={(e) =>
                  setBookForm({ ...bookForm, projectName: e.target.value })
                }
              />
            </div>
            <div className="form-group">
              <label>المخرج</label>
              <input
                type="text"
                className="input"
                placeholder="اسم المخرج"
                value={bookForm.director}
                onChange={(e) =>
                  setBookForm({ ...bookForm, director: e.target.value })
                }
              />
            </div>
            <div className="form-group">
              <label>شركة الإنتاج</label>
              <input
                type="text"
                className="input"
                placeholder="اسم الشركة"
                value={bookForm.productionCompany}
                onChange={(e) =>
                  setBookForm({
                    ...bookForm,
                    productionCompany: e.target.value,
                  })
                }
              />
            </div>
          </div>
          <div className="form-actions">
            <button
              className="btn"
              onClick={handleGenerateBook}
              disabled={loading}
            >
              <Book size={18} />
              {loading ? "جاري الإنشاء..." : "إنشاء"}
            </button>
            <button
              className="btn btn-secondary"
              onClick={() => setShowBookForm(false)}
            >
              إلغاء
            </button>
          </div>
        </div>
      )}

      {showDecisionForm && (
        <div className="form-modal card fade-in">
          <h3>
            <PenTool size={20} /> توثيق قرار إبداعي
          </h3>
          <div className="form-grid">
            <div className="form-group full-width">
              <label>عنوان القرار</label>
              <input
                type="text"
                className="input"
                placeholder="مثال: اختيار اللون الرئيسي للديكور"
                value={decisionForm.title}
                onChange={(e) =>
                  setDecisionForm({ ...decisionForm, title: e.target.value })
                }
              />
            </div>
            <div className="form-group full-width">
              <label>الوصف</label>
              <textarea
                className="input"
                placeholder="وصف تفصيلي للقرار"
                value={decisionForm.description}
                onChange={(e) =>
                  setDecisionForm({
                    ...decisionForm,
                    description: e.target.value,
                  })
                }
              />
            </div>
            <div className="form-group">
              <label>الفئة</label>
              <select
                className="input"
                value={decisionForm.category}
                onChange={(e) =>
                  setDecisionForm({ ...decisionForm, category: e.target.value })
                }
              >
                <option value="color">الألوان</option>
                <option value="lighting">الإضاءة</option>
                <option value="props">الإكسسوارات</option>
                <option value="furniture">الأثاث</option>
                <option value="texture">الخامات</option>
              </select>
            </div>
            <div className="form-group">
              <label>المبرر</label>
              <input
                type="text"
                className="input"
                placeholder="سبب اتخاذ هذا القرار"
                value={decisionForm.rationale}
                onChange={(e) =>
                  setDecisionForm({
                    ...decisionForm,
                    rationale: e.target.value,
                  })
                }
              />
            </div>
          </div>
          <div className="form-actions">
            <button
              className="btn"
              onClick={handleLogDecision}
              disabled={loading}
            >
              <Plus size={18} />
              {loading ? "جاري التوثيق..." : "توثيق"}
            </button>
            <button
              className="btn btn-secondary"
              onClick={() => setShowDecisionForm(false)}
            >
              إلغاء
            </button>
          </div>
        </div>
      )}

      <div className="documentation-grid">
        {productionBook && (
          <div className="doc-card card fade-in">
            <div className="doc-header">
              <Book size={24} />
              <div>
                <h3>{productionBook.titleAr}</h3>
                <p>{productionBook.title}</p>
              </div>
            </div>
            <div className="doc-sections">
              <h4>الأقسام:</h4>
              <ul>
                {productionBook.sections.map((section, index) => (
                  <li key={index}>{section}</li>
                ))}
              </ul>
            </div>
            <div className="doc-meta">
              تاريخ الإنشاء:{" "}
              {new Date(productionBook.createdAt).toLocaleDateString("ar-EG")}
            </div>
            <div className="export-buttons">
              <button
                className="btn btn-secondary"
                onClick={() => handleExport("pdf")}
              >
                <Download size={16} /> PDF
              </button>
              <button
                className="btn btn-secondary"
                onClick={() => handleExport("docx")}
              >
                <Download size={16} /> Word
              </button>
            </div>
          </div>
        )}

        {styleGuide && (
          <div className="doc-card card fade-in">
            <div className="doc-header">
              <PenTool size={24} />
              <div>
                <h3>{styleGuide.nameAr}</h3>
                <p>{styleGuide.name}</p>
              </div>
            </div>
            <div className="doc-sections">
              <h4>العناصر:</h4>
              <div className="elements-grid">
                {styleGuide.elements.map((element, index) => (
                  <span key={index} className="element-tag">
                    {element}
                  </span>
                ))}
              </div>
            </div>
          </div>
        )}
      </div>
    </div>
  );
}

export default Documentation;

import { Palette, Sparkles, Image, Wand2 } from "lucide-react";
import { useState } from "react";

import "./Inspiration.css";
import { artDirectorApiPath } from "../lib/api-client";

interface ColorPalette {
  name: string;
  nameAr: string;
  colors: string[];
}

interface MoodBoard {
  theme: string;
  themeAr: string;
  keywords: string[];
  suggestedPalette: ColorPalette;
}

function Inspiration() {
  const [sceneDescription, setSceneDescription] = useState("");
  const [mood, setMood] = useState("");
  const [era, setEra] = useState("");
  const [loading, setLoading] = useState(false);
  const [result, setResult] = useState<MoodBoard | null>(null);
  const [palettes, setPalettes] = useState<ColorPalette[]>([]);

  const handleAnalyze = async () => {
    if (!sceneDescription) return;

    setLoading(true);
    try {
      const response = await fetch(artDirectorApiPath("/inspiration/analyze"), {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({
          sceneDescription,
          mood: mood || undefined,
          era: era || undefined,
        }),
      });
      const data = await response.json();
      if (data.success && data.data) {
        setResult(data.data);
      }
    } catch (error) {
      console.error("Error:", error);
    }
    setLoading(false);
  };

  const handleGeneratePalette = async () => {
    if (!mood) return;

    setLoading(true);
    try {
      const response = await fetch(artDirectorApiPath("/inspiration/palette"), {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ mood, count: 3 }),
      });
      const data = await response.json();
      if (data.success && data.data?.palettes) {
        setPalettes(data.data.palettes);
      }
    } catch (error) {
      console.error("Error:", error);
    }
    setLoading(false);
  };

  return (
    <div className="inspiration-page fade-in">
      <header className="page-header">
        <Palette size={32} className="header-icon" />
        <div>
          <h1>الإلهام البصري</h1>
          <p>إنشاء لوحات مزاجية وباليتات ألوان للمشاهد</p>
        </div>
      </header>

      <div className="inspiration-grid">
        <section className="input-section card">
          <h2>
            <Wand2 size={20} /> تحليل المشهد
          </h2>

          <div className="form-group">
            <label>وصف المشهد</label>
            <textarea
              className="input"
              placeholder="صف المشهد بالتفصيل... مثال: مشهد رومانسي في مقهى قديم بباريس في الثلاثينيات"
              value={sceneDescription}
              onChange={(e) => setSceneDescription(e.target.value)}
            />
          </div>

          <div className="form-row">
            <div className="form-group">
              <label>المزاج العام</label>
              <select
                className="input"
                value={mood}
                onChange={(e) => setMood(e.target.value)}
              >
                <option value="">اختر المزاج</option>
                <option value="romantic">رومانسي</option>
                <option value="dramatic">درامي</option>
                <option value="mysterious">غامض</option>
                <option value="cheerful">مرح</option>
                <option value="melancholic">حزين</option>
                <option value="tense">متوتر</option>
              </select>
            </div>

            <div className="form-group">
              <label>الحقبة الزمنية</label>
              <select
                className="input"
                value={era}
                onChange={(e) => setEra(e.target.value)}
              >
                <option value="">اختر الحقبة</option>
                <option value="ancient">قديمة</option>
                <option value="medieval">عصور وسطى</option>
                <option value="victorian">فيكتورية</option>
                <option value="1920s">العشرينيات</option>
                <option value="1950s">الخمسينيات</option>
                <option value="1980s">الثمانينيات</option>
                <option value="modern">حديثة</option>
                <option value="futuristic">مستقبلية</option>
              </select>
            </div>
          </div>

          <div className="button-row">
            <button
              className="btn"
              onClick={handleAnalyze}
              disabled={loading || !sceneDescription}
            >
              <Sparkles size={18} />
              {loading ? "جاري التحليل..." : "تحليل المشهد"}
            </button>
            <button
              className="btn btn-secondary"
              onClick={handleGeneratePalette}
              disabled={loading || !mood}
            >
              <Palette size={18} />
              اقتراح ألوان
            </button>
          </div>
        </section>

        <section className="results-section">
          {result && (
            <div className="result-card card fade-in">
              <h3>
                <Image size={20} /> نتائج التحليل
              </h3>

              <div className="result-theme">
                <span className="theme-label">الموضوع:</span>
                <span className="theme-value">{result.themeAr}</span>
              </div>

              <div className="keywords-section">
                <span className="keywords-label">الكلمات المفتاحية:</span>
                <div className="keywords-list">
                  {result.keywords.map((keyword, index) => (
                    <span key={index} className="keyword-tag">
                      {keyword}
                    </span>
                  ))}
                </div>
              </div>

              {result.suggestedPalette && (
                <div className="palette-section">
                  <span className="palette-label">
                    الباليت المقترح: {result.suggestedPalette.nameAr}
                  </span>
                  <div className="color-row">
                    {result.suggestedPalette.colors.map((color, index) => (
                      <div
                        key={index}
                        className="color-swatch"
                        style={{ background: color }}
                        title={color}
                      />
                    ))}
                  </div>
                </div>
              )}
            </div>
          )}

          {palettes.length > 0 && (
            <div className="palettes-grid fade-in">
              {palettes.map((palette, index) => (
                <div key={index} className="palette-card card">
                  <h4>{palette.nameAr}</h4>
                  <p className="palette-name-en">{palette.name}</p>
                  <div className="color-row">
                    {palette.colors.map((color, colorIndex) => (
                      <div
                        key={colorIndex}
                        className="color-swatch"
                        style={{ background: color }}
                        title={color}
                      />
                    ))}
                  </div>
                </div>
              ))}
            </div>
          )}
        </section>
      </div>
    </div>
  );
}

export default Inspiration;

import { MapPin, Plus, Search, Building, Trees, Mountain } from "lucide-react";
import { useState } from "react";

import "./Locations.css";
import { artDirectorApiPath } from "../lib/api-client";

interface Location {
  id: string;
  name: string;
  nameAr: string;
  type: string;
  address: string;
  features: string[];
}

function Locations() {
  const [locations, setLocations] = useState<Location[]>([]);
  const [showAddForm, setShowAddForm] = useState(false);
  const [searchQuery, setSearchQuery] = useState("");
  const [formData, setFormData] = useState({
    name: "",
    nameAr: "",
    type: "interior",
    address: "",
    features: "",
  });

  const handleSearch = async () => {
    try {
      const response = await fetch(artDirectorApiPath("/locations/search"), {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ query: searchQuery || undefined }),
      });
      const data = await response.json();
      if (data.success && data.data?.locations) {
        setLocations(data.data.locations);
      }
    } catch (error) {
      console.error("Error:", error);
    }
  };

  const handleAddLocation = async () => {
    try {
      const response = await fetch(artDirectorApiPath("/locations/add"), {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({
          ...formData,
          features: formData.features
            .split(",")
            .map((f) => f.trim())
            .filter(Boolean),
        }),
      });
      const data = await response.json();
      if (data.success) {
        setShowAddForm(false);
        setFormData({
          name: "",
          nameAr: "",
          type: "interior",
          address: "",
          features: "",
        });
        handleSearch();
      }
    } catch (error) {
      console.error("Error:", error);
    }
  };

  const getTypeIcon = (type: string) => {
    switch (type) {
      case "exterior":
        return Trees;
      case "natural":
        return Mountain;
      default:
        return Building;
    }
  };

  return (
    <div className="locations-page fade-in">
      <header className="page-header">
        <MapPin size={32} className="header-icon" />
        <div>
          <h1>إدارة المواقع</h1>
          <p>قاعدة بيانات مواقع التصوير والديكورات</p>
        </div>
      </header>

      <div className="locations-toolbar">
        <div className="search-box">
          <input
            type="text"
            className="input"
            placeholder="ابحث عن موقع..."
            value={searchQuery}
            onChange={(e) => setSearchQuery(e.target.value)}
            onKeyPress={(e) => e.key === "Enter" && handleSearch()}
          />
          <button className="btn" onClick={handleSearch}>
            <Search size={18} />
            بحث
          </button>
        </div>
        <button className="btn" onClick={() => setShowAddForm(true)}>
          <Plus size={18} />
          إضافة موقع جديد
        </button>
      </div>

      {showAddForm && (
        <div className="add-form card fade-in">
          <h3>إضافة موقع جديد</h3>
          <div className="form-grid">
            <div className="form-group">
              <label>اسم الموقع (عربي)</label>
              <input
                type="text"
                className="input"
                placeholder="مثال: قصر البارون"
                value={formData.nameAr}
                onChange={(e) =>
                  setFormData({ ...formData, nameAr: e.target.value })
                }
              />
            </div>
            <div className="form-group">
              <label>اسم الموقع (إنجليزي)</label>
              <input
                type="text"
                className="input"
                placeholder="Example: Baron Palace"
                value={formData.name}
                onChange={(e) =>
                  setFormData({ ...formData, name: e.target.value })
                }
              />
            </div>
            <div className="form-group">
              <label>النوع</label>
              <select
                className="input"
                value={formData.type}
                onChange={(e) =>
                  setFormData({ ...formData, type: e.target.value })
                }
              >
                <option value="interior">داخلي</option>
                <option value="exterior">خارجي</option>
                <option value="natural">طبيعي</option>
                <option value="studio">استوديو</option>
              </select>
            </div>
            <div className="form-group">
              <label>العنوان</label>
              <input
                type="text"
                className="input"
                placeholder="العنوان الكامل"
                value={formData.address}
                onChange={(e) =>
                  setFormData({ ...formData, address: e.target.value })
                }
              />
            </div>
            <div className="form-group full-width">
              <label>المميزات (مفصولة بفواصل)</label>
              <input
                type="text"
                className="input"
                placeholder="مثال: إضاءة طبيعية, مساحة واسعة, موقف سيارات"
                value={formData.features}
                onChange={(e) =>
                  setFormData({ ...formData, features: e.target.value })
                }
              />
            </div>
          </div>
          <div className="form-actions">
            <button className="btn" onClick={handleAddLocation}>
              <Plus size={18} />
              إضافة
            </button>
            <button
              className="btn btn-secondary"
              onClick={() => setShowAddForm(false)}
            >
              إلغاء
            </button>
          </div>
        </div>
      )}

      <div className="locations-grid grid grid-3">
        {locations.length === 0 ? (
          <div className="empty-state card">
            <MapPin size={48} />
            <h3>لا توجد مواقع</h3>
            <p>ابدأ بإضافة موقع جديد أو قم بالبحث</p>
          </div>
        ) : (
          locations.map((location) => {
            const TypeIcon = getTypeIcon(location.type);
            return (
              <div key={location.id} className="location-card card">
                <div className="location-type">
                  <TypeIcon size={16} />
                  {location.type}
                </div>
                <h3>{location.nameAr}</h3>
                <p className="location-name-en">{location.name}</p>
                <p className="location-address">{location.address}</p>
                {location.features && location.features.length > 0 && (
                  <div className="location-features">
                    {location.features.map((feature, index) => (
                      <span key={index} className="feature-tag">
                        {feature}
                      </span>
                    ))}
                  </div>
                )}
              </div>
            );
          })
        )}
      </div>
    </div>
  );
}

export default Locations;

import { Boxes, Recycle, Leaf, Plus } from "lucide-react";
import { useState } from "react";

import "./Sets.css";
import { artDirectorApiPath } from "../lib/api-client";

interface SetPiece {
  id: string;
  name: string;
  nameAr: string;
  category: string;
  condition: string;
  reusabilityScore: number;
}

interface SustainabilityReport {
  totalPieces: number;
  reusablePercentage: number;
  estimatedSavings: number;
  environmentalImpact: string;
}

function Sets() {
  const [pieces, setPieces] = useState<SetPiece[]>([]);
  const [report, setReport] = useState<SustainabilityReport | null>(null);
  const [showAddForm, setShowAddForm] = useState(false);
  const [loading, setLoading] = useState(false);
  const [formData, setFormData] = useState({
    name: "",
    nameAr: "",
    category: "furniture",
    condition: "excellent",
    dimensions: "",
  });

  const handleAddPiece = async () => {
    setLoading(true);
    try {
      const response = await fetch(artDirectorApiPath("/sets/add-piece"), {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify(formData),
      });
      const data = await response.json();
      if (data.success) {
        setShowAddForm(false);
        setFormData({
          name: "",
          nameAr: "",
          category: "furniture",
          condition: "excellent",
          dimensions: "",
        });
        loadInventory();
      }
    } catch (error) {
      console.error("Error:", error);
    }
    setLoading(false);
  };

  const loadInventory = async () => {
    try {
      const response = await fetch(artDirectorApiPath("/sets/inventory"), {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({}),
      });
      const data = await response.json();
      if (data.success && data.data?.pieces) {
        setPieces(data.data.pieces);
      }
    } catch (error) {
      console.error("Error:", error);
    }
  };

  const loadSustainabilityReport = async () => {
    setLoading(true);
    try {
      const response = await fetch(
        artDirectorApiPath("/sets/sustainability-report"),
        {
          method: "POST",
          headers: { "Content-Type": "application/json" },
          body: JSON.stringify({}),
        }
      );
      const data = await response.json();
      if (data.success && data.data) {
        setReport(data.data);
      }
    } catch (error) {
      console.error("Error:", error);
    }
    setLoading(false);
  };

  const getConditionColor = (condition: string) => {
    switch (condition) {
      case "excellent":
        return "#4ade80";
      case "good":
        return "#fbbf24";
      case "fair":
        return "#f97316";
      default:
        return "#ef4444";
    }
  };

  const getConditionLabel = (condition: string) => {
    switch (condition) {
      case "excellent":
        return "ممتاز";
      case "good":
        return "جيد";
      case "fair":
        return "مقبول";
      default:
        return "سيء";
    }
  };

  return (
    <div className="sets-page fade-in">
      <header className="page-header">
        <Boxes size={32} className="header-icon" />
        <div>
          <h1>إدارة الديكورات</h1>
          <p>تتبع قطع الديكور وتحليل إعادة الاستخدام</p>
        </div>
      </header>

      <div className="sets-toolbar">
        <button className="btn" onClick={() => setShowAddForm(true)}>
          <Plus size={18} />
          إضافة قطعة
        </button>
        <button className="btn btn-secondary" onClick={loadInventory}>
          <Boxes size={18} />
          عرض المخزون
        </button>
        <button
          className="btn btn-secondary"
          onClick={loadSustainabilityReport}
        >
          <Leaf size={18} />
          تقرير الاستدامة
        </button>
      </div>

      {showAddForm && (
        <div className="add-form card fade-in">
          <h3>إضافة قطعة ديكور</h3>
          <div className="form-grid">
            <div className="form-group">
              <label>الاسم (عربي)</label>
              <input
                type="text"
                className="input"
                placeholder="مثال: كنبة كلاسيكية"
                value={formData.nameAr}
                onChange={(e) =>
                  setFormData({ ...formData, nameAr: e.target.value })
                }
              />
            </div>
            <div className="form-group">
              <label>الاسم (إنجليزي)</label>
              <input
                type="text"
                className="input"
                placeholder="Example: Classic Sofa"
                value={formData.name}
                onChange={(e) =>
                  setFormData({ ...formData, name: e.target.value })
                }
              />
            </div>
            <div className="form-group">
              <label>الفئة</label>
              <select
                className="input"
                value={formData.category}
                onChange={(e) =>
                  setFormData({ ...formData, category: e.target.value })
                }
              >
                <option value="furniture">أثاث</option>
                <option value="props">إكسسوارات</option>
                <option value="lighting">إضاءة</option>
                <option value="textiles">أقمشة</option>
                <option value="structural">هياكل</option>
              </select>
            </div>
            <div className="form-group">
              <label>الحالة</label>
              <select
                className="input"
                value={formData.condition}
                onChange={(e) =>
                  setFormData({ ...formData, condition: e.target.value })
                }
              >
                <option value="excellent">ممتاز</option>
                <option value="good">جيد</option>
                <option value="fair">مقبول</option>
                <option value="poor">سيء</option>
              </select>
            </div>
            <div className="form-group full-width">
              <label>الأبعاد</label>
              <input
                type="text"
                className="input"
                placeholder="مثال: 200×80×90 سم"
                value={formData.dimensions}
                onChange={(e) =>
                  setFormData({ ...formData, dimensions: e.target.value })
                }
              />
            </div>
          </div>
          <div className="form-actions">
            <button className="btn" onClick={handleAddPiece} disabled={loading}>
              <Plus size={18} />
              {loading ? "جاري الإضافة..." : "إضافة"}
            </button>
            <button
              className="btn btn-secondary"
              onClick={() => setShowAddForm(false)}
            >
              إلغاء
            </button>
          </div>
        </div>
      )}

      {report && (
        <div className="sustainability-report card fade-in">
          <h3>
            <Leaf size={20} /> تقرير الاستدامة
          </h3>
          <div className="report-stats">
            <div className="report-stat">
              <span className="stat-value">{report.totalPieces}</span>
              <span className="stat-label">إجمالي القطع</span>
            </div>
            <div className="report-stat">
              <span className="stat-value" style={{ color: "#4ade80" }}>
                {report.reusablePercentage}%
              </span>
              <span className="stat-label">قابل لإعادة الاستخدام</span>
            </div>
            <div className="report-stat">
              <span className="stat-value" style={{ color: "#fbbf24" }}>
                ${report.estimatedSavings}
              </span>
              <span className="stat-label">توفير متوقع</span>
            </div>
          </div>
          <div className="environmental-impact">
            <Recycle size={18} />
            <span>{report.environmentalImpact}</span>
          </div>
        </div>
      )}

      <div className="pieces-grid grid grid-4">
        {pieces.length === 0 ? (
          <div className="empty-state card">
            <Boxes size={48} />
            <h3>لا توجد قطع</h3>
            <p>ابدأ بإضافة قطع ديكور جديدة</p>
          </div>
        ) : (
          pieces.map((piece) => (
            <div key={piece.id} className="piece-card card">
              <div className="piece-category">{piece.category}</div>
              <h4>{piece.nameAr}</h4>
              <p className="piece-name-en">{piece.name}</p>
              <div className="piece-footer">
                <span
                  className="condition-badge"
                  style={{
                    background: `${getConditionColor(piece.condition)}20`,
                    color: getConditionColor(piece.condition),
                  }}
                >
                  {getConditionLabel(piece.condition)}
                </span>
                <span className="reusability-score">
                  <Recycle size={14} />
                  {piece.reusabilityScore}%
                </span>
              </div>
            </div>
          ))
        )}
      </div>
    </div>
  );
}

export default Sets;

import { Play, Loader2 } from "lucide-react";
import { useState, useEffect } from "react";

import { toolConfigs, ToolId, ToolInput } from "../core/toolConfigs";
import "./Tools.css";
import { artDirectorApiPath } from "../lib/api-client";

interface Plugin {
  id: string;
  name: string;
  nameAr: string;
  category: string;
  version: string;
}

function Tools() {
  const [plugins, setPlugins] = useState<Plugin[]>([]);
  const [selectedTool, setSelectedTool] = useState<ToolId | null>(null);
  const [formData, setFormData] = useState<Record<string, string>>({});
  const [result, setResult] = useState<any>(null);
  const [loading, setLoading] = useState(false);

  useEffect(() => {
    fetch(artDirectorApiPath("/plugins"))
      .then((res) => res.json())
      .then((data) => setPlugins(data.plugins ?? []))
      .catch(console.error);
  }, []);

  const handleExecute = async () => {
    if (!selectedTool) return;

    const config = toolConfigs[selectedTool];
    if (!config) return;

    setLoading(true);
    setResult(null);

    try {
      const response = await fetch(
        config.endpoint.startsWith("/api/")
          ? artDirectorApiPath(config.endpoint.replace(/^\/api/, ""))
          : config.endpoint,
        {
          method: "POST",
          headers: { "Content-Type": "application/json" },
          body: JSON.stringify(formData),
        }
      );
      const data = await response.json();
      setResult(data);
    } catch {
      setResult({ success: false, error: "حدث خطأ في الاتصال" });
    }
    setLoading(false);
  };

  const renderInput = (input: ToolInput) => {
    if (input.type === "select") {
      return (
        <select
          className="input"
          value={formData[input.name] ?? ""}
          onChange={(e) =>
            setFormData({ ...formData, [input.name]: e.target.value })
          }
        >
          <option value="">اختر...</option>
          {input.options?.map((opt: any) => (
            <option key={opt.value} value={opt.value}>
              {opt.label}
            </option>
          ))}
        </select>
      );
    }
    if (input.type === "textarea") {
      return (
        <textarea
          className="input"
          placeholder={input.placeholder}
          value={formData[input.name] ?? ""}
          onChange={(e) =>
            setFormData({ ...formData, [input.name]: e.target.value })
          }
        />
      );
    }
    return (
      <input
        type={input.type}
        className="input"
        placeholder={input.placeholder}
        value={formData[input.name] ?? ""}
        onChange={(e) =>
          setFormData({ ...formData, [input.name]: e.target.value })
        }
      />
    );
  };

  return (
    <div className="tools-page fade-in">
      <header className="page-header">
        <Play size={32} className="header-icon" />
        <div>
          <h1>جميع الأدوات</h1>
          <p>تشغيل واختبار جميع أدوات CineArchitect الـ 16</p>
        </div>
      </header>

      <div className="tools-layout">
        <aside className="tools-sidebar">
          <h3>الأدوات المتاحة ({plugins.length})</h3>
          <div className="tools-list">
            {plugins.map((plugin) => {
              const config = toolConfigs[plugin.id];
              const Icon = config?.icon ?? Play;
              const color = config?.color ?? "#e94560";

              return (
                <button
                  key={plugin.id}
                  className={`tool-item ${selectedTool === plugin.id ? "active" : ""}`}
                  onClick={() => {
                    setSelectedTool(plugin.id);
                    setFormData({});
                    setResult(null);
                  }}
                  style={{ "--tool-color": color } as any}
                >
                  <Icon size={20} style={{ color }} />
                  <div className="tool-info">
                    <span className="tool-name-ar">{plugin.nameAr}</span>
                    <span className="tool-category">{plugin.category}</span>
                  </div>
                </button>
              );
            })}
          </div>
        </aside>

        <main className="tools-main">
          {!selectedTool ? (
            <div className="no-tool-selected">
              <Play size={64} />
              <h2>اختر أداة للبدء</h2>
              <p>اختر أداة من القائمة الجانبية لتشغيلها</p>
            </div>
          ) : (
            <div className="tool-workspace">
              <div className="tool-header">
                {(() => {
                  const plugin = plugins.find((p) => p.id === selectedTool);
                  const config = toolConfigs[selectedTool];
                  const Icon = config?.icon ?? Play;
                  return (
                    <>
                      <Icon size={32} style={{ color: config?.color }} />
                      <div>
                        <h2>{plugin?.nameAr}</h2>
                        <p>{plugin?.name}</p>
                      </div>
                    </>
                  );
                })()}
              </div>

              <div className="tool-form card">
                <h3>المدخلات</h3>
                <div className="form-grid">
                  {toolConfigs[selectedTool]?.inputs.map((input) => (
                    <div key={input.name} className="form-group">
                      <label>{input.label}</label>
                      {renderInput(input)}
                    </div>
                  ))}
                </div>
                <button
                  className="btn execute-btn"
                  onClick={handleExecute}
                  disabled={loading}
                >
                  {loading ? (
                    <>
                      <Loader2 size={18} className="spinner" />
                      جاري التنفيذ...
                    </>
                  ) : (
                    <>
                      <Play size={18} />
                      تنفيذ
                    </>
                  )}
                </button>
              </div>

              {result && (
                <div className="tool-result card fade-in">
                  <h3>النتيجة</h3>
                  <div
                    className={`result-status ${result.success ? "success" : "error"}`}
                  >
                    {result.success ? "تم بنجاح" : "حدث خطأ"}
                  </div>
                  <pre className="result-json">
                    {JSON.stringify(result, null, 2)}
                  </pre>
                </div>
              )}
            </div>
          )}
        </main>
      </div>
    </div>
  );
}

export default Tools;

