// CineArchitect AI - Mixed Reality Pre-visualization Studio
// استوديو التصور المسبق بالواقع المختلط

import { v4 as uuidv4 } from "uuid";

import { definedProps } from "@/lib/defined-props";

import { Plugin, PluginInput, PluginOutput } from "../../types";

interface XRScene {
  id: string;
  name: string;
  description: string;
  environment: "indoor" | "outdoor" | "studio" | "virtual";
  dimensions: { width: number; height: number; depth: number };
  objects: XRObject[];
  cameras: VirtualCamera[];
  lighting: XRLighting;
  createdAt: Date;
  updatedAt: Date;
}

interface XRObject {
  id: string;
  name: string;
  type: "prop" | "set-piece" | "character" | "vehicle" | "environment";
  position: Vector3D;
  rotation: Vector3D;
  scale: Vector3D;
  model3D?: string;
  material?: string;
  isInteractive: boolean;
}

interface VirtualCamera {
  id: string;
  name: string;
  type: "main" | "secondary" | "tracking" | "crane" | "steadicam" | "drone";
  position: Vector3D;
  target: Vector3D;
  fov: number;
  lensLength: number;
  aspectRatio: string;
  movement?: CameraMovement;
}

interface CameraMovement {
  type:
    | "static"
    | "pan"
    | "tilt"
    | "dolly"
    | "track"
    | "crane"
    | "orbit"
    | "follow";
  startPosition: Vector3D;
  endPosition: Vector3D;
  duration: number;
  easing: "linear" | "ease-in" | "ease-out" | "ease-in-out";
}

interface XRLighting {
  ambient: { color: string; intensity: number };
  directional: {
    id: string;
    color: string;
    intensity: number;
    position: Vector3D;
    target: Vector3D;
  }[];
  pointLights: {
    id: string;
    color: string;
    intensity: number;
    position: Vector3D;
    radius: number;
  }[];
  hdriEnvironment?: string;
}

interface Vector3D {
  x: number;
  y: number;
  z: number;
}

interface XRDevice {
  type: "vr-headset" | "ar-glasses" | "mr-headset" | "mobile-ar" | "desktop";
  name: string;
  capabilities: string[];
  resolution: { width: number; height: number };
  trackingType: "3dof" | "6dof" | "inside-out" | "outside-in";
}

const scenes = new Map<string, XRScene>();

const supportedDevices: XRDevice[] = [
  {
    type: "vr-headset",
    name: "Meta Quest Pro",
    capabilities: [
      "6dof-tracking",
      "hand-tracking",
      "passthrough",
      "eye-tracking",
    ],
    resolution: { width: 1800, height: 1920 },
    trackingType: "inside-out",
  },
  {
    type: "mr-headset",
    name: "Apple Vision Pro",
    capabilities: [
      "mixed-reality",
      "hand-tracking",
      "eye-tracking",
      "spatial-audio",
    ],
    resolution: { width: 3660, height: 3200 },
    trackingType: "inside-out",
  },
  {
    type: "ar-glasses",
    name: "HoloLens 2",
    capabilities: ["hand-tracking", "spatial-mapping", "voice-control"],
    resolution: { width: 2048, height: 1080 },
    trackingType: "inside-out",
  },
  {
    type: "mobile-ar",
    name: "ARKit/ARCore Device",
    capabilities: ["plane-detection", "light-estimation", "face-tracking"],
    resolution: { width: 1920, height: 1080 },
    trackingType: "6dof",
  },
];

export class MRPrevizStudio implements Plugin {
  id = "mr-previz-studio";
  name = "Mixed Reality Pre-visualization Studio";
  nameAr = "استوديو التصور المسبق بالواقع المختلط";
  version = "1.0.0";
  description =
    "Platform combining VR/AR/MR for comprehensive pre-visualization";
  descriptionAr = "منصة تجمع بين VR/AR/MR للتصور الشامل";
  category = "xr-immersive" as const;

  async initialize(): Promise<void> {
    console.log(`[${this.name}] Initialized with XR capabilities`);
  }

  async execute(input: PluginInput): Promise<PluginOutput> {
    switch (input.type) {
      case "create-scene":
        return this.createScene(input.data as any);
      case "add-object":
        return this.addObject(input.data as any);
      case "setup-camera":
        return this.setupCamera(input.data as any);
      case "simulate-movement":
        return this.simulateCameraMovement(input.data as any);
      case "configure-lighting":
        return this.configureLighting(input.data as any);
      case "export-scene":
        return this.exportScene(input.data as any);
      case "get-devices":
        return this.getSupportedDevices();
      case "ar-preview":
        return this.generateARPreview(input.data as any);
      case "vr-walkthrough":
        return this.generateVRWalkthrough(input.data as any);
      case "list-scenes":
        return this.listScenes();
      default:
        return { success: false, error: `Unknown operation: ${input.type}` };
    }
  }

  private async createScene(data: {
    name: string;
    description: string;
    environment: "indoor" | "outdoor" | "studio" | "virtual";
    dimensions: { width: number; height: number; depth: number };
  }): Promise<PluginOutput> {
    const scene: XRScene = {
      id: uuidv4(),
      name: data.name,
      description: data.description,
      environment: data.environment,
      dimensions: data.dimensions,
      objects: [],
      cameras: [
        {
          id: uuidv4(),
          name: "Main Camera",
          type: "main",
          position: { x: 0, y: 1.7, z: 5 },
          target: { x: 0, y: 1, z: 0 },
          fov: 50,
          lensLength: 35,
          aspectRatio: "16:9",
        },
      ],
      lighting: {
        ambient: { color: "#ffffff", intensity: 0.3 },
        directional: [
          {
            id: uuidv4(),
            color: "#fff5e6",
            intensity: 1.0,
            position: { x: 10, y: 10, z: 5 },
            target: { x: 0, y: 0, z: 0 },
          },
        ],
        pointLights: [],
      },
      createdAt: new Date(),
      updatedAt: new Date(),
    };

    scenes.set(scene.id, scene);

    return {
      success: true,
      data: {
        scene: scene as unknown as Record<string, unknown>,
        message: "XR scene created successfully",
        messageAr: "تم إنشاء مشهد الواقع الممتد بنجاح",
        capabilities: {
          vrSupported: true,
          arSupported: true,
          mrSupported: true,
          realTimeRendering: true,
          cameraSimulation: true,
        },
      },
    };
  }

  private async addObject(data: {
    sceneId: string;
    object: Partial<XRObject>;
  }): Promise<PluginOutput> {
    const scene = scenes.get(data.sceneId);
    if (!scene) {
      return { success: false, error: "Scene not found" };
    }

    const newObject: XRObject = {
      id: uuidv4(),
      name: data.object.name ?? "New Object",
      type: data.object.type ?? "prop",
      position: data.object.position ?? { x: 0, y: 0, z: 0 },
      rotation: data.object.rotation ?? { x: 0, y: 0, z: 0 },
      scale: data.object.scale ?? { x: 1, y: 1, z: 1 },
      isInteractive: data.object.isInteractive ?? false,
      ...definedProps({
        model3D: data.object.model3D,
        material: data.object.material,
      }),
    };

    scene.objects.push(newObject);
    scene.updatedAt = new Date();

    return {
      success: true,
      data: {
        object: newObject as unknown as Record<string, unknown>,
        sceneObjectCount: scene.objects.length,
        message: "Object added to XR scene",
        messageAr: "تم إضافة العنصر إلى مشهد الواقع الممتد",
      },
    };
  }

  private async setupCamera(data: {
    sceneId: string;
    camera: Partial<VirtualCamera>;
  }): Promise<PluginOutput> {
    const scene = scenes.get(data.sceneId);
    if (!scene) {
      return { success: false, error: "Scene not found" };
    }

    const newCamera: VirtualCamera = {
      id: uuidv4(),
      name: data.camera.name ?? "Camera",
      type: data.camera.type ?? "main",
      position: data.camera.position ?? { x: 0, y: 1.7, z: 5 },
      target: data.camera.target ?? { x: 0, y: 1, z: 0 },
      fov: data.camera.fov ?? 50,
      lensLength: data.camera.lensLength ?? 35,
      aspectRatio: data.camera.aspectRatio ?? "16:9",
      ...definedProps({
        movement: data.camera.movement,
      }),
    };

    scene.cameras.push(newCamera);
    scene.updatedAt = new Date();

    const composition = this.analyzeComposition(newCamera, scene);

    return {
      success: true,
      data: {
        camera: newCamera as unknown as Record<string, unknown>,
        composition,
        previewUrl: `/xr/preview/${scene.id}/${newCamera.id}`,
        message: "Virtual camera configured",
        messageAr: "تم تكوين الكاميرا الافتراضية",
      },
    };
  }

  private analyzeComposition(
    camera: VirtualCamera,
    scene: XRScene
  ): Record<string, unknown> {
    const objectsInFrame = scene.objects.filter((obj) => {
      const distance = Math.sqrt(
        Math.pow(obj.position.x - camera.position.x, 2) +
          Math.pow(obj.position.y - camera.position.y, 2) +
          Math.pow(obj.position.z - camera.position.z, 2)
      );
      return distance < 20;
    });

    return {
      ruleOfThirds: {
        applied: objectsInFrame.length > 0,
        suggestions:
          objectsInFrame.length === 0
            ? ["Add subjects to the scene"]
            : ["Consider positioning key elements at intersection points"],
      },
      depthLayers: {
        foreground: objectsInFrame.filter(
          (o) => this.getDistance(o.position, camera.position) < 3
        ).length,
        midground: objectsInFrame.filter((o) => {
          const d = this.getDistance(o.position, camera.position);
          return d >= 3 && d < 8;
        }).length,
        background: objectsInFrame.filter(
          (o) => this.getDistance(o.position, camera.position) >= 8
        ).length,
      },
      estimatedFps: 60,
      qualityLevel: "high",
    };
  }

  private getDistance(a: Vector3D, b: Vector3D): number {
    return Math.sqrt(
      Math.pow(a.x - b.x, 2) + Math.pow(a.y - b.y, 2) + Math.pow(a.z - b.z, 2)
    );
  }

  private async simulateCameraMovement(data: {
    sceneId: string;
    cameraId: string;
    movement: CameraMovement;
  }): Promise<PluginOutput> {
    const scene = scenes.get(data.sceneId);
    if (!scene) {
      return { success: false, error: "Scene not found" };
    }

    const camera = scene.cameras.find((c) => c.id === data.cameraId);
    if (!camera) {
      return { success: false, error: "Camera not found" };
    }

    camera.movement = data.movement;
    scene.updatedAt = new Date();

    const keyframes = this.generateKeyframes(data.movement);

    return {
      success: true,
      data: {
        movement: data.movement as unknown as Record<string, unknown>,
        keyframes,
        duration: data.movement.duration,
        frameCount: Math.round(data.movement.duration * 24),
        estimatedRenderTime: Math.round(data.movement.duration * 24 * 0.5),
        previewUrl: `/xr/animation/${scene.id}/${camera.id}`,
        message: "Camera movement simulated",
        messageAr: "تم محاكاة حركة الكاميرا",
      },
    };
  }

  private generateKeyframes(movement: CameraMovement): unknown[] {
    const frames = Math.round(movement.duration * 24);
    const keyframes = [];

    for (let i = 0; i <= frames; i += Math.max(1, Math.floor(frames / 10))) {
      const t = i / frames;
      const easedT = this.applyEasing(t, movement.easing);

      keyframes.push({
        frame: i,
        time: i / 24,
        position: {
          x:
            movement.startPosition.x +
            (movement.endPosition.x - movement.startPosition.x) * easedT,
          y:
            movement.startPosition.y +
            (movement.endPosition.y - movement.startPosition.y) * easedT,
          z:
            movement.startPosition.z +
            (movement.endPosition.z - movement.startPosition.z) * easedT,
        },
      });
    }

    return keyframes;
  }

  private applyEasing(t: number, easing: string): number {
    switch (easing) {
      case "ease-in":
        return t * t;
      case "ease-out":
        return t * (2 - t);
      case "ease-in-out":
        return t < 0.5 ? 2 * t * t : -1 + (4 - 2 * t) * t;
      default:
        return t;
    }
  }

  private async configureLighting(data: {
    sceneId: string;
    lighting: Partial<XRLighting>;
  }): Promise<PluginOutput> {
    const scene = scenes.get(data.sceneId);
    if (!scene) {
      return { success: false, error: "Scene not found" };
    }

    if (data.lighting.ambient) {
      scene.lighting.ambient = data.lighting.ambient;
    }
    if (data.lighting.directional) {
      scene.lighting.directional = data.lighting.directional;
    }
    if (data.lighting.pointLights) {
      scene.lighting.pointLights = data.lighting.pointLights;
    }
    if (data.lighting.hdriEnvironment) {
      scene.lighting.hdriEnvironment = data.lighting.hdriEnvironment;
    }

    scene.updatedAt = new Date();

    return {
      success: true,
      data: {
        lighting: scene.lighting as unknown as Record<string, unknown>,
        renderPreview: `/xr/lighting-preview/${scene.id}`,
        message: "XR lighting configured",
        messageAr: "تم تكوين إضاءة الواقع الممتد",
      },
    };
  }

  private async exportScene(data: {
    sceneId: string;
    format: "gltf" | "usdz" | "fbx" | "obj";
    target: "vr" | "ar" | "mr" | "all";
  }): Promise<PluginOutput> {
    const scene = scenes.get(data.sceneId);
    if (!scene) {
      return { success: false, error: "Scene not found" };
    }

    const exportFormats: Record<
      string,
      { extension: string; description: string }
    > = {
      gltf: {
        extension: ".gltf",
        description: "GL Transmission Format - WebXR compatible",
      },
      usdz: {
        extension: ".usdz",
        description: "Universal Scene Description - iOS AR",
      },
      fbx: { extension: ".fbx", description: "Autodesk FBX - Game engines" },
      obj: { extension: ".obj", description: "Wavefront OBJ - Universal 3D" },
    };

    return {
      success: true,
      data: {
        sceneId: scene.id,
        sceneName: scene.name,
        format: data.format,
        formatInfo: exportFormats[data.format],
        target: data.target,
        exportUrl: `/xr/export/${scene.id}/${data.format}`,
        fileSize: "~" + Math.round(scene.objects.length * 2.5 + 5) + " MB",
        includes: {
          objects: scene.objects.length,
          cameras: scene.cameras.length,
          lights:
            scene.lighting.directional.length +
            scene.lighting.pointLights.length,
          animations: scene.cameras.filter((c) => c.movement).length,
        },
        message: `Scene exported as ${data.format.toUpperCase()}`,
        messageAr: `تم تصدير المشهد بتنسيق ${data.format.toUpperCase()}`,
      },
    };
  }

  private async getSupportedDevices(): Promise<PluginOutput> {
    return {
      success: true,
      data: {
        devices: supportedDevices as unknown as Record<string, unknown>[],
        message: "Supported XR devices retrieved",
        messageAr: "تم استرجاع أجهزة الواقع الممتد المدعومة",
      },
    };
  }

  private async generateARPreview(data: {
    sceneId: string;
    targetDevice: string;
  }): Promise<PluginOutput> {
    const scene = scenes.get(data.sceneId);
    if (!scene) {
      return { success: false, error: "Scene not found" };
    }

    return {
      success: true,
      data: {
        sceneId: scene.id,
        arPreviewUrl: `/ar/preview/${scene.id}`,
        qrCode: `data:image/svg+xml,<svg xmlns='http://www.w3.org/2000/svg' viewBox='0 0 100 100'><rect fill='%23000' width='100' height='100'/></svg>`,
        targetDevice: data.targetDevice,
        instructions: {
          en: "Scan the QR code with your AR-enabled device to view the scene in augmented reality",
          ar: "امسح رمز QR بجهازك المزود بتقنية AR لعرض المشهد بالواقع المعزز",
        },
        features: [
          "real-world-placement",
          "scale-adjustment",
          "light-estimation",
          "occlusion",
        ],
        message: "AR preview generated",
        messageAr: "تم توليد معاينة الواقع المعزز",
      },
    };
  }

  private async generateVRWalkthrough(data: {
    sceneId: string;
    waypoints?: Vector3D[];
  }): Promise<PluginOutput> {
    const scene = scenes.get(data.sceneId);
    if (!scene) {
      return { success: false, error: "Scene not found" };
    }

    const waypoints = data.waypoints ?? [
      { x: 0, y: 1.7, z: 5 },
      { x: 3, y: 1.7, z: 3 },
      { x: 0, y: 1.7, z: 0 },
      { x: -3, y: 1.7, z: 3 },
    ];

    return {
      success: true,
      data: {
        sceneId: scene.id,
        vrWalkthroughUrl: `/vr/walkthrough/${scene.id}`,
        waypoints,
        duration: waypoints.length * 5,
        interactionPoints: scene.objects
          .filter((o) => o.isInteractive)
          .map((o) => ({
            objectId: o.id,
            name: o.name,
            position: o.position,
          })),
        features: [
          "teleportation",
          "free-movement",
          "object-inspection",
          "annotations",
        ],
        message: "VR walkthrough generated",
        messageAr: "تم توليد جولة الواقع الافتراضي",
      },
    };
  }

  private async listScenes(): Promise<PluginOutput> {
    const sceneList = Array.from(scenes.values()).map((s) => ({
      id: s.id,
      name: s.name,
      environment: s.environment,
      objectCount: s.objects.length,
      cameraCount: s.cameras.length,
      createdAt: s.createdAt,
      updatedAt: s.updatedAt,
    }));

    return {
      success: true,
      data: {
        scenes: sceneList,
        totalScenes: sceneList.length,
        message: "XR scenes retrieved",
        messageAr: "تم استرجاع مشاهد الواقع الممتد",
      },
    };
  }

  async shutdown(): Promise<void> {
    scenes.clear();
    console.log(`[${this.name}] Shut down`);
  }
}

export const mrPrevizStudio = new MRPrevizStudio();

// CineArchitect AI - Production Readiness Report Prompt Builder
// مُنشئ تقرير جاهزية الإنتاج

import { Plugin, PluginInput, PluginOutput } from "../../types";

interface RepositoryAnalysisData {
  languages?: string[];
  hasPackageJson?: boolean;
  hasRequirementsTxt?: boolean;
  hasPyprojectToml?: boolean;
  hasDockerfile?: boolean;
  hasTests?: boolean;
  hasCI?: boolean;
  hasReadme?: boolean;
  hasGitignore?: boolean;
  fileStructure?: string[];
  packageJsonContent?: string | null;
  readmeContent?: string | null;
  requirementsContent?: string | null;
}

interface ProductionReadinessPromptInput {
  owner: string;
  repo: string;
  analysisData: RepositoryAnalysisData;
}

const MAX_PACKAGE_JSON_CHARS = 2000;
const MAX_README_CHARS = 2000;
const MAX_REQUIREMENTS_CHARS = 1000;

const formatFileSection = (
  title: string,
  content: string,
  maxChars: number
): string =>
  `\n────────────────────────────────────────────────────────────────────────────────\n${title}\n────────────────────────────────────────────────────────────────────────────────\n${content.substring(0, maxChars)}\n`;

const buildPrompt = ({
  owner,
  repo,
  analysisData,
}: ProductionReadinessPromptInput): string => {
  const fileStructure = analysisData.fileStructure?.length
    ? analysisData.fileStructure.join("\n")
    : "غير متوفر";

  const packageJsonSection = analysisData.packageJsonContent
    ? formatFileSection(
        "📦 محتوى package.json",
        analysisData.packageJsonContent,
        MAX_PACKAGE_JSON_CHARS
      )
    : "";

  const readmeSection = analysisData.readmeContent
    ? formatFileSection(
        "📄 محتوى README",
        analysisData.readmeContent,
        MAX_README_CHARS
      )
    : "";

  const requirementsSection = analysisData.requirementsContent
    ? formatFileSection(
        "📋 محتوى requirements.txt",
        analysisData.requirementsContent,
        MAX_REQUIREMENTS_CHARS
      )
    : "";

  return `أنت خبير هندسي متخصص في تقييم جاهزية التطبيقات للنشر في بيئات الإنتاج. مهمتك هي إجراء مراجعة هندسية شاملة وكتابة تقرير جاهزية إنتاج (Production Readiness Report) احترافي لتطبيق ويب تفاعلي.

════════════════════════════════════════════════════════════════════════════════
 اول مهمة  تقوم بتحليل  

البنية التقنية:
- package.json: ${analysisData.hasPackageJson ? "✓ موجود" : "✗ غير موجود"}
- requirements.txt: ${analysisData.hasRequirementsTxt ? "✓ موجود" : "✗ غير موجود"}
- pyproject.toml: ${analysisData.hasPyprojectToml ? "✓ موجود" : "✗ غير موجود"}
- Dockerfile: ${analysisData.hasDockerfile ? "✓ موجود" : "✗ غير موجود"}

ضمان الجودة:
- اختبارات آلية: ${analysisData.hasTests ? "✓ موجودة" : "✗ غير موجودة"}
- CI/CD Pipeline: ${analysisData.hasCI ? "✓ موجود" : "✗ غير موجود"}

التوثيق:
- README: ${analysisData.hasReadme ? "✓ موجود" : "✗ غير موجود"}
- .gitignore: ${analysisData.hasGitignore ? "✓ موجود" : "✗ غير موجود"}

هيكل الملفات:
${fileStructure}
${packageJsonSection}${readmeSection}${requirementsSection}
════════════════════════════════════════════════════════════════════════════════
🎯 المجالات الهندسية للتقييم
════════════════════════════════════════════════════════════════════════════════

قم بتقييم التطبيق عبر المجالات الهندسية العشرة التالية:

1️⃣ **الوظائف الأساسية (Core Functionality)**
   معايير التقييم:
   • اكتمال الميزات الأساسية المطلوبة
   • استقرار الوظائف وخلوها من الأخطاء الحرجة
   • تغطية حالات الاستخدام الرئيسية
   • معالجة الأخطاء والحالات الاستثنائية

2️⃣ **الأداء (Performance)**
   معايير التقييم:
   • زمن تحميل الصفحة الأولى (< 3 ثواني)
   • زمن الاستجابة للعمليات (< 200ms)
   • كفاءة استخدام الموارد (Memory/CPU)
   • قابلية التوسع الأفقي والعمودي
   • تحسين الصور والأصول الثابتة
   • استراتيجيات التخزين المؤقت (Caching)

3️⃣ **الأمان (Security)**
   معايير التقييم:
   • آليات المصادقة والتفويض (Authentication/Authorization)
   • حماية من الثغرات الشائعة (OWASP Top 10)
   • تشفير البيانات الحساسة (في الحركة وفي الراحة)
   • إدارة الأسرار والمفاتيح (Secrets Management)
   • حماية من CSRF, XSS, SQL Injection
   • سياسات CORS و Content Security Policy
   • تحديثات أمنية للمكتبات والاعتماديات

4️⃣ **البنية التحتية (Infrastructure)**
   معايير التقييم:
   • توفر بيئات متعددة (Dev/Staging/Production)
   • آليات النشر الآلي (Deployment Automation)
   • إدارة الإعدادات البيئية (Environment Configuration)
   • استراتيجيات التوسع (Scaling Strategy)
   • التوافرية العالية (High Availability)
   • استراتيجية النسخ الاحتياطي التلقائي

5️⃣ **المراقبة والسجلات (Monitoring & Logging)**
   معايير التقييم:
   • نظام تسجيل الأحداث الشامل (Structured Logging)
   • مراقبة الأداء والموارد (APM)
   • تنبيهات الأخطاء والمشاكل الحرجة (Alerting)
   • تتبع الأخطاء (Error Tracking)
   • لوحات القياس والمقاييس (Metrics Dashboard)

6️⃣ **النسخ الاحتياطي والاستعادة (Backup & Recovery)**
   معايير التقييم:
   • استراتيجية النسخ الاحتياطي الآلي
   • نقطة استعادة الهدف (RPO - Recovery Point Objective)
   • وقت استعادة الهدف (RTO - Recovery Time Objective)
   • خطة التعافي من الكوارث (Disaster Recovery Plan)
   • اختبار دوري لعمليات الاستعادة

7️⃣ **التوثيق (Documentation)**
   معايير التقييم:
   • README شامل يوضح الغرض والاستخدام
   • توثيق التثبيت والإعداد
   • توثيق API (إن وجد)
   • توثيق البنية المعمارية
   • توثيق العمليات التشغيلية (Runbooks)
   • دليل المساهمة (Contributing Guide)

8️⃣ **الاختبار (Testing)**
   معايير التقييم:
   • اختبارات الوحدة (Unit Tests) - تغطية > 70%
   • اختبارات التكامل (Integration Tests)
   • اختبارات من النهاية للنهاية (E2E Tests)
   • اختبارات الأداء والحمل (Load/Stress Tests)
   • اختبارات الأمان (Security Tests)
   • اختبارات قبول المستخدم (UAT)

9️⃣ **التوافق (Compatibility)**
   معايير التقييم:
   • دعم المتصفحات الرئيسية (Chrome, Firefox, Safari, Edge)
   • التوافق مع الأجهزة المختلفة (Desktop, Mobile, Tablet)
   • التصميم المتجاوب (Responsive Design)
   • إمكانية الوصول (Accessibility - WCAG 2.1)
   • دعم اللغات المتعددة (إن كان مطلوباً)

🔟 **الامتثال (Compliance)**
   معايير التقييم:
   • الامتثال لـ GDPR (إن كان التطبيق يخدم الاتحاد الأوروبي)
   • سياسات الخصوصية وشروط الاستخدام
   • الامتثال للمعايير الصناعية (ISO, SOC 2, إلخ)
   • متطلبات الترخيص (License Compliance)
   • لوائح حماية البيانات المحلية

════════════════════════════════════════════════════════════════════════════════
📊 منهجية التقييم
════════════════════════════════════════════════════════════════════════════════

نظام التقييم لكل مجال:
- **ready** (جاهز): المجال يلبي جميع المعايير الأساسية ومُجهّز للإنتاج
- **conditional** (جاهز بشروط): المجال يحتاج تحسينات طفيفة أو متوسطة، لكن ليست حرجة
- **not-ready** (غير جاهز): المجال يعاني من نقص حرج يمنع النشر
- **unknown** (غير محدد): معلومات غير كافية للتقييم

نظام الأولويات للتوصيات:
- **P0 (حرج)**: يجب معالجته قبل النشر - يمنع النشر
- **P1 (عالي)**: يجب معالجته في أقرب وقت - يؤثر على الاستقرار أو الأمان
- **P2 (متوسط)**: يُنصح بمعالجته قريباً - يحسن الجودة
- **P3 (منخفض)**: يمكن معالجته لاحقاً - تحسينات اختيارية

════════════════════════════════════════════════════════════════════════════════
✍️ إرشادات كتابة التقرير
════════════════════════════════════════════════════════════════════════════════

1. **التحليل الأولي**:
   - قبل كتابة التقرير، حلل المعلومات المتوفرة بعمق
   - حدد الأنماط والعلاقات بين المجالات المختلفة
   - ابحث عن الفجوات المعلوماتية الحرجة
   - استنتج معلومات ضمنية من البيانات المتاحة

2. **الدقة والموضوعية**:
   - قدم تقييماً موضوعياً مبنياً على الأدلة
   - اذكر أي افتراضات قمت بها بوضوح
   - لا تقدم تقييمات مبنية على تخمينات إذا كانت البيانات غير كافية
   - استخدم "unknown" عندما لا تتوفر معلومات كافية

3. **القابلية للتنفيذ**:
   - اجعل كل توصية محددة وقابلة للتنفيذ
   - أضف الأولوية لكل توصية
   - اقترح خطوات عملية واضحة

4. **الشمولية**:
   - غطِ جميع المجالات العشرة حتى لو كانت المعلومات محدودة
   - اربط المجالات ببعضها عند الحاجة
   - حدد التأثيرات المتداخلة بين المجالات

════════════════════════════════════════════════════════════════════════════════
📤 هيكل الرد المطلوب (JSON)
════════════════════════════════════════════════════════════════════════════════

يجب أن يكون الرد بصيغة JSON التالية بالضبط (كل النصوص بالعربية):

