              <SliderNumberInput
                label="فتحة العدسة"
                icon={Aperture}
                unit="f"
                value={aperture}
                min={1.4}
                max={22}
                step={0.1}
                formatValue={(value) => value.toFixed(1)}
                onChange={setAperture}
