  aperture: number;
  distortion: number;
  showBokeh: boolean;
  isAnamorphic: boolean;
  selectedPreset: string | null;
}

interface LensSimulatorToolProps {
  className?: string;
  onLensChange?: (lens: {
    focalLength: number;
    aperture: number;
    distortion: number;
  }) => void;
}

const DEFAULT_LENS_SETTINGS: LensSettings = {
