/**
 * @fileoverview Hook مخصص لإدارة حالة استوديو التصوير السينمائي
 *
 * هذا الـ Hook يوفر واجهة موحدة لإدارة جميع حالات الاستوديو
 * بما في ذلك المرحلة الحالية، الأداة النشطة، والمود البصري.
 * يستخدم useReducer للتعامل مع الحالات المعقدة بشكل أفضل.
 *
 * @module cinematography-studio/hooks/useCinematographyStudio
 */

"use client";

import { useReducer, useCallback, useEffect, useMemo, useRef } from "react";

import { publishDiagnostics } from "../lib/diagnostics-bus";
import {
  clearSession as clearPersistedSession,
  patchSession,
  readSession,
} from "../lib/session-storage";
import {
  TAB_VALUE_BY_PHASE,
  PHASE_BY_TAB,
  isValidTabValue,
  isValidVisualMood,
} from "../types";

import type {
  Phase,
  TabValue,
  VisualMood,
  ViewMode,
  CineStudioState,
} from "../types";

// ============================================
// أنواع الإجراءات
// ============================================

/**
 * أنواع الإجراءات المتاحة لتحديث حالة الاستوديو
 */
type StudioAction =
  | { type: "SET_PHASE"; payload: Phase }
  | { type: "SET_VISUAL_MOOD"; payload: VisualMood }
  | { type: "SET_ACTIVE_TOOL"; payload: string | null }
  | { type: "SET_ACTIVE_VIEW"; payload: ViewMode }
  | { type: "RESET_TOOL" }
  | { type: "NAVIGATE_TO_PHASE"; payload: { phase: Phase; view: ViewMode } };

// ============================================
// الحالة الابتدائية
// ============================================

/**
 * الحالة الابتدائية للاستوديو
 * تُستخدم عند تهيئة الـ Hook لأول مرة
 */
const initialState: CineStudioState = {
  currentPhase: "pre",
  visualMood: "noir",
  activeTool: null,
  activeView: "dashboard",
};

// ============================================
// المخفض (Reducer)
// ============================================

/**
 * مخفض حالة الاستوديو
 * يتعامل مع جميع الإجراءات ويعيد الحالة الجديدة
 *
 * @param state - الحالة الحالية
 * @param action - الإجراء المراد تنفيذه
 * @returns الحالة الجديدة بعد تطبيق الإجراء
 */
function studioReducer(
  state: CineStudioState,
  action: StudioAction
): CineStudioState {
  switch (action.type) {
    case "SET_PHASE":
      return {
        ...state,
        currentPhase: action.payload,
      };

    case "SET_VISUAL_MOOD":
      return {
        ...state,
        visualMood: action.payload,
      };

    case "SET_ACTIVE_TOOL":
      return {
        ...state,
        activeTool: action.payload,
      };

    case "SET_ACTIVE_VIEW":
      return {
        ...state,
        activeView: action.payload,
      };

    case "RESET_TOOL":
      return {
        ...state,
        activeTool: null,
      };

    case "NAVIGATE_TO_PHASE":
      return {
        ...state,
        currentPhase: action.payload.phase,
        activeView: action.payload.view,
      };

    default:
      return state;
  }
}

// ============================================
// الـ Hook الرئيسي
// ============================================

/**
 * Hook مخصص لإدارة حالة استوديو التصوير السينمائي
 *
 * يوفر هذا الـ Hook:
 * - إدارة مركزية لحالة الاستوديو
 * - دوال محسنة للأداء لتحديث الحالة
 * - قيم محسوبة مشتقة من الحالة
 * - تحقق من صحة البيانات قبل التحديث
 *
 * @example
 * ```tsx
 * const {
 *   state,
 *   setPhase,
 *   setVisualMood,
 *   openTool,
 *   closeTool,
 *   currentTabValue
 * } = useCinematographyStudio();
 * ```
 *
 * @returns كائن يحتوي على الحالة والدوال المساعدة
 */
export function useCinematographyStudio() {
  const [state, dispatch] = useReducer(studioReducer, initialState);
  const hydratedFromStorage = useRef(false);
  const studioRenderCount = useRef(0);
  studioRenderCount.current += 1;

  // نشر عدّاد إعادة التركيب لطبقة التشخيص.
  useEffect(() => {
    publishDiagnostics({
      slice: "renderCount",
      data: { studio: studioRenderCount.current },
    });
  });

  // استعادة الحالة من localStorage على أول mount فقط — مرة واحدة لتجنب
  // إعادة الكتابة فوق تنقل المستخدم اللاحق.
  useEffect(() => {
    if (hydratedFromStorage.current) {
      return;
    }
    hydratedFromStorage.current = true;
    const persisted = readSession();
    if (!persisted) {
      return;
    }
    if (persisted.phase) {
      dispatch({ type: "SET_PHASE", payload: persisted.phase });
    }
    if (persisted.mood) {
      dispatch({ type: "SET_VISUAL_MOOD", payload: persisted.mood });
    }
    if (persisted.view) {
      dispatch({ type: "SET_ACTIVE_VIEW", payload: persisted.view });
    }
    if (persisted.activeTool !== undefined) {
      dispatch({ type: "SET_ACTIVE_TOOL", payload: persisted.activeTool });
    }
  }, []);

  // حفظ الحالة عند كل تغيير (بعد أول هيدرة فقط لتجنب الكتابة بقيم افتراضية فوق
  // القيم المحفوظة قبل قراءتها).
  useEffect(() => {
    if (!hydratedFromStorage.current) {
      return;
    }
    patchSession({
      phase: state.currentPhase,
      mood: state.visualMood,
      view: state.activeView,
      activeTool: state.activeTool,
    });
  }, [state.currentPhase, state.visualMood, state.activeView, state.activeTool]);

  // ============================================
  // دوال تحديث الحالة (محسنة للأداء)
  // ============================================

  /**
   * تعيين مرحلة الإنتاج الحالية
   *
   * @param phase - المرحلة الجديدة
   */
  const setPhase = useCallback((phase: Phase) => {
    dispatch({ type: "SET_PHASE", payload: phase });
  }, []);

  /**
   * تعيين المود البصري للمشروع
   *
   * @param mood - المود البصري الجديد
   */
  const setVisualMood = useCallback((mood: string) => {
    if (isValidVisualMood(mood)) {
      dispatch({ type: "SET_VISUAL_MOOD", payload: mood });
    }
  }, []);

  /**
   * فتح أداة محددة
   *
   * @param toolId - معرف الأداة
   */
  const openTool = useCallback((toolId: string) => {
    dispatch({ type: "SET_ACTIVE_TOOL", payload: toolId });
  }, []);

  /**
   * إغلاق الأداة الحالية والعودة للوحة التحكم
   */
  const closeTool = useCallback(() => {
    dispatch({ type: "RESET_TOOL" });
  }, []);

  /**
   * تغيير طريقة العرض
   *
   * @param view - طريقة العرض الجديدة
   */
  const setActiveView = useCallback((view: ViewMode) => {
    dispatch({ type: "SET_ACTIVE_VIEW", payload: view });
  }, []);

  /**
   * الانتقال إلى مرحلة محددة مع تغيير العرض
   *
   * @param phase - المرحلة المراد الانتقال إليها
   */
  const navigateToPhase = useCallback((phase: Phase) => {
    dispatch({
      type: "NAVIGATE_TO_PHASE",
      payload: { phase, view: "phases" },
    });
  }, []);

  /**
   * معالجة تغيير علامة التبويب
   *
   * @param value - قيمة علامة التبويب الجديدة
   */
  const handleTabChange = useCallback((value: string) => {
    if (isValidTabValue(value)) {
      const phase = PHASE_BY_TAB[value];
      dispatch({ type: "SET_PHASE", payload: phase });
    }
  }, []);

  /**
   * يمسح جلسة الاستوديو المحفوظة محليًا. لا يُعيد ضبط الحالة الحية،
   * لكنه يضمن ألا تعود الحالة القديمة بعد إعادة التحميل.
   */
  const clearStudioSession = useCallback(() => {
    clearPersistedSession();
  }, []);

  // ============================================
  // قيم محسوبة (مشتقة من الحالة)
  // ============================================

  /**
   * قيمة علامة التبويب الحالية بناءً على المرحلة
   */
  const currentTabValue = useMemo((): TabValue => {
    return TAB_VALUE_BY_PHASE[state.currentPhase];
  }, [state.currentPhase]);

  /**
   * التحقق من وجود أداة نشطة
   */
  const hasActiveTool = useMemo((): boolean => {
    return state.activeTool !== null;
  }, [state.activeTool]);

  /**
   * التحقق من كون العرض الحالي هو لوحة التحكم
   */
  const isDashboardView = useMemo((): boolean => {
    return state.activeView === "dashboard";
  }, [state.activeView]);

  /**
   * التحقق من كون العرض الحالي هو المراحل
   */
  const isPhasesView = useMemo((): boolean => {
    return state.activeView === "phases";
  }, [state.activeView]);

  // ============================================
  // القيمة المُرجعة
  // ============================================

  return {
    // الحالة الحالية
    state,

    // خصائص مباشرة من الحالة
    currentPhase: state.currentPhase,
    visualMood: state.visualMood,
    activeTool: state.activeTool,
    activeView: state.activeView,

    // دوال تحديث الحالة
    setPhase,
    setVisualMood,
    openTool,
    closeTool,
    setActiveView,
    navigateToPhase,
    handleTabChange,
    clearStudioSession,

    // قيم محسوبة
    currentTabValue,
    hasActiveTool,
    isDashboardView,
    isPhasesView,
  };
}

export default useCinematographyStudio;

/**
 * خطاف موحد لإدارة إدخال الوسائط لمسارات التحليل السينمائي.
 *
 * يغطي:
 * - اختيار الصور والفيديو.
 * - استخراج إطار مرجعي من الفيديو.
 * - تشغيل الكاميرا والتقاط إطار فعلي.
 * - إدارة حالات الصلاحيات والبدائل.
 */

"use client";

import { useCallback, useEffect, useMemo, useRef, useState } from "react";

import { logger } from "@/lib/ai/utils/logger";

import { cinematographyInputConfig } from "../lib/cinematography-config";
import { publishDiagnostics } from "../lib/diagnostics-bus";
import {
  captureFrameFromVideoElement,
  extractFrameFromVideoFile,
  isImageFile,
  isVideoFile,
  revokeObjectUrlSafely,
  validateMediaFile,
} from "../lib/media-input";

export type MediaInputMode = "image" | "video" | "camera";
export type CameraPermissionState =
  | "idle"
  | "requesting"
  | "granted"
  | "denied"
  | "unsupported"
  | "no-device"
  | "error";

export interface MediaInputPipelineState {
  mode: MediaInputMode;
  previewUrl: string | null;
  previewType: "image" | "video" | "camera" | null;
  selectedFile: File | null;
  analysisFile: File | null;
  isPreparing: boolean;
  error: string | null;
  cameraPermission: CameraPermissionState;
}

export interface MediaInputPipeline {
  state: MediaInputPipelineState;
  cameraVideoRef: React.RefObject<HTMLVideoElement | null>;
  cameraCanvasRef: React.RefObject<HTMLCanvasElement | null>;
  setMode: (mode: MediaInputMode) => void;
  selectMediaFile: (file: File | null) => Promise<void>;
  requestCamera: () => Promise<void>;
  stopCamera: () => void;
  captureCameraFrame: () => Promise<File | null>;
  clearMedia: () => void;
  canAnalyze: boolean;
}

interface CameraFailure {
  permission: CameraPermissionState;
  message: string;
}

function withCameraRequestTimeout<T>(
  promise: Promise<T>,
  timeoutMs = 4000
): Promise<T> {
  return new Promise<T>((resolve, reject) => {
    const timeoutId = window.setTimeout(() => {
      const error = new Error("Timed out while waiting for camera access.");
      error.name = "TimeoutError";
      reject(error);
    }, timeoutMs);

    promise.then(
      (value) => {
        window.clearTimeout(timeoutId);
        resolve(value);
      },
      (error) => {
        window.clearTimeout(timeoutId);
        reject(error);
      }
    );
  });
}

function createInitialState(mode: MediaInputMode): MediaInputPipelineState {
  return {
    mode,
    previewUrl: null,
    previewType: null,
    selectedFile: null,
    analysisFile: null,
    isPreparing: false,
    error: null,
    cameraPermission: "idle",
  };
}

export function useMediaInputPipeline(
  defaultMode: MediaInputMode = "image"
): MediaInputPipeline {
  const [state, setState] = useState<MediaInputPipelineState>(() =>
    createInitialState(defaultMode)
  );
  const streamRef = useRef<MediaStream | null>(null);
  const previewUrlRef = useRef<string | null>(null);
  const cameraVideoRef = useRef<HTMLVideoElement | null>(null);
  const cameraCanvasRef = useRef<HTMLCanvasElement | null>(null);

  const applyPreview = useCallback(
    (
      nextUrl: string | null,
      nextType: MediaInputPipelineState["previewType"]
    ) => {
      if (previewUrlRef.current && previewUrlRef.current !== nextUrl) {
        revokeObjectUrlSafely(previewUrlRef.current);
      }
      previewUrlRef.current = nextUrl;
      setState((prev) => ({
        ...prev,
        previewUrl: nextUrl,
        previewType: nextType,
      }));
    },
    []
  );

  const stopCamera = useCallback(() => {
    if (streamRef.current) {
      streamRef.current.getTracks().forEach((track) => track.stop());
      streamRef.current = null;
    }

    if (cameraVideoRef.current) {
      cameraVideoRef.current.srcObject = null;
    }

    setState((prev) => ({
      ...prev,
      cameraPermission:
        prev.cameraPermission === "granted" ? "idle" : prev.cameraPermission,
    }));
  }, []);

  const clearSelectionState = useCallback(() => {
    setState((prev) => ({
      ...prev,
      selectedFile: null,
      analysisFile: null,
      isPreparing: false,
      error: null,
    }));
  }, []);

  const setMode = useCallback(
    (mode: MediaInputMode) => {
      stopCamera();
      applyPreview(null, null);
      clearSelectionState();
      setState((prev) => ({
        ...prev,
        mode,
        previewType: null,
        previewUrl: null,
      }));
    },
    [applyPreview, clearSelectionState, stopCamera]
  );

  const setError = useCallback((message: string) => {
    logger.warn("[CinematographyInput] media error", { message });
    setState((prev) => ({
      ...prev,
      error: message,
    }));
  }, []);

  const selectMediaFile = useCallback(
    async (file: File | null) => {
      if (!file) {
        return;
      }

      const fileIsImage = isImageFile(file);
      const fileIsVideo = isVideoFile(file);
      const inferredMode: MediaInputMode = fileIsVideo ? "video" : "image";

      try {
        if (!fileIsImage && !fileIsVideo) {
          throw new Error("صيغة الملف غير مدعومة. استخدم صورة أو فيديو.");
        }

        validateMediaFile(file, inferredMode, cinematographyInputConfig);
        stopCamera();

        const objectUrl = URL.createObjectURL(file);
        applyPreview(objectUrl, inferredMode);

        if (fileIsImage) {
          setState((prev) => ({
            ...prev,
            mode: "image",
            selectedFile: file,
            analysisFile: file,
            isPreparing: false,
            error: null,
          }));
          return;
        }

        setState((prev) => ({
          ...prev,
          mode: "video",
          selectedFile: file,
          analysisFile: null,
          isPreparing: true,
          error: null,
        }));

        const canvas =
          cameraCanvasRef.current ?? document.createElement("canvas");
        const extractedFrame = await extractFrameFromVideoFile(
          file,
          canvas,
          cinematographyInputConfig
        );

        setState((prev) => ({
          ...prev,
          analysisFile: extractedFrame,
          isPreparing: false,
        }));
      } catch (error) {
        const message =
          error instanceof Error ? error.message : "فشل تجهيز الملف المحدد.";
        setError(message);
        setState((prev) => ({
          ...prev,
          isPreparing: false,
          analysisFile: null,
        }));
      }
    },
    [applyPreview, setError, stopCamera]
  );

  const requestCamera = useCallback(async () => {
    if (
      typeof navigator === "undefined" ||
      !navigator.mediaDevices?.getUserMedia
    ) {
      setState((prev) => ({
        ...prev,
        cameraPermission: "unsupported",
        error: "المتصفح الحالي لا يدعم الوصول للكاميرا.",
      }));
      return;
    }

    try {
      stopCamera();
      applyPreview(null, null);
      setState((prev) => ({
        ...prev,
        mode: "camera",
        selectedFile: null,
        analysisFile: null,
        isPreparing: false,
        cameraPermission: "requesting",
        error: null,
        previewType: null,
        previewUrl: null,
      }));

      const stream = await withCameraRequestTimeout(
        navigator.mediaDevices.getUserMedia({
          video: {
            width: { ideal: cinematographyInputConfig.captureWidth },
            height: { ideal: cinematographyInputConfig.captureHeight },
            facingMode: "environment",
          },
          audio: false,
        })
      );

      streamRef.current = stream;
      // ربط أولي إن كان عنصر الفيديو متاحًا الآن. إن لم يكن (شائع لأن الـ video
      // لا يُركَّب إلا عند previewType === "camera") سيلتقطه useEffect أدناه فور تركيبه.
      if (cameraVideoRef.current && cameraVideoRef.current.srcObject !== stream) {
        cameraVideoRef.current.srcObject = stream;
        await cameraVideoRef.current.play().catch(() => undefined);
      }

      applyPreview(null, "camera");
      setState((prev) => ({
        ...prev,
        cameraPermission: "granted",
        error: null,
      }));
    } catch (error) {
      const failure = translateCameraFailure(error);

      logger.error("[CinematographyInput] camera start failed", {
        permission: failure.permission,
        message: failure.message,
      });

      setState((prev) => ({
        ...prev,
        cameraPermission: failure.permission,
        error: failure.message,
      }));
    }
  }, [applyPreview, stopCamera]);

  const captureCameraFrame = useCallback(async (): Promise<File | null> => {
    const video = cameraVideoRef.current;
    const canvas = cameraCanvasRef.current;

    if (!video || !canvas || state.cameraPermission !== "granted") {
      setError("فعّل الكاميرا أولًا قبل التقاط إطار التحليل.");
      return null;
    }

    try {
      const frame = await captureFrameFromVideoElement(
        video,
        canvas,
        cinematographyInputConfig
      );
      const frameUrl = URL.createObjectURL(frame);

      applyPreview(frameUrl, "image");
      setState((prev) => ({
        ...prev,
        mode: "camera",
        selectedFile: frame,
        analysisFile: frame,
        error: null,
      }));

      return frame;
    } catch (error) {
      const message =
        error instanceof Error
          ? error.message
          : "تعذر التقاط إطار من الكاميرا.";
      setError(message);
      return null;
    }
  }, [applyPreview, setError, state.cameraPermission]);

  const clearMedia = useCallback(() => {
    stopCamera();
    applyPreview(null, null);
    setState((prev) => ({
      ...prev,
      selectedFile: null,
      analysisFile: null,
      isPreparing: false,
      error: null,
    }));
  }, [applyPreview, stopCamera]);

  useEffect(() => {
    return () => {
      stopCamera();
      if (previewUrlRef.current) {
        revokeObjectUrlSafely(previewUrlRef.current);
        previewUrlRef.current = null;
      }
    };
  }, [stopCamera]);

  // ربط البث بعنصر الفيديو فور توفره — يُغلق الـ race الذي كان يحدث
  // عندما يصل البث قبل تركيب عنصر الفيديو في DOM (لأن الـ video لا يُركَّب
  // إلا حين previewType === "camera").
  useEffect(() => {
    if (state.cameraPermission !== "granted") {
      return;
    }
    const stream = streamRef.current;
    const video = cameraVideoRef.current;
    if (!stream || !video) {
      return;
    }
    if (video.srcObject !== stream) {
      video.srcObject = stream;
      video.play().catch(() => undefined);
    }
  }, [state.cameraPermission, state.previewType]);

  // نشر حالة الكاميرا لطبقة التشخيص — صفر تكلفة عند تعطيل العلم البيئي.
  useEffect(() => {
    publishDiagnostics({
      slice: "camera",
      data: {
        permission: state.cameraPermission,
        previewType: state.previewType,
        lastFrameAt: state.cameraPermission === "granted" ? Date.now() : null,
      },
    });
  }, [state.cameraPermission, state.previewType]);

  const canAnalyze = useMemo(() => {
    return Boolean(state.analysisFile) && !state.isPreparing;
  }, [state.analysisFile, state.isPreparing]);

  return {
    state,
    cameraVideoRef,
    cameraCanvasRef,
    setMode,
    selectMediaFile,
    requestCamera,
    stopCamera,
    captureCameraFrame,
    clearMedia,
    canAnalyze,
  };
}

export default useMediaInputPipeline;

function translateCameraFailure(error: unknown): CameraFailure {
  const errorName =
    typeof error === "object" &&
    error !== null &&
    "name" in error &&
    typeof error.name === "string"
      ? error.name
      : "";

  if (
    errorName === "NotAllowedError" ||
    errorName === "PermissionDeniedError"
  ) {
    return {
      permission: "denied",
      message: "تم رفض صلاحية الكاميرا. يمكنك المتابعة عبر رفع صورة أو فيديو.",
    };
  }

  if (errorName === "NotFoundError" || errorName === "DevicesNotFoundError") {
    return {
      permission: "no-device",
      message:
        "لا توجد كاميرا متاحة على هذا الجهاز. استخدم رفع صورة أو فيديو كبديل.",
    };
  }

  if (
    errorName === "SecurityError" ||
    errorName === "TypeError" ||
    errorName === "NotSupportedError"
  ) {
    return {
      permission: "unsupported",
      message:
        "المتصفح الحالي لا يدعم الوصول للكاميرا مباشرة. استخدم رفع الملفات بدلًا منها.",
    };
  }

  if (errorName === "TimeoutError") {
    return {
      permission: "unsupported",
      message:
        "المتصفح الحالي لا يدعم الوصول للكاميرا في جلسة التشغيل الحالية. استخدم رفع الملفات بدلًا منها.",
    };
  }

  if (errorName === "NotReadableError" || errorName === "TrackStartError") {
    return {
      permission: "error",
      message:
        "الكاميرا مشغولة أو غير قابلة للقراءة الآن. أغلق أي تطبيق آخر يحجزها ثم أعد المحاولة.",
    };
  }

  return {
    permission: "error",
    message: "تعذر تفعيل الكاميرا. يمكنك استخدام رفع الملفات كبديل.",
  };
}

/**
 * @fileoverview Hook مخصص لإدارة أدوات ما بعد الإنتاج
 *
 * هذا الـ Hook يوفر جميع الوظائف المطلوبة لمرحلة ما بعد الإنتاج
 * بما في ذلك تدريج الألوان، المونتاج، وإعدادات التصدير.
 * يتضمن معالجة الأخطاء والتحقق من صحة البيانات.
 *
 * @module cinematography-studio/hooks/usePostProduction
 */

"use client";

import { useState, useCallback, useMemo } from "react";
import { toast } from "react-hot-toast";

import { createLocalFootageSummary } from "../lib/local-shot-analysis";
import { resolveAnalysisWinner } from "../lib/resolve-analysis-winner";
import { postStudioFormData, postStudioJson } from "../lib/studio-route-client";
import { ColorTemperatureSchema, ColorPaletteSchema } from "../types";

import { useMediaInputPipeline } from "./useMediaInputPipeline";

import type {
  VisualMood,
  ExportSettings,
  FootageAnalysisSummary,
} from "../types";

// ============================================
// واجهات الحالة الداخلية
// ============================================

/**
 * نوع المشهد للتدريج اللوني
 */
type SceneType =
  | "morning"
  | "night"
  | "indoor"
  | "outdoor"
  | "happy"
  | "sad"
  | null;

/**
 * حالة تدريج الألوان
 */
interface ColorGradingState {
  /** نوع المشهد المحدد */
  sceneType: SceneType;
  /** درجة حرارة اللون بالكلفن */
  temperature: number;
  /** لوحة الألوان المولدة */
  colorPalette: string[];
  /** حالة التوليد جارية */
  isGenerating: boolean;
}

/**
 * حالة المونتاج
 */
interface EditorialState {
  /** ملاحظات المونتاج */
  notes: string;
  /** حالة التحليل جارية */
  isAnalyzing: boolean;
}

/**
 * حالة تحليل المشاهد
 */
interface FootageState {
  /** حالة الرفع جارية */
  isUploading: boolean;
  /** رسالة الخطأ */
  error: string | null;
  /** ملخص التحليل */
  summary: FootageAnalysisSummary | null;
  /** مصدر التحليل الحالي */
  analysisSource: "remote" | "local-fallback" | null;
  /** حالة التحليل */
  analysisStatus: {
    exposure: "pending" | "analyzing" | "complete";
    colorConsistency: "pending" | "analyzing" | "complete";
    focusQuality: "pending" | "analyzing" | "complete";
    motionBlur: "pending" | "analyzing" | "complete";
  };
}

// ============================================
// الثوابت
// ============================================

/**
 * درجة الحرارة الافتراضية
 */
const DEFAULT_TEMPERATURE = 5500;

/**
 * الحالة الابتدائية لتدريج الألوان
 */
const initialColorGradingState: ColorGradingState = {
  sceneType: null,
  temperature: DEFAULT_TEMPERATURE,
  colorPalette: [],
  isGenerating: false,
};

/**
 * الحالة الابتدائية للمونتاج
 */
const initialEditorialState: EditorialState = {
  notes: "",
  isAnalyzing: false,
};

/**
 * الحالة الابتدائية لتحليل المشاهد
 */
const initialFootageState: FootageState = {
  isUploading: false,
  error: null,
  summary: null,
  analysisSource: null,
  analysisStatus: {
    exposure: "pending",
    colorConsistency: "pending",
    focusQuality: "pending",
    motionBlur: "pending",
  },
};

interface ColorGradingResponse {
  success?: boolean;
  palette?: string[];
}

interface ChatResponse {
  success?: boolean;
  data?: {
    response?: string;
  };
}

interface ValidateShotResponse {
  success?: boolean;
  validation?: {
    score?: number;
    status?: string;
    exposure?: string;
    composition?: string;
    focus?: string;
    colorBalance?: string;
    suggestions?: string[];
    improvements?: string[];
  };
}

// ============================================
// الـ Hook الرئيسي
// ============================================

/**
 * Hook مخصص لإدارة أدوات ما بعد الإنتاج
 *
 * يوفر هذا الـ Hook:
 * - إدارة تدريج الألوان وتوليد لوحات الألوان
 * - تحليل إيقاع المونتاج
 * - تحليل المشاهد المصورة
 * - إعدادات التصدير والتسليم
 * - معالجة الأخطاء مع إشعارات Toast
 *
 * @example
 * ```tsx
 * const {
 *   colorPalette,
 *   generateColorPalette,
 *   temperature,
 *   setTemperature
 * } = usePostProduction("noir");
 * ```
 *
 * @param mood - المود البصري للمشروع
 * @returns كائن يحتوي على الحالة والدوال المساعدة
 */
export function usePostProduction(mood: VisualMood = "noir") {
  // ============================================
  // الحالة
  // ============================================

  const [colorGrading, setColorGrading] = useState<ColorGradingState>(
    initialColorGradingState
  );
  const [editorial, setEditorial] = useState<EditorialState>(
    initialEditorialState
  );
  const [footage, setFootage] = useState<FootageState>(initialFootageState);
  const [exportSettings, setExportSettings] = useState<ExportSettings | null>(
    null
  );
  const mediaInput = useMediaInputPipeline("image");

  // ============================================
  // دوال تدريج الألوان
  // ============================================

  /**
   * تحديث نوع المشهد
   *
   * @param sceneType - نوع المشهد الجديد
   */
  const setSceneType = useCallback((sceneType: SceneType) => {
    setColorGrading((prev) => ({
      ...prev,
      sceneType,
    }));
  }, []);

  /**
   * تحديث درجة حرارة اللون
   *
   * @param value - القيمة الجديدة
   */
  const setTemperature = useCallback((value: number[]) => {
    const temperature = value[0] ?? DEFAULT_TEMPERATURE;

    // التحقق من صحة القيمة
    const validation = ColorTemperatureSchema.safeParse(temperature);
    if (!validation.success) {
      toast.error(validation.error.errors[0]?.message ?? "قيمة غير صالحة");
      return;
    }

    setColorGrading((prev) => ({
      ...prev,
      temperature,
    }));
  }, []);

  /**
   * توليد لوحة الألوان
   *
   * تقوم هذه الدالة بتوليد لوحة ألوان مناسبة بناءً على:
   * - المود البصري للمشروع
   * - نوع المشهد المحدد
   * - درجة حرارة اللون
   */
  const generateColorPalette = useCallback(async () => {
    try {
      setColorGrading((prev) => ({
        ...prev,
        isGenerating: true,
      }));

      toast.loading("جاري توليد لوحة الألوان...", { id: "palette" });

      // استدعاء API لتوليد لوحة الألوان
      const data = await postStudioJson<ColorGradingResponse>(
        "/api/cineai/color-grading",
        {
          sceneType: colorGrading.sceneType,
          mood,
          temperature: colorGrading.temperature,
        }
      );
      const palette = data.palette ?? [];

      // التحقق من صحة اللوحة
      const validation = ColorPaletteSchema.safeParse(palette);
      if (!validation.success) {
        throw new Error("فشل في توليد لوحة الألوان");
      }

      setColorGrading((prev) => ({
        ...prev,
        isGenerating: false,
        colorPalette: validation.data,
      }));

      toast.success("تم توليد لوحة الألوان بنجاح!", { id: "palette" });
    } catch (error) {
      setColorGrading((prev) => ({
        ...prev,
        isGenerating: false,
      }));

      toast.error(
        error instanceof Error ? error.message : "فشل في توليد لوحة الألوان",
        { id: "palette" }
      );
    }
  }, [mood, colorGrading.sceneType, colorGrading.temperature]);

  // ============================================
  // دوال المونتاج
  // ============================================

  /**
   * تحديث ملاحظات المونتاج
   *
   * @param notes - الملاحظات الجديدة
   */
  const setEditorialNotes = useCallback((notes: string) => {
    setEditorial((prev) => ({
      ...prev,
      notes,
    }));
  }, []);

  /**
   * تحليل إيقاع المونتاج
   */
  const analyzeRhythm = useCallback(async () => {
    if (!editorial.notes.trim()) {
      toast.error("يرجى إدخال ملاحظات المونتاج أولاً");
      return;
    }

    try {
      setEditorial((prev) => ({
        ...prev,
        isAnalyzing: true,
      }));

      toast.loading("جاري تحليل الإيقاع...", { id: "rhythm" });

      // استدعاء API لتحليل إيقاع المونتاج
      const response = await postStudioJson<ChatResponse>(
        "/api/ai/chat",
        {
          message: `حلل إيقاع المونتاج بناءً على هذه الملاحظات وقدم توصيات تقنية:\n${editorial.notes}`,
          context: {
            assistant: "editorial-rhythm-analysis",
            mood,
          },
        },
        { requireCsrf: true }
      );

      toast.success(response.data?.response ?? "تم تحليل الإيقاع بنجاح!", {
        id: "rhythm",
      });

      setEditorial((prev) => ({
        ...prev,
        isAnalyzing: false,
      }));
    } catch (error) {
      setEditorial((prev) => ({
        ...prev,
        isAnalyzing: false,
      }));

      toast.error(
        error instanceof Error ? error.message : "فشل في تحليل الإيقاع",
        { id: "rhythm" }
      );
    }
  }, [editorial.notes, mood]);

  // ============================================
  // دوال تحليل المشاهد
  // ============================================

  /**
   * حد المهلة لمسار التحليل البعيد (ms).
   * يجب أن يسبق مهلة الاختبار الطرفي بهامش آمن.
   */
  const REMOTE_ANALYSIS_TIMEOUT_MS = 12_000;

  /**
   * تحليل المشاهد المرفوعة — مسار متوازٍ
   *
   * يبدأ الطلب البعيد والبديل المحلي معًا.
   * إذا عاد التحليل البعيد بنتيجة صالحة قبل المهلة يُعتمد كمصدر نهائي.
   * إذا تأخر أو فشل أو أعاد حمولة غير صالحة يُثبَّت الملخص المحلي فورًا.
   */
  const analyzeFootage = useCallback(
    async (file: File) => {
      const allComplete: FootageState["analysisStatus"] = {
        exposure: "complete",
        colorConsistency: "complete",
        focusQuality: "complete",
        motionBlur: "complete",
      };

      toast.loading("جاري تحليل الإطار المرجعي...", { id: "analysis" });

      setFootage((prev) => ({
        ...prev,
        analysisStatus: {
          exposure: "analyzing",
          colorConsistency: "analyzing",
          focusQuality: "analyzing",
          motionBlur: "analyzing",
        },
      }));

      // تجهيز البديل المحلي بالتوازي من اللحظة الأولى
      const localPromise = createLocalFootageSummary(file, mood).catch(
        () => null
      );

      // الطلب البعيد مع مهلة واضحة
      const formData = new FormData();
      formData.set("image", file);

      const remotePromise = postStudioFormData<ValidateShotResponse>(
        "/api/cineai/validate-shot",
        formData,
        {
          timeoutMs: REMOTE_ANALYSIS_TIMEOUT_MS,
          timeoutMessage:
            "انتهت المهلة الزمنية لتحليل المشهد. سيُستخدم التحليل المحلي.",
        }
      )
        .then((remoteResult) => {
          if (!remoteResult?.validation) {
            return null;
          }

          return normalizeFootageSummary(remoteResult.validation);
        })
        .catch(() => null);

      const winner = await resolveAnalysisWinner({
        remote: remotePromise,
        local: localPromise,
      });

      if (winner?.source === "remote") {
        setFootage((prev) => ({
          ...prev,
          summary: winner.value,
          analysisSource: "remote",
          error: null,
          analysisStatus: allComplete,
        }));
        toast.success("اكتمل تحليل الإطار المرجعي!", { id: "analysis" });
        toast.success("تم رفع الإطار المرجعي بنجاح!", { id: "upload" });
        return;
      }

      if (winner?.source === "local-fallback") {
        setFootage((prev) => ({
          ...prev,
          summary: winner.value,
          analysisSource: "local-fallback",
          error: null,
          analysisStatus: allComplete,
        }));
        toast.success("تم تفعيل التحليل المحلي البديل للمشاهد", {
          id: "analysis",
        });
        return;
      }

      // كلا المسارين فشلا
      setFootage((prev) => ({
        ...prev,
        analysisSource: null,
        error: "فشل في تحليل الإطار المرجعي من جميع المصادر",
        analysisStatus: initialFootageState.analysisStatus,
      }));
      toast.error("فشل في تحليل الإطار المرجعي", { id: "analysis" });
    },
    [mood]
  );

  /**
   * رفع إطار مرجعي للتحليل
   */
  const uploadFootage = useCallback(
    async (file?: File | null) => {
      const effectiveFile = file ?? mediaInput.state.analysisFile;
      if (!effectiveFile) {
        const message =
          "يرجى اختيار صورة أو فيديو أو التقاط إطار من الكاميرا قبل بدء التحليل.";
        setFootage((prev) => ({
          ...prev,
          error: message,
        }));
        toast.error(message);
        return;
      }

      try {
        setFootage((prev) => ({
          ...prev,
          isUploading: true,
          error: null,
        }));

        toast.loading("جاري رفع الإطار المرجعي...", { id: "upload" });

        await analyzeFootage(effectiveFile);
      } catch (error) {
        const message =
          error instanceof Error ? error.message : "فشل في رفع الإطار المرجعي";
        setFootage((prev) => ({
          ...prev,
          error: message,
        }));
        toast.error(message, { id: "upload" });
      } finally {
        setFootage((prev) => ({
          ...prev,
          isUploading: false,
        }));
      }
    },
    [analyzeFootage, mediaInput.state.analysisFile]
  );

  // ============================================
  // دوال التصدير
  // ============================================

  /**
   * إنشاء إعدادات التصدير
   *
   * @param platform - المنصة المستهدفة
   */
  const createExportSettings = useCallback(
    (platform: ExportSettings["platform"]) => {
      const settings = getExportSettingsForPlatform(platform);
      setExportSettings(settings);
      toast.success(`تم إنشاء إعدادات التصدير لـ ${settings.platform}`);
    },
    []
  );

  // ============================================
  // قيم محسوبة
  // ============================================

  /**
   * درجة الحرارة الموصى بها بناءً على المود
   */
  const recommendedTemperature = useMemo((): number => {
    const moodDefaults: Record<VisualMood, number> = {
      noir: 3200,
      realistic: 5600,
      surreal: 4500,
      vintage: 3800,
    };
    return moodDefaults[mood];
  }, [mood]);

  /**
   * التحقق من وجود لوحة ألوان
   */
  const hasColorPalette = useMemo((): boolean => {
    return colorGrading.colorPalette.length > 0;
  }, [colorGrading.colorPalette]);

  /**
   * التحقق من اكتمال تحليل المشاهد
   */
  const isFootageAnalysisComplete = useMemo((): boolean => {
    const { analysisStatus } = footage;
    return Object.values(analysisStatus).every(
      (status) => status === "complete"
    );
  }, [footage.analysisStatus]);

  /**
   * قيمة درجة الحرارة للعرض
   */
  const temperatureValue = useMemo(
    () => [colorGrading.temperature],
    [colorGrading.temperature]
  );

  // ============================================
  // القيمة المُرجعة
  // ============================================

  return {
    // تدريج الألوان
    sceneType: colorGrading.sceneType,
    temperature: colorGrading.temperature,
    temperatureValue,
    colorPalette: colorGrading.colorPalette,
    isGeneratingPalette: colorGrading.isGenerating,
    setSceneType,
    setTemperature,
    generateColorPalette,
    hasColorPalette,
    recommendedTemperature,

    // المونتاج
    editorialNotes: editorial.notes,
    isAnalyzingRhythm: editorial.isAnalyzing,
    setEditorialNotes,
    analyzeRhythm,

    // تحليل المشاهد
    isUploadingFootage: footage.isUploading,
    footageAnalysisStatus: footage.analysisStatus,
    footageSummary: footage.summary,
    footageAnalysisSource: footage.analysisSource,
    footageError: footage.error,
    uploadFootage,
    isFootageAnalysisComplete,
    mediaInput,

    // التصدير
    exportSettings,
    createExportSettings,
  };
}

/**
 * الحصول على إعدادات التصدير للمنصة
 */
function getExportSettingsForPlatform(
  platform: ExportSettings["platform"]
): ExportSettings {
  const settingsMap: Record<ExportSettings["platform"], ExportSettings> = {
    "cinema-dcp": {
      platform: "cinema-dcp",
      resolution: "4096x2160",
      frameRate: 24,
      codec: "JPEG2000",
    },
    "broadcast-hd": {
      platform: "broadcast-hd",
      resolution: "1920x1080",
      frameRate: 25,
      codec: "ProRes 422",
    },
    "web-social": {
      platform: "web-social",
      resolution: "1920x1080",
      frameRate: 30,
      codec: "H.264",
    },
    bluray: {
      platform: "bluray",
      resolution: "1920x1080",
      frameRate: 24,
      codec: "H.264 High Profile",
    },
  };

  return settingsMap[platform];
}

export default usePostProduction;

function normalizeFootageSummary(
  validation:
    | {
        score?: number;
        status?: string;
        exposure?: string;
        composition?: string;
        focus?: string;
        colorBalance?: string;
        suggestions?: string[];
        improvements?: string[];
      }
    | undefined
): FootageAnalysisSummary {
  return {
    score: clampScore(validation?.score),
    status: validation?.status ?? "unknown",
    exposure: validation?.exposure ?? "غير متاح",
    colorBalance: validation?.colorBalance ?? "غير متاح",
    focus: validation?.focus ?? "غير متاح",
    suggestions: [
      ...(validation?.suggestions ?? []),
      ...(validation?.improvements ?? []),
    ].filter((value, index, array) => array.indexOf(value) === index),
  };
}

function clampScore(value: number | undefined): number {
  if (typeof value !== "number" || Number.isNaN(value)) {
    return 0;
  }

  return Math.max(0, Math.min(100, Math.round(value)));
}

/**
 * @fileoverview Hook مخصص لإدارة أدوات أثناء التصوير
 *
 * هذا الـ Hook يوفر جميع الوظائف المطلوبة لمرحلة التصوير الفعلي
 * بما في ذلك تحليل اللقطات وإدارة الإعدادات التقنية.
 * يتضمن معالجة الأخطاء والتحقق من صحة البيانات.
 *
 * @module cinematography-studio/hooks/useProduction
 */

"use client";

import { useState, useCallback, useEffect, useMemo, useRef } from "react";
import { toast } from "react-hot-toast";

import { publishDiagnostics } from "../lib/diagnostics-bus";
import { createLocalShotAnalysis } from "../lib/local-shot-analysis";
import { resolveAnalysisWinner } from "../lib/resolve-analysis-winner";
import { patchSession, readSession } from "../lib/session-storage";
import { postStudioFormData, postStudioJson } from "../lib/studio-route-client";
import { ShotAnalysisSchema } from "../types";

import { useMediaInputPipeline } from "./useMediaInputPipeline";

import type { VisualMood, ShotAnalysis } from "../types";

// ============================================
// واجهات الحالة الداخلية
// ============================================

/**
 * حالة تحليل اللقطة
 */
interface AnalysisState {
  /** حالة التحليل جارية */
  isAnalyzing: boolean;
  /** نتيجة التحليل */
  analysis: ShotAnalysis | null;
  /** مصدر التحليل الفعلي */
  source: "remote" | "local-fallback" | null;
  /** رسالة الخطأ إن وجدت */
  error: string | null;
  /** سؤال المستخدم للمساعد */
  question: string;
}

/**
 * حالة المساعد الذكي — منفصلة عن حالة التحليل لأن الإجابة والخطأ
 * يجب أن يبقيا داخل لوحة المساعد لا في إشعار toast العابر.
 */
interface AssistantState {
  isLoading: boolean;
  /** آخر إجابة ناجحة */
  answer: string | null;
  /** آخر سؤال أُرسل بنجاح (لعرضه فوق الإجابة) */
  lastQuestion: string | null;
  /** آخر خطأ */
  error: string | null;
}

/**
 * الإعدادات التقنية للكاميرا
 */
interface TechnicalSettings {
  /** Focus Peaking */
  focusPeaking: boolean;
  /** False Color */
  falseColor: boolean;
  /** درجة حرارة اللون بالكلفن */
  colorTemp: number;
}

// ============================================
// الثوابت
// ============================================

/**
 * الحالة الابتدائية للتحليل
 */
const initialAnalysisState: AnalysisState = {
  isAnalyzing: false,
  analysis: null,
  source: null,
  error: null,
  question: "",
};

const initialAssistantState: AssistantState = {
  isLoading: false,
  answer: null,
  lastQuestion: null,
  error: null,
};

/** حد المهلة لطلب المساعد الذكي (ms). */
const ASSISTANT_REQUEST_TIMEOUT_MS = 15_000;

/**
 * الإعدادات التقنية الافتراضية
 */
const defaultTechnicalSettings: TechnicalSettings = {
  focusPeaking: true,
  falseColor: false,
  colorTemp: 3200,
};

interface ValidateShotResponse {
  success?: boolean;
  validation?: {
    score?: number;
    status?: string;
    exposure?: string;
    composition?: string;
    focus?: string;
    colorBalance?: string;
    suggestions?: string[];
    improvements?: string[];
  };
}

interface ChatResponse {
  success?: boolean;
  data?: {
    response?: string;
  };
}

// ============================================
// الـ Hook الرئيسي
// ============================================

/**
 * Hook مخصص لإدارة أدوات أثناء التصوير
 *
 * يوفر هذا الـ Hook:
 * - تحليل اللقطات بالذكاء الاصطناعي
 * - إدارة الإعدادات التقنية للكاميرا
 * - نظام تحذيرات ذكي
 * - معالجة الأخطاء مع إشعارات Toast
 *
 * @example
 * ```tsx
 * const {
 *   analysis,
 *   isAnalyzing,
 *   handleAnalyzeShot,
 *   technicalSettings
 * } = useProduction("noir");
 * ```
 *
 * @param mood - المود البصري للمشروع
 * @returns كائن يحتوي على الحالة والدوال المساعدة
 */
export function useProduction(mood: VisualMood = "noir") {
  // ============================================
  // الحالة
  // ============================================

  const [analysisState, setAnalysisState] =
    useState<AnalysisState>(initialAnalysisState);
  const [assistantState, setAssistantState] = useState<AssistantState>(
    initialAssistantState
  );
  const [technicalSettings, setTechnicalSettings] = useState<TechnicalSettings>(
    defaultTechnicalSettings
  );
  const mediaInput = useMediaInputPipeline("image");
  const persistenceHydrated = useRef(false);

  // استعادة الإعدادات التقنية وآخر تحليل عند أول تركيب — ثم نسمح بالحفظ.
  useEffect(() => {
    if (persistenceHydrated.current) {
      return;
    }
    persistenceHydrated.current = true;
    const persisted = readSession();
    if (!persisted) {
      return;
    }
    if (persisted.technicalSettings) {
      setTechnicalSettings(persisted.technicalSettings);
    }
    if (persisted.lastAnalysis) {
      setAnalysisState((prev) => ({
        ...prev,
        analysis: persisted.lastAnalysis ?? null,
        source: "local-fallback",
      }));
    }
    if (persisted.lastAssistant?.answer) {
      setAssistantState({
        isLoading: false,
        answer: persisted.lastAssistant.answer,
        lastQuestion: persisted.lastAssistant.question ?? null,
        error: null,
      });
    }
  }, []);

  // حفظ الإعدادات التقنية بعد الهيدرة الأولى.
  useEffect(() => {
    if (!persistenceHydrated.current) {
      return;
    }
    patchSession({ technicalSettings });
  }, [technicalSettings]);

  // حفظ آخر تحليل وآخر إجابة مساعد (نص فقط، بدون وسائط).
  useEffect(() => {
    if (!persistenceHydrated.current) {
      return;
    }
    patchSession({ lastAnalysis: analysisState.analysis });
  }, [analysisState.analysis]);

  useEffect(() => {
    if (!persistenceHydrated.current) {
      return;
    }
    patchSession({
      lastAssistant: assistantState.answer
        ? {
            question: assistantState.lastQuestion,
            answer: assistantState.answer,
          }
        : null,
    });
  }, [assistantState.answer, assistantState.lastQuestion]);

  // نشر حالة المساعد لطبقة التشخيص.
  useEffect(() => {
    publishDiagnostics({
      slice: "assistant",
      data: {
        isLoading: assistantState.isLoading,
        lastQuestion: assistantState.lastQuestion,
        answerLength: assistantState.answer?.length ?? 0,
        error: assistantState.error,
      },
    });
  }, [
    assistantState.answer,
    assistantState.error,
    assistantState.isLoading,
    assistantState.lastQuestion,
  ]);

  // عدّاد إعادة التركيب للتشخيص.
  const productionRenderCount = useRef(0);
  productionRenderCount.current += 1;
  useEffect(() => {
    publishDiagnostics({
      slice: "renderCount",
      data: { production: productionRenderCount.current },
    });
  });

  // ============================================
  // دوال التحليل
  // ============================================

  /**
   * حد المهلة لمسار التحليل البعيد (ms).
   */
  const REMOTE_ANALYSIS_TIMEOUT_MS = 12_000;

  /**
   * تحليل اللقطة الحالية — مسار متوازٍ
   *
   * يبدأ الطلب البعيد والبديل المحلي معًا.
   * إذا عاد البعيد بنتيجة صالحة قبل المهلة يُعتمد.
   * إذا تأخر أو فشل يُثبَّت البديل المحلي فورًا.
   */
  const handleAnalyzeShot = useCallback(
    async (file?: File | null) => {
      const effectiveFile = file ?? mediaInput.state.analysisFile;

      if (!effectiveFile) {
        toast.error(
          "يرجى اختيار صورة أو فيديو أو التقاط إطار من الكاميرا أولاً"
        );
        return;
      }

      setAnalysisState((prev) => ({
        ...prev,
        isAnalyzing: true,
        error: null,
      }));

      toast.loading("جاري المسح الطيفي للقطة...", { id: "analyzing" });

      // تجهيز البديل المحلي بالتوازي من اللحظة الأولى
      const localPromise = createLocalShotAnalysis(effectiveFile, mood)
        .then((analysis) => {
          const validation = ShotAnalysisSchema.safeParse(analysis);
          return validation.success ? validation.data : null;
        })
        .catch(() => null);

      // الطلب البعيد مع مهلة واضحة
      const formData = new FormData();
      formData.set("image", effectiveFile);

      const remotePromise = postStudioFormData<ValidateShotResponse>(
        "/api/cineai/validate-shot",
        formData,
        {
          timeoutMs: REMOTE_ANALYSIS_TIMEOUT_MS,
          timeoutMessage:
            "انتهت المهلة الزمنية لتحليل اللقطة. سيُستخدم التحليل المحلي.",
        }
      )
        .then((remoteData) => {
          if (!remoteData?.validation) {
            return null;
          }

          const analysis = normalizeShotAnalysis(remoteData.validation);
          const validation = ShotAnalysisSchema.safeParse(analysis);
          return validation.success ? validation.data : null;
        })
        .catch(() => null);

      const winner = await resolveAnalysisWinner({
        remote: remotePromise,
        local: localPromise,
      });

      if (winner?.source === "remote") {
        setAnalysisState((prev) => ({
          ...prev,
          isAnalyzing: false,
          analysis: winner.value,
          source: "remote",
          error: null,
        }));

        if (winner.value.issues.length > 0) {
          toast.success(
            `تم التحليل بنجاح - يوجد ${winner.value.issues.length} ملاحظة`,
            { id: "analyzing" }
          );
        } else {
          toast.success("اللقطة جاهزة للتصوير!", { id: "analyzing" });
        }
        return;
      }

      if (winner?.source === "local-fallback") {
        setAnalysisState((prev) => ({
          ...prev,
          isAnalyzing: false,
          error: null,
          analysis: winner.value,
          source: "local-fallback",
        }));
        toast.success("تم تفعيل التحليل المحلي البديل بنجاح", {
          id: "analyzing",
        });
        return;
      }

      // كلا المسارين فشلا
      setAnalysisState((prev) => ({
        ...prev,
        isAnalyzing: false,
        source: null,
        error: "فشل في تحليل اللقطة من جميع المصادر",
      }));
      toast.error("فشل في تحليل اللقطة", { id: "analyzing" });
    },
    [mediaInput.state.analysisFile, mood]
  );

  /**
   * تحديث سؤال المستخدم
   *
   * @param question - السؤال الجديد
   */
  const setQuestion = useCallback((question: string) => {
    setAnalysisState((prev) => ({
      ...prev,
      question,
    }));
  }, []);

  /**
   * إرسال سؤال للمساعد الذكي.
   *
   * - يضع حالة تحميل داخل لوحة المساعد (لا يعتمد على toast فقط).
   * - يحترم مهلة محددة عبر `postStudioJson`.
   * - عند النجاح: يعرض الإجابة داخل اللوحة ويمسح السؤال الحالي.
   * - عند الفشل: يعرض الخطأ داخل اللوحة ويُبقي السؤال الذي كتبه المستخدم.
   */
  const askAssistant = useCallback(async () => {
    const trimmedQuestion = analysisState.question.trim();

    if (!trimmedQuestion) {
      setAssistantState((prev) => ({
        ...prev,
        error: "يرجى كتابة سؤالك أولاً",
      }));
      return;
    }

    if (assistantState.isLoading) {
      // منع الإرسال المزدوج عبر زر الإدخال أو النقر المتكرر
      return;
    }

    setAssistantState({
      isLoading: true,
      answer: null,
      lastQuestion: trimmedQuestion,
      error: null,
    });

    try {
      const response = await postStudioJson<ChatResponse>(
        "/api/ai/chat",
        {
          message: trimmedQuestion,
          context: {
            assistant: "cinematography-assistant",
            mood,
            latestAnalysis: analysisState.analysis,
          },
        },
        {
          requireCsrf: true,
          timeoutMs: ASSISTANT_REQUEST_TIMEOUT_MS,
          timeoutMessage:
            "انتهت المهلة الزمنية للمساعد. تحقق من الاتصال ثم أعد المحاولة.",
        }
      );

      const answerText = response.data?.response?.trim();

      if (!answerText) {
        throw new Error("لم يصل المساعد بإجابة قابلة للعرض. حاول مرة أخرى.");
      }

      setAssistantState({
        isLoading: false,
        answer: answerText,
        lastQuestion: trimmedQuestion,
        error: null,
      });

      // مسح السؤال فقط بعد نجاح الإرسال
      setAnalysisState((prev) => ({
        ...prev,
        question: "",
      }));
    } catch (error) {
      const message =
        error instanceof Error ? error.message : "فشل في إرسال السؤال";
      setAssistantState((prev) => ({
        ...prev,
        isLoading: false,
        answer: null,
        error: message,
      }));
    }
  }, [
    analysisState.analysis,
    analysisState.question,
    assistantState.isLoading,
    mood,
  ]);

  /**
   * مسح آخر إجابة/خطأ من لوحة المساعد دون مسح السؤال الحالي.
   */
  const dismissAssistantResult = useCallback(() => {
    setAssistantState((prev) => ({
      ...prev,
      answer: null,
      error: null,
    }));
  }, []);

  /**
   * إعادة تعيين حالة التحليل
   */
  const resetAnalysis = useCallback(() => {
    setAnalysisState(initialAnalysisState);
    setAssistantState(initialAssistantState);
    mediaInput.clearMedia();
  }, [mediaInput.clearMedia]);

  // ============================================
  // دوال الإعدادات التقنية
  // ============================================

  /**
   * تبديل إعداد Focus Peaking
   */
  const toggleFocusPeaking = useCallback(() => {
    setTechnicalSettings((prev) => ({
      ...prev,
      focusPeaking: !prev.focusPeaking,
    }));
    toast.success(
      technicalSettings.focusPeaking
        ? "تم إيقاف Focus Peaking"
        : "تم تفعيل Focus Peaking"
    );
  }, [technicalSettings.focusPeaking]);

  /**
   * تبديل إعداد False Color
   */
  const toggleFalseColor = useCallback(() => {
    setTechnicalSettings((prev) => ({
      ...prev,
      falseColor: !prev.falseColor,
    }));
    toast.success(
      technicalSettings.falseColor
        ? "تم إيقاف False Color"
        : "تم تفعيل False Color"
    );
  }, [technicalSettings.falseColor]);

  /**
   * تحديث درجة حرارة اللون
   *
   * @param colorTemp - درجة الحرارة بالكلفن
   */
  const setColorTemp = useCallback((colorTemp: number) => {
    if (colorTemp >= 2000 && colorTemp <= 10000) {
      setTechnicalSettings((prev) => ({
        ...prev,
        colorTemp,
      }));
    }
  }, []);

  /**
   * تحديث درجة حرارة اللون من Slider (يأخذ مصفوفة)
   *
   * @param value - القيمة كمصفوفة من الـ Slider
   */
  const setColorTempFromSlider = useCallback(
    (value: number[]) => {
      const temp = value[0] ?? 3200;
      setColorTemp(temp);
    },
    [setColorTemp]
  );

  /**
   * قيمة درجة الحرارة كمصفوفة للـ Slider
   */
  const colorTempValue = useMemo(
    () => [technicalSettings.colorTemp],
    [technicalSettings.colorTemp]
  );

  // ============================================
  // قيم محسوبة
  // ============================================

  /**
   * درجة الحرارة الموصى بها بناءً على المود الحالي
   */
  const recommendedColorTemp = useMemo((): number => {
    const moodDefaults: Record<VisualMood, number> = {
      noir: 3200,
      realistic: 5600,
      surreal: 4500,
      vintage: 3800,
    };
    return moodDefaults[mood];
  }, [mood]);

  /**
   * التحقق من وجود تحليل جاهز
   */
  const hasAnalysis = useMemo((): boolean => {
    return analysisState.analysis !== null;
  }, [analysisState.analysis]);

  /**
   * التحقق من وجود مشاكل في اللقطة
   */
  const hasIssues = useMemo((): boolean => {
    return (analysisState.analysis?.issues.length ?? 0) > 0;
  }, [analysisState.analysis]);

  /**
   * حالة الجاهزية للتصوير
   */
  const isReadyToShoot = useMemo((): boolean => {
    return hasAnalysis && !hasIssues;
  }, [hasAnalysis, hasIssues]);

  // ============================================
  // القيمة المُرجعة
  // ============================================

  return {
    // حالة التحليل
    analysis: analysisState.analysis,
    analysisSource: analysisState.source,
    isAnalyzing: analysisState.isAnalyzing,
    error: analysisState.error,
    question: analysisState.question,

    // دوال التحليل
    handleAnalyzeShot,
    setQuestion,
    askAssistant,
    resetAnalysis,
    dismissAssistantResult,

    // حالة المساعد الذكي
    assistantAnswer: assistantState.answer,
    assistantError: assistantState.error,
    assistantLastQuestion: assistantState.lastQuestion,
    isAssistantLoading: assistantState.isLoading,

    // إدخال الوسائط
    mediaInput,

    // الإعدادات التقنية
    technicalSettings,
    toggleFocusPeaking,
    toggleFalseColor,
    setColorTemp,
    setColorTempFromSlider,
    colorTempValue,

    // قيم محسوبة
    hasAnalysis,
    hasIssues,
    isReadyToShoot,
    recommendedColorTemp,
  };
}

export default useProduction;

function normalizeShotAnalysis(
  validation:
    | {
        score?: number;
        status?: string;
        exposure?: string;
        composition?: string;
        focus?: string;
        colorBalance?: string;
        suggestions?: string[];
        improvements?: string[];
      }
    | undefined
): ShotAnalysis {
  const issues = [
    ...(validation?.suggestions ?? []),
    ...(validation?.improvements ?? []),
  ].filter((value, index, array) => array.indexOf(value) === index);

  return {
    score: clampScore(validation?.score),
    dynamicRange: validation?.composition ?? validation?.exposure ?? "غير متاح",
    grainLevel: validation?.focus ?? validation?.colorBalance ?? "غير متاح",
    issues,
    exposure: clampScore(validation?.score),
  };
}

function clampScore(value: number | undefined): number {
  if (typeof value !== "number" || Number.isNaN(value)) {
    return 0;
  }

  return Math.max(0, Math.min(100, Math.round(value)));
}

/**
 * @fileoverview طبقة حفظ آمنة لجلسة استوديو التصوير السينمائي.
 *
 * - تحفظ في localStorage تحت مفتاح ثابت ومختوم بنسخة (v1).
 * - لا تحفظ ملفات وسائط ثقيلة. الفيديو لا يُسلسل أبدًا. الصور المُلتقطة
 *   لا تُحفظ في النسخة الأولى — يكتفى ببقاء آخر تحليل نصي فقط.
 * - تتسامح مع البيانات الفاسدة وتعيد null بدلًا من رمي استثناء.
 *
 * مفتاح التخزين الرسمي:
 *
 *     cinematography-studio.session.v1
 */

import type { Phase, ShotAnalysis, ViewMode, VisualMood } from "../types";

export const SESSION_STORAGE_KEY = "cinematography-studio.session.v1";

/** حقول الجلسة المحفوظة. كلها اختيارية لأن المتصفح قد لا يجد بعضها. */
export interface PersistedStudioSession {
  phase?: Phase;
  view?: ViewMode;
  mood?: VisualMood;
  activeTool?: string | null;
  technicalSettings?: {
    focusPeaking: boolean;
    falseColor: boolean;
    colorTemp: number;
  };
  lastAnalysis?: ShotAnalysis | null;
  lastAssistant?: {
    question: string | null;
    answer: string | null;
  } | null;
  savedAt?: string;
}

const VALID_PHASES: readonly Phase[] = ["pre", "production", "post"];
const VALID_VIEWS: readonly ViewMode[] = ["dashboard", "phases"];
const VALID_MOODS: readonly VisualMood[] = [
  "noir",
  "realistic",
  "surreal",
  "vintage",
];

function isBrowser(): boolean {
  return typeof window !== "undefined" && typeof window.localStorage !== "undefined";
}

function asString(value: unknown): string | undefined {
  return typeof value === "string" ? value : undefined;
}

function asBoolean(value: unknown): boolean | undefined {
  return typeof value === "boolean" ? value : undefined;
}

function asNumber(value: unknown): number | undefined {
  return typeof value === "number" && Number.isFinite(value) ? value : undefined;
}

function sanitizeAnalysis(value: unknown): ShotAnalysis | null {
  if (!value || typeof value !== "object") {
    return null;
  }
  const candidate = value as Record<string, unknown>;
  const score = asNumber(candidate.score);
  const exposure = asNumber(candidate.exposure);
  if (score === undefined || exposure === undefined) {
    return null;
  }

  const issuesRaw = candidate.issues;
  const issues = Array.isArray(issuesRaw)
    ? issuesRaw.filter((entry): entry is string => typeof entry === "string")
    : [];

  return {
    score,
    exposure,
    dynamicRange: asString(candidate.dynamicRange) ?? "غير متاح",
    grainLevel: asString(candidate.grainLevel) ?? "غير متاح",
    issues,
  };
}

function sanitizeSession(value: unknown): PersistedStudioSession | null {
  if (!value || typeof value !== "object") {
    return null;
  }
  const candidate = value as Record<string, unknown>;
  const result: PersistedStudioSession = {};

  const phase = asString(candidate.phase);
  if (phase && (VALID_PHASES as readonly string[]).includes(phase)) {
    result.phase = phase as Phase;
  }

  const view = asString(candidate.view);
  if (view && (VALID_VIEWS as readonly string[]).includes(view)) {
    result.view = view as ViewMode;
  }

  const mood = asString(candidate.mood);
  if (mood && (VALID_MOODS as readonly string[]).includes(mood)) {
    result.mood = mood as VisualMood;
  }

  if (candidate.activeTool === null) {
    result.activeTool = null;
  } else {
    const tool = asString(candidate.activeTool);
    if (tool) {
      result.activeTool = tool;
    }
  }

  if (candidate.technicalSettings && typeof candidate.technicalSettings === "object") {
    const techRaw = candidate.technicalSettings as Record<string, unknown>;
    const focusPeaking = asBoolean(techRaw.focusPeaking);
    const falseColor = asBoolean(techRaw.falseColor);
    const colorTemp = asNumber(techRaw.colorTemp);
    if (
      focusPeaking !== undefined &&
      falseColor !== undefined &&
      colorTemp !== undefined &&
      colorTemp >= 2000 &&
      colorTemp <= 10000
    ) {
      result.technicalSettings = { focusPeaking, falseColor, colorTemp };
    }
  }

  result.lastAnalysis = sanitizeAnalysis(candidate.lastAnalysis);

  if (candidate.lastAssistant && typeof candidate.lastAssistant === "object") {
    const assistantRaw = candidate.lastAssistant as Record<string, unknown>;
    const question = asString(assistantRaw.question);
    const answer = asString(assistantRaw.answer);
    if (question || answer) {
      result.lastAssistant = {
        question: question ?? null,
        answer: answer ?? null,
      };
    } else {
      result.lastAssistant = null;
    }
  }

  const savedAt = asString(candidate.savedAt);
  if (savedAt) {
    result.savedAt = savedAt;
  }

  return result;
}

/**
 * يقرأ الجلسة المحفوظة. يعيد null عند غياب المتصفح أو عند فساد البيانات.
 * لا يرمي أبدًا.
 */
export function readSession(): PersistedStudioSession | null {
  if (!isBrowser()) {
    return null;
  }

  try {
    const raw = window.localStorage.getItem(SESSION_STORAGE_KEY);
    if (!raw) {
      return null;
    }
    const parsed = JSON.parse(raw);
    return sanitizeSession(parsed);
  } catch {
    return null;
  }
}

/**
 * يدمج تحديثًا جزئيًا مع الجلسة الحالية ويحفظ النتيجة.
 * يتحمّل أخطاء الكوتا أو وضع الخصوصية بصمت.
 */
export function patchSession(patch: PersistedStudioSession): void {
  if (!isBrowser()) {
    return;
  }
  try {
    const current = readSession() ?? {};
    const merged: PersistedStudioSession = {
      ...current,
      ...patch,
      savedAt: new Date().toISOString(),
    };
    window.localStorage.setItem(SESSION_STORAGE_KEY, JSON.stringify(merged));
  } catch {
    // تجاهل الأخطاء — عدم إعاقة المستخدم بسبب فشل تخزين محلي.
  }
}

/**
 * يمسح جلسة الاستوديو المحفوظة بالكامل.
 */
export function clearSession(): void {
  if (!isBrowser()) {
    return;
  }
  try {
    window.localStorage.removeItem(SESSION_STORAGE_KEY);
  } catch {
    // تجاهل
  }
}

