export default function CharactersPage() {
  const [isDialogOpen, setIsDialogOpen] = useState(false);
  const [selectedCharacter, setSelectedCharacter] = useState<Character | null>(
    null
  );
  const [deleteConfirmId, setDeleteConfirmId] = useState<string | null>(null);
  const queryClient = useQueryClient();
  const { projectId: currentProjectId } = useCurrentProject();
  const { toast } = useToast();

  const {
    data: characters,
    isLoading,
    error,
  } = useQuery({
    queryKey: ["characters", currentProjectId],
    queryFn: async () => {
      if (!currentProjectId) return [];
      const res = await fetch(`/api/projects/${currentProjectId}/characters`);
      if (!res.ok) throw new Error(`فشل تحميل الشخصيات: ${res.status}`);
      const data = await res.json();
      return data.data as Character[];
    },
    enabled: !!currentProjectId,
  });

  const deleteMutation = useMutation({
    mutationFn: async (characterId: string) => {
      const res = await fetch(`/api/characters/${characterId}`, {
        method: "DELETE",
      });
      if (!res.ok) throw new Error(`فشل حذف الشخصية: ${res.status}`);
      return res.json();
    },
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: ["characters"] });
      setDeleteConfirmId(null);
      toast({ title: "تم الحذف", description: "تم حذف الشخصية بنجاح" });
    },
    onError: (err: Error) => {
      toast({
        title: "حدث خطأ",
        description: err.message,
        variant: "destructive",
      });
    },
  });

  const handleEdit = useCallback((character: Character) => {
    setSelectedCharacter(character);
    setIsDialogOpen(true);
  }, []);

  const handleDelete = useCallback(
    (characterId: string) => {
      if (deleteConfirmId === characterId) {
        deleteMutation.mutate(characterId);
      } else {
        setDeleteConfirmId(characterId);
      }
    },
    [deleteConfirmId, deleteMutation]
  );

  const handleDialogClose = useCallback(() => {
    setIsDialogOpen(false);
    setSelectedCharacter(null);
  }, []);

  if (!currentProjectId) {
    return (
      <div className="flex flex-col items-center justify-center min-h-[60vh] gap-4">
        <AlertTriangle className="h-16 w-16 text-[var(--app-text-muted)]" />
        <p className="text-[var(--app-text-muted)] text-lg">
          لا يوجد مشروع محدد. يرجى اختيار مشروع أولاً.
        </p>
      </div>
    );
  }

  if (isLoading) {
    return (
      <div className="flex items-center justify-center min-h-[60vh]">
        <div className="flex flex-col items-center gap-3">
          <div className="h-8 w-8 border-4 border-[var(--app-accent)] border-t-transparent rounded-full animate-spin" />
          <p className="text-[var(--app-text-muted)]">جاري تحميل الشخصيات...</p>
        </div>
      </div>
    );
  }

  if (error) {
    return (
      <div className="flex flex-col items-center justify-center min-h-[60vh] gap-4">
        <AlertTriangle className="h-12 w-12 text-destructive" />
        <p className="text-destructive">{(error).message}</p>
      </div>
    );
  }

  return (
    <div className="container mx-auto py-8 px-4">
      <div className="flex justify-between items-center mb-8">
        <div>
          <h1 className="text-4xl font-bold text-[var(--app-text)]">
            الشخصيات
          </h1>
          <p className="text-[var(--app-text-muted)] mt-2">
            إدارة شخصيات المشروع
          </p>
        </div>
        <Button
          onClick={() => setIsDialogOpen(true)}
          className="bg-[var(--app-accent)] text-white hover:bg-[var(--app-accent)]/90"
        >
          <Plus className="mr-2 h-4 w-4" />
          شخصية جديدة
        </Button>
      </div>

      {characters && characters.length > 10 ? (
        <VirtualizedGrid
          items={characters}
          renderItem={(character) => (
            <CharacterCard
              key={character.id}
              character={character}
              onEdit={handleEdit}
              onDelete={handleDelete}
            />
          )}
          columnCount={3}
          itemHeight={280}
          itemWidth={350}
        />
      ) : (
        <div className="grid gap-4 md:grid-cols-2 lg:grid-cols-3">
          {characters?.map((character) => (
            <CharacterCard
              key={character.id}
              character={character}
              onEdit={handleEdit}
              onDelete={handleDelete}
            />
          ))}
        </div>
      )}

      {characters?.length === 0 && (
        <div className="text-center py-12">
          <Users className="h-16 w-16 mx-auto text-[var(--app-text-muted)] mb-4" />
          <p className="text-[var(--app-text-muted)]">
            لا توجد شخصيات حتى الآن
          </p>
          <Button
            className="mt-4 bg-[var(--app-accent)] text-white hover:bg-[var(--app-accent)]/90"
            onClick={() => setIsDialogOpen(true)}
          >
            <Plus className="mr-2 h-4 w-4" />
            إنشاء شخصية جديدة
          </Button>
        </div>
      )}

      <CharacterFormDialog
        open={isDialogOpen}
        onOpenChange={handleDialogClose}
        {...(selectedCharacter && { character: selectedCharacter })}
        projectId={currentProjectId}
      />
    </div>
  );
}

/**
 * @fileoverview مكوّن لوحة المحادثة مع المساعد الذكي
 *
 * السبب في وجود هذا المكوّن: توفير واجهة تفاعلية
 * للتواصل مع الذكاء الاصطناعي للحصول على مساعدة في الإخراج.
 *
 * يدعم:
 * - إرسال واستقبال الرسائل النصية
 * - اقتراحات سريعة للأسئلة الشائعة
 * - عرض حالة التحميل أثناء انتظار الرد
 */
"use client";

import { Sparkles, Send, User, Bot } from "lucide-react";
import { useState, useCallback, useMemo, memo } from "react";

import { Badge } from "@/components/ui/badge";
import { Button } from "@/components/ui/button";
import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";
import { Input } from "@/components/ui/input";
import { ScrollArea } from "@/components/ui/scroll-area";
import { useToast } from "@/hooks/use-toast";
import { useChatWithAI } from "@/hooks/useAI";

/**
 * واجهة بيانات الرسالة
 */
interface Message {
  /** معرف الرسالة الفريد */
  id: string;
  /** دور المرسل (مستخدم أو مساعد) */
  role: "user" | "assistant";
  /** محتوى الرسالة */
  content: string;
  /** وقت الإرسال */
  timestamp: string;
}

/**
 * رسائل الخطأ
 */
const ERROR_MESSAGES = {
  chatError: "عذراً، حدث خطأ. الرجاء المحاولة مرة أخرى.",
} as const;

/**
 * اقتراحات الأسئلة الشائعة
 * السبب: مساعدة المستخدم على البدء بأسئلة مفيدة
 */
const DEFAULT_SUGGESTIONS = [
  "اقترح زوايا تصوير للمشهد الأول",
  "كيف أحسن الإضاءة في مشهد ليلي؟",
  "ما هي أفضل طريقة لتصوير مشهد مطاردة؟",
] as const;

/**
 * الرسالة الترحيبية الافتراضية
 */
const WELCOME_MESSAGE: Message = {
  id: "1",
  role: "assistant",
  content:
    "مرحباً! أنا مساعدك الذكي للإخراج السينمائي. كيف يمكنني مساعدتك اليوم؟",
  timestamp: "الآن",
};

/**
 * مكوّن عنصر رسالة فردية
 *
 * السبب في فصله: تحسين قابلية القراءة والأداء
 * من خلال تذكير الرسائل الفردية.
 */
const MessageItem = memo(function MessageItem({
  message,
}: {
  message: Message;
}) {
  const isUser = message.role === "user";

  return (
    <div
      className={`flex gap-3 ${isUser ? "justify-start flex-row-reverse" : "justify-end"}`}
      data-testid={`message-${message.id}`}
    >
      <div
        className={`flex items-start gap-3 max-w-[80%] ${isUser ? "flex-row-reverse" : ""}`}
      >
        <div
          className={`p-2 rounded-full ${isUser ? "bg-[var(--app-accent)]" : "bg-[var(--app-surface)]"}`}
        >
          {isUser ? (
            <User className="w-4 h-4 text-white" />
          ) : (
            <Bot className="w-4 h-4 text-[var(--app-text-muted)]" />
          )}
        </div>

        <div
          className={`flex flex-col gap-1 ${isUser ? "items-end" : "items-start"}`}
        >
          <div
            className={`p-4 rounded-md ${
              isUser
                ? "bg-[var(--app-accent)] text-white"
                : "bg-[var(--app-surface)] text-[var(--app-text)]"
            }`}
          >
            <p className="text-sm leading-relaxed">{message.content}</p>
          </div>
          <span className="text-xs text-[var(--app-text-muted)] px-2">
            {message.timestamp}
          </span>
        </div>
      </div>
    </div>
  );
});

/**
 * مكوّن مؤشر الكتابة (typing indicator)
 */
const TypingIndicator = memo(function TypingIndicator() {
  return (
