    (title: string, message: string): void => {
      const normalizedTitle = title.trim() || "تشخيص المحرر";
      const normalizedMessage = message.trim() || "حدث خطأ غير معروف.";
      setDiagnosticEvents((current) =>
        [
          {
            id: `${Date.now()}-${Math.random().toString(36).slice(2, 7)}`,
            title: normalizedTitle,
            message: normalizedMessage,
            createdAt: new Date().toISOString(),
          },
          ...current,
        ].slice(0, MAX_DIAGNOSTIC_EVENTS)
      );
    },
    []
  );

  /* ── تركيب/تدمير EditorArea مرة واحدة فقط ── */
  useEffect(() => {
    const mount = editorMountRef.current;
    if (!mount) return;

    const editorArea = new EditorArea({
      mount,
      onContentChange: (text) => setDocumentText(text),
      onStatsChange: (nextStats) => setStats(nextStats),
      onFormatChange: (format) => setCurrentFormat(format),
      onImportError: (message) => {
        recordDiagnostic("فشل تطبيق نظام الشك", message);
        toast({
          title: "فشل تطبيق نظام الشك",
          description: message,
          variant: "destructive",
        });
      },
      onProgressiveStateChange: (state) => setProgressiveSurfaceState(state),
    });
    editorAreaRef.current = editorArea;

    const snapshot = readAutosaveSnapshot();
    if (canRestoreAutosaveSnapshot(snapshot)) {
      void applyAutosaveSnapshot(editorArea, snapshot)
        .then(() => {
          setDocumentText(editorArea.getAllText());
        })
        .catch((error) => {
          const message =
            error instanceof Error
              ? error.message
              : "حدث خطأ غير معروف أثناء الاستعادة التلقائية.";
          recordDiagnostic("فشل الاستعادة التلقائية", message);
          logger.warn("Automatic autosave restore failed", {
            scope: "autosave",
            data: error,
          });
        });
    }

    return () => {
      editorArea.destroy();
      editorAreaRef.current = null;
    };
  }, [recordDiagnostic]);

  useEffect(() => {
    return subscribeIsMobile((nextIsMobile) => {
      setIsMobile(nextIsMobile);
      if (nextIsMobile) {
        setOpenSidebarItem(null);
      }
    });
  }, []);

  useEffect(() => {
    const syncActiveProjectTitle = () => {
      setActiveProjectTitle(readActiveProjectTitle());
    };

    syncActiveProjectTitle();
    window.addEventListener("storage", syncActiveProjectTitle);
    window.addEventListener(
      "directors-studio:project-changed",
      syncActiveProjectTitle
    );
    window.addEventListener(
      "directors-editor:project-synced",
      syncActiveProjectTitle
    );

    return () => {
      window.removeEventListener("storage", syncActiveProjectTitle);
      window.removeEventListener(
        "directors-studio:project-changed",
        syncActiveProjectTitle
      );
      window.removeEventListener(
        "directors-editor:project-synced",
        syncActiveProjectTitle
      );
    };
  }, []);

  /* ── استعادة يدوية للمسودة المحفوظة تلقائيًا ── */
  const restoreAutosaveDraft = useCallback(async (): Promise<void> => {
    const area = editorAreaRef.current;
    if (!area) return;

    const snapshot = readAutosaveSnapshot();

    if (!canRestoreAutosaveSnapshot(snapshot)) {
      toast({
        title: "لا توجد مسودة",
        description: "لم نعثر على مسودة محفوظة لاستعادتها.",
      });
      return;
    }

    try {
      await applyAutosaveSnapshot(area, snapshot);
      setDocumentText(area.getAllText());
      toast({
        title: "تمت استعادة المسودة",
        description: "استرجعنا آخر نسخة محفوظة تلقائيًا.",
      });
    } catch (error) {
      logger.warn("Manual autosave restore failed", {
        scope: "autosave",
        data: error,
      });
      recordDiagnostic(
        "تعذرت استعادة المسودة",
        error instanceof Error
          ? error.message
          : "حدث خطأ غير معروف أثناء استعادة المسودة."
      );
      toast({
        title: "تعذرت استعادة المسودة",
        description:
          error instanceof Error
            ? error.message
            : "حدث خطأ غير معروف أثناء استعادة المسودة.",
        variant: "destructive",
      });
    }
  }, []);

  /* ── إغلاق القوائم عند النقر خارجها ── */
  useEffect(() => {
    const closeMenus = (event: MouseEvent): void => {
      const target = event.target as HTMLElement | null;
      if (target?.closest('[data-app-menu-root="true"]')) {
        return;
      }
      setActiveMenu(null);
    };
    document.addEventListener("click", closeMenus);
    return () => document.removeEventListener("click", closeMenus);
  }, []);

  useEffect(() => {
    saveToStorage(TYPING_SETTINGS_STORAGE_KEY, typingSystemSettings);
  }, [typingSystemSettings]);

  useEffect(() => {
    const area = editorAreaRef.current;
    if (!area) return;

    scheduleAutoSave<EditorAutosaveSnapshot>(
      AUTOSAVE_DRAFT_STORAGE_KEY,
      {
        html: area.getAllHtml(),
        text: area.getAllText(),
        updatedAt: new Date().toISOString(),
        version: 2,
      },
      1500
    );
  }, [documentText]);

  /* ── تفعيل Design Tokens من constants/colors.ts ── */
  useEffect(() => {
    const rootStyle = document.documentElement.style;
    rootStyle.setProperty("--brand", brandColors.jungleGreen);
    rootStyle.setProperty("--brand-teal", brandColors.teal);
    rootStyle.setProperty("--brand-bronze", brandColors.bronze);
    rootStyle.setProperty("--ring", brandColors.jungleGreen);
    rootStyle.setProperty("--accent", semanticColors.secondary);
    rootStyle.setProperty("--accent-success", semanticColors.success);
    rootStyle.setProperty("--accent-warning", semanticColors.warning);
    rootStyle.setProperty("--accent-error", semanticColors.error);
    rootStyle.setProperty("--accent-creative", semanticColors.creative);
    rootStyle.setProperty("--accent-technical", semanticColors.technical);
    rootStyle.setProperty("--filmlane-brand-gradient", gradients.jungleFull);
    rootStyle.setProperty("--filmlane-brand-gradient-soft", gradients.jungle);
    rootStyle.setProperty("--filmlane-highlight-primary", highlightColors[0]);
    rootStyle.setProperty("--filmlane-highlight-secondary", highlightColors[1]);
    rootStyle.setProperty("--filmlane-palette-dark", colors[0]);
    rootStyle.setProperty("--filmlane-editor-font", LOCKED_EDITOR_FONT_VALUE);
    rootStyle.setProperty(
      "--filmlane-editor-size",
      `${LOCKED_EDITOR_SIZE_LABEL}pt`
    );
  }, []);

  const fileImportBackendEndpoint = resolveFileImportExtractEndpoint();
  const hasFileImportBackend = fileImportBackendEndpoint.length > 0;

  const handleTypingModeChange = (
    nextMode: TypingSystemSettings["typingSystemMode"]
  ): void => {
    setTypingSystemSettings((current) =>
      sanitizeTypingSystemSettings({
        ...current,
        typingSystemMode: nextMode,
      })
    );

    if (
      nextMode !== "auto-live" &&
      liveTypingWorkflowTimeoutRef.current !== null
    ) {
      window.clearTimeout(liveTypingWorkflowTimeoutRef.current);
      liveTypingWorkflowTimeoutRef.current = null;
    }

    logger.info("Typing system mode updated", {
      scope: "typing-system",
      data: { mode: nextMode },
    });
  };

  const handleLiveIdleMinutesChange = (nextMinutes: number): void => {
    setTypingSystemSettings((current) =>
      sanitizeTypingSystemSettings({
        ...current,
        liveIdleMinutes: nextMinutes,
      })
    );
  };

  const runDocumentThroughPasteWorkflow = useCallback(
    async (options: RunDocumentThroughPasteWorkflowOptions): Promise<void> => {
      const area = editorAreaRef.current;
      if (!area) return;
      if (area.isSurfaceLocked()) return;

      const fullText = area.getAllText().trim();
      if (!fullText) return;

      if (
        options.source === "live-idle" &&
        fullText === lastLiveWorkflowTextRef.current
      ) {
        return;
      }

      if (applyingTypingWorkflowRef.current) return;
      applyingTypingWorkflowRef.current = true;

      try {
        await area.importClassifiedText(fullText, "replace");
        lastLiveWorkflowTextRef.current = area.getAllText().trim();

        logger.info("Typing workflow executed", {
          scope: "typing-system",
          data: {
            source: options.source,
            reviewProfile: options.reviewProfile,
            policyProfile: options.policyProfile,
          },
        });

        if (!options.suppressToasts) {
          toast({
            title:
              options.source === "live-idle"
                ? "تمت المعالجة الحية"
                : "تمت المعالجة المؤجلة",
            description: "تم تمرير كامل المستند عبر مصنف اللصق وتحديث البنية.",
          });
        }
      } catch (error) {
        logger.error("Typing workflow failed", {
          scope: "typing-system",
          data: error,
        });
        if (!options.suppressToasts) {
          recordDiagnostic(
            "تعذر تشغيل نظام الكتابة",
            error instanceof Error
              ? error.message
              : "حدث خطأ غير معروف أثناء المعالجة."
          );
          toast({
            title: "تعذر تشغيل نظام الكتابة",
            description:
              error instanceof Error
                ? error.message
                : "حدث خطأ غير معروف أثناء المعالجة.",
            variant: "destructive",
          });
        }
      } finally {
        applyingTypingWorkflowRef.current = false;
      }
    },
    []
  );

  const runForcedProductionSelfCheck = useCallback(
    async (
      trigger: "manual-auto-check" | "manual-reclassify"
    ): Promise<void> => {
      const area = editorAreaRef.current;
      if (!area) return;

      try {
        const { runProductionSelfCheck } =
          await import("./extensions/production-self-check");
        const report = await runProductionSelfCheck({
          trigger,
          sampleText: area.getAllText(),
          force: true,
        });

        if (report.failedFunctions === 0) {
          toast({
            title: "فحص التكامل مكتمل",
            description: `تم تشغيل ${report.executedFunctions} دالة بنجاح عبر مسار الإنتاج.`,
          });
          return;
        }

        toast({
          title: "فحص التكامل اكتشف أخطاء",
          description: `نجح ${report.executedFunctions - report.failedFunctions} وفشل ${report.failedFunctions}.`,
          variant: "destructive",
        });
      } catch (error) {
        logger.error("Forced production self-check failed", {
          scope: "self-check",
          data: error,
        });
        recordDiagnostic(
          "تعذر تشغيل فحص التكامل",
          error instanceof Error
            ? error.message
            : "حدث خطأ غير معروف أثناء فحص التكامل."
        );
        toast({
          title: "تعذر تشغيل فحص التكامل",
          description:
            error instanceof Error
              ? error.message
              : "حدث خطأ غير معروف أثناء فحص التكامل.",
          variant: "destructive",
        });
      }
    },
    [recordDiagnostic]
  );

  useEffect(() => {
    if (typeof window === "undefined") return;

    const liveIdleDelayMs = minutesToMilliseconds(
      typingSystemSettings.liveIdleMinutes
    );
    if (typingSystemSettings.typingSystemMode !== "auto-live") {
      if (liveTypingWorkflowTimeoutRef.current !== null) {
        window.clearTimeout(liveTypingWorkflowTimeoutRef.current);
        liveTypingWorkflowTimeoutRef.current = null;
      }
      return;
    }

    const normalizedText = documentText.trim();
    if (!normalizedText) return;
    if (applyingTypingWorkflowRef.current) return;
    if (progressiveSurfaceState?.activeRun?.surfaceLocked) return;
    if (normalizedText === lastLiveWorkflowTextRef.current) return;

    if (liveTypingWorkflowTimeoutRef.current !== null) {
      window.clearTimeout(liveTypingWorkflowTimeoutRef.current);
    }

    liveTypingWorkflowTimeoutRef.current = window.setTimeout(() => {
      liveTypingWorkflowTimeoutRef.current = null;
      void runDocumentThroughPasteWorkflow({
        source: "live-idle",
        reviewProfile: "silent-live",
        policyProfile: "strict-structure",
        suppressToasts: true,
      });
    }, liveIdleDelayMs);

    return () => {
      if (liveTypingWorkflowTimeoutRef.current !== null) {
        window.clearTimeout(liveTypingWorkflowTimeoutRef.current);
        liveTypingWorkflowTimeoutRef.current = null;
      }
    };
  }, [
    documentText,
    progressiveSurfaceState?.activeRun?.surfaceLocked,
    runDocumentThroughPasteWorkflow,
    typingSystemSettings,
  ]);

  const approveCurrentVersion = useCallback(async (): Promise<void> => {
    const area = editorAreaRef.current;
    if (!area) return;

    try {
      await area.approveCurrentVersion();
      toast({
        title: "تم اعتماد النسخة",
        description: "تم وسم كل العناصر الظاهرة في النسخة المعتمدة.",
      });
    } catch (error) {
      recordDiagnostic(
        "تعذر اعتماد النسخة",
        error instanceof Error
          ? error.message
          : "حدث خطأ غير معروف أثناء اعتماد النسخة."
      );
      toast({
        title: "تعذر اعتماد النسخة",
        description:
          error instanceof Error
            ? error.message
            : "حدث خطأ غير معروف أثناء اعتماد النسخة.",
        variant: "destructive",
      });
    }
  }, [recordDiagnostic]);

  const dismissProgressiveFailure = useCallback((): void => {
    const area = editorAreaRef.current;
    if (!area) return;

    const dismissed = area.dismissProgressiveFailure();
    if (!dismissed) return;

    toast({
      title: "تم إغلاق حالة الفشل",
      description: "حافظنا على آخر نسخة صالحة وأعدنا فتح السطح لتشغيل جديد.",
    });
  }, []);

  /* ── اختصارات لوحة المفاتيح العامة ── */
  useEffect(() => {
    const handleGlobalShortcut = (event: KeyboardEvent): void => {
      if (!(event.ctrlKey || event.metaKey)) return;

      const key = event.key.toLowerCase();

      // مراقب الـ pipeline — يعمل حتى لو المحرر مش جاهز
      if (event.shiftKey && key === "m") {
        event.preventDefault();
        setShowPipelineMonitor((prev) => !prev);
        return;
      }

      const area = editorAreaRef.current;
      if (!area) return;
      const targetElement = event.target as HTMLElement | null;
      const activeElement =
        typeof document !== "undefined"
          ? (document.activeElement as HTMLElement | null)
          : null;
      const isEditorFocused = Boolean(
        targetElement?.closest(".ProseMirror") ??
          activeElement?.closest(".ProseMirror") ??
          targetElement?.isContentEditable ??
          activeElement?.isContentEditable ??
          area.editor.view.hasFocus()
      );

      if (key in SHORTCUT_FORMAT_BY_DIGIT) {
        event.preventDefault();
        const shortcutFormat = SHORTCUT_FORMAT_BY_DIGIT[key];
        if (shortcutFormat) {
          area.setFormat(shortcutFormat);
        }
        return;
      }

      switch (key) {
        case "s":
          event.preventDefault();
          void handleMenuActionRef.current?.("save-file");
          break;
        case "o":
          event.preventDefault();
          void handleMenuActionRef.current?.("open-file");
          break;
        case "n":
          event.preventDefault();
          void handleMenuActionRef.current?.("new-file");
          break;
        case "a":
          if (isEditorFocused) {
            event.preventDefault();
            area.runCommand({ command: "select-all" });
          }
          break;
        case "c":
          if (isEditorFocused || area.hasSelection()) {
            event.preventDefault();
            void handleMenuActionRef.current?.("copy");
          }
          break;
        case "x":
          if (isEditorFocused || area.hasSelection()) {
            event.preventDefault();
            void handleMenuActionRef.current?.("cut");
          }
          break;
        case "v":
          if (isEditorFocused) {
            event.preventDefault();
            void handleMenuActionRef.current?.("paste");
          }
          break;
        case "z":
          event.preventDefault();
          area.runCommand("undo");
          break;
        case "y":
          event.preventDefault();
          area.runCommand("redo");
          break;
        case "b":
          event.preventDefault();
          area.runCommand("bold");
          break;
        case "i":
          event.preventDefault();
          area.runCommand("italic");
          break;
        case "u":
          event.preventDefault();
          area.runCommand("underline");
          break;
        default:
          break;
      }
    };

    // capture: true يضمن تنفيذ المعالج قبل أي handler آخر ومنع المتصفح من اعتراض Ctrl+B/I/Z
    document.addEventListener("keydown", handleGlobalShortcut, true);
    return () =>
      document.removeEventListener("keydown", handleGlobalShortcut, true);
  }, []);

  const resolveMenuCommand = useMenuCommandResolver(editorAreaRef, toast);

  const actionDeps: EditorActionsDeps = {
    getArea: () => editorAreaRef.current,
    toast,
    resolveMenuCommand,
    isProgressiveSurfaceLocked: () =>
      editorAreaRef.current?.isSurfaceLocked() ?? false,
    runDocumentThroughPasteWorkflow,
    runForcedProductionSelfCheck,
    restoreAutosaveDraft,
    recordDiagnostic,
  };

  const dispatchMenuAction = async (actionId: MenuActionId): Promise<void> => {
    setActiveMenu(null);
    await handleMenuAction(actionId, actionDeps);
  };

  handleMenuActionRef.current = dispatchMenuAction;

  const currentFormatLabel = currentFormat
    ? FORMAT_LABEL_BY_TYPE[currentFormat]
    : "—";

  /* ──────────────────────── JSX ──────────────────────── */
  return (
    <div
      className="editor-modern-floating app-root flex h-screen flex-col overflow-hidden font-['Cairo'] selection:bg-[color:var(--mf-accent)]/25"
      dir="rtl"
      data-testid="app-root"
    >
      <BackgroundGrid />
      <AppHeader
        menuSections={MENU_SECTIONS}
        activeMenu={activeMenu}
        onToggleMenu={(sectionLabel) =>
          setActiveMenu((prev) => (prev === sectionLabel ? null : sectionLabel))
        }
        activeProjectTitle={activeProjectTitle}
        progressiveSurfaceState={progressiveSurfaceState}
        onApproveVisibleVersion={() => {
          void approveCurrentVersion();
        }}
        onDismissFailure={dismissProgressiveFailure}
        onAction={(actionId) => {
          void dispatchMenuAction(actionId as MenuActionId);
        }}
        infoDotColor={semanticColors.info}
        brandGradient={gradients.jungle}
        onlineDotColor={brandColors.jungleGreen}
      />

      <div
        className="app-main relative z-10 flex flex-1 overflow-hidden"
        suppressHydrationWarning
      >
        <div className="app-stage relative flex min-h-full min-w-0 flex-1">
          {!isCompact && (
            <AppSidebar
              sections={SIDEBAR_SECTIONS}
              openSectionId={openSidebarItem}
              isMobile={isMobile}
              documentText={documentText}
              onEditorSearchJump={(query) => {
                const area = editorAreaRef.current;
                if (!area) return;
                area.findAndFocus(query);
              }}
              onToggleSection={(sectionId) =>
                setOpenSidebarItem((prev) =>
                  prev === sectionId ? null : sectionId
                )
              }
              onItemAction={(sectionId, itemLabel) => {
                void handleSidebarItemAction(sectionId, itemLabel, actionDeps);
              }}
              settingsPanel={
                <SettingsPanel
                  typingSystemSettings={typingSystemSettings}
                  onTypingModeChange={handleTypingModeChange}
                  onLiveIdleMinutesChange={handleLiveIdleMinutesChange}
                  onRunExportClassified={() => {
                    void runExport("classified", actionDeps, "النص_المصنف");
                  }}
                  onRunProcessNow={() => {
                    void runDocumentThroughPasteWorkflow({
                      source: "manual-deferred",
                      reviewProfile: "interactive",
                      policyProfile: "strict-structure",
                    });
                  }}
                  lockedEditorFontLabel={LOCKED_EDITOR_FONT_LABEL}
                  lockedEditorSizeLabel={LOCKED_EDITOR_SIZE_LABEL}
                  supportedLegacyFormatCount={SUPPORTED_LEGACY_FORMAT_COUNT}
                  classifierOptionCount={CLASSIFIER_OPTION_COUNT}
                  actionBlockSpacing={ACTION_BLOCK_SPACING}
                  hasFileImportBackend={hasFileImportBackend}
                />
              }
            />
          )}

          <main className="app-editor-main relative flex min-w-0 flex-1 flex-col overflow-hidden">
            <AppDock
              buttons={DOCK_BUTTONS}
              isMobile={isMobile}
              isCompact={isCompact}
              onAction={(actionId) => {
                void dispatchMenuAction(actionId as MenuActionId);
              }}
            />

            <div
              className="app-editor-scroll scrollbar-none relative flex flex-1 justify-center overflow-x-hidden overflow-y-auto"
              style={{
                paddingTop: `${EDITOR_CANVAS_TOP_OFFSET_PX}px`,
                paddingRight: `${
                  isCompact
                    ? EDITOR_CANVAS_COMPACT_GUTTER_PX
                    : EDITOR_CANVAS_RIGHT_RESERVE_PX
                }px`,
                paddingLeft: `${
                  isCompact
                    ? EDITOR_CANVAS_COMPACT_GUTTER_PX
                    : EDITOR_CANVAS_LEFT_GUTTER_PX
                }px`,
                paddingBottom: `${EDITOR_CANVAS_BOTTOM_OFFSET_PX}px`,
              }}
              onClick={(e) => {
                // منح التركيز للمحرر عند النقر في المنطقة البيضاء خارج الورقة
                const target = e.target as HTMLElement;
                if (target.closest(".ProseMirror")) return;
                editorAreaRef.current?.focusEditor();
              }}
            >
              <DotBackground />
              <div
                className="app-editor-shell relative mx-auto w-full pb-20"
                style={{
                  maxWidth: `${
                    isCompact
                      ? EDITOR_CANVAS_COMPACT_SHELL_WIDTH_PX
                      : EDITOR_CANVAS_WIDTH_PX
                  }px`,
                  minWidth: `${
                    isCompact
                      ? EDITOR_CANVAS_COMPACT_SHELL_WIDTH_PX
                      : EDITOR_CANVAS_WIDTH_PX
                  }px`,
                }}
              >
                <div
                  ref={editorMountRef}
                  className="editor-area app-editor-host"
                  data-testid="editor-area"
                />
              </div>
            </div>
          </main>
        </div>
      </div>

      <AppFooter
        stats={stats}
        currentFormatLabel={currentFormatLabel}
        isMobile={isMobile}
      />

      <PipelineMonitor
        visible={showPipelineMonitor}
        progressiveSurfaceState={progressiveSurfaceState}
        onDismissFailure={dismissProgressiveFailure}
        onClose={() => setShowPipelineMonitor(false)}
      />

      {diagnosticEvents.length > 0 ? (
        <aside
          className="editor-diagnostics-log fixed right-4 bottom-20 z-50 w-[min(92vw,420px)] rounded-2xl border border-red-500/25 bg-red-950/85 p-3 text-right text-red-50 shadow-2xl backdrop-blur-xl"
          data-testid="editor-diagnostics-log"
          role="status"
          aria-live="polite"
        >
          <div className="mb-2 text-xs font-bold">سجل تشخيص المحرر</div>
          <div className="space-y-2">
            {diagnosticEvents.map((event) => (
              <div
                key={event.id}
                className="rounded-xl border border-white/10 bg-white/5 p-2"
              >
                <div className="text-xs font-bold">{event.title}</div>
                <div className="mt-1 text-[11px] leading-5 text-red-100/85">
                  {event.message}
                </div>
              </div>
            ))}
          </div>
        </aside>
      ) : null}

      <div className="sr-only">
        {screenplayFormats.map((format) => (
          <span key={format.id}>{format.label}</span>
        ))}
      </div>
    </div>
  );
}

import { User, type LucideIcon } from "lucide-react";
import React, { useCallback, useEffect, useId, useMemo, useRef } from "react";

import { HoverBorderGradient } from "@/components/ui/hover-border-gradient";

import type { ProgressiveSurfaceState } from "../editor";

/**
 * عنصر قائمة واحد داخل قائمة منسدلة من قوائم الهيدر.
 */
export interface AppShellMenuItem {
  label: string;
  actionId: string;
  shortcut?: string;
  icon?: LucideIcon;
  iconGlyph?: string;
  disabled?: boolean;
}

/**
 * قسم قائمة علوي (ملف، تعديل، إضافة، أدوات، مساعدة).
 */
export interface AppShellMenuSection {
  label: string;
  items: readonly AppShellMenuItem[];
}

export interface AppHeaderProps {
  menuSections: readonly AppShellMenuSection[];
  activeMenu: string | null;
  onToggleMenu: (sectionLabel: string) => void;
  activeProjectTitle: string | null;
  progressiveSurfaceState: ProgressiveSurfaceState | null;
  onApproveVisibleVersion: () => void;
  onDismissFailure: () => void;
  onAction: (actionId: string) => void;
  infoDotColor: string;
  brandGradient: string;
  onlineDotColor: string;
}

const toTestId = (value: string): string =>
  value.trim().toLowerCase().replace(/\s+/g, "-");

const isEnabled = (item: AppShellMenuItem): boolean => !item.disabled;

/**
 * شريط القوائم العلوي للمحرر.
 *
 * إعادة التصميم البصرية فقط: تحويل الشريط الممتد إلى مجموعات عائمة (clusters)
 * فوق سطح ورقي دافئ. كل السلوكيات (WAI-ARIA Menubar، تنقل الأسهم،
 * فتح/إغلاق القوائم، تركيز أول عنصر، Escape/Tab/Enter، RTL navigation)
 * محفوظة بالكامل بدون تعديل.
 */
export function AppHeader({
  menuSections,
  activeMenu,
  onToggleMenu,
  activeProjectTitle,
  progressiveSurfaceState,
  onApproveVisibleVersion,
  onDismissFailure,
  onAction,
  infoDotColor,
  brandGradient,
  onlineDotColor,
}: AppHeaderProps): React.JSX.Element {
  const menubarId = useId();
  const menubarButtonRefs = useRef<Record<string, HTMLButtonElement | null>>(
    {}
  );
  const menuItemRefs = useRef<Record<string, HTMLButtonElement | null>>({});
  const previouslyActiveMenuRef = useRef<string | null>(null);
  const pendingFocusFirstItemRef = useRef<string | null>(null);

  const activeRun = progressiveSurfaceState?.activeRun ?? null;
  const visibleVersion = progressiveSurfaceState?.visibleVersion ?? null;
  const approvalEligible =
    activeRun?.status === "settled" &&
    visibleVersion?.approvalEligible === true;
  const isApproved = activeRun?.status === "approved";
  const hasRecoverableFailure =
    activeRun?.status === "failed-after-visible" &&
    activeRun.failureRecoveryRequired;
  const statusLabel = isApproved
    ? "معتمد"
    : hasRecoverableFailure
      ? "فشل بعد الظهور"
      : activeRun?.status === "settled"
        ? "مستقر"
        : activeRun?.surfaceLocked
          ? "قيد المعالجة"
          : "جاهز";

  const sectionIndex = useMemo(() => {
    const map = new Map<string, number>();
    menuSections.forEach((section, index) => map.set(section.label, index));
    return map;
  }, [menuSections]);

  const getSiblingSectionLabel = useCallback(
    (
      fromLabel: string,
      direction: "next" | "prev" | "first" | "last"
    ): string | null => {
      if (menuSections.length === 0) return null;
      if (direction === "first") return menuSections[0]?.label ?? null;
      if (direction === "last")
        return menuSections[menuSections.length - 1]?.label ?? null;
      const currentIndex = sectionIndex.get(fromLabel);
      if (currentIndex === undefined) return null;
      const delta = direction === "next" ? 1 : -1;
      const nextIndex =
        (currentIndex + delta + menuSections.length) % menuSections.length;
      return menuSections[nextIndex]?.label ?? null;
    },
    [menuSections, sectionIndex]
  );

  const focusSectionButton = useCallback((sectionLabel: string): void => {
    const target = menubarButtonRefs.current[sectionLabel];
    if (target) {
      target.focus();
    }
  }, []);

  const focusMenuItem = useCallback(
    (sectionLabel: string, itemIndex: number): void => {
      const key = `${sectionLabel}::${itemIndex}`;
      const target = menuItemRefs.current[key];
      if (target) {
        target.focus();
      }
    },
    []
  );

  const getFirstEnabledIndex = useCallback(
    (section: AppShellMenuSection): number => {
      return section.items.findIndex(isEnabled);
    },
    []
  );

  const getLastEnabledIndex = useCallback(
    (section: AppShellMenuSection): number => {
      for (let i = section.items.length - 1; i >= 0; i -= 1) {
        const candidate = section.items[i];
        if (candidate && isEnabled(candidate)) return i;
      }
      return -1;
    },
    []
  );

  const stepEnabledIndex = useCallback(
    (
      section: AppShellMenuSection,
      fromIndex: number,
      direction: 1 | -1
    ): number => {
      const length = section.items.length;
      if (length === 0) return -1;
      let cursor = fromIndex;
      for (let step = 0; step < length; step += 1) {
        cursor = (cursor + direction + length) % length;
        const candidate = section.items[cursor];
        if (candidate && isEnabled(candidate)) return cursor;
      }
      return -1;
    },
    []
  );

  useEffect(() => {
    if (activeMenu && previouslyActiveMenuRef.current !== activeMenu) {
      const section = menuSections.find((item) => item.label === activeMenu);
      if (section) {
        const targetIndex =
          pendingFocusFirstItemRef.current === activeMenu
            ? getFirstEnabledIndex(section)
            : getFirstEnabledIndex(section);
        if (targetIndex >= 0) {
          requestAnimationFrame(() => {
            focusMenuItem(activeMenu, targetIndex);
          });
        }
      }
      pendingFocusFirstItemRef.current = null;
    }

    if (!activeMenu && previouslyActiveMenuRef.current) {
      const lastLabel = previouslyActiveMenuRef.current;
      requestAnimationFrame(() => {
        focusSectionButton(lastLabel);
      });
    }

    previouslyActiveMenuRef.current = activeMenu;
  }, [
    activeMenu,
    menuSections,
    focusMenuItem,
    focusSectionButton,
    getFirstEnabledIndex,
  ]);

  const handleSectionButtonKeyDown = useCallback(
    (
      event: React.KeyboardEvent<HTMLButtonElement>,
      sectionLabel: string
    ): void => {
      const key = event.key;
      if (key === "ArrowRight") {
        event.preventDefault();
        const target = getSiblingSectionLabel(sectionLabel, "prev");
        if (target) focusSectionButton(target);
        return;
      }
      if (key === "ArrowLeft") {
        event.preventDefault();
        const target = getSiblingSectionLabel(sectionLabel, "next");
        if (target) focusSectionButton(target);
        return;
      }
      if (key === "Home") {
        event.preventDefault();
        const target = getSiblingSectionLabel(sectionLabel, "first");
        if (target) focusSectionButton(target);
        return;
      }
      if (key === "End") {
        event.preventDefault();
        const target = getSiblingSectionLabel(sectionLabel, "last");
        if (target) focusSectionButton(target);
        return;
      }
      if (key === "ArrowDown" || key === "Enter" || key === " ") {
        event.preventDefault();
        pendingFocusFirstItemRef.current = sectionLabel;
        if (activeMenu !== sectionLabel) {
          onToggleMenu(sectionLabel);
        } else {
          const section = menuSections.find(
            (item) => item.label === sectionLabel
          );
          if (section) {
            const firstIndex = getFirstEnabledIndex(section);
            if (firstIndex >= 0) focusMenuItem(sectionLabel, firstIndex);
          }
        }
        return;
      }
      if (key === "Escape") {
        if (activeMenu) {
          event.preventDefault();
          onToggleMenu(activeMenu);
        }
      }
    },
    [
      activeMenu,
      onToggleMenu,
      menuSections,
      focusMenuItem,
      focusSectionButton,
      getFirstEnabledIndex,
      getSiblingSectionLabel,
    ]
  );

  const handleMenuItemKeyDown = useCallback(
    (
      event: React.KeyboardEvent<HTMLButtonElement>,
      sectionLabel: string,
      itemIndex: number
    ): void => {
      const key = event.key;
      const section = menuSections.find((item) => item.label === sectionLabel);
      if (!section) return;

      if (key === "ArrowDown") {
        event.preventDefault();
        const next = stepEnabledIndex(section, itemIndex, 1);
        if (next >= 0) focusMenuItem(sectionLabel, next);
        return;
      }
      if (key === "ArrowUp") {
        event.preventDefault();
        const prev = stepEnabledIndex(section, itemIndex, -1);
        if (prev >= 0) focusMenuItem(sectionLabel, prev);
        return;
      }
      if (key === "Home") {
        event.preventDefault();
        const first = getFirstEnabledIndex(section);
        if (first >= 0) focusMenuItem(sectionLabel, first);
        return;
      }
      if (key === "End") {
        event.preventDefault();
        const last = getLastEnabledIndex(section);
        if (last >= 0) focusMenuItem(sectionLabel, last);
        return;
      }
      if (key === "Escape") {
        event.preventDefault();
        onToggleMenu(sectionLabel);
        focusSectionButton(sectionLabel);
        return;
      }
      if (key === "Tab") {
        if (activeMenu === sectionLabel) {
          onToggleMenu(sectionLabel);
        }
        return;
      }
      if (key === "ArrowRight" || key === "ArrowLeft") {
        event.preventDefault();
        const direction = key === "ArrowRight" ? "prev" : "next";
        const target = getSiblingSectionLabel(sectionLabel, direction);
        if (!target) return;
        if (activeMenu === sectionLabel) {
          onToggleMenu(sectionLabel);
        }
        pendingFocusFirstItemRef.current = target;
        onToggleMenu(target);
        return;
      }
      if (key === "Enter" || key === " ") {
        event.preventDefault();
        const targetItem = section.items[itemIndex];
        if (targetItem && isEnabled(targetItem)) {
          onAction(targetItem.actionId);
        }
      }
    },
    [
      activeMenu,
      menuSections,
      onAction,
      onToggleMenu,
      focusMenuItem,
      focusSectionButton,
      getFirstEnabledIndex,
      getLastEnabledIndex,
      getSiblingSectionLabel,
      stepEnabledIndex,
    ]
  );

  return (
    <header
      className="app-header relative z-40 flex h-[68px] flex-shrink-0 items-center justify-between px-6"
      data-app-menu-root="true"
      data-testid="app-header"
      role="banner"
    >
      {/* مجموعة يمين (بصريًا في RTL): الهوية + شريط القوائم */}
      <div className="app-header-primary flex items-center gap-3">
        <HoverBorderGradient
          containerClassName="app-header-brand rounded-full"
          className="flex h-11 items-center gap-2.5 bg-transparent px-5"
          duration={2}
        >
          <span
            className="h-1.5 w-1.5 rounded-full"
            style={{
              backgroundColor: infoDotColor,
              boxShadow: `0 0 8px ${infoDotColor}66`,
            }}
            aria-hidden="true"
          />
          <span
            className="bg-clip-text text-[15px] font-bold text-transparent"
            style={{ backgroundImage: brandGradient }}
          >
            أفان تيتر
          </span>
        </HoverBorderGradient>

        <HoverBorderGradient
          as="div"
          role="menubar"
          aria-label="شريط القوائم الرئيسي"
          aria-orientation="horizontal"
          id={menubarId}
          containerClassName="app-header-menubar rounded-full"
          className="relative z-50 flex h-11 items-center gap-1 bg-transparent p-1"
          duration={2}
        >
          {menuSections.map((section) => {
            const sectionTestId = toTestId(section.label);
            const menuId = `${menubarId}-menu-${sectionTestId}`;
            const buttonId = `${menubarId}-button-${sectionTestId}`;
            const isOpen = activeMenu === section.label;
            return (
              <div
                key={section.label}
                className="group relative h-full"
                onClick={(event) => {
                  event.stopPropagation();
                }}
              >
                <button
                  type="button"
                  id={buttonId}
                  ref={(element) => {
                    menubarButtonRefs.current[section.label] = element;
                  }}
                  role="menuitem"
                  aria-haspopup="menu"
                  aria-expanded={isOpen}
                  aria-controls={isOpen ? menuId : undefined}
                  tabIndex={activeMenu ? (isOpen ? 0 : -1) : 0}
                  className={`flex h-full min-w-[72px] items-center justify-center rounded-full px-4 text-[13px] font-medium transition-all outline-none focus-visible:ring-2 focus-visible:ring-[color:var(--mf-accent)] focus-visible:ring-offset-2 focus-visible:ring-offset-white ${
                    isOpen
                      ? "bg-[color:var(--mf-surface-soft)] text-[color:var(--mf-text-strong)] shadow-inner"
                      : "bg-transparent text-[color:var(--mf-text-muted)] hover:bg-[color:var(--mf-surface-soft)] hover:text-[color:var(--mf-text-strong)]"
                  }`}
                  onClick={() => onToggleMenu(section.label)}
                  onKeyDown={(event) =>
                    handleSectionButtonKeyDown(event, section.label)
                  }
                  data-testid={`menu-section-${sectionTestId}`}
                >
                  {section.label}
                </button>

                {isOpen && (
                  <div
                    id={menuId}
                    role="menu"
                    aria-label={section.label}
                    aria-orientation="vertical"
                    className="mf-surface absolute top-full right-0 z-50 mt-2 min-w-[220px] overflow-hidden p-1.5"
                  >
                    {section.items.map((item, itemIndex) => {
                      const itemKey = `${section.label}::${itemIndex}`;
                      return (
                        <button
                          type="button"
                          key={itemKey}
                          role="menuitem"
                          ref={(element) => {
                            menuItemRefs.current[itemKey] = element;
                          }}
                          disabled={item.disabled}
                          aria-disabled={item.disabled ? true : undefined}
                          tabIndex={-1}
                          onClick={() => {
                            if (!isEnabled(item)) return;
                            onAction(item.actionId);
                          }}
                          onKeyDown={(event) =>
                            handleMenuItemKeyDown(
                              event,
                              section.label,
                              itemIndex
                            )
                          }
                          data-testid={`menu-action-${item.actionId}`}
                          className={`flex w-full items-center gap-2 rounded-xl px-3 py-2 text-right text-[13px] transition-colors outline-none ${
                            item.disabled
                              ? "cursor-not-allowed text-[color:var(--mf-text-faint)]"
                              : "text-[color:var(--mf-text)] hover:bg-[color:var(--mf-surface-soft)] hover:text-[color:var(--mf-text-strong)] focus-visible:bg-[color:var(--mf-surface-soft)] focus-visible:text-[color:var(--mf-text-strong)]"
                          }`}
                        >
                          <span className="flex-1 text-right">
                            {item.label}
                          </span>
                          {item.shortcut && (
                            <span
                              className="text-[10px] text-[color:var(--mf-text-faint)]"
                              aria-hidden="true"
                            >
                              {item.shortcut}
                            </span>
                          )}
                          {item.iconGlyph && (
                            <span
                              className="w-4 text-center text-[13px] text-[color:var(--mf-text-muted)]"
                              aria-hidden="true"
                            >
                              {item.iconGlyph}
                            </span>
                          )}
                          {item.icon && (
                            <item.icon
                              className="size-4 text-[color:var(--mf-text-muted)]"
                              aria-hidden="true"
                            />
                          )}
                          {item.shortcut && (
                            <span className="sr-only">
                              اختصار لوحة المفاتيح {item.shortcut}
                            </span>
                          )}
                        </button>
                      );
                    })}
                  </div>
                )}
              </div>
            );
          })}
        </HoverBorderGradient>
      </div>

      {/* مجموعة يسار (بصريًا في RTL): الحالة، الاعتماد، المشروع، الحساب، النسخة */}
      <div className="app-header-secondary flex items-center gap-2">
        {(activeRun ?? visibleVersion) && (
          <div
            className="mf-pill flex h-11 items-center gap-2 px-4 text-[11px] font-bold"
            data-testid="app-header-status"
          >
            <span className="text-[color:var(--mf-text-muted)]">الحالة</span>
            <span
              className="text-[color:var(--mf-text-strong)]"
              aria-live="polite"
            >
              {statusLabel}
            </span>
          </div>
        )}

        {approvalEligible && (
          <button
            type="button"
            onClick={onApproveVisibleVersion}
            className="app-header-status-approve flex h-11 items-center px-4 text-[11px] font-bold transition-colors focus-visible:ring-2 focus-visible:ring-[color:var(--mf-success)] focus-visible:outline-none"
            data-testid="approve-visible-version"
          >
            اعتماد النسخة
          </button>
        )}

        {hasRecoverableFailure && (
          <button
            type="button"
            onClick={onDismissFailure}
            className="app-header-status-dismiss flex h-11 items-center px-4 text-[11px] font-bold transition-colors focus-visible:ring-2 focus-visible:ring-[color:var(--mf-warning)] focus-visible:outline-none"
            data-testid="dismiss-progressive-failure"
          >
            إغلاق الفشل
          </button>
        )}

        <HoverBorderGradient
          containerClassName="rounded-full"
          className="flex h-11 items-center gap-2 bg-transparent px-4 text-[11px] font-bold tracking-wider text-[color:var(--mf-text-muted)] uppercase"
          duration={2}
        >
          <span
            className="h-1.5 w-1.5 animate-pulse rounded-full"
            style={{ backgroundColor: onlineDotColor }}
            aria-hidden="true"
          />
          <span aria-label="حالة الاتصال: متصل">Online</span>
        </HoverBorderGradient>

        {activeProjectTitle ? (
          <HoverBorderGradient
            containerClassName="rounded-full max-w-[260px]"
            className="flex h-11 items-center gap-2 bg-transparent px-4 text-[11px] text-[color:var(--mf-text)]"
            duration={2}
          >
            <span className="text-[color:var(--mf-text-muted)]">المشروع</span>
            <span className="truncate font-bold">{activeProjectTitle}</span>
          </HoverBorderGradient>
        ) : null}

        <HoverBorderGradient
          containerClassName="rounded-full h-11 w-11"
          className="flex h-full w-full cursor-pointer items-center justify-center bg-transparent"
          duration={2}
        >
          <User
            className="size-4 text-[color:var(--mf-text-muted)]"
            aria-label="الحساب"
          />
        </HoverBorderGradient>

        <HoverBorderGradient
          containerClassName="rounded-full"
          className="group flex h-11 cursor-pointer items-center gap-2.5 bg-transparent px-5 leading-none"
          duration={2}
        >
          <span
            className="bg-clip-text text-[15px] font-bold text-transparent"
            style={{ backgroundImage: brandGradient }}
          >
            النسخة
          </span>
          <span
            className="h-1.5 w-1.5 rounded-full"
            style={{ backgroundColor: onlineDotColor }}
            aria-hidden="true"
          />
        </HoverBorderGradient>
      </div>
    </header>
  );
}

