/**
 * إنشاء محرر السيناريو
 */
export function createScreenplayEditor(element: HTMLElement): Editor {
  // تخصيص مستند (Document) لقبول عناصر السيناريو فقط
  const ScreenplayDocument = Document.extend({
    content: "block+",
  });

  const editor = new Editor({
    element,
    extensions: [
      ScreenplayDocument,
      Text,
      Bold,
      Italic,
      Underline,
      TextAlign.configure({
        types: [
          "basmala",
          "scene_header_top_line",
          "scene_header_1",
          "scene_header_2",
          "scene_header_3",
          "action",
          "character",
          "dialogue",
          "parenthetical",
          "transition",
        ],
        alignments: ["left", "center", "right"],
      }),
      ScreenplayPages.configure({
        pageFormat: SCREENPLAY_PAGE_FORMAT,
        pageGap: PAGE_GAP_PX,
        headerTopMargin: 0,
        footerBottomMargin: 0,
        pageBreakBackground: "#060808",
        header: PAGES_HEADER_TEMPLATE,
        footer: PAGES_FOOTER_TEMPLATE,
      }),
      ScreenplayHistory,
      // عناصر السيناريو المخصصة
      Basmala,
      SceneHeaderTopLine,
      SceneHeader1,
      SceneHeader2,
      SceneHeader3,
      Action,
      Character,
      Dialogue,
      Parenthetical,
      Transition,
      // أوامر السيناريو واختصارات لوحة المفاتيح
      ScreenplayCommands,
      // تصنيف النص الملصوق تلقائياً
      PasteClassifier,
    ],
    content: getDefaultContent(),
    editorProps: {
      attributes: {
        class: "tiptap",
        spellcheck: "true",
        dir: "rtl",
      },
    },
    autofocus: true,
  });

  return editor;
}

/**
