 *   نماذج لجميع عناصر السيناريو الأساسية (بسملة، رأس مشهد، حدث، شخصية، حوار، انتقال).
 *   يُستخدم كقيمة أولية لخاصية `content` في مثيل Tiptap Editor.
 *
 * @returns {string} سلسلة HTML تمثل محتوى السيناريو الافتراضي مع `data-type` attributes.
 */
function getDefaultContent(): string {
  return `<div data-type="action"></div>`;
}

/**
 * @module extensions/ai-context-layer
 * @description
 * طبقة السياق المُعزَّزة بـ Gemini Flash — Frontend integration.
 *
 * تستدعي Backend route عبر SSE وتستقبل تصحيحات streaming
 * ثم تطبّقها على المحرر تدريجياً عبر ProgressiveUpdateSession.
 *
 * يُصدّر:
 * - {@link requestContextEnhancement} — الدالة الرئيسية لاستدعاء طبقة السياق
 * - {@link ContextEnhancementResult} — نتيجة عملية التعزيز
 */

import { resolveContextEnhanceEndpoint } from "../utils/backend-endpoints";
import { logger } from "../utils/logger";

import { isElementType } from "./classification-types";

import type {
  AICorrectionCommand,
  ProgressiveUpdateSession,
} from "./ai-progressive-updater";
import type { ClassifiedLine } from "./classification-types";
import type { EditorView } from "@tiptap/pm/view";



// ─── الأنواع ──────────────────────────────────────────────────────

/** نتيجة عملية تعزيز السياق */
export interface ContextEnhancementResult {
  readonly success: boolean;
  readonly totalCorrections: number;
  readonly appliedCorrections: number;
  readonly latencyMs: number;
  readonly error?: string;
}

/** خيارات استدعاء طبقة السياق */
export interface ContextEnhancementOptions {
  /** معرف الجلسة */
  readonly sessionId: string;
  /** السطور المُصنّفة محلياً */
  readonly classifiedLines: readonly ClassifiedLine[];
  /** جلسة التحديث التدريجي */
  readonly updateSession: ProgressiveUpdateSession;
  /** EditorView للتطبيق */
  readonly view: EditorView;
  /** AbortSignal للإلغاء */
  readonly signal?: AbortSignal;
}

// ─── الثوابت ──────────────────────────────────────────────────────

const contextLogger = logger.createScope("ai-context-layer");

/** عنوان الـ endpoint — يُقرأ من متغيرات البيئة */
const resolveContextEndpoint = (): string => {
  const envValue = (
    process.env.NEXT_PUBLIC_AI_CONTEXT_ENDPOINT
  )?.trim();
  if (envValue) return envValue;
  return resolveContextEnhanceEndpoint();
};

/** هل الطبقة مفعّلة */
const isContextLayerEnabled = (): boolean => {
  const rawValue = (
    process.env.NEXT_PUBLIC_AI_CONTEXT_ENABLED
  )
    ?.trim()
    .toLowerCase();
  if (!rawValue) return true; // مفعّلة بالـ default
  return !["0", "false", "off", "no"].includes(rawValue);
};

// ─── SSE Parser ───────────────────────────────────────────────────

/**
 * يقرأ SSE stream ويستخرج الأحداث.
 *
 * @yields كل حدث SSE كـ { event, data }
 */
async function* parseSSEStream(
  reader: ReadableStreamDefaultReader<Uint8Array>,
  signal?: AbortSignal
): AsyncGenerator<{ event: string; data: string }> {
  const decoder = new TextDecoder();
  let buffer = "";

  try {
    while (true) {
      if (signal?.aborted) break;

      const { done, value } = await reader.read();
      if (done) break;

      buffer += decoder.decode(value, { stream: true });

      // SSE events مفصولة بـ \n\n
      const events = buffer.split("\n\n");
      // آخر عنصر ممكن يكون غير مكتمل
      buffer = events.pop() ?? "";

      for (const rawEvent of events) {
        if (!rawEvent.trim()) continue;

        let eventType = "message";
        let data = "";

        for (const line of rawEvent.split("\n")) {
          if (line.startsWith("event: ")) {
            eventType = line.slice(7).trim();
          } else if (line.startsWith("data: ")) {
            data = line.slice(6);
          }
        }

        if (data) {
          yield { event: eventType, data };
        }
      }
    }
  } finally {
    reader.releaseLock();
  }
}

// ─── الدالة الرئيسية ─────────────────────────────────────────────

/**
 * يستدعي طبقة السياق المُعزَّزة بـ Gemini Flash.
 *
 * يرسل السطور المُصنّفة للـ backend،
 * يستقبل تصحيحات streaming،
 * ويطبّقها على المحرر تدريجياً.
 */
export const requestContextEnhancement = async (
  options: ContextEnhancementOptions
): Promise<ContextEnhancementResult> => {
  const { sessionId, classifiedLines, updateSession, view, signal } = options;

  if (!isContextLayerEnabled()) {
    return {
      success: true,
      totalCorrections: 0,
      appliedCorrections: 0,
      latencyMs: 0,
    };
  }

  if (classifiedLines.length === 0) {
    return {
      success: true,
      totalCorrections: 0,
      appliedCorrections: 0,
      latencyMs: 0,
    };
  }

  const endpoint = resolveContextEndpoint();
  const startedAt = Date.now();
  let totalCorrections = 0;
  let appliedCorrections = 0;

  try {
    contextLogger.info("context-enhance-request", {
      sessionId,
      lineCount: classifiedLines.length,
      endpoint,
    });

    // تحضير البيانات — بنبعت بس المعلومات المطلوبة (مش النص الكامل)
    const payload = {
      sessionId,
      classifiedLines: classifiedLines.map((line) => ({
        text: line.text,
        assignedType: line.assignedType,
        confidence: line.originalConfidence,
      })),
    };

    const response = await fetch(
      endpoint,
      definedProps({
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify(payload),
        signal,
      })
    );

    if (!response.ok) {
      const errorText = await response.text();
      throw new Error(
        `Context enhance failed (${response.status}): ${errorText}`
      );
    }

    if (!response.body) {
      throw new Error("Response body is null — SSE not supported.");
    }

    const reader = response.body.getReader();

    for await (const sseEvent of parseSSEStream(reader, signal)) {
      if (view.isDestroyed || updateSession.status === "aborted") break;

      if (sseEvent.event === "correction") {
        try {
          const correction = JSON.parse(sseEvent.data);
          totalCorrections += 1;

          // تحويل إلى AICorrectionCommand
          if (
            typeof correction.correctedType === "string" &&
            isElementType(correction.correctedType)
          ) {
            const command: AICorrectionCommand = {
              lineIndex: correction.lineIndex,
              correctedType: correction.correctedType,
              confidence: correction.confidence ?? 0.8,
              reason: correction.reason ?? "",
              source: "gemini-context",
            };

            if (updateSession.applyCorrection(view, command)) {
              appliedCorrections += 1;
            }
          }
        } catch {
          // تجاهل JSON غير صالح
        }
      } else if (sseEvent.event === "error") {
        try {
          const errorData = JSON.parse(sseEvent.data);
          contextLogger.error("context-enhance-stream-error", {
            sessionId,
            message: errorData.message,
          });
        } catch {
          // تجاهل
        }
      } else if (sseEvent.event === "done") {
        contextLogger.info("context-enhance-stream-done", {
          sessionId,
          totalCorrections,
          appliedCorrections,
        });
      }
    }

    const latencyMs = Date.now() - startedAt;
    return {
      success: true,
      totalCorrections,
      appliedCorrections,
      latencyMs,
    };
  } catch (error) {
    const message = error instanceof Error ? error.message : String(error);
    const isAbort =
      error instanceof DOMException && error.name === "AbortError";

    if (!isAbort) {
      contextLogger.error("context-enhance-failed", {
        sessionId,
        error: message,
      });
    }

    return {
      success: false,
      totalCorrections,
      appliedCorrections,
      latencyMs: Date.now() - startedAt,
      error: message,
    };
  }
};
import { definedProps } from "@/lib/defined-props";

/**
 * @module extensions/classification-sequence-rules
 * @description
 * قواعد تسلسل التصنيف — يحدد التسلسلات الصالحة بين أنواع عناصر السيناريو
 * ودرجات خطورة الانتهاكات.
 *
 * يُصدّر:
 * - {@link SequenceSuggestionFeatures} — خصائص السطر المُستخدمة لاقتراح النوع
 * - {@link CLASSIFICATION_VALID_SEQUENCES} — خريطة التسلسلات الصالحة (نوع → أنواع تالية مسموحة)
 * - {@link CLASSIFICATION_SEQUENCE_VIOLATION_SEVERITY} — درجة خطورة كل انتهاك تسلسل
 * - {@link suggestTypeFromClassificationSequence} — يقترح النوع التالي بناءً على النوع السابق والخصائص
 *
 * يُستهلك في {@link PostClassificationReviewer} لكشف انتهاكات التسلسل.
 */
import type { ElementType } from "./classification-types";
export const CLASSIFICATION_VALID_SEQUENCES: ReadonlyMap<
  string,
  ReadonlySet<string>
> = new Map([
  ["character", new Set(["dialogue", "parenthetical"])],
  ["parenthetical", new Set(["dialogue"])],
  [
    "dialogue",
    new Set(["dialogue", "action", "character", "transition", "parenthetical"]),
  ],
  ["action", new Set(["action", "character", "transition", "scene_header_1"])],
  ["transition", new Set(["scene_header_1", "action"])],
  ["scene_header_1", new Set(["scene_header_2", "scene_header_3", "action"])],
  ["scene_header_2", new Set(["scene_header_3", "action", "character"])],
  ["scene_header_3", new Set(["action", "character"])],
  ["basmala", new Set(["scene_header_1", "action", "character"])],
]);

export const CLASSIFICATION_SEQUENCE_VIOLATION_SEVERITY: ReadonlyMap<
  string,
  number
> = new Map([
  ["character→character", 95],
  ["character→action", 80],
  ["character→transition", 80],
  ["parenthetical→action", 90],
  ["parenthetical→character", 90],
  ["parenthetical→transition", 90],
  ["transition→dialogue", 80],
  ["transition→character", 75],
  ["scene_header_1→dialogue", 70],
  ["scene_header_2→dialogue", 70],
  ["scene_header_3→dialogue", 70],
  ["scene_header_1→action", 75],
  ["scene_header_1→character", 75],
  ["scene_header_2→action", 75],
  ["scene_header_2→character", 75],
]);

export interface ClassificationSequenceSuggestionFeatures {
  isParenthetical: boolean;
  endsWithColon: boolean;
  wordCount: number;
  hasPunctuation: boolean;
  startsWithDash: boolean;
  hasActionIndicators: boolean;
}

export const suggestTypeFromClassificationSequence = (
  prevType: ElementType | string,
  features: ClassificationSequenceSuggestionFeatures
): ElementType | null => {
  if (prevType === "character") {
    return features.isParenthetical
      ? ("parenthetical")
      : ("dialogue");
  }

  if (prevType === "parenthetical") {
    return "dialogue";
  }

  if (prevType === "dialogue") {
    if (features.startsWithDash || features.hasActionIndicators) {
      return "action";
    }
    if (
      features.endsWithColon ||
      (features.wordCount <= 3 && !features.hasPunctuation)
    ) {
      return "character";
    }
    return "action";
  }

  if (prevType === "transition") {
    return "scene_header_1";
  }

  if (prevType === "scene_header_1") {
    return "scene_header_2";
  }

  if (prevType === "scene_header_2") {
    return "scene_header_3";
  }

  if (prevType === "scene_header_3") {
    return "action";
  }

  return null;
};

/**
