/**
 * @module pipeline-diagnostics
 * @description أداة تشخيص تلقائية — تشغّل الـ pipeline بكل تركيبة flags
 *   وتقارن النتايج مع الـ baseline في ضربة واحدة.
 *
 *   الاستخدام من الـ console:
 *     window.__diagnosePipeline()          // يستخدم النص الموجود في المحرر
 *     window.__diagnosePipeline(myText)    // يستخدم نص مخصص
 */
import {
  classifyLines,
  PIPELINE_FLAGS,
  type ClassifyLinesContext,
} from "./paste-classifier";
import { registerPipelineRecorderUI } from "./pipeline-recorder";

import type { ClassifiedDraftWithId } from "./paste-classifier-helpers";

// ─── أنواع التقرير ────────────────────────────────────────────────

type FlagKey = keyof typeof PIPELINE_FLAGS;

interface LayerDiff {
  lineIndex: number;
  text: string;
  baselineType: string;
  variantType: string;
  baselineConfidence: number;
  variantConfidence: number;
}

interface LayerReport {
  flag: FlagKey;
  totalLines: number;
  changedLines: number;
  changeRate: string;
  diffs: LayerDiff[];
  typeDistDelta: Record<string, number>;
}

interface DiagnosticReport {
  timestamp: string;
  inputLines: number;
  baselineTypeDist: Record<string, number>;
  layers: LayerReport[];
  /** الطبقات مرتبة من الأكثر تأثير للأقل */
  ranking: { flag: FlagKey; changedLines: number; changeRate: string }[];
  /** تركيبة كل الطبقات مع بعض */
  allOnReport: LayerReport;
}

// ─── دوال مساعدة ──────────────────────────────────────────────────

const ALL_FLAGS: FlagKey[] = [
  "DCG_ENABLED",
  "SELF_REFLECTION_ENABLED",
  "RETRO_NEW_PATTERNS_ENABLED",
  "REVERSE_PASS_ENABLED",
  "VITERBI_OVERRIDE_ENABLED",
];

/** حفظ الحالة الحالية واسترجاعها */
const snapshotFlags = (): Record<FlagKey, boolean> => ({ ...PIPELINE_FLAGS });

const restoreFlags = (snapshot: Record<FlagKey, boolean>): void => {
  for (const key of ALL_FLAGS) {
    (PIPELINE_FLAGS)[key] = snapshot[key];
  }
};

const setAllFlags = (value: boolean): void => {
  for (const key of ALL_FLAGS) {
    (PIPELINE_FLAGS)[key] = value;
  }
};

const typeDist = (
  classified: readonly ClassifiedDraftWithId[]
): Record<string, number> => {
  const dist: Record<string, number> = {};
  for (const item of classified) {
    dist[item.type] = (dist[item.type] ?? 0) + 1;
  }
  return dist;
};

const diffClassified = (
  baseline: readonly ClassifiedDraftWithId[],
  variant: readonly ClassifiedDraftWithId[]
): LayerDiff[] => {
  const diffs: LayerDiff[] = [];
  const len = Math.max(baseline.length, variant.length);
  for (let i = 0; i < len; i++) {
    const b = baseline[i];
    const v = variant[i];
    if (!b || !v) {
      diffs.push({
        lineIndex: i,
        text: (b?.text ?? v?.text ?? "").slice(0, 60),
        baselineType: b?.type ?? "—",
        variantType: v?.type ?? "—",
        baselineConfidence: b?.confidence ?? 0,
        variantConfidence: v?.confidence ?? 0,
      });
      continue;
    }
    if (b.type !== v.type) {
      diffs.push({
        lineIndex: i,
        text: b.text.slice(0, 60),
        baselineType: b.type,
        variantType: v.type,
        baselineConfidence: b.confidence,
        variantConfidence: v.confidence,
      });
    }
  }
  return diffs;
};

const typeDistDelta = (
  baselineDist: Record<string, number>,
  variantDist: Record<string, number>
): Record<string, number> => {
  const allTypes = new Set([
    ...Object.keys(baselineDist),
    ...Object.keys(variantDist),
  ]);
  const delta: Record<string, number> = {};
  for (const t of allTypes) {
    const d = (variantDist[t] ?? 0) - (baselineDist[t] ?? 0);
    if (d !== 0) delta[t] = d;
  }
  return delta;
};

// ─── المحرك الرئيسي ──────────────────────────────────────────────

const runWithFlags = (
  text: string,
  ctx?: ClassifyLinesContext
): ClassifiedDraftWithId[] => {
  return classifyLines(text, ctx);
};

/**
 * يشغّل التشخيص الكامل ويرجع تقرير مفصّل.
 */
export const diagnosePipeline = (
  text: string,
  ctx?: ClassifyLinesContext
): DiagnosticReport => {
  const saved = snapshotFlags();

  try {
    // ── 1) Baseline: كل الطبقات OFF ──
    setAllFlags(false);
    const baseline = runWithFlags(text, ctx);
    const baselineDist = typeDist(baseline);

    // ── 2) كل طبقة لوحدها ──
    const layers: LayerReport[] = [];
    for (const flag of ALL_FLAGS) {
      setAllFlags(false);
      (PIPELINE_FLAGS)[flag] = true;

      const variant = runWithFlags(text, ctx);
      const diffs = diffClassified(baseline, variant);
      const vDist = typeDist(variant);

      layers.push({
        flag,
        totalLines: variant.length,
        changedLines: diffs.length,
        changeRate:
          baseline.length > 0
            ? ((diffs.length / baseline.length) * 100).toFixed(1) + "%"
            : "0%",
        diffs,
        typeDistDelta: typeDistDelta(baselineDist, vDist),
      });
    }

    // ── 3) كل الطبقات ON مع بعض ──
    setAllFlags(true);
    const allOn = runWithFlags(text, ctx);
    const allOnDiffs = diffClassified(baseline, allOn);
    const allOnDist = typeDist(allOn);
    const allOnReport: LayerReport = {
      flag: "ALL_ON" as FlagKey,
      totalLines: allOn.length,
      changedLines: allOnDiffs.length,
      changeRate:
        baseline.length > 0
          ? ((allOnDiffs.length / baseline.length) * 100).toFixed(1) + "%"
          : "0%",
      diffs: allOnDiffs,
      typeDistDelta: typeDistDelta(baselineDist, allOnDist),
    };

    // ── 4) ترتيب الطبقات بالتأثير ──
    const ranking = layers
      .map((l) => ({
        flag: l.flag,
        changedLines: l.changedLines,
        changeRate: l.changeRate,
      }))
      .sort((a, b) => b.changedLines - a.changedLines);

    return {
      timestamp: new Date().toISOString(),
      inputLines: baseline.length,
      baselineTypeDist: baselineDist,
      layers,
      ranking,
      allOnReport,
    };
  } finally {
    restoreFlags(saved);
  }
};

// ─── عرض التقرير في الـ console ────────────────────────────────────

const printReport = (report: DiagnosticReport): void => {
  console.warn(
    "%c╔══════════════════════════════════════════════════════╗",
    "color: #00ff88; font-weight: bold"
  );
  console.warn(
    "%c║      🔬 Pipeline Layer Diagnostics Report           ║",
    "color: #00ff88; font-weight: bold"
  );
  console.warn(
    "%c╚══════════════════════════════════════════════════════╝",
    "color: #00ff88; font-weight: bold"
  );

  console.warn(`\n📊 Baseline: ${report.inputLines} lines`);

  console.table(report.baselineTypeDist);

  console.warn(
    "\n%c🏆 Layer Impact Ranking (من الأكثر تأثير للأقل):",
    "color: #ffcc00; font-weight: bold"
  );

  console.table(
    report.ranking.map((r) => ({
      "🏷️ Layer": r.flag,
      "📐 Changed Lines": r.changedLines,
      "📊 Change Rate": r.changeRate,
    }))
  );

  // تفاصيل كل طبقة
  for (const layer of report.layers) {
    if (layer.changedLines === 0) {
      console.warn(`\n✅ ${layer.flag}: لا تغيير`);
      continue;
    }

    console.warn(
      `\n%c⚠️ ${layer.flag}: ${layer.changedLines} lines changed (${layer.changeRate})`,
      "color: #ff6b6b; font-weight: bold"
    );

    if (Object.keys(layer.typeDistDelta).length > 0) {
      console.warn("   Type distribution delta:");

      console.table(layer.typeDistDelta);
    }

    // أول 10 تغييرات كمثال
    const sample = layer.diffs.slice(0, 10);

    console.table(
      sample.map((d) => ({
        "Line#": d.lineIndex,
        Text: d.text.slice(0, 40),
        Baseline: d.baselineType,
        "→ Variant": d.variantType,
        "Δ Conf":
          d.variantConfidence - d.baselineConfidence > 0
            ? `+${d.variantConfidence - d.baselineConfidence}`
            : `${d.variantConfidence - d.baselineConfidence}`,
      }))
    );
    if (layer.diffs.length > 10) {
      console.warn(`   ... و ${layer.diffs.length - 10} تغيير تاني`);
    }
  }

  // ALL ON
  console.warn(
    `\n%c🔥 ALL LAYERS ON: ${report.allOnReport.changedLines} lines changed (${report.allOnReport.changeRate})`,
    "color: #ff00ff; font-weight: bold"
  );
  if (report.allOnReport.diffs.length > 0) {
    console.table(
      report.allOnReport.diffs.slice(0, 15).map((d) => ({
        "Line#": d.lineIndex,
        Text: d.text.slice(0, 40),
        Baseline: d.baselineType,
        "→ All ON": d.variantType,
      }))
    );
  }

  console.warn("\n%c─── Full report object: ───", "color: #888");
  console.warn(report);
};

// ─── ربط بالـ window للاستخدام من الـ console ──────────────────────

const isPipelineConsoleDebugEnabled = (): boolean => {
  if (typeof window === "undefined") return false;
  try {
    return window.localStorage.getItem("filmlane.pipeline.debug") === "true";
  } catch {
    return false;
  }
};

/**
 * يسجّل `window.__diagnosePipeline` و `window.__lastDiagReport`.
 *
 * @param getEditorText - دالة ترجع النص الحالي من المحرر
 */
export const registerPipelineDiagnostics = (
  getEditorText: () => string
): void => {
  if (typeof window === "undefined") return;

  const win = window as unknown as Record<string, unknown>;

  win["__diagnosePipeline"] = (
    customText?: string,
    ctx?: ClassifyLinesContext
  ): DiagnosticReport => {
    const text = customText ?? getEditorText();
    if (!text.trim()) {
      console.warn("⚠️ مفيش نص — افتح ملف الأول أو مرّر نص كـ argument");
      return {} as DiagnosticReport;
    }

    console.warn(`🔬 Running diagnostics on ${text.length} chars...`);
    const t0 = performance.now();
    const report = diagnosePipeline(text, ctx);
    const elapsed = (performance.now() - t0).toFixed(0);
    console.warn(`⏱️ Done in ${elapsed}ms\n`);

    printReport(report);
    win["__lastDiagReport"] = report;
    return report;
  };

  // ── تسجيل أدوات الـ Pipeline Recorder (رادار شامل) ──
  registerPipelineRecorderUI();

  if (isPipelineConsoleDebugEnabled()) {
    console.warn(
      "%c🔬 Pipeline diagnostics ready! Run: __diagnosePipeline()",
      "color: #00ff88; font-weight: bold; font-size: 13px"
    );
  }
};

/**
 * @module extensions/pipeline-recorder
 * @description
 * رادار شامل — يسجّل كل مراحل الـ pipeline من لحظة اللصق حتى آخر تصحيح AI.
 *
 * يأخذ snapshot في كل مرحلة ويحسب الـ diffs بين كل مرحلتين متتاليتين.
 * يسجّل تصحيحات AI بشكل فردي (applied/skipped).
 *
 * الاستخدام من الـ console:
 *   window.__showPipelineRun()        // تقرير مُنسّق بالجداول
 *   window.__showLineJourney(15)      // رحلة سطر واحد عبر كل المراحل
 *   window.__lastPipelineRun          // الـ raw data
 *
 * يُصدّر:
 * - {@link pipelineRecorder} — الـ singleton
 * - {@link registerPipelineRecorderUI} — ربط بالـ window
 */

import { definedProps } from "@/lib/defined-props";

type PipelineRecorderDebugWindow = Window & {
  __lastPipelineRun?: PipelineRunReport | null;
  __showPipelineRun?: () => void;
  __showLineJourney?: (lineIndex: number) => void;
  __pipelineRecorderUiRegistered?: boolean;
};

const isPipelineConsoleDebugEnabled = (): boolean => {
  if (typeof window === "undefined") return false;
  try {
    return window.localStorage.getItem("filmlane.pipeline.debug") === "true";
  } catch {
    return false;
  }
};

// ─── الأنواع ──────────────────────────────────────────────────────

/** سطر واحد في snapshot (خفيف — بدون النص الكامل) */
export interface SnapshotLine {
  readonly type: string;
  readonly confidence: number;
  readonly method: string;
  readonly text: string; // أول 50 حرف
}

/** snapshot لمرحلة واحدة */
export interface PipelineSnapshot {
  readonly stage: string;
  readonly timestamp: number; // performance.now()
  readonly lines: readonly SnapshotLine[];
  readonly metadata?: Record<string, unknown>;
}

/** تغيير سطر بين مرحلتين */
export interface LineChange {
  readonly lineIndex: number;
  readonly text: string;
  readonly fromType: string;
  readonly toType: string;
  readonly confidenceDelta: number;
}

/** diff بين مرحلتين متتاليتين */
export interface StageDiff {
  readonly fromStage: string;
  readonly toStage: string;
  readonly latencyMs: number;
  readonly changes: readonly LineChange[];
}

/** تصحيح AI مسجّل */
export interface RecordedAICorrection {
  readonly lineIndex: number;
  readonly text: string;
  readonly previousType: string;
  readonly correctedType: string;
  readonly confidence: number;
  readonly source: string;
  readonly applied: boolean;
  readonly reason?: string;
}

export interface RecordedApproval {
  readonly runId: string;
  readonly approvedVersionId: string;
  readonly replacesVersionId: string | null;
  readonly elementCount: number;
  readonly approvedAt: string;
}

/** تقرير run كامل */
export interface PipelineRunReport {
  readonly runId: string;
  readonly source: string;
  readonly sourceType?: string;
  readonly intakeKind?: "paste" | "file-open";
  readonly fileName?: string | null;
  readonly startTime: number;
  endTime: number;
  totalDurationMs: number;
  readonly input: { textLength: number; lineCount: number };
  readonly snapshots: PipelineSnapshot[];
  readonly diffs: StageDiff[];
  readonly aiCorrections: RecordedAICorrection[];
  readonly approvals: RecordedApproval[];
  finalTypeDist: Record<string, number>;
  failure?: {
    stage: string;
    message: string;
    code?: string;
  };
}

// ─── Snapshot Line Builder ────────────────────────────────────────

const toSnapshotLine = (item: {
  type: string;
  text: string;
  confidence: number;
  classificationMethod?: string;
}): SnapshotLine => ({
  type: item.type,
  confidence: item.confidence,
  method: item.classificationMethod ?? "unknown",
  text: item.text.slice(0, 50),
});

// ─── Diff Engine ──────────────────────────────────────────────────

const computeDiff = (
  from: PipelineSnapshot,
  to: PipelineSnapshot
): StageDiff => {
  const changes: LineChange[] = [];
  const len = Math.max(from.lines.length, to.lines.length);

  for (let i = 0; i < len; i++) {
    const f = from.lines[i];
    const t = to.lines[i];
    if (!f || !t) {
      // سطر مضاف أو محذوف
      changes.push({
        lineIndex: i,
        text: (f?.text ?? t?.text ?? "").slice(0, 50),
        fromType: f?.type ?? "—",
        toType: t?.type ?? "—",
        confidenceDelta: (t?.confidence ?? 0) - (f?.confidence ?? 0),
      });
      continue;
    }
    if (f.type !== t.type) {
      changes.push({
        lineIndex: i,
        text: f.text,
        fromType: f.type,
        toType: t.type,
        confidenceDelta: t.confidence - f.confidence,
      });
    }
  }

  return {
    fromStage: from.stage,
    toStage: to.stage,
    latencyMs: Math.round(to.timestamp - from.timestamp),
    changes,
  };
};

// ─── Type Distribution ────────────────────────────────────────────

const computeTypeDist = (
  lines: readonly SnapshotLine[]
): Record<string, number> => {
  const dist: Record<string, number> = {};
  for (const line of lines) {
    dist[line.type] = (dist[line.type] ?? 0) + 1;
  }
  return dist;
};

// ─── Event Bus ────────────────────────────────────────────────────

export type PipelineEvent =
  | {
      kind: "run-start";
      runId: string;
      source: string;
      sourceType?: string;
      intakeKind?: "paste" | "file-open";
      fileName?: string | null;
      input: { textLength: number; lineCount: number };
    }
  | {
      kind: "snapshot";
      stage: string;
      lineCount: number;
      changes: number;
      latencyMs: number;
      metadata?: Record<string, unknown>;
      activeFiles: string[];
    }
  | { kind: "ai-correction"; correction: RecordedAICorrection }
  | { kind: "approval"; approval: RecordedApproval }
  | {
      kind: "run-failure";
      stage: string;
      message: string;
      code?: string;
    }
  | {
      kind: "run-end";
      totalDurationMs: number;
      totalVerdicts: number;
      finalTypeDist: Record<string, number>;
      outcome: "settled" | "failed-after-visible";
    }
  | {
      kind: "engine-bridge";
      source: string;
      elementCount: number;
      latencyMs: number;
    }
  | { kind: "file-open"; fileName: string; fileType: string; mode: string }
  | {
      kind: "file-extract-done";
      fileName: string;
      method: string;
      usedOcr: boolean;
      textLength: number;
      schemaElementCount: number;
      latencyMs: number;
    };

type PipelineEventListener = (event: PipelineEvent) => void;

// ─── الفئة الرئيسية ──────────────────────────────────────────────

class PipelineRecorder {
  private _currentRun: PipelineRunReport | null = null;
  private _lastCompletedRun: PipelineRunReport | null = null;
  private readonly _listeners = new Set<PipelineEventListener>();
  private readonly _trackedFiles = new Set<string>();

  subscribe(listener: PipelineEventListener): () => void {
    this._listeners.add(listener);
    return () => {
      this._listeners.delete(listener);
    };
  }

  private _emit(event: PipelineEvent): void {
    for (const listener of this._listeners) {
      try {
        listener(event);
      } catch {
        /* سلامة — لا نوقف الـ pipeline بسبب خطأ UI */
      }
    }
  }

  /**
   * بداية run جديد — يُستدعى عند أول مرحلة في الـ pipeline.
   */
  startRun(
    source: string,
    input: { textLength: number; lineCount: number },
    metadata?: {
      sourceType?: string;
      intakeKind?: "paste" | "file-open";
      fileName?: string | null;
    }
  ): void {
    const runId = `run-${Date.now()}-${Math.random().toString(36).slice(2, 6)}`;
    this._currentRun = {
      runId,
      source,
      fileName: metadata?.fileName ?? null,
      startTime: performance.now(),
      endTime: 0,
      totalDurationMs: 0,
      input,
      snapshots: [],
      diffs: [],
      aiCorrections: [],
      approvals: [],
      finalTypeDist: {},
      ...definedProps({
        sourceType: metadata?.sourceType,
        intakeKind: metadata?.intakeKind,
      }),
    };
    this._emit({
      kind: "run-start" as const,
      runId,
      source,
      fileName: metadata?.fileName ?? null,
      input,
      ...definedProps({
        sourceType: metadata?.sourceType,
        intakeKind: metadata?.intakeKind,
      }),
    });
  }

  /**
   * تسجيل snapshot لمرحلة.
   *
   * @param stage - اسم المرحلة (مثل "forward-pass", "retroactive")
   * @param classified - مصفوفة العناصر المصنفة
   * @param metadata - بيانات إضافية (مثل عدد التصحيحات لكل pattern)
   */
  snapshot(
    stage: string,
    classified: readonly {
      type: string;
      text: string;
      confidence: number;
      classificationMethod?: string;
    }[],
    metadata?: Record<string, unknown>
  ): void {
    if (!this._currentRun) return;

    const snap: PipelineSnapshot = definedProps({
      stage,
      timestamp: performance.now(),
      lines: classified.map(toSnapshotLine),
      metadata,
    });

    const snaps = this._currentRun.snapshots;
    snaps.push(snap);

    let changes = 0;
    let latencyMs = 0;
    // حساب diff مع المرحلة السابقة
    if (snaps.length >= 2) {
      const prev = snaps.at(-2);
      if (prev) {
        const diff = computeDiff(prev, snap);
        (this._currentRun.diffs).push(diff);
        changes = diff.changes.length;
        latencyMs = diff.latencyMs;
      }
    }

    const activeFiles = [...this._trackedFiles];
    this._trackedFiles.clear();
    this._emit({
      kind: "snapshot",
      stage,
      lineCount: classified.length,
      changes,
      latencyMs,
      activeFiles,
      ...definedProps({ metadata }),
    });
  }

  /**
   * تسجيل تصحيح AI (من progressive updater).
   */
  logAICorrection(correction: RecordedAICorrection): void {
    if (!this._currentRun) return;
    (this._currentRun.aiCorrections).push(correction);
    this._emit({ kind: "ai-correction", correction });
  }

  logApproval(approval: RecordedApproval): void {
    const targetRun = this._currentRun ?? this._lastCompletedRun;
    if (!targetRun) return;
    (targetRun.approvals).push(approval);
    this._emit({ kind: "approval", approval });
  }

  logRunFailure(stage: string, message: string, code?: string): void {
    if (!this._currentRun) return;
    this._currentRun.failure = definedProps({ stage, message, code });
    this._emit({
      kind: "run-failure" as const,
      stage,
      message,
      ...definedProps({ code }),
    });
  }

  /**
   * رصد ملف كود اشتغل — يُستدعى من الملفات نفسها عند تنفيذ دوالها.
   */
  trackFile(fileName: string): void {
    this._trackedFiles.add(fileName);
  }

  /**
   * رصد استدعاء البريدج — observation only بدون لمس حالة الـ run.
   */
  logBridgeCall(source: string, elementCount: number, latencyMs: number): void {
    this._emit({ kind: "engine-bridge", source, elementCount, latencyMs });
  }

  /**
   * رصد فتح ملف — بداية رحلة الملف.
   */
  logFileOpen(fileName: string, fileType: string, mode: string): void {
    this._emit({ kind: "file-open", fileName, fileType, mode });
  }

  /**
   * رصد انتهاء استخراج الملف — الباك إند خلص.
   */
  logFileExtractDone(info: {
    fileName: string;
    method: string;
    usedOcr: boolean;
    textLength: number;
    schemaElementCount: number;
    latencyMs: number;
  }): void {
    this._emit({ kind: "file-extract-done", ...info });
  }

  /**
   * إنهاء الـ run الحالي.
   */
  finishRun(): void {
    if (!this._currentRun) return;

    this._currentRun.endTime = performance.now();
    this._currentRun.totalDurationMs = Math.round(
      this._currentRun.endTime - this._currentRun.startTime
    );

    // حساب الـ type distribution النهائي
    const lastSnap =
      this._currentRun.snapshots[this._currentRun.snapshots.length - 1];
    if (lastSnap) {
      this._currentRun.finalTypeDist = computeTypeDist(lastSnap.lines);
    }

    this._emit({
      kind: "run-end",
      totalDurationMs: this._currentRun.totalDurationMs,
      totalVerdicts: this._currentRun.aiCorrections.filter((c) => c.applied)
        .length,
      finalTypeDist: this._currentRun.finalTypeDist,
      outcome: this._currentRun.failure ? "failed-after-visible" : "settled",
    });

    this._lastCompletedRun = this._currentRun;
    this._currentRun = null;
  }

  /**
   * هل فيه run شغّال دلوقتي؟
   */
  get isRunning(): boolean {
    return this._currentRun !== null;
  }

  /**
   * آخر run اتسجّل (أو الشغّال حالياً).
   */
  get lastRun(): PipelineRunReport | null {
    return this._currentRun ?? this._lastCompletedRun;
  }
}

// ─── Singleton ────────────────────────────────────────────────────

export const pipelineRecorder = new PipelineRecorder();

// ─── Console UI ───────────────────────────────────────────────────

const printRunReport = (report: PipelineRunReport): void => {
  console.warn(
    "%c╔══════════════════════════════════════════════════════╗",
    "color: #00ccff; font-weight: bold"
  );
  console.warn(
    "%c║      📡 Pipeline Run Report                          ║",
    "color: #00ccff; font-weight: bold"
  );
  console.warn(
    "%c╚══════════════════════════════════════════════════════╝",
    "color: #00ccff; font-weight: bold"
  );

  // ── ملخص عام ──
  const frontendMs =
    report.snapshots.length >= 2
      ? Math.round(
          (report.snapshots.find((s) => s.stage === "render-first")
            ?.timestamp ??
            report.snapshots[report.snapshots.length - 1]?.timestamp ??
            0) - (report.snapshots[0]?.timestamp ?? 0)
        )
      : 0;
  const aiMs = report.totalDurationMs - frontendMs;

  console.warn(
    `\n📋 Source: ${report.source} | ${report.input.lineCount} lines | ${report.input.textLength} chars`
  );
  console.warn(
    `⏱️ Total: ${(report.totalDurationMs / 1000).toFixed(1)}s (frontend: ${frontendMs}ms, AI: ${(aiMs / 1000).toFixed(1)}s)`
  );
  console.warn(`🆔 Run ID: ${report.runId}`);

  // ── جدول المراحل ──
  console.warn(
    "\n%c━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━",
    "color: #888"
  );
  console.warn(
    "%c📊 Stage-by-Stage Progression:",
    "color: #ffcc00; font-weight: bold"
  );

  const stageTable = report.snapshots.map((snap, idx) => {
    const diff = idx > 0 ? report.diffs[idx - 1] : null;
    const prevSnap = idx > 0 ? report.snapshots[idx - 1] : null;
    const latency = prevSnap
      ? Math.round(snap.timestamp - prevSnap.timestamp)
      : 0;

    return {
      "#": idx + 1,
      Stage: snap.stage,
      Lines: snap.lines.length,
      Changes: diff ? diff.changes.length : "—",
      Duration: idx === 0 ? "—" : `${latency}ms`,
      Notes: snap.metadata
        ? Object.entries(snap.metadata)
            .map(([k, v]) => `${k}=${v}`)
            .join(", ")
            .slice(0, 60)
        : "",
    };
  });

  console.table(stageTable);

  // ── Type Distribution النهائي ──
  console.warn(
    "\n%c📦 Final Type Distribution:",
    "color: #00ff88; font-weight: bold"
  );

  console.table(report.finalTypeDist);

  // ── Diffs بين المراحل ──
  for (const diff of report.diffs) {
    if (diff.changes.length === 0) continue;

    console.warn(
      `\n%c🔄 ${diff.fromStage} → ${diff.toStage}: ${diff.changes.length} changes (${diff.latencyMs}ms)`,
      "color: #ff6b6b; font-weight: bold"
    );

    const sample = diff.changes.slice(0, 15);

    console.table(
      sample.map((c) => ({
        "Line#": c.lineIndex,
        Text: c.text.slice(0, 40),
        Before: c.fromType,
        "→ After": c.toType,
        "Δ Conf":
          c.confidenceDelta > 0
            ? `+${c.confidenceDelta}`
            : `${c.confidenceDelta}`,
      }))
    );
    if (diff.changes.length > 15) {
      console.warn(`   ... و ${diff.changes.length - 15} تغيير تاني`);
    }
  }

  // ── تصحيحات AI ──
  const applied = report.aiCorrections.filter((c) => c.applied);
  const skipped = report.aiCorrections.filter((c) => !c.applied);

  if (report.aiCorrections.length > 0) {
    console.warn(
      "\n%c━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━",
      "color: #888"
    );
    console.warn(
      `%c🤖 AI Corrections: ${applied.length} applied, ${skipped.length} skipped`,
      "color: #ff00ff; font-weight: bold"
    );

    // تجميع حسب المصدر
    const bySource = new Map<string, { applied: number; skipped: number }>();
    for (const c of report.aiCorrections) {
      const entry = bySource.get(c.source) ?? { applied: 0, skipped: 0 };
      if (c.applied) entry.applied++;
      else entry.skipped++;
      bySource.set(c.source, entry);
    }

    console.table(
      Object.fromEntries(
        Array.from(bySource.entries()).map(([source, stats]) => [source, stats])
      )
    );

    if (applied.length > 0) {
      console.warn(
        "\n%c✅ Applied AI Corrections:",
        "color: #00ff88; font-weight: bold"
      );

      console.table(
        applied.slice(0, 20).map((c) => ({
          "Line#": c.lineIndex,
          Text: c.text.slice(0, 35),
          From: c.previousType,
          "→ To": c.correctedType,
          Conf: c.confidence.toFixed(2),
          Source: c.source,
        }))
      );
    }
  }

  console.warn("\n%c─── Full report object: ───", "color: #888");
  console.warn(report);
};

const printLineJourney = (
  report: PipelineRunReport,
  lineIndex: number
): void => {
  console.warn(
    `%c📍 Line Journey: #${lineIndex}`,
    "color: #00ccff; font-weight: bold; font-size: 14px"
  );

  // بحث عن النص من أول snapshot
  const firstSnap = report.snapshots[0];
  const lineText = firstSnap?.lines[lineIndex]?.text ?? "???";
  console.warn(`   "${lineText}"\n`);

  // رحلة عبر الـ snapshots
  const journey: {
    Stage: string;
    Type: string;
    Confidence: number;
    Method: string;
    Changed: string;
  }[] = [];

  let prevType: string | null = null;
  for (const snap of report.snapshots) {
    const line = snap.lines[lineIndex];
    if (!line) continue;

    const changed =
      prevType !== null && line.type !== prevType
        ? `⚠️ ${prevType} → ${line.type}`
        : prevType === null
          ? "—"
          : "✅ unchanged";

    journey.push({
      Stage: snap.stage,
      Type: line.type,
      Confidence: line.confidence,
      Method: line.method,
      Changed: changed,
    });

    prevType = line.type;
  }

  console.table(journey);

  // تصحيحات AI لهذا السطر
  const aiForLine = report.aiCorrections.filter(
    (c) => c.lineIndex === lineIndex
  );
  if (aiForLine.length > 0) {
    console.warn(
      `\n%c🤖 AI corrections for this line:`,
      "color: #ff00ff; font-weight: bold"
    );

    console.table(
      aiForLine.map((c) => ({
        Source: c.source,
        From: c.previousType,
        "→ To": c.correctedType,
        Conf: c.confidence.toFixed(2),
        Applied: c.applied ? "✅" : "❌",
      }))
    );
  }

  // الحالة النهائية
  const lastSnap = report.snapshots[report.snapshots.length - 1];
  const finalLine = lastSnap?.lines[lineIndex];
  const lastAIApplied = aiForLine.filter((c) => c.applied).pop();

  const finalType = lastAIApplied?.correctedType ?? finalLine?.type ?? "???";
  console.warn(
    `\n   Final type: %c${finalType}`,
    "color: #00ff88; font-weight: bold; font-size: 14px"
  );
};

// ─── ربط بالـ window ──────────────────────────────────────────────

/**
 * يسجّل `__showPipelineRun` و `__showLineJourney` و `__lastPipelineRun` على الـ window.
 */
export const registerPipelineRecorderUI = (): void => {
  if (typeof window === "undefined") return;

  const win = window as PipelineRecorderDebugWindow;
  const shouldLogReady =
    !win.__pipelineRecorderUiRegistered && isPipelineConsoleDebugEnabled();

  Object.defineProperty(win, "__lastPipelineRun", {
    get: () => pipelineRecorder.lastRun,
    configurable: true,
  });

  win.__showPipelineRun = (): void => {
    const report = pipelineRecorder.lastRun;
    if (!report) {
      console.warn("⚠️ مفيش pipeline run مسجّل — الصق نص أو افتح ملف الأول");
      return;
    }
    printRunReport(report);
  };

  win.__showLineJourney = (lineIndex: number): void => {
    const report = pipelineRecorder.lastRun;
    if (!report) {
      console.warn("⚠️ مفيش pipeline run مسجّل — الصق نص أو افتح ملف الأول");
      return;
    }
    if (typeof lineIndex !== "number" || lineIndex < 0) {
      console.warn("⚠️ ادخل رقم السطر: __showLineJourney(15)");
      return;
    }
    printLineJourney(report, lineIndex);
  };

  win.__pipelineRecorderUiRegistered = true;

  if (shouldLogReady) {
    console.warn(
      "%c📡 Pipeline recorder ready! After paste/import, run: __showPipelineRun() or __showLineJourney(lineIndex)",
      "color: #00ccff; font-weight: bold; font-size: 13px"
    );
  }
};

import { logger } from "../utils/logger";

import { classifyText } from "./paste-classifier";

export type ProductionSelfCheckTrigger =
  | "editor-import"
  | "manual-auto-check"
  | "manual-reclassify";

export interface ProductionSelfCheckOptions {
  trigger: ProductionSelfCheckTrigger;
  sampleText?: string;
  force?: boolean;
}

export interface ProductionSelfCheckReport {
  trigger: ProductionSelfCheckTrigger;
  executedFunctions: number;
  failedFunctions: number;
  uiFunctionsExecuted: number;
  extensionFunctionsExecuted: number;
  durationMs: number;
  failures: readonly { name: string; message: string }[];
}

const selfCheckLogger = logger.createScope("production-self-check");

let hasExecutedSelfCheck = false;
let lastReport: ProductionSelfCheckReport | null = null;
let inFlightSelfCheck: Promise<ProductionSelfCheckReport> | null = null;

const safeMessage = (error: unknown): string =>
  error instanceof Error ? error.message : String(error);

const runExtensionChecks = (sampleText: string): number => {
  const classified = classifyText(sampleText);
  if (classified.length === 0) {
    throw new Error("Classification returned no lines.");
  }
  return 1;
};

export const runProductionSelfCheck = async (
  options: ProductionSelfCheckOptions
): Promise<ProductionSelfCheckReport> => {
  if (!options.force && hasExecutedSelfCheck && lastReport) {
    return lastReport;
  }

  if (!options.force && inFlightSelfCheck) {
    return inFlightSelfCheck;
  }

  const run = (async (): Promise<ProductionSelfCheckReport> => {
    const startedAt = performance.now();
    const failures: { name: string; message: string }[] = [];

    const sampleText =
      (options.sampleText ?? "ثم يدخل أحمد إلى البيت.").trim() ||
      "ثم يدخل أحمد إلى البيت.";

    let extensionFunctionsExecuted = 0;

    try {
      extensionFunctionsExecuted += runExtensionChecks(sampleText);
    } catch (error) {
      failures.push({ name: "classification", message: safeMessage(error) });
    }

    const report: ProductionSelfCheckReport = {
      trigger: options.trigger,
      executedFunctions: extensionFunctionsExecuted,
      failedFunctions: failures.length,
      uiFunctionsExecuted: 0,
      extensionFunctionsExecuted,
      durationMs: Math.round(performance.now() - startedAt),
      failures,
    };

    hasExecutedSelfCheck = true;
    lastReport = report;

    selfCheckLogger.info("Production self-check completed", report);

    return report;
  })();

  inFlightSelfCheck = run;

  try {
    return await run;
  } finally {
    inFlightSelfCheck = null;
  }
};

/**
 * @module extensions/reverse-classification-pass
 * @description
 * ممر تصنيف عكسي — يقرأ السيناريو من النهاية للبداية.
 *
 * الـ forward pass بيبني سياق "اللي فات" بس. الـ reverse pass بيدي كل سطر
 * سياق "اللي جاي" — لما ندمج الاتنين، كل سطر عنده معلومات من الاتجاهين.
 *
 * المراحل:
 * 1. Reverse Classification: تصنيف عكسي داخل كل مشهد على حده
 * 2. Merge: دمج forward + reverse — الاتفاق بيرفع الثقة، الاختلاف بيصلح
 *
 * يُصدّر:
 * - {@link ReverseClassificationResult} — نتيجة الـ reverse pass
 * - {@link reverseClassificationPass} — التصنيف العكسي
 * - {@link mergeForwardReverse} — دمج النتيجتين
 *
 * يُستهلك في {@link PasteClassifier} → `classifyLines()` بعد الـ forward pass.
 */

import { logger } from "../utils/logger";

import { collectActionEvidence } from "./action";
import { CLASSIFICATION_VALID_SEQUENCES } from "./classification-sequence-rules";
import { hasDirectDialogueCues } from "./dialogue";
import { pipelineRecorder } from "./pipeline-recorder";
import {
  normalizeLine,
  isActionVerbStart,
  hasActionVerbStructure,
  isActionCueLine,
} from "./text-utils";

import type { ClassifiedDraft, ElementType } from "./classification-types";
import type { DocumentContextGraph } from "./document-context-graph";


const reverseLogger = logger.createScope("reverse-pass");

// ─── الأنواع ──────────────────────────────────────────────────────

/** نتيجة الـ reverse classification pass */
export interface ReverseClassificationResult {
  /** النوع العكسي لكل سطر (null = لا اقتراح) */
  readonly reverseTypes: readonly (ElementType | null)[];
  /** ثقة التصنيف العكسي لكل سطر */
  readonly reverseConfidences: readonly number[];
}

// ─── ثوابت ─────────────────────────────────────────────────────────

/** الحد الأقصى لنسبة التغييرات المسموحة من الـ merge */
const MAX_MERGE_CHANGE_RATIO = 0.1;

/** الحد الأدنى لثقة الـ regex عشان ما نغيرهوش */
const REGEX_CONFIDENCE_FLOOR = 90;

// ─── أدوات مساعدة ──────────────────────────────────────────────────

/** عدد كلمات السطر */
const wordCount = (text: string): number =>
  normalizeLine(text).split(/\s+/).filter(Boolean).length;

/** هل السطر يشبه character هيكلياً؟ */
const looksLikeCharacterStructurally = (line: string): boolean => {
  const normalized = normalizeLine(line);
  if (!normalized) return false;
  if (!/[:：]\s*$/.test(normalized)) return false;
  if (wordCount(normalized) > 4) return false;
  if (/^[-–—]/.test(normalized)) return false;
  return true;
};

/** هل النوع الجديد يعدّي sequence rules؟ */
const isValidSequence = (
  fromType: ElementType,
  toType: ElementType
): boolean => {
  const validNext = CLASSIFICATION_VALID_SEQUENCES.get(fromType);
  if (!validNext) return true;
  return validNext.has(toType);
};

// ─── التصنيف العكسي ───────────────────────────────────────────────

/**
 * تصنيف سطر واحد بسياق عكسي (الأنواع اللي **بعده**).
 *
 * @param line - السطر المطبّع
 * @param futureTypes - الأنواع اللي بعد السطر ده (أقربهم أولاً)
 * @param forwardDraft - نتيجة الـ forward pass لنفس السطر
 * @returns نوع + ثقة
 */
const classifyWithReverseContext = (
  line: string,
  futureTypes: ElementType[],
  forwardDraft: ClassifiedDraft
): { type: ElementType; confidence: number } => {
  const normalized = normalizeLine(line);
  if (!normalized || futureTypes.length === 0) {
    return {
      type: forwardDraft.type,
      confidence: forwardDraft.confidence * 0.9,
    };
  }

  const nextType = futureTypes[0];

  // قاعدة 1: لو اللي بعدي dialogue/parenthetical + أنا شبه character → character
  if (
    (nextType === "dialogue" || nextType === "parenthetical") &&
    looksLikeCharacterStructurally(normalized)
  ) {
    return { type: "character", confidence: 88 };
  }

  // قاعدة 2: لو اللي بعدي character أو scene_header → أنا آخر سطر في الكتلة
  if (nextType === "character" || nextType === "scene_header_top_line") {
    if (isActionVerbStart(normalized) || hasActionVerbStructure(normalized)) {
      return { type: "action", confidence: 85 };
    }
    if (
      !hasActionVerbStructure(normalized) &&
      !isActionCueLine(normalized) &&
      !/^[-–—]/.test(normalized) &&
      wordCount(normalized) <= 15
    ) {
      // سطر قصير بدون action indicators → حوار أرجح
      if (hasDirectDialogueCues(normalized) || wordCount(normalized) <= 8) {
        return { type: "dialogue", confidence: 82 };
      }
    }
  }

  // قاعدة 3: لو الـ 3 أسطر بعدي ≥ 2 action + أنا فيّ action verb → action
  const futureActionCount = futureTypes
    .slice(0, 3)
    .filter((t) => t === "action").length;
  if (futureActionCount >= 2) {
    const ev = collectActionEvidence(normalized);
    if (ev.byVerb || ev.byStructure) {
      return { type: "action", confidence: 83 };
    }
  }

  // قاعدة 4: لو الـ 3 أسطر بعدي ≥ 2 dialogue + أنا عندي dialogue cues → dialogue
  const futureDialogueCount = futureTypes
    .slice(0, 3)
    .filter((t) => t === "dialogue").length;
  if (futureDialogueCount >= 2 && hasDirectDialogueCues(normalized)) {
    return { type: "dialogue", confidence: 83 };
  }

  // default: ارجع للـ forward type بثقة أقل
  return {
    type: forwardDraft.type,
    confidence: Math.round(forwardDraft.confidence * 0.9),
  };
};

// ─── الدوال المُصدّرة ─────────────────────────────────────────────

/**
 * ممر التصنيف العكسي — يصنّف كل سطر بسياق مستقبلي.
 *
 * يشتغل داخل كل مشهد على حده (من DCG) عشان ما يخلطش سياق مشاهد مختلفة.
 *
 * @param classified - الأسطر المصنّفة (من الـ forward pass)
 * @param dcg - خريطة سياق المستند
 * @returns {@link ReverseClassificationResult}
 */
export const reverseClassificationPass = (
  classified: readonly ClassifiedDraft[],
  dcg: DocumentContextGraph
): ReverseClassificationResult => {
  pipelineRecorder.trackFile("reverse-classification-pass.ts");
  const n = classified.length;
  if (n === 0) {
    return { reverseTypes: [], reverseConfidences: [] };
  }

  const reverseTypes: (ElementType | null)[] = new Array(n).fill(null);
  const reverseConfidences: number[] = new Array(n).fill(0);

  // بناء scene ranges من DCG — مع clamp على حجم classified
  // (DCG بيُبنى من raw lines اللي ممكن تكون أكبر من classified بسبب الدمج/الحذف)
  const clamp = (idx: number): number => Math.min(idx, n - 1);

  const sceneRanges: { start: number; end: number }[] = [];
  if (dcg.sceneBreaks.length === 0) {
    // مفيش scene breaks → المستند كله مشهد واحد
    sceneRanges.push({ start: 0, end: n - 1 });
  } else {
    // قبل أول scene break
    const firstBreakVal = dcg.sceneBreaks[0];
    if (firstBreakVal !== undefined) {
      const firstBreak = clamp(firstBreakVal);
      if (firstBreak > 0) {
        sceneRanges.push({ start: 0, end: firstBreak - 1 });
      }
    }
    // المشاهد
    for (let s = 0; s < dcg.sceneBreaks.length; s++) {
      const startVal = dcg.sceneBreaks[s];
      if (startVal === undefined) continue;
      const start = clamp(startVal);
      if (start >= n) break;
      const nextBreakVal =
        s + 1 < dcg.sceneBreaks.length ? dcg.sceneBreaks[s + 1] : undefined;
      const end = nextBreakVal !== undefined ? clamp(nextBreakVal - 1) : n - 1;
      if (end < start) continue;
      sceneRanges.push({ start, end });
    }
  }

  // لكل مشهد — تصنيف عكسي من الآخر للأول
  for (const range of sceneRanges) {
    const reverseContext: ElementType[] = [];

    for (let i = range.end; i >= range.start; i--) {
      const draft = classified[i];
      if (draft?.text === undefined) continue;
      const line = normalizeLine(draft.text);

      // أنواع regex عالية الثقة → نسخ مباشرة
      if (
        draft.classificationMethod === "regex" &&
        draft.confidence >= REGEX_CONFIDENCE_FLOOR
      ) {
        reverseTypes[i] = draft.type;
        reverseConfidences[i] = draft.confidence;
        reverseContext.push(draft.type);
        continue;
      }

      const result = classifyWithReverseContext(line, reverseContext, draft);
      reverseTypes[i] = result.type;
      reverseConfidences[i] = result.confidence;
      reverseContext.push(result.type);
    }
  }

  return { reverseTypes, reverseConfidences };
};

/**
 * دمج نتائج الـ forward pass والـ reverse pass.
 *
 * - لو متفقين → ارفع الثقة +5
 * - لو مختلفين + الـ reverse واثق + الـ forward ضعيف → طبّق الـ reverse
 * - حد أقصى 10% تغيير
 *
 * @param classified - الأسطر المصنّفة (بيتعدّل in-place)
 * @param reverse - نتيجة الـ reverse pass
 * @returns عدد التصحيحات
 */
export const mergeForwardReverse = (
  classified: ClassifiedDraft[],
  reverse: ReverseClassificationResult
): number => {
  const n = classified.length;
  if (n === 0) return 0;

  const maxChanges = Math.max(1, Math.ceil(n * MAX_MERGE_CHANGE_RATIO));
  let corrections = 0;

  for (let i = 0; i < n; i++) {
    if (corrections >= maxChanges) break;

    const fwd = classified[i];
    const rev = reverse.reverseTypes[i];
    const revConf = reverse.reverseConfidences[i];

    if (!fwd || rev === null || rev === undefined || revConf === undefined)
      continue;

    // لو متفقين → ارفع الثقة
    if (rev === fwd.type) {
      classified[i] = {
        ...fwd,
        confidence: Math.min(99, fwd.confidence + 5),
      };
      continue;
    }

    // لو مختلفين → هل نغيّر؟
    const shouldOverride =
      revConf >= 82 &&
      fwd.confidence <= 80 &&
      fwd.classificationMethod !== "regex";

    if (!shouldOverride) continue;

    // فحص sequence rules — لازم النوع الجديد يتوافق مع الجيران
    const prev = i > 0 ? classified[i - 1] : null;
    const prevType = prev ? prev.type : null;

    const next = i + 1 < n ? classified[i + 1] : null;
    const nextType = next ? next.type : null;

    const seqValid =
      (!prevType || isValidSequence(prevType, rev)) &&
      (!nextType || isValidSequence(rev, nextType));

    if (!seqValid) continue;

    classified[i] = {
      ...fwd,
      type: rev,
      confidence: Math.max(fwd.confidence, revConf),
      classificationMethod: "context",
    };
    corrections++;
  }

  if (corrections > 0) {
    reverseLogger.info("merge-applied", {
      total: n,
      corrections,
      maxAllowed: maxChanges,
    });
  }

  return corrections;
};

#!/usr/bin/env npx tsx
/**
 * agent.ts — وكيل OCR العربي الرئيسي
 *
 * مبني على Vercel AI SDK v6 مع دعم MCP.
 * يُنسّق عملية تحويل ملفات PDF العربية الممسوحة ضوئياً إلى نص.
 *
 * البنية المعمارية:
 *   ┌─────────────┐     ┌──────────────┐     ┌─────────────────┐
 *   │  المستخدم   │────▶│  ToolLoop    │────▶│  MCP Server     │
 *   │  (CLI)      │◀────│  Agent       │◀────│  (Mistral OCR)  │
 *   └─────────────┘     └──────┬───────┘     └─────────────────┘
 *                              │
 *                    ┌─────────┴─────────┐
 *                    │  أدوات محلية:     │
 *                    │  - تصنيف PDF     │
 *                    │  - قراءة ملفات   │
 *                    │  - كتابة ملفات   │
 *                    │  - سرد ملفات     │
 *                    └─────────┬─────────┘
 *                              │
 *                    ┌─────────┴─────────┐
 *                    │  أدوات المهارة:   │
 *                    │  (skill scripts)  │
 *                    │  - OCR Mistral   │
 *                    │  - كتابة مخرجات  │
 *                    │  - تحسين صور     │
 *                    │  - تصنيف PDF     │
 *                    └───────────────────┘
 */

import { resolve } from "node:path";

import { createMCPClient } from "@ai-sdk/mcp";
import { openai } from "@ai-sdk/openai";
import { StdioClientTransport } from "@modelcontextprotocol/sdk/client/stdio.js";
import { ToolLoopAgent, stepCountIs } from "ai";

import { buildAgentConfig, validateEnvironment } from "./config";
import {
  skillClassifyPdf,
  skillOcrMistral,
  skillWriteOutput,
  skillEnhanceImages,
} from "./skill-tools";
import {
  readFileTool,
  writeFileTool,
  listFilesTool,
  classifyPdfTool,
} from "./tools";

import type { MCPClient } from "@ai-sdk/mcp";
import type { ToolSet } from "ai";

// ─── ألوان الطرفية ──────────────────────────────────────────

const C = {
  reset: "\x1b[0m",
  bold: "\x1b[1m",
  dim: "\x1b[2m",
  green: "\x1b[32m",
  yellow: "\x1b[33m",
  blue: "\x1b[34m",
  red: "\x1b[31m",
  cyan: "\x1b[36m",
} as const;

function log(prefix: string, color: string, msg: string): void {
  console.error(`${color}${C.bold}[${prefix}]${C.reset} ${msg}`);
}

function createChildEnv(extra: Record<string, string>): Record<string, string> {
  const base = Object.fromEntries(
    Object.entries(process.env).filter(
      (entry): entry is [string, string] => typeof entry[1] === "string"
    )
  );

  return {
    ...base,
    ...extra,
  };
}

// ─── إنشاء عميل MCP ────────────────────────────────────────

async function createOcrMcpClient(serverPath: string) {
  log("MCP", C.blue, `الاتصال بخادم OCR: ${serverPath}`);

  const transport = new StdioClientTransport({
    command: "npx",
    args: ["tsx", serverPath],
    env: createChildEnv({
      MISTRAL_API_KEY: process.env["MISTRAL_API_KEY"] ?? "",
      OPENAI_API_KEY: process.env["OPENAI_API_KEY"] ?? "",
    }),
  });

  const client = await createMCPClient({ transport });
  log("MCP", C.green, "تم الاتصال بنجاح");

  return client;
}

// ─── تعليمات الوكيل ─────────────────────────────────────────

const AGENT_INSTRUCTIONS = `أنت وكيل متخصص في استخراج النص العربي من ملفات PDF الممسوحة ضوئياً (OCR).

## مجموعات الأدوات المتاحة:

### 1. أدوات المهارة (skill scripts) — المسار الأساسي:
- **skill_classify_pdf**: تصنيف PDF (نصي / ممسوح / مختلط / محمي) — الخطوة الأولى دائماً
- **skill_ocr_mistral**: استخراج OCR عبر Mistral API → يُنتج ملف JSON خام
- **skill_write_output**: تحويل JSON الخام إلى TXT أو Markdown نهائي
- **skill_enhance_images**: تحسين جودة الصور قبل OCR (عند ضعف النتائج)

### 2. أدوات MCP (خادم OCR المتكامل) — مسار بديل:
- **convert_document_to_markdown**: تحويل شامل (OCR + تطبيع + LLM اختياري) في خطوة واحدة

### 3. أدوات نظام الملفات:
- **read_file**: قراءة محتوى ملف
- **write_file**: كتابة ملف جديد (يتجنب الكتابة فوق الموجود)
- **list_files**: سرد ملفات في مجلد مع تصفية حسب الامتداد
- **classify_pdf**: تصنيف سريع مدمج (بديل خفيف لـ skill_classify_pdf)

## سير العمل المعتاد (المسار الأساسي عبر أدوات المهارة):
1. إذا أعطاك المستخدم مسار مجلد → استخدم list_files لاكتشاف PDFs
2. صنّف كل ملف عبر **skill_classify_pdf**
3. إذا كان ممسوحاً أو مختلطاً:
   أ. نفّذ OCR عبر **skill_ocr_mistral** → ينتج ملف JSON
   ب. حوّل JSON إلى الصيغة المطلوبة عبر **skill_write_output**
4. إذا كانت النتائج ضعيفة → استخدم **skill_enhance_images** ثم أعد OCR
5. أبلغ المستخدم بالنتائج (المحرك، عدد الصفحات، الحجم، الوقت)

## المسار البديل (عبر MCP — خطوة واحدة):
- استخدم **convert_document_to_markdown** مباشرةً عندما:
  - المستخدم يريد تحويل سريع بدون تحكم تفصيلي
  - يريد تفعيل تطبيع النص العربي المتقدم (normalizer)
  - يريد تحسين LLM اختياري

## خيارات التطبيع المتاحة في convert_document_to_markdown:
- normalizeHamza: توحيد الهمزات (الافتراضي: true)
- removeDiacritics: إزالة التشكيل (الافتراضي: true)
- normalizeDigits: توحيد الأرقام — "arabic" أو "western" أو "none"
- scriptSpecificRules: قواعد السيناريوهات (الافتراضي: true)
- fixConnectedLetters: إصلاح الحروف الملتصقة (الافتراضي: true)

## قواعد استخراج النص (غير قابلة للتفاوض):
- الدقة الحرفية: لا تصحح أخطاء إملائية، لا تُعد الصياغة
- التشكيل: حافظ على كل علامات التشكيل إن وُجدت
- البنية: أسطر وفقرات كما في الأصل تماماً
- غير واضح: ضعه بين {غير واضح: وصف}
- لا تخمن أبداً — ضع العلامة وامضِ

## قواعد عامة:
- تحدث بالعربية المصرية المهنية دائماً
- أبلغ المستخدم بأي أخطاء أو تحذيرات فوراً
- لا تكتب فوق ملفات موجودة بدون إذن
- إذا كان الملف محمياً (protected) → أبلغ المستخدم وأوقف المعالجة
- إذا كان الملف أكبر من 50 صفحة → أبلغ المستخدم بالعدد قبل البدء`;

// ─── بناء الوكيل ────────────────────────────────────────────

async function buildAgent() {
  const config = buildAgentConfig();

  // التحقق من البيئة
  const envCheck = validateEnvironment();
  if (!envCheck.valid) {
    log("خطأ", C.red, `مفاتيح API مفقودة: ${envCheck.missing.join(", ")}`);
    log("خطأ", C.red, "أنشئ ملف .env بناءً على .env.example");
    process.exit(1);
  }

  // إنشاء عميل MCP للاتصال بخادم OCR
  let mcpClient: MCPClient | null = null;
  let mcpTools: Awaited<ReturnType<MCPClient["tools"]>> = {};

  try {
    mcpClient = await createOcrMcpClient(config.mcpServerPath);
    mcpTools = await mcpClient.tools();
    log(
      "أدوات",
      C.cyan,
      `تم تحميل ${Object.keys(mcpTools).length} أداة من خادم MCP`
    );
  } catch (error: unknown) {
    const msg = error instanceof Error ? error.message : String(error);
    log("تحذير", C.yellow, `فشل الاتصال بخادم MCP: ${msg}`);
    log("تحذير", C.yellow, "الوكيل سيعمل بالأدوات المحلية فقط");
  }

  // دمج كل الأدوات: محلية + مهارة (skill) + MCP
  const allTools = {
    // أدوات نظام الملفات
    classify_pdf: classifyPdfTool,
    read_file: readFileTool,
    write_file: writeFileTool,
    list_files: listFilesTool,
    // أدوات المهارة (skill scripts)
    skill_classify_pdf: skillClassifyPdf,
    skill_ocr_mistral: skillOcrMistral,
    skill_write_output: skillWriteOutput,
    skill_enhance_images: skillEnhanceImages,
    // أدوات MCP (خادم OCR المتكامل)
    ...mcpTools,
  } satisfies ToolSet;

  const skillCount = 4;
  const localCount = 4;
  const mcpCount = Object.keys(mcpTools).length;
  log(
    "وكيل",
    C.green,
    `إجمالي الأدوات: ${Object.keys(allTools).length} (${skillCount} مهارة + ${localCount} محلية + ${mcpCount} MCP)`
  );

  // بناء الوكيل
  const agent = new ToolLoopAgent({
    model: openai(config.agentModel),
    instructions: AGENT_INSTRUCTIONS,
    tools: allTools,
    stopWhen: stepCountIs(config.maxSteps),

    // ─── دوال رد النداء ─────────────────────────────
    onStepFinish: ({ text, toolCalls }) => {
      if (toolCalls && toolCalls.length > 0) {
        for (const call of toolCalls) {
          const callArgs =
            "input" in call
              ? (call as Record<string, unknown>).input
              : (call as Record<string, unknown>).args;
          log(
            "أداة",
            C.cyan,
            `← ${call.toolName}(${JSON.stringify(callArgs ?? {}).substring(0, 100)}...)`
          );
        }
      }
      if (text) {
        log("وكيل", C.dim, text.substring(0, 200));
      }
    },
  });

  return { agent, mcpClient, config };
}

// ─── واجهة سطر الأوامر ──────────────────────────────────────

async function main(): Promise<void> {
  log("بدء", C.green, "وكيل OCR العربي — Vercel AI SDK v6");
  log("بدء", C.dim, "─".repeat(50));

  const { agent, mcpClient, config } = await buildAgent();

  // تحليل معاملات سطر الأوامر
  const args = process.argv.slice(2);
  let userPrompt: string;

  if (args.length === 0) {
    // وضع تفاعلي — طلب افتراضي
    userPrompt = `اسرد ملفات PDF في المجلد: ${config.defaultInputDir}`;
    log("وضع", C.yellow, "لم يُحدد ملف — سيتم سرد ملفات PDF المتاحة");
  } else if (args[0] === "--prompt" || args[0] === "-p") {
    // طلب نصي حر
    userPrompt = args.slice(1).join(" ");
  } else {
    // مسار ملف PDF مباشر
    const pdfArg = args[0];
    if (pdfArg === undefined) {
      process.exit(1);
    }

    const pdfPath = resolve(pdfArg);
    const outputFormat = args.includes("--txt") ? "txt" : "md";
    const outputPath = args
      .find((a) => a.startsWith("--output="))
      ?.split("=")[1];

    userPrompt = `حوّل ملف PDF التالي إلى ${outputFormat}:
المسار: ${pdfPath}${outputPath ? `\nمسار الإخراج: ${outputPath}` : ""}

الخطوات:
1. صنّف الملف أولاً
2. إذا كان ممسوحاً أو مختلطاً — نفّذ OCR عبر convert_document_to_markdown
3. اكتب النتيجة في ملف ${outputFormat}
4. أبلغني بالنتائج`;
  }

  log("طلب", C.blue, userPrompt.substring(0, 150));
  log("بدء", C.dim, "─".repeat(50));

  try {
    // تشغيل الوكيل
    const result = await agent.generate({
      prompt: userPrompt,
    });

    // عرض النتيجة النهائية
    console.error();
    log("نتيجة", C.green, "─".repeat(50));
    console.error(result.text);
    log("نتيجة", C.green, "─".repeat(50));

    // إحصائيات الاستخدام
    const usage = result.usage as unknown as Record<string, number> | undefined;
    if (usage) {
      const input = usage["promptTokens"] ?? usage["inputTokens"] ?? 0;
      const output = usage["completionTokens"] ?? usage["outputTokens"] ?? 0;
      const total = usage["totalTokens"] ?? input + output;
      log(
        "إحصائيات",
        C.dim,
        `الرموز: ${input} إدخال + ${output} إخراج = ${total} إجمالي`
      );
    }
    log("إحصائيات", C.dim, `الخطوات: ${result.steps?.length ?? 0}`);
  } catch (error: unknown) {
    const msg = error instanceof Error ? error.message : String(error);
    log("خطأ", C.red, `فشل تشغيل الوكيل: ${msg}`);
    if (error instanceof Error && error.stack) {
      console.error(error.stack);
    }
    process.exitCode = 1;
  } finally {
    // تنظيف اتصال MCP
    if (mcpClient) {
      try {
        await mcpClient.close();
        log("MCP", C.dim, "تم إغلاق الاتصال");
      } catch {
        // تجاهل أخطاء الإغلاق
      }
    }
  }
}

// ─── نقطة الدخول ────────────────────────────────────────────

main().catch((error) => {
  console.error("خطأ غير متوقع:", error);
  process.exit(1);
});

#!/usr/bin/env npx tsx
/**
 * batch.ts — معالجة دفعية لعدة ملفات PDF
 *
 * يقرأ مجلداً كاملاً ويُعالج جميع ملفات PDF الموجودة فيه.
 * يستخدم نفس بنية الوكيل مع تكرار على كل ملف.
 *
 * الاستخدام:
 *   npx tsx src/batch.ts /path/to/pdf/folder
 *   npx tsx src/batch.ts /path/to/pdf/folder --output /path/to/output --format txt
 */

import { readdir, mkdir } from "node:fs/promises";
import { join, extname, basename, resolve } from "node:path";

import { createMCPClient } from "@ai-sdk/mcp";
