/**
 * @fileoverview Editor Insertion — إدراج العناصر المصنفة في المحرر
 *
 * @module pipeline/editor-insertion
 */

import { Fragment, Slice } from "@tiptap/pm/model";

import { logger } from "../utils/logger";

import type { ElementType } from "../extensions/classification-types";
import type { EditorView } from "@tiptap/pm/view";

const insertionLogger = logger.createScope("editor-insertion");

/** عنصر مصنف مع معرف */
export interface ClassifiedItem {
  _itemId: string;
  type: ElementType;
  text: string;
  confidence?: number;
  classificationMethod?: string;
}

/** خيارات الإدراج */
export interface InsertionOptions {
  from?: number;
  to?: number;
}

/**
 * إدراج عناصر مصنفة في المحرر
 */
export async function insertClassifiedItems(
  view: EditorView,
  items: ClassifiedItem[],
  options: InsertionOptions = {}
): Promise<void> {
  const { from = 0, to = view.state.doc.content.size } = options;

  insertionLogger.info("inserting-classified-items", {
    itemCount: items.length,
    from,
    to,
  });

  const tr = view.state.tr;

  // بناء عقد ProseMirror من العناصر المصنفة
  const nodes = items
    .map((item) => {
      const nodeType = view.state.schema.nodes[item.type];
      if (!nodeType) {
        insertionLogger.warn("unknown-node-type", { type: item.type });
        return null;
      }

      // إنشاء العقدة مع البيانات الوصفية
      const node = nodeType.create(
        { "data-item-id": item._itemId },
        view.state.schema.text(item.text)
      );

      return node;
    })
    .filter((n): n is NonNullable<typeof n> => n !== null);

  if (nodes.length === 0) {
    insertionLogger.warn("no-nodes-to-insert");
    return;
  }

  // إنشاء Fragment و Slice
  const fragment = Fragment.from(nodes);
  const slice = new Slice(fragment, 0, 0);

  // استبدال المحتوى
  tr.replaceRange(from, to, slice);
  view.dispatch(tr);

  insertionLogger.info("items-inserted", {
    count: nodes.length,
  });
}

import { randomInt } from "node:crypto";
import { readFile } from "node:fs/promises";
import path from "node:path";

const CANONICAL_MISTRAL_OCR_MODEL = "mistral-ocr-latest";
const CANONICAL_MISTRAL_OCR_BASE_URL = "https://api.mistral.ai";

export type MistralResponseFormat =
  | { type: "text" }
  | { type: "json_object" }
  | { type: "json_schema"; json_schema: unknown };

export interface MistralOcrPage {
  readonly index: number;
  readonly markdown: string;
  readonly images?: readonly unknown[];
  readonly dimensions?: {
    readonly dpi?: number;
    readonly height?: number;
    readonly width?: number;
  };
  readonly [key: string]: unknown;
}

export interface MistralOcrResponse {
  readonly model: string;
  readonly pages: readonly MistralOcrPage[];
  readonly usage_info?: Record<string, unknown>;
  readonly document_annotation?: string | null;
  readonly [key: string]: unknown;
}

export interface MistralFileObject {
  readonly id: string;
  readonly object: "file";
  readonly filename?: string;
  readonly purpose?: "fine-tune" | "batch" | "ocr";
  readonly mimetype?: string | null;
  readonly bytes?: number | null;
  readonly [key: string]: unknown;
}

export interface MistralOcrProcessOptions {
  readonly pages?: readonly number[];
  readonly includeImageBase64?: boolean;
  readonly extractHeader?: boolean;
  readonly extractFooter?: boolean;
  readonly tableFormat?: "markdown" | "html";
  readonly imageLimit?: number;
  readonly imageMinSize?: number;
  readonly bboxAnnotationFormat?: MistralResponseFormat;
  readonly bboxAnnotationPrompt?: string;
  readonly documentAnnotationFormat?: MistralResponseFormat;
  readonly documentAnnotationPrompt?: string;
}

export type MistralOcrInput =
  | { type: "file_path"; filePath: string }
  | { type: "file_id"; fileId: string }
  | { type: "document_url"; documentUrl: string }
  | { type: "image_url"; imageUrl: string };

export interface MistralOcrClientOptions {
  readonly apiKey?: string;
  readonly baseUrl?: string;
  readonly model?: string;
  readonly timeoutMs?: number;
  readonly maxRetries?: number;
  readonly retryBaseDelayMs?: number;
  readonly autoDeleteUploadedFile?: boolean;
  readonly defaultHeaders?: Readonly<Record<string, string>>;
}

export interface OcrProcessPdfResult {
  readonly provider: string;
  readonly pages: readonly { pageIndex: number; markdown: string }[];
  readonly raw: MistralOcrResponse;
}

export class MistralOcrClient {
  private readonly apiKey: string;
  private readonly baseUrl: string;
  private readonly model: string;
  private readonly timeoutMs: number;
  private readonly maxRetries: number;
  private readonly retryBaseDelayMs: number;
  private readonly autoDeleteUploadedFile: boolean;
  private readonly defaultHeaders: Readonly<Record<string, string>>;

  constructor(options: MistralOcrClientOptions = {}) {
    this.apiKey = requireApiKey(
      options.apiKey ?? process.env["MISTRAL_API_KEY"]
    );

    this.baseUrl = resolveHardLockedBaseUrl(
      options.baseUrl ?? process.env["MISTRAL_BASE_URL"]
    );
    this.model = resolveHardLockedModel(
      options.model ?? process.env["MISTRAL_OCR_MODEL"]
    );
    this.timeoutMs = options.timeoutMs ?? 90_000;
    this.maxRetries = Math.max(0, Math.min(options.maxRetries ?? 1, 5));
    this.retryBaseDelayMs = Math.max(100, options.retryBaseDelayMs ?? 500);
    this.autoDeleteUploadedFile = options.autoDeleteUploadedFile ?? false;
    this.defaultHeaders = options.defaultHeaders ?? {};
  }

  async processPdf(
    filePath: string,
    options: MistralOcrProcessOptions = {}
  ): Promise<OcrProcessPdfResult> {
    const raw = await this.process({ type: "file_path", filePath }, options);
    return {
      provider: "mistral-ocr",
      pages: (raw.pages ?? []).map((page) => ({
        pageIndex: typeof page.index === "number" ? page.index : 0,
        markdown: typeof page.markdown === "string" ? page.markdown : "",
      })),
      raw,
    };
  }

  async process(
    input: MistralOcrInput,
    options: MistralOcrProcessOptions = {}
  ): Promise<MistralOcrResponse> {
    let uploadedFileId: string | undefined;

    try {
      const document = await this.buildDocumentPayload(input, (fileId) => {
        uploadedFileId = fileId;
      });

      const body = {
        model: this.model,
        document,
        ...(options.pages?.length ? { pages: [...options.pages] } : {}),
        ...(typeof options.includeImageBase64 === "boolean"
          ? { include_image_base64: options.includeImageBase64 }
          : {}),
        ...(typeof options.extractHeader === "boolean"
          ? { extract_header: options.extractHeader }
          : {}),
        ...(typeof options.extractFooter === "boolean"
          ? { extract_footer: options.extractFooter }
          : {}),
        ...(options.tableFormat ? { table_format: options.tableFormat } : {}),
        ...(typeof options.imageLimit === "number"
          ? { image_limit: options.imageLimit }
          : {}),
        ...(typeof options.imageMinSize === "number"
          ? { image_min_size: options.imageMinSize }
          : {}),
        ...(options.bboxAnnotationFormat
          ? { bbox_annotation_format: options.bboxAnnotationFormat }
          : {}),
        ...(options.bboxAnnotationPrompt
          ? { bbox_annotation_prompt: options.bboxAnnotationPrompt }
          : {}),
        ...(options.documentAnnotationFormat
          ? { document_annotation_format: options.documentAnnotationFormat }
          : {}),
        ...(options.documentAnnotationPrompt
          ? { document_annotation_prompt: options.documentAnnotationPrompt }
          : {}),
      };

      return await this.requestJson<MistralOcrResponse>("/v1/ocr", {
        method: "POST",
        headers: {
          "Content-Type": "application/json",
        },
        body: JSON.stringify(body),
      });
    } finally {
      if (uploadedFileId && this.autoDeleteUploadedFile) {
        try {
          await this.deleteFile(uploadedFileId);
        } catch {
          // best-effort cleanup
        }
      }
    }
  }

  async uploadFile(
    filePath: string,
    purpose: "ocr" | "batch" | "fine-tune" = "ocr"
  ): Promise<MistralFileObject> {
    const buffer = await readFile(filePath);
    const form = new FormData();
    const fileName = path.basename(filePath);
    const mimeType = inferMimeType(fileName);

    form.append("purpose", purpose);
    form.append("file", new Blob([buffer], { type: mimeType }), fileName);

    return this.requestJson<MistralFileObject>("/v1/files", {
      method: "POST",
      body: form,
      headers: {},
    });
  }

  async deleteFile(
    fileId: string
  ): Promise<{ id: string; deleted: boolean; object: string }> {
    return this.requestJson<{ id: string; deleted: boolean; object: string }>(
      `/v1/files/${encodeURIComponent(fileId)}`,
      {
        method: "DELETE",
        headers: {},
      }
    );
  }

  private async buildDocumentPayload(
    input: MistralOcrInput,
    onUploaded?: (fileId: string) => void
  ): Promise<Record<string, unknown>> {
    switch (input.type) {
      case "file_id":
        return { file_id: input.fileId };

      case "document_url":
        return {
          type: "document_url",
          document_url: input.documentUrl,
        };

      case "image_url":
        return {
          type: "image_url",
          image_url: input.imageUrl,
        };

      case "file_path": {
        const uploaded = await this.uploadFile(input.filePath, "ocr");
        onUploaded?.(uploaded.id);
        return { file_id: uploaded.id };
      }
    }
  }

  private async requestJson<T>(route: string, init: RequestInit): Promise<T> {
    let attempt = 0;
    let lastError: unknown;

    while (attempt <= this.maxRetries) {
      const timeoutState = createTimeoutState(this.timeoutMs);
      try {
        const headers = new Headers(init.headers ?? {});
        headers.set("Authorization", `Bearer ${this.apiKey}`);
        if (!headers.has("Accept")) {
          headers.set("Accept", "application/json");
        }
        for (const [key, value] of Object.entries(this.defaultHeaders)) {
          if (!headers.has(key)) headers.set(key, value);
        }

        const response = await fetch(`${this.baseUrl}${route}`, {
          ...init,
          headers,
          signal: timeoutState.signal,
        });

        const text = await response.text();
        const json = text ? safeJsonParse(text) : null;

        if (!response.ok) {
          const error = new Error(
            `Mistral API error ${response.status}: ${
              typeof json === "object" && json ? JSON.stringify(json) : text
            }`
          );

          if (isRetryableStatus(response.status) && attempt < this.maxRetries) {
            attempt += 1;
            await sleep(
              exponentialBackoffDelay(this.retryBaseDelayMs, attempt)
            );
            continue;
          }

          throw error;
        }

        return json as T;
      } catch (error) {
        lastError = error;
        if (
          shouldRetryRequest(error, timeoutState.didTimeout) &&
          attempt < this.maxRetries
        ) {
          attempt += 1;
          await sleep(exponentialBackoffDelay(this.retryBaseDelayMs, attempt));
          continue;
        }
        throw error;
      } finally {
        timeoutState.cleanup();
      }
    }

    throw new Error(
      `Mistral request failed after retries: ${toErrorMessage(lastError)}`
    );
  }
}

function safeJsonParse(text: string): unknown {
  try {
    return JSON.parse(text);
  } catch {
    return text;
  }
}

function requireApiKey(raw: string | undefined): string {
  const value = (raw ?? "").trim();
  if (!value) {
    throw new Error("MISTRAL_API_KEY is missing.");
  }
  if (/\s/u.test(value)) {
    throw new Error("MISTRAL_API_KEY is invalid: contains whitespace.");
  }
  return value;
}

function normalizeComparableValue(value: string): string {
  return value.trim().replace(/\/+$/u, "");
}

function resolveHardLockedModel(raw: string | undefined): string {
  if (typeof raw !== "string" || !raw.trim()) {
    return CANONICAL_MISTRAL_OCR_MODEL;
  }
  if (
    normalizeComparableValue(raw) !==
    normalizeComparableValue(CANONICAL_MISTRAL_OCR_MODEL)
  ) {
    throw new Error(
      `MISTRAL_OCR_MODEL is hard-locked to ${CANONICAL_MISTRAL_OCR_MODEL}. Received: ${raw.trim()}`
    );
  }
  return CANONICAL_MISTRAL_OCR_MODEL;
}

function resolveHardLockedBaseUrl(raw: string | undefined): string {
  if (typeof raw !== "string" || !raw.trim()) {
    return CANONICAL_MISTRAL_OCR_BASE_URL;
  }
  const normalized = normalizeComparableValue(raw);
  if (normalized !== normalizeComparableValue(CANONICAL_MISTRAL_OCR_BASE_URL)) {
    throw new Error(
      `MISTRAL OCR base URL is hard-locked to ${CANONICAL_MISTRAL_OCR_BASE_URL}. Received: ${raw.trim()}`
    );
  }
  return CANONICAL_MISTRAL_OCR_BASE_URL;
}

function createTimeoutState(timeoutMs: number): {
  signal: AbortSignal;
  cleanup: () => void;
  didTimeout: () => boolean;
} {
  const hasAbortSignalTimeout =
    typeof AbortSignal !== "undefined" &&
    typeof (AbortSignal as unknown as { timeout?: unknown }).timeout ===
      "function";

  if (hasAbortSignalTimeout) {
    const timeoutSignal = (
      AbortSignal as unknown as { timeout: (ms: number) => AbortSignal }
    ).timeout(timeoutMs);
    return {
      signal: timeoutSignal,
      cleanup: () => undefined,
      didTimeout: () => timeoutSignal.aborted,
    };
  }

  const controller = new AbortController();
  const timer = setTimeout(() => controller.abort(), timeoutMs);
  return {
    signal: controller.signal,
    cleanup: () => clearTimeout(timer),
    didTimeout: () => controller.signal.aborted,
  };
}

function isRetryableStatus(status: number): boolean {
  return status === 408 || status === 425 || status === 429 || status >= 500;
}

function shouldRetryRequest(
  error: unknown,
  didTimeout: () => boolean
): boolean {
  if (didTimeout()) {
    return true;
  }
  if (error instanceof Error) {
    if (error.name === "AbortError" || error.name === "TimeoutError") {
      return true;
    }
    const lowerMessage = error.message.toLowerCase();
    if (
      lowerMessage.includes("fetch failed") ||
      lowerMessage.includes("network") ||
      lowerMessage.includes("timed out")
    ) {
      return true;
    }
  }
  return false;
}

function exponentialBackoffDelay(baseDelayMs: number, attempt: number): number {
  const withExponent = baseDelayMs * 2 ** Math.max(0, attempt - 1);
  const jitter = randomInt(0, 101);
  return withExponent + jitter;
}

async function sleep(ms: number): Promise<void> {
  await new Promise((resolve) => {
    setTimeout(resolve, ms);
  });
}

function toErrorMessage(error: unknown): string {
  if (error instanceof Error) {
    return error.message;
  }
  return String(error ?? "unknown error");
}

function inferMimeType(fileName: string): string {
  const ext = path.extname(fileName).toLowerCase();
  switch (ext) {
    case ".pdf":
      return "application/pdf";
    case ".png":
      return "image/png";
    case ".jpg":
    case ".jpeg":
      return "image/jpeg";
    case ".webp":
      return "image/webp";
    case ".tif":
    case ".tiff":
      return "image/tiff";
    default:
      return "application/octet-stream";
  }
}

/**
 * محوّل مساعد: دمج صفحات الـOCR إلى نص خام قابل للمقارنة مع DOCX.
 * - لا يعيد ترتيب الصفحات.
 * - يفصل الصفحات بسطرين فقط.
 */
export function mistralOcrPagesToText(
  pages: readonly { index: number; markdown: string }[]
): string {
  return [...pages]
    .sort((a, b) => a.index - b.index)
    .map((page) => (page.markdown ?? "").trim())
    .filter(Boolean)
    .join("\n\n");
}

import { randomInt } from "node:crypto";

import type { OcrPageResult, OcrProvider } from "../types";

interface MistralOcrResponse {
  pages?: {
    index?: number;
    markdown?: string;
    text?: string;
  }[];
  document_annotation?: string | null;
}

const CANONICAL_MISTRAL_OCR_MODEL = "mistral-ocr-latest";
const CANONICAL_MISTRAL_OCR_ENDPOINT = "https://api.mistral.ai/v1/ocr";

export class MistralOcrProvider implements OcrProvider {
  public name = "mistral";

  private apiKey: string;
  private model: string;
  private endpoint: string;
  private timeoutMs: number;
  private maxRetries: number;
  private retryBaseDelayMs: number;

  constructor(opts?: {
    apiKey?: string;
    model?: string;
    endpoint?: string;
    timeoutMs?: number;
    maxRetries?: number;
    retryBaseDelayMs?: number;
  }) {
    this.apiKey = requireApiKey(opts?.apiKey ?? process.env["MISTRAL_API_KEY"]);
    this.model = resolveHardLockedValue(
      opts?.model ?? process.env["MISTRAL_OCR_MODEL"],
      CANONICAL_MISTRAL_OCR_MODEL,
      "MISTRAL_OCR_MODEL"
    );
    this.endpoint = resolveHardLockedValue(
      opts?.endpoint ?? process.env["MISTRAL_OCR_ENDPOINT"],
      CANONICAL_MISTRAL_OCR_ENDPOINT,
      "MISTRAL_OCR_ENDPOINT"
    );
    this.timeoutMs = Math.max(1_000, opts?.timeoutMs ?? 90_000);
    this.maxRetries = Math.max(0, Math.min(opts?.maxRetries ?? 1, 5));
    this.retryBaseDelayMs = Math.max(100, opts?.retryBaseDelayMs ?? 500);
  }

  async processPdfPages(input: {
    pdfBuffer: Buffer;
    pages: number[];
    hint?: string;
  }): Promise<OcrPageResult[]> {
    const body = {
      model: this.model,
      document: {
        type: "document_url",
        document_url: toDataUrl(input.pdfBuffer, "application/pdf"),
      },
      ...(input.pages.length > 0 ? { pages: input.pages } : {}),
      extract_header: false,
      extract_footer: false,
    };

    const data = await this.requestJsonWithRetry(body);

    const out: OcrPageResult[] = [];
    for (const p of data.pages ?? []) {
      const page = p.index ?? -1;
      const text = (p.text ?? p.markdown ?? "").trim();
      out.push({
        page,
        text,
        lines: text
          .split(/\r?\n/)
          .map((s) => s.trim())
          .filter(Boolean),
      });
    }

    return out;
  }

  private async requestJsonWithRetry(
    body: Record<string, unknown>
  ): Promise<MistralOcrResponse> {
    let attempt = 0;
    let lastError: unknown;

    while (attempt <= this.maxRetries) {
      const timeoutState = createTimeoutState(this.timeoutMs);
      try {
        const response = await fetch(this.endpoint, {
          method: "POST",
          headers: {
            Authorization: `Bearer ${this.apiKey}`,
            "Content-Type": "application/json",
            Accept: "application/json",
          },
          body: JSON.stringify(body),
          signal: timeoutState.signal,
        });

        if (!response.ok) {
          const txt = await response.text().catch(() => "");
          const error = new Error(
            `Mistral OCR failed: ${response.status} ${txt}`
          );

          if (isRetryableStatus(response.status) && attempt < this.maxRetries) {
            attempt += 1;
            await sleep(
              exponentialBackoffDelay(this.retryBaseDelayMs, attempt)
            );
            continue;
          }

          throw error;
        }

        return (await response.json()) as MistralOcrResponse;
      } catch (error) {
        lastError = error;
        if (
          shouldRetryRequest(error, timeoutState.didTimeout) &&
          attempt < this.maxRetries
        ) {
          attempt += 1;
          await sleep(exponentialBackoffDelay(this.retryBaseDelayMs, attempt));
          continue;
        }
        throw error;
      } finally {
        timeoutState.cleanup();
      }
    }

    throw new Error(
      `Mistral OCR request failed after retries: ${toErrorMessage(lastError)}`
    );
  }
}

function toDataUrl(buf: Buffer, mime: string): string {
  return `data:${mime};base64,${buf.toString("base64")}`;
}

function normalizeComparableValue(value: string): string {
  return value.trim().replace(/\/+$/u, "");
}

function resolveHardLockedValue(
  raw: string | undefined,
  canonical: string,
  label: string
): string {
  if (typeof raw !== "string" || !raw.trim()) {
    return canonical;
  }
  if (normalizeComparableValue(raw) !== normalizeComparableValue(canonical)) {
    throw new Error(
      `${label} is hard-locked to ${canonical}. Received: ${raw.trim()}`
    );
  }
  return canonical;
}

function requireApiKey(raw: string | undefined): string {
  const value = (raw ?? "").trim();
  if (!value) {
    throw new Error("MISTRAL_API_KEY is required for MistralOcrProvider");
  }
  if (/\s/u.test(value)) {
    throw new Error("MISTRAL_API_KEY is invalid: contains whitespace.");
  }
  return value;
}

function createTimeoutState(timeoutMs: number): {
  signal: AbortSignal;
  cleanup: () => void;
  didTimeout: () => boolean;
} {
  const hasAbortSignalTimeout =
    typeof AbortSignal !== "undefined" &&
    typeof (AbortSignal as unknown as { timeout?: unknown }).timeout ===
      "function";

  if (hasAbortSignalTimeout) {
    const timeoutSignal = (
      AbortSignal as unknown as { timeout: (ms: number) => AbortSignal }
    ).timeout(timeoutMs);
    return {
      signal: timeoutSignal,
      cleanup: () => undefined,
      didTimeout: () => timeoutSignal.aborted,
    };
  }

  const controller = new AbortController();
  const timer = setTimeout(() => controller.abort(), timeoutMs);
  return {
    signal: controller.signal,
    cleanup: () => clearTimeout(timer),
    didTimeout: () => controller.signal.aborted,
  };
}

function isRetryableStatus(status: number): boolean {
  return status === 408 || status === 425 || status === 429 || status >= 500;
}

function shouldRetryRequest(
  error: unknown,
  didTimeout: () => boolean
): boolean {
  if (didTimeout()) {
    return true;
  }
  if (error instanceof Error) {
    if (error.name === "AbortError" || error.name === "TimeoutError") {
      return true;
    }
    const lowerMessage = error.message.toLowerCase();
    if (
      lowerMessage.includes("fetch failed") ||
      lowerMessage.includes("network") ||
      lowerMessage.includes("timed out")
    ) {
      return true;
    }
  }
  return false;
}

function exponentialBackoffDelay(baseDelayMs: number, attempt: number): number {
  const withExponent = baseDelayMs * 2 ** Math.max(0, attempt - 1);
  const jitter = randomInt(0, 101);
  return withExponent + jitter;
}

async function sleep(ms: number): Promise<void> {
  await new Promise((resolve) => {
    setTimeout(resolve, ms);
  });
}

function toErrorMessage(error: unknown): string {
  if (error instanceof Error) {
    return error.message;
  }
  return String(error ?? "unknown error");
}

/**
 * @module pipeline/trust-policy
 * @description Structured Input Trust Policy — المرحلة 1 من إعادة الهيكلة
 *
 * يُحدد مستويات الثقة للمدخلات المهيكلة ويقرر مسار المعالجة:
 * - trusted_structured → استيراد مباشر كعقد + فحص خلفي
 * - semi_structured → fallback مناسب مع تصنيف جزئي
 * - raw_text → المصنف النصي الكامل (paste-classifier)
 *
 * الثقة هنا ليست "بنية لغوية عربية جاهزة" بل "بنية تشغيلية داخلية
 * ناتجة من التطبيق/الاستخراج الداخلي".
 */

// ─── مستويات الثقة ──────────────────────────────────────────────

export type InputTrustLevel =
  | "trusted_structured"
  | "semi_structured"
  | "raw_text";

// ─── معايير الثقة ───────────────────────────────────────────────

export interface TrustAssessment {
  /** مستوى الثقة المُحدد */
  level: InputTrustLevel;
  /** هل المدخل system-generated */
  isSystemGenerated: boolean;
  /** هل المدخل مُتحقق من المخطط (schema-valid) */
  isSchemaValid: boolean;
  /** هل المدخل مُعلّم بالمصدر (source-tagged) */
  isSourceTagged: boolean;
  /** هل المدخل مُتحقق من السلامة (integrity-checked) */
  isIntegrityChecked: boolean;
  /** مصدر المدخل */
  source: string;
  /** سبب تحديد المستوى */
  reason: string;
  /** إصدار المخطط الرقمي — لدعم هجرة بنية StructuredBlock مستقبلاً */
  schemaVersion: number;
}

/** الإصدار الحالي لمخطط StructuredBlock */
export const CURRENT_SCHEMA_VERSION = 1;

// ─── واجهة كتلة مهيكلة ─────────────────────────────────────────

export interface StructuredBlock {
  /** نوع العنصر */
  type: string;
  /** النص */
  text: string;
  /** بيانات إضافية */
  meta?: Record<string, unknown>;
}

export interface StructuredInput {
  /** الكتل المهيكلة */
  blocks: StructuredBlock[];
  /** المصدر */
  source?: string;
  /** هل وُلّدت من النظام */
  systemGenerated?: boolean;
  /** هل تم التحقق من المخطط */
  schemaValid?: boolean;
  /** هل تم التحقق من السلامة */
  integrityChecked?: boolean;
}

// ─── تحديد مستوى الثقة ─────────────────────────────────────────

const VALID_TYPES = new Set([
  "action",
  "dialogue",
  "character",
  "scene_header_top_line",
  "scene_header_1",
  "scene_header_2",
  "scene_header_3",
  "transition",
  "parenthetical",
  "basmala",
]);

/**
 * فحص صلاحية المخطط — كل كتلة يجب أن تحتوي type صالح و text غير فارغ.
 */
const validateSchema = (blocks: readonly StructuredBlock[]): boolean => {
  if (!Array.isArray(blocks) || blocks.length === 0) return false;
  return blocks.every(
    (block) =>
      block &&
      typeof block.type === "string" &&
      VALID_TYPES.has(block.type) &&
      typeof block.text === "string" &&
      block.text.trim().length > 0
  );
};

/**
 * تقييم مستوى الثقة لمدخل مهيكل.
 *
 * القاعدة:
 * - إذا كانت الكتل system-generated + schema-valid + source-tagged + integrity-checked
 *   ⇒ trusted_structured
 * - إذا كانت schema-valid فقط
 *   ⇒ semi_structured
 * - غير ذلك
 *   ⇒ raw_text
 */
export const assessTrustLevel = (input: StructuredInput): TrustAssessment => {
  const isSchemaValid = validateSchema(input.blocks);
  const isSystemGenerated = input.systemGenerated === true;
  const isSourceTagged =
    typeof input.source === "string" && input.source.length > 0;
  const isIntegrityChecked = input.integrityChecked === true;

  if (
    isSystemGenerated &&
    isSchemaValid &&
    isSourceTagged &&
    isIntegrityChecked
  ) {
    return {
      level: "trusted_structured",
      isSystemGenerated,
      isSchemaValid,
      isSourceTagged,
      isIntegrityChecked,
      source: input.source ?? "unknown",
      reason: "جميع معايير الثقة مستوفاة — استيراد مباشر مع فحص خلفي",
      schemaVersion: CURRENT_SCHEMA_VERSION,
    };
  }

  if (isSchemaValid) {
    return {
      level: "semi_structured",
      isSystemGenerated,
      isSchemaValid,
      isSourceTagged,
      isIntegrityChecked,
      source: input.source ?? "unknown",
      reason: "المخطط صالح لكن معايير الثقة غير مكتملة",
      schemaVersion: CURRENT_SCHEMA_VERSION,
    };
  }

  return {
    level: "raw_text",
    isSystemGenerated,
    isSchemaValid,
    isSourceTagged,
    isIntegrityChecked,
    source: input.source ?? "unknown",
    reason: "المدخل غير مهيكل أو المخطط غير صالح — fallback للمصنف النصي",
    schemaVersion: CURRENT_SCHEMA_VERSION,
  };
};

// ─── مسار المعالجة ─────────────────────────────────────────────

export type ImportAction =
  | "direct_import" // استيراد مباشر كعقد
  | "direct_import_with_bg_check" // استيراد مباشر + فحص خلفي
  | "fallback_to_classifier"; // المصنف النصي الكامل

/**
 * تحديد مسار المعالجة بناءً على مستوى الثقة.
 */
export const resolveImportAction = (level: InputTrustLevel): ImportAction => {
  switch (level) {
    case "trusted_structured":
      return "direct_import_with_bg_check";
    case "semi_structured":
      return "fallback_to_classifier";
    case "raw_text":
      return "fallback_to_classifier";
  }
};

import { GoogleGenAI } from "@google/genai";

import {
  qdrantClient,
  RAG_COLLECTION_NAME,
  GEMINI_API_KEY,
  logger,
} from "./config";
import { generateEmbedding } from "./embeddings";
import { SearchResult, RagResponse } from "./types";

const ai = new GoogleGenAI({ apiKey: GEMINI_API_KEY });

export async function searchCode(
  query: string,
  limit = 5
): Promise<SearchResult[]> {
  try {
    logger.info({ query, limit }, "Searching code...");

    const queryEmbedding = await generateEmbedding(query);

    const searchResult = await qdrantClient.search(RAG_COLLECTION_NAME, {
      vector: queryEmbedding,
      limit,
      with_payload: true,
    });

    const results: SearchResult[] = searchResult.map(
      (result: {
        id: string | number;
        score: number;
        payload?: Record<string, unknown> | null;
      }) => {
        const p = result.payload ?? {};
        const metadata: SearchResult["chunk"]["metadata"] = {
          filePath: String(p.filePath ?? ""),
          fileName: String(p.fileName ?? ""),
          fileType: String(p.fileType ?? ""),
          chunkIndex: Number(p.chunkIndex ?? 0),
          totalChunks: Number(p.totalChunks ?? 0),
          language: String(p.language ?? ""),
          ...(typeof p.functionName === "string" && {
            functionName: p.functionName,
          }),
          ...(typeof p.className === "string" && { className: p.className }),
          ...(typeof p.section === "string" && { section: p.section }),
          ...(typeof p.startLine === "number" && { startLine: p.startLine }),
          ...(typeof p.endLine === "number" && { endLine: p.endLine }),
        };

        return {
          chunk: {
            content: String(p.content ?? ""),
            metadata,
          },
          score: result.score || 0,
          id: result.id,
        };
      }
    );

    logger.info(`Found ${results.length} results`);
    return results;
  } catch (error) {
    logger.error({ error }, "Failed to search code");
    throw error;
  }
}

export async function askQuestion(question: string): Promise<RagResponse> {
  try {
    logger.info({ question }, "Processing RAG question...");

    const searchResults = await searchCode(question, 5);

    if (searchResults.length === 0) {
      return {
        answer: "لم أجد معلومات كافية في الكود للإجابة على هذا السؤال.",
        sources: [],
      };
    }

    const context = searchResults
      .map((result, idx) => {
        const { filePath, startLine, endLine } = result.chunk.metadata;
        const location =
          startLine && endLine
            ? `${filePath}:${startLine}-${endLine}`
            : filePath;
        return `[${idx + 1}] من ${location}:\n${result.chunk.content}`;
      })
      .join("\n\n---\n\n");

    const prompt = `أنت مساعد برمجي متخصص في تحليل كود TypeScript/JavaScript.
لديك وصول لأجزاء من كود المشروع.
أجب على السؤال بناءً على الكود المتاح فقط.
اذكر أسماء الملفات والـ functions ذات الصلة.
إذا لم تجد معلومات كافية، قل ذلك بوضوح.
استخدم اللغة العربية في الإجابة.

السؤال: ${question}

الكود المتاح:
${context}

أجب على السؤال بناءً على الكود أعلاه.`;

    try {
      const response = await ai.models.generateContent({
        model: "gemini-3.1-pro-preview",
        contents: prompt,
      });

      const answer = response.text ?? "فشل في توليد الإجابة";

      return {
        answer,
        sources: searchResults.map((result) => ({
          filePath: result.chunk.metadata.filePath,
          snippet: result.chunk.content.slice(0, 200) + "...",
          score: result.score,
        })),
      };
    } catch (geminiError) {
      logger.warn({ geminiError }, "Gemini failed, trying alternative...");
      return {
        answer:
          "فشل في الاتصال بـ Gemini. النتائج المتاحة:\n\n" +
          searchResults
            .map(
              (r, i) =>
                `${i + 1}. ${r.chunk.metadata.filePath}\n${r.chunk.content.slice(0, 300)}...`
            )
            .join("\n\n"),
        sources: searchResults.map((result) => ({
          filePath: result.chunk.metadata.filePath,
          snippet: result.chunk.content.slice(0, 200) + "...",
          score: result.score,
        })),
      };
    }
  } catch (error) {
    logger.error({ error }, "Failed to generate RAG response");
    throw error;
  }
}

