import {
  copyToClipboard,
  cutToClipboard,
  pasteFromClipboard,
} from "./editor-clipboard";

import type { Editor } from "@tiptap/core";

const setClipboard = (clipboard: Partial<Clipboard>): void => {
  Object.defineProperty(navigator, "clipboard", {
    configurable: true,
    value: clipboard,
  });
};

const createEditor = (options?: {
  emptySelection?: boolean;
  text?: string;
  selectedText?: string;
  deleteResult?: boolean;
}): Editor => {
  const emptySelection = options?.emptySelection ?? false;
  const selectedText = options?.selectedText ?? "كلمة محددة";
  const deleteResult = options?.deleteResult ?? true;

  return {
    state: {
      selection: {
        empty: emptySelection,
        from: 1,
        to: 1 + selectedText.length,
      },
      doc: {
        textBetween: vi.fn(() => selectedText),
      },
    },
    getText: vi.fn(() => options?.text ?? "نص كامل"),
    getHTML: vi.fn(() => "<div data-type=\"action\">نص كامل</div>"),
    chain: vi.fn(() => ({
      focus: vi.fn().mockReturnThis(),
      deleteSelection: vi.fn().mockReturnThis(),
      run: vi.fn(() => deleteResult),
    })),
  } as unknown as Editor;
};

describe("editor clipboard helpers", () => {
  afterEach(() => {
    vi.restoreAllMocks();
    Object.defineProperty(navigator, "clipboard", {
      configurable: true,
      value: undefined,
    });
  });

  it("copies the selected text with a detailed success result", async () => {
    const writeText = vi.fn(async () => undefined);
    setClipboard({ writeText });

    const result = await copyToClipboard(createEditor(), true);

    expect(result.ok).toBe(true);
    expect(result.status).toBe("success");
    expect(result.textLength).toBe("كلمة محددة".length);
    expect(writeText).toHaveBeenCalledWith("كلمة محددة");
  });

  it("cuts the selected text only after a successful copy", async () => {
    const writeText = vi.fn(async () => undefined);
    const editor = createEditor();
    setClipboard({ writeText });

    const result = await cutToClipboard(editor);

    expect(result.ok).toBe(true);
    expect(result.status).toBe("success");
    expect(editor.chain).toHaveBeenCalled();
  });

  it("pastes plain text through the import callback", async () => {
    const readText = vi.fn(async () => "نص منسوخ");
    const importText = vi.fn(async () => undefined);
    const importBlocks = vi.fn(async () => undefined);
    setClipboard({ readText });

    const result = await pasteFromClipboard("menu", importText, importBlocks);

    expect(result.ok).toBe(true);
    expect(result.status).toBe("success");
    expect(importText).toHaveBeenCalledWith("نص منسوخ", "insert", {
      classificationProfile: "paste",
    });
    expect(importBlocks).not.toHaveBeenCalled();
  });

  it("returns a permission error when clipboard writing is denied", async () => {
    setClipboard({
      writeText: vi.fn(async () => {
        throw new DOMException("denied", "NotAllowedError");
      }),
    });

    const result = await copyToClipboard(createEditor(), true);

    expect(result.ok).toBe(false);
    expect(result.status).toBe("permission-denied");
  });
});

import { sanitizeExportFileBaseName } from "./shared";

import type { ScreenplayBlock } from "../file-import/document-model";

interface ExportAsClassifiedOptions {
  fileNameBase?: string;
  blocks: ScreenplayBlock[];
}

const mapFormatIdToClassifiedElement = (
  formatId: ScreenplayBlock["formatId"]
): string => {
  switch (formatId) {
    case "basmala":
      return "BASMALA";
    case "scene_header_1":
      return "SCENE-HEADER-1";
    case "scene_header_2":
      return "SCENE-HEADER-2";
    case "scene_header_3":
      return "SCENE-HEADER-3";
    case "scene_header_top_line":
      return "ACTION";
    case "action":
      return "ACTION";
    case "character":
      return "CHARACTER";
    case "dialogue":
      return "DIALOGUE";
    case "parenthetical":
      return "PARENTHETICAL";
    case "transition":
      return "TRANSITION";
    default:
      return "ACTION";
  }
};

const normalizeText = (text: string): string => {
  return text.replace(/\s+/g, " ").trim();
};

export const generateClassifiedText = (blocks: ScreenplayBlock[]): string => {
  const lines: string[] = [];

  for (let i = 0; i < blocks.length; i++) {
    const block = blocks[i];
    if (!block) continue;
    const text = normalizeText(block.text);
    if (!text) continue;

    if (block.formatId === "scene_header_top_line") {
      continue;
    }

    const element = mapFormatIdToClassifiedElement(block.formatId);
    if (!element) {
      continue;
    }
    let finalValue = text;

    if (element === "CHARACTER") {
      if (!finalValue.endsWith(":")) {
        finalValue += " :";
      }
    }

    lines.push(`${element} = ${finalValue}`);
  }

  return lines.join("\n");
};

export const exportAsClassified = ({
  fileNameBase,
  blocks,
}: ExportAsClassifiedOptions): void => {
  const textContent = generateClassifiedText(blocks);
  const safeName =
    (sanitizeExportFileBaseName(fileNameBase ?? "النص_المصنف") ||
      "النص_المصنف") + ".txt";

  const blob = new Blob([textContent], { type: "text/plain;charset=utf-8" });
  const url = URL.createObjectURL(blob);
  const a = document.createElement("a");
  a.href = url;
  a.download = safeName;
  document.body.appendChild(a);
  a.click();
  document.body.removeChild(a);
  URL.revokeObjectURL(url);
};

import DOMPurify from "isomorphic-dompurify";
import { jsPDF } from "jspdf";

import {
  type ExportRequest,
  buildFullHtmlDocument,
  sanitizeExportFileBaseName,
} from "./shared";

/**
 * يُصدّر المستند كـ PDF عبر jsPDF + html2canvas.
 *
 * الإصلاح: النسخة القديمة كانت تحقن HTML خام بدون أي CSS.
 * الآن: يبني HTML كامل عبر buildFullHtmlDocument (نفس تنسيقات المحرر)
 * ثم يحوّله لـ PDF.
 */
export const exportAsPdf = async (request: ExportRequest): Promise<void> => {
  const fileBase = sanitizeExportFileBaseName(request.fileNameBase);

  // بناء HTML كامل بالتنسيقات — مثل ما المستخدم شايفه في المحرر
  const styledHtml = buildFullHtmlDocument(request.html, request.title);

  // Sanitize the HTML before injecting it to prevent XSS vulnerabilities
  const sanitizedHtml = DOMPurify.sanitize(styledHtml, {
    WHOLE_DOCUMENT: true,
  });

  // BUG-010: jsPDF.html() يستدعي html2canvas داخلياً، و html2canvas
  // يعدّل viewport المستند بشكل مؤقت لالتقاط المحتوى — ما يسبب
  // تغيير زوم المحرر وتحريك الـ scroll لدى المستخدم.
  //
  // الحل:
  // 1. نلتقط scrollX/scrollY قبل التشغيل ونُعيدها بعده.
  // 2. نستخدم iframe مستقلاً ذا viewport ثابت بدل document الرئيسي،
  //    فيعمل html2canvas داخله بدون مساس بصفحة المستخدم.
  const previousScrollX = window.scrollX;
  const previousScrollY = window.scrollY;

  const iframe = document.createElement("iframe");
  iframe.setAttribute("aria-hidden", "true");
  iframe.style.position = "fixed";
  iframe.style.left = "-10000px";
  iframe.style.top = "0";
  iframe.style.width = "794px";
  iframe.style.height = "1123px";
  iframe.style.border = "0";
  iframe.style.pointerEvents = "none";
  iframe.style.visibility = "hidden";
  document.body.appendChild(iframe);

  try {
    const iframeDoc = iframe.contentDocument;
    if (!iframeDoc) {
      throw new Error("pdf-export: تعذّر تحضير مستند داخلي لـ jsPDF");
    }

    iframeDoc.open();
    iframeDoc.write(sanitizedHtml);
    iframeDoc.close();

    // ننتظر حتى يبني المتصفح شجرة DOM داخل iframe قبل الإلتقاط
    await new Promise<void>((resolve) => {
      if (iframeDoc.readyState === "complete") {
        resolve();
        return;
      }
      iframe.addEventListener("load", () => resolve(), { once: true });
    });

    const innerBody = iframeDoc.body;

    const pdf = new jsPDF({
      orientation: "portrait",
      unit: "pt",
      format: "a4",
      compress: true,
    });
    pdf.setR2L(true);

    await pdf.html(innerBody, {
      x: 24,
      y: 24,
      margin: [24, 24, 24, 24],
      autoPaging: "text",
      width: 547,
      windowWidth: 794,
      html2canvas: {
        scale: 1.5,
        useCORS: true,
        logging: false,
        // نمنع html2canvas من تحريك صفحة المستخدم أثناء الالتقاط
        scrollX: 0,
        scrollY: 0,
        windowWidth: 794,
        windowHeight: 1123,
      },
    });

    pdf.save(`${fileBase}.pdf`);
  } finally {
    iframe.remove();
    // استرجاع موضع التمرير الأصلي كضمان إضافي حتى لا يقفز المحرر
    window.scrollTo(previousScrollX, previousScrollY);
  }
};

import {
  resolveEditorRuntimeHealthEndpoint,
  resolvePdfaExportEndpoint,
} from "../backend-endpoints";

import {
  type ExportRequest,
  buildFullHtmlDocument,
  downloadBlob,
  sanitizeExportFileBaseName,
} from "./shared";

const PDFA_ENDPOINT = resolvePdfaExportEndpoint();
const EDITOR_RUNTIME_HEALTH_ENDPOINT = resolveEditorRuntimeHealthEndpoint();

/**
 * يتحقق من توفر خادم التصدير قبل الإرسال.
 */
const checkServerHealth = async (healthEndpoint: string): Promise<boolean> => {
  try {
    const response = await fetch(healthEndpoint, {
      method: "GET",
      signal: AbortSignal.timeout(3000),
    });
    return response.ok;
  } catch {
    return false;
  }
};

/**
 * يُصدّر المستند بصيغة PDF/A عبر خادم Puppeteer الخلفي.
 *
 * المسار:
 * 1. يبني HTML كامل مع التنسيقات
 * 2. يرسله POST إلى /api/export/pdfa
 * 3. الخادم يستخدم Puppeteer لتحويل HTML → PDF
 * 4. يستقبل blob ويحفظه
 */
export const exportAsPdfA = async (request: ExportRequest): Promise<void> => {
  const fileBase = sanitizeExportFileBaseName(request.fileNameBase);
  const fullHtml = buildFullHtmlDocument(request.html, request.title);

  const isHealthy = await checkServerHealth(EDITOR_RUNTIME_HEALTH_ENDPOINT);
  if (!isHealthy) {
    throw new Error(
      "خادم التصدير غير متاح. تأكد من تشغيل الخادم الخلفي (pnpm dev)."
    );
  }

  const response = await fetch(PDFA_ENDPOINT, {
    method: "POST",
    headers: { "Content-Type": "application/json" },
    body: JSON.stringify({
      html: fullHtml,
      filename: `${fileBase}.pdf`,
    }),
  });

  if (!response.ok) {
    const errorData = await response.json().catch(() => null);
    throw new Error(
      (errorData as { error?: string })?.error ??
        `فشل تصدير PDF/A (${response.status})`
    );
  }

  const blob = await response.blob();
  downloadBlob(`${fileBase}.pdf`, blob);
};

