                        </div>
                      )}
                    </div>
                  </div>
                )}
                {error && (
                  <p className="text-red-500 text-xs mt-4 text-center">
                    {error}
                  </p>
                )}
              </div>
            </motion.div>
          </CardSpotlight>
        </motion.div>
      )}
    </AnimatePresence>
  );
};

