};

/**
 * Edit a garment image with AI.
 */
export const editGarmentImage = async (
  imageFileOrUrl: File | string,
  editPrompt: string
): Promise<{ url: string; name: string }> => {
  const imageUrl =
    typeof imageFileOrUrl === "string"
      ? imageFileOrUrl
      : await fileToBase64(imageFileOrUrl);
  const result = await callGeminiAPI("editGarment", { imageUrl, editPrompt });
  const editedImageUrl = getStringValue(result.imageUrl);
  if (!editedImageUrl) {
    throw new Error("Garment editing did not return an image.");
  }
  return {
    url: editedImageUrl,
    name: editPrompt.slice(0, 30),
  };
};

/**
 * StyleIST Backend API Client
 * Calls the Express backend through the Next.js proxy at /api/styleist/*
 */

const STYLEIST_API = "/api/styleist";

async function fetchStyleist<T>(
  path: string,
  options: RequestInit = {}
): Promise<T> {
  const headers: HeadersInit = {
    "Content-Type": "application/json",
    ...(options.headers ?? {}),
  };

  const response = await fetch(`${STYLEIST_API}${path}`, {
    ...options,
    headers,
    credentials: "include",
  });

  if (response.status === 401) {
    throw new Error("غير مصرح - يرجى تسجيل الدخول");
  }

  const data = await response.json();

  if (!response.ok || !data.success) {
    throw new Error(data.error ?? "فشل في العملية");
  }

  return data.data as T;
}

