import { motion } from "framer-motion";
import {
  GitBranch,
  ChevronDown,
  ChevronUp,
  GripVertical,
  Copy,
} from "lucide-react";
import { useState } from "react";

import { Badge } from "@/components/ui/badge";
import { Button } from "@/components/ui/button";
// import { toast } from "sonner"; // Temporarily disabled

interface TimelineScene {
  id: string;
  title: string;
  branch?: "A" | "B" | "C";
  act?: number;
  beat?: string;
}

interface NarrativeTimelineProps {
  mode: "linear" | "nonlinear";
  scenes: TimelineScene[];
  activeBranch?: "A" | "B" | "C" | "hidden";
  onSceneClick?: (sceneId: string) => void;
  onBranchCreate?: (sceneId: string, branch: "A" | "B" | "C") => void;
}

const branchColors = {
  A: "var(--color-accent)",
  B: "var(--state-alt)",
  C: "var(--state-final)",
};

export function NarrativeTimeline({
  mode,
  scenes,
  activeBranch,
  onSceneClick,
  onBranchCreate,
}: NarrativeTimelineProps) {
  const [isExpanded, setIsExpanded] = useState(true);
  const [showBranches, setShowBranches] = useState(mode === "nonlinear");
  const [draggedScene, setDraggedScene] = useState<TimelineScene | null>(null);

  const groupedScenes = scenes.reduce(
    (acc, scene) => {
      const branch = scene.branch ?? "main";
      if (!acc[branch]) acc[branch] = [];
      acc[branch].push(scene);
      return acc;
    },
    {} as Record<string, TimelineScene[]>
  );

  const handleBranchCreate = (
    sceneId: string,
    targetBranch: "A" | "B" | "C"
  ) => {
    onBranchCreate?.(sceneId, targetBranch);
    // toast.success(`تم إنشاء فرع ${targetBranch} من المشهد`);
  };

  return (
    <div className="bg-[var(--color-panel)] border border-[var(--color-surface)] rounded-xl overflow-hidden">
      <div className="p-4 border-b border-[var(--color-surface)] flex items-center justify-between">
        <div className="flex items-center gap-3">
          <h3 className="text-[var(--color-text)]" dir="rtl">
            الخط الزمني السردي
          </h3>
          <Badge
            variant="outline"
            className="border-[var(--color-muted)] text-[var(--color-muted)]"
          >
            {mode === "linear" ? "خطي" : "غير خطي"}
          </Badge>
        </div>
        <div className="flex items-center gap-2">
          {mode === "nonlinear" && (
            <Button
              variant="ghost"
              size="sm"
              onClick={() => setShowBranches(!showBranches)}
              className="text-[var(--color-accent)] hover:bg-[var(--color-surface)]"
            >
              <GitBranch className="w-4 h-4 ml-1" />
              {showBranches ? "إخفاء الفروع" : "إظهار الفروع"}
            </Button>
          )}
          <Button
            variant="ghost"
            size="sm"
            onClick={() => setIsExpanded(!isExpanded)}
            className="text-[var(--color-text)] hover:bg-[var(--color-surface)]"
          >
            {isExpanded ? (
              <ChevronUp className="w-4 h-4" />
            ) : (
              <ChevronDown className="w-4 h-4" />
            )}
          </Button>
        </div>
      </div>

      {isExpanded && (
        <div className="p-4 space-y-6">
          {Object.entries(groupedScenes).map(([branch, branchScenes]) => {
            const isActiveBranch = activeBranch === branch || branch === "main";
            const branchColor =
              branch !== "main"
                ? branchColors[branch as "A" | "B" | "C"]
                : "var(--color-accent)";

            if (!showBranches && branch !== "main" && branch !== activeBranch) {
              return null;
            }

            return (
              <div key={branch} className="space-y-3">
                {branch !== "main" && (
                  <div className="flex items-center gap-2 mb-2">
                    <GitBranch
                      className="w-4 h-4"
                      style={{ color: branchColor }}
                    />
                    <span className="text-[var(--color-muted)]" dir="rtl">
                      فرع {branch}
                    </span>
                  </div>
                )}

                <div className="relative">
                  {/* Timeline line */}
                  <div
                    className="absolute top-0 bottom-0 w-0.5 bg-[var(--color-surface)]"
                    style={{
                      right: "1rem",
                      backgroundColor: isActiveBranch
                        ? branchColor
                        : "var(--color-surface)",
                    }}
                  />

                  {/* Scenes */}
                  <div className="space-y-3">
                    {branchScenes.map((scene, index) => (
                      <motion.div
                        key={scene.id}
                        className="relative pr-10 group"
                        initial={{ opacity: 0, x: -20 }}
                        animate={{ opacity: 1, x: 0 }}
                        transition={{ delay: index * 0.05 }}
                      >
                        {/* Timeline dot */}
                        <div
                          className="absolute right-3.5 top-2 w-3 h-3 rounded-full border-2 bg-[var(--color-panel)]"
                          style={{
                            borderColor: isActiveBranch
                              ? branchColor
                              : "var(--color-surface)",
                          }}
                        />

                        {/* Scene card */}
                        <div
                          className="p-3 rounded-lg border border-[var(--color-surface)] hover:border-[var(--color-accent-weak)] bg-[var(--color-panel)] cursor-pointer transition-all"
                          onClick={() => onSceneClick?.(scene.id)}
                          draggable={mode === "nonlinear"}
                          onDragStart={() => setDraggedScene(scene)}
                          onDragEnd={() => setDraggedScene(null)}
                        >
                          <div className="flex items-start gap-2">
                            {mode === "nonlinear" && (
                              <div className="opacity-0 group-hover:opacity-100 transition-opacity">
                                <GripVertical className="w-4 h-4 text-[var(--color-muted)] cursor-grab active:cursor-grabbing mt-1" />
                              </div>
                            )}
                            <div className="flex-1">
                              <h4
                                className="text-[var(--color-text)]"
                                dir="rtl"
                              >
                                {scene.title}
                              </h4>
                              <div className="flex items-center gap-2 mt-1">
                                {scene.act && (
                                  <span className="text-[var(--color-muted)]">
                                    فصل {scene.act}
                                  </span>
                                )}
                                {scene.beat && (
                                  <Badge
                                    variant="secondary"
                                    className="bg-[var(--color-surface)] text-[var(--color-muted)]"
                                  >
                                    {scene.beat}
                                  </Badge>
                                )}
                              </div>
                            </div>
                            {mode === "nonlinear" && (
                              <Button
                                variant="ghost"
                                size="sm"
                                onClick={(e) => {
                                  e.stopPropagation();
                                  handleBranchCreate(scene.id, "A");
                                }}
                                className="opacity-0 group-hover:opacity-100 transition-opacity text-[var(--color-accent)] hover:bg-[var(--color-surface)]"
                                title="إنشاء فرع"
                              >
                                <Copy className="w-4 h-4" />
                              </Button>
                            )}
                          </div>
                          {draggedScene?.id === scene.id && (
                            <motion.div
                              className="absolute inset-0 border-2 border-dashed border-[var(--color-accent)] rounded-lg pointer-events-none"
                              initial={{ opacity: 0 }}
                              animate={{ opacity: 1 }}
                            />
                          )}
                        </div>
                      </motion.div>
                    ))}
                  </div>
                </div>
              </div>
            );
          })}
        </div>
      )}
    </div>
  );
}

import { motion, AnimatePresence } from "framer-motion";
import { Search, X } from "lucide-react";
import React, { useState, useEffect, useCallback } from "react";

import { Input } from "@/components/ui/input";
import {
  Sheet,
  SheetContent,
  SheetHeader,
  SheetTitle,
} from "@/components/ui/sheet";
import { useIsMobile } from "@/hooks/use-mobile";
import { useNotifications } from "@/hooks/use-notifications";

interface Command {
  id: string;
  label: string;
  icon?: React.ReactNode;
  action: () => void;
  shortcut?: string;
}

interface RadialCommandPaletteProps {
  isOpen: boolean;
  onClose: () => void;
  context?: "global" | "editor" | "analysis" | "development" | "brainstorm";
  commands: Command[];
}

// Custom debounce hook
function useDebounce<T>(value: T, delay: number): T {
  const [debouncedValue, setDebouncedValue] = useState<T>(value);

  useEffect(() => {
    const handler = setTimeout(() => {
      setDebouncedValue(value);
    }, delay);

    return () => {
      clearTimeout(handler);
    };
  }, [value, delay]);

  return debouncedValue;
}

export function RadialCommandPalette({
  isOpen,
  onClose,
  context = "global",
  commands,
}: RadialCommandPaletteProps) {
  const notifications = useNotifications();
  const [search, setSearch] = useState("");
  const isMobile = useIsMobile();
  const debouncedSearch = useDebounce(search, 180);
  const [filteredCommands, setFilteredCommands] = useState(commands);

  // Filter commands with debounced search
  useEffect(() => {
    if (debouncedSearch) {
      setFilteredCommands(
        commands.filter((cmd) =>
          cmd.label.toLowerCase().includes(debouncedSearch.toLowerCase())
        )
      );
    } else {
      setFilteredCommands(commands);
    }
  }, [debouncedSearch, commands]);

  useEffect(() => {
    const handleKeyDown = (e: KeyboardEvent) => {
      if (e.key === "Escape" && isOpen) {
        onClose();
      }
    };

    window.addEventListener("keydown", handleKeyDown);
    return () => window.removeEventListener("keydown", handleKeyDown);
  }, [isOpen, onClose]);

  const handleCommandClick = useCallback(
    (cmd: Command) => {
      try {
        cmd.action();
        notifications.success(`تم تنفيذ: ${cmd.label}`);
        onClose();
      } catch {
        notifications.error("فشل تنفيذ الأمر");
      }
    },
    [notifications, onClose]
  );

  // Mobile view (Bottom Sheet)
  if (isMobile) {
    return (
      <Sheet open={isOpen} onOpenChange={onClose}>
        <SheetContent
          side="bottom"
          className="bg-[var(--color-panel)] border-[var(--color-surface)] h-[80vh] rounded-t-3xl"
        >
          <SheetHeader className="border-b border-[var(--color-surface)] pb-4">
            <SheetTitle
              className="text-[var(--color-text)] text-right"
              dir="rtl"
            >
              لوحة الأوامر
            </SheetTitle>
          </SheetHeader>

          <div className="mt-4 space-y-4">
            <div className="relative">
              <Search className="absolute right-3 top-1/2 -translate-y-1/2 w-5 h-5 text-[var(--color-muted)]" />
              <Input
                value={search}
                onChange={(e) => setSearch(e.target.value)}
                placeholder="ابحث عن أمر..."
                className="pr-10 bg-[var(--color-surface)] border-[var(--color-surface)] text-[var(--color-text)]"
                dir="rtl"
              />
            </div>

            <div className="space-y-2 overflow-y-auto max-h-[60vh]">
              {filteredCommands.length === 0 ? (
                <div
                  className="text-center py-12 text-[var(--color-muted)]"
                  dir="rtl"
                >
                  لا توجد نتائج
                </div>
              ) : (
                filteredCommands.map((cmd, index) => (
                  <motion.button
                    key={cmd.id}
                    className="w-full flex items-center gap-3 p-4 rounded-lg bg-[var(--color-surface)] hover:bg-[var(--color-accent)]/10 transition-colors text-right border border-transparent hover:border-[var(--color-accent)]/30"
                    onClick={() => handleCommandClick(cmd)}
                    initial={{ opacity: 0, y: 20 }}
                    animate={{ opacity: 1, y: 0 }}
                    transition={{ delay: index * 0.03 }}
                  >
                    {cmd.icon && (
                      <div className="text-[var(--color-accent)]">
                        {cmd.icon}
                      </div>
                    )}
                    <span className="flex-1 text-[var(--color-text)]">
                      {cmd.label}
                    </span>
                    {cmd.shortcut && (
                      <span className="text-[var(--color-muted)] px-2 py-1 bg-[var(--color-bg)] rounded text-sm">
                        {cmd.shortcut}
                      </span>
                    )}
                  </motion.button>
                ))
              )}
            </div>
          </div>
        </SheetContent>
      </Sheet>
    );
  }

  // Desktop view (Modal)
  return (
    <AnimatePresence>
      {isOpen && (
        <>
          <motion.div
            className="fixed inset-0 bg-black/60 backdrop-blur-sm z-50"
            initial={{ opacity: 0 }}
            animate={{ opacity: 1 }}
            exit={{ opacity: 0 }}
            onClick={onClose}
          />
          <motion.div
            className="fixed top-1/2 left-1/2 -translate-x-1/2 -translate-y-1/2 z-50 w-[600px] max-w-[90vw]"
            initial={{ opacity: 0, scale: 0.9, y: 20 }}
            animate={{ opacity: 1, scale: 1, y: 0 }}
            exit={{ opacity: 0, scale: 0.9, y: 20 }}
            transition={{ duration: 0.2 }}
          >
            <div className="bg-[var(--color-panel)] border border-[var(--color-surface)] rounded-2xl overflow-hidden backdrop-blur-xl shadow-2xl">
              <div className="flex items-center gap-3 px-4 py-3 border-b border-[var(--color-surface)]">
                <Search className="w-5 h-5 text-[var(--color-muted)]" />
                <Input
                  value={search}
                  onChange={(e) => setSearch(e.target.value)}
                  placeholder="ابحث عن أمر..."
                  className="flex-1 bg-transparent border-none focus-visible:ring-0 text-[var(--color-text)] placeholder:text-[var(--color-muted)]"
                  autoFocus
                  dir="rtl"
                />
                <button
                  onClick={onClose}
                  className="p-1 hover:bg-[var(--color-surface)] rounded-lg transition-colors"
                >
                  <X className="w-5 h-5 text-[var(--color-muted)]" />
                </button>
              </div>

              <div className="max-h-[400px] overflow-y-auto p-2">
                {filteredCommands.length === 0 ? (
                  <div
                    className="text-center py-8 text-[var(--color-muted)]"
                    dir="rtl"
                  >
                    لا توجد نتائج
                  </div>
                ) : (
                  filteredCommands.map((cmd, index) => (
                    <motion.button
                      key={cmd.id}
                      className="w-full flex items-center gap-3 px-4 py-3 rounded-lg hover:bg-[var(--color-surface)] transition-colors text-right"
                      onClick={() => handleCommandClick(cmd)}
                      initial={{ opacity: 0, x: -20 }}
                      animate={{ opacity: 1, x: 0 }}
                      transition={{ delay: index * 0.03 }}
                    >
                      {cmd.icon && (
                        <div className="text-[var(--color-accent)]">
                          {cmd.icon}
                        </div>
                      )}
                      <span className="flex-1 text-[var(--color-text)]">
                        {cmd.label}
                      </span>
                      {cmd.shortcut && (
                        <span className="text-[var(--color-muted)] px-2 py-1 bg-[var(--color-bg)] rounded">
                          {cmd.shortcut}
                        </span>
                      )}
                    </motion.button>
                  ))
                )}
              </div>

              <div className="px-4 py-2 border-t border-[var(--color-surface)] text-[var(--color-muted)] flex items-center justify-between">
                <span>السياق: {context}</span>
                <span>Space للفتح • ESC للإغلاق</span>
              </div>
            </div>
          </motion.div>
        </>
      )}
    </AnimatePresence>
  );
}

