import { AgentReportsExporter } from "./agent-reports-exporter";

import type { AgentTaskResult } from "./agent-reports-exporter";

// ---------------------------------------------------------------------------
// Browser API mocks
// ---------------------------------------------------------------------------

const mockRevokeObjectURL = vi.fn();
const mockCreateObjectURL = vi.fn(() => "blob:mock-url");

// Track Blob constructor calls so we can inspect content
let lastBlobContent = "";
let lastBlobOptions: BlobPropertyBag = {};

class MockBlob {
  constructor(parts: BlobPart[], options?: BlobPropertyBag) {
    lastBlobContent = parts.join("");
    lastBlobOptions = options ?? {};
  }
}

// Mock anchor click so no real navigation happens
const mockAnchorClick = vi.fn();
const mockAppendChild = vi.fn();
const mockRemoveChild = vi.fn();

// Mock useToast so the component doesn't fail due to missing toast context
vi.mock("@/hooks/use-toast", () => ({
  useToast: () => ({ toast: vi.fn() }),
}));

beforeEach(() => {
  vi.stubGlobal("Blob", MockBlob);
  vi.stubGlobal("URL", {
    createObjectURL: mockCreateObjectURL,
    revokeObjectURL: mockRevokeObjectURL,
  });

  // Mock document.createElement to intercept anchor creation
  const originalCreateElement = document.createElement.bind(document);
  vi.spyOn(document, "createElement").mockImplementation((tag: string) => {
    if (tag === "a") {
      const anchor = originalCreateElement("a");
      anchor.click = mockAnchorClick;
      return anchor;
    }
    return originalCreateElement(tag);
  });

  vi.spyOn(document.body, "appendChild").mockImplementation(mockAppendChild);
  vi.spyOn(document.body, "removeChild").mockImplementation(mockRemoveChild);
});

afterEach(() => {
  vi.restoreAllMocks();
  vi.unstubAllGlobals();
  lastBlobContent = "";
  lastBlobOptions = {};
  mockAnchorClick.mockClear();
  mockCreateObjectURL.mockClear();
  mockRevokeObjectURL.mockClear();
});

// ---------------------------------------------------------------------------
// Fixtures
// ---------------------------------------------------------------------------

const sampleReports: Record<string, unknown> = {
  "agent-alpha": "نتيجة الوكيل ألفا",
};

const completedStep1: AgentTaskResult = {
  agentName: "محلل التحليل",
  agentId: "analysis-step",
  text: "نتيجة خطوة التحليل التفصيلية",
  confidence: 0.9,
  timestamp: "2026-04-03T10:00:00Z",
};

const completedStep2: AgentTaskResult = {
  agentName: "مولد الإبداع",
  agentId: "creative-step",
  text: "نتيجة خطوة الإبداع التفصيلية",
  confidence: 0.85,
  timestamp: "2026-04-03T10:01:00Z",
};

// ---------------------------------------------------------------------------
// Helpers
// ---------------------------------------------------------------------------

function renderExporter(
  props: Partial<React.ComponentProps<typeof AgentReportsExporter>> = {}
) {
  const defaultProps = {
    reports: sampleReports,
    originalText: "النص الأصلي للنص الدرامي",
  };
  return render(<AgentReportsExporter {...defaultProps} {...props} />);
}

function clickJsonExport() {
  fireEvent.click(screen.getByRole("button", { name: /تصدير json/i }));
}

function clickTextExport() {
  fireEvent.click(screen.getByRole("button", { name: /تصدير نصي/i }));
}

// ---------------------------------------------------------------------------
// JSON Export Tests
// ---------------------------------------------------------------------------

describe("AgentReportsExporter — JSON export", () => {
  it("produces valid JSON containing the reports object", () => {
    renderExporter();
    clickJsonExport();

    const parsed = JSON.parse(lastBlobContent) as Record<string, unknown>;
    expect(parsed).toHaveProperty("reports");
    expect((parsed.reports as Record<string, unknown>)["agent-alpha"]).toBe(
      "نتيجة الوكيل ألفا"
    );
  });

  it("includes taskResults in JSON export when provided", () => {
    const taskResults: Record<string, AgentTaskResult> = {
      "analysis-step": completedStep1,
      "creative-step": completedStep2,
    };

    renderExporter({ taskResults });
    clickJsonExport();

    const parsed = JSON.parse(lastBlobContent) as Record<string, unknown>;
    expect(parsed).toHaveProperty("taskResults");

    const exportedResults = parsed.taskResults as Record<
      string,
      AgentTaskResult
    >;
    expect(exportedResults).toHaveProperty("analysis-step");
    expect(exportedResults["analysis-step"].text).toBe(
      "نتيجة خطوة التحليل التفصيلية"
    );
    expect(exportedResults["analysis-step"].agentName).toBe("محلل التحليل");
    expect(exportedResults).toHaveProperty("creative-step");
    expect(exportedResults["creative-step"].text).toBe(
      "نتيجة خطوة الإبداع التفصيلية"
    );
  });

  it("includes originalText in JSON export", () => {
    renderExporter({ taskResults: { "analysis-step": completedStep1 } });
    clickJsonExport();

    const parsed = JSON.parse(lastBlobContent) as Record<string, unknown>;
    expect(parsed).toHaveProperty("originalText", "النص الأصلي للنص الدرامي");
  });

  it("taskResults defaults to empty object when not provided", () => {
    renderExporter();
    clickJsonExport();

    const parsed = JSON.parse(lastBlobContent) as Record<string, unknown>;
    expect(parsed).toHaveProperty("taskResults");
    expect(parsed.taskResults).toEqual({});
  });

  it("uses application/json MIME type", () => {
    renderExporter({ taskResults: { "analysis-step": completedStep1 } });
    clickJsonExport();

    expect(lastBlobOptions.type).toBe("application/json");
  });

  it("triggers file download (createObjectURL + anchor click)", () => {
    renderExporter({ taskResults: { "analysis-step": completedStep1 } });
    clickJsonExport();

    expect(mockCreateObjectURL).toHaveBeenCalledOnce();
    expect(mockAnchorClick).toHaveBeenCalledOnce();
    expect(mockRevokeObjectURL).toHaveBeenCalledWith("blob:mock-url");
  });
});

// ---------------------------------------------------------------------------
// Text / Markdown Export Tests
// ---------------------------------------------------------------------------

describe("AgentReportsExporter — Text/Markdown export", () => {
  it("produces text containing agent report sections", () => {
    renderExporter();
    clickTextExport();

    expect(lastBlobContent).toContain("نتائج التحليل");
    expect(lastBlobContent).toContain("agent-alpha");
    expect(lastBlobContent).toContain("نتيجة الوكيل ألفا");
  });

  it("includes originalText section when originalText is provided", () => {
    renderExporter({ originalText: "نص درامي تجريبي" });
    clickTextExport();

    expect(lastBlobContent).toContain("النص الأصلي");
    expect(lastBlobContent).toContain("نص درامي تجريبي");
  });

  it("appends ## {agentName} heading for each completed step", () => {
    const taskResults: Record<string, AgentTaskResult> = {
      "analysis-step": completedStep1,
      "creative-step": completedStep2,
    };

    renderExporter({ taskResults });
    clickTextExport();

    expect(lastBlobContent).toContain("## محلل التحليل");
    expect(lastBlobContent).toContain("## مولد الإبداع");
  });

  it("appends step text body after each heading", () => {
    const taskResults: Record<string, AgentTaskResult> = {
      "analysis-step": completedStep1,
    };

    renderExporter({ taskResults });
    clickTextExport();

    expect(lastBlobContent).toContain("نتيجة خطوة التحليل التفصيلية");
  });

  it("appends supporting steps section header when taskResults are present", () => {
    const taskResults: Record<string, AgentTaskResult> = {
      "analysis-step": completedStep1,
    };

    renderExporter({ taskResults });
    clickTextExport();

    expect(lastBlobContent).toContain("النتائج الداعمة");
  });

  it("does not append supporting steps section when taskResults is empty", () => {
    renderExporter({ taskResults: {} });
    clickTextExport();

    expect(lastBlobContent).not.toContain("النتائج الداعمة");
  });

  it("does not append supporting steps section when taskResults is undefined", () => {
    renderExporter({ taskResults: undefined });
    clickTextExport();

    expect(lastBlobContent).not.toContain("النتائج الداعمة");
  });

  it("skips steps with empty text from the supporting steps section", () => {
    const taskResults: Record<string, AgentTaskResult> = {
      "analysis-step": completedStep1,
      "empty-step": {
        agentName: "وكيل فارغ",
        agentId: "empty-step",
        text: "",
        confidence: 0,
        timestamp: "2026-04-03T10:02:00Z",
      },
      "whitespace-step": {
        agentName: "وكيل مسافات",
        agentId: "whitespace-step",
        text: "   ",
        confidence: 0,
        timestamp: "2026-04-03T10:03:00Z",
      },
    };

    renderExporter({ taskResults });
    clickTextExport();

    // Sections with text present
    expect(lastBlobContent).toContain("## محلل التحليل");
    // Steps without meaningful text must NOT appear as headings
    expect(lastBlobContent).not.toContain("## وكيل فارغ");
    expect(lastBlobContent).not.toContain("## وكيل مسافات");
  });

  it("uses text/plain MIME type with utf-8 charset", () => {
    renderExporter({ taskResults: { "analysis-step": completedStep1 } });
    clickTextExport();

    expect(lastBlobOptions.type).toBe("text/plain;charset=utf-8");
  });

  it("triggers file download for text export", () => {
    renderExporter({ taskResults: { "analysis-step": completedStep1 } });
    clickTextExport();

    expect(mockCreateObjectURL).toHaveBeenCalledOnce();
    expect(mockAnchorClick).toHaveBeenCalledOnce();
    expect(mockRevokeObjectURL).toHaveBeenCalledWith("blob:mock-url");
  });
});

// ---------------------------------------------------------------------------
// Missing / Empty taskResults — Robustness
// ---------------------------------------------------------------------------

describe("AgentReportsExporter — missing/empty taskResults robustness", () => {
  it("JSON export does not throw when taskResults is undefined", () => {
    renderExporter({ taskResults: undefined });
    expect(() => clickJsonExport()).not.toThrow();
  });

  it("JSON export does not throw when taskResults is empty object", () => {
    renderExporter({ taskResults: {} });
    expect(() => clickJsonExport()).not.toThrow();
    const parsed = JSON.parse(lastBlobContent) as Record<string, unknown>;
    expect(parsed.taskResults).toEqual({});
  });

  it("Text export does not throw when taskResults is undefined", () => {
    renderExporter({ taskResults: undefined });
    expect(() => clickTextExport()).not.toThrow();
  });

  it("Text export does not throw when taskResults is empty object", () => {
    renderExporter({ taskResults: {} });
    expect(() => clickTextExport()).not.toThrow();
    expect(lastBlobContent.length).toBeGreaterThan(0);
  });

  it("export buttons are disabled when reports object is empty", () => {
    render(<AgentReportsExporter reports={{}} originalText="نص" />);

    expect(screen.getByRole("button", { name: /تصدير json/i })).toBeDisabled();
    expect(screen.getByRole("button", { name: /تصدير نصي/i })).toBeDisabled();
  });

  it("export buttons are enabled when reports has at least one entry", () => {
    renderExporter();

    expect(
      screen.getByRole("button", { name: /تصدير json/i })
    ).not.toBeDisabled();
    expect(
      screen.getByRole("button", { name: /تصدير نصي/i })
    ).not.toBeDisabled();
  });
});

// ---------------------------------------------------------------------------
// onExport callback
// ---------------------------------------------------------------------------

describe("AgentReportsExporter — onExport callback", () => {
  it("calls onExport with 'json' after successful JSON export", () => {
    const onExport = vi.fn();
    renderExporter({ onExport });
    clickJsonExport();

    expect(onExport).toHaveBeenCalledExactlyOnceWith("json");
  });

  it("calls onExport with 'txt' after successful text export", () => {
    const onExport = vi.fn();
    renderExporter({ onExport });
    clickTextExport();

    expect(onExport).toHaveBeenCalledExactlyOnceWith("txt");
  });
});

"use client";

import { Download } from "lucide-react";
import React from "react";

import { Button } from "@/components/ui/button";
import { useToast } from "@/hooks/use-toast";

export interface AgentTaskResult {
  agentName: string;
  agentId: string;
  text: string;
  confidence: number;
  timestamp: string;
}

export interface AgentReportsExporterProps {
  reports: Record<string, any>;
  originalText?: string;
  taskResults?: Record<string, AgentTaskResult>;
  onExport?: (format: string) => void;
}

export const AgentReportsExporter: React.FC<AgentReportsExporterProps> = ({
  reports,
  originalText,
  taskResults,
  onExport,
}) => {
  const { toast } = useToast();

  const handleExport = (format: "txt" | "json") => {
    try {
      let content: string;
      let filename: string;
      let mimeType: string;

      if (format === "json") {
        content = JSON.stringify(
          { reports, originalText, taskResults: taskResults ?? {} },
          null,
          2
        );
        filename = `agent-reports-${Date.now()}.json`;
        mimeType = "application/json";
      } else {
        // Text format
        const sections: string[] = [
          "===========================================",
          "تقرير التحليل الإبداعي - جميع الوكلاء",
          "===========================================",
          "",
        ];

        if (originalText) {
          sections.push("## النص الأصلي");
          sections.push("-------------------------------------------");
          sections.push(originalText);
          sections.push("");
        }

        sections.push("## نتائج التحليل");
        sections.push("-------------------------------------------");

        Object.entries(reports).forEach(([agentId, report]) => {
          sections.push(`### ${agentId}`);
          sections.push(
            typeof report === "string"
              ? report
              : JSON.stringify(report, null, 2)
          );
          sections.push("");
        });

        // Append each supporting step as a Markdown section
        if (taskResults) {
          const completedSteps = Object.values(taskResults).filter((step) =>
            step.text?.trim()
          );
          if (completedSteps.length > 0) {
            sections.push("## النتائج الداعمة");
            sections.push("-------------------------------------------");
            sections.push("");
            for (const step of completedSteps) {
              sections.push(`## ${step.agentName}`);
              sections.push("");
              sections.push(step.text);
              sections.push("");
            }
          }
        }

        sections.push("===========================================");
        sections.push("نهاية التقرير");
        sections.push("===========================================");

        content = sections.join("\n");
        filename = `agent-reports-${Date.now()}.txt`;
        mimeType = "text/plain;charset=utf-8";
      }

      const blob = new Blob([content], { type: mimeType });
      const url = URL.createObjectURL(blob);
      const a = document.createElement("a");
      a.href = url;
      a.download = filename;
      document.body.appendChild(a);
      a.click();
      document.body.removeChild(a);
      URL.revokeObjectURL(url);

      if (onExport) {
        onExport(format);
      }

      toast({
        title: "تم التصدير بنجاح",
        description: `تم تصدير التقرير بصيغة ${format.toUpperCase()}`,
      });
    } catch (error) {
      toast({
        title: "فشل التصدير",
        description:
          error instanceof Error ? error.message : "حدث خطأ غير متوقع",
        variant: "destructive",
      });
    }
  };

  const hasReports = Object.keys(reports).length > 0;

  return (
    <div className="flex gap-2">
      <Button
        onClick={() => handleExport("txt")}
        disabled={!hasReports}
        variant="outline"
        className="gap-2"
      >
        <Download className="h-4 w-4" />
        تصدير نصي
      </Button>
      <Button
        onClick={() => handleExport("json")}
        disabled={!hasReports}
        variant="outline"
        className="gap-2"
      >
        <Download className="h-4 w-4" />
        تصدير JSON
      </Button>
    </div>
  );
};

"use client";

import { useState, useEffect } from "react";

import { logger } from "@/lib/ai/utils/logger";

/**
 * إعدادات BYO-API
 * Bring Your Own API Settings Component
 *
 * المبادئ:
 * 1. لا يتم إرسال مفاتيح API إلى السيرفر
 * 2. التخزين المحلي المشفر فقط
 * 3. الاتصال المباشر بمزود الخدمة
 */

import {
  saveAPIConfig,
  listAPIConfigs,
  deleteAPIConfig,
  testAPIConnection,
  type APIProviderConfig,
} from "@/lib/crypto";

export function BYOAPISettings() {
  const [providers, setProviders] = useState<
    Omit<APIProviderConfig, "apiKey">[]
  >([]);
  const [isAdding, setIsAdding] = useState(false);
  const [formData, setFormData] = useState({
    providerName: "",
    endpointUrl: "",
    apiKey: "",
  });
  const [testing, setTesting] = useState(false);
  const [testResult, setTestResult] = useState<{
    success: boolean;
    message: string;
  } | null>(null);
  const [error, setError] = useState<string | null>(null);

  useEffect(() => {
    loadProviders();
  }, []);

  const loadProviders = async () => {
    try {
      const list = await listAPIConfigs();
      setProviders(list);
    } catch (err) {
      logger.error("خطأ في تحميل المزودين:", err);
    }
  };

  const handleSave = async (e: React.FormEvent) => {
    e.preventDefault();
    setError(null);

    try {
      const config: APIProviderConfig = {
        id: Date.now().toString(),
        providerName: formData.providerName,
        endpointUrl: formData.endpointUrl,
        apiKey: formData.apiKey,
      };

      await saveAPIConfig(config);

      // إعادة تعيين النموذج
      setFormData({ providerName: "", endpointUrl: "", apiKey: "" });
      setIsAdding(false);
      await loadProviders();
    } catch (err) {
      logger.error("خطأ في الحفظ:", err);
      setError("فشل في حفظ الإعدادات");
    }
  };

  const handleTest = async () => {
    setTesting(true);
    setTestResult(null);

    try {
      const config: APIProviderConfig = {
        id: "test",
        providerName: formData.providerName,
        endpointUrl: formData.endpointUrl,
        apiKey: formData.apiKey,
      };

      const result = await testAPIConnection(config);
      setTestResult(result);
    } catch (err) {
      logger.error("خطأ في الاختبار:", err);
      setTestResult({
        success: false,
        message: "فشل في اختبار الاتصال",
      });
    } finally {
      setTesting(false);
    }
  };

  const handleDelete = async (id: string) => {
    if (!confirm("هل أنت متأكد من حذف هذا المزود؟")) {
      return;
    }

    try {
      await deleteAPIConfig(id);
      await loadProviders();
    } catch (err) {
      logger.error("خطأ في الحذف:", err);
      setError("فشل في حذف المزود");
    }
  };

  return (
    <div className="max-w-4xl mx-auto p-6" dir="rtl">
      <h2 className="text-2xl font-bold mb-6">إعدادات BYO-API</h2>

      {/* تحذير أمني */}
      <div className="bg-yellow-50 border-2 border-yellow-400 rounded p-4 mb-6">
        <h3 className="font-bold text-lg mb-2">⚠️ مهم: BYO-API</h3>
        <ul className="text-sm space-y-1 list-disc list-inside">
          <li>
            <strong>الفوترة:</strong> أنت المسؤول عن جميع التكاليف والفواتير في
            حسابك لدى مزود الخدمة
          </li>
          <li>
            <strong>الأمان:</strong> مفاتيح API تُخزن محلياً فقط على جهازك
            (مشفرة)
          </li>
          <li>
            <strong>الاتصال:</strong> الطلبات تذهب مباشرة من متصفحك إلى مزود
            الخدمة (لا تمر عبر خوادمنا)
          </li>
          <li>
            <strong>الخصوصية:</strong> لا نستطيع رؤية أو الوصول إلى مفاتيحك أو
            طلباتك
          </li>
        </ul>
      </div>

      {error && (
        <div className="bg-red-50 border border-red-300 text-red-700 rounded p-3 mb-4">
          {error}
        </div>
      )}

      {/* قائمة المزودين الحاليين */}
      <div className="mb-6">
        <h3 className="text-lg font-semibold mb-3">المزودون المحفوظون</h3>
        {providers.length === 0 ? (
          <p className="text-gray-500">لا توجد إعدادات محفوظة</p>
        ) : (
          <div className="space-y-2">
            {providers.map((provider) => (
              <div
                key={provider.id}
                className="flex items-center justify-between p-3 border border-gray-300 rounded"
              >
                <div>
                  <p className="font-medium">{provider.providerName}</p>
                  <p className="text-sm text-gray-600" dir="ltr">
                    {provider.endpointUrl}
                  </p>
                </div>
                <button
                  onClick={() => handleDelete(provider.id)}
                  className="px-3 py-1 bg-red-500 text-white rounded hover:bg-red-600"
                >
                  حذف
                </button>
              </div>
            ))}
          </div>
        )}
      </div>

      {/* زر إضافة مزود جديد */}
      {!isAdding && (
        <button
          onClick={() => setIsAdding(true)}
          className="w-full py-2 px-4 bg-blue-600 text-white rounded hover:bg-blue-700"
        >
          + إضافة مزود جديد
        </button>
      )}

      {/* نموذج إضافة مزود */}
      {isAdding && (
        <div className="border border-gray-300 rounded p-4">
          <h3 className="text-lg font-semibold mb-4">إضافة مزود API</h3>

          <form onSubmit={handleSave} className="space-y-4">
            <div>
              <label className="block text-sm font-medium mb-1">
                اسم المزود
              </label>
              <input
                type="text"
                value={formData.providerName}
                onChange={(e) =>
                  setFormData({ ...formData, providerName: e.target.value })
                }
                required
                placeholder="مثال: Google Gemini, OpenAI, Groq"
                className="w-full px-3 py-2 border border-gray-300 rounded focus:outline-none focus:ring-2 focus:ring-blue-500"
              />
            </div>

            <div>
              <label className="block text-sm font-medium mb-1">
                Endpoint URL
              </label>
              <input
                type="url"
                value={formData.endpointUrl}
                onChange={(e) =>
                  setFormData({ ...formData, endpointUrl: e.target.value })
                }
                required
                placeholder="https://api.example.com/v1/chat"
                className="w-full px-3 py-2 border border-gray-300 rounded focus:outline-none focus:ring-2 focus:ring-blue-500"
                dir="ltr"
              />
            </div>

            <div>
              <label className="block text-sm font-medium mb-1">API Key</label>
              <input
                type="password"
                value={formData.apiKey}
                onChange={(e) =>
                  setFormData({ ...formData, apiKey: e.target.value })
                }
                required
                placeholder="sk-..."
                className="w-full px-3 py-2 border border-gray-300 rounded focus:outline-none focus:ring-2 focus:ring-blue-500"
                dir="ltr"
              />
            </div>

            {testResult && (
              <div
                className={`p-3 rounded ${
                  testResult.success
                    ? "bg-green-50 border border-green-300 text-green-700"
                    : "bg-red-50 border border-red-300 text-red-700"
                }`}
              >
                {testResult.message}
              </div>
            )}

            <div className="flex gap-2">
              <button
                type="button"
                onClick={handleTest}
                disabled={testing}
                className="flex-1 py-2 px-4 border border-blue-600 text-blue-600 rounded hover:bg-blue-50 disabled:opacity-50"
              >
                {testing ? "جارٍ الاختبار..." : "اختبار الاتصال"}
              </button>
              <button
                type="submit"
                className="flex-1 py-2 px-4 bg-blue-600 text-white rounded hover:bg-blue-700"
              >
                حفظ
              </button>
              <button
                type="button"
                onClick={() => {
                  setIsAdding(false);
                  setFormData({
                    providerName: "",
                    endpointUrl: "",
                    apiKey: "",
                  });
                  setTestResult(null);
                }}
                className="flex-1 py-2 px-4 border border-gray-300 rounded hover:bg-gray-100"
              >
                إلغاء
              </button>
            </div>
          </form>
        </div>
      )}
    </div>
  );
}

"use client";

import { useRouter } from "next/navigation";
import { useState } from "react";

import { logger } from "@/lib/ai/utils/logger";

/**
 * نموذج تسجيل الدخول Zero-Knowledge
 * Zero-Knowledge Login Form
 *
 * المبادئ:
 * 1. جلب kdfSalt من السيرفر أولاً
 * 2. اشتقاق authVerifier محلياً
 * 3. إرسال authVerifier للتحقق
 * 4. اشتقاق KEK وحفظه في الذاكرة
 */


import {
  deriveKEK,
  deriveAuthVerifier,
  uint8ArrayToBase64,
  base64ToUint8Array,
 getKeyManager } from "@/lib/crypto";


export function ZKLoginForm() {
  const router = useRouter();
  const [email, setEmail] = useState("");
  const [password, setPassword] = useState("");
  const [isLoading, setIsLoading] = useState(false);
  const [error, setError] = useState<string | null>(null);

  const handleLogin = async (e: React.FormEvent) => {
    e.preventDefault();
    setError(null);
    setIsLoading(true);

    try {
      // المرحلة 1: جلب kdfSalt من السيرفر
      const initResponse = await fetch("/api/auth/zk-login-init", {
        method: "POST",
        headers: {
          "Content-Type": "application/json",
        },
        body: JSON.stringify({ email }),
      });

      const initData = await initResponse.json();

      if (!initData.success) {
        setError(initData.error ?? "فشل في بدء تسجيل الدخول");
        return;
      }

      const kdfSalt = base64ToUint8Array(initData.data.kdfSalt);

      // المرحلة 2: اشتقاق authVerifier محلياً
      const authVerifierBytes = await deriveAuthVerifier(password, kdfSalt);
      const authVerifier = uint8ArrayToBase64(authVerifierBytes);

      // المرحلة 3: التحقق من authVerifier
      const verifyResponse = await fetch("/api/auth/zk-login-verify", {
        method: "POST",
        headers: {
          "Content-Type": "application/json",
        },
        body: JSON.stringify({
          email,
          authVerifier,
        }),
      });

      const verifyData = await verifyResponse.json();

      if (!verifyData.success) {
        setError(verifyData.error ?? "بيانات اعتماد غير صحيحة");
        return;
      }

      // المرحلة 4: اشتقاق KEK وحفظه في الذاكرة
      const kek = await deriveKEK(password, kdfSalt);
      const keyManager = getKeyManager();
      keyManager.setKEK(kek);

      // الانتقال إلى لوحة التحكم
      router.push("/dashboard");
    } catch (err) {
      logger.error("خطأ في تسجيل الدخول:", err);
      setError("حدث خطأ أثناء تسجيل الدخول");
    } finally {
      setIsLoading(false);
    }
  };

  return (
    <div
      className="max-w-md mx-auto p-6 bg-white rounded-lg shadow-md"
      dir="rtl"
    >
      <h2 className="text-2xl font-bold mb-6">تسجيل الدخول</h2>

      <div className="bg-blue-50 border border-blue-300 rounded p-3 mb-4 text-sm">
        <p className="font-semibold mb-1">🔒 Zero-Knowledge</p>
        <p className="text-xs">
          كلمة المرور تُستخدم فقط على جهازك لفك تشفير بياناتك.
        </p>
      </div>

      {error && (
        <div className="bg-red-50 border border-red-300 text-red-700 rounded p-3 mb-4">
          {error}
        </div>
      )}

      <form onSubmit={handleLogin} className="space-y-4">
        <div>
          <label className="block text-sm font-medium mb-1">
            البريد الإلكتروني
          </label>
          <input
            type="email"
            value={email}
            onChange={(e) => setEmail(e.target.value)}
            required
            className="w-full px-3 py-2 border border-gray-300 rounded focus:outline-none focus:ring-2 focus:ring-blue-500"
            dir="ltr"
          />
        </div>

        <div>
          <label className="block text-sm font-medium mb-1">كلمة المرور</label>
          <input
            type="password"
            value={password}
            onChange={(e) => setPassword(e.target.value)}
            required
            className="w-full px-3 py-2 border border-gray-300 rounded focus:outline-none focus:ring-2 focus:ring-blue-500"
          />
        </div>

        <button
          type="submit"
          disabled={isLoading}
          className="w-full bg-blue-600 text-white py-2 px-4 rounded hover:bg-blue-700 disabled:bg-gray-400 disabled:cursor-not-allowed"
        >
          {isLoading ? "جارٍ تسجيل الدخول..." : "تسجيل الدخول"}
        </button>
      </form>

      <div className="mt-4 text-center text-sm">
        <a href="/forgot-password" className="text-blue-600 hover:underline">
          نسيت كلمة المرور؟
        </a>
      </div>
    </div>
  );
}

"use client";

import { useRouter } from "next/navigation";
import { useState } from "react";

import { logger } from "@/lib/ai/utils/logger";

/**
 * نموذج تسجيل Zero-Knowledge
 * Zero-Knowledge Signup Form
 *
 * المبادئ:
 * 1. اشتقاق KEK و authVerifier من كلمة المرور
 * 2. إرسال authVerifier فقط إلى السيرفر
 * 3. KEK يبقى في الذاكرة فقط
 * 4. توليد وعرض Recovery Key
 */


import {
  generateSalt,
  deriveKEK,
  deriveAuthVerifier,
  generateRecoveryKey,
  uint8ArrayToBase64,
  encryptData,
  generateIV,
  arrayBufferToBase64,
 getKeyManager } from "@/lib/crypto";


export function ZKSignupForm() {
  const router = useRouter();
  const [email, setEmail] = useState("");
  const [password, setPassword] = useState("");
  const [confirmPassword, setConfirmPassword] = useState("");
  const [recoveryKey, setRecoveryKey] = useState<string | null>(null);
  const [isLoading, setIsLoading] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const [step, setStep] = useState<"signup" | "recovery">("signup");

  const handleSignup = async (e: React.FormEvent) => {
    e.preventDefault();
    setError(null);

    // التحقق من تطابق كلمات المرور
    if (password !== confirmPassword) {
      setError("كلمات المرور غير متطابقة");
      return;
    }

    // التحقق من قوة كلمة المرور
    if (password.length < 12) {
      setError("كلمة المرور يجب أن تكون 12 حرفاً على الأقل");
      return;
    }

    setIsLoading(true);

    try {
      // 1. توليد Salt عشوائي
      const kdfSalt = generateSalt();
      const kdfSaltBase64 = uint8ArrayToBase64(kdfSalt);

      // 2. اشتقاق authVerifier (للمصادقة)
      const authVerifierBytes = await deriveAuthVerifier(password, kdfSalt);
      const authVerifier = uint8ArrayToBase64(authVerifierBytes);

      // 3. اشتقاق KEK (للتشفير - يبقى في الذاكرة)
      const kek = await deriveKEK(password, kdfSalt);

      // 4. توليد Recovery Key
      const recoveryKeyStr = generateRecoveryKey();
      setRecoveryKey(recoveryKeyStr);

      // 5. إنشاء Recovery Artifact (مشفر بواسطة Recovery Key)
      const recoveryArtifact = await createRecoveryArtifact(
        recoveryKeyStr,
        kdfSaltBase64
      );

      // 6. إرسال البيانات إلى السيرفر (بدون KEK!)
      const response = await fetch("/api/auth/zk-signup", {
        method: "POST",
        headers: {
          "Content-Type": "application/json",
        },
        body: JSON.stringify({
          email,
          authVerifier,
          kdfSalt: kdfSaltBase64,
          recoveryArtifact: recoveryArtifact.ciphertext,
          recoveryIv: recoveryArtifact.iv,
        }),
      });

      const data = await response.json();

      if (!data.success) {
        setError(data.error ?? "فشل التسجيل");
        return;
      }

      // 7. حفظ KEK في الذاكرة
      const keyManager = getKeyManager();
      keyManager.setKEK(kek);

      // 8. الانتقال إلى عرض Recovery Key
      setStep("recovery");
    } catch (err) {
      logger.error("خطأ في التسجيل:", err);
      setError("حدث خطأ أثناء التسجيل");
    } finally {
      setIsLoading(false);
    }
  };

  const handleRecoveryKeySaved = () => {
    router.push("/dashboard");
  };

  if (step === "recovery") {
    return (
      <div
        className="max-w-md mx-auto p-6 bg-white rounded-lg shadow-md"
        dir="rtl"
      >
        <h2 className="text-2xl font-bold mb-4 text-red-600">
          ⚠️ مفتاح الاسترداد - احفظه الآن!
        </h2>
        <div className="bg-yellow-50 border-2 border-yellow-400 rounded p-4 mb-4">
          <p className="text-sm mb-2">
            هذا هو مفتاح الاسترداد الوحيد. إذا فقدت كلمة المرور، ستحتاج هذا
            المفتاح لاستعادة الوصول.
          </p>
          <div className="bg-white p-4 rounded border border-gray-300 font-mono text-lg text-center select-all">
            {recoveryKey}
          </div>
        </div>
        <div className="bg-red-50 border border-red-300 rounded p-3 mb-4">
          <ul className="text-sm list-disc list-inside space-y-1">
            <li>احفظ هذا المفتاح في مكان آمن</li>
            <li>لن يتم عرضه مرة أخرى</li>
            <li>بدونه، لا يمكن استعادة البيانات إذا فقدت كلمة المرور</li>
          </ul>
        </div>
        <button
          onClick={handleRecoveryKeySaved}
          className="w-full bg-blue-600 text-white py-2 px-4 rounded hover:bg-blue-700"
        >
          لقد حفظت المفتاح، المتابعة
        </button>
      </div>
    );
  }

  return (
    <div
      className="max-w-md mx-auto p-6 bg-white rounded-lg shadow-md"
      dir="rtl"
    >
      <h2 className="text-2xl font-bold mb-6">إنشاء حساب Zero-Knowledge</h2>

      <div className="bg-blue-50 border border-blue-300 rounded p-3 mb-4 text-sm">
        <p className="font-semibold mb-1">🔒 تشفير من طرف إلى طرف</p>
        <p className="text-xs">
          كلمة المرور لا تُرسل إلى السيرفر. جميع بياناتك مشفرة على جهازك.
        </p>
      </div>

      {error && (
        <div className="bg-red-50 border border-red-300 text-red-700 rounded p-3 mb-4">
          {error}
        </div>
      )}

      <form onSubmit={handleSignup} className="space-y-4">
        <div>
          <label className="block text-sm font-medium mb-1">
            البريد الإلكتروني
          </label>
          <input
            type="email"
            value={email}
            onChange={(e) => setEmail(e.target.value)}
            required
            className="w-full px-3 py-2 border border-gray-300 rounded focus:outline-none focus:ring-2 focus:ring-blue-500"
            dir="ltr"
          />
        </div>

        <div>
          <label className="block text-sm font-medium mb-1">
            كلمة المرور (12 حرفاً على الأقل)
          </label>
          <input
            type="password"
            value={password}
            onChange={(e) => setPassword(e.target.value)}
            required
            minLength={12}
            className="w-full px-3 py-2 border border-gray-300 rounded focus:outline-none focus:ring-2 focus:ring-blue-500"
          />
        </div>

        <div>
          <label className="block text-sm font-medium mb-1">
            تأكيد كلمة المرور
          </label>
          <input
            type="password"
            value={confirmPassword}
            onChange={(e) => setConfirmPassword(e.target.value)}
            required
            minLength={12}
            className="w-full px-3 py-2 border border-gray-300 rounded focus:outline-none focus:ring-2 focus:ring-blue-500"
          />
        </div>

        <button
          type="submit"
          disabled={isLoading}
          className="w-full bg-blue-600 text-white py-2 px-4 rounded hover:bg-blue-700 disabled:bg-gray-400 disabled:cursor-not-allowed"
        >
          {isLoading ? "جارٍ التسجيل..." : "إنشاء حساب"}
        </button>
      </form>
    </div>
  );
}

/**
 * إنشاء Recovery Artifact
 */
async function createRecoveryArtifact(
  recoveryKey: string,
  kdfSalt: string
): Promise<{ ciphertext: string; iv: string }> {
  const encoder = new TextEncoder();
  const recoveryKeyBytes = encoder.encode(recoveryKey.replace(/-/g, ""));

  const recoveryKek = await crypto.subtle.importKey(
    "raw",
    recoveryKeyBytes.slice(0, 32),
    { name: "AES-GCM", length: 256 },
    false,
    ["encrypt", "decrypt"]
  );

  const iv = generateIV();
  const aad = encoder.encode("recovery-artifact");

  const { ciphertext } = await encryptData(kdfSalt, recoveryKek, aad);

  return {
    ciphertext: arrayBufferToBase64(ciphertext),
    iv: uint8ArrayToBase64(iv),
  };
}

/**
 * Device Detection and Performance Optimization
 *
 * Detects device capabilities and adjusts performance settings
 * for particle systems and animations
 */

export interface DeviceCapabilities {
  deviceType: "mobile" | "tablet" | "desktop";
  performanceTier: "low" | "medium" | "high";
  supportsWebGL: boolean;
  pixelRatio: number;
  maxTextureSize: number;
  isTouchDevice: boolean;
  isLowPowerMode: boolean;
  hardwareConcurrency: number;
  memoryGB: number | null;
}

export interface ParticleLODConfig {
  particleCount: number;
  effectRadius: number;
  updateFrequency: number; // ms
  enableAdvancedEffects: boolean;
  enableShadows: boolean;
  textureQuality: "low" | "medium" | "high";
}

/**
 * Detect device type based on screen size and user agent
 */
export function detectDeviceType(): "mobile" | "tablet" | "desktop" {
  if (typeof window === "undefined") return "desktop";

  const width = window.innerWidth;
  const userAgent = navigator.userAgent.toLowerCase();

  // Check user agent
  const isMobile = /mobile|android|iphone|ipod|blackberry|windows phone/.test(
    userAgent
  );
  const isTablet = /tablet|ipad/.test(userAgent);

  // Check screen size
  if (width < 768) {
    return "mobile";
  } else if (width < 1024) {
    return isTablet ? "tablet" : "mobile";
  } else {
    return isMobile ? "tablet" : "desktop";
  }
}

/**
 * Check if device supports WebGL
 */
export function supportsWebGL(): boolean {
  if (typeof window === "undefined") return false;

  try {
    const canvas = document.createElement("canvas");
    const gl =
      canvas.getContext("webgl") ?? canvas.getContext("experimental-webgl");
    return !!gl;
  } catch {
    return false;
  }
}

/**
 * Get maximum texture size supported by GPU
 */
export function getMaxTextureSize(): number {
  if (typeof window === "undefined") return 2048;

  try {
    const canvas = document.createElement("canvas");
    const gl =
      canvas.getContext("webgl") ??
      (canvas.getContext("experimental-webgl") as WebGLRenderingContext | null);

    if (gl) {
      return gl.getParameter(gl.MAX_TEXTURE_SIZE);
    }
  } catch (e) {
    console.warn("Failed to get max texture size:", e);
  }

  return 2048; // Default fallback
}

/**
 * Detect if device is in low power mode (battery saving)
 */
export async function detectLowPowerMode(): Promise<boolean> {
  if (typeof navigator === "undefined") return false;

  // Check Battery API (if available)
  if ("getBattery" in navigator) {
    try {
      const battery = await (
        navigator as Navigator & {
          getBattery(): Promise<{ charging: boolean; level: number }>;
        }
      ).getBattery();

      // Consider low power mode if:
      // - Battery is charging and level is low (< 20%)
      // - Battery is not charging and level is critically low (< 15%)
      if (!battery.charging && battery.level < 0.15) {
        return true;
      }
      if (battery.level < 0.2) {
        return true;
      }
    } catch (e) {
      console.warn("Battery API not supported:", e);
    }
  }

  // Check for reduced motion preference (often enabled in low power mode)
  if (typeof window !== "undefined" && window.matchMedia) {
    const prefersReducedMotion = window.matchMedia(
      "(prefers-reduced-motion: reduce)"
    ).matches;
    return prefersReducedMotion;
  }

  return false;
}

/**
 * Synchronous version of isLowPowerMode for immediate checks
 */
export function isLowPowerMode(): boolean {
  if (typeof window === "undefined") return false;

  // Check for reduced motion preference (often enabled in low power mode)
  if (window.matchMedia) {
    const prefersReducedMotion = window.matchMedia(
      "(prefers-reduced-motion: reduce)"
    ).matches;
    return prefersReducedMotion;
  }

  return false;
}

/**
 * Get hardware concurrency (CPU cores)
 */
export function getHardwareConcurrency(): number {
  if (typeof navigator === "undefined") return 4;
  return navigator.hardwareConcurrency || 4;
}

/**
 * Get device memory (if available)
 */
export function getDeviceMemory(): number | null {
  if (typeof navigator === "undefined") return null;

  const memory = (navigator as Navigator & { deviceMemory?: number })
    .deviceMemory;
  return typeof memory === "number" ? memory : null;
}

/**
 * Calculate performance tier based on device capabilities
 */
export function calculatePerformanceTier(
  deviceType: string,
  cores: number,
  memory: number | null,
  webglSupport: boolean
): "low" | "medium" | "high" {
  // Low tier criteria
  if (!webglSupport) return "low";
  if (deviceType === "mobile" && (memory === null || memory < 4)) return "low";
  if (cores <= 2) return "low";

  // High tier criteria
  if (
    deviceType === "desktop" &&
    cores >= 8 &&
    (memory === null || memory >= 8)
  )
    return "high";
  if (deviceType === "desktop" && cores >= 4) return "high";

  // Medium tier (default)
  return "medium";
}

/**
 * Get complete device capabilities
 */
export function getDeviceCapabilities(): DeviceCapabilities {
  const deviceType = detectDeviceType();
  const supportsWebGLFlag = supportsWebGL();
  const hardwareConcurrency = getHardwareConcurrency();
  const memoryGB = getDeviceMemory();

  return {
    deviceType,
    performanceTier: calculatePerformanceTier(
      deviceType,
      hardwareConcurrency,
      memoryGB,
      supportsWebGLFlag
    ),
    supportsWebGL: supportsWebGLFlag,
    pixelRatio: typeof window !== "undefined" ? window.devicePixelRatio : 1,
    maxTextureSize: getMaxTextureSize(),
    isTouchDevice: typeof window !== "undefined" && "ontouchstart" in window,
    isLowPowerMode: isLowPowerMode(),
    hardwareConcurrency,
    memoryGB,
  };
}

/**
 * Get Level of Detail (LOD) configuration based on device capabilities
 */
export function getParticleLODConfig(
  capabilities: DeviceCapabilities
): ParticleLODConfig {
  const { performanceTier, deviceType, isLowPowerMode } = capabilities;

  // Low power mode overrides
  if (isLowPowerMode) {
    return {
      particleCount: 500,
      effectRadius: 100,
      updateFrequency: 100, // Update every 100ms
      enableAdvancedEffects: false,
      enableShadows: false,
      textureQuality: "low",
    };
  }

  // Performance tier based configurations
  switch (performanceTier) {
    case "high":
      return {
        particleCount: deviceType === "desktop" ? 3000 : 2000,
        effectRadius: 200,
        updateFrequency: 16, // ~60fps
        enableAdvancedEffects: true,
        enableShadows: deviceType === "desktop",
        textureQuality: "high",
      };

    case "medium":
      return {
        particleCount: deviceType === "mobile" ? 800 : 1500,
        effectRadius: 150,
        updateFrequency: 33, // ~30fps
        enableAdvancedEffects: deviceType !== "mobile",
        enableShadows: false,
        textureQuality: "medium",
      };

    case "low":
    default:
      return {
        particleCount: 500,
        effectRadius: 100,
        updateFrequency: 50, // ~20fps
        enableAdvancedEffects: false,
        enableShadows: false,
        textureQuality: "low",
      };
  }
}

/**
 * Monitor performance and adjust LOD dynamically
 */
export class PerformanceMonitor {
  private frameTimeHistory: number[] = [];
  private readonly historySize = 60; // Track last 60 frames
  private lastFrameTime = 0;
  private currentQualityLevel: "low" | "medium" | "high" = "high";
  private qualityAdjustmentCooldown = 0;
  private readonly cooldownFrames = 120; // Wait 2 seconds before adjusting again
  private isVisible = true;
  private visibilityChangeHandler?: () => void;

  constructor() {
    this.setupVisibilityListener();
  }

  /**
   * Setup Visibility API listener to pause/resume when tab is hidden/visible
   */
  private setupVisibilityListener(): void {
    if (typeof document === "undefined") return;

    this.visibilityChangeHandler = () => {
      this.isVisible = !document.hidden;

      if (!this.isVisible) {
        console.log("🔇 Tab hidden - pausing performance monitoring");
      } else {
        console.log("🔊 Tab visible - resuming performance monitoring");
        // Reset on visibility change to avoid FPS drops from tab switching
        this.reset();
      }
    };

    document.addEventListener("visibilitychange", this.visibilityChangeHandler);
  }

  recordFrame(currentTime: number): void {
    if (!this.isVisible) return; // Don't record frames when tab is hidden

    if (this.lastFrameTime > 0) {
      const frameTime = currentTime - this.lastFrameTime;
      this.frameTimeHistory.push(frameTime);

      if (this.frameTimeHistory.length > this.historySize) {
        this.frameTimeHistory.shift();
      }
    }
    this.lastFrameTime = currentTime;

    // Increment cooldown
    if (this.qualityAdjustmentCooldown > 0) {
      this.qualityAdjustmentCooldown--;
    }
  }

  getAverageFPS(): number {
    if (this.frameTimeHistory.length === 0) return 60;

    const avgFrameTime =
      this.frameTimeHistory.reduce((a, b) => a + b, 0) /
      this.frameTimeHistory.length;
    return 1000 / avgFrameTime;
  }

  shouldReduceQuality(targetFPS = 30): boolean {
    if (this.qualityAdjustmentCooldown > 0) return false;

    const avgFPS = this.getAverageFPS();
    const shouldReduce = avgFPS < targetFPS;

    if (shouldReduce) {
      this.qualityAdjustmentCooldown = this.cooldownFrames;
    }

    return shouldReduce;
  }

  shouldIncreaseQuality(targetFPS = 55): boolean {
    if (this.qualityAdjustmentCooldown > 0) return false;

    const avgFPS = this.getAverageFPS();
    const shouldIncrease =
      avgFPS > targetFPS && this.frameTimeHistory.length >= this.historySize;

    if (shouldIncrease) {
      this.qualityAdjustmentCooldown = this.cooldownFrames;
    }

    return shouldIncrease;
  }

  /**
   * Get dynamic LOD config based on current performance
   */
  getDynamicLODConfig(baseConfig: ParticleLODConfig): ParticleLODConfig {
    const fps = this.getAverageFPS();

    // If FPS is too low, reduce quality
    if (fps < 25) {
      this.currentQualityLevel = "low";
      return {
        particleCount: Math.floor(baseConfig.particleCount * 0.4),
        effectRadius: Math.floor(baseConfig.effectRadius * 0.6),
        updateFrequency: Math.max(baseConfig.updateFrequency * 2, 50),
        enableAdvancedEffects: false,
        enableShadows: false,
        textureQuality: "low",
      };
    }

    // If FPS is moderate, use medium quality
    if (fps < 45) {
      this.currentQualityLevel = "medium";
      return {
        particleCount: Math.floor(baseConfig.particleCount * 0.7),
        effectRadius: Math.floor(baseConfig.effectRadius * 0.8),
        updateFrequency: Math.ceil(baseConfig.updateFrequency * 1.5),
        enableAdvancedEffects: false,
        enableShadows: false,
        textureQuality: "medium",
      };
    }

    // Otherwise use base config (high quality)
    this.currentQualityLevel = "high";
    return baseConfig;
  }

  getQualityLevel(): "low" | "medium" | "high" {
    return this.currentQualityLevel;
  }

  isTabVisible(): boolean {
    return this.isVisible;
  }

  reset(): void {
    this.frameTimeHistory = [];
    this.lastFrameTime = 0;
    this.qualityAdjustmentCooldown = 0;
  }

  destroy(): void {
    if (this.visibilityChangeHandler && typeof document !== "undefined") {
      document.removeEventListener(
        "visibilitychange",
        this.visibilityChangeHandler
      );
    }
  }
}

