"use client";

import { useState } from "react";

import type React from "react";

const ERROR_IMG_SRC =
  "data:image/svg+xml;base64,";

export function ImageWithFallback(
  props: React.ImgHTMLAttributes<HTMLImageElement>
) {
  const [didError, setDidError] = useState(false);

  const handleError = () => {
    setDidError(true);
  };

  const { src, alt, style, className, ...rest } = props;

  if (didError) {
    return (
      <div
        className={`inline-block bg-muted text-center align-middle ${className ?? ""}`}
        style={style}
      >
        <div className="flex items-center justify-center w-full h-full">
          <img
            src={ERROR_IMG_SRC || "/placeholder.svg"}
            alt="Error loading image"
            {...rest}
            data-original-url={src}
          />
        </div>
      </div>
    );
  }

  return (
    <img
      src={src ?? "/placeholder.svg"}
      alt={alt}
      className={className}
      style={style}
      {...rest}
      onError={handleError}
    />
  );
}

"use client";

import { Upload, File, X, CheckCircle, AlertCircle } from "lucide-react";
import { useState, useCallback } from "react";

import { Button } from "@/components/ui/button";
import { Card, CardContent } from "@/components/ui/card";
import { Progress } from "@/components/ui/progress";

interface FileUploadProps {
  onFileContent: (content: string, filename: string) => void;
  accept?: string;
  maxSize?: number; // in MB
  className?: string;
}

interface UploadedFile {
  name: string;
  size: number;
  type: string;
  content: string;
  status: "uploading" | "success" | "error";
  progress: number;
}

export default function FileUpload({
  onFileContent,
  accept = ".pdf,.docx,.txt",
  maxSize = 10,
  className = "",
}: FileUploadProps) {
  const [files, setFiles] = useState<UploadedFile[]>([]);
  const [isDragging, setIsDragging] = useState(false);

  const extractTextFromFile = async (file: File): Promise<string> => {
    return new Promise((resolve, reject) => {
      const reader = new FileReader();

      reader.onload = async (e) => {
        try {
          const arrayBuffer = e.target?.result as ArrayBuffer;

          if (!arrayBuffer) {
            reject(new Error("فشل في قراءة الملف"));
            return;
          }

          if (file.type === "text/plain") {
            // Handle TXT files
            const text = new TextDecoder().decode(arrayBuffer);
            resolve(text);
          } else if (file.type === "application/pdf") {
            // Handle PDF files using PDF.js with proper worker setup
            const pdfjsLib = await import("pdfjs-dist");

            // Use CDN worker that works in production
            pdfjsLib.GlobalWorkerOptions.workerSrc = `https://unpkg.com/pdfjs-dist@4.4.168/build/pdf.worker.min.mjs`;

            const pdf = await pdfjsLib.getDocument({ data: arrayBuffer })
              .promise;
            let fullText = "";

            for (let i = 1; i <= pdf.numPages; i++) {
              const page = await pdf.getPage(i);
              const textContent = await page.getTextContent();
              const pageText = textContent.items
                .map((item: any) => item.str)
                .join(" ");
              fullText += pageText + "\n";
            }

            resolve(fullText);
          } else if (
            file.type ===
            "application/vnd.openxmlformats-officedocument.wordprocessingml.document"
          ) {
            // Handle DOCX files using mammoth
            const mammoth = await import("mammoth");
            const result = await mammoth.extractRawText({ arrayBuffer });
            resolve(result.value);
          } else {
            reject(new Error("نوع الملف غير مدعوم"));
          }
        } catch (error) {
          reject(error);
        }
      };

      reader.onerror = () => reject(new Error("فشل في قراءة الملف"));
      reader.readAsArrayBuffer(file);
    });
  };

  const processFile = useCallback(
    async (file: File) => {
      // Add file to state with uploading status
      const newFile: UploadedFile = {
        name: file.name,
        size: file.size,
        type: file.type,
        content: "",
        status: "uploading",
        progress: 0,
      };

      setFiles((prev) => [...prev, newFile]);

      try {
        // Simulate progress
        const progressInterval = setInterval(() => {
          setFiles((prev) =>
            prev.map((f) =>
              f.name === file.name
                ? { ...f, progress: Math.min(f.progress + 10, 90) }
                : f
            )
          );
        }, 100);

        // Extract text content
        const content = await extractTextFromFile(file);

        clearInterval(progressInterval);

        // Update file status
        setFiles((prev) =>
          prev.map((f) =>
            f.name === file.name
              ? { ...f, content, status: "success", progress: 100 }
              : f
          )
        );

        // Call callback with content
        onFileContent(content, file.name);
      } catch (error) {
        setFiles((prev) =>
          prev.map((f) =>
            f.name === file.name ? { ...f, status: "error", progress: 0 } : f
          )
        );
        console.error("خطأ في معالجة الملف:", error);
      }
    },
    [onFileContent]
  );

  const handleFileSelect = useCallback(
    (selectedFiles: FileList | null) => {
      if (!selectedFiles) return;

      Array.from(selectedFiles).forEach((file) => {
        // Check file size
        if (file.size > maxSize * 1024 * 1024) {
          alert(`الملف ${file.name} كبير جداً. الحد الأقصى ${maxSize}MB`);
          return;
        }

        // Check file type
        const allowedTypes = [
          "text/plain",
          "application/pdf",
          "application/vnd.openxmlformats-officedocument.wordprocessingml.document",
        ];

        if (!allowedTypes.includes(file.type)) {
          alert(
            `نوع الملف ${file.name} غير مدعوم. الأنواع المدعومة: PDF, DOCX, TXT`
          );
          return;
        }

        processFile(file);
      });
    },
    [maxSize, processFile]
  );

  const handleDrop = useCallback(
    (e: React.DragEvent) => {
      e.preventDefault();
      setIsDragging(false);
      handleFileSelect(e.dataTransfer.files);
    },
    [handleFileSelect]
  );

  const handleDragOver = useCallback((e: React.DragEvent) => {
    e.preventDefault();
    setIsDragging(true);
  }, []);

  const handleDragLeave = useCallback((e: React.DragEvent) => {
    e.preventDefault();
    setIsDragging(false);
  }, []);

  const removeFile = (fileName: string) => {
    setFiles((prev) => prev.filter((f) => f.name !== fileName));
  };

  const formatFileSize = (bytes: number) => {
    if (bytes === 0) return "0 Bytes";
    const k = 1024;
    const sizes = ["Bytes", "KB", "MB", "GB"];
    const i = Math.floor(Math.log(bytes) / Math.log(k));
    return parseFloat((bytes / Math.pow(k, i)).toFixed(2)) + " " + sizes[i];
  };

  return (
    <div className={`space-y-4 ${className}`}>
      {/* Upload Area */}
      <Card
        className={`border-2 border-dashed transition-colors ${
          isDragging
            ? "border-blue-500 bg-blue-50"
            : "border-gray-300 hover:border-gray-400"
        }`}
        onDrop={handleDrop}
        onDragOver={handleDragOver}
        onDragLeave={handleDragLeave}
      >
        <CardContent className="p-8 text-center">
          <Upload className="w-12 h-12 mx-auto mb-4 text-gray-400" />
          <h3 className="text-lg font-semibold mb-2">تحميل الملفات</h3>
          <p className="text-gray-600 mb-4">
            اسحب الملفات هنا أو انقر للاختيار
          </p>
          <p className="text-sm text-gray-500 mb-4">
            الأنواع المدعومة: PDF, DOCX, TXT (حتى {maxSize}MB)
          </p>

          <input
            type="file"
            multiple
            accept={accept}
            onChange={(e) => handleFileSelect(e.target.files)}
            className="hidden"
            id="file-upload"
          />

          <Button asChild>
            <label htmlFor="file-upload" className="cursor-pointer">
              <Upload className="w-4 h-4 mr-2" />
              اختيار الملفات
            </label>
          </Button>
        </CardContent>
      </Card>

      {/* Uploaded Files List */}
      {files.length > 0 && (
        <div className="space-y-2">
          <h4 className="font-medium">الملفات المحملة:</h4>
          {files.map((file, index) => (
            <Card key={index} className="p-4">
              <div className="flex items-center justify-between">
                <div className="flex items-center space-x-3 space-x-reverse">
                  <File className="w-5 h-5 text-blue-500" />
                  <div>
                    <p className="font-medium text-sm">{file.name}</p>
                    <p className="text-xs text-gray-500">
                      {formatFileSize(file.size)}
                    </p>
                  </div>
                </div>

                <div className="flex items-center space-x-2 space-x-reverse">
                  {file.status === "uploading" && (
                    <div className="flex items-center space-x-2 space-x-reverse">
                      <Progress value={file.progress} className="w-20" />
                      <span className="text-xs text-gray-500">
                        {file.progress}%
                      </span>
                    </div>
                  )}

                  {file.status === "success" && (
                    <CheckCircle className="w-5 h-5 text-green-500" />
                  )}

                  {file.status === "error" && (
                    <AlertCircle className="w-5 h-5 text-red-500" />
                  )}

                  <Button
                    variant="ghost"
                    size="sm"
                    onClick={() => removeFile(file.name)}
                  >
                    <X className="w-4 h-4" />
                  </Button>
                </div>
              </div>

              {file.status === "uploading" && (
                <Progress value={file.progress} className="mt-2" />
              )}
            </Card>
          ))}
        </div>
      )}
    </div>
  );
}

"use client";

import { useEffect, useRef } from "react";
import * as THREE from "three";

import {
  getDeviceCapabilities,
  getParticleLODConfig,
  logDeviceCapabilities,
} from "@/components/device-detection";
import {
  applySparkEffect,
  applyWaveEffect,
  applyVortexEffect,
  applyDefaultEffect,
  calculateWaveColor,
  calculateVortexColor,
  performanceMonitor,
} from "@/components/particle-effects";
import {
  BASELINE,
  STROKE_WIDTH,
  X_HEIGHT,
  ASCENDER_HEIGHT,
  DESCENDER_DEPTH,
  ARABIC_HEIGHT,
  LETTER_POSITIONS,
  SAMPLING_BOUNDS,
  PARTICLE_THRESHOLDS,
} from "@/components/particle-letters.constants";

import type {
  ParticleVelocity,
  ParticlePosition,
  EffectConfig,
} from "@/components/particle-effects";

type Effect = "default" | "spark" | "wave" | "vortex";

/**
 * Get optimal particle configuration using device detection
 */
function getOptimalParticleCount(): {
  count: number;
  batchSize: number;
  config: any;
} {
  if (typeof window === "undefined" || typeof navigator === "undefined") {
    return { count: 3000, batchSize: 400, config: null };
  }

  // Check for reduced motion preference
  const prefersReducedMotion = window.matchMedia(
    "(prefers-reduced-motion: reduce)"
  ).matches;
  if (prefersReducedMotion) {
    return { count: 0, batchSize: 0, config: null };
  }

  // Use device detection system
  const capabilities = getDeviceCapabilities();
  const lodConfig = getParticleLODConfig(capabilities);

  // Calculate batch size based on particle count (20-25% of total)
  const batchSize = Math.floor(lodConfig.particleCount * 0.22);

  // Log device capabilities in development
  if (process.env.NODE_ENV === "development") {
    logDeviceCapabilities();
  }

  return {
    count: lodConfig.particleCount,
    batchSize: batchSize,
    config: lodConfig,
  };
}

/**
 * Enhanced requestIdleCallback with fallback
 */
const requestIdle = (
  callback: (deadline: any) => void,
  options?: any
): number => {
  if (typeof requestIdleCallback !== "undefined") {
    return requestIdleCallback(callback, options);
  } else {
    return setTimeout(
      () =>
        callback({
          timeRemaining: () => Math.max(0, 50),
          didTimeout: false,
        }),
      options?.timeout ?? 0
    ) as any;
  }
};

const clamp = (value: number, min: number, max: number) => {
  return Math.max(min, Math.min(max, value));
};

// Distance to box with rounded corners
const sdBox = (
  px: number,
  py: number,
  bx: number,
  by: number,
  r: number
): number => {
  const dx = Math.abs(px) - bx;
  const dy = Math.abs(py) - by;
  return (
    Math.sqrt(Math.max(dx, 0) ** 2 + Math.max(dy, 0) ** 2) +
    Math.min(Math.max(dx, dy), 0) -
    r
  );
};

// Distance to circle
const sdCircle = (
  px: number,
  py: number,
  cx: number,
  cy: number,
  r: number
): number => {
  return Math.hypot(px - cx, py - cy) - r;
};

// Distance to ring (hollow circle)
const sdRing = (
  px: number,
  py: number,
  cx: number,
  cy: number,
  r: number,
  thickness: number
): number => {
  return Math.abs(sdCircle(px, py, cx, cy, r)) - thickness;
};

// Distance to line segment (capsule)
const sdSegment = (
  px: number,
  py: number,
  ax: number,
  ay: number,
  bx: number,
  by: number,
  r: number
): number => {
  const pax = px - ax;
  const pay = py - ay;
  const bax = bx - ax;
  const bay = by - ay;
  const h = clamp((pax * bax + pay * bay) / (bax * bax + bay * bay), 0, 1);
  const dx = pax - bax * h;
  const dy = pay - bay * h;
  return Math.sqrt(dx * dx + dy * dy) - r;
};

// Distance to arc
const sdArc = (
  px: number,
  py: number,
  cx: number,
  cy: number,
  r: number,
  startAngle: number,
  endAngle: number,
  thickness: number
): number => {
  const dx = px - cx;
  const dy = py - cy;
  const angle = Math.atan2(dy, dx);

  let normAngle = angle;
  while (normAngle < startAngle) normAngle += Math.PI * 2;
  while (normAngle > endAngle + Math.PI * 2) normAngle -= Math.PI * 2;

  const clampedAngle = clamp(normAngle, startAngle, endAngle);
  const targetX = cx + Math.cos(clampedAngle) * r;
  const targetY = cy + Math.sin(clampedAngle) * r;

  return Math.hypot(px - targetX, py - targetY) - thickness;
};

// SDF boolean operations
const opUnion = (a: number, b: number): number => Math.min(a, b);
const opSubtract = (a: number, b: number): number => Math.max(a, -b);

// Letters SDF definitions (using shared constants)
const dist_t = (px: number, py: number): number => {
  const x = LETTER_POSITIONS.T;
  const stem = sdSegment(
    px,
    py,
    x,
    BASELINE + ASCENDER_HEIGHT - 0.05,
    x,
    BASELINE,
    STROKE_WIDTH
  );
  const crossbar = sdSegment(
    px,
    py,
    x - 0.15,
    BASELINE + ASCENDER_HEIGHT,
    x + 0.15,
    BASELINE + ASCENDER_HEIGHT,
    STROKE_WIDTH
  );
  return opUnion(stem, crossbar);
};

const dist_h = (px: number, py: number): number => {
  const x = LETTER_POSITIONS.H;
  const stem = sdSegment(
    px,
    py,
    x,
    BASELINE + ASCENDER_HEIGHT,
    x,
    BASELINE,
    STROKE_WIDTH
  );
  const shoulder = sdArc(
    px,
    py,
    x,
    BASELINE + X_HEIGHT * 0.8,
    0.22,
    -Math.PI / 2,
    0,
    STROKE_WIDTH
  );
  const rightLeg = sdSegment(
    px,
    py,
    x + 0.22,
    BASELINE + X_HEIGHT * 0.8,
    x + 0.22,
    BASELINE,
    STROKE_WIDTH
  );
  return opUnion(opUnion(stem, shoulder), rightLeg);
};

const dist_e = (px: number, py: number): number => {
  const cx = LETTER_POSITIONS.E;
  const cy = BASELINE + X_HEIGHT * 0.5;
  const r = 0.2;
  let ring = sdRing(px, py, cx, cy, r, STROKE_WIDTH);
  const cutBox = sdBox(px - (cx + r * 0.5), py - cy, 0.15, 0.14, 0);
  ring = opSubtract(ring, cutBox);
  const bar = sdSegment(px, py, cx - r, cy, cx + r * 0.7, cy, STROKE_WIDTH);
  return opUnion(ring, bar);
};

const dist_c = (px: number, py: number): number => {
  const cx = LETTER_POSITIONS.C;
  const cy = BASELINE + X_HEIGHT * 0.5;
  const r = 0.2;
  const ring = sdRing(px, py, cx, cy, r, STROKE_WIDTH);
  const cutBox = sdBox(px - (cx + r * 0.5), py - cy, 0.15, 0.14, 0);
  return opSubtract(ring, cutBox);
};

const dist_o = (px: number, py: number): number => {
  const cx = LETTER_POSITIONS.O;
  const cy = BASELINE + X_HEIGHT * 0.5;
  const r = 0.2;
  return sdRing(px, py, cx, cy, r, STROKE_WIDTH);
};

const dist_p = (px: number, py: number): number => {
  const x = LETTER_POSITIONS.P;
  const cy = BASELINE + X_HEIGHT * 0.5;
  const stem = sdSegment(
    px,
    py,
    x,
    BASELINE + X_HEIGHT,
    x,
    BASELINE + DESCENDER_DEPTH,
    STROKE_WIDTH
  );
  const bowl = sdRing(px, py, x + 0.2, cy, 0.17, STROKE_WIDTH);
  return opUnion(stem, bowl);
};

const dist_y = (px: number, py: number): number => {
  const x = LETTER_POSITIONS.Y;
  const top = BASELINE + X_HEIGHT;
  const mid = BASELINE + X_HEIGHT * 0.2;
  const leftArm = sdSegment(px, py, x - 0.15, top, x, mid, STROKE_WIDTH);
  const rightArm = sdSegment(px, py, x + 0.15, top, x, mid, STROKE_WIDTH);
  const descender = sdSegment(
    px,
    py,
    x,
    mid,
    x + 0.05,
    BASELINE + DESCENDER_DEPTH,
    STROKE_WIDTH
  );
  return opUnion(opUnion(leftArm, rightArm), descender);
};

const dist_dash = (px: number, py: number): number => {
  const x = LETTER_POSITIONS.DASH;
  return sdSegment(
    px,
    py,
    x - 0.1,
    BASELINE + X_HEIGHT * 0.5,
    x + 0.1,
    BASELINE + X_HEIGHT * 0.5,
    STROKE_WIDTH * 0.8
  );
};

const dist_alef = (px: number, py: number): number => {
  const x = LETTER_POSITIONS.ALEF;
  const stem = sdSegment(
    px,
    py,
    x,
    BASELINE + ARABIC_HEIGHT * 0.95,
    x,
    BASELINE,
    STROKE_WIDTH * 1.2
  );
  const base = sdSegment(
    px,
    py,
    x - 0.03,
    BASELINE,
    x + 0.03,
    BASELINE,
    STROKE_WIDTH * 1.5
  );
  return opUnion(stem, base);
};

const dist_lam = (px: number, py: number): number => {
  const x = LETTER_POSITIONS.LAM;
  const stem = sdSegment(
    px,
    py,
    x,
    BASELINE + ARABIC_HEIGHT * 0.95,
    x,
    BASELINE + 0.08,
    STROKE_WIDTH * 1.2
  );
  const hook = sdArc(
    px,
    py,
    x - 0.12,
    BASELINE + 0.08,
    0.12,
    0,
    Math.PI / 2,
    STROKE_WIDTH * 1.1
  );
  const hookEnd = sdSegment(
    px,
    py,
    x - 0.24,
    BASELINE,
    x - 0.15,
    BASELINE,
    STROKE_WIDTH
  );
  return opUnion(opUnion(stem, hook), hookEnd);
};

const dist_noon = (px: number, py: number): number => {
  const x = LETTER_POSITIONS.NOON;
  const cy = BASELINE + ARABIC_HEIGHT * 0.4;
  const mainArc = sdArc(
    px,
    py,
    x,
    cy,
    0.18,
    -Math.PI * 0.15,
    Math.PI * 0.85,
    STROKE_WIDTH * 1.1
  );
  const connector = sdSegment(
    px,
    py,
    x - 0.17,
    cy - 0.05,
    x - 0.08,
    BASELINE + 0.02,
    STROKE_WIDTH
  );
  const base = sdSegment(
    px,
    py,
    x - 0.08,
    BASELINE + 0.02,
    x + 0.1,
    BASELINE,
    STROKE_WIDTH
  );
  const dot = sdCircle(px, py, x, cy + 0.28, 0.035);
  return opUnion(opUnion(opUnion(mainArc, connector), base), dot);
};

const dist_seen = (px: number, py: number): number => {
  const x = LETTER_POSITIONS.SEEN;
  const baseY = BASELINE + 0.02;
  const toothHeight = ARABIC_HEIGHT * 0.35;
  const baseLine = sdSegment(
    px,
    py,
    x - 0.28,
    baseY,
    x + 0.28,
    baseY,
    STROKE_WIDTH * 1.1
  );
  const tooth1 = sdArc(
    px,
    py,
    x - 0.18,
    baseY + toothHeight * 0.6,
    0.1,
    Math.PI * 0.9,
    Math.PI * 0.1,
    STROKE_WIDTH
  );
  const tooth2 = sdArc(
    px,
    py,
    x,
    baseY + toothHeight * 0.8,
    0.12,
    Math.PI * 0.9,
    Math.PI * 0.1,
    STROKE_WIDTH
  );
  const tooth3 = sdArc(
    px,
    py,
    x + 0.18,
    baseY + toothHeight * 0.6,
    0.1,
    Math.PI * 0.9,
    Math.PI * 0.1,
    STROKE_WIDTH
  );
  const connect1 = sdSegment(
    px,
    py,
    x - 0.18,
    baseY,
    x - 0.18,
    baseY + toothHeight * 0.5,
    STROKE_WIDTH * 0.8
  );
  const connect2 = sdSegment(
    px,
    py,
    x,
    baseY,
    x,
    baseY + toothHeight * 0.7,
    STROKE_WIDTH * 0.8
  );
  const connect3 = sdSegment(
    px,
    py,
    x + 0.18,
    baseY,
    x + 0.18,
    baseY + toothHeight * 0.5,
    STROKE_WIDTH * 0.8
  );
  return opUnion(
    opUnion(
      opUnion(
        opUnion(opUnion(opUnion(baseLine, tooth1), tooth2), tooth3),
        connect1
      ),
      connect2
    ),
    connect3
  );
};

const dist_khaa = (px: number, py: number): number => {
  const x = LETTER_POSITIONS.KHAA;
  const cy = BASELINE + ARABIC_HEIGHT * 0.4;
  const mainArc = sdArc(
    px,
    py,
    x,
    cy,
    0.2,
    Math.PI * 0.6,
    Math.PI * 2.4,
    STROKE_WIDTH * 1.1
  );
  const rightConnect = sdSegment(
    px,
    py,
    x + 0.15,
    cy - 0.12,
    x + 0.12,
    BASELINE,
    STROKE_WIDTH
  );
  const leftConnect = sdSegment(
    px,
    py,
    x - 0.15,
    cy - 0.12,
    x - 0.08,
    BASELINE,
    STROKE_WIDTH
  );
  const dot = sdCircle(px, py, x, cy + 0.28, 0.035);
  return opUnion(opUnion(opUnion(mainArc, rightConnect), leftConnect), dot);
};

const dist_taa_marbouta = (px: number, py: number): number => {
  const x = LETTER_POSITIONS.TAA_MARBOUTA;
  const cy = BASELINE + ARABIC_HEIGHT * 0.4;
  let circle = sdRing(px, py, x, cy, 0.17, STROKE_WIDTH * 1.1);
  const opening = sdBox(px - x, py - (cy - 0.05), 0.08, 0.08, 0);
  circle = opSubtract(circle, opening);
  const dot1 = sdCircle(px, py, x - 0.07, cy + 0.28, 0.03);
  const dot2 = sdCircle(px, py, x + 0.07, cy + 0.28, 0.03);
  return opUnion(opUnion(circle, dot1), dot2);
};

// Combine all letters
const dist_all = (px: number, py: number): number => {
  return Math.min(
    dist_t(px, py),
    dist_h(px, py),
    dist_e(px, py),
    dist_c(px, py),
    dist_o(px, py),
    dist_p(px, py),
    dist_y(px, py),
    dist_dash(px, py),
    dist_alef(px, py),
    dist_lam(px, py),
    dist_noon(px, py),
    dist_seen(px, py),
    dist_khaa(px, py),
    dist_taa_marbouta(px, py)
  );
};

const dist = (px: number, py: number): number => dist_all(px, py);

/**
 * Generate particles in batches using requestIdleCallback
 */
const generateParticlesInBatches = async (): Promise<{
  positions: Float32Array;
  colors: Float32Array;
  count: number;
  originalPositions: Float32Array;
  phases: Float32Array;
  velocities: Float32Array;
  lodConfig: any;
}> => {
  try {
    // Get optimal particle count based on device capabilities
    const particleConfig = getOptimalParticleCount();

    // If no particles should be rendered (reduced motion preference)
    if (particleConfig.count === 0) {
      return {
        positions: new Float32Array(0),
        colors: new Float32Array(0),
        count: 0,
        originalPositions: new Float32Array(0),
        phases: new Float32Array(0),
        velocities: new Float32Array(0),
        lodConfig: null,
      };
    }

    const numParticles = particleConfig.count;
    const batchSize = particleConfig.batchSize;
    const thickness = 0.15;

    const positions = new Float32Array(numParticles * 3);
    const colors = new Float32Array(numParticles * 3);

    // Sampling bounds
    const { minX, maxX, minY, maxY } = SAMPLING_BOUNDS;

    let generatedCount = 0;
    const maxAttempts = 3000000;
    let attempts = 0;
    let batchAttempts = 0;
    const maxBatchAttempts = 50000;

    const processBatch = (): Promise<void> => {
      return new Promise((resolve) => {
        let batchGenerated = 0;

        while (
          batchGenerated < batchSize &&
          generatedCount < numParticles &&
          attempts < maxAttempts &&
          batchAttempts < maxBatchAttempts
        ) {
          attempts++;
          batchAttempts++;

          const x = Math.random() * (maxX - minX) + minX;
          const y = Math.random() * (maxY - minY) + minY;
          const z = Math.random() * thickness - thickness / 2;

          const d = dist(x, y);
          const threshold =
            x > 2.5 ? PARTICLE_THRESHOLDS.arabic : PARTICLE_THRESHOLDS.english;

          if (d <= threshold) {
            const idx = generatedCount * 3;
            positions[idx] = x;
            positions[idx + 1] = y;
            positions[idx + 2] = z;
            colors[idx] = 1;
            colors[idx + 1] = 1;
            colors[idx + 2] = 1;
            generatedCount++;
            batchGenerated++;
          }
        }

        if (
          generatedCount < numParticles &&
          attempts < maxAttempts &&
          batchAttempts < maxBatchAttempts
        ) {
          requestIdle(() => resolve(), { timeout: 100 });
        } else {
          resolve();
        }
      });
    };

    // Process all batches
    while (generatedCount < numParticles && attempts < maxAttempts) {
      await processBatch();
    }

    // If SDF sampling produced too few points, fall back to a simple starfield
    if (generatedCount < 200) {
      const fallbackCount = Math.min(numParticles, 3000);
      for (let j = 0; j < fallbackCount; j++) {
        const idx = j * 3;
        positions[idx] = (Math.random() - 0.5) * 6;
        positions[idx + 1] = (Math.random() - 0.5) * 3.5;
        positions[idx + 2] = (Math.random() - 0.5) * 0.3;
        colors[idx] = 1;
        colors[idx + 1] = 1;
        colors[idx + 2] = 1;
      }
      generatedCount = fallbackCount;
    }

    // Create final arrays
    const finalPositions = positions.slice(0, generatedCount * 3);
    const finalColors = colors.slice(0, generatedCount * 3);
    const originalPositions = positions.slice(0, generatedCount * 3);
    const phases = new Float32Array(generatedCount);
    const velocities = new Float32Array(generatedCount * 3);

    for (let j = 0; j < generatedCount; j++) {
      phases[j] = Math.random() * Math.PI * 2;
    }

    return {
      positions: finalPositions,
      colors: finalColors,
      count: generatedCount,
      originalPositions,
      phases,
      velocities,
      lodConfig: particleConfig.config,
    };
  } catch (error) {
    console.error("❌ خطأ في توليد الجسيمات:", error);
    throw error;
  }
};

export default function OptimizedParticleAnimation() {
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const animationRef = useRef<number | null>(null);
  const cleanupTimeoutRef = useRef<NodeJS.Timeout | null>(null);

  const currentEffect: Effect = "spark";
  const canRenderInBrowser = typeof window !== "undefined";
  const prefersReducedMotion =
    canRenderInBrowser &&
    window.matchMedia("(prefers-reduced-motion: reduce)").matches;

  // Scene reference with all necessary data
  const sceneRef = useRef<{
    scene: THREE.Scene;
    camera: THREE.PerspectiveCamera;
    renderer: THREE.WebGLRenderer;
    points: THREE.Points;
    geometry: THREE.BufferGeometry;
    originalPositions: Float32Array;
    velocities: Float32Array;
    phases: Float32Array;
    intersectionPoint: THREE.Vector3 | null;
    rotationX: number;
    rotationY: number;
    isDragging: boolean;
    previousMouseX: number;
    previousMouseY: number;
    particleCount: number;
    isGenerated: boolean;
    lastFrameTime?: number;
  } | null>(null);

  /**
   * Update camera position based on rotation
   */
  const updateCameraPosition = (
    camera: THREE.PerspectiveCamera,
    rotationX: number,
    rotationY: number
  ): void => {
    camera.position.x = Math.sin(rotationY) * 3.5;
    camera.position.z = Math.cos(rotationY) * 3.5;
    camera.position.y = rotationX * 0.5;
    camera.lookAt(0, 0, 0);
  };

  /**
   * Apply attraction to original position
   */
  const applyAttraction = (
    position: ParticlePosition,
    target: { x: number; y: number; z: number },
    velocity: ParticleVelocity,
    attractStrength: number
  ): ParticleVelocity => {
    return {
      vx: velocity.vx + (target.x - position.px) * attractStrength,
      vy: velocity.vy + (target.y - position.py) * attractStrength,
      vz: velocity.vz + (target.z - position.pz) * attractStrength,
    };
  };

  /**
   * Apply damping to velocity
   */
  const applyDamping = (
    velocity: ParticleVelocity,
    damping: number
  ): ParticleVelocity => {
    return {
      vx: velocity.vx * damping,
      vy: velocity.vy * damping,
      vz: velocity.vz * damping,
    };
  };

  /**
   * Update position based on velocity
   */
  const updatePosition = (
    position: ParticlePosition,
    velocity: ParticleVelocity
  ): ParticlePosition => {
    return {
      px: position.px + velocity.vx,
      py: position.py + velocity.vy,
      pz: position.pz + velocity.vz,
    };
  };

  /**
   * Calculate particle color based on effect
   */
  const calculateParticleColor = (
    effect: Effect,
    position: ParticlePosition,
    intersection: THREE.Vector3 | null,
    effectRadius: number,
    time: number
  ): { r: number; g: number; b: number } => {
    if (!intersection) {
      return { r: 1, g: 1, b: 1 };
    }

    const intersectionPoint = {
      x: intersection.x,
      y: intersection.y,
      z: intersection.z,
    };

    if (effect === "wave") {
      return calculateWaveColor(
        position,
        intersectionPoint,
        effectRadius,
        time
      );
    }
    if (effect === "vortex") {
      return calculateVortexColor(
        position,
        intersectionPoint,
        effectRadius,
        time
      );
    }

    return { r: 1, g: 1, b: 1 };
  };

  /**
   * Apply particle effect using lookup strategy
   */
  const applyParticleEffect = (
    effect: Effect,
    position: ParticlePosition,
    intersection: THREE.Vector3,
    velocity: ParticleVelocity,
    config: EffectConfig,
    time: number
  ): ParticleVelocity => {
    const intersectionPoint = {
      x: intersection.x,
      y: intersection.y,
      z: intersection.z,
    };

    switch (effect) {
      case "spark":
        return applySparkEffect(position, intersectionPoint, velocity, config);
      case "wave":
        return applyWaveEffect(
          position,
          intersectionPoint,
          velocity,
          config,
          time
        );
      case "vortex":
        return applyVortexEffect(position, intersectionPoint, velocity, config);
      case "default":
        return applyDefaultEffect(
          position,
          intersectionPoint,
          velocity,
          config
        );
    }
  };

  useEffect(() => {
    if (!canRenderInBrowser || prefersReducedMotion) return;
    if (!canvasRef.current) return;

    const canvas = canvasRef.current;

    // Initialize Three.js scene
    const scene = new THREE.Scene();
    const camera = new THREE.PerspectiveCamera(
      75,
      window.innerWidth / window.innerHeight,
      0.1,
      1000
    );
    const renderer = new THREE.WebGLRenderer({ canvas, antialias: true });

    renderer.setSize(window.innerWidth, window.innerHeight);
    renderer.setClearColor(0x000000);

    const raycaster = new THREE.Raycaster();
    const mouse = new THREE.Vector2();
    const plane = new THREE.Plane(new THREE.Vector3(0, 0, 1), 0);

    // Initialize geometry (will be updated after particle generation)
    const geometry = new THREE.BufferGeometry();
    const material = new THREE.PointsMaterial({
      size: 0.008,
      sizeAttenuation: true,
      vertexColors: true,
      transparent: true,
      opacity: 0.95,
    });

    const points = new THREE.Points(geometry, material);
    scene.add(points);
    camera.position.set(0, 0, 3.2);

    // Handle resize
    const handleResize = () => {
      const width = window.innerWidth;
      const height = window.innerHeight;
      renderer.setSize(width, height);
      camera.aspect = width / height;
      camera.updateProjectionMatrix();
    };
    window.addEventListener("resize", handleResize);

    // Initialize scene reference
    sceneRef.current = {
      scene,
      camera,
      renderer,
      points,
      geometry,
      originalPositions: new Float32Array(0),
      velocities: new Float32Array(0),
      phases: new Float32Array(0),
      intersectionPoint: null,
      rotationX: 0,
      rotationY: 0,
      isDragging: false,
      previousMouseX: 0,
      previousMouseY: 0,
      particleCount: 0,
      isGenerated: false,
    };

    // Generate particles asynchronously
    generateParticlesInBatches()
      .then((result) => {
        if (!sceneRef.current) return;

        const {
          positions,
          colors,
          count,
          originalPositions,
          phases,
          velocities,
        } = result;

        // Update geometry
        sceneRef.current.geometry.setAttribute(
          "position",
          new THREE.BufferAttribute(positions, 3)
        );
        sceneRef.current.geometry.setAttribute(
          "color",
          new THREE.BufferAttribute(colors, 3)
        );

        // Update scene reference
        sceneRef.current.originalPositions = originalPositions;
        sceneRef.current.phases = phases;
        sceneRef.current.velocities = velocities;
        sceneRef.current.particleCount = count;
        sceneRef.current.isGenerated = true;
      })
      .catch((error) => {
        console.error("❌ فشل في توليد الجسيمات:", error);
      });

    // Mouse interaction handlers
    const handleCanvasMouseMove = (event: MouseEvent) => {
      if (!sceneRef.current) return;

      const rect = canvas.getBoundingClientRect();
      mouse.x = ((event.clientX - rect.left) / canvas.width) * 2 - 1;
      mouse.y = -((event.clientY - rect.top) / canvas.height) * 2 + 1;

      raycaster.setFromCamera(mouse, camera);
      const intersection = new THREE.Vector3();
      raycaster.ray.intersectPlane(plane, intersection);
      sceneRef.current.intersectionPoint = intersection;
    };

    const handleMouseLeave = () => {
      if (sceneRef.current) {
        sceneRef.current.intersectionPoint = null;
      }
    };

    canvas.addEventListener("mousemove", handleCanvasMouseMove);
    canvas.addEventListener("mouseleave", handleMouseLeave);

    // Animation loop with batch processing
    const animate = () => {
      if (!sceneRef.current?.isGenerated) {
        animationRef.current = requestAnimationFrame(animate);
        return;
      }

      const currentTime = performance.now();
      const time = currentTime * 0.001;

      // Record frame for performance monitoring
      performanceMonitor.recordFrame(currentTime);

      const {
        scene,
        camera,
        renderer,
        geometry,
        originalPositions,
        velocities,
        intersectionPoint,
        rotationX,
        rotationY,
        particleCount,
      } = sceneRef.current;

      const positionAttribute = geometry.getAttribute(
        "position"
      ) as THREE.BufferAttribute;
      const colorAttribute = geometry.getAttribute(
        "color"
      ) as THREE.BufferAttribute;

      const config: EffectConfig = {
        effectRadius: 0.5,
        repelStrength: 0.08,
      };
      const attractStrength = 0.15;
      const damping = 0.92;

      // Apply rotation
      updateCameraPosition(camera, rotationX, rotationY);

      // Process particles in batches for better performance
      const processParticlesInBatches = (batchSize = 800) => {
        let currentIndex = 0;

        const processBatch = () => {
          const endIndex = Math.min(
            currentIndex + Math.min(batchSize, 200),
            particleCount
          );

          for (let j = currentIndex; j < endIndex; j++) {
            const idx = j * 3;
            const position: ParticlePosition = {
              px: positionAttribute.getX(j),
              py: positionAttribute.getY(j),
              pz: positionAttribute.getZ(j),
            };

            const target = {
              x: originalPositions[idx] ?? 0,
              y: originalPositions[idx + 1] ?? 0,
              z: originalPositions[idx + 2] ?? 0,
            };

            let velocity: ParticleVelocity = {
              vx: velocities[idx] ?? 0,
              vy: velocities[idx + 1] ?? 0,
              vz: velocities[idx + 2] ?? 0,
            };

            // Apply effect based on mouse interaction
            if (intersectionPoint) {
              try {
                velocity = applyParticleEffect(
                  currentEffect,
                  position,
                  intersectionPoint,
                  velocity,
                  config,
                  time
                );
              } catch (error) {
                console.warn("خطأ في تأثير الجسيم:", error);
              }
            }

            // Attract back to original position
            velocity = applyAttraction(
              position,
              target,
              velocity,
              attractStrength
            );
            velocity = applyDamping(velocity, damping);

            // Update position
            const newPos = updatePosition(position, velocity);
            positionAttribute.setXYZ(j, newPos.px, newPos.py, newPos.pz);

            velocities[idx] = velocity.vx;
            velocities[idx + 1] = velocity.vy;
            velocities[idx + 2] = velocity.vz;

            // Calculate and apply color
            try {
              const color = calculateParticleColor(
                currentEffect,
                newPos,
                intersectionPoint,
                config.effectRadius,
                time
              );
              colorAttribute.setXYZ(j, color.r, color.g, color.b);
            } catch (error) {
              console.warn("خطأ في حساب لون الجسيم:", error);
            }
          }

          currentIndex = endIndex;

          if (currentIndex < particleCount) {
            requestAnimationFrame(processBatch);
          } else {
            // Update data and render
            positionAttribute.needsUpdate = true;
            colorAttribute.needsUpdate = true;

            renderer.render(scene, camera);

            // Schedule next frame
            animationRef.current = requestAnimationFrame(animate);
          }
        };

        processBatch();
      };

      // Throttle animation to prevent performance issues
      if (currentTime - (sceneRef.current.lastFrameTime ?? 0) > 16) {
        sceneRef.current.lastFrameTime = currentTime;
        processParticlesInBatches();
      } else {
        animationRef.current = requestAnimationFrame(animate);
      }
    };

    // Start animation loop
    animationRef.current = requestAnimationFrame(animate);

    // Mouse drag handlers (using native event types for addEventListener)
    const handleMouseDown = (event: MouseEvent) => {
      if (!sceneRef.current) return;
      sceneRef.current.isDragging = true;
      sceneRef.current.previousMouseX = event.clientX;
      sceneRef.current.previousMouseY = event.clientY;
    };

    const handleMouseMove = (event: MouseEvent) => {
      if (!sceneRef.current?.isDragging) return;

      const deltaX = event.clientX - sceneRef.current.previousMouseX;
      const deltaY = event.clientY - sceneRef.current.previousMouseY;

      sceneRef.current.rotationY -= deltaX * 0.005;
      sceneRef.current.rotationX -= deltaY * 0.005;

      sceneRef.current.previousMouseX = event.clientX;
      sceneRef.current.previousMouseY = event.clientY;
    };

    const handleMouseUp = () => {
      if (sceneRef.current) {
        sceneRef.current.isDragging = false;
      }
    };

    // Touch handlers (using native event types for addEventListener)
    const handleTouchStart = (event: TouchEvent) => {
      if (!sceneRef.current || !event.touches[0]) return;
      sceneRef.current.isDragging = true;
      sceneRef.current.previousMouseX = event.touches[0].clientX;
      sceneRef.current.previousMouseY = event.touches[0].clientY;
    };

    const handleTouchMove = (event: TouchEvent) => {
      if (
        !sceneRef.current ||
        !sceneRef.current.isDragging ||
        !event.touches[0]
      )
        return;

      const deltaX = event.touches[0].clientX - sceneRef.current.previousMouseX;
      const deltaY = event.touches[0].clientY - sceneRef.current.previousMouseY;

      sceneRef.current.rotationY -= deltaX * 0.005;
      sceneRef.current.rotationX -= deltaY * 0.005;

      sceneRef.current.previousMouseX = event.touches[0].clientX;
      sceneRef.current.previousMouseY = event.touches[0].clientY;
    };

    const handleTouchEnd = () => {
      if (sceneRef.current) {
        sceneRef.current.isDragging = false;
      }
    };

    // Cleanup function with error handling
    const cleanup = () => {
      try {
        if (animationRef.current) {
          cancelAnimationFrame(animationRef.current);
        }
        if (cleanupTimeoutRef.current) {
          clearTimeout(cleanupTimeoutRef.current);
        }

        canvas.removeEventListener("mousemove", handleCanvasMouseMove);
        canvas.removeEventListener("mouseleave", handleMouseLeave);

        if (geometry) geometry.dispose();
        if (material) material.dispose();
        if (renderer) renderer.dispose();

        window.removeEventListener("resize", handleResize);

        // Reset performance monitor
        performanceMonitor.reset();

        if (sceneRef.current) {
          sceneRef.current.originalPositions = null as any;
          sceneRef.current.velocities = null as any;
          sceneRef.current.phases = null as any;
          sceneRef.current = null;
        }

        // تم تنظيف موارد الجسيمات بنجاح
      } catch (error) {
        console.error("خطأ في تنظيف موارد الجسيمات:", error);
      }
    };

    // Automatic cleanup after 5 minutes for safety
    cleanupTimeoutRef.current = setTimeout(cleanup, 300000);

    // Attach event listeners
    canvas.addEventListener("mousedown", handleMouseDown);
    canvas.addEventListener("mousemove", handleMouseMove);
    canvas.addEventListener("mouseup", handleMouseUp);
    canvas.addEventListener("mouseleave", handleMouseUp);
    canvas.addEventListener("touchstart", handleTouchStart, { passive: true });
    canvas.addEventListener("touchmove", handleTouchMove, { passive: true });
    canvas.addEventListener("touchend", handleTouchEnd);

    return cleanup;
  }, [canRenderInBrowser, prefersReducedMotion]);

  if (!canRenderInBrowser || prefersReducedMotion) {
    return null;
  }

  return (
    <div className="absolute inset-0 z-0 flex items-center justify-center w-full h-full bg-black">
      <canvas
        ref={canvasRef}
        width={1400}
        height={600}
        className="block"
        style={{ touchAction: "none" }}
      />
    </div>
  );
}

"use client";

import { useEffect, useRef, useState } from "react";
import * as THREE from "three";

import { ParticleWorkerManager } from "@/workers/worker-manager";

import {
  getDeviceCapabilities,
  getParticleLODConfig,
  logDeviceCapabilities,
  type ParticleLODConfig,
} from "./device-detection";

import type { Effect } from "@/workers/types";

/**
 * Get optimal particle configuration using comprehensive LOD system
 */
function getOptimalParticleConfig(): {
  count: number;
  batchSize: number;
  config: ParticleLODConfig;
} {
  if (typeof window === "undefined") {
    return {
      count: 3000,
      batchSize: 400,
      config: {
        particleCount: 3000,
        effectRadius: 150,
        updateFrequency: 33,
        enableAdvancedEffects: false,
        enableShadows: false,
        textureQuality: "medium",
      },
    };
  }

  // Use comprehensive device detection system
  const capabilities = getDeviceCapabilities();
  const lodConfig = getParticleLODConfig(capabilities);

  // Calculate batch size based on particle count (20-25% of total)
  const batchSize = Math.floor(lodConfig.particleCount * 0.22);

  // Log device capabilities in development
  if (process.env.NODE_ENV === "development") {
    logDeviceCapabilities();
  }

  return {
    count: lodConfig.particleCount,
    batchSize: batchSize,
    config: lodConfig,
  };
}

export default function WorkerParticleAnimation() {
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const animationRef = useRef<number | null>(null);
  const workerManagerRef = useRef<ParticleWorkerManager | null>(null);
  const [generationProgress, setGenerationProgress] = useState<number>(0);
  const [isGenerating, setIsGenerating] = useState<boolean>(true);

  const currentEffect: Effect = "spark";

  // Check for reduced motion preference
  const prefersReducedMotion = false;

  // Scene reference with all necessary data
  const sceneRef = useRef<{
    scene: THREE.Scene;
    camera: THREE.PerspectiveCamera;
    renderer: THREE.WebGLRenderer;
    points: THREE.Points;
    geometry: THREE.BufferGeometry;
    originalPositions: Float32Array;
    velocities: Float32Array;
    phases: Float32Array;
    intersectionPoint: THREE.Vector3 | null;
    rotationX: number;
    rotationY: number;
    isDragging: boolean;
    previousMouseX: number;
    previousMouseY: number;
    particleCount: number;
    isGenerated: boolean;
  } | null>(null);

  /**
   * Update camera position based on rotation
   */
  const updateCameraPosition = (
    camera: THREE.PerspectiveCamera,
    rotationX: number,
    rotationY: number
  ): void => {
    camera.position.x = Math.sin(rotationY) * 3.5;
    camera.position.z = Math.cos(rotationY) * 3.5;
    camera.position.y = rotationX * 0.5;
    camera.lookAt(0, 0, 0);
  };

  useEffect(() => {
    if (!canvasRef.current || typeof window === "undefined") return;

    // Skip animation if user prefers reduced motion
    if (prefersReducedMotion) return;

    const canvas = canvasRef.current;

    // Initialize Three.js scene
    const scene = new THREE.Scene();
    const camera = new THREE.PerspectiveCamera(
      75,
      window.innerWidth / window.innerHeight,
      0.1,
      1000
    );
    const renderer = new THREE.WebGLRenderer({ canvas, antialias: true });

    renderer.setSize(window.innerWidth, window.innerHeight);
    renderer.setClearColor(0x000000);

    const raycaster = new THREE.Raycaster();
    const mouse = new THREE.Vector2();
    const plane = new THREE.Plane(new THREE.Vector3(0, 0, 1), 0);

    // Initialize geometry
    const geometry = new THREE.BufferGeometry();
    const material = new THREE.PointsMaterial({
      size: 0.008,
      sizeAttenuation: true,
      vertexColors: true,
      transparent: true,
      opacity: 0.95,
    });

    const points = new THREE.Points(geometry, material);
    scene.add(points);
    camera.position.set(0, 0, 3.2);

    // Handle resize
    const handleResize = () => {
      const width = window.innerWidth;
      const height = window.innerHeight;
      renderer.setSize(width, height);
      camera.aspect = width / height;
      camera.updateProjectionMatrix();
    };
    window.addEventListener("resize", handleResize);

    // Initialize scene reference
    sceneRef.current = {
      scene,
      camera,
      renderer,
      points,
      geometry,
      originalPositions: new Float32Array(0),
      velocities: new Float32Array(0),
      phases: new Float32Array(0),
      intersectionPoint: null,
      rotationX: 0,
      rotationY: 0,
      isDragging: false,
      previousMouseX: 0,
      previousMouseY: 0,
      particleCount: 0,
      isGenerated: false,
    };

    // Initialize worker manager
    const workerManager = new ParticleWorkerManager();
    workerManagerRef.current = workerManager;

    // Initialize workers and generate particles
    const initializeAndGenerate = async () => {
      try {
        await workerManager.initializeWorkers();

        // Determine device capabilities and particle count using LOD system
        const particleConfig = getOptimalParticleConfig();
        const numParticles = particleConfig.count;
        const thickness = 0.15;

        // Sampling bounds
        const minX = -2.1;
        const maxX = 5.6;
        const minY = -0.4;
        const maxY = 0.85;

        // Generate particles using worker with LOD-optimized batch size
        const result = await workerManager.generateParticles(
          {
            numParticles,
            thickness,
            minX,
            maxX,
            minY,
            maxY,
            maxAttempts: 3000000,
            batchSize: particleConfig.batchSize,
          },
          (progress) => {
            setGenerationProgress(progress);
          }
        );

        if (!sceneRef.current) return;

        const {
          positions,
          colors,
          count,
          originalPositions,
          phases,
          velocities,
        } = result;

        // Update geometry
        sceneRef.current.geometry.setAttribute(
          "position",
          new THREE.BufferAttribute(positions, 3)
        );
        sceneRef.current.geometry.setAttribute(
          "color",
          new THREE.BufferAttribute(colors, 3)
        );

        // Update scene reference
        sceneRef.current.originalPositions = originalPositions;
        sceneRef.current.phases = phases;
        sceneRef.current.velocities = velocities;
        sceneRef.current.particleCount = count;
        sceneRef.current.isGenerated = true;

        setIsGenerating(false);
        setGenerationProgress(100);
      } catch (error) {
        console.error("Failed to generate particles:", error);
        setIsGenerating(false);
      }
    };

    // Use requestIdleCallback for initialization to avoid blocking main thread
    if ("requestIdleCallback" in window) {
      requestIdleCallback(() => initializeAndGenerate(), { timeout: 2000 });
    } else {
      setTimeout(initializeAndGenerate, 100);
    }

    // Pause animation when tab is hidden (save battery and CPU)
    const handleVisibilityChange = () => {
      if (document.hidden && animationRef.current) {
        cancelAnimationFrame(animationRef.current);
        animationRef.current = null;
      } else if (
        !document.hidden &&
        sceneRef.current &&
        !animationRef.current
      ) {
        animationRef.current = requestAnimationFrame(animate);
      }
    };

    document.addEventListener("visibilitychange", handleVisibilityChange);

    // Mouse interaction handlers
    const handleCanvasMouseMove = (event: MouseEvent) => {
      if (!sceneRef.current) return;

      const rect = canvas.getBoundingClientRect();
      mouse.x = ((event.clientX - rect.left) / canvas.width) * 2 - 1;
      mouse.y = -((event.clientY - rect.top) / canvas.height) * 2 + 1;

      raycaster.setFromCamera(mouse, camera);
      const intersection = new THREE.Vector3();
      raycaster.ray.intersectPlane(plane, intersection);
      sceneRef.current.intersectionPoint = intersection;
    };

    const handleMouseLeave = () => {
      if (sceneRef.current) {
        sceneRef.current.intersectionPoint = null;
      }
    };

    canvas.addEventListener("mousemove", handleCanvasMouseMove);
    canvas.addEventListener("mouseleave", handleMouseLeave);

    // Animation loop - now uses worker for physics calculations
    const animate = async () => {
      if (!sceneRef.current?.isGenerated) {
        animationRef.current = requestAnimationFrame(animate);
        return;
      }

      const time = Date.now() * 0.001;
      const {
        camera,
        renderer,
        geometry,
        originalPositions,
        velocities,
        intersectionPoint,
        rotationX,
        rotationY,
        particleCount,
      } = sceneRef.current;

      const positionAttribute = geometry.getAttribute(
        "position"
      ) as THREE.BufferAttribute;
      const colorAttribute = geometry.getAttribute(
        "color"
      ) as THREE.BufferAttribute;

      // Apply rotation
      updateCameraPosition(camera, rotationX, rotationY);

      // Clone arrays for worker (using transferable objects)
      const positions = new Float32Array(positionAttribute.array);
      const colors = new Float32Array(colorAttribute.array);
      const vels = new Float32Array(velocities);

      try {
        // Update particles using worker
        if (
          workerManagerRef.current &&
          workerManagerRef.current.isInitialized()
        ) {
          const result = await workerManagerRef.current.updateParticles({
            type: "update",
            positions,
            velocities: vels,
            originalPositions,
            colors,
            particleCount,
            config: {
              effect: currentEffect,
              effectRadius: 0.5,
              repelStrength: 0.08,
              attractStrength: 0.15,
              damping: 0.92,
              intersectionPoint: intersectionPoint
                ? {
                    x: intersectionPoint.x,
                    y: intersectionPoint.y,
                    z: intersectionPoint.z,
                  }
                : null,
              time,
            },
          });

          // Update geometry with new data
          positionAttribute.set(result.positions);
          colorAttribute.set(result.colors);
          sceneRef.current.velocities = result.velocities;

          positionAttribute.needsUpdate = true;
          colorAttribute.needsUpdate = true;
        }
      } catch (error) {
        console.warn("Worker update failed, skipping frame:", error);
      }

      renderer.render(scene, camera);
      animationRef.current = requestAnimationFrame(animate);
    };

    // Start animation loop
    animationRef.current = requestAnimationFrame(animate);

    // Mouse drag handlers
    const handleMouseDown = (e: MouseEvent) => {
      if (!sceneRef.current) return;
      sceneRef.current.isDragging = true;
      sceneRef.current.previousMouseX = e.clientX;
      sceneRef.current.previousMouseY = e.clientY;
    };

    const handleMouseMoveRotate = (e: MouseEvent) => {
      if (!sceneRef.current?.isDragging) return;

      const deltaX = e.clientX - sceneRef.current.previousMouseX;
      const deltaY = e.clientY - sceneRef.current.previousMouseY;

      sceneRef.current.rotationY -= deltaX * 0.005;
      sceneRef.current.rotationX -= deltaY * 0.005;

      sceneRef.current.previousMouseX = e.clientX;
      sceneRef.current.previousMouseY = e.clientY;
    };

    const handleMouseUp = () => {
      if (sceneRef.current) {
        sceneRef.current.isDragging = false;
      }
    };

    // Touch handlers
    const handleTouchStart = (e: TouchEvent) => {
      if (!sceneRef.current || !e.touches[0]) return;
      sceneRef.current.isDragging = true;
      sceneRef.current.previousMouseX = e.touches[0].clientX;
      sceneRef.current.previousMouseY = e.touches[0].clientY;
    };

    const handleTouchMove = (e: TouchEvent) => {
      if (!sceneRef.current || !sceneRef.current.isDragging || !e.touches[0])
        return;

      const deltaX = e.touches[0].clientX - sceneRef.current.previousMouseX;
      const deltaY = e.touches[0].clientY - sceneRef.current.previousMouseY;

      sceneRef.current.rotationY -= deltaX * 0.005;
      sceneRef.current.rotationX -= deltaY * 0.005;

      sceneRef.current.previousMouseX = e.touches[0].clientX;
      sceneRef.current.previousMouseY = e.touches[0].clientY;
    };

    const handleTouchEnd = () => {
      if (sceneRef.current) {
        sceneRef.current.isDragging = false;
      }
    };

    canvas.addEventListener("mousedown", handleMouseDown);
    canvas.addEventListener("mousemove", handleMouseMoveRotate);
    canvas.addEventListener("mouseup", handleMouseUp);
    canvas.addEventListener("mouseleave", handleMouseUp);
    canvas.addEventListener("touchstart", handleTouchStart, { passive: true });
    canvas.addEventListener("touchmove", handleTouchMove, { passive: true });
    canvas.addEventListener("touchend", handleTouchEnd);

    // Cleanup function
    const cleanup = () => {
      try {
        if (animationRef.current) {
          cancelAnimationFrame(animationRef.current);
        }

        canvas.removeEventListener("mousemove", handleCanvasMouseMove);
        canvas.removeEventListener("mouseleave", handleMouseLeave);
        canvas.removeEventListener("mousedown", handleMouseDown);
        canvas.removeEventListener("mousemove", handleMouseMoveRotate);
        canvas.removeEventListener("mouseup", handleMouseUp);
        canvas.removeEventListener("touchstart", handleTouchStart);
        canvas.removeEventListener("touchmove", handleTouchMove);
        canvas.removeEventListener("touchend", handleTouchEnd);

        document.removeEventListener(
          "visibilitychange",
          handleVisibilityChange
        );

        if (geometry) geometry.dispose();
        if (material) material.dispose();
        if (renderer) renderer.dispose();

        window.removeEventListener("resize", handleResize);

        // Terminate workers
        if (workerManagerRef.current) {
          workerManagerRef.current.terminate();
          workerManagerRef.current = null;
        }

        if (sceneRef.current) {
          sceneRef.current = null;
        }
      } catch (error) {
        console.error("Cleanup error:", error);
      }
    };

    return cleanup;
  }, [prefersReducedMotion]);

  return (
    <div className="absolute inset-0 z-0 flex items-center justify-center w-full h-full bg-black">
      <canvas
        ref={canvasRef}
        width={1400}
        height={600}
        className="block"
        style={{ touchAction: "none", pointerEvents: "auto" }}
      />

      {/* Progress indicator during generation */}
      {isGenerating && (
        <div className="absolute bottom-10 left-1/2 transform -translate-x-1/2 bg-black/50 text-white px-4 py-2 rounded-lg">
          <div className="text-sm">
            توليد الجسيمات: {Math.round(generationProgress)}%
          </div>
          <div className="w-48 h-2 bg-gray-700 rounded-full mt-2">
            <div
              className="h-full bg-blue-500 rounded-full transition-all duration-300"
              style={{ width: `${generationProgress}%` }}
            />
          </div>
        </div>
      )}
    </div>
  );
}

"use client";


import { useEffect, useRef } from "react";
import * as THREE from "three";

import {
  BASELINE,
  STROKE_WIDTH,
  X_HEIGHT,
  ASCENDER_HEIGHT,
  DESCENDER_DEPTH,
  ARABIC_HEIGHT,
  LETTER_POSITIONS,
  SAMPLING_BOUNDS,
  PARTICLE_THRESHOLDS,
} from "@/lib/particle-letters.constants";

import {
  getDeviceCapabilities,
  getParticleLODConfig,
  PerformanceMonitor,
  logDeviceCapabilities,
} from "./device-detection";

import type React from "react";

// Create a single performance monitor instance for the module
const performanceMonitor = new PerformanceMonitor();

type Effect = "default" | "spark" | "wave" | "vortex";

function updateCameraPosition(
  camera: THREE.PerspectiveCamera,
  rotationX: number,
  rotationY: number
): void {
  camera.position.x = Math.sin(rotationY) * 3.5;
  camera.position.z = Math.cos(rotationY) * 3.5;
  camera.position.y = rotationX * 0.5;
  camera.lookAt(0, 0, 0);
}

/**
 * Get optimal particle configuration using LOD system
 */
function getOptimalParticleCount(): number {
  if (typeof window === "undefined") {
    return 3000;
  }

  // Use comprehensive device detection system
  const capabilities = getDeviceCapabilities();
  const lodConfig = getParticleLODConfig(capabilities);

  // Log device capabilities in development
  if (process.env.NODE_ENV === "development") {
    logDeviceCapabilities();
  }

  return lodConfig.particleCount;
}

function updateParticlePhysics(
  positions: Float32Array,
  velocities: Float32Array,
  originalPositions: Float32Array,
  _colors: Float32Array,
  particleCount: number,
  config: any
): void {
  const { intersectionPoint, repelStrength, damping } = config;

  for (let i = 0; i < particleCount; i++) {
    const idx = i * 3;

    // Current state
    const px = positions[idx] ?? 0;
    const py = positions[idx + 1] ?? 0;
    const pz = positions[idx + 2] ?? 0;

    const vx = velocities[idx] ?? 0;
    const vy = velocities[idx + 1] ?? 0;
    const vz = velocities[idx + 2] ?? 0;

    // Original position for attraction
    const opx = originalPositions[idx] ?? 0;
    const opy = originalPositions[idx + 1] ?? 0;
    const opz = originalPositions[idx + 2] ?? 0;

    let nvx = vx * damping;
    let nvy = vy * damping;
    let nvz = vz * damping;

    // Attraction to original position
    const adx = opx - px;
    const ady = opy - py;
    const adz = opz - pz;
    const aDist = Math.sqrt(adx * adx + ady * ady + adz * adz);

    if (aDist > 0.01) {
      const aNorm = 0.02 / (aDist + 0.001);
      nvx += adx * aNorm;
      nvy += ady * aNorm;
      nvz += adz * aNorm;
    }

    // Repulsion from intersection point
    if (intersectionPoint) {
      const rdx = px - intersectionPoint.x;
      const rdy = py - intersectionPoint.y;
      const rdz = pz - intersectionPoint.z;
      const rDist = Math.sqrt(rdx * rdx + rdy * rdy + rdz * rdz);

      if (rDist < 0.5) {
        const rForce = repelStrength / (rDist + 0.01);
        nvx += (rdx / (rDist + 0.001)) * rForce;
        nvy += (rdy / (rDist + 0.001)) * rForce;
        nvz += (rdz / (rDist + 0.001)) * rForce;
      }
    }

    // Update velocities
    velocities[idx] = nvx;
    velocities[idx + 1] = nvy;
    velocities[idx + 2] = nvz;

    // Update positions
    positions[idx] = px + nvx;
    positions[idx + 1] = py + nvy;
    positions[idx + 2] = pz + nvz;
  }
}

const clamp = (value: number, min: number, max: number) => {
  return Math.max(min, Math.min(max, value));
};

const sdBox = (
  px: number,
  py: number,
  bx: number,
  by: number,
  r: number
): number => {
  const dx = Math.abs(px) - bx;
  const dy = Math.abs(py) - by;
  return (
    Math.sqrt(Math.max(dx, 0) ** 2 + Math.max(dy, 0) ** 2) +
    Math.min(Math.max(dx, dy), 0) -
    r
  );
};

const sdCircle = (
  px: number,
  py: number,
  cx: number,
  cy: number,
  r: number
): number => {
  return Math.hypot(px - cx, py - cy) - r;
};

const sdRing = (
  px: number,
  py: number,
  cx: number,
  cy: number,
  r: number,
  thickness: number
): number => {
  return Math.abs(sdCircle(px, py, cx, cy, r)) - thickness;
};

const sdSegment = (
  px: number,
  py: number,
  ax: number,
  ay: number,
  bx: number,
  by: number,
  r: number
): number => {
  const pax = px - ax;
  const pay = py - ay;
  const bax = bx - ax;
  const bay = by - ay;
  const h = clamp((pax * bax + pay * bay) / (bax * bax + bay * bay), 0, 1);
  const dx = pax - bax * h;
  const dy = pay - bay * h;
  return Math.sqrt(dx * dx + dy * dy) - r;
};

const sdArc = (
  px: number,
  py: number,
  cx: number,
  cy: number,
  r: number,
  startAngle: number,
  endAngle: number,
  thickness: number
): number => {
  const dx = px - cx;
  const dy = py - cy;
  const angle = Math.atan2(dy, dx);

  let normAngle = angle;
  while (normAngle < startAngle) normAngle += Math.PI * 2;
  while (normAngle > endAngle + Math.PI * 2) normAngle -= Math.PI * 2;

  const clampedAngle = clamp(normAngle, startAngle, endAngle);
  const targetX = cx + Math.cos(clampedAngle) * r;
  const targetY = cy + Math.sin(clampedAngle) * r;

  return Math.hypot(px - targetX, py - targetY) - thickness;
};

const opUnion = (a: number, b: number): number => Math.min(a, b);
const opSubtract = (a: number, b: number): number => Math.max(a, -b);

const dist_t = (px: number, py: number): number => {
  const x = LETTER_POSITIONS.T;
  const stem = sdSegment(
    px,
    py,
    x,
    BASELINE + ASCENDER_HEIGHT - 0.05,
    x,
    BASELINE,
    STROKE_WIDTH
  );
  const crossbar = sdSegment(
    px,
    py,
    x - 0.15,
    BASELINE + ASCENDER_HEIGHT,
    x + 0.15,
    BASELINE + ASCENDER_HEIGHT,
    STROKE_WIDTH
  );
  return opUnion(stem, crossbar);
};

const dist_h = (px: number, py: number): number => {
  const x = LETTER_POSITIONS.H;
  const stem = sdSegment(
    px,
    py,
    x,
    BASELINE + ASCENDER_HEIGHT,
    x,
    BASELINE,
    STROKE_WIDTH
  );
  const shoulder = sdArc(
    px,
    py,
    x,
    BASELINE + X_HEIGHT * 0.8,
    0.22,
    -Math.PI / 2,
    0,
    STROKE_WIDTH
  );
  const rightLeg = sdSegment(
    px,
    py,
    x + 0.22,
    BASELINE + X_HEIGHT * 0.8,
    x + 0.22,
    BASELINE,
    STROKE_WIDTH
  );
  return opUnion(opUnion(stem, shoulder), rightLeg);
};

const dist_e = (px: number, py: number): number => {
  const cx = LETTER_POSITIONS.E;
  const cy = BASELINE + X_HEIGHT * 0.5;
  const r = 0.2;

  let ring = sdRing(px, py, cx, cy, r, STROKE_WIDTH);
  const cutBox = sdBox(px - (cx + r * 0.5), py - cy, 0.15, 0.14, 0);
  ring = opSubtract(ring, cutBox);

  const bar = sdSegment(px, py, cx - r, cy, cx + r * 0.7, cy, STROKE_WIDTH);

  return opUnion(ring, bar);
};

const dist_c = (px: number, py: number): number => {
  const cx = LETTER_POSITIONS.C;
  const cy = BASELINE + X_HEIGHT * 0.5;
  const r = 0.2;

  let ring = sdRing(px, py, cx, cy, r, STROKE_WIDTH);
  const cutBox = sdBox(px - (cx + r * 0.5), py - cy, 0.15, 0.14, 0);
  ring = opSubtract(ring, cutBox);

  return ring;
};

const dist_o = (px: number, py: number): number => {
  const cx = LETTER_POSITIONS.O;
  const cy = BASELINE + X_HEIGHT * 0.5;
  const r = 0.2;
  return sdRing(px, py, cx, cy, r, STROKE_WIDTH);
};

const dist_p = (px: number, py: number): number => {
  const x = LETTER_POSITIONS.P;
  const cy = BASELINE + X_HEIGHT * 0.5;

  const stem = sdSegment(
    px,
    py,
    x,
    BASELINE + X_HEIGHT,
    x,
    BASELINE + DESCENDER_DEPTH,
    STROKE_WIDTH
  );
  const bowl = sdRing(px, py, x + 0.2, cy, 0.17, STROKE_WIDTH);

  return opUnion(stem, bowl);
};

const dist_y = (px: number, py: number): number => {
  const x = LETTER_POSITIONS.Y;
  const top = BASELINE + X_HEIGHT;
  const mid = BASELINE + X_HEIGHT * 0.2;

  const leftArm = sdSegment(px, py, x - 0.15, top, x, mid, STROKE_WIDTH);
  const rightArm = sdSegment(px, py, x + 0.15, top, x, mid, STROKE_WIDTH);
  const descender = sdSegment(
    px,
    py,
    x,
    mid,
    x + 0.05,
    BASELINE + DESCENDER_DEPTH,
    STROKE_WIDTH
  );

  return opUnion(opUnion(leftArm, rightArm), descender);
};

const dist_dash = (px: number, py: number): number => {
  const x = LETTER_POSITIONS.DASH;
  return sdSegment(
    px,
    py,
    x - 0.1,
    BASELINE + X_HEIGHT * 0.5,
    x + 0.1,
    BASELINE + X_HEIGHT * 0.5,
    STROKE_WIDTH * 0.8
  );
};

const dist_alef = (px: number, py: number): number => {
  const x = LETTER_POSITIONS.ALEF;
  const stem = sdSegment(
    px,
    py,
    x,
    BASELINE + ARABIC_HEIGHT * 0.95,
    x,
    BASELINE,
    STROKE_WIDTH * 1.2
  );
  const base = sdSegment(
    px,
    py,
    x - 0.03,
    BASELINE,
    x + 0.03,
    BASELINE,
    STROKE_WIDTH * 1.5
  );
  return opUnion(stem, base);
};

const dist_lam = (px: number, py: number): number => {
  const x = LETTER_POSITIONS.LAM;
  const stem = sdSegment(
    px,
    py,
    x,
    BASELINE + ARABIC_HEIGHT * 0.95,
    x,
    BASELINE + 0.08,
    STROKE_WIDTH * 1.2
  );
  const hook = sdArc(
    px,
    py,
    x - 0.12,
    BASELINE + 0.08,
    0.12,
    0,
    Math.PI / 2,
    STROKE_WIDTH * 1.1
  );
  const hookEnd = sdSegment(
    px,
    py,
    x - 0.24,
    BASELINE,
    x - 0.15,
    BASELINE,
    STROKE_WIDTH
  );
  return opUnion(opUnion(stem, hook), hookEnd);
};

const dist_noon = (px: number, py: number): number => {
  const x = LETTER_POSITIONS.NOON;
  const cy = BASELINE + ARABIC_HEIGHT * 0.4;

  const mainArc = sdArc(
    px,
    py,
    x,
    cy,
    0.18,
    -Math.PI * 0.15,
    Math.PI * 0.85,
    STROKE_WIDTH * 1.1
  );
  const connector = sdSegment(
    px,
    py,
    x - 0.17,
    cy - 0.05,
    x - 0.08,
    BASELINE + 0.02,
    STROKE_WIDTH
  );
  const base = sdSegment(
    px,
    py,
    x - 0.08,
    BASELINE + 0.02,
    x + 0.1,
    BASELINE,
    STROKE_WIDTH
  );
  const dot = sdCircle(px, py, x, cy + 0.28, 0.035);

  return opUnion(opUnion(opUnion(mainArc, connector), base), dot);
};

const dist_seen = (px: number, py: number): number => {
  const x = LETTER_POSITIONS.SEEN;
  const baseY = BASELINE + 0.02;
  const toothHeight = ARABIC_HEIGHT * 0.35;

  const baseLine = sdSegment(
    px,
    py,
    x - 0.28,
    baseY,
    x + 0.28,
    baseY,
    STROKE_WIDTH * 1.1
  );

  const tooth1 = sdArc(
    px,
    py,
    x - 0.18,
    baseY + toothHeight * 0.6,
    0.1,
    Math.PI * 0.9,
    Math.PI * 0.1,
    STROKE_WIDTH
  );
  const tooth2 = sdArc(
    px,
    py,
    x,
    baseY + toothHeight * 0.8,
    0.12,
    Math.PI * 0.9,
    Math.PI * 0.1,
    STROKE_WIDTH
  );
  const tooth3 = sdArc(
    px,
    py,
    x + 0.18,
    baseY + toothHeight * 0.6,
    0.1,
    Math.PI * 0.9,
    Math.PI * 0.1,
    STROKE_WIDTH
  );

  const connect1 = sdSegment(
    px,
    py,
    x - 0.18,
    baseY,
    x - 0.18,
    baseY + toothHeight * 0.5,
    STROKE_WIDTH * 0.8
  );
  const connect2 = sdSegment(
    px,
    py,
    x,
    baseY,
    x,
    baseY + toothHeight * 0.7,
    STROKE_WIDTH * 0.8
  );
  const connect3 = sdSegment(
    px,
    py,
    x + 0.18,
    baseY,
    x + 0.18,
    baseY + toothHeight * 0.5,
    STROKE_WIDTH * 0.8
  );

  return opUnion(
    opUnion(
      opUnion(
        opUnion(opUnion(opUnion(baseLine, tooth1), tooth2), tooth3),
        connect1
      ),
      connect2
    ),
    connect3
  );
};

const dist_khaa = (px: number, py: number): number => {
  const x = LETTER_POSITIONS.KHAA;
  const cy = BASELINE + ARABIC_HEIGHT * 0.4;

  const mainArc = sdArc(
    px,
    py,
    x,
    cy,
    0.2,
    Math.PI * 0.6,
    Math.PI * 2.4,
    STROKE_WIDTH * 1.1
  );
  const rightConnect = sdSegment(
    px,
    py,
    x + 0.15,
    cy - 0.12,
    x + 0.12,
    BASELINE,
    STROKE_WIDTH
  );
  const leftConnect = sdSegment(
    px,
    py,
    x - 0.15,
    cy - 0.12,
    x - 0.08,
    BASELINE,
    STROKE_WIDTH
  );
  const dot = sdCircle(px, py, x, cy + 0.28, 0.035);

  return opUnion(opUnion(opUnion(mainArc, rightConnect), leftConnect), dot);
};

const dist_taa_marbouta = (px: number, py: number): number => {
  const x = LETTER_POSITIONS.TAA_MARBOUTA;
  const cy = BASELINE + ARABIC_HEIGHT * 0.4;

  let circle = sdRing(px, py, x, cy, 0.17, STROKE_WIDTH * 1.1);
  const opening = sdBox(px - x, py - (cy - 0.05), 0.08, 0.08, 0);
  circle = opSubtract(circle, opening);

  const dot1 = sdCircle(px, py, x - 0.07, cy + 0.28, 0.03);
  const dot2 = sdCircle(px, py, x + 0.07, cy + 0.28, 0.03);

  return opUnion(opUnion(circle, dot1), dot2);
};

const dist_all = (px: number, py: number): number => {
  return Math.min(
    dist_t(px, py),
    dist_h(px, py),
    dist_e(px, py),
    dist_c(px, py),
    dist_o(px, py),
    dist_p(px, py),
    dist_y(px, py),
    dist_dash(px, py),
    dist_alef(px, py),
    dist_lam(px, py),
    dist_noon(px, py),
    dist_seen(px, py),
    dist_khaa(px, py),
    dist_taa_marbouta(px, py)
  );
};

const dist = (px: number, py: number): number => dist_all(px, py);

export default function V0ParticleAnimation() {
  const canvasRef = useRef<HTMLCanvasElement>(null);

  const sceneRef = useRef<{
    scene: THREE.Scene;
    camera: THREE.PerspectiveCamera;
    renderer: THREE.WebGLRenderer;
    points: THREE.Points;
    geometry: THREE.BufferGeometry;
    originalPositions: Float32Array;
    velocities: Float32Array;
    phases: Float32Array;
    intersectionPoint: THREE.Vector3 | null;
    rotationX: number;
    rotationY: number;
    isDragging: boolean;
    previousMouseX: number;
    previousMouseY: number;
    particleCount: number;
  } | null>(null);

  const currentEffect: Effect = "spark";

  useEffect(() => {
    if (typeof window === "undefined") return;

    const prefersReducedMotion = window.matchMedia(
      "(prefers-reduced-motion: reduce)"
    ).matches;

    if (prefersReducedMotion) return;

    if (!canvasRef.current) return;

    const canvas = canvasRef.current;
    const scene = new THREE.Scene();
    const camera = new THREE.PerspectiveCamera(
      75,
      canvas.width / canvas.height,
      0.1,
      1000
    );
    const renderer = new THREE.WebGLRenderer({ canvas, antialias: true });

    renderer.setSize(canvas.width, canvas.height);
    renderer.setClearColor(0x000000);

    const raycaster = new THREE.Raycaster();
    const mouse = new THREE.Vector2();
    const plane = new THREE.Plane(new THREE.Vector3(0, 0, 1), 0);

    // Use LOD system to determine optimal particle count
    const numParticles = getOptimalParticleCount();

    const thickness = 0.15;
    const positions = new Float32Array(numParticles * 3);
    const colors = new Float32Array(numParticles * 3);

    const { minX, maxX, minY, maxY } = SAMPLING_BOUNDS;

    const originalPositions = new Float32Array(numParticles * 3);
    const velocities = new Float32Array(numParticles * 3);
    const phases = new Float32Array(numParticles);

    camera.position.set(0, 0, 3.2);

    sceneRef.current = {
      scene,
      camera,
      renderer,
      points: null as any,
      geometry: null as any,
      originalPositions,
      velocities,
      phases,
      intersectionPoint: null,
      rotationX: 0,
      rotationY: 0,
      isDragging: false,
      previousMouseX: 0,
      previousMouseY: 0,
      particleCount: 0,
    };

    let animationId: number;

    const handleMouseMove = (event: MouseEvent) => {
      if (!sceneRef.current) return;

      const rect = canvas.getBoundingClientRect();
      mouse.x = ((event.clientX - rect.left) / canvas.width) * 2 - 1;
      mouse.y = -((event.clientY - rect.top) / canvas.height) * 2 + 1;

      raycaster.setFromCamera(mouse, camera);
      const intersection = new THREE.Vector3();
      raycaster.ray.intersectPlane(plane, intersection);
      sceneRef.current.intersectionPoint = intersection;
    };

    const handleMouseLeave = () => {
      if (sceneRef.current) {
        sceneRef.current.intersectionPoint = null;
      }
    };

    canvas.addEventListener("mousemove", handleMouseMove);
    canvas.addEventListener("mouseleave", handleMouseLeave);

    const animate = () => {
      if (!sceneRef.current) return;

      // Record frame time for performance monitoring
      const currentTime = performance.now();
      performanceMonitor.recordFrame(currentTime);

      const {
        scene,
        camera,
        renderer,
        geometry,
        originalPositions,
        velocities,
        intersectionPoint,
        rotationY,
        particleCount,
      } = sceneRef.current;

      if (!geometry || particleCount === 0) {
        renderer.render(scene, camera);
        animationId = requestAnimationFrame(animate);
        return;
      }

      const positionAttribute = geometry.getAttribute("position");
      const colorAttribute = geometry.getAttribute("color");

      if (!positionAttribute || !colorAttribute) {
        renderer.render(scene, camera);
        animationId = requestAnimationFrame(animate);
        return;
      }

      updateCameraPosition(camera, 0, rotationY);

      const positions = new Float32Array(positionAttribute.array);
      const colors = new Float32Array(colorAttribute.array);

      updateParticlePhysics(
        positions,
        velocities,
        originalPositions,
        colors,
        particleCount,
        {
          intersectionPoint,
          effect: currentEffect,
          repelStrength: 0.08,
          damping: 0.92,
        }
      );

      if (positionAttribute instanceof THREE.BufferAttribute) {
        positionAttribute.set(positions);
        positionAttribute.needsUpdate = true;
      }
      if (colorAttribute instanceof THREE.BufferAttribute) {
        colorAttribute.set(colors);
        colorAttribute.needsUpdate = true;
      }

      renderer.render(scene, camera);
      animationId = requestAnimationFrame(animate);
    };

    animationId = requestAnimationFrame(animate);

    const generateParticlesInBatches = (batchSize = 750): Promise<number> => {
      return new Promise((resolve, reject) => {
        let generatedCount = 0;
        const maxAttempts = 3000000;
        let attempts = 0;
        let batchAttempts = 0;
        const maxBatchAttempts = 50000;

        const processBatch = () => {
          try {
            let batchGenerated = 0;

            while (
              batchGenerated < batchSize &&
              generatedCount < numParticles &&
              attempts < maxAttempts &&
              batchAttempts < maxBatchAttempts
            ) {
              attempts++;
              batchAttempts++;

              const x = Math.random() * (maxX - minX) + minX;
              const y = Math.random() * (maxY - minY) + minY;
              const z = Math.random() * thickness - thickness / 2;

              const d = dist(x, y);

              const threshold =
                x > 2.5
                  ? PARTICLE_THRESHOLDS.arabic
                  : PARTICLE_THRESHOLDS.english;

              if (d <= threshold) {
                positions[generatedCount * 3] = x;
                positions[generatedCount * 3 + 1] = y;
                positions[generatedCount * 3 + 2] = z;
                colors[generatedCount * 3] = 1;
                colors[generatedCount * 3 + 1] = 1;
                colors[generatedCount * 3 + 2] = 1;
                generatedCount++;
                batchGenerated++;
              }
            }

            if (
              generatedCount < numParticles &&
              attempts < maxAttempts &&
              batchAttempts < maxBatchAttempts
            ) {
              if (typeof requestIdleCallback !== "undefined") {
                requestIdleCallback(processBatch, { timeout: 100 });
              } else {
                setTimeout(processBatch, 0);
              }
            } else {
              resolve(generatedCount);
            }
          } catch (error) {
            reject(error);
          }
        };

        processBatch();
      });
    };

    generateParticlesInBatches()
      .then((finalCount) => {
        console.log("[v0] Generated particles:", finalCount);
        if (!sceneRef.current) return;

        sceneRef.current.particleCount = finalCount;

        const finalPositions = positions.slice(0, finalCount * 3);
        const finalColors = colors.slice(0, finalCount * 3);

        // Copy to original positions
        if (finalCount > 0) {
          for (let i = 0; i < finalCount * 3; i++) {
            originalPositions[i] = finalPositions[i] ?? 0;
          }
        }

        const geometry = new THREE.BufferGeometry();
        geometry.setAttribute(
          "position",
          new THREE.BufferAttribute(finalPositions, 3)
        );
        geometry.setAttribute(
          "color",
          new THREE.BufferAttribute(finalColors, 3)
        );

        const material = new THREE.PointsMaterial({
          size: 0.0045,
          sizeAttenuation: true,
          vertexColors: true,
          transparent: true,
          opacity: 0.95,
        });

        const points = new THREE.Points(geometry, material);
        scene.add(points);

        sceneRef.current.geometry = geometry;
        sceneRef.current.points = points;

        console.log("[v0] Particles added to scene");
      })
      .catch((error) => {
        console.error("Failed to generate particles:", error);
      });

    const cleanup = () => {
      try {
        cancelAnimationFrame(animationId);
        canvas.removeEventListener("mousemove", handleMouseMove);
        canvas.removeEventListener("mouseleave", handleMouseLeave);

        if (sceneRef.current?.geometry) sceneRef.current.geometry.dispose();
        if (sceneRef.current?.points?.material) {
          const material = sceneRef.current.points.material;
          if (material && !Array.isArray(material)) {
            material.dispose();
          }
        }
        if (renderer) renderer.dispose();

        // Cleanup performance monitor
        performanceMonitor.reset();
        performanceMonitor.destroy();

        if (sceneRef.current) {
          sceneRef.current.originalPositions = null as any;
          sceneRef.current.velocities = null as any;
          sceneRef.current.phases = null as any;
          sceneRef.current = null;
        }
      } catch (error) {
        console.error("Cleanup error:", error);
      }
    };

    const safetyCleanup = setTimeout(cleanup, 300000);

    return () => {
      clearTimeout(safetyCleanup);
      cleanup();
    };
  }, []);

  const handleMouseDown = (event: React.MouseEvent) => {
    if (!sceneRef.current) return;
    sceneRef.current.isDragging = true;
    sceneRef.current.previousMouseX = event.clientX;
    sceneRef.current.previousMouseY = event.clientY;
  };

  const handleMouseMove = (event: React.MouseEvent) => {
    if (!sceneRef.current?.isDragging) return;

    const deltaX = event.clientX - sceneRef.current.previousMouseX;
    const deltaY = event.clientY - sceneRef.current.previousMouseY;

    sceneRef.current.rotationY -= deltaX * 0.005;
    sceneRef.current.rotationX -= deltaY * 0.005;

    sceneRef.current.previousMouseX = event.clientX;
    sceneRef.current.previousMouseY = event.clientY;
  };

  const handleMouseUp = () => {
    if (sceneRef.current) {
      sceneRef.current.isDragging = false;
    }
  };

  const handleTouchStart = (event: React.TouchEvent) => {
    if (!sceneRef.current || !event.touches[0]) return;
    sceneRef.current.isDragging = true;
    sceneRef.current.previousMouseX = event.touches[0].clientX;
    sceneRef.current.previousMouseY = event.touches[0].clientY;
  };

  const handleTouchMove = (event: React.TouchEvent) => {
    if (!sceneRef.current || !sceneRef.current.isDragging || !event.touches[0])
      return;

    const deltaX = event.touches[0].clientX - sceneRef.current.previousMouseX;
    const deltaY = event.touches[0].clientY - sceneRef.current.previousMouseY;

    sceneRef.current.rotationY -= deltaX * 0.005;
    sceneRef.current.rotationX -= deltaY * 0.005;

    sceneRef.current.previousMouseX = event.touches[0].clientX;
    sceneRef.current.previousMouseY = event.touches[0].clientY;
  };

  const handleTouchEnd = () => {
    if (sceneRef.current) {
      sceneRef.current.isDragging = false;
    }
  };

  return (
    <div className="relative flex items-center justify-center w-full h-full bg-black">
      <canvas
        ref={canvasRef}
        width={1400}
        height={600}
        className="block"
        onMouseDown={handleMouseDown}
        onMouseMove={handleMouseMove}
        onMouseUp={handleMouseUp}
        onMouseLeave={handleMouseUp}
        onTouchStart={handleTouchStart}
        onTouchMove={handleTouchMove}
        onTouchEnd={handleTouchEnd}
      />
    </div>
  );
}

/**
 * Particle effect helper functions with LOD support
 * Extracted from particle-background.tsx to reduce complexity
 *
 * Features:
 * - Device detection and performance adaptation
 * - Level of Detail (LOD) system
 * - Dynamic quality adjustment
 */

import {
  getDeviceCapabilities,
  getParticleLODConfig,
  PerformanceMonitor,
} from "@/components/device-detection";

/**
 * Enhanced requestIdleCallback with fallback
 */
export const requestIdle = (
  callback: (deadline: any) => void,
  options?: any
): number => {
  if (typeof requestIdleCallback !== "undefined") {
    return requestIdleCallback(callback, options);
  } else {
    // Fallback to setTimeout
    return setTimeout(
      () =>
        callback({
          timeRemaining: () => Math.max(0, 50), // Simulate 50ms remaining time
          didTimeout: false,
        }),
      options?.timeout ?? 0
    ) as any;
  }
};

/**
 * Cancel idle callback
 */
export const cancelIdle = (id: number): void => {
  if (typeof cancelIdleCallback !== "undefined") {
    cancelIdleCallback(id);
  } else {
    clearTimeout(id);
  }
};

/**
 * Batch processor for particle operations
 */
export class BatchProcessor {
  private items: any[] = [];
  private batchSize: number;

  constructor(batchSize = 500) {
    this.batchSize = batchSize;
  }

  add(item: any): void {
    this.items.push(item);
  }

  processBatch(): Promise<void> {
    return new Promise((resolve, reject) => {
      try {
        const batch = this.items.splice(0, this.batchSize);

        if (batch.length === 0) {
          resolve();
          return;
        }

        requestIdle(
          () => {
            try {
              void batch;
              resolve();
            } catch (error) {
              reject(error);
            }
          },
          { timeout: 100 }
        );
      } catch (error) {
        reject(error);
      }
    });
  }
}

export interface ParticleVelocity {
  vx: number;
  vy: number;
  vz: number;
}

export interface ParticlePosition {
  px: number;
  py: number;
  pz: number;
}

export interface EffectConfig {
  effectRadius: number;
  repelStrength: number;
}

/**
 * Apply spark effect to particle with error handling
 */
export function applySparkEffect(
  particle: ParticlePosition,
  intersection: { x: number; y: number; z: number },
  velocity: ParticleVelocity,
  config: EffectConfig
): ParticleVelocity {
  try {
    const dx = particle.px - intersection.x;
    const dy = particle.py - intersection.y;
    const dz = particle.pz - intersection.z;
    const distSq = dx * dx + dy * dy + dz * dz;

    if (distSq < config.effectRadius * config.effectRadius && distSq > 0.0001) {
      const dist = Math.sqrt(distSq);
      const force = (1 - dist / config.effectRadius) * config.repelStrength * 3;
      return {
        vx: velocity.vx + (dx / dist) * force,
        vy: velocity.vy + (dy / dist) * force,
        vz: velocity.vz + (dz / dist) * force,
      };
    }

    return velocity;
  } catch (error) {
    console.warn("خطأ في تأثير الشرر:", error);
    return velocity;
  }
}

/**
 * Apply wave effect to particle with error handling
 */
export function applyWaveEffect(
  particle: ParticlePosition,
  intersection: { x: number; y: number; z: number },
  velocity: ParticleVelocity,
  config: EffectConfig,
  time: number
): ParticleVelocity {
  try {
    const dx = particle.px - intersection.x;
    const dy = particle.py - intersection.y;
    const dz = particle.pz - intersection.z;
    const distSq = dx * dx + dy * dy + dz * dz;

    if (distSq < config.effectRadius * config.effectRadius) {
      const dist = Math.sqrt(distSq);
      const wavePhase = time * 8 - dist * 12;
      const waveStrength = 0.12;
      const waveForce =
        Math.sin(wavePhase) * waveStrength * (1 - dist / config.effectRadius);
      if (dist > 0.001) {
        return {
          vx: velocity.vx + (dx / dist) * waveForce,
          vy: velocity.vy + (dy / dist) * waveForce,
          vz: velocity.vz + waveForce * 0.5,
        };
      }
    }

    return velocity;
  } catch (error) {
    console.warn("خطأ في تأثير الموجة:", error);
    return velocity;
  }
}

/**
 * Apply vortex effect to particle with error handling
 */
export function applyVortexEffect(
  particle: ParticlePosition,
  intersection: { x: number; y: number; z: number },
  velocity: ParticleVelocity,
  config: EffectConfig
): ParticleVelocity {
  try {
    const dx = particle.px - intersection.x;
    const dy = particle.py - intersection.y;
    const dz = particle.pz - intersection.z;
    const distSq = dx * dx + dy * dy + dz * dz;
    const dist = Math.sqrt(distSq);

    if (distSq < config.effectRadius * config.effectRadius && dist > 0.05) {
      const vortexStrength = 0.15;
      const spiralForce = vortexStrength * (1 - dist / config.effectRadius);

      const tangentX = -dy;
      const tangentY = dx;
      const tangentLength = Math.sqrt(
        tangentX * tangentX + tangentY * tangentY
      );

      let newVx = velocity.vx;
      let newVy = velocity.vy;

      if (tangentLength > 0.001) {
        newVx += (tangentX / tangentLength) * spiralForce;
        newVy += (tangentY / tangentLength) * spiralForce;
      }

      const pullStrength = spiralForce * 0.3;
      newVx -= (dx / dist) * pullStrength;
      newVy -= (dy / dist) * pullStrength;

      return {
        vx: newVx,
        vy: newVy,
        vz: velocity.vz,
      };
    }

    return velocity;
  } catch (error) {
    console.warn("خطأ في تأثير الدوامة:", error);
    return velocity;
  }
}

/**
 * Apply default repel effect to particle with error handling
 */
export function applyDefaultEffect(
  particle: ParticlePosition,
  intersection: { x: number; y: number; z: number },
  velocity: ParticleVelocity,
  config: EffectConfig
): ParticleVelocity {
  try {
    const dx = particle.px - intersection.x;
    const dy = particle.py - intersection.y;
    const dz = particle.pz - intersection.z;
    const distSq = dx * dx + dy * dy + dz * dz;
    const dist = Math.sqrt(distSq);

    if (distSq < config.effectRadius * config.effectRadius && distSq > 0.0001) {
      const force = (1 - dist / config.effectRadius) * config.repelStrength;
      return {
        vx: velocity.vx + (dx / dist) * force,
        vy: velocity.vy + (dy / dist) * force,
        vz: velocity.vz + (dz / dist) * force,
      };
    }

    return velocity;
  } catch (error) {
    console.warn("خطأ في التأثير الافتراضي:", error);
    return velocity;
  }
}

/**
 * Calculate color for wave effect with error handling
 */
export function calculateWaveColor(
  particle: ParticlePosition,
  intersection: { x: number; y: number; z: number },
  effectRadius: number,
  time: number
): { r: number; g: number; b: number } {
  try {
    const dx = particle.px - intersection.x;
    const dy = particle.py - intersection.y;
    const dz = particle.pz - intersection.z;
    const distSq = dx * dx + dy * dy + dz * dz;
    const dist = Math.sqrt(distSq);

    if (distSq < effectRadius * effectRadius) {
      const wavePhase = time * 8 - dist * 15;
      const intensity =
        Math.abs(Math.sin(wavePhase)) * (1 - dist / effectRadius) + 1;
      return {
        r: intensity * 0.5 + 0.8,
        g: intensity * 0.8 + 0.6,
        b: intensity * 1.2 + 0.4,
      };
    }

    return { r: 1, g: 1, b: 1 };
  } catch (error) {
    console.warn("خطأ في حساب لون الموجة:", error);
    return { r: 1, g: 1, b: 1 };
  }
}

/**
 * Calculate color for vortex effect with error handling
 */
export function calculateVortexColor(
  particle: ParticlePosition,
  intersection: { x: number; y: number; z: number },
  effectRadius: number,
  time: number
): { r: number; g: number; b: number } {
  try {
    const dx = particle.px - intersection.x;
    const dy = particle.py - intersection.y;
    const dz = particle.pz - intersection.z;
    const distSq = dx * dx + dy * dy + dz * dz;
    const dist = Math.sqrt(distSq);

    if (distSq < effectRadius * effectRadius) {
      const angle = Math.atan2(dy, dx) + time * 5;
      const intensity = (1 - dist / effectRadius) * 2 + 1;
      return {
        r: (Math.sin(angle) * 0.5 + 0.5) * intensity,
        g: (Math.sin(angle + (Math.PI * 2) / 3) * 0.5 + 0.5) * intensity,
        b: (Math.sin(angle + (Math.PI * 4) / 3) * 0.5 + 0.5) * intensity,
      };
    }

    return { r: 1, g: 1, b: 1 };
  } catch (error) {
    console.warn("خطأ في حساب لون الدوامة:", error);
    return { r: 1, g: 1, b: 1 };
  }
}

