                  </div>

                  {/* Actions */}
                  <div className="flex items-center gap-2 pt-4 border-t">
                    <Button
                      variant={selectedShot.isSaved ? "secondary" : "outline"}
                      onClick={() => toggleSave(selectedShot.id)}
