  },
  {
    id: "arri-alexa-lf",
    name: "ARRI ALEXA LF",
    nameAr: "آري أليكسا LF",
    width: 36.7,
    height: 25.54,
    cropFactor: 0.98,
    circleOfConfusion: 0.029,
  },
  {
    id: "arri-alexa-35",
    name: "ARRI ALEXA 35",
    nameAr: "آري أليكسا 35",
    width: 27.99,
    height: 19.22,
    cropFactor: 1.28,
    circleOfConfusion: 0.022,
  },
  {
    id: "red-monstro",
    name: "RED Monstro 8K",
    nameAr: "ريد مونسترو",
    width: 40.96,
    height: 21.6,
    cropFactor: 0.88,
    circleOfConfusion: 0.033,
  },
  {
    id: "red-komodo",
    name: "RED Komodo",
    nameAr: "ريد كومودو",
    width: 27.03,
