    circleOfConfusion: 0.027,
  },
  {
    id: "aps-c",
    name: "APS-C",
    nameAr: "APS-C",
    width: 23.5,
    height: 15.6,
    cropFactor: 1.5,
    circleOfConfusion: 0.018,
  },
  {
    id: "micro-43",
