/**
 * Spatial Scene Planner Component for Directors Studio
 * Based on UI_DESIGN_SUGGESTIONS.md
 *
 * Features:
 * - 3D scene visualization with grid
 * - Camera position and angle control
 * - Object placement (characters, props, lights)
 * - Shot preview simulation
 * - Timeline for shot sequencing
 * - Light placement and preview
 */

interface Position3D {
  x: number;
  y: number;
  z: number;
}

interface Rotation3D {
  pitch: number; // X rotation
  yaw: number; // Y rotation
  roll: number; // Z rotation
}

interface SceneObject {
  id: string;
  type: "character" | "prop" | "light" | "camera";
  name: string;
  position: Position3D;
  rotation: Rotation3D;
  scale: number;
  color?: string;
  visible: boolean;
}

interface CameraSettings {
  focalLength: number;
  aperture: number;
  position: Position3D;
  lookAt: Position3D;
  rotation: Rotation3D;
}

interface ShotKeyframe {
  id: string;
  time: number;
  camera: CameraSettings;
  label: string;
}

interface SpatialScenePlannerProps {
  sceneId?: string;
  sceneName?: string;
  onSave?: (data: {
    objects: SceneObject[];
    shots: ShotKeyframe[];
    camera: CameraSettings;
  }) => void;
  className?: string;
}

const CELL_SIZE = 40;

// Object type icons
const ObjectIcons = {
  character: User,
  prop: Box,
  light: Lightbulb,
  camera: Camera,
};

// Camera presets
const CAMERA_PRESETS = [
  { name: "لقطة عريضة", focalLength: 24, position: { x: 0, y: 200, z: 500 } },
  { name: "لقطة متوسطة", focalLength: 50, position: { x: 0, y: 150, z: 300 } },
  { name: "لقطة قريبة", focalLength: 85, position: { x: 0, y: 100, z: 150 } },
  {
    name: "لقطة قريبة جداً",
    focalLength: 135,
    position: { x: 0, y: 80, z: 80 },
  },
  { name: "زاوية عالية", focalLength: 35, position: { x: 0, y: 400, z: 300 } },
  { name: "زاوية منخفضة", focalLength: 35, position: { x: 0, y: 50, z: 300 } },
];

export function SpatialScenePlanner({
  sceneName = "مشهد جديد",
  onSave,
  className,
}: SpatialScenePlannerProps) {
  const canvasRef = React.useRef<HTMLDivElement>(null);

  // Scene state
  const [objects, setObjects] = React.useState<SceneObject[]>([
    {
      id: "char-1",
      type: "character",
      name: "الشخصية 1",
      position: { x: 0, y: 0, z: 0 },
      rotation: { pitch: 0, yaw: 0, roll: 0 },
      scale: 1,
      color: "oklch(0.7 0.15 200)",
      visible: true,
    },
  ]);

  const [camera, setCamera] = React.useState<CameraSettings>({
    focalLength: 50,
    aperture: 2.8,
    position: { x: 0, y: 150, z: 300 },
    lookAt: { x: 0, y: 0, z: 0 },
    rotation: { pitch: -15, yaw: 0, roll: 0 },
  });

  const [shots, setShots] = React.useState<ShotKeyframe[]>([]);
  const [selectedObject, setSelectedObject] = React.useState<string | null>(
    null
  );
  const [selectedShot, setSelectedShot] = React.useState<string | null>(null);
  const [tool, setTool] = React.useState<
    "select" | "move" | "rotate" | "camera"
  >("select");
  const [viewMode, setViewMode] = React.useState<
    "top" | "side" | "front" | "perspective"
  >("perspective");
  const [showGrid, setShowGrid] = React.useState(true);
  const [showLightPreview, setShowLightPreview] = React.useState(true);
  const [isPlaying, setIsPlaying] = React.useState(false);
  const [currentTime, setCurrentTime] = React.useState(0);
  const [timeOfDay, setTimeOfDay] = React.useState<"day" | "night" | "sunset">(
    "day"
  );

  // Viewport drag state
  const [isDragging, setIsDragging] = React.useState(false);
  const [dragStart, setDragStart] = React.useState({ x: 0, y: 0 });
  const [viewOffset, setViewOffset] = React.useState({ x: 0, y: 0 });
  const [zoom, setZoom] = React.useState(1);

  // Add object
  const addObject = (type: SceneObject["type"]) => {
    const newObject: SceneObject = {
      id: `${type}-${Date.now()}`,
      type,
      name:
        type === "character"
          ? `شخصية ${objects.filter((o) => o.type === "character").length + 1}`
          : type === "prop"
            ? `عنصر ${objects.filter((o) => o.type === "prop").length + 1}`
            : type === "light"
              ? `إضاءة ${objects.filter((o) => o.type === "light").length + 1}`
              : `كاميرا ${objects.filter((o) => o.type === "camera").length + 1}`,
      position: {
        x: Math.random() * 200 - 100,
        y: 0,
        z: Math.random() * 200 - 100,
      },
      rotation: { pitch: 0, yaw: 0, roll: 0 },
      scale: 1,
      color:
        type === "light"
          ? "oklch(0.9 0.15 80)"
          : `oklch(0.6 0.15 ${Math.random() * 360})`,
      visible: true,
    };
    setObjects([...objects, newObject]);
    setSelectedObject(newObject.id);
  };

  // Delete selected object
  const deleteObject = (id: string) => {
    setObjects(objects.filter((o) => o.id !== id));
    if (selectedObject === id) setSelectedObject(null);
  };

  // Update object
  const updateObject = (id: string, updates: Partial<SceneObject>) => {
    setObjects(objects.map((o) => (o.id === id ? { ...o, ...updates } : o)));
  };

  // Add shot keyframe
  const addShot = () => {
    const newShot: ShotKeyframe = {
      id: `shot-${Date.now()}`,
      time: shots.length * 2,
      camera: { ...camera },
      label: `لقطة ${shots.length + 1}`,
    };
    setShots([...shots, newShot]);
    setSelectedShot(newShot.id);
  };

  // Apply camera preset
  const applyCameraPreset = (preset: (typeof CAMERA_PRESETS)[0]) => {
    setCamera((prev) => ({
      ...prev,
      focalLength: preset.focalLength,
      position: { ...preset.position },
    }));
  };

  // Go to shot
  const goToShot = (shot: ShotKeyframe) => {
    setCamera(shot.camera);
    setSelectedShot(shot.id);
    setCurrentTime(shot.time);
  };

  // Handle save
  const handleSave = () => {
    onSave?.({ objects, shots, camera });
  };

  // Calculate viewport transform for object
  const getObjectViewportPosition = (pos: Position3D) => {
    // Simplified perspective projection
    const scale =
      zoom *
      (viewMode === "perspective"
        ? 500 / (500 - pos.z + camera.position.z)
        : 1);
    let x = 0,
      y = 0;

    switch (viewMode) {
      case "top":
        x = pos.x * zoom + viewOffset.x;
        y = pos.z * zoom + viewOffset.y;
        break;
      case "side":
        x = pos.z * zoom + viewOffset.x;
        y = -pos.y * zoom + viewOffset.y;
        break;
      case "front":
        x = pos.x * zoom + viewOffset.x;
        y = -pos.y * zoom + viewOffset.y;
        break;
      case "perspective":
      default:
        x = pos.x * scale + viewOffset.x;
        y = (-pos.y + pos.z * 0.3) * scale + viewOffset.y;
        break;
    }

    return { x, y, scale };
  };

  // Get time of day lighting
  const getTimeOfDayStyle = () => {
    switch (timeOfDay) {
      case "night":
        return "from-slate-900 via-slate-800 to-slate-900";
      case "sunset":
        return "from-orange-300/20 via-amber-200/10 to-blue-300/20";
      default:
        return "from-blue-100/30 via-white/5 to-blue-100/30";
    }
  };

  return (
    <TooltipProvider>
      <div
        className={cn("spatial-scene-planner flex flex-col h-full", className)}
      >
        {/* Header */}
        <div className="flex items-center justify-between p-4 border-b bg-card">
          <div className="flex items-center gap-4">
            <div>
              <h2 className="text-lg font-semibold flex items-center gap-2">
                <Move3D className="h-5 w-5 text-brand" />
                {sceneName}
              </h2>
              <p className="text-sm text-muted-foreground">
                مخطط المشهد المكاني
              </p>
            </div>
            <Badge variant="outline">{shots.length} لقطات</Badge>
          </div>

          <div className="flex items-center gap-2">
            <Button variant="outline" size="sm" onClick={handleSave}>
              <Save className="h-4 w-4 ml-2" />
              حفظ
            </Button>
            <Button variant="outline" size="sm">
              <Download className="h-4 w-4 ml-2" />
              تصدير
            </Button>
          </div>
        </div>

        <div className="flex flex-1 overflow-hidden">
          {/* Left Sidebar - Objects & Tools */}
          <div className="w-64 border-l bg-card/50 flex flex-col">
            {/* Tool Selection */}
            <div className="p-3 border-b">
              <p className="text-xs font-medium text-muted-foreground mb-2">
                الأدوات
              </p>
              <div className="flex gap-1">
                <Tooltip>
                  <TooltipTrigger asChild>
                    <Button
                      variant={tool === "select" ? "default" : "ghost"}
                      size="icon"
                      onClick={() => setTool("select")}
                    >
                      <Camera className="h-4 w-4" />
                    </Button>
                  </TooltipTrigger>
                  <TooltipContent>تحديد</TooltipContent>
                </Tooltip>
                <Tooltip>
                  <TooltipTrigger asChild>
                    <Button
                      variant={tool === "move" ? "default" : "ghost"}
                      size="icon"
                      onClick={() => setTool("move")}
                    >
                      <Move3D className="h-4 w-4" />
                    </Button>
                  </TooltipTrigger>
                  <TooltipContent>تحريك</TooltipContent>
                </Tooltip>
                <Tooltip>
                  <TooltipTrigger asChild>
                    <Button
                      variant={tool === "rotate" ? "default" : "ghost"}
                      size="icon"
                      onClick={() => setTool("rotate")}
                    >
                      <RotateCcw className="h-4 w-4" />
                    </Button>
                  </TooltipTrigger>
                  <TooltipContent>تدوير</TooltipContent>
                </Tooltip>
                <Tooltip>
                  <TooltipTrigger asChild>
                    <Button
                      variant={tool === "camera" ? "default" : "ghost"}
                      size="icon"
                      onClick={() => setTool("camera")}
                    >
                      <Video className="h-4 w-4" />
                    </Button>
                  </TooltipTrigger>
                  <TooltipContent>كاميرا</TooltipContent>
                </Tooltip>
              </div>
            </div>

            {/* Add Objects */}
            <div className="p-3 border-b">
              <p className="text-xs font-medium text-muted-foreground mb-2">
                إضافة عناصر
              </p>
              <div className="grid grid-cols-2 gap-2">
                <Button
                  variant="outline"
                  size="sm"
                  className="justify-start"
                  onClick={() => addObject("character")}
                >
                  <User className="h-4 w-4 ml-2" />
                  شخصية
                </Button>
                <Button
                  variant="outline"
                  size="sm"
                  className="justify-start"
                  onClick={() => addObject("prop")}
                >
                  <Box className="h-4 w-4 ml-2" />
                  عنصر
                </Button>
                <Button
                  variant="outline"
                  size="sm"
                  className="justify-start"
                  onClick={() => addObject("light")}
                >
                  <Lightbulb className="h-4 w-4 ml-2" />
                  إضاءة
                </Button>
                <Button
                  variant="outline"
                  size="sm"
                  className="justify-start"
                  onClick={() => addObject("camera")}
                >
                  <Camera className="h-4 w-4 ml-2" />
                  كاميرا
                </Button>
              </div>
            </div>

            {/* Objects List */}
            <div className="flex-1 overflow-y-auto p-3">
              <p className="text-xs font-medium text-muted-foreground mb-2">
                عناصر المشهد ({objects.length})
              </p>
              <div className="space-y-1">
                {objects.map((obj) => {
                  const Icon = ObjectIcons[obj.type];
                  return (
                    <div
                      key={obj.id}
                      className={cn(
                        "flex items-center gap-2 p-2 rounded-lg cursor-pointer transition-colors",
                        selectedObject === obj.id
                          ? "bg-brand/10 border border-brand/30"
                          : "hover:bg-muted"
                      )}
                      onClick={() => setSelectedObject(obj.id)}
                    >
                      <div
                        className="w-8 h-8 rounded-full flex items-center justify-center"
                        style={{ backgroundColor: obj.color }}
                      >
                        <Icon className="h-4 w-4 text-white" />
                      </div>
                      <div className="flex-1 min-w-0">
                        <p className="text-sm font-medium truncate">
                          {obj.name}
                        </p>
                        <p className="text-xs text-muted-foreground">
                          {obj.position.x.toFixed(0)},{" "}
                          {obj.position.y.toFixed(0)},{" "}
                          {obj.position.z.toFixed(0)}
                        </p>
                      </div>
                      <div className="flex gap-1">
                        <Button
                          variant="ghost"
                          size="icon"
                          className="h-6 w-6"
                          onClick={(e) => {
                            e.stopPropagation();
                            updateObject(obj.id, { visible: !obj.visible });
                          }}
                        >
                          {obj.visible ? (
                            <Eye className="h-3 w-3" />
                          ) : (
                            <EyeOff className="h-3 w-3" />
                          )}
                        </Button>
                        <Button
                          variant="ghost"
                          size="icon"
                          className="h-6 w-6 text-destructive hover:text-destructive"
                          onClick={(e) => {
                            e.stopPropagation();
                            deleteObject(obj.id);
                          }}
                        >
                          <Trash2 className="h-3 w-3" />
                        </Button>
                      </div>
                    </div>
                  );
                })}
              </div>
            </div>
          </div>

          {/* Main Viewport */}
          <div className="flex-1 flex flex-col">
            {/* Viewport Toolbar */}
            <div className="flex items-center justify-between p-2 border-b bg-muted/30">
              <div className="flex items-center gap-2">
                <Select
                  value={viewMode}
                  onValueChange={(v) => setViewMode(v as typeof viewMode)}
                >
                  <SelectTrigger className="w-32">
                    <SelectValue />
                  </SelectTrigger>
                  <SelectContent>
                    <SelectItem value="perspective">منظور</SelectItem>
                    <SelectItem value="top">من أعلى</SelectItem>
                    <SelectItem value="front">من الأمام</SelectItem>
                    <SelectItem value="side">من الجانب</SelectItem>
                  </SelectContent>
                </Select>

                <div className="h-6 w-px bg-border mx-1" />

                <Tooltip>
                  <TooltipTrigger asChild>
                    <Button
                      variant={showGrid ? "secondary" : "ghost"}
                      size="icon"
                      onClick={() => setShowGrid(!showGrid)}
                    >
                      <Grid3X3 className="h-4 w-4" />
                    </Button>
                  </TooltipTrigger>
                  <TooltipContent>الشبكة</TooltipContent>
                </Tooltip>

                <Tooltip>
                  <TooltipTrigger asChild>
                    <Button
                      variant={showLightPreview ? "secondary" : "ghost"}
                      size="icon"
                      onClick={() => setShowLightPreview(!showLightPreview)}
                    >
                      <Lightbulb className="h-4 w-4" />
                    </Button>
                  </TooltipTrigger>
                  <TooltipContent>معاينة الإضاءة</TooltipContent>
                </Tooltip>
              </div>

              <div className="flex items-center gap-2">
                {/* Time of Day */}
                <div className="flex items-center gap-1 bg-muted rounded-lg p-1">
                  <Button
                    variant={timeOfDay === "day" ? "secondary" : "ghost"}
                    size="icon"
                    className="h-7 w-7"
                    onClick={() => setTimeOfDay("day")}
                  >
                    <Sun className="h-4 w-4" />
                  </Button>
                  <Button
                    variant={timeOfDay === "sunset" ? "secondary" : "ghost"}
                    size="icon"
                    className="h-7 w-7"
                    onClick={() => setTimeOfDay("sunset")}
                  >
                    <Sparkles className="h-4 w-4" />
                  </Button>
                  <Button
                    variant={timeOfDay === "night" ? "secondary" : "ghost"}
                    size="icon"
                    className="h-7 w-7"
                    onClick={() => setTimeOfDay("night")}
                  >
                    <Moon className="h-4 w-4" />
                  </Button>
                </div>

                <div className="h-6 w-px bg-border mx-1" />

                {/* Zoom Controls */}
                <Button
                  variant="ghost"
                  size="icon"
                  onClick={() => setZoom(Math.max(0.25, zoom - 0.25))}
                >
                  <ZoomOut className="h-4 w-4" />
                </Button>
                <span className="text-xs font-mono w-12 text-center">
                  {Math.round(zoom * 100)}%
                </span>
                <Button
                  variant="ghost"
                  size="icon"
                  onClick={() => setZoom(Math.min(4, zoom + 0.25))}
                >
                  <ZoomIn className="h-4 w-4" />
                </Button>
                <Button
                  variant="ghost"
                  size="icon"
                  onClick={() => {
                    setZoom(1);
                    setViewOffset({ x: 0, y: 0 });
                  }}
                >
                  <Maximize2 className="h-4 w-4" />
                </Button>
              </div>
            </div>

            {/* 3D Viewport */}
            <div
              ref={canvasRef}
              className={cn(
                "flex-1 relative overflow-hidden",
                `bg-gradient-to-br ${getTimeOfDayStyle()}`
              )}
              onMouseDown={(e) => {
                if (e.button === 1 || e.shiftKey) {
                  setIsDragging(true);
                  setDragStart({
                    x: e.clientX - viewOffset.x,
                    y: e.clientY - viewOffset.y,
                  });
                }
              }}
              onMouseMove={(e) => {
                if (isDragging) {
                  setViewOffset({
                    x: e.clientX - dragStart.x,
                    y: e.clientY - dragStart.y,
                  });
                }
              }}
              onMouseUp={() => setIsDragging(false)}
              onMouseLeave={() => setIsDragging(false)}
            >
              {/* Grid */}
              {showGrid && (
                <svg className="absolute inset-0 w-full h-full pointer-events-none opacity-20">
                  <defs>
                    <pattern
                      id="grid"
                      width={CELL_SIZE * zoom}
                      height={CELL_SIZE * zoom}
                      patternUnits="userSpaceOnUse"
                      patternTransform={`translate(${viewOffset.x % (CELL_SIZE * zoom)} ${viewOffset.y % (CELL_SIZE * zoom)})`}
                    >
                      <path
                        d={`M ${CELL_SIZE * zoom} 0 L 0 0 0 ${CELL_SIZE * zoom}`}
                        fill="none"
                        stroke="currentColor"
                        strokeWidth="1"
                      />
                    </pattern>
                  </defs>
                  <rect width="100%" height="100%" fill="url(#grid)" />
                </svg>
              )}

              {/* Center crosshair */}
              <div className="absolute inset-0 flex items-center justify-center pointer-events-none">
                <div className="w-8 h-px bg-muted-foreground/30" />
              </div>
              <div className="absolute inset-0 flex items-center justify-center pointer-events-none">
                <div className="w-px h-8 bg-muted-foreground/30" />
              </div>

              {/* Objects */}
              {objects
                .filter((o) => o.visible)
                .map((obj) => {
                  const { x, y, scale } = getObjectViewportPosition(
                    obj.position
                  );
                  const Icon = ObjectIcons[obj.type];
                  const isSelected = selectedObject === obj.id;
                  const size = 40 * scale * obj.scale;

                  return (
                    <div
                      key={obj.id}
                      className={cn(
                        "absolute cursor-pointer transition-all duration-200",
                        isSelected && "z-10"
                      )}
                      style={{
                        left: `calc(50% + ${x}px)`,
                        top: `calc(50% + ${y}px)`,
                        transform: "translate(-50%, -50%)",
                      }}
                      onClick={() => setSelectedObject(obj.id)}
                    >
                      {/* Light glow effect */}
                      {obj.type === "light" && showLightPreview && (
                        <div
                          className="absolute inset-0 rounded-full blur-2xl opacity-50"
                          style={{
                            backgroundColor: obj.color,
                            width: size * 4,
                            height: size * 4,
                            left: -(size * 1.5),
                            top: -(size * 1.5),
                          }}
                        />
                      )}

                      <div
                        className={cn(
                          "rounded-full flex items-center justify-center shadow-lg transition-all",
                          isSelected &&
                            "ring-2 ring-brand ring-offset-2 ring-offset-background"
                        )}
                        style={{
                          width: size,
                          height: size,
                          backgroundColor: obj.color,
                        }}
                      >
                        <Icon
                          className="text-white"
                          style={{ width: size * 0.5, height: size * 0.5 }}
                        />
                      </div>

                      {/* Name label */}
                      <div className="absolute -bottom-6 left-1/2 -translate-x-1/2 whitespace-nowrap text-xs font-medium bg-card/80 backdrop-blur-sm px-2 py-0.5 rounded">
                        {obj.name}
                      </div>
                    </div>
                  );
                })}

              {/* Camera preview frustum */}
              {tool === "camera" && (
                <div
                  className="absolute border-2 border-brand/50 border-dashed bg-brand/5"
                  style={{
                    left: `calc(50% + ${viewOffset.x}px - 100px)`,
                    top: `calc(50% + ${viewOffset.y}px - 75px)`,
                    width: 200 * zoom,
                    height: 150 * zoom,
                    transform: `perspective(500px) rotateX(${camera.rotation.pitch}deg)`,
                  }}
                >
                  <div className="absolute top-2 right-2">
                    <Badge variant="secondary" className="text-xs">
                      {camera.focalLength}mm
                    </Badge>
                  </div>
                </div>
              )}

              {/* View Mode Label */}
              <div className="absolute top-4 left-4">
                <Badge
                  variant="outline"
                  className="bg-card/80 backdrop-blur-sm"
                >
                  {viewMode === "perspective"
                    ? "منظور"
                    : viewMode === "top"
                      ? "من أعلى"
                      : viewMode === "front"
                        ? "من الأمام"
                        : "من الجانب"}
                </Badge>
              </div>
            </div>

            {/* Timeline */}
            <div className="h-32 border-t bg-card/50">
              <div className="flex items-center justify-between p-2 border-b">
                <div className="flex items-center gap-2">
                  <Button
                    variant="ghost"
                    size="icon"
                    onClick={() => setIsPlaying(!isPlaying)}
                  >
                    {isPlaying ? (
                      <Pause className="h-4 w-4" />
                    ) : (
                      <Play className="h-4 w-4" />
                    )}
                  </Button>
                  <Button variant="ghost" size="icon">
                    <SkipForward className="h-4 w-4" />
                  </Button>
                  <span className="text-sm font-mono">
                    {currentTime.toFixed(1)}s
                  </span>
                </div>

                <Button variant="outline" size="sm" onClick={addShot}>
                  <Plus className="h-4 w-4 ml-2" />
                  إضافة لقطة
                </Button>
              </div>

              <div className="flex gap-2 p-2 overflow-x-auto">
                {shots.map((shot) => (
                  <Card
                    key={shot.id}
                    className={cn(
                      "min-w-32 cursor-pointer transition-all",
                      selectedShot === shot.id && "ring-2 ring-brand"
                    )}
                    onClick={() => goToShot(shot)}
                  >
                    <CardContent className="p-3">
                      <div className="flex items-center gap-2 mb-2">
                        <Camera className="h-4 w-4 text-brand" />
                        <span className="text-sm font-medium">
                          {shot.label}
                        </span>
                      </div>
                      <div className="text-xs text-muted-foreground">
                        {shot.camera.focalLength}mm | {shot.time}s
                      </div>
                    </CardContent>
                  </Card>
                ))}

                {shots.length === 0 && (
                  <div className="flex items-center justify-center w-full text-sm text-muted-foreground">
                    أضف لقطات لبناء تسلسل المشهد
                  </div>
                )}
              </div>
            </div>
          </div>

          {/* Right Sidebar - Properties */}
          <div className="w-72 border-r bg-card/50 overflow-y-auto">
            {/* Camera Properties */}
            <div className="p-4 border-b">
              <h3 className="font-medium flex items-center gap-2 mb-4">
                <Video className="h-4 w-4 text-brand" />
                إعدادات الكاميرا
              </h3>

              {/* Camera Presets */}
              <div className="mb-4">
                <p className="text-xs text-muted-foreground mb-2">
                  قوالب جاهزة
                </p>
                <Select
                  onValueChange={(v) => {
                    const preset = CAMERA_PRESETS[parseInt(v)];
                    if (preset) applyCameraPreset(preset);
                  }}
                >
                  <SelectTrigger>
                    <SelectValue placeholder="اختر قالب..." />
                  </SelectTrigger>
                  <SelectContent>
                    {CAMERA_PRESETS.map((preset, idx) => (
                      <SelectItem key={idx} value={idx.toString()}>
                        {preset.name} ({preset.focalLength}mm)
                      </SelectItem>
                    ))}
                  </SelectContent>
                </Select>
              </div>

              {/* Focal Length */}
              <div className="space-y-2 mb-4">
                <div className="flex items-center justify-between">
                  <label className="text-sm">البعد البؤري</label>
                  <span className="text-sm font-mono">
                    {camera.focalLength}mm
                  </span>
                </div>
                <Slider
                  value={[camera.focalLength]}
                  min={14}
                  max={200}
                  step={1}
                  onValueChange={([v]) => {
                    if (v === undefined) return;
                    setCamera((prev) => ({ ...prev, focalLength: v }));
                  }}
                />
              </div>

              {/* Aperture */}
              <div className="space-y-2 mb-4">
                <div className="flex items-center justify-between">
                  <label className="text-sm">فتحة العدسة</label>
                  <span className="text-sm font-mono">f/{camera.aperture}</span>
                </div>
                <Slider
                  value={[camera.aperture]}
                  min={1.4}
                  max={22}
                  step={0.1}
                  onValueChange={([v]) => {
                    if (v === undefined) return;
                    setCamera((prev) => ({ ...prev, aperture: v }));
                  }}
                />
              </div>

              {/* Camera Position */}
              <div className="space-y-2">
                <p className="text-xs text-muted-foreground">موقع الكاميرا</p>
                <div className="grid grid-cols-3 gap-2">
                  {(["x", "y", "z"] as const).map((axis) => (
                    <div key={axis} className="space-y-1">
                      <label className="text-xs text-muted-foreground uppercase">
                        {axis}
                      </label>
                      <input
                        type="number"
                        value={camera.position[axis]}
                        onChange={(e) =>
                          setCamera((prev) => ({
                            ...prev,
                            position: {
                              ...prev.position,
                              [axis]: parseFloat(e.target.value) || 0,
                            },
                          }))
                        }
                        className="w-full px-2 py-1 text-sm border rounded-md bg-background"
                      />
                    </div>
                  ))}
                </div>
              </div>
            </div>

            {/* Selected Object Properties */}
            {selectedObject && (
              <div className="p-4">
                <h3 className="font-medium flex items-center gap-2 mb-4">
                  <Settings2 className="h-4 w-4 text-brand" />
                  خصائص العنصر
                </h3>

                {(() => {
                  const obj = objects.find((o) => o.id === selectedObject);
                  if (!obj) return null;

                  return (
                    <div className="space-y-4">
                      {/* Name */}
                      <div className="space-y-1">
                        <label className="text-xs text-muted-foreground">
                          الاسم
                        </label>
                        <input
                          type="text"
                          value={obj.name}
                          onChange={(e) =>
                            updateObject(obj.id, { name: e.target.value })
                          }
                          className="w-full px-2 py-1 text-sm border rounded-md bg-background"
                          dir="rtl"
                        />
                      </div>

                      {/* Position */}
                      <div className="space-y-2">
                        <p className="text-xs text-muted-foreground">الموقع</p>
                        <div className="grid grid-cols-3 gap-2">
                          {(["x", "y", "z"] as const).map((axis) => (
                            <div key={axis} className="space-y-1">
                              <label className="text-xs text-muted-foreground uppercase">
                                {axis}
                              </label>
                              <input
                                type="number"
                                value={obj.position[axis]}
                                onChange={(e) =>
                                  updateObject(obj.id, {
                                    position: {
                                      ...obj.position,
                                      [axis]: parseFloat(e.target.value) || 0,
                                    },
                                  })
                                }
                                className="w-full px-2 py-1 text-sm border rounded-md bg-background"
                              />
                            </div>
                          ))}
                        </div>
                      </div>

                      {/* Scale */}
                      <div className="space-y-2">
                        <div className="flex items-center justify-between">
                          <label className="text-sm">الحجم</label>
                          <span className="text-sm font-mono">
                            {obj.scale.toFixed(1)}x
                          </span>
                        </div>
                        <Slider
                          value={[obj.scale]}
                          min={0.5}
                          max={3}
                          step={0.1}
                          onValueChange={([v]) => {
                            if (v === undefined) return;
                            updateObject(obj.id, { scale: v });
                          }}
                        />
                      </div>

                      {/* Color */}
                      <div className="space-y-1">
                        <label className="text-xs text-muted-foreground">
                          اللون
                        </label>
                        <div className="flex gap-2">
                          {[
                            "oklch(0.7 0.15 200)",
                            "oklch(0.6 0.15 30)",
                            "oklch(0.7 0.15 140)",
                            "oklch(0.65 0.15 280)",
                            "oklch(0.8 0.15 80)",
                          ].map((color) => (
                            <button
                              key={color}
                              className={cn(
                                "w-8 h-8 rounded-full transition-all",
                                obj.color === color &&
                                  "ring-2 ring-brand ring-offset-2"
                              )}
                              style={{ backgroundColor: color }}
                              onClick={() => updateObject(obj.id, { color })}
                            />
                          ))}
                        </div>
                      </div>
                    </div>
                  );
                })()}
              </div>
            )}
          </div>
        </div>
      </div>
    </TooltipProvider>
  );
}

export default SpatialScenePlanner;

"use client";

import {
  Target,
  TrendingUp,
  TrendingDown,
  AlertTriangle,
  CheckCircle,
  Lightbulb,
  Shield,
  Zap,
  BarChart3,
  FileText,
  Download,
  Star,
  ArrowUp,
} from "lucide-react";
import * as React from "react";

import { Badge } from "@/components/ui/badge";
import { Button } from "@/components/ui/button";
import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";
import { Progress } from "@/components/ui/progress";
import { TooltipProvider } from "@/components/ui/tooltip";
import { cn } from "@/lib/utils";

/**
 * SWOT Analysis Component for Breakdown
 * Strengths, Weaknesses, Opportunities, Threats visualization
 *
 * Features:
 * - Visual SWOT matrix
 * - Score indicators
 * - Interactive items
 * - Priority highlighting
 * - Export functionality
 */

interface SWOTItem {
  id: string;
  text: string;
  priority: "high" | "medium" | "low";
  impact: number; // 1-10
  details?: string;
}

interface SWOTData {
  strengths: SWOTItem[];
  weaknesses: SWOTItem[];
  opportunities: SWOTItem[];
  threats: SWOTItem[];
  overallScore: {
    narrative: number;
    structure: number;
    characters: number;
    conflict: number;
    total: number;
    rating: string;
  };
  summary?: string;
}

interface SWOTAnalysisProps {
  data: SWOTData;
  title?: string;
  className?: string;
  onItemClick?: (
    item: SWOTItem,
    category: keyof Omit<SWOTData, "overallScore" | "summary">
  ) => void;
}

// Category configurations
const CATEGORIES = {
  strengths: {
    title: "نقاط القوة",
    titleEn: "Strengths",
    icon: CheckCircle,
    color: "text-green-500",
    bgColor: "bg-green-500/10",
    borderColor: "border-green-500/30",
    gradientFrom: "from-green-500/20",
    gradientTo: "to-emerald-500/5",
  },
  weaknesses: {
    title: "نقاط الضعف",
    titleEn: "Weaknesses",
    icon: AlertTriangle,
    color: "text-red-500",
    bgColor: "bg-red-500/10",
    borderColor: "border-red-500/30",
    gradientFrom: "from-red-500/20",
    gradientTo: "to-rose-500/5",
  },
  opportunities: {
    title: "الفرص",
    titleEn: "Opportunities",
    icon: Lightbulb,
    color: "text-blue-500",
    bgColor: "bg-blue-500/10",
    borderColor: "border-blue-500/30",
    gradientFrom: "from-blue-500/20",
    gradientTo: "to-cyan-500/5",
  },
  threats: {
    title: "التهديدات",
    titleEn: "Threats",
    icon: Shield,
    color: "text-amber-500",
    bgColor: "bg-amber-500/10",
    borderColor: "border-amber-500/30",
    gradientFrom: "from-amber-500/20",
    gradientTo: "to-orange-500/5",
  },
};

// Get priority badge style
const getPriorityStyle = (priority: SWOTItem["priority"]) => {
  switch (priority) {
    case "high":
      return "bg-red-500/20 text-red-400 border-red-500/30";
    case "medium":
      return "bg-amber-500/20 text-amber-400 border-amber-500/30";
    case "low":
      return "bg-green-500/20 text-green-400 border-green-500/30";
  }
};

// Get score color
const getScoreColor = (score: number) => {
  if (score >= 80) return "text-green-500";
  if (score >= 60) return "text-blue-500";
  if (score >= 40) return "text-amber-500";
  return "text-red-500";
};

// Get rating emoji
const getRatingEmoji = (rating: string) => {
  if (rating.includes("ممتاز")) return "🌟";
  if (rating.includes("جيد جداً")) return "⭐";
  if (rating.includes("جيد")) return "👍";
  if (rating.includes("مقبول")) return "📝";
  return "⚠️";
};

export function SWOTAnalysis({
  data,
  title = "تحليل SWOT",
  className,
  onItemClick,
}: SWOTAnalysisProps) {
  const [expandedItem, setExpandedItem] = React.useState<string | null>(null);
  const [hoveredCategory, setHoveredCategory] = React.useState<string | null>(
    null
  );

  // Calculate category scores
  const getCategoryScore = (items: SWOTItem[]) => {
    if (items.length === 0) return 0;
    const totalImpact = items.reduce((sum, item) => sum + item.impact, 0);
    return Math.round((totalImpact / (items.length * 10)) * 100);
  };

  // Render SWOT item
  const renderItem = (item: SWOTItem, category: keyof typeof CATEGORIES) => {
    const isExpanded = expandedItem === item.id;
    const config = CATEGORIES[category];

    return (
      <div
        key={item.id}
        className={cn(
          "p-3 rounded-lg border transition-all cursor-pointer",
          config.borderColor,
          isExpanded ? config.bgColor : "hover:bg-muted/50",
          item.priority === "high" &&
            "ring-1 ring-offset-1 ring-offset-background",
          item.priority === "high" &&
            config.borderColor.replace("border-", "ring-")
        )}
        onClick={() => {
          setExpandedItem(isExpanded ? null : item.id);
          onItemClick?.(item, category);
        }}
      >
        <div className="flex items-start justify-between gap-2">
          <div className="flex-1">
            <div className="flex items-center gap-2 mb-1">
              {item.priority === "high" && (
                <ArrowUp className="h-3 w-3 text-red-500" />
              )}
              <p className="text-sm font-medium">{item.text}</p>
            </div>
            {isExpanded && item.details && (
              <p className="text-xs text-muted-foreground mt-2 animate-in fade-in">
                {item.details}
              </p>
            )}
          </div>
          <div className="flex items-center gap-2">
            <Badge
              variant="outline"
              className={cn("text-xs", getPriorityStyle(item.priority))}
            >
              {item.priority === "high"
                ? "عالي"
                : item.priority === "medium"
                  ? "متوسط"
                  : "منخفض"}
            </Badge>
            <div className="flex items-center gap-1 text-xs text-muted-foreground">
              <Zap className="h-3 w-3" />
              {item.impact}
            </div>
          </div>
        </div>
      </div>
    );
  };

  // Render category card
  const renderCategory = (
    category: keyof typeof CATEGORIES,
    items: SWOTItem[]
  ) => {
    const config = CATEGORIES[category];
    const Icon = config.icon;
    const score = getCategoryScore(items);
    const isHovered = hoveredCategory === category;

    return (
      <Card
        className={cn(
          "overflow-hidden transition-all duration-300",
          isHovered && "shadow-lg scale-[1.02]"
        )}
        onMouseEnter={() => setHoveredCategory(category)}
        onMouseLeave={() => setHoveredCategory(null)}
      >
        <div className={cn("h-1", config.bgColor)} />
        <CardHeader className="pb-3">
          <div className="flex items-center justify-between">
            <CardTitle className="text-base flex items-center gap-2">
              <div className={cn("p-2 rounded-lg", config.bgColor)}>
                <Icon className={cn("h-4 w-4", config.color)} />
              </div>
              <div>
                <span className={config.color}>{config.title}</span>
                <span className="text-xs text-muted-foreground block">
                  {config.titleEn}
                </span>
              </div>
            </CardTitle>
            <div className="flex items-center gap-2">
              <Badge variant="secondary">{items.length}</Badge>
              <div className="text-sm font-bold text-muted-foreground">
                {score}%
              </div>
            </div>
          </div>
        </CardHeader>
        <CardContent className="space-y-2 max-h-80 overflow-y-auto">
          {items.length === 0 ? (
            <p className="text-sm text-muted-foreground text-center py-4">
              لا توجد عناصر
            </p>
          ) : (
            items.map((item) => renderItem(item, category))
          )}
        </CardContent>
      </Card>
    );
  };

  return (
    <TooltipProvider>
      <div className={cn("swot-analysis space-y-6", className)}>
        {/* Header */}
        <div className="flex items-center justify-between">
          <div>
            <h2 className="text-2xl font-bold flex items-center gap-2">
              <BarChart3 className="h-6 w-6 text-brand" />
              {title}
            </h2>
            <p className="text-sm text-muted-foreground">
              تحليل نقاط القوة والضعف والفرص والتهديدات
            </p>
          </div>
          <Button variant="outline" size="sm">
            <Download className="h-4 w-4 ml-2" />
            تصدير
          </Button>
        </div>

        {/* Overall Score */}
        <Card className="bg-gradient-to-br from-brand/5 to-purple-500/5 border-brand/20">
          <CardContent className="p-6">
            <div className="grid grid-cols-2 md:grid-cols-6 gap-6">
              {/* Total Score */}
              <div className="col-span-2 md:col-span-2 flex flex-col items-center justify-center">
                <div className="relative">
                  <svg className="w-32 h-32" viewBox="0 0 100 100">
                    <circle
                      cx="50"
                      cy="50"
                      r="45"
                      fill="none"
                      stroke="currentColor"
                      strokeWidth="8"
                      className="text-muted/20"
                    />
                    <circle
                      cx="50"
                      cy="50"
                      r="45"
                      fill="none"
                      stroke="currentColor"
                      strokeWidth="8"
                      strokeLinecap="round"
                      strokeDasharray={`${data.overallScore.total * 2.83} 283`}
                      transform="rotate(-90 50 50)"
                      className={getScoreColor(data.overallScore.total)}
                    />
                  </svg>
                  <div className="absolute inset-0 flex flex-col items-center justify-center">
                    <span
                      className={cn(
                        "text-3xl font-bold",
                        getScoreColor(data.overallScore.total)
                      )}
                    >
                      {data.overallScore.total}
                    </span>
                    <span className="text-xs text-muted-foreground">
                      من 100
                    </span>
                  </div>
                </div>
                <div className="mt-3 text-center">
                  <Badge className="text-lg px-4 py-1">
                    {getRatingEmoji(data.overallScore.rating)}{" "}
                    {data.overallScore.rating}
                  </Badge>
                </div>
              </div>

              {/* Individual Scores */}
              <div className="col-span-2 md:col-span-4 grid grid-cols-2 gap-4">
                {[
                  {
                    label: "جودة السرد",
                    score: data.overallScore.narrative,
                    icon: FileText,
                  },
                  {
                    label: "السلامة الهيكلية",
                    score: data.overallScore.structure,
                    icon: Target,
                  },
                  {
                    label: "تطوير الشخصيات",
                    score: data.overallScore.characters,
                    icon: Star,
                  },
                  {
                    label: "فعالية الصراع",
                    score: data.overallScore.conflict,
                    icon: Zap,
                  },
                ].map((item) => (
                  <div key={item.label} className="space-y-2">
                    <div className="flex items-center justify-between text-sm">
                      <span className="flex items-center gap-2 text-muted-foreground">
                        <item.icon className="h-4 w-4" />
                        {item.label}
                      </span>
                      <span
                        className={cn("font-bold", getScoreColor(item.score))}
                      >
                        {item.score}
                      </span>
                    </div>
                    <Progress value={item.score} className="h-2" />
                  </div>
                ))}
              </div>
            </div>

            {/* Summary */}
            {data.summary && (
              <div className="mt-6 pt-6 border-t">
                <h3 className="font-medium mb-2 flex items-center gap-2">
                  <FileText className="h-4 w-4 text-brand" />
                  الملخص التنفيذي
                </h3>
                <p className="text-sm text-muted-foreground leading-relaxed">
                  {data.summary}
                </p>
              </div>
            )}
          </CardContent>
        </Card>

        {/* SWOT Matrix */}
        <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
          {/* Internal Factors */}
          <div className="space-y-4">
            <div className="flex items-center gap-2 text-sm text-muted-foreground">
              <TrendingUp className="h-4 w-4" />
              العوامل الداخلية
            </div>
            {renderCategory("strengths", data.strengths)}
            {renderCategory("weaknesses", data.weaknesses)}
          </div>

          {/* External Factors */}
          <div className="space-y-4">
            <div className="flex items-center gap-2 text-sm text-muted-foreground">
              <TrendingDown className="h-4 w-4" />
              العوامل الخارجية
            </div>
            {renderCategory("opportunities", data.opportunities)}
            {renderCategory("threats", data.threats)}
          </div>
        </div>

        {/* Quick Stats */}
        <div className="grid grid-cols-2 md:grid-cols-4 gap-4">
          {(Object.keys(CATEGORIES) as (keyof typeof CATEGORIES)[]).map(
            (key) => {
              const config = CATEGORIES[key];
              const items = data[key];
              const highPriority = items.filter(
                (i) => i.priority === "high"
              ).length;
              const Icon = config.icon;

              return (
                <Card key={key} className={cn("border", config.borderColor)}>
                  <CardContent className="p-4">
                    <div className="flex items-center justify-between">
                      <div>
                        <p className="text-xs text-muted-foreground">
                          {config.title}
                        </p>
                        <p className="text-2xl font-bold">{items.length}</p>
                      </div>
                      <div className={cn("p-3 rounded-full", config.bgColor)}>
                        <Icon className={cn("h-5 w-5", config.color)} />
                      </div>
                    </div>
                    {highPriority > 0 && (
                      <div className="mt-2 flex items-center gap-1 text-xs text-red-500">
                        <ArrowUp className="h-3 w-3" />
                        {highPriority} أولوية عالية
                      </div>
                    )}
                  </CardContent>
                </Card>
              );
            }
          )}
        </div>
      </div>
    </TooltipProvider>
  );
}

export default SWOTAnalysis;

"use client";

import {
  Palette,
  Type,
  Layout,
  Moon,
  Sun,
  Monitor,
  Check,
  RotateCcw,
  Download,
  Upload,
  Sparkles,
} from "lucide-react";
import * as React from "react";

import {
  Dialog,
  DialogContent,
  DialogHeader,
  DialogTitle,
} from "@/components/ui/dialog";
import { Label } from "@/components/ui/label";
import { Slider } from "@/components/ui/slider";
import { Tabs, TabsList, TabsTrigger, TabsContent } from "@/components/ui/tabs";
import { cn } from "@/lib/utils";

/**
 * Enhanced Theme Customizer Component
 * Based on UI_DESIGN_SUGGESTIONS.md
 *
 * Features:
 * - Live color picker with OKLCH support
 * - Font family selection
 * - Spacing adjustments
 * - Dark/Light mode toggle
 * - Export/Import themes
 * - AI-powered color palette suggestions
 * - Real-time preview
 */

interface ThemeConfig {
  colors: {
    primary: string;
    secondary: string;
    accent: string;
    background: string;
    foreground: string;
  };
  typography: {
    fontFamily: string;
    scale: number;
  };
  spacing: {
    scale: number;
  };
  mode: "light" | "dark" | "system";
}

interface ThemeCustomizerProps {
  open?: boolean;
  onOpenChange?: (open: boolean) => void;
  onThemeChange?: (theme: ThemeConfig) => void;
}

const fontFamilies = [
  { name: "Cairo", value: "'Cairo', sans-serif", preview: "القاهرة" },
  {
    name: "Noto Kufi Arabic",
    value: "'Noto Kufi Arabic', sans-serif",
    preview: "نوتو كوفي",
  },
  {
    name: "Noto Sans Arabic",
    value: "'Noto Sans Arabic', sans-serif",
    preview: "نوتو سانس",
  },
  {
    name: "IBM Plex Mono Arabic",
    value: "'IBM Plex Mono Arabic', monospace",
    preview: "آي بي إم",
  },
];

const colorPresets = [
  {
    name: "الافتراضي",
    colors: {
      primary: "oklch(0.205 0 0)",
      secondary: "oklch(0.97 0 0)",
      accent: "oklch(0.646 0.222 41.116)",
      background: "oklch(1 0 0)",
      foreground: "oklch(0.145 0 0)",
    },
  },
  {
    name: "إبداعي",
    colors: {
      primary: "oklch(0.7 0.15 330)",
      secondary: "oklch(0.85 0.1 340)",
      accent: "oklch(0.65 0.2 320)",
      background: "oklch(0.98 0.01 330)",
      foreground: "oklch(0.2 0.05 330)",
    },
  },
  {
    name: "تقني",
    colors: {
      primary: "oklch(0.65 0.18 220)",
      secondary: "oklch(0.85 0.1 230)",
      accent: "oklch(0.6 0.2 210)",
      background: "oklch(0.98 0.01 220)",
      foreground: "oklch(0.2 0.05 220)",
    },
  },
  {
    name: "طبيعي",
    colors: {
      primary: "oklch(0.7 0.15 140)",
      secondary: "oklch(0.85 0.1 150)",
      accent: "oklch(0.65 0.18 130)",
      background: "oklch(0.98 0.01 140)",
      foreground: "oklch(0.2 0.05 140)",
    },
  },
];

export function ThemeCustomizerEnhanced({
  open = false,
  onOpenChange,
  onThemeChange,
}: ThemeCustomizerProps) {
  const [isOpen, setIsOpen] = React.useState(open);

  const defaultColorPreset = colorPresets[0];
  const defaultFontFamily = fontFamilies[0];

  if (!defaultColorPreset || !defaultFontFamily) {
    throw new Error("Default presets not found");
  }

  const [theme, setTheme] = React.useState<ThemeConfig>({
    colors: defaultColorPreset.colors,
    typography: {
      fontFamily: defaultFontFamily.value,
      scale: 1.25,
    },
    spacing: {
      scale: 1,
    },
    mode: "system",
  });

  React.useEffect(() => {
    setIsOpen(open);
  }, [open]);

  const handleOpenChange = (newOpen: boolean) => {
    setIsOpen(newOpen);
    onOpenChange?.(newOpen);
  };

  const updateTheme = (updates: Partial<ThemeConfig>) => {
    const newTheme = { ...theme, ...updates };
    setTheme(newTheme);
    onThemeChange?.(newTheme);
  };

  const applyColorPreset = (preset: (typeof colorPresets)[0]) => {
    updateTheme({
      colors: preset.colors,
    });
  };

  const resetTheme = () => {
    const defaultColorPreset = colorPresets[0];
    const defaultFontFamily = fontFamilies[0];

    if (!defaultColorPreset || !defaultFontFamily) {
      return;
    }

    const defaultTheme: ThemeConfig = {
      colors: defaultColorPreset.colors,
      typography: {
        fontFamily: defaultFontFamily.value,
        scale: 1.25,
      },
      spacing: {
        scale: 1,
      },
      mode: "system",
    };
    setTheme(defaultTheme);
    onThemeChange?.(defaultTheme);
  };

  const exportTheme = () => {
    const json = JSON.stringify(theme, null, 2);
    const blob = new Blob([json], { type: "application/json" });
    const url = URL.createObjectURL(blob);
    const a = document.createElement("a");
    a.href = url;
    a.download = "theme-config.json";
    a.click();
    URL.revokeObjectURL(url);
  };

  const importTheme = (event: React.ChangeEvent<HTMLInputElement>) => {
    const file = event.target.files?.[0];
    if (!file) return;

    const reader = new FileReader();
    reader.onload = (e) => {
      try {
        const result = e.target?.result;
        if (typeof result === "string") {
          const imported = JSON.parse(result);
          setTheme(imported);
          onThemeChange?.(imported);
        }
      } catch (error) {
        void error;
      }
    };
    reader.readAsText(file);
  };

  return (
    <Dialog open={isOpen} onOpenChange={handleOpenChange}>
      <DialogContent
        className="max-w-4xl max-h-[90vh] overflow-y-auto"
        dir="rtl"
      >
        <DialogHeader>
          <DialogTitle className="flex items-center gap-2">
            <Palette className="h-5 w-5" />
            مخصص الثيم
          </DialogTitle>
        </DialogHeader>

        <Tabs defaultValue="colors" className="mt-4">
          <TabsList className="grid w-full grid-cols-4">
            <TabsTrigger value="colors" className="gap-2">
              <Palette className="h-4 w-4" />
              الألوان
            </TabsTrigger>
            <TabsTrigger value="typography" className="gap-2">
              <Type className="h-4 w-4" />
              الخطوط
            </TabsTrigger>
            <TabsTrigger value="spacing" className="gap-2">
              <Layout className="h-4 w-4" />
              المسافات
            </TabsTrigger>
            <TabsTrigger value="mode" className="gap-2">
              <Monitor className="h-4 w-4" />
              الوضع
            </TabsTrigger>
          </TabsList>

          {/* Colors Tab */}
