"use client";

import {
  Palette,
  Sun,
  Moon,
  Monitor,
  Check,
  RotateCcw,
  Sparkles,
} from "lucide-react";
import * as React from "react";

import { Button } from "@/components/ui/button";
import { Label } from "@/components/ui/label";
import {
  Sheet,
  SheetContent,
  SheetHeader,
  SheetTitle,
  SheetTrigger,
} from "@/components/ui/sheet";
import { Slider } from "@/components/ui/slider";
import { Switch } from "@/components/ui/switch";
import { cn } from "@/lib/utils";

/**
 * Theme Customizer Component
 * Based on UI_DESIGN_SUGGESTIONS.md
 *
 * Features:
 * - Theme mode selection (light/dark/system)
 * - Brand color customization
 * - Radius customization
 * - Font size adjustment
 * - Live preview
 * - Preset themes
 */

type ThemeMode = "light" | "dark" | "system";

interface ThemeConfig {
  mode: ThemeMode;
  brandHue: number;
  brandChroma: number;
  radius: number;
  fontSize: number;
  reduceMotion: boolean;
}

const defaultConfig: ThemeConfig = {
  mode: "system",
  brandHue: 41,
  brandChroma: 0.222,
  radius: 10,
  fontSize: 16,
  reduceMotion: false,
};

const presetThemes = [
  { name: "البرتقالي", nameEn: "Orange", hue: 41, chroma: 0.222 },
  { name: "الأزرق", nameEn: "Blue", hue: 220, chroma: 0.18 },
  { name: "الأخضر", nameEn: "Green", hue: 140, chroma: 0.15 },
  { name: "البنفسجي", nameEn: "Purple", hue: 280, chroma: 0.2 },
  { name: "الوردي", nameEn: "Pink", hue: 330, chroma: 0.15 },
  { name: "الأحمر", nameEn: "Red", hue: 25, chroma: 0.2 },
];

export function ThemeCustomizer() {
  const [config, setConfig] = React.useState<ThemeConfig>(defaultConfig);
  const [isOpen, setIsOpen] = React.useState(false);

  // Load saved config
  React.useEffect(() => {
    const saved = localStorage.getItem("theme-config");
    if (saved) {
      const parsed = JSON.parse(saved);
      setConfig(parsed);
      applyTheme(parsed);
    }
  }, []);

  // Apply theme changes
  const applyTheme = React.useCallback((newConfig: ThemeConfig) => {
    const root = document.documentElement;

    // Apply mode
    if (newConfig.mode === "dark") {
      root.classList.add("dark");
    } else if (newConfig.mode === "light") {
      root.classList.remove("dark");
    } else {
      // System preference
      const prefersDark = window.matchMedia(
        "(prefers-color-scheme: dark)"
      ).matches;
      root.classList.toggle("dark", prefersDark);
    }

    // Apply brand color
    const brandColor = `oklch(0.646 ${newConfig.brandChroma} ${newConfig.brandHue})`;
    root.style.setProperty("--brand", brandColor);

    // Apply radius
    root.style.setProperty("--radius", `${newConfig.radius / 16}rem`);
    root.style.setProperty("--radius-lg", `${(newConfig.radius + 6) / 16}rem`);
    root.style.setProperty("--radius-xl", `${(newConfig.radius + 14) / 16}rem`);

    // Apply font size
    root.style.setProperty("--text-base", `${newConfig.fontSize / 16}rem`);

    // Apply reduce motion
    if (newConfig.reduceMotion) {
      root.style.setProperty("--duration-fast", "0ms");
      root.style.setProperty("--duration-normal", "0ms");
      root.style.setProperty("--duration-slow", "0ms");
    } else {
      root.style.setProperty("--duration-fast", "150ms");
      root.style.setProperty("--duration-normal", "300ms");
      root.style.setProperty("--duration-slow", "500ms");
    }

    // Save to localStorage
    localStorage.setItem("theme-config", JSON.stringify(newConfig));
  }, []);

  // Update config and apply
  const updateConfig = (updates: Partial<ThemeConfig>) => {
    const newConfig = { ...config, ...updates };
    setConfig(newConfig);
    applyTheme(newConfig);
  };

  // Reset to defaults
  const resetToDefaults = () => {
    setConfig(defaultConfig);
    applyTheme(defaultConfig);
  };

  // Listen for system theme changes
  React.useEffect(() => {
    if (config.mode !== "system") return;

    const mediaQuery = window.matchMedia("(prefers-color-scheme: dark)");
    const handleChange = () => applyTheme(config);

    mediaQuery.addEventListener("change", handleChange);
    return () => mediaQuery.removeEventListener("change", handleChange);
  }, [config, applyTheme]);

  return (
    <Sheet open={isOpen} onOpenChange={setIsOpen}>
      <SheetTrigger asChild>
        <Button
          variant="ghost"
          size="icon"
          className="fixed bottom-6 left-6 z-50 w-12 h-12 rounded-full shadow-lg bg-brand text-brand-foreground hover:bg-brand/90"
        >
          <Palette className="w-5 h-5" />
          <span className="sr-only">تخصيص الثيم</span>
        </Button>
      </SheetTrigger>

      <SheetContent side="left" className="w-80 sm:w-96" dir="rtl">
        <SheetHeader>
          <SheetTitle className="flex items-center gap-2 text-right">
            <Sparkles className="w-5 h-5 text-brand" />
            تخصيص المظهر
          </SheetTitle>
        </SheetHeader>

        <div className="mt-6 space-y-6">
          {/* Theme Mode */}
          <div className="space-y-3">
            <Label className="text-sm font-medium">وضع الثيم</Label>
            <div className="grid grid-cols-3 gap-2">
              {[
                { mode: "light" as ThemeMode, icon: Sun, label: "فاتح" },
                { mode: "dark" as ThemeMode, icon: Moon, label: "داكن" },
                { mode: "system" as ThemeMode, icon: Monitor, label: "النظام" },
              ].map(({ mode, icon: Icon, label }) => (
                <button
                  key={mode}
                  onClick={() => updateConfig({ mode })}
                  className={cn(
                    "flex flex-col items-center gap-2 p-3 rounded-lg border-2 transition-all",
                    config.mode === mode
                      ? "border-brand bg-brand/10"
                      : "border-border hover:border-brand/50"
                  )}
                >
                  <Icon className="w-5 h-5" />
                  <span className="text-xs font-medium">{label}</span>
                  {config.mode === mode && (
                    <Check className="w-4 h-4 text-brand absolute top-2 left-2" />
                  )}
                </button>
              ))}
            </div>
          </div>

          {/* Brand Color Presets */}
          <div className="space-y-3">
            <Label className="text-sm font-medium">لون العلامة التجارية</Label>
            <div className="grid grid-cols-6 gap-2">
              {presetThemes.map((preset) => (
                <button
                  key={preset.nameEn}
                  onClick={() =>
                    updateConfig({
                      brandHue: preset.hue,
                      brandChroma: preset.chroma,
                    })
                  }
                  className={cn(
                    "w-10 h-10 rounded-full border-2 transition-transform hover:scale-110",
                    config.brandHue === preset.hue
                      ? "border-foreground scale-110"
                      : "border-transparent"
                  )}
                  style={{
                    background: `oklch(0.646 ${preset.chroma} ${preset.hue})`,
                  }}
                  title={preset.name}
                >
                  {config.brandHue === preset.hue && (
                    <Check className="w-4 h-4 text-white mx-auto" />
                  )}
                </button>
              ))}
            </div>
          </div>

          {/* Brand Hue Slider */}
          <div className="space-y-3">
            <div className="flex items-center justify-between">
              <Label className="text-sm font-medium">درجة اللون</Label>
              <span className="text-xs text-muted-foreground">
                {config.brandHue}°
              </span>
            </div>
            <Slider
              value={[config.brandHue]}
              onValueChange={([value]) => {
                if (value === undefined) return;
                updateConfig({ brandHue: value });
              }}
              min={0}
              max={360}
              step={1}
              className="w-full"
            />
            <div
              className="h-4 rounded-full"
              style={{
                background: `linear-gradient(to left,
                  oklch(0.646 0.2 0),
                  oklch(0.646 0.2 60),
                  oklch(0.646 0.2 120),
                  oklch(0.646 0.2 180),
                  oklch(0.646 0.2 240),
                  oklch(0.646 0.2 300),
                  oklch(0.646 0.2 360)
                )`,
              }}
            />
          </div>

          {/* Radius */}
          <div className="space-y-3">
            <div className="flex items-center justify-between">
              <Label className="text-sm font-medium">حدة الزوايا</Label>
              <span className="text-xs text-muted-foreground">
                {config.radius}px
              </span>
            </div>
            <Slider
              value={[config.radius]}
              onValueChange={([value]) => {
                if (value === undefined) return;
                updateConfig({ radius: value });
              }}
              min={0}
              max={24}
              step={2}
              className="w-full"
            />
            <div className="flex gap-2">
              <div
                className="flex-1 h-10 bg-muted"
                style={{ borderRadius: `${config.radius}px` }}
              />
              <div
                className="flex-1 h-10 bg-brand"
                style={{ borderRadius: `${config.radius}px` }}
              />
            </div>
          </div>

          {/* Font Size */}
          <div className="space-y-3">
            <div className="flex items-center justify-between">
              <Label className="text-sm font-medium">حجم الخط</Label>
              <span className="text-xs text-muted-foreground">
                {config.fontSize}px
              </span>
            </div>
            <Slider
              value={[config.fontSize]}
              onValueChange={([value]) => {
                if (value === undefined) return;
                updateConfig({ fontSize: value });
              }}
              min={12}
              max={20}
              step={1}
              className="w-full"
            />
          </div>

          {/* Reduce Motion */}
          <div className="flex items-center justify-between">
            <div className="space-y-0.5">
              <Label className="text-sm font-medium">تقليل الحركة</Label>
              <p className="text-xs text-muted-foreground">
                إيقاف الحركات والانتقالات
              </p>
            </div>
            <Switch
              checked={config.reduceMotion}
              onCheckedChange={(checked) =>
                updateConfig({ reduceMotion: checked })
              }
            />
          </div>

          {/* Preview Card */}
          <div className="p-4 bg-card border border-border rounded-lg space-y-3">
            <div className="font-medium">معاينة</div>
            <div className="flex gap-2">
              <Button size="sm">زر أساسي</Button>
              <Button size="sm" variant="outline">
                زر ثانوي
              </Button>
            </div>
            <p className="text-sm text-muted-foreground">
              هذا نص تجريبي لمعاينة حجم الخط والألوان
            </p>
          </div>

          {/* Reset Button */}
          <Button
            variant="outline"
            className="w-full"
            onClick={resetToDefaults}
          >
            <RotateCcw className="w-4 h-4 ml-2" />
            إعادة التعيين للافتراضي
          </Button>
        </div>
      </SheetContent>
    </Sheet>
  );
}

export default ThemeCustomizer;

"use client";

import { motion, AnimatePresence } from "framer-motion";
import {
  Search,
  Mic,
  Image as ImageIcon,
  X,
  Clock,
  Sparkles,
  FileText,
  Video,
  Users,
  Folder,
  ArrowRight,
  Loader2,
  type LucideIcon,
} from "lucide-react";
import * as React from "react";

import { Dialog, DialogContent } from "@/components/ui/dialog";
import { Tabs, TabsList, TabsTrigger } from "@/components/ui/tabs";
import { cn } from "@/lib/utils";

/**
 * Universal Search Component
 * Based on UI_DESIGN_SUGGESTIONS.md
 *
 * Features:
 * - Text, voice, and image search
 * - AI-powered suggestions
 * - Recent searches
 * - Categorized results
 * - Keyboard navigation
 * - Fuzzy search
 */

export type SearchCategory =
  | "all"
  | "projects"
  | "scenes"
  | "characters"
  | "scripts"
  | "media";

export interface SearchResult {
  id: string;
  title: string;
  description?: string;
  category: SearchCategory;
  icon?: LucideIcon;
  url?: string;
  metadata?: {
    date?: string;
    author?: string;
    tags?: string[];
  };
  onClick?: () => void;
}

export interface UniversalSearchProps {
  open?: boolean;
  onOpenChange?: (open: boolean) => void;
  onSearch?: (
    query: string,
    category: SearchCategory
  ) => Promise<SearchResult[]>;
  placeholder?: string;
  recentSearches?: string[];
  onRecentSearchClick?: (query: string) => void;
}

const categoryIcons: Record<SearchCategory, LucideIcon> = {
  all: Search,
  projects: Folder,
  scenes: Video,
  characters: Users,
  scripts: FileText,
  media: ImageIcon,
};

const categoryLabels: Record<SearchCategory, string> = {
  all: "الكل",
  projects: "المشاريع",
  scenes: "المشاهد",
  characters: "الشخصيات",
  scripts: "النصوص",
  media: "الوسائط",
};

export function UniversalSearch({
  open = false,
  onOpenChange,
  onSearch,
  placeholder = "ابحث عن أي شيء...",
  recentSearches = [],
  onRecentSearchClick,
}: UniversalSearchProps) {
  const [isOpen, setIsOpen] = React.useState(open);
  const [query, setQuery] = React.useState("");
  const [category, setCategory] = React.useState<SearchCategory>("all");
  const [results, setResults] = React.useState<SearchResult[]>([]);
  const [isSearching, setIsSearching] = React.useState(false);
  const [selectedIndex, setSelectedIndex] = React.useState(0);
  const [isVoiceActive, setIsVoiceActive] = React.useState(false);
  const inputRef = React.useRef<HTMLInputElement>(null);

  React.useEffect(() => {
    setIsOpen(open);
  }, [open]);

  const handleOpenChange = (newOpen: boolean) => {
    setIsOpen(newOpen);
    onOpenChange?.(newOpen);
    if (!newOpen) {
      setQuery("");
      setResults([]);
      setSelectedIndex(0);
    }
  };

  // Keyboard shortcuts
  React.useEffect(() => {
    const handleKeyDown = (e: KeyboardEvent) => {
      if ((e.metaKey || e.ctrlKey) && e.key === "k") {
        e.preventDefault();
        handleOpenChange(!isOpen);
      }
    };

    window.addEventListener("keydown", handleKeyDown);
    return () => window.removeEventListener("keydown", handleKeyDown);
  }, [isOpen]);

  // Search with debounce
  React.useEffect(() => {
    if (!query.trim() || !onSearch) {
      setResults([]);
      return;
    }

    const timer = setTimeout(async () => {
      setIsSearching(true);
      try {
        const searchResults = await onSearch(query, category);
        setResults(searchResults);
      } catch (error) {
        void error;
        setResults([]);
      } finally {
        setIsSearching(false);
      }
    }, 300);

    return () => clearTimeout(timer);
  }, [query, category, onSearch]);

  // Keyboard navigation
  const handleKeyDown = (e: React.KeyboardEvent) => {
    if (e.key === "ArrowDown") {
      e.preventDefault();
      setSelectedIndex((prev) => Math.min(prev + 1, results.length - 1));
    } else if (e.key === "ArrowUp") {
      e.preventDefault();
      setSelectedIndex((prev) => Math.max(prev - 1, 0));
    } else if (e.key === "Enter" && results[selectedIndex]) {
      e.preventDefault();
      results[selectedIndex].onClick?.();
      handleOpenChange(false);
    }
  };

  // Voice search (placeholder - requires Web Speech API)
  const handleVoiceSearch = () => {
    setIsVoiceActive(true);
    // Implement voice search using Web Speech API
    setTimeout(() => setIsVoiceActive(false), 2000);
  };

  return (
    <Dialog open={isOpen} onOpenChange={handleOpenChange}>
      <DialogContent className="max-w-3xl p-0 gap-0 overflow-hidden" dir="rtl">
        <div className="flex flex-col h-[600px]">
          {/* Search Header */}
          <div className="border-b bg-gradient-to-r from-background to-muted/20 p-4">
            <div className="flex items-center gap-3">
              <Search className="h-5 w-5 text-muted-foreground flex-shrink-0" />

              <input
                ref={inputRef}
                type="text"
                value={query}
                onChange={(e) => setQuery(e.target.value)}
                onKeyDown={handleKeyDown}
                placeholder={placeholder}
                className="flex-1 bg-transparent border-none outline-none text-lg placeholder:text-muted-foreground"
                autoFocus
              />

              {/* Voice Search */}
              <button
                onClick={handleVoiceSearch}
                className={cn(
                  "p-2 rounded-md hover:bg-accent transition-colors",
                  isVoiceActive && "bg-accent-creative text-white animate-pulse"
                )}
                aria-label="البحث الصوتي"
              >
                <Mic className="h-4 w-4" />
              </button>

              {/* Image Search */}
              <button
                className="p-2 rounded-md hover:bg-accent transition-colors"
                aria-label="البحث بالصورة"
              >
                <ImageIcon className="h-4 w-4" />
              </button>

              {/* Clear */}
              {query && (
                <button
                  onClick={() => setQuery("")}
                  className="p-2 rounded-md hover:bg-accent transition-colors"
                  aria-label="مسح"
                >
                  <X className="h-4 w-4" />
                </button>
              )}
            </div>

            {/* Category Tabs */}
            <Tabs
              value={category}
              onValueChange={(v) => setCategory(v as SearchCategory)}
              className="mt-4"
            >
              <TabsList className="w-full justify-start">
                {Object.entries(categoryLabels).map(([key, label]) => {
                  const Icon = categoryIcons[key as SearchCategory];
                  return (
                    <TabsTrigger key={key} value={key} className="gap-2">
                      <Icon className="h-4 w-4" />
                      {label}
                    </TabsTrigger>
                  );
                })}
              </TabsList>
            </Tabs>
          </div>

          {/* Results Area */}
          <div className="flex-1 overflow-y-auto p-4">
            {isSearching ? (
              <div className="flex items-center justify-center h-full">
                <Loader2 className="h-8 w-8 animate-spin text-muted-foreground" />
              </div>
            ) : query && results.length === 0 ? (
              <div className="flex flex-col items-center justify-center h-full text-center">
                <Search className="h-12 w-12 text-muted-foreground mb-4" />
                <p className="text-lg font-medium">لا توجد نتائج</p>
                <p className="text-sm text-muted-foreground mt-1">
                  جرب كلمات بحث مختلفة
                </p>
              </div>
            ) : query && results.length > 0 ? (
              <div className="space-y-2">
                <AnimatePresence mode="popLayout">
                  {results.map((result, index) => (
                    <SearchResultItem
                      key={result.id}
                      result={result}
                      isSelected={index === selectedIndex}
                      onClick={() => {
                        result.onClick?.();
                        handleOpenChange(false);
                      }}
                    />
                  ))}
                </AnimatePresence>
              </div>
            ) : (
              <div className="space-y-6">
                {/* Recent Searches */}
                {recentSearches.length > 0 && (
                  <div>
                    <div className="flex items-center gap-2 mb-3">
                      <Clock className="h-4 w-4 text-muted-foreground" />
                      <h3 className="text-sm font-medium text-muted-foreground">
                        عمليات البحث الأخيرة
                      </h3>
                    </div>
                    <div className="space-y-1">
                      {recentSearches.map((search, index) => (
                        <button
                          key={index}
                          onClick={() => {
                            setQuery(search);
                            onRecentSearchClick?.(search);
                          }}
                          className="w-full text-right px-3 py-2 rounded-md hover:bg-accent transition-colors text-sm"
                        >
                          {search}
                        </button>
                      ))}
                    </div>
                  </div>
                )}

                {/* AI Suggestions */}
                <div>
                  <div className="flex items-center gap-2 mb-3">
                    <Sparkles className="h-4 w-4 text-accent-creative" />
                    <h3 className="text-sm font-medium text-muted-foreground">
                      اقتراحات ذكية
                    </h3>
                  </div>
                  <div className="grid grid-cols-2 gap-2">
                    {[
                      "مشاهد الحركة",
                      "شخصيات رئيسية",
                      "حوارات درامية",
                      "مواقع تصوير",
                    ].map((suggestion) => (
                      <button
                        key={suggestion}
                        onClick={() => setQuery(suggestion)}
                        className="px-4 py-3 rounded-lg border bg-gradient-to-br from-accent/50 to-transparent hover:from-accent hover:to-accent/50 transition-all text-sm font-medium text-right"
                      >
                        {suggestion}
                      </button>
                    ))}
                  </div>
                </div>
              </div>
            )}
          </div>

          {/* Footer with shortcuts */}
          <div className="border-t p-3 bg-muted/20">
            <div className="flex items-center justify-between text-xs text-muted-foreground">
              <div className="flex items-center gap-4">
                <span className="flex items-center gap-1">
                  <kbd className="px-2 py-1 rounded bg-background border">
                    ↑↓
                  </kbd>
                  للتنقل
                </span>
                <span className="flex items-center gap-1">
                  <kbd className="px-2 py-1 rounded bg-background border">
                    Enter
                  </kbd>
                  للفتح
                </span>
                <span className="flex items-center gap-1">
                  <kbd className="px-2 py-1 rounded bg-background border">
                    Esc
                  </kbd>
                  للإغلاق
                </span>
              </div>
              <span>مدعوم بالذكاء الاصطناعي</span>
            </div>
          </div>
        </div>
      </DialogContent>
    </Dialog>
  );
}

