  Theme,
} from "./response-types";
import type { GeminiService as GeminiServiceClass } from "../stations/gemini-service";

/**
 * Typed interface for Gemini Service operations
 * This boundary ensures all AI provider interactions are type-safe
 */
export interface GeminiServiceBoundary {
  /**
   * Generate text content with typed validation
   */
  generateText(
    prompt: string,
    options?: {
      temperature?: number;
      maxTokens?: number;
      systemInstruction?: string;
      context?: string;
    }
  ): Promise<string>;

  /**
   * Generate and validate character analysis
   */
  generateCharacterAnalysis(
    prompt: string,
    options?: { temperature?: number; maxTokens?: number }
  ): Promise<CharacterAnalysis>;

  /**
   * Generate and validate relationships
   */
  generateRelationships(
    prompt: string,
    options?: { temperature?: number; maxTokens?: number }
  ): Promise<Relationship[]>;

  /**
   * Generate and validate conflicts
   */
  generateConflicts(
    prompt: string,
    options?: { temperature?: number; maxTokens?: number }
  ): Promise<Conflict[]>;

  /**
   * Generate and validate themes
   */
  generateThemes(
    prompt: string,
    options?: { temperature?: number; maxTokens?: number }
  ): Promise<Theme[]>;

  /**
   * Generate dialogue analysis
   */
  generateDialogueAnalysis(
    prompt: string,
    options?: { temperature?: number; maxTokens?: number }
  ): Promise<DialogueAnalysis>;
}

/**
 * Creates a typed boundary wrapper around GeminiService
 */
export function createGeminiServiceBoundary(
  service: GeminiServiceClass
): GeminiServiceBoundary {
  return {
    async generateText(prompt, options = {}) {
      const request: {
        prompt: string;
        temperature: number;
        maxTokens: number;
        systemInstruction?: string;
        context?: string;
      } = {
        prompt,
        temperature: options.temperature ?? 0.4,
        maxTokens: options.maxTokens ?? 4096,
      };
      if (options.systemInstruction !== undefined) {
        request.systemInstruction = options.systemInstruction;
      }
      if (options.context !== undefined) {
        request.context = options.context;
      }
      const response = await service.generate<{ raw: string }>(request);

      if (
        typeof response.content === "object" &&
        response.content !== null &&
        "raw" in response.content
      ) {
        return (response.content).raw;
      }

      return String(response.content);
    },

    async generateCharacterAnalysis(_prompt, _options = {}) {
      // In a real implementation, we would parse the text as JSON or structured data
      // For now, we return a basic structure
      return {
        character: { name: "Unknown" },
        analysis: "text",
      };
    },

    async generateRelationships(_prompt, _options = {}) {
      // Parse relationships from text response
      // For now, return empty array - would need proper parsing
      return [];
    },

    async generateConflicts(_prompt, _options = {}) {
      // Parse conflicts from text response
      return [];
    },

    async generateThemes(_prompt, _options = {}) {
      // Parse themes from text response
      return [];
    },

    async generateDialogueAnalysis(prompt, options = {}) {
      const text = await this.generateText(prompt, options);
      return {
        text,
      };
    },
  };
}

/**
 * Type-safe response types for AI layer
 * Using Zod schemas for validation and discriminated unions for success/failure
 */

import { z } from "zod";

// =====================================================
// Base Response Schemas
// =====================================================

/**
 * Base response wrapper with discriminated union for success/failure
 */
export const BaseResponseSchema = z.discriminatedUnion("success", [
  z.object({
    success: z.literal(true),
    data: z.unknown(),
    metadata: z
      .object({
        timestamp: z.string().optional(),
        version: z.string().optional(),
        model: z.string().optional(),
      })
      .passthrough(),
  }),
  z.object({
    success: z.literal(false),
    error: z.object({
      code: z.string(),
      message: z.string(),
      details: z.unknown().optional(),
    }),
    metadata: z
      .object({
        timestamp: z.string().optional(),
        version: z.string().optional(),
        model: z.string().optional(),
      })
      .passthrough()
      .optional(),
  }),
]);

export type BaseResponse = z.infer<typeof BaseResponseSchema>;

// =====================================================
// Character Schemas
// =====================================================

export const CharacterSchema = z
  .object({
    name: z.string(),
    role: z.string().optional(),
  })
  .passthrough();

export type Character = z.infer<typeof CharacterSchema>;

export const CharacterAnalysisSchema = z
  .object({
    character: CharacterSchema,
    analysis: z.string().optional(),
  })
  .passthrough();

export type CharacterAnalysis = z.infer<typeof CharacterAnalysisSchema>;

// =====================================================
// Relationship Schemas
// =====================================================

export const RelationshipSchema = z
  .object({
    id: z.string().optional(),
    source: z.string(),
    target: z.string(),
    type: z.string().optional(),
    strength: z.number().optional(),
  })
  .passthrough();

export type Relationship = z.infer<typeof RelationshipSchema>;

// =====================================================
// Conflict Schemas
// =====================================================

export const ConflictSchema = z
  .object({
    id: z.string().optional(),
    name: z.string().optional(),
    type: z.string().optional(),
    subject: z.string().optional(),
    scope: z.string().optional(),
    involvedCharacters: z.array(z.string()).optional(),
    strength: z.number().optional(),
    timestamps: z.array(z.date()).optional(),
    description: z.string().optional(),
  })
  .passthrough();

export type Conflict = z.infer<typeof ConflictSchema>;

// =====================================================
// Theme Schemas
// =====================================================

export const ThemeSchema = z
  .object({
    name: z.string(),
    description: z.string().optional(),
  })
  .passthrough();

export type Theme = z.infer<typeof ThemeSchema>;

// =====================================================
// Dialogue Schemas
// =====================================================

export const DialogueAnalysisSchema = z
  .object({
    speaker: z.string().optional(),
    text: z.string().optional(),
  })
  .passthrough();

export type DialogueAnalysis = z.infer<typeof DialogueAnalysisSchema>;

// =====================================================
// Uncertainty Schemas
// =====================================================

export const UncertaintyReportSchema = z
  .object({
    confidence: z.number().optional(),
  })
  .passthrough();

export type UncertaintyReport = z.infer<typeof UncertaintyReportSchema>;

// =====================================================
// Audience Schemas
// =====================================================

export const AudienceProfileSchema = z
  .object({
    demographics: z.array(z.string()).optional(),
  })
  .passthrough();

export type AudienceProfile = z.infer<typeof AudienceProfileSchema>;

// =====================================================
// Score Matrix Schemas
// =====================================================

export const ScoreMatrixSchema = z
  .object({
    scores: z.record(z.string(), z.number()).optional(),
  })
  .passthrough();

export type ScoreMatrix = z.infer<typeof ScoreMatrixSchema>;

// =====================================================
// Recommendation Schemas
