// frontend/src/lib/ai/rag/context-retriever.ts

import { GeminiService } from "../stations/gemini-service";
import { logger } from "../utils/logger";

import { TextChunk, ContextMap } from "./text-chunking";

export interface RetrievalOptions {
  maxChunks?: number;
  minRelevanceScore?: number;
  includeMetadata?: boolean;
}

export interface RetrievalResult {
  chunks: TextChunk[];
  context: string;
  relevanceScores: Map<string, number>;
  metadata: {
    totalChunks: number;
    query: string;
    retrievalTime: number;
  };
}

export class ContextRetriever {
  private geminiService: GeminiService;

  constructor(geminiService: GeminiService) {
    this.geminiService = geminiService;
  }

  private async generateText(
    prompt: string,
    options: { temperature?: number; maxTokens?: number }
  ): Promise<string> {
    const request = {
      prompt,
      ...(options.temperature !== undefined
        ? { temperature: options.temperature }
        : {}),
      ...(options.maxTokens !== undefined
        ? { maxTokens: options.maxTokens }
        : {}),
    };
    const response = await this.geminiService.generate<{ raw: string }>(
      request
    );

    if (
      typeof response.content === "object" &&
      response.content !== null &&
      "raw" in response.content
    ) {
      return response.content.raw;
    }

    return String(response.content);
  }

  /**
   * بناء خريطة سياق محسنة
   */
  async buildContextMap(chunks: TextChunk[]): Promise<ContextMap> {
    const contextMap: ContextMap = {
      chunks: new Map(),
      entities: new Map(),
      themes: new Map(),
      relationships: new Map(),
    };

    // إنشاء ملخصات محسنة للأجزاء باستخدام Gemini
    for (const chunk of chunks) {
      const summary = await this.generateChunkSummary(chunk.content);
      contextMap.chunks.set(chunk.id, summary);

      // استخراج الكيانات والمواضيع باستخدام Gemini
      const entities = await this.extractEntities(chunk.content);
      for (const entity of entities) {
        const count = contextMap.entities.get(entity) ?? 0;
        contextMap.entities.set(entity, count + 1);
      }

      const themes = await this.extractThemes(chunk.content);
      for (const theme of themes) {
        const count = contextMap.themes.get(theme) ?? 0;
        contextMap.themes.set(theme, count + 1);
      }
    }

    // استخراج العلاقات بين الكيانات
    contextMap.relationships = await this.extractRelationships(chunks);

    return contextMap;
  }

  /**
   * استرجاع الأجزاء ذات الصلة بناءً على استعلام
   */
  async retrieveRelevantChunks(
    query: string,
    chunks: TextChunk[],
    contextMap: ContextMap,
    options: RetrievalOptions = {}
  ): Promise<RetrievalResult> {
    const startTime = Date.now();
    const maxChunks = options.maxChunks ?? 5;
    const minRelevanceScore = options.minRelevanceScore ?? 0.3;

    // حساب درجات الصلة لكل جزء
    const relevanceScores = new Map<string, number>();

    for (const chunk of chunks) {
      const score = await this.calculateRelevanceScore(
        query,
        chunk,
        contextMap
      );
      relevanceScores.set(chunk.id, score);
    }

    // ترتيب الأجزاء حسب درجة الصلة
    const sortedChunks = chunks
      .filter(
        (chunk) => (relevanceScores.get(chunk.id) ?? 0) >= minRelevanceScore
      )
      .sort(
        (a, b) =>
          (relevanceScores.get(b.id) ?? 0) - (relevanceScores.get(a.id) ?? 0)
      )
      .slice(0, maxChunks);

    // بناء السياق من الأجزاء ذات الصلة
    const context = sortedChunks.map((chunk) => chunk.content).join("\n\n");

    return {
      chunks: sortedChunks,
      context,
      relevanceScores,
      metadata: {
        totalChunks: sortedChunks.length,
        query,
        retrievalTime: Date.now() - startTime,
      },
    };
  }

  /**
   * إنشاء ملخص للجزء باستخدام Gemini
   */
  private async generateChunkSummary(content: string): Promise<string> {
    const prompt = `
لخص النص التالي في جملة واحدة أو جملتين قصيرتين:
 ${content.substring(0, 1000)}
`;

    try {
      const summary = await this.generateText(prompt, {
        temperature: 0.2,
        maxTokens: 150,
      });

      return summary.trim();
    } catch (error) {
      logger.error("Error generating chunk summary:", error);
      // fallback: أول 100 حرف
      return content.substring(0, 100);
    }
  }

  /**
   * استخراج الكيانات باستخدام Gemini
   */
  private async extractEntities(content: string): Promise<string[]> {
    const prompt = `
استخرج أسماء الشخصيات والأماكن والمؤسسات المذكورة في النص التالي:
 ${content.substring(0, 1000)}

قدم الأسماء كقائمة مفصولة بفواصل:
`;

    try {
      const result = await this.generateText(prompt, {
        temperature: 0.1,
        maxTokens: 300,
      });

      return result
        .split(",")
        .map((entity: string) => entity.trim())
        .filter((entity: string) => entity.length > 0);
    } catch (error) {
      logger.error("Error extracting entities:", error);
      // fallback: استخراج بسيط يعتمد على الأحرف الكبيرة
      const words = content.split(/\s+/);
      return words
        .filter(
          (word) =>
            word.length > 2 && word[0] === word[0]?.toUpperCase()
        )
        .slice(0, 10); // تحديد العدد لتجنب القوائم الطويلة
    }
  }

  /**
   * استخراج المواضيع باستخدام Gemini
   */
  private async extractThemes(content: string): Promise<string[]> {
    const prompt = `
استخرج المواضيع والأفكار الرئيسية في النص التالي:
 ${content.substring(0, 1000)}

قدم المواضيع كقائمة مفصولة بفواصل:
`;

    try {
      const result = await this.generateText(prompt, {
        temperature: 0.2,
        maxTokens: 300,
      });

      return result
        .split(",")
        .map((theme: string) => theme.trim())
        .filter((theme: string) => theme.length > 0);
    } catch (error) {
      logger.error("Error extracting themes:", error);
      return [];
    }
  }

  /**
   * استخراج العلاقات بين الكيانات
   */
  private async extractRelationships(
    chunks: TextChunk[]
  ): Promise<Map<string, string[]>> {
    const relationships = new Map<string, string[]>();

    // للتبسيط، نستخرج العلاقات بناءً على ظهور الكيانات معاً في نفس الجزء
    for (const chunk of chunks) {
      const words = chunk.content.split(/\s+/);
      const entities = words
        .filter(
          (word) =>
            word.length > 2 && word[0] === word[0]?.toUpperCase()
        )
        .slice(0, 10); // تحديد العدد

      // إضافة علاقات بين كل زوج من الكيانات في نفس الجزء
      for (let i = 0; i < entities.length; i++) {
        for (let j = i + 1; j < entities.length; j++) {
          const entity1 = entities[i];
          const entity2 = entities[j];

          if (!entity1 || !entity2) continue;

          // إضافة entity2 إلى قائمة علاقات entity1
          if (!relationships.has(entity1)) {
            relationships.set(entity1, []);
          }
          const entity1Relations = relationships.get(entity1)!;
          if (!entity1Relations.includes(entity2)) {
            entity1Relations.push(entity2);
          }

          // إضافة entity1 إلى قائمة علاقات entity2
          if (!relationships.has(entity2)) {
            relationships.set(entity2, []);
          }
          const entity2Relations = relationships.get(entity2)!;
          if (!entity2Relations.includes(entity1)) {
            entity2Relations.push(entity1);
          }
        }
      }
    }

    return relationships;
  }

  /**
   * حساب درجة الصلة بين الاستعلام والجزء
   */
  private async calculateRelevanceScore(
    query: string,
    chunk: TextChunk,
    contextMap: ContextMap
  ): Promise<number> {
    // للتبسيط، نستخدم تشابه الكلمات المفتاحية
    const queryWords = query.toLowerCase().split(/\s+/);
    const chunkContent = chunk.content.toLowerCase();

    // حساب عدد الكلمات المتطابقة
    let matchCount = 0;
    for (const word of queryWords) {
      if (chunkContent.includes(word)) {
        matchCount++;
      }
    }

    // حساب درجة التشابه البسيطة
    const wordSimilarity = matchCount / queryWords.length;

    // حساب درجة الصلة بناءً على الكيانات
    let entityScore = 0;
    for (const [entity, count] of contextMap.entities.entries()) {
      if (query.toLowerCase().includes(entity.toLowerCase())) {
        entityScore += Math.min(count / 5, 1); // تحديد أقصى قيمة
      }
    }
    entityScore = Math.min(entityScore / queryWords.length, 1);

    // حساب درجة الصلة بناءً على المواضيع
    let themeScore = 0;
    for (const [theme, count] of contextMap.themes.entries()) {
      if (query.toLowerCase().includes(theme.toLowerCase())) {
        themeScore += Math.min(count / 3, 1); // تحديد أقصى قيمة
      }
    }
    themeScore = Math.min(themeScore / queryWords.length, 1);

    // دمج الدرجات بأوزان مختلفة
    const combinedScore =
      wordSimilarity * 0.5 + entityScore * 0.3 + themeScore * 0.2;

    return Math.min(combinedScore, 1);
  }
}

// Export singleton instance
let contextRetrieverInstance: ContextRetriever | null = null;

export function getContextRetriever(
  geminiService: GeminiService
): ContextRetriever {
  if (!contextRetrieverInstance) {
    contextRetrieverInstance = new ContextRetriever(geminiService);
  }
  return contextRetrieverInstance;
}

// frontend/src/lib/ai/rag/text-chunking.ts

export interface TextChunk {
  id: string;
  content: string;
  startIndex: number;
  endIndex: number;
  metadata?: {
    chapter?: string;
    scene?: string;
    characters?: string[];
    summary?: string;
  };
}

export interface ChunkingOptions {
  strategy: "sliding_window" | "semantic" | "fixed_size";
  chunkSize: number; // بالتوكنز
  overlap: number; // بالتوكنز
  minChunkSize?: number; // بالتوكنز
}

export interface ChunkingResult {
  chunks: TextChunk[];
  summary: string;
  contextMap: ContextMap;
  metadata: {
    totalChunks: number;
    averageChunkSize: number;
    strategy: string;
    originalLength: number;
  };
}

export interface ContextMap {
  chunks: Map<string, string>; // chunkId -> summary
  entities: Map<string, number>; // entity -> frequency
  themes: Map<string, number>; // theme -> frequency
  relationships: Map<string, string[]>; // entity -> related entities
}

export class TextChunker {
  /**
   * تقسيم النص إلى أجزاء
   */
  async chunkText(
    text: string,
    options: ChunkingOptions
  ): Promise<ChunkingResult> {
    switch (options.strategy) {
      case "sliding_window":
        return this.slidingWindowChunking(text, options);
      case "semantic":
        return this.semanticChunking(text, options);
      case "fixed_size":
        return this.fixedSizeChunking(text, options);
      default:
        return this.fixedSizeChunking(text, options);
    }
  }

  /**
   * تقسيم النص باستخدام نافذة منزلقة
   */
  private async slidingWindowChunking(
    text: string,
    options: ChunkingOptions
  ): Promise<ChunkingResult> {
    const chunks: TextChunk[] = [];
    const chunkSize = options.chunkSize * 4; // تحويل من توكن إلى أحرف (تقديري)
    const overlap = options.overlap * 4;

    let startIndex = 0;
    let chunkIndex = 0;

    while (startIndex < text.length) {
      const endIndex = Math.min(startIndex + chunkSize, text.length);
      const chunkContent = text.substring(startIndex, endIndex);

      // تجنب تقسيم الكلمات
      let adjustedEndIndex = endIndex;
      if (endIndex < text.length) {
        const lastSpaceIndex = chunkContent.lastIndexOf(" ");
        if (lastSpaceIndex > chunkSize * 0.8) {
          adjustedEndIndex = startIndex + lastSpaceIndex;
        }
      }

      const finalChunkContent = text.substring(startIndex, adjustedEndIndex);

      chunks.push({
        id: `chunk_${chunkIndex}`,
        content: finalChunkContent,
        startIndex,
        endIndex: adjustedEndIndex,
      });

      startIndex = adjustedEndIndex - overlap;
      chunkIndex++;
    }

    // إنشاء ملخص وسياق
    const summary = await this.generateSummary(chunks);
    const contextMap = await this.buildContextMap(chunks);

    return {
      chunks,
      summary,
      contextMap,
      metadata: {
        totalChunks: chunks.length,
        averageChunkSize:
          chunks.reduce((sum, chunk) => sum + chunk.content.length, 0) /
          chunks.length,
        strategy: "sliding_window",
        originalLength: text.length,
      },
    };
  }

  /**
   * تقسيم النص باستخدام تحليل دلالي
   */
  private async semanticChunking(
    text: string,
    options: ChunkingOptions
  ): Promise<ChunkingResult> {
    // للتبسيط، نستخدم تقسيماً يعتمد على الفقرات والمشاهد
    const paragraphs = text.split(/\n\s*\n/);
    const chunks: TextChunk[] = [];
    let currentChunk = "";
    let currentChunkStart = 0;
    let chunkIndex = 0;

    for (const paragraph of paragraphs) {
      // إذا كانت إضافة الفقرة الحالية تتجاوز حجم الجزء المحدد
      if (
        currentChunk.length + paragraph.length > options.chunkSize * 4 &&
        currentChunk.length > 0
      ) {
        // حفظ الجزء الحالي
        chunks.push({
          id: `chunk_${chunkIndex}`,
          content: currentChunk.trim(),
          startIndex: currentChunkStart,
          endIndex: currentChunkStart + currentChunk.length,
        });

        // بدء جزء جديد
        currentChunk = paragraph;
        currentChunkStart = currentChunkStart + currentChunk.length;
        chunkIndex++;
      } else {
        // إضافة الفقرة إلى الجزء الحالي
        if (currentChunk.length > 0) {
          currentChunk += "\n\n" + paragraph;
        } else {
          currentChunk = paragraph;
        }
      }
    }

    // إضافة الجزء الأخير إذا لم يكن فارغاً
    if (currentChunk.trim().length > 0) {
      chunks.push({
        id: `chunk_${chunkIndex}`,
        content: currentChunk.trim(),
        startIndex: currentChunkStart,
        endIndex: currentChunkStart + currentChunk.length,
      });
    }

    // إنشاء ملخص وسياق
    const summary = await this.generateSummary(chunks);
    const contextMap = await this.buildContextMap(chunks);

    return {
      chunks,
      summary,
      contextMap,
      metadata: {
        totalChunks: chunks.length,
        averageChunkSize:
          chunks.reduce((sum, chunk) => sum + chunk.content.length, 0) /
          chunks.length,
        strategy: "semantic",
        originalLength: text.length,
      },
    };
  }

  /**
   * تقسيم النص بأحجام ثابتة
   */
  private async fixedSizeChunking(
    text: string,
    options: ChunkingOptions
  ): Promise<ChunkingResult> {
    const chunks: TextChunk[] = [];
    const chunkSize = options.chunkSize * 4; // تحويل من توكن إلى أحرف (تقديري)

    for (let i = 0; i < text.length; i += chunkSize) {
      const endIndex = Math.min(i + chunkSize, text.length);
      const chunkContent = text.substring(i, endIndex);

      chunks.push({
        id: `chunk_${chunks.length}`,
        content: chunkContent,
        startIndex: i,
        endIndex,
      });
    }

    // إنشاء ملخص وسياق
    const summary = await this.generateSummary(chunks);
    const contextMap = await this.buildContextMap(chunks);

    return {
      chunks,
      summary,
      contextMap,
      metadata: {
        totalChunks: chunks.length,
        averageChunkSize: chunkSize,
        strategy: "fixed_size",
        originalLength: text.length,
      },
    };
  }

  /**
   * إنشاء ملخص للأجزاء
   */
  private async generateSummary(chunks: TextChunk[]): Promise<string> {
    // للتبسيط، نستخدم أول 500 حرف من كل جزء لإنشاء ملخص
    const excerpts = chunks
      .map((chunk) =>
        chunk.content.substring(0, Math.min(500, chunk.content.length))
      )
      .join("\n\n");

    // في تطبيق حقيقي، سيتم استخدام نموذج لغوي لإنشاء ملخص
    return excerpts.substring(0, 2000);
  }

  /**
   * بناء خريطة السياق
   */
  private async buildContextMap(chunks: TextChunk[]): Promise<ContextMap> {
    const contextMap: ContextMap = {
      chunks: new Map(),
      entities: new Map(),
      themes: new Map(),
      relationships: new Map(),
    };

    // إنشاء ملخصات بسيطة للأجزاء
    for (const chunk of chunks) {
      // للتبسيط، نستخدم أول 100 حرف كملخص
      const summary = chunk.content.substring(0, 100);
      contextMap.chunks.set(chunk.id, summary);

      // استخراج كيانات بسيطة (أسماء شخصيات تبدأ بحرف كبير)
      const words = chunk.content.split(/\s+/);
      for (const word of words) {
        if (word.length > 2 && word[0] === word[0]?.toUpperCase()) {
          const count = contextMap.entities.get(word) ?? 0;
          contextMap.entities.set(word, count + 1);
        }
      }
    }

    return contextMap;
  }

  /**
   * تقدير عدد التوكنز في النص
   */
  estimateTokens(text: string): number {
    // تقدير بسيط: 1 توكن ≈ 4 أحرف للغة العربية
    return Math.ceil(text.length / 4);
  }

  /**
   * تحديد ما إذا كان النص يحتاج إلى تقسيم
   */
  needsChunking(text: string, maxTokens = 30000): boolean {
    return this.estimateTokens(text) > maxTokens;
  }
}

// Export singleton instance
let textChunkerInstance: TextChunker | null = null;

export function getTextChunker(): TextChunker {
  if (!textChunkerInstance) {
    textChunkerInstance = new TextChunker();
  }
  return textChunkerInstance;
}

// frontend/src/lib/ai/stations/base-station.ts

import { checkConstitutionalCompliance } from "../constitutional/principles";
import { getUncertaintyQuantificationEngine } from "../constitutional/uncertainty-quantification";
import { StationMetadata } from "../core/models/base-entities";

import { GeminiService } from "./gemini-service";

// تعريف واجهة للخيارات الجديدة
export interface StationOptions {
  // خيارات Constitutional AI
  enableConstitutionalCheck?: boolean;

  // خيارات Uncertainty Quantification
  enableUncertaintyQuantification?: boolean;

  // خيارات RAG
  enableRAG?: boolean;

  // خيارات عامة
  temperature?: number;
  maxTokens?: number;
}

import type {
  PreviousResults,
  TextChunk,
  ContextMap,
  StationResult,
} from "../interfaces/response-types";

export interface StationInput {
  text: string;
  projectName?: string | undefined;
  options?: StationOptions | undefined;
  // يمكن إضافة المزيد من المدخلات حسب الحاجة
  previousResults?: PreviousResults | undefined;
  chunks?: TextChunk[] | undefined;
  contextMap?: ContextMap | undefined;
}

export interface StationOutput {
  // النتيجة الأساسية من المحطة
  result: StationResult;

  // البيانات الوصفية المحسنة
  metadata: StationMetadata & {
    // نتائج Constitutional AI
    constitutionalCheck?: {
      checked: boolean;
      compliant: boolean;
      violations: string[];
      improvementScore: number;
      correctedAnalysis?: string;
    };

    // نتائج Uncertainty Quantification
    uncertaintyQuantification?: {
      quantified: boolean;
      overallConfidence: number;
      uncertaintyType: "epistemic" | "aleatoric";
      sources: {
        aspect: string;
        reason: string;
        reducible: boolean;
      }[];
    };

    // معلومات RAG
    ragInfo?: {
      wasChunked: boolean;
      chunksCount: number;
      retrievalTime: number;
    };
  };
}

export abstract class BaseStation {
  protected geminiService: GeminiService;
  protected stationName: string;
  protected stationNumber: number;

  constructor(
    geminiService: GeminiService,
    stationName: string,
    stationNumber: number
  ) {
    this.geminiService = geminiService;
    this.stationName = stationName;
    this.stationNumber = stationNumber;
  }

  /**
   * نقطة الدخول الرئيسية لتشغيل المحطة
   */
  async run(input: StationInput): Promise<StationOutput> {
    const startTime = Date.now();
    const options = this.mergeWithDefaultOptions(input.options);

    try {
      // 1. تنفيذ منطق المحطة الأساسي
      let result = await this.execute(input, options);

      // 2. تطبيق Constitutional AI إذا كان مفعلاً
      if (options.enableConstitutionalCheck) {
        result = await this.applyConstitutionalCheck(result, input.text);
      }

      // 3. تطبيق Uncertainty Quantification إذا كان مفعلاً
      if (options.enableUncertaintyQuantification) {
        result = await this.applyUncertaintyQuantification(result, input);
      }

      // 4. إنشاء البيانات الوصفية النهائية
      const metadata = await this.createMetadata(startTime, options, input);

      return {
        result,
        metadata,
      };
    } catch (error) {
      // SECURITY FIX: Pass stationName as separate argument to prevent format string injection
      console.error("Error in station:", this.stationName, error);

      // إرجاع نتيجة خطأ مع البيانات الوصفية المناسبة
      return {
        result: null,
        metadata: {
          stationName: this.stationName,
          stationNumber: this.stationNumber,
          status: "Failed",
          error: (error as Error).message,
          executionTime: Date.now() - startTime,
          agentsUsed: [],
          tokensUsed: 0,
        },
      };
    }
  }

  /**
   * دالة مجردة يجب على كل محطة تطبيقها
   */
  protected abstract execute(
    input: StationInput,
    options: StationOptions
  ): Promise<StationResult>;

  /**
   * دمج الخيارات المدخلة مع الخيارات الافتراضية
   */
  private mergeWithDefaultOptions(options?: StationOptions): StationOptions {
    return {
      enableConstitutionalCheck: true,
      enableUncertaintyQuantification: true,
      enableRAG: false, // يتم تفعيله عادةً في المنسق
      temperature: 0.4,
      maxTokens: 4096,
      ...options,
    };
  }

  /**
   * تطبيق فحص التوافق مع المبادئ الدستورية
   */
  private async applyConstitutionalCheck(
    result: StationResult,
    originalText: string
  ): Promise<StationResult> {
    try {
      // استخراج النصوص التي تحتاج إلى فحص
      const textsToCheck = this.extractTextsForConstitutionalCheck(result);

      const constitutionalResults = [];
      let hasViolations = false;
      let overallImprovementScore = 1.0;

      for (const text of textsToCheck) {
        const checkResult = await checkConstitutionalCompliance(
          text,
          originalText,
          this.geminiService
        );

        constitutionalResults.push(checkResult);

        if (!checkResult.compliant) {
          hasViolations = true;
          overallImprovementScore = Math.min(
            overallImprovementScore,
            checkResult.improvementScore
          );

          // استبدال النص بالنسخة المصححة
          result = this.replaceTextInResult(
            result,
            text,
            checkResult.correctedAnalysis ?? text
          );
        }
      }

      // إضافة نتائج الفحص الدستوري إلى النتيجة
      const resultObj = result as Record<string, unknown>;
      resultObj.constitutionalCheck = {
        checked: true,
        compliant: !hasViolations,
        violations: constitutionalResults.flatMap((r) =>
          r.violations.map((v) => `${v.principle}: ${v.description}`)
        ),
        improvementScore: overallImprovementScore,
      };

      return result;
    } catch (error) {
      console.error("Constitutional check failed:", error);

      // إضافة معلومات الفشل إلى النتيجة
      const resultObj = result as Record<string, unknown>;
      resultObj.constitutionalCheck = {
        checked: false,
        compliant: false,
        violations: [`فشل الفحص: ${(error as Error).message}`],
        improvementScore: 0,
      };

      return result;
    }
  }

  /**
   * تطبيق قياس عدم اليقين
   */
  private async applyUncertaintyQuantification(
    result: StationResult,
    input: StationInput
  ): Promise<StationResult> {
    try {
      const uncertaintyEngine = getUncertaintyQuantificationEngine(
        this.geminiService
      );

      // استخراج النصوص التي تحتاج إلى قياس عدم اليقين
      const textsToQuantify =
        this.extractTextsForUncertaintyQuantification(result);

      const uncertaintyResults = [];
      let overallConfidence = 0;
      let uncertaintyType: "epistemic" | "aleatoric" = "epistemic";
      const allSources = [];

      for (const text of textsToQuantify) {
        const metrics = await uncertaintyEngine.quantify(text, {
          originalText: input.text,
          analysisType: this.stationName,
          previousResults: input.previousResults,
        });

        uncertaintyResults.push(metrics);
        overallConfidence += metrics.confidence;
        uncertaintyType = metrics.type;
        allSources.push(...metrics.sources);
      }

      // حساب متوسط درجات عدم اليقين
      overallConfidence =
        overallConfidence / Math.max(uncertaintyResults.length, 1);

      // إضافة نتائج قياس عدم اليقين إلى النتيجة
      const resultObj = result as Record<string, unknown>;
      resultObj.uncertaintyQuantification = {
        quantified: true,
        overallConfidence,
        uncertaintyType,
        sources: allSources.slice(0, 5), // أهم 5 مصادر
      };

      return result;
    } catch (error) {
      console.error("Uncertainty quantification failed:", error);

      // إضافة معلومات الفشل إلى النتيجة
      const resultObj = result as Record<string, unknown>;
      resultObj.uncertaintyQuantification = {
        quantified: false,
        overallConfidence: 0.5,
        uncertaintyType: "epistemic",
        sources: [
          {
            aspect: "فشل التحليل",
            reason: (error as Error).message,
            reducible: false,
          },
        ],
      };

      return result;
    }
  }

  /**
   * إنشاء البيانات الوصفية النهائية
   */
  private async createMetadata(
    startTime: number,
    options: StationOptions,
    input: StationInput
  ): Promise<StationMetadata> {
    const executionTime = Date.now() - startTime;

    return {
      stationName: this.stationName,
      stationNumber: this.stationNumber,
      status: "Success",
      executionTime,
      agentsUsed: this.getAgentsUsed(),
      tokensUsed: this.estimateTokensUsed(input.text),
      options: {
        ...(options.enableConstitutionalCheck !== undefined && {
          constitutionalCheck: options.enableConstitutionalCheck,
        }),
        ...(options.enableUncertaintyQuantification !== undefined && {
          uncertaintyQuantification: options.enableUncertaintyQuantification,
        }),
        ...(options.enableRAG !== undefined && { rag: options.enableRAG }),
        ...(options.temperature !== undefined && {
          temperature: options.temperature,
        }),
        ...(options.maxTokens !== undefined && {
          maxTokens: options.maxTokens,
        }),
      },
      ragInfo:
        options.enableRAG && input.chunks
          ? {
              wasChunked: true,
              chunksCount: input.chunks.length,
              retrievalTime: 0, // سيتم حسابه في المنسق
            }
          : {
              wasChunked: false,
              chunksCount: 0,
              retrievalTime: 0,
            },
    };
  }

  /**
   * استخراج النصوص التي تحتاج إلى فحص دستوري (يمكن تجاوزه في المحطات الفرعية)
   */
  protected extractTextsForConstitutionalCheck(
    result: StationResult
  ): string[] {
    const texts = [];

    // استخراج النصوص الرئيسية من نتيجة المحطة
    if (typeof result === "object" && result !== null) {
      const resultObj = result as Record<string, unknown>;
      if (typeof resultObj.logline === "string") texts.push(resultObj.logline);
      if (typeof resultObj.storyStatement === "string")
        texts.push(resultObj.storyStatement);
      if (typeof resultObj.elevatorPitch === "string")
        texts.push(resultObj.elevatorPitch);
      if (typeof resultObj.executiveSummary === "string")
        texts.push(resultObj.executiveSummary);
    }

    // استخراج النصوص من التحليلات الفرعية
    if (
      typeof result === "object" &&
      result !== null &&
      "characterAnalysis" in result
    ) {
      const characterAnalysis = result.characterAnalysis;
      if (typeof characterAnalysis === "object" && characterAnalysis !== null) {
        for (const [_character, analysis] of Object.entries(
          characterAnalysis
        )) {
          if (typeof analysis === "string") texts.push(analysis);
        }
      }
    }

    if (typeof result === "object" && result !== null && "themes" in result) {
      const themes = result.themes;
      if (
        typeof themes === "object" &&
        themes !== null &&
        "primary" in themes
      ) {
        const primaryThemes = (
          themes as { primary?: { description?: string }[] }
        ).primary;
        if (Array.isArray(primaryThemes)) {
          for (const theme of primaryThemes) {
            if (
              theme &&
              typeof theme === "object" &&
              "description" in theme &&
              typeof theme.description === "string"
            ) {
              texts.push(theme.description);
            }
          }
        }
      }
    }

    return texts;
  }

  /**
   * استخراج النصوص التي تحتاج إلى قياس عدم اليقين (يمكن تجاوزه في المحطات الفرعية)
   */
  protected extractTextsForUncertaintyQuantification(
    result: StationResult
  ): string[] {
    // للتبسيط، نستخدم نفس النصوص المستخدمة في الفحص الدستوري
    return this.extractTextsForConstitutionalCheck(result);
  }

  /**
   * استبدال نص في نتيجة المحطة
   */
  protected replaceTextInResult(
    result: StationResult,
    oldText: string,
    newText: string
  ): StationResult {
    // نسخة عميقة من النتيجة لتجنب التعديل المباشر
    const newResult = JSON.parse(JSON.stringify(result)) as StationResult;

    // دالة تعاودية للبحث والاستبدال
    function replaceInObject(obj: unknown): void {
      if (typeof obj !== "object" || obj === null) {
        return;
      }

      for (const key in obj) {
        const value = (obj as Record<string, unknown>)[key];
        if (typeof value === "string" && value === oldText) {
          (obj as Record<string, unknown>)[key] = newText;
        } else if (typeof value === "object" && value !== null) {
          replaceInObject(value);
        }
      }
    }

    replaceInObject(newResult);
    return newResult;
  }

  /**
   * الحصول على قائمة الوكلاء المستخدمين في هذه المحطة (يجب تجاوزه)
   */
  protected abstract getAgentsUsed(): string[];

  /**
   * تقدير عدد التوكنز المستخدمة
   */
  protected estimateTokensUsed(text: string): number {
    // تقدير بسيط: 1 توكن ≈ 4 أحرف
    return Math.ceil(text.length / 4);
  }
}

import "server-only";
import { GoogleGenAI } from "@google/genai";

import { logger } from "../utils/logger";

export enum GeminiModel {
  PRO = "gemini-2.5-pro",
  FLASH = "gemini-2.5-flash",
  FLASH_LITE = "gemini-2.5-flash-lite",
}

export interface GeminiConfig {
  apiKey: string;
  defaultModel: GeminiModel;
  maxRetries: number;
  timeout: number;
  fallbackModel?: GeminiModel;
  enableCaching?: boolean;
  enableRateLimiting?: boolean;
  requestsPerMinute?: number;
}

export interface GeminiRequest<T> {
  prompt: string;
  model?: GeminiModel;
  context?: string;
  systemInstruction?: string;
  temperature?: number;
  maxTokens?: number;
  validator?: (value: unknown) => value is T;
  allowPartial?: boolean;
  onPartialFallback?: (value: unknown) => T;
  stopSequences?: string[];
  topP?: number;
  topK?: number;
}

export interface GeminiResponse<T> {
  model: GeminiModel;
  content: T;
  usage: {
    promptTokens: number;
    completionTokens: number;
    totalTokens: number;
  };
  metadata: {
    timestamp: Date;
    latency: number;
    cached: boolean;
    retryCount: number;
  };
}

interface CacheEntry<T> {
  response: GeminiResponse<T>;
  timestamp: number;
  expiresAt: number;
}

interface RateLimitState {
  requests: number[];
  lastReset: number;
}

export class GeminiService {
  private ai: GoogleGenAI;
  private config: GeminiConfig;
  private cache: Map<string, CacheEntry<any>>;
  private rateLimitState: RateLimitState;
  private readonly CACHE_TTL = 3600000;
  private readonly RATE_LIMIT_WINDOW = 60000;

  constructor(config: GeminiConfig) {
    this.config = {
      ...config,
      enableCaching: config.enableCaching ?? true,
      enableRateLimiting: config.enableRateLimiting ?? true,
      requestsPerMinute: config.requestsPerMinute ?? 60,
    };

    this.ai = new GoogleGenAI({ apiKey: config.apiKey });
    this.cache = new Map();
    this.rateLimitState = {
      requests: [],
      lastReset: Date.now(),
    };

    this.validateModels();
    this.startCacheCleanup();
  }

  private validateModels(): void {
    const allowedModels = Object.values(GeminiModel);
    if (!allowedModels.includes(this.config.defaultModel)) {
      throw new Error(
        `Invalid model: ${this.config.defaultModel}. ` +
          `Only ${allowedModels.join(", ")} are allowed.`
      );
    }

    if (
      this.config.fallbackModel &&
      !allowedModels.includes(this.config.fallbackModel)
    ) {
      throw new Error(
        `Invalid fallback model: ${this.config.fallbackModel}. ` +
          `Only ${allowedModels.join(", ")} are allowed.`
      );
    }
  }

  async generate<T>(request: GeminiRequest<T>): Promise<GeminiResponse<T>> {
    this.validateModels();

    if (this.config.enableRateLimiting) {
      await this.enforceRateLimit();
    }

    const cacheKey = this.generateCacheKey(request);

    if (this.config.enableCaching) {
      const cached = this.getFromCache<T>(cacheKey);
      if (cached) {
        logger.info("[GeminiService] Returning cached response", { cacheKey });
        return cached;
      }
    }

    const primaryModel = request.model ?? this.config.defaultModel;
    let retryCount = 0;

    for (let attempt = 0; attempt <= this.config.maxRetries; attempt++) {
      try {
        const response = await this.performRequest<T>(
          {
            ...request,
            model: primaryModel,
          },
          attempt
        );

        response.metadata.retryCount = retryCount;

        if (this.config.enableCaching) {
          this.saveToCache(cacheKey, response);
        }

        return response;
      } catch (primaryError) {
        retryCount++;

        if (attempt === this.config.maxRetries) {
          if (
            this.config.fallbackModel &&
            this.config.fallbackModel !== primaryModel
          ) {
            logger.warn(
              "[GeminiService] Primary model exhausted retries. Trying fallback model.",
              {
                primaryModel,
                fallbackModel: this.config.fallbackModel,
                attempt,
              }
            );

            try {
              const fallbackResponse = await this.performRequest<T>(
                {
                  ...request,
                  model: this.config.fallbackModel,
                },
                0
              );

              fallbackResponse.metadata.retryCount = retryCount;

              if (this.config.enableCaching) {
                this.saveToCache(cacheKey, fallbackResponse);
              }

              return fallbackResponse;
            } catch (fallbackError) {
              return this.handleError<T>(fallbackError, {
                ...request,
                model: this.config.fallbackModel,
              });
            }
          }

          return this.handleError<T>(primaryError, {
            ...request,
            model: primaryModel,
          });
        }

        const backoffDelay = Math.min(1000 * Math.pow(2, attempt), 30000);
        logger.warn(
          `[GeminiService] Request failed. Retrying in ${backoffDelay}ms`,
          {
            attempt: attempt + 1,
            maxRetries: this.config.maxRetries,
            error:
              primaryError instanceof Error ? primaryError.message : "Unknown",
          }
        );

        await this.delay(backoffDelay);
      }
    }

    throw new Error("Unexpected: exceeded retry loop without resolution");
  }

  private async performRequest<T>(
    request: GeminiRequest<T>,
    attemptNumber: number
  ): Promise<GeminiResponse<T>> {
    const startTime = Date.now();
    const modelName = request.model ?? this.config.defaultModel;

    const systemPart = request.systemInstruction
      ? `System Instructions: ${request.systemInstruction}\n\n`
      : "";

    const contextPart = request.context
      ? `Context: ${request.context}\n\n`
      : "";

    const fullPrompt = `${systemPart}${contextPart}${request.prompt}`;

    const finalConfig: any = {
      temperature: request.temperature ?? 0.7,
      maxOutputTokens: request.maxTokens ?? 8192,
      topP: request.topP ?? 0.95,
      topK: request.topK ?? 40,
    };

    if (request.stopSequences && request.stopSequences.length > 0) {
      finalConfig.stopSequences = request.stopSequences;
    }

    logger.info(`[GeminiService] Generating content with model ${modelName}`, {
      promptLength: fullPrompt.length,
      temperature: finalConfig.temperature,
      maxTokens: finalConfig.maxOutputTokens,
      attemptNumber,
    });

    const timeoutPromise = new Promise<never>((_, reject) => {
      setTimeout(
        () => reject(new Error("Request timeout")),
        this.config.timeout
      );
    });

    const requestPromise = this.ai.models.generateContent({
      model: modelName,
      contents: fullPrompt,
      config: finalConfig,
    });

    const result = await Promise.race([requestPromise, timeoutPromise]);

    const text = result.text ?? "";
    const latency = Date.now() - startTime;

    const usage = this.estimateTokenUsage(fullPrompt, text);

    logger.info("[GeminiService] Content generated successfully", {
      model: modelName,
      latency,
      outputTokens: usage.completionTokens,
      attemptNumber,
    });

    return {
      model: modelName,
      content: this.parseResponse<T>(text, request),
      usage,
      metadata: {
        timestamp: new Date(),
        latency,
        cached: false,
        retryCount: 0,
      },
    };
  }

  private parseResponse<T>(responseText: string, request: GeminiRequest<T>): T {
    const { validator, allowPartial, onPartialFallback } = request;

    if (validator) {
      const rawData = { raw: responseText };
      if (validator(rawData)) {
        return rawData;
      }

      if (allowPartial && onPartialFallback) {
        const partial = onPartialFallback(rawData);
        if (partial !== undefined) {
          logger.info("[GeminiService] Using partial fallback for response");
          return partial;
        }
      }

      logger.error("[GeminiService] Response failed validation");
      throw new Error("Gemini response failed validation");
    }

    return { raw: responseText } as T;
  }

  private async handleError<T>(
    error: unknown,
    request: GeminiRequest<T>
  ): Promise<never> {
    const message = error instanceof Error ? error.message : "Unknown error";
    logger.error(
      `[GeminiService] Failed to generate content with model ${request.model}`,
      {
        error: message,
      }
    );
    throw error instanceof Error ? error : new Error(message);
  }

  private generateCacheKey(request: GeminiRequest<any>): string {
    const model = request.model ?? this.config.defaultModel;
    const temp = request.temperature ?? 0.7;
    const maxTokens = request.maxTokens ?? 8192;

    const keyData = {
      model,
      prompt: request.prompt.substring(0, 500),
      context: request.context?.substring(0, 200),
      systemInstruction: request.systemInstruction?.substring(0, 200),
      temp,
      maxTokens,
    };

    return JSON.stringify(keyData);
  }

  private getFromCache<T>(cacheKey: string): GeminiResponse<T> | null {
    const entry = this.cache.get(cacheKey);
    if (!entry) return null;

    if (Date.now() > entry.expiresAt) {
      this.cache.delete(cacheKey);
      return null;
    }

    const response = { ...entry.response };
    response.metadata = { ...response.metadata, cached: true };
    return response;
  }

  private saveToCache<T>(cacheKey: string, response: GeminiResponse<T>): void {
    const entry: CacheEntry<T> = {
      response: { ...response },
      timestamp: Date.now(),
      expiresAt: Date.now() + this.CACHE_TTL,
    };
    this.cache.set(cacheKey, entry);
  }

  private startCacheCleanup(): void {
    setInterval(() => {
      const now = Date.now();
      let cleaned = 0;

      for (const [key, entry] of this.cache.entries()) {
        if (now > entry.expiresAt) {
          this.cache.delete(key);
          cleaned++;
        }
      }

      if (cleaned > 0) {
        logger.info(
          `[GeminiService] Cache cleanup: removed ${cleaned} expired entries`
        );
      }
    }, 300000);
  }

  private async enforceRateLimit(): Promise<void> {
    const now = Date.now();

    if (now - this.rateLimitState.lastReset > this.RATE_LIMIT_WINDOW) {
      this.rateLimitState.requests = [];
      this.rateLimitState.lastReset = now;
    }

    this.rateLimitState.requests = this.rateLimitState.requests.filter(
      (timestamp) => now - timestamp < this.RATE_LIMIT_WINDOW
    );

    if (
      this.rateLimitState.requests.length >=
      (this.config.requestsPerMinute ?? 60)
    ) {
      const oldestRequest = this.rateLimitState.requests[0];
      const waitTime = oldestRequest
        ? this.RATE_LIMIT_WINDOW - (now - oldestRequest)
        : 0;

      logger.warn(`[GeminiService] Rate limit reached. Waiting ${waitTime}ms`, {
        requestsInWindow: this.rateLimitState.requests.length,
        limit: this.config.requestsPerMinute,
      });

      await this.delay(waitTime);
      return this.enforceRateLimit();
    }

    this.rateLimitState.requests.push(now);
  }

  private estimateTokenUsage(
    prompt: string,
    completion: string
  ): {
    promptTokens: number;
    completionTokens: number;
    totalTokens: number;
  } {
    const promptTokens = Math.ceil(prompt.length / 4);
    const completionTokens = Math.ceil(completion.length / 4);

    return {
      promptTokens,
      completionTokens,
      totalTokens: promptTokens + completionTokens,
    };
  }

  private delay(ms: number): Promise<void> {
    return new Promise((resolve) => setTimeout(resolve, ms));
  }

  clearCache(): void {
    this.cache.clear();
    logger.info("[GeminiService] Cache cleared");
  }

  getCacheStats(): {
    size: number;
    oldestEntry: number;
    newestEntry: number;
  } {
    if (this.cache.size === 0) {
      return { size: 0, oldestEntry: 0, newestEntry: 0 };
    }

    const timestamps = Array.from(this.cache.values()).map((e) => e.timestamp);
    return {
      size: this.cache.size,
      oldestEntry: Math.min(...timestamps),
      newestEntry: Math.max(...timestamps),
    };
  }

  getRateLimitStats(): {
    requestsInWindow: number;
    limit: number;
    resetAt: number;
  } {
    const now = Date.now();
    const requestsInWindow = this.rateLimitState.requests.filter(
      (timestamp) => now - timestamp < this.RATE_LIMIT_WINDOW
    ).length;

    return {
      requestsInWindow,
      limit: this.config.requestsPerMinute ?? 60,
      resetAt: this.rateLimitState.lastReset + this.RATE_LIMIT_WINDOW,
    };
  }

  async testConnection(): Promise<boolean> {
    try {
      await this.generate({
        prompt: 'Test connection. Reply with "OK".',
        temperature: 0.1,
        maxTokens: 10,
      });
      logger.info("[GeminiService] Connection test successful");
      return true;
    } catch (error) {
      logger.error("[GeminiService] Connection test failed:", error);
      return false;
    }
  }

  getConfig(): Readonly<GeminiConfig> {
    return { ...this.config };
  }

  updateConfig(updates: Partial<GeminiConfig>): void {
    this.config = { ...this.config, ...updates };
    this.validateModels();
    logger.info("[GeminiService] Configuration updated", updates);
  }
}

export function createGeminiService(config: GeminiConfig): GeminiService {
  return new GeminiService(config);
}

export function createProductionGeminiService(apiKey: string): GeminiService {
  return new GeminiService({
    apiKey,
    defaultModel: GeminiModel.PRO,
    fallbackModel: GeminiModel.FLASH,
    maxRetries: 5,
    timeout: 180_000,
    enableCaching: true,
    enableRateLimiting: true,
    requestsPerMinute: 50,
  });
}

export function createDevelopmentGeminiService(apiKey: string): GeminiService {
  return new GeminiService({
    apiKey,
    defaultModel: GeminiModel.FLASH,
    fallbackModel: GeminiModel.FLASH_LITE,
    maxRetries: 2,
    timeout: 60_000,
    enableCaching: false,
    enableRateLimiting: false,
    requestsPerMinute: 100,
  });
}

// Singleton instance for use in BaseStation and other core modules
let geminiServiceSingleton: GeminiService | null = null;

/**
 * Get or create the singleton GeminiService instance
 * Uses environment variables to determine the API key and configuration
 */
export function getGeminiService(config?: GeminiConfig): GeminiService {
  if (!geminiServiceSingleton) {
    if (config) {
      geminiServiceSingleton = new GeminiService(config);
    } else {
      // Try to get API key from environment (server-side only)
      let apiKey: string;
      try {
        // Dynamic import to avoid issues if env.ts is not available
        const { getApiKey } = require("../../../env");
        apiKey = getApiKey();
      } catch {
        // Fallback: try to get from process.env directly
        apiKey =
          process.env["GEMINI_API_KEY_PROD"] ??
          process.env["GEMINI_API_KEY_STAGING"] ??
          "";
      }

      if (!apiKey) {
        throw new Error(
          "GeminiService requires a config object or GEMINI_API_KEY environment variable"
        );
      }

      // Determine environment and create appropriate service
      const isProduction = process.env.NODE_ENV === "production";
      if (isProduction) {
        geminiServiceSingleton = createProductionGeminiService(apiKey);
      } else {
        geminiServiceSingleton = createDevelopmentGeminiService(apiKey);
      }
    }
  }
  return geminiServiceSingleton;
}

import {
  ConflictNetwork,
  Conflict,
  Relationship,
} from "../core/models/base-entities";

export interface DiagnosticReport {
  overallHealthScore: number;
  criticalityLevel:
    | "healthy"
    | "minor_issues"
    | "moderate_issues"
    | "major_issues"
    | "critical";
  structuralIssues: StructuralIssue[];
  isolatedCharacters: {
    totalIsolated: number;
    characters: IsolatedCharacterIssue[];
  };
  abandonedConflicts: {
    totalAbandoned: number;
    conflicts: AbandonedConflictIssue[];
  };
  overloadedCharacters: {
    totalOverloaded: number;
    characters: OverloadedCharacterIssue[];
  };
  weakConnections: {
    totalWeak: number;
    connections: WeakConnectionIssue[];
  };
  redundancies: {
    totalRedundant: number;
    items: RedundancyIssue[];
  };
}

export interface StructuralIssue {
  type:
    | "disconnected_components"
    | "single_point_failure"
    | "circular_dependency";
  severity: "low" | "medium" | "high" | "critical";
  description: string;
  affectedElements: string[];
}

export interface IsolatedCharacterIssue {
  characterName: string;
  characterId: string;
  isolationType:
    | "completely_isolated"
    | "weakly_connected"
    | "conflict_isolated";
  suggestedConnections: string[];
}

export interface AbandonedConflictIssue {
  conflictName: string;
  conflictId: string;
  issueType: "stuck_in_phase" | "no_progression" | "weak_involvement";
  daysInactive: number;
  suggestedActions: string[];
}

export interface OverloadedCharacterIssue {
  characterName: string;
  characterId: string;
  overloadType:
    | "too_many_conflicts"
    | "too_many_relationships"
    | "central_bottleneck";
  currentLoad: number;
  recommendedLoad: number;
  suggestedDistribution: string[];
}

export interface WeakConnectionIssue {
  connectionType: "relationship" | "conflict_involvement";
  elementId: string;
  weakness: string;
  strengthScore: number;
  improvementSuggestions: string[];
}

export interface RedundancyIssue {
  redundancyType:
    | "duplicate_relationships"
    | "similar_conflicts"
    | "overlapping_characters";
  affectedElements: string[];
  redundancyScore: number;
  consolidationSuggestion: string;
}

interface DiagnosticIssueSummary {
  structuralIssues: StructuralIssue[];
  isolatedCharacters: DiagnosticReport["isolatedCharacters"];
  abandonedConflicts: DiagnosticReport["abandonedConflicts"];
  overloadedCharacters: DiagnosticReport["overloadedCharacters"];
  weakConnections: DiagnosticReport["weakConnections"];
  redundancies: DiagnosticReport["redundancies"];
}

export class NetworkDiagnostics {
  private network: ConflictNetwork;

  constructor(network: ConflictNetwork) {
    this.network = network;
  }

  runAllDiagnostics(): DiagnosticReport {
    const structuralIssues = this.analyzeStructuralIssues();
    const isolatedCharacters = this.findIsolatedCharacters();
    const abandonedConflicts = this.findAbandonedConflicts();
    const overloadedCharacters = this.findOverloadedCharacters();
    const weakConnections = this.findWeakConnections();
    const redundancies = this.findRedundancies();

    const overallHealthScore = this.calculateOverallHealth({
      structuralIssues,
      isolatedCharacters,
      abandonedConflicts,
      overloadedCharacters,
      weakConnections,
      redundancies,
    });

    return {
      overallHealthScore,
      criticalityLevel: this.determineCriticalityLevel(overallHealthScore),
      structuralIssues,
      isolatedCharacters,
      abandonedConflicts,
      overloadedCharacters,
      weakConnections,
      redundancies,
    };
  }

  private analyzeStructuralIssues(): StructuralIssue[] {
    const issues: StructuralIssue[] = [];

    // Check for disconnected components
    const components = this.findConnectedComponents();
    if (components.length > 1) {
      issues.push({
        type: "disconnected_components",
        severity: "high",
        description: `الشبكة مقسمة إلى ${components.length} مكونات منفصلة`,
        affectedElements: components.flat(),
      });
    }

    // Check for single points of failure
    const criticalNodes = this.findCriticalNodes();
    if (criticalNodes.length > 0) {
      issues.push({
        type: "single_point_failure",
        severity: "medium",
        description: "توجد شخصيات حرجة قد تؤدي إزالتها لانهيار الشبكة",
        affectedElements: criticalNodes,
      });
    }

    return issues;
  }

  private findIsolatedCharacters(): {
    totalIsolated: number;
    characters: IsolatedCharacterIssue[];
  } {
    const isolatedChars: IsolatedCharacterIssue[] = [];

    for (const [characterId, character] of Object.entries(
      this.network.characters
    )) {
      const relationships = this.getCharacterRelationships(characterId);
      const conflicts = this.getCharacterConflicts(characterId);

      if (relationships.length === 0 && conflicts.length === 0) {
        isolatedChars.push({
          characterName: character.name,
          characterId: characterId,
          isolationType: "completely_isolated",
          suggestedConnections:
            this.suggestConnectionsForCharacter(characterId),
        });
      } else if (relationships.length <= 1 && conflicts.length === 0) {
        isolatedChars.push({
          characterName: character.name,
          characterId: characterId,
          isolationType: "weakly_connected",
          suggestedConnections:
            this.suggestConnectionsForCharacter(characterId),
        });
      } else if (relationships.length > 0 && conflicts.length === 0) {
        isolatedChars.push({
          characterName: character.name,
          characterId: characterId,
          isolationType: "conflict_isolated",
          suggestedConnections: this.suggestConflictInvolvement(),
        });
      }
    }

    return {
      totalIsolated: isolatedChars.length,
      characters: isolatedChars,
    };
  }

  private findAbandonedConflicts(): {
    totalAbandoned: number;
    conflicts: AbandonedConflictIssue[];
  } {
    const abandonedConflicts: AbandonedConflictIssue[] = [];

    if (!this.network.conflicts) return { totalAbandoned: 0, conflicts: [] };

    for (const [conflictId, conflict] of Object.entries(
      this.network.conflicts
    )) {
      const daysSinceLastUpdate = this.calculateDaysSinceLastUpdate(conflict);

      if (daysSinceLastUpdate > 30) {
        abandonedConflicts.push({
          conflictName: conflict.name ?? conflictId,
          conflictId: conflict.id ?? conflictId,
          issueType: "stuck_in_phase",
          daysInactive: daysSinceLastUpdate,
          suggestedActions: this.suggestConflictActions(conflict),
        });
      } else if ((conflict.strength ?? 0) < 3) {
        abandonedConflicts.push({
          conflictName: conflict.name ?? conflictId,
          conflictId: conflict.id ?? conflictId,
          issueType: "weak_involvement",
          daysInactive: daysSinceLastUpdate,
          suggestedActions: this.suggestConflictActions(conflict),
        });
      }
    }

    return {
      totalAbandoned: abandonedConflicts.length,
      conflicts: abandonedConflicts,
    };
  }

  private findOverloadedCharacters(): {
    totalOverloaded: number;
    characters: OverloadedCharacterIssue[];
  } {
    const overloadedChars: OverloadedCharacterIssue[] = [];

    for (const [characterId, character] of Object.entries(
      this.network.characters
    )) {
      const relationships = this.getCharacterRelationships(characterId);
      const conflicts = this.getCharacterConflicts(characterId);

      const totalLoad = relationships.length + conflicts.length * 2; // Conflicts weighted more

      if (totalLoad > 8) {
        // Threshold for overload
        overloadedChars.push({
          characterName: character.name,
          characterId: characterId,
          overloadType: "central_bottleneck",
          currentLoad: totalLoad,
          recommendedLoad: 6,
          suggestedDistribution: this.suggestLoadDistribution(characterId),
        });
      }
    }

    return {
      totalOverloaded: overloadedChars.length,
      characters: overloadedChars,
    };
  }

  private findWeakConnections(): {
    totalWeak: number;
    connections: WeakConnectionIssue[];
  } {
    const weakConnections: WeakConnectionIssue[] = [];

    // Check weak relationships
    for (const relationshipArray of Object.values(this.network.relationships)) {
      for (const relationship of relationshipArray) {
        if ((relationship.strength ?? 0) < 4) {
          weakConnections.push({
            connectionType: "relationship",
            elementId:
              relationship.id ??
              `${relationship.source}-${relationship.target}`,
            weakness: "قوة العلاقة ضعيفة",
            strengthScore: relationship.strength,
            improvementSuggestions: [
              "أضف مشاهد تفاعل أكثر بين الشخصيتين",
              "طور الخلفية المشتركة للشخصيتين",
              "أنشئ صراعاً يجمع بينهما",
            ],
          });
        }
      }
    }

    // Check weak conflict involvement
    if (this.network.conflicts) {
      for (const [conflictId, conflict] of Object.entries(
        this.network.conflicts
      )) {
        if ((conflict.strength ?? 0) < 4) {
          weakConnections.push({
            connectionType: "conflict_involvement",
            elementId: conflict.id ?? conflictId,
            weakness: "مشاركة ضعيفة في الصراع",
            strengthScore: conflict.strength,
            improvementSuggestions: [
              "زد من حدة الصراع",
              "أضف نقاط تحول مهمة",
              "اربط الصراع بدوافع الشخصيات الأساسية",
            ],
          });
        }
      }
    }

    return {
      totalWeak: weakConnections.length,
      connections: weakConnections,
    };
  }

  private findRedundancies(): {
    totalRedundant: number;
    items: RedundancyIssue[];
  } {
    const redundancies: RedundancyIssue[] = [];

    // Check for duplicate relationships
    const relationshipPairs = this.findDuplicateRelationships();
    for (const pair of relationshipPairs) {
      redundancies.push({
        redundancyType: "duplicate_relationships",
        affectedElements: pair,
        redundancyScore: 0.8,
        consolidationSuggestion: "دمج العلاقات المتشابهة في علاقة واحدة أقوى",
      });
    }

    // Check for similar conflicts
    const conflictGroups = this.findSimilarConflicts();
    for (const group of conflictGroups) {
      if (group.length > 1) {
        redundancies.push({
          redundancyType: "similar_conflicts",
          affectedElements: group,
          redundancyScore: 0.7,
          consolidationSuggestion:
            "دمج الصراعات المتشابهة في صراع واحد أكثر تعقيداً",
        });
      }
    }

    return {
      totalRedundant: redundancies.length,
      items: redundancies,
    };
  }

  // Helper methods
  private getCharacterRelationships(characterId: string): Relationship[] {
    return Object.values(this.network.relationships)
      .flat()
      .filter(
        (rel) => rel.source === characterId || rel.target === characterId
      );
  }

  private getCharacterConflicts(characterId: string): Conflict[] {
    if (!this.network.conflicts) return [];
    return Object.values(this.network.conflicts).filter((conflict) =>
      conflict.involvedCharacters?.includes(characterId)
    );
  }

  private findConnectedComponents(): string[][] {
    // Simple connected components algorithm
    const visited = new Set<string>();
    const components: string[][] = [];

    for (const charId of this.network.characters.keys()) {
      if (!visited.has(charId)) {
        const component = this.dfsComponent(charId, visited);
        components.push(component);
      }
    }

    return components;
  }

  private dfsComponent(startId: string, visited: Set<string>): string[] {
    const component: string[] = [];
    const stack = [startId];

    while (stack.length > 0) {
      const currentId = stack.pop()!;
      if (visited.has(currentId)) continue;

      visited.add(currentId);
      component.push(currentId);

      // Add connected characters
      const relationships = this.getCharacterRelationships(currentId);
      for (const rel of relationships) {
        const otherId = rel.source === currentId ? rel.target : rel.source;
        if (!visited.has(otherId)) {
          stack.push(otherId);
        }
      }
    }

    return component;
  }

  private findCriticalNodes(): string[] {
    // Characters whose removal would disconnect the network
    const criticalNodes: string[] = [];

    for (const charId of Object.keys(this.network.characters)) {
      const relationships = this.getCharacterRelationships(charId);
      if (relationships.length >= 3) {
        // High connectivity threshold
        criticalNodes.push(charId);
      }
    }

    return criticalNodes;
  }

  private suggestConnectionsForCharacter(characterId: string): string[] {
    const suggestions: string[] = [];
    const character = this.network.characters.get(characterId);

    if (character) {
      // Find characters with similar traits or roles
      for (const [
        otherCharId,
        otherChar,
      ] of this.network.characters.entries()) {
        if (otherCharId !== characterId) {
          suggestions.push(`ربط مع الشخصية: ${otherChar.name}`);
          if (suggestions.length >= 3) break;
        }
      }
    }

    return suggestions;
  }

  private suggestConflictInvolvement(): string[] {
    const suggestions: string[] = [];
    if (!this.network.conflicts) return suggestions;
    const conflicts = Object.values(this.network.conflicts);

    for (const conflict of conflicts.slice(0, 2)) {
      suggestions.push(`إشراك في الصراع: ${conflict.name ?? "صراع غير معروف"}`);
    }

    return suggestions;
  }

  private calculateDaysSinceLastUpdate(conflict: Conflict): number {
    if (!conflict.timestamps || conflict.timestamps.length === 0) return 365; // Very old

    const lastUpdate = conflict.timestamps[conflict.timestamps.length - 1];
    if (!lastUpdate) return 365; // No valid timestamp
    const now = new Date();
    const diffTime = Math.abs(now.getTime() - lastUpdate.getTime());
    return Math.ceil(diffTime / (1000 * 60 * 60 * 24));
  }

  private suggestConflictActions(_conflict: Conflict): string[] {
    return [
      "تطوير الصراع إلى المرحلة التالية",
      "إضافة نقطة تحول جديدة",
      "زيادة مشاركة الشخصيات",
      "ربط الصراع بصراعات أخرى",
    ];
  }

  private suggestLoadDistribution(_characterId: string): string[] {
    return [
      "نقل بعض العلاقات لشخصيات أخرى",
      "تقسيم الصراعات الكبيرة",
      "إنشاء شخصيات مساعدة",
    ];
  }

  private findDuplicateRelationships(): string[][] {
    const duplicates: string[][] = [];
    const allRelationships = Object.values(this.network.relationships).flat();

    for (let i = 0; i < allRelationships.length; i++) {
      for (let j = i + 1; j < allRelationships.length; j++) {
        const rel1 = allRelationships[i] as Relationship;
        const rel2 = allRelationships[j] as Relationship;

        if (this.areRelationshipsSimilar(rel1, rel2)) {
          duplicates.push([
            rel1.id ?? `${rel1.source}-${rel1.target}`,
            rel2.id ?? `${rel2.source}-${rel2.target}`,
          ]);
        }
      }
    }

    return duplicates;
  }

  private findSimilarConflicts(): string[][] {
    const groups: string[][] = [];
    if (!this.network.conflicts) return groups;
    const conflicts = Object.entries(this.network.conflicts);
    const processed = new Set<string>();

    for (const [conflictId, conflict] of conflicts) {
      const id = conflict.id ?? conflictId;
      if (processed.has(id)) continue;

      const similarGroup = [id];
      processed.add(id);

      for (const [otherConflictId, otherConflict] of conflicts) {
        const otherId = otherConflict.id ?? otherConflictId;
        if (otherId !== id && !processed.has(otherId)) {
          if (this.areConflictsSimilar(conflict, otherConflict)) {
            similarGroup.push(otherId);
            processed.add(otherId);
          }
        }
      }

      if (similarGroup.length > 1) {
        groups.push(similarGroup);
      }
    }

    return groups;
  }

  private areRelationshipsSimilar(
    rel1: Relationship,
    rel2: Relationship
  ): boolean {
    return (
      rel1.type === rel2.type &&
      ((rel1.source === rel2.source && rel1.target === rel2.target) ||
        (rel1.source === rel2.target && rel1.target === rel2.source))
    );
  }

  private areConflictsSimilar(
    conflict1: Conflict,
    conflict2: Conflict
  ): boolean {
    return (
      conflict1.subject === conflict2.subject &&
      conflict1.scope === conflict2.scope &&
      this.hasOverlappingCharacters(
        conflict1.involvedCharacters ?? [],
        conflict2.involvedCharacters ?? []
      )
    );
  }

  private hasOverlappingCharacters(
    chars1: string[],
    chars2: string[]
  ): boolean {
    return chars1.some((char) => chars2.includes(char));
  }

  private calculateOverallHealth(issues: DiagnosticIssueSummary): number {
    let score = 100;

    // Deduct points for each type of issue
    score -= issues.structuralIssues.length * 15;
    score -= issues.isolatedCharacters.totalIsolated * 10;
    score -= issues.abandonedConflicts.totalAbandoned * 8;
    score -= issues.overloadedCharacters.totalOverloaded * 12;
    score -= issues.weakConnections.totalWeak * 5;
    score -= issues.redundancies.totalRedundant * 7;

    return Math.max(0, score);
  }

  private determineCriticalityLevel(
    score: number
  ):
    | "healthy"
    | "minor_issues"
    | "moderate_issues"
    | "major_issues"
    | "critical" {
    if (score >= 85) return "healthy";
    if (score >= 70) return "minor_issues";
    if (score >= 50) return "moderate_issues";
    if (score >= 30) return "major_issues";
    return "critical";
  }
}

import { logger } from "../utils/logger";

import { GeminiService } from "./gemini-service";
import {
  Station1TextAnalysis,
  type Station1Output,
} from "./station1-text-analysis";
import {
  Station2ConceptualAnalysis,
  type Station2Output,
} from "./station2-conceptual-analysis";
import {
  Station3NetworkBuilder,
  type Station3Output,
} from "./station3-network-builder";
import {
  Station4EfficiencyMetrics,
  type Station4Output,
} from "./station4-efficiency-metrics";
import {
  Station5DynamicSymbolicStylistic,
  type Station5Output,
} from "./station5-dynamic-symbolic-stylistic";
import {
  Station6Diagnostics,
  type Station6Output,
} from "./station6-diagnostics-treatment";
import {
  Station7Finalization,
  type Station7Output,
} from "./station7-finalization";

export interface OrchestrationConfig {
  geminiService: GeminiService;
  outputDirectory: string;
  enableCaching?: boolean;
  enableRetry?: boolean;
  maxRetries?: number;
  retryDelay?: number;
  enableProgressTracking?: boolean;
  enableDetailedLogging?: boolean;
}

export interface StationProgress {
  stationNumber: number;
  stationName: string;
  status: "pending" | "running" | "completed" | "failed" | "retrying";
  startTime?: number;
  endTime?: number;
  duration?: number;
  attempt?: number;
  error?: string;
}

export interface OrchestrationResult {
  success: boolean;
  stationOutputs: {
    station1?: Station1Output;
    station2?: Station2Output;
    station3?: Station3Output;
    station4?: Station4Output;
    station5?: Station5Output;
    station6?: Station6Output;
    station7?: Station7Output;
  };
  metadata: {
    totalExecutionTime: number;
    stationsCompleted: number;
    stationsFailed: number;
    startedAt: string;
    finishedAt: string;
    overallScore?: number;
    overallRating?: string;
  };
  progressLog: StationProgress[];
  errors: {
    station: number;
    error: string;
    timestamp: string;
  }[];
}

export class StationsOrchestrator {
  private readonly geminiService: GeminiService;
  private readonly outputDirectory: string;
  private readonly enableCaching: boolean;
  private readonly enableRetry: boolean;
  private readonly maxRetries: number;
  private readonly retryDelay: number;
  private readonly enableDetailedLogging: boolean;

  private progressLog: StationProgress[] = [];
  private errors: { station: number; error: string; timestamp: string }[] =
    [];

  constructor(config: OrchestrationConfig) {
    this.geminiService = config.geminiService;
    this.outputDirectory = config.outputDirectory;
    this.enableCaching = config.enableCaching ?? false;
    this.enableRetry = config.enableRetry ?? true;
    this.maxRetries = config.maxRetries ?? 3;
    this.retryDelay = config.retryDelay ?? 5000;
    this.enableDetailedLogging = config.enableDetailedLogging ?? true;
  }

  async execute(
    fullText: string,
    projectName = "untitled-project",
    options?: {
      startFromStation?: number;
      endAtStation?: number;
      skipStations?: number[];
    }
  ): Promise<OrchestrationResult> {
    const startTime = Date.now();
    const startFromStation = options?.startFromStation ?? 1;
    const endAtStation = options?.endAtStation ?? 7;
    const skipStations = new Set(options?.skipStations ?? []);

    logger.info("[Orchestrator] Starting comprehensive analysis pipeline", {
      projectName,
      textLength: fullText.length,
      startFromStation,
      endAtStation,
      skipStations: Array.from(skipStations),
    });

    const stationOutputs: OrchestrationResult["stationOutputs"] = {};
    let stationsCompleted = 0;
    let stationsFailed = 0;

    const allPreviousStationsData = new Map<number, unknown>();

    try {
      if (startFromStation <= 1 && endAtStation >= 1 && !skipStations.has(1)) {
        const station1Output = await this.executeStation<Station1Output>(
          1,
          "Text Analysis",
          async () => {
            const station1 = new Station1TextAnalysis(this.geminiService);
            const result = await station1.run({
              text: fullText,
              projectName,
            });
            return result.result as Station1Output;
          }
        );
        if (station1Output) {
          stationOutputs.station1 = station1Output;
          allPreviousStationsData.set(1, station1Output);
          stationsCompleted++;
        } else {
          stationsFailed++;
        }
        await this.delay(6000);
      }

      if (startFromStation <= 2 && endAtStation >= 2 && !skipStations.has(2)) {
        const station2Output = await this.executeStation<Station2Output>(
          2,
          "Conceptual Analysis",
          async () => {
            if (!stationOutputs.station1) {
              throw new Error("Station 1 output is required for Station 2");
            }
            const station2 = new Station2ConceptualAnalysis(this.geminiService);
            const result = await station2.run({
              text: fullText,
              station1Output: stationOutputs.station1,
            } as any);
            return result.result as Station2Output;
          }
        );
        if (station2Output) {
          stationOutputs.station2 = station2Output;
          allPreviousStationsData.set(2, station2Output);
          stationsCompleted++;
        } else {
          stationsFailed++;
        }
        await this.delay(6000);
      }

      if (startFromStation <= 3 && endAtStation >= 3 && !skipStations.has(3)) {
        const station3Output = await this.executeStation<Station3Output>(
          3,
          "Network Builder",
          async () => {
            if (!stationOutputs.station1 || !stationOutputs.station2) {
              throw new Error(
                "Station 1 and 2 outputs are required for Station 3"
              );
            }
            const station3 = new Station3NetworkBuilder(this.geminiService);
            const result = await station3.run({
              text: fullText,
              station1Output: stationOutputs.station1,
              station2Output: stationOutputs.station2,
            } as any);
            return result.result as Station3Output;
          }
        );
        if (station3Output) {
          stationOutputs.station3 = station3Output;
          allPreviousStationsData.set(3, station3Output);
          stationsCompleted++;
        } else {
          stationsFailed++;
        }
        await this.delay(6000);
      }

      if (startFromStation <= 4 && endAtStation >= 4 && !skipStations.has(4)) {
        const station4Output = await this.executeStation<Station4Output>(
          4,
          "Efficiency Metrics",
          async () => {
            if (!stationOutputs.station3) {
              throw new Error("Station 3 output is required for Station 4");
            }
            const station4 = new Station4EfficiencyMetrics(
              {
                stationId: "station4",
                name: "Efficiency Metrics",
                description: "Efficiency Metrics",
                cacheEnabled: this.enableCaching,
                performanceTracking: true,
                inputValidation: (input) => !!input,
                outputValidation: (output) => !!output,
              },
              this.geminiService
            );
            const result = await station4.execute({
              station3Output: stationOutputs.station3,
              originalText: fullText,
            });
            return result.output;
          }
        );
        if (station4Output) {
          stationOutputs.station4 = station4Output;
          allPreviousStationsData.set(4, station4Output);
          stationsCompleted++;
        } else {
          stationsFailed++;
        }
        await this.delay(6000);
      }

      if (startFromStation <= 5 && endAtStation >= 5 && !skipStations.has(5)) {
        const station5Output = await this.executeStation<Station5Output>(
          5,
          "Dynamic/Symbolic/Stylistic Analysis",
          async () => {
            if (!stationOutputs.station3 || !stationOutputs.station4) {
              throw new Error(
                "Station 3 and 4 outputs are required for Station 5"
              );
            }
            const station5 = new Station5DynamicSymbolicStylistic(
              {
                stationId: "station5",
                name: "Dynamic/Symbolic/Stylistic Analysis",
                description: "Dynamic/Symbolic/Stylistic Analysis",
                cacheEnabled: this.enableCaching,
                performanceTracking: true,
                inputValidation: (input) => !!input,
                outputValidation: (output) => !!output,
              },
              this.geminiService
            );
            const result = await station5.execute({
              conflictNetwork: stationOutputs.station3.conflictNetwork,
              station4Output: stationOutputs.station4,
              fullText,
            });
            return result.output;
          }
        );
        if (station5Output) {
          stationOutputs.station5 = station5Output;
          allPreviousStationsData.set(5, station5Output);
          stationsCompleted++;
        } else {
          stationsFailed++;
        }
        await this.delay(6000);
      }

      if (startFromStation <= 6 && endAtStation >= 6 && !skipStations.has(6)) {
        const station6Output = await this.executeStation<Station6Output>(
          6,
          "Diagnostics & Treatment",
          async () => {
            if (
              !stationOutputs.station1 ||
              !stationOutputs.station2 ||
              !stationOutputs.station3 ||
              !stationOutputs.station4 ||
              !stationOutputs.station5
            ) {
              throw new Error(
                "All previous station outputs are required for Station 6"
              );
            }
            const station6 = new Station6Diagnostics(this.geminiService);
            const result = await station6.execute(fullText, {
              station1: stationOutputs.station1,
              station2: stationOutputs.station2,
              station3: stationOutputs.station3,
              station4: stationOutputs.station4,
              station5: stationOutputs.station5,
            });
            return result;
          }
        );
        if (station6Output) {
          stationOutputs.station6 = station6Output;
          allPreviousStationsData.set(6, station6Output);
          stationsCompleted++;
        } else {
          stationsFailed++;
        }
        await this.delay(6000);
      }

      if (startFromStation <= 7 && endAtStation >= 7 && !skipStations.has(7)) {
        const station7Output = await this.executeStation<Station7Output>(
          7,
          "Finalization & Visualization",
          async () => {
            if (!stationOutputs.station3 || !stationOutputs.station6) {
              throw new Error(
                "Station 3 and 6 outputs are required for Station 7"
              );
            }
            const station7 = new Station7Finalization(
              {
                stationId: "station7",
                name: "Finalization & Visualization",
                description: "Finalization & Visualization",
                cacheEnabled: this.enableCaching,
                performanceTracking: true,
                inputValidation: (input) => !!input,
                outputValidation: (output) => !!output,
              },
              this.geminiService,
              this.outputDirectory
            );
            const result = await station7.execute({
              conflictNetwork: stationOutputs.station3.conflictNetwork,
              station6Output: stationOutputs.station6,
              allPreviousStationsData,
            });
            return result.output;
          }
        );
        if (station7Output) {
          stationOutputs.station7 = station7Output;
          allPreviousStationsData.set(7, station7Output);
          stationsCompleted++;
        } else {
          stationsFailed++;
        }
      }

      const endTime = Date.now();
      const totalExecutionTime = endTime - startTime;

      const overallScore = stationOutputs.station7?.scoreMatrix?.overall;
      const overallRating =
        stationOutputs.station7?.finalReport?.overallAssessment?.rating;

      logger.info("[Orchestrator] Pipeline execution completed", {
        stationsCompleted,
        stationsFailed,
        totalExecutionTime,
        overallScore,
        overallRating,
      });

      return {
        success: stationsFailed === 0,
        stationOutputs,
        metadata: {
          totalExecutionTime,
          stationsCompleted,
          stationsFailed,
          startedAt: new Date(startTime).toISOString(),
          finishedAt: new Date(endTime).toISOString(),
          ...(overallScore !== undefined && { overallScore }),
          ...(overallRating !== undefined && { overallRating }),
        },
        progressLog: this.progressLog,
        errors: this.errors,
      };
    } catch (error) {
      logger.error("[Orchestrator] Fatal error in pipeline execution:", error);

      const endTime = Date.now();
      return {
        success: false,
        stationOutputs,
        metadata: {
          totalExecutionTime: endTime - startTime,
          stationsCompleted,
          stationsFailed: stationsFailed + 1,
          startedAt: new Date(startTime).toISOString(),
          finishedAt: new Date(endTime).toISOString(),
        },
        progressLog: this.progressLog,
        errors: this.errors,
      };
    }
  }

  private async executeStation<T>(
    stationNumber: number,
    stationName: string,
    executor: () => Promise<T>
  ): Promise<T | null> {
    const progress: StationProgress = {
      stationNumber,
      stationName,
      status: "pending",
      attempt: 0,
    };
    this.progressLog.push(progress);

    let lastError: Error | null = null;

    for (
      let attempt = 1;
      attempt <= (this.enableRetry ? this.maxRetries : 1);
      attempt++
    ) {
      try {
        progress.status = attempt > 1 ? "retrying" : "running";
        progress.attempt = attempt;
        progress.startTime = Date.now();

        if (this.enableDetailedLogging) {
          logger.info(
            `[Orchestrator] Executing Station ${stationNumber}: ${stationName}`,
            {
              attempt,
              maxAttempts: this.maxRetries,
            }
          );
        }

        const result = await executor();

        progress.endTime = Date.now();
        progress.duration = progress.endTime - progress.startTime;
        progress.status = "completed";

        if (this.enableDetailedLogging) {
          logger.info(
            `[Orchestrator] Station ${stationNumber} completed successfully`,
            {
              duration: progress.duration,
            }
          );
        }

        return result;
      } catch (error) {
        lastError = error instanceof Error ? error : new Error(String(error));
        progress.error = lastError.message;

        logger.error(
          `[Orchestrator] Station ${stationNumber} failed (attempt ${attempt}/${this.maxRetries})`,
          {
            error: lastError.message,
            willRetry: attempt < this.maxRetries && this.enableRetry,
          }
        );

        this.errors.push({
          station: stationNumber,
          error: lastError.message,
          timestamp: new Date().toISOString(),
        });

        if (attempt < this.maxRetries && this.enableRetry) {
          await this.delay(this.retryDelay * attempt);
        }
      }
    }

    progress.status = "failed";
    progress.endTime = Date.now();
    progress.duration = progress.endTime - (progress.startTime ?? 0);

    logger.error(
      `[Orchestrator] Station ${stationNumber} failed after ${this.maxRetries} attempts`,
      {
        lastError: lastError?.message,
      }
    );

    return null;
  }

  private delay(ms: number): Promise<void> {
    return new Promise((resolve) => setTimeout(resolve, ms));
  }

  getProgressLog(): StationProgress[] {
    return [...this.progressLog];
  }

  getErrors(): { station: number; error: string; timestamp: string }[] {
    return [...this.errors];
  }

  getStationStatus(): Record<string, string> {
    const status: Record<string, string> = {};
    this.progressLog.forEach((progress) => {
      status[`station${progress.stationNumber}`] = progress.status;
    });
    return status;
  }

  clearProgressLog(): void {
    this.progressLog = [];
    this.errors = [];
  }
}

