      overallHealthScore: Math.min(100, efficiencyScore),
      healthBreakdown: {
        characterDevelopment: Math.min(100, efficiencyScore),
        plotCoherence: Math.min(100, efficiencyScore),
        structuralIntegrity: Math.min(100, efficiencyScore),
