  location: string;
  currentIssue: string;
  suggestedRewrite: string;
  reasoning: string;
  impact: number;
  priority: "must" | "should" | "could";
}

export interface ScoreMatrix {
  foundation: number;
  conceptual: number;
  conflictNetwork: number;
  efficiency: number;
  dynamicSymbolic: number;
  diagnostics: number;
  overall: number;
}

export interface Station7Output {
  finalReport: {
