    };
    strengthsAnalysis: string[];
    weaknessesIdentified: string[];
    opportunitiesForImprovement: string[];
    threatsToCoherence: string[];
    finalRecommendations: {
      mustDo: string[];
      shouldDo: string[];
      couldDo: string[];
    };
