export interface ChunkOptions {
  maxChunkSize?: number;
  overlap?: number;
}

export interface TextChunk {
  text: string;
  index: number;
  start: number;
  end: number;
}

export function chunkText(text: string, options?: ChunkOptions): TextChunk[] {
  const maxSize = options?.maxChunkSize ?? 1000;
  const overlap = options?.overlap ?? 100;
  const chunks: TextChunk[] = [];

  let start = 0;
  let index = 0;

  while (start < text.length) {
    const end = Math.min(start + maxSize, text.length);
    chunks.push({
      text: text.substring(start, end),
      index: index++,
      start,
      end,
    });
    start += maxSize - overlap;
  }

  return chunks;
}

export default {
  chunkText,
};

export interface LogLevel {
  ERROR: "error";
  WARN: "warn";
  INFO: "info";
  DEBUG: "debug";
}

export class Logger {
  private logLevel: keyof LogLevel = "INFO";

  setLevel(level: keyof LogLevel) {
    this.logLevel = level;
  }

  private shouldLog(level: keyof LogLevel): boolean {
    const levels = ["DEBUG", "INFO", "WARN", "ERROR"];
    return levels.indexOf(level) >= levels.indexOf(this.logLevel);
  }

  private formatMessage(level: string, message: string, meta?: any): string {
    const timestamp = new Date().toISOString();
    const metaStr = meta ? ` ${JSON.stringify(meta)}` : "";
    return `[${timestamp}] ${level.toUpperCase()}: ${message}${metaStr}`;
  }

  error(message: string, meta?: any) {
    if (this.shouldLog("ERROR")) {
      console.error(this.formatMessage("error", message, meta));
    }
  }

  warn(message: string, meta?: any) {
    if (this.shouldLog("WARN")) {
      console.warn(this.formatMessage("warn", message, meta));
    }
  }

  info(message: string, meta?: any) {
    if (this.shouldLog("INFO")) {
      console.info(this.formatMessage("info", message, meta));
    }
  }

  debug(message: string, meta?: any) {
    if (this.shouldLog("DEBUG")) {
      console.debug(this.formatMessage("debug", message, meta));
    }
  }
}

export const logger = new Logger();
export default logger;

export function toText(content: { raw?: unknown } | string): string {
  if (typeof content === "string") {
    return content.trim();
  }
  if (content && typeof content === "object" && "raw" in content) {
    return String(content.raw ?? "").trim();
  }
  return "";
}

export function safeSub(text: string, start: number, end: number): string {
  if (!text || typeof text !== "string") {
    return "";
  }
  return text.substring(start, Math.min(end, text.length));
}

