interface ConflictDynamicsContext {
  originalText?: string;
  analysisReport?: any;
  characters?: any[];
  plotPoints?: any[];
  conflictTypes?: string[]; // ['internal', 'interpersonal', 'societal', 'man-vs-nature']
  analyzeEvolution?: boolean;
  trackIntensity?: boolean;
  identifyResolution?: boolean;
}

/**
 * Conflict Dynamics Agent - وكيل ديناميكيات الصراع
 * يطبق النمط القياسي: RAG → Self-Critique → Constitutional → Uncertainty → Hallucination → Debate
 * إخراج نصي فقط - لا JSON
 */
export class ConflictDynamicsAgent extends BaseAgent {
  constructor() {
    super(
      "ConflictAnalyzer AI",
      TaskType.CONFLICT_DYNAMICS,
      CONFLICT_DYNAMICS_AGENT_CONFIG.systemPrompt ?? ""
    );

    this.confidenceFloor = 0.82;
  }

  protected buildPrompt(input: StandardAgentInput): string {
    const { input: taskInput, context } = input;
    const ctx = context as ConflictDynamicsContext;

    const originalText = ctx?.originalText ?? "";
    const characters = ctx?.characters ?? [];
    const plotPoints = ctx?.plotPoints ?? [];
    const conflictTypes = ctx?.conflictTypes ?? ["internal", "interpersonal"];
    const analyzeEvolution = ctx?.analyzeEvolution ?? true;
    const trackIntensity = ctx?.trackIntensity ?? true;
    const identifyResolution = ctx?.identifyResolution ?? true;

    let prompt = `مهمة تحليل ديناميكيات الصراع الدرامي\n\n`;

    if (originalText) {
      prompt += `النص المراد تحليله:\n${originalText.substring(0, 2500)}...\n\n`;
    }

    if (characters.length > 0) {
      prompt += `الشخصيات الرئيسية:\n`;
      characters.slice(0, 5).forEach((char: any, idx: number) => {
        const charName =
          typeof char === "string" ? char : char.name ?? `شخصية ${idx + 1}`;
        prompt += `${idx + 1}. ${charName}\n`;
      });
      prompt += "\n";
    }

    if (plotPoints.length > 0) {
      prompt += `نقاط الحبكة الرئيسية:\n`;
      plotPoints.slice(0, 4).forEach((point: any, idx: number) => {
        const pointText =
          typeof point === "string"
            ? point
            : point.description ?? `نقطة ${idx + 1}`;
        prompt += `${idx + 1}. ${pointText}\n`;
      });
      prompt += "\n";
    }

    prompt += `أنواع الصراعات المطلوب تحليلها: ${conflictTypes.map(this.translateConflictType).join("، ")}\n`;
    prompt += `تحليل التطور: ${analyzeEvolution ? "نعم" : "لا"}\n`;
    prompt += `تتبع الشدة: ${trackIntensity ? "نعم" : "لا"}\n`;
    prompt += `تحديد الحل: ${identifyResolution ? "نعم" : "لا"}\n\n`;

    prompt += `المهمة المطلوبة:\n${taskInput}\n\n`;

    prompt += `التعليمات:

1. **نظرة عامة** (2-3 جمل): لخص الطبيعة العامة للصراعات في النص

2. **الصراعات الرئيسية**: حدد وحلل كل صراع رئيسي
   لكل صراع:
   - **نوع الصراع**: (داخلي، بين شخصي، مجتمعي، إلخ)
   - **الأطراف المتصارعة**: من هم المتورطون وما هي مواقفهم
   - **جذور الصراع**: ما الذي يسبب أو يغذي هذا الصراع
   - **الرهانات**: ما الذي على المحك، ما الذي يمكن أن يُفقد أو يُكسب
   - **الأدلة النصية**: أمثلة محددة من النص توضح الصراع

${
  analyzeEvolution
    ? `3. **تطور الصراع**: كيف يتطور كل صراع عبر النص
   - نقطة البداية
   - التصعيد والذروة
   - لحظات التحول الحاسمة`
    : ""
}

${
  trackIntensity
    ? `4. **شدة الصراع**: تقييم مستوى الشدة والتوتر
   - المستوى الحالي (منخفض، متوسط، عالي، حرج)
   - التقلبات والتذبذبات
   - المشاهد ذات الشدة القصوى`
    : ""
}

${
  identifyResolution
    ? `5. **الحل أو الخاتمة**: كيف يُحل أو يُختم كل صراع
   - نوع الحل (انتصار، هزيمة، تسوية، عدم حل)
   - رضا الأطراف
   - التأثير على الشخصيات`
    : ""
}

6. **التشابك والتفاعل**: كيف تتشابك الصراعات المختلفة وتؤثر على بعضها

7. **الوظيفة الدرامية**: كيف تخدم هذه الصراعات البنية الدرامية والثيمات

8. **التقييم النهائي**: مدى فعالية وعمق الصراعات في تحريك القصة

اكتب بشكل نصي تحليلي واضح مع أمثلة نصية محددة.
لا تستخدم JSON أو جداول. نص تحليلي درامي مباشر.`;

    return prompt;
  }

  protected override async postProcess(
    output: StandardAgentOutput
  ): Promise<StandardAgentOutput> {
    const processedText = this.cleanupConflictText(output.text);

    const conflictIdentification =
      await this.assessConflictIdentification(processedText);
    const analysisDepth = await this.assessAnalysisDepth(processedText);
    const evidenceQuality = await this.assessEvidenceQuality(processedText);
    const insightfulness = await this.assessInsightfulness(processedText);

    const qualityScore =
      conflictIdentification * 0.3 +
      analysisDepth * 0.3 +
      evidenceQuality * 0.2 +
      insightfulness * 0.2;

    const adjustedConfidence = output.confidence * 0.5 + qualityScore * 0.5;

    return {
      ...output,
      text: processedText,
      confidence: adjustedConfidence,
      notes: this.generateConflictNotes(
        output,
        conflictIdentification,
        analysisDepth,
        evidenceQuality,
        insightfulness
      ),
      metadata: {
        ...output.metadata,
        conflictAnalysisQuality: {
          overall: qualityScore,
          conflictIdentification,
          analysisDepth,
          evidenceQuality,
          insightfulness,
        },
        conflictsIdentified: this.countConflicts(processedText),
        conflictTypes: this.identifyConflictTypes(processedText),
        intensityLevel: this.assessIntensityLevel(processedText),
      },
    };
  }

  private cleanupConflictText(text: string): string {
    text = text.replace(/```json[\s\S]*?```/g, "");
    text = text.replace(/```[\s\S]*?```/g, "");
    text = text.replace(/\{[\s\S]*?\}/g, (match) => {
      if (match.includes('"') && match.includes(":")) return "";
      return match;
    });

    return text.replace(/\n{3,}/g, "\n\n").trim();
  }

  private async assessConflictIdentification(text: string): Promise<number> {
    let score = 0.5;

    const conflictTerms = [
      "صراع",
      "نزاع",
      "خلاف",
      "مواجهة",
      "تضارب",
      "تعارض",
      "صدام",
      "احتكاك",
    ];
    // SECURITY FIX: Use safe RegExp utility to prevent injection
    const termCount = safeCountMultipleTerms(text, conflictTerms);
    score += Math.min(0.25, termCount * 0.02);

    const typeTerms = ["داخلي", "خارجي", "بين شخصي", "مجتمعي", "فردي"];
    // SECURITY FIX: Use safe RegExp utility to prevent injection
    const typeCount = safeCountMultipleTerms(text, typeTerms);
    score += Math.min(0.15, typeCount * 0.05);

    if (text.includes("الأطراف") || text.includes("المتصارع")) score += 0.1;

    return Math.min(1, score);
  }

  private async assessAnalysisDepth(text: string): Promise<number> {
    let score = 0.5;

    const depthIndicators = [
      "جذور",
      "أسباب",
      "يؤدي إلى",
      "ينتج عن",
      "يتطور",
      "يتصاعد",
      "ذروة",
      "حل",
    ];
    // SECURITY FIX: Use safe RegExp utility to prevent injection
    const depthCount = safeCountMultipleTerms(text, depthIndicators);
    score += Math.min(0.25, depthCount * 0.025);

    const hasCausality =
      text.includes("لأن") || text.includes("بسبب") || text.includes("نتيجة");
    if (hasCausality) score += 0.15;

    if (text.length > 1500) score += 0.1;

    return Math.min(1, score);
  }

  private async assessEvidenceQuality(text: string): Promise<number> {
    let score = 0.6;

    const evidenceMarkers = [
      "مثل",
      "كما في",
      "نرى",
      "يظهر",
      "في المشهد",
      "عندما",
      "حيث",
    ];
    // SECURITY FIX: Use safe RegExp utility to prevent injection
    const evidenceCount = safeCountMultipleTerms(text, evidenceMarkers);
    score += Math.min(0.25, evidenceCount * 0.025);

    const hasQuotes = (text.match(/["«]/g) ?? []).length;
    score += Math.min(0.15, hasQuotes * 0.015);

    return Math.min(1, score);
  }

  private async assessInsightfulness(text: string): Promise<number> {
    let score = 0.5;

    const insightWords = [
      "يكشف",
      "يوضح",
      "يعكس",
      "الأهمية",
      "التأثير",
      "الدلالة",
      "يشير",
      "نستنتج",
    ];
    // SECURITY FIX: Use safe RegExp utility to prevent injection
    const insightCount = safeCountMultipleTerms(text, insightWords);
    score += Math.min(0.3, insightCount * 0.03);

    const hasFunctionAnalysis =
      text.includes("وظيفة") || text.includes("دور") || text.includes("يخدم");
    if (hasFunctionAnalysis) score += 0.2;

    return Math.min(1, score);
  }

  private countConflicts(text: string): number {
    const conflictMarkers = text.match(
      /الصراع الأول|الصراع الثاني|الصراع الرئيسي|صراع|نزاع رئيسي/gi
    );
    return conflictMarkers ? Math.min(conflictMarkers.length, 8) : 0;
  }

  private identifyConflictTypes(text: string): string[] {
    const types: string[] = [];
    if (text.includes("داخلي") || text.includes("النفس")) types.push("داخلي");
    if (text.includes("بين شخصي") || text.includes("شخصية"))
      types.push("بين شخصي");
    if (text.includes("مجتمعي") || text.includes("اجتماعي"))
      types.push("مجتمعي");
    if (text.includes("الطبيعة") || text.includes("البيئة"))
      types.push("ضد الطبيعة");
    if (text.includes("القدر") || text.includes("المصير"))
      types.push("ضد القدر");
    return types;
  }

  private assessIntensityLevel(text: string): string {
    const highIntensity = ["حاد", "شديد", "عنيف", "حرج", "ذروة", "انفجار"];
    const mediumIntensity = ["متوسط", "متصاعد", "متزايد"];
    const lowIntensity = ["هادئ", "خفيف", "كامن", "مكبوت"];

    // SECURITY FIX: Use safe string matching to prevent ReDoS
    const highCount = highIntensity.reduce((count, term) => {
      const occurrences =
        text.toLowerCase().split(term.toLowerCase()).length - 1;
      return count + occurrences;
    }, 0);
    const mediumCount = mediumIntensity.reduce((count, term) => {
      const occurrences =
        text.toLowerCase().split(term.toLowerCase()).length - 1;
      return count + occurrences;
    }, 0);
    const lowCount = lowIntensity.reduce((count, term) => {
      const occurrences =
        text.toLowerCase().split(term.toLowerCase()).length - 1;
      return count + occurrences;
    }, 0);

    if (highCount > mediumCount && highCount > lowCount) return "عالي";
    if (lowCount > mediumCount && lowCount > highCount) return "منخفض";
    return "متوسط";
  }

  private generateConflictNotes(
    output: StandardAgentOutput,
    identification: number,
    depth: number,
    evidence: number,
    insight: number
  ): string[] {
    const notes: string[] = [];

    const avg = (identification + depth + evidence + insight) / 4;
    if (avg > 0.8) notes.push("تحليل صراعات ممتاز");
    else if (avg > 0.65) notes.push("تحليل جيد");
    else notes.push("يحتاج عمق أكبر");

    if (identification > 0.8) notes.push("تحديد دقيق للصراعات");
    if (depth > 0.8) notes.push("عمق تحليلي قوي");
    if (evidence > 0.75) notes.push("أدلة نصية جيدة");
    if (insight > 0.75) notes.push("رؤى ثاقبة");

    if (identification < 0.6) notes.push("يحتاج تحديد أوضح");
    if (depth < 0.5) notes.push("يحتاج تحليل أعمق");
    if (evidence < 0.5) notes.push("يحتاج مزيد من الأدلة");

    if (output.notes) notes.push(...output.notes);

    return notes;
  }

  private translateConflictType(type: string): string {
    const types: Record<string, string> = {
      internal: "داخلي (الإنسان ضد نفسه)",
      interpersonal: "بين شخصي (شخص ضد شخص)",
      societal: "مجتمعي (فرد ضد مجتمع)",
      "man-vs-nature": "ضد الطبيعة",
      "man-vs-fate": "ضد القدر",
      "man-vs-technology": "ضد التكنولوجيا",
      "man-vs-supernatural": "ضد الخارق",
    };
    return types[type] ?? type;
  }

  protected override async getFallbackResponse(
    _input: StandardAgentInput
  ): Promise<string> {
    return `نظرة عامة:
النص يحتوي على عدة مستويات من الصراعات التي تحرك الأحداث وتطور الشخصيات.

الصراع الرئيسي:
[نوع الصراع] - يتمحور حول [موضوع عام يحتاج تحديد أدق]
الأطراف: [شخصيات متصارعة تحتاج تعريف]
الرهانات: [ما على المحك]
الأدلة: [أمثلة من النص تحتاج تحديد]

تطور الصراع:
يبدأ الصراع بـ[نقطة البداية] ويتصاعد عبر [مراحل] حتى يصل إلى [ذروة أو حل].

الوظيفة الدرامية:
هذه الصراعات تخدم [الغرض الدرامي] وتساهم في [التأثير على الحبكة].

ملاحظة: يُرجى تفعيل الخيارات المتقدمة وتوفير المزيد من التفاصيل عن الشخصيات والأحداث للحصول على تحليل صراعات أكثر دقة وعمقاً مع أمثلة نصية محددة.`;
  }
}

export const conflictDynamicsAgent = new ConflictDynamicsAgent();

import { safeCountMultipleTerms } from "@/lib/security/safe-regexp";
import { TaskType } from "@core/types";

import { BaseAgent } from "../shared/BaseAgent";
import {
  StandardAgentInput,
  StandardAgentOutput,
} from "../shared/standardAgentPattern";

import { CREATIVE_AGENT_CONFIG } from "./agent";
import { CREATIVE_MODE_INSTRUCTIONS } from "./instructions";

/**
 * Creative Development Agent - وكيل التطوير الإبداعي
 * يطبق النمط القياسي: RAG → Self-Critique → Constitutional → Uncertainty → Hallucination → Debate
 * إخراج نصي فقط - لا JSON
 */
export class CreativeAgent extends BaseAgent {
  constructor() {
    super(
      "CreativeVision AI",
      TaskType.CREATIVE,
      CREATIVE_AGENT_CONFIG.systemPrompt ?? ""
    );

    // Set agent-specific confidence floor
    this.confidenceFloor = 0.75;
  }

  /**
   * Build prompt for creative development task
   */
  protected buildPrompt(input: StandardAgentInput): string {
    const { input: taskInput, context } = input;

    // Extract relevant context
    const contextObj =
      typeof context === "object" && context !== null ? context : {};
    const originalText = (contextObj as any)?.originalText ?? "";
    const developmentFocus = (contextObj as any)?.developmentFocus ?? "general";
    const creativeConstraints = (contextObj as any)?.constraints ?? [];
    const targetAudience = (contextObj as any)?.targetAudience ?? "عام";
    const creativeGoals = (contextObj as any)?.goals ?? [];

    // Build structured prompt
    let prompt = `${CREATIVE_MODE_INSTRUCTIONS}\n\n`;

    // Add original text if available
    if (originalText) {
      prompt += `النص الأصلي للتطوير:\n${originalText}\n\n`;
    }

    // Add development focus
    prompt += `محور التطوير الإبداعي: ${this.translateFocus(developmentFocus)}\n\n`;

    // Add creative goals
    if (creativeGoals.length > 0) {
      prompt += `الأهداف الإبداعية:\n`;
      creativeGoals.forEach((goal: string, index: number) => {
        prompt += `${index + 1}. ${goal}\n`;
      });
      prompt += "\n";
    }

    // Add constraints if any
    if (creativeConstraints.length > 0) {
      prompt += `القيود الإبداعية:\n`;
      creativeConstraints.forEach((constraint: string) => {
        prompt += `- ${constraint}\n`;
      });
      prompt += "\n";
    }

    // Add target audience
    prompt += `الجمهور المستهدف: ${targetAudience}\n\n`;

    // Add the specific task
    prompt += `المهمة المحددة:\n${taskInput}\n\n`;

    // Add generation instructions
    prompt += `قدم تطويراً إبداعياً شاملاً يتضمن:

1. **تحليل إبداعي** (3-4 جمل): رؤية نقدية للعناصر الإبداعية الحالية
2. **مقترحات التطوير**: أفكار محددة وقابلة للتطبيق
3. **أمثلة تطبيقية**: نماذج عملية للتحسينات المقترحة
4. **التأثير المتوقع**: كيف ستحسن هذه التطويرات من جودة العمل

اكتب بشكل نصي واضح ومباشر، دون استخدام JSON أو تنسيقات معقدة.`;

    return prompt;
  }

  /**
   * Post-process the creative output
   */
  protected override async postProcess(
    output: StandardAgentOutput
  ): Promise<StandardAgentOutput> {
    // Clean and structure the output
    const processedText = this.cleanupCreativeText(output.text);

    // Assess creative quality
    const creativityScore = await this.assessCreativity(processedText);
    const practicalityScore = await this.assessPracticality(processedText);

    // Balance confidence between creativity and practicality
    const adjustedConfidence =
      output.confidence * 0.5 +
      creativityScore * 0.25 +
      practicalityScore * 0.25;

    // Generate enhanced notes
    const enhancedNotes = this.generateCreativeNotes(
      output,
      creativityScore,
      practicalityScore
    );

    return {
      ...output,
      text: processedText,
      confidence: adjustedConfidence,
      notes: enhancedNotes,
      metadata: {
        ...output.metadata,
        creativityScore,
        practicalityScore,
        innovationLevel: this.calculateInnovationLevel(creativityScore),
        implementationDifficulty:
          this.calculateImplementationDifficulty(practicalityScore),
      },
    };
  }

  /**
   * Clean up creative text and ensure proper formatting
   */
  private cleanupCreativeText(text: string): string {
    // Remove any JSON or code block artifacts
    text = text.replace(/```json[\s\S]*?```/g, "");
    text = text.replace(/```[\s\S]*?```/g, "");
    text = text.replace(/\{[\s\S]*?\}/g, (match) => {
      // Keep curly braces only if they're part of natural text
      if (match.includes('"') || match.includes(":")) return "";
      return match;
    });

    // Structure the output with clear sections
    const sections = this.extractSections(text);

    let structured = "";

    // Add creative analysis section
    if (sections.analysis) {
      structured += `تحليل إبداعي:\n${sections.analysis}\n\n`;
    }

    // Add development proposals
    if (sections.proposals) {
      structured += `مقترحات التطوير:\n${sections.proposals}\n\n`;
    }

    // Add practical examples
    if (sections.examples) {
      structured += `أمثلة تطبيقية:\n${sections.examples}\n\n`;
    }

    // Add expected impact
    if (sections.impact) {
      structured += `التأثير المتوقع:\n${sections.impact}\n\n`;
    }

    // If no clear sections, return cleaned original
    if (!structured) {
      structured = text;
    }

    // Final cleanup
    structured = structured.replace(/\n{3,}/g, "\n\n").trim();

    return structured;
  }

  /**
   * Extract sections from text
   */
  private extractSections(text: string): Record<string, string> {
    const sections: Record<string, string> = {};

    // Patterns for different sections
    const patterns = {
      analysis:
        /(?:تحليل|التحليل|رؤية نقدية|تقييم)[\s\S]*?(?=مقترحات|أمثلة|التأثير|$)/i,
      proposals:
        /(?:مقترحات|اقتراحات|التطوير|تطويرات)[\s\S]*?(?=أمثلة|التأثير|$)/i,
      examples: /(?:أمثلة|نماذج|تطبيقات|مثال)[\s\S]*?(?=التأثير|$)/i,
      impact: /(?:التأثير|النتائج|المخرجات|الأثر)[\s\S]*?$/i,
    };

    for (const [key, pattern] of Object.entries(patterns)) {
      const match = text.match(pattern);
      if (match) {
        sections[key] = match[0].replace(/^[^\n]*\n/, "").trim();
      }
    }

    // If no sections found, try to split by paragraphs
    if (Object.keys(sections).length === 0) {
      const paragraphs = text.split("\n\n").filter((p) => p.trim());
      if (paragraphs.length >= 2 && paragraphs[0]) {
        sections.analysis = paragraphs[0];
        sections.proposals = paragraphs.slice(1).join("\n\n");
      }
    }

    return sections;
  }

  /**
   * Assess creativity score
   */
  private async assessCreativity(text: string): Promise<number> {
    let score = 0.5; // Base score

    // Check for innovative keywords
    const innovativeWords = [
      "مبتكر",
      "جديد",
      "فريد",
      "أصيل",
      "إبداعي",
      "متميز",
      "رائد",
    ];
    // SECURITY FIX: Use safe RegExp utility to prevent injection
    const innovationCount = safeCountMultipleTerms(text, innovativeWords);
    score += Math.min(0.2, innovationCount * 0.02);

    // Check for multiple perspectives
    const perspectiveMarkers = [
      "من جهة",
      "من ناحية",
      "بالإضافة",
      "كما",
      "أيضاً",
    ];
    // SECURITY FIX: Use safe RegExp utility to prevent injection
    const perspectiveCount = safeCountMultipleTerms(text, perspectiveMarkers);
    score += Math.min(0.15, perspectiveCount * 0.03);

    // Check for concrete examples
    if (text.includes("مثال") || text.includes("مثلاً")) {
      score += 0.1;
    }

    // Check for depth (longer, detailed explanations)
    if (text.length > 1500) score += 0.05;

    return Math.min(1, score);
  }

  /**
   * Assess practicality score
   */
  private async assessPracticality(text: string): Promise<number> {
    let score = 0.6; // Base score for practicality

    // Check for actionable language
    const actionableWords = ["يمكن", "ينبغي", "يجب", "خطوة", "تطبيق", "تنفيذ"];
    // SECURITY FIX: Use safe RegExp utility to prevent injection
    const actionableCount = safeCountMultipleTerms(text, actionableWords);
    score += Math.min(0.2, actionableCount * 0.02);

    // Check for specific details
    const hasNumbers = /\d+/.test(text);
    const hasSteps =
      text.includes("أولاً") || text.includes("ثانياً") || /\d\./.test(text);
    if (hasNumbers) score += 0.05;
    if (hasSteps) score += 0.1;

    // Check for realistic constraints mentioned
    const constraintWords = ["تحدي", "صعوبة", "يتطلب", "احتياج", "موارد"];
    const hasConstraints = constraintWords.some((word) => text.includes(word));
    if (hasConstraints) score += 0.05;

    return Math.min(1, score);
  }

  /**
   * Calculate innovation level
   */
  private calculateInnovationLevel(creativityScore: number): string {
    if (creativityScore > 0.8) return "عالي جداً";
    if (creativityScore > 0.6) return "عالي";
    if (creativityScore > 0.4) return "متوسط";
    return "محافظ";
  }

  /**
   * Calculate implementation difficulty
   */
  private calculateImplementationDifficulty(practicalityScore: number): string {
    if (practicalityScore > 0.8) return "سهل";
    if (practicalityScore > 0.6) return "متوسط";
    if (practicalityScore > 0.4) return "صعب";
    return "صعب جداً";
  }

  /**
   * Generate creative notes
   */
  private generateCreativeNotes(
    output: StandardAgentOutput,
    creativityScore: number,
    practicalityScore: number
  ): string[] {
    const notes: string[] = [];

    // Creativity assessment
    if (creativityScore > 0.7) {
      notes.push("أفكار إبداعية متميزة");
    } else if (creativityScore > 0.5) {
      notes.push("مستوى إبداعي جيد");
    } else {
      notes.push("يحتاج المزيد من الابتكار");
    }

    // Practicality assessment
    if (practicalityScore > 0.7) {
      notes.push("قابل للتطبيق بسهولة");
    } else if (practicalityScore > 0.5) {
      notes.push("قابلية تطبيق معقولة");
    } else {
      notes.push("يحتاج دراسة للتطبيق");
    }

    // Overall confidence
    if (output.confidence > 0.8) {
      notes.push("ثقة عالية في الجودة");
    }

    // Add original notes if any
    if (output.notes) {
      notes.push(...output.notes.filter((note) => !notes.includes(note)));
    }

    return notes;
  }

  /**
   * Translate development focus
   */
  private translateFocus(focus: string): string {
    const focuses: Record<string, string> = {
      general: "تطوير عام",
      plot: "تطوير الحبكة",
      characters: "تطوير الشخصيات",
      dialogue: "تطوير الحوار",
      setting: "تطوير البيئة",
      theme: "تطوير المواضيع",
      style: "تطوير الأسلوب",
      structure: "تطوير البنية",
    };
    return focuses[focus] ?? focus;
  }

  /**
   * Generate fallback response for creative tasks
   */
  protected override async getFallbackResponse(
    input: StandardAgentInput
  ): Promise<string> {
    const focus =
      (typeof input.context === "object" && input.context?.developmentFocus) ??
      "general";

    return `تحليل إبداعي:
لتطوير ${this.translateFocus(focus)} في النص المقدم، يمكن التركيز على تعزيز العناصر الأساسية وإضافة عمق أكبر.

مقترحات التطوير:
- تعميق التفاصيل الوصفية
- تطوير الحوارات لتكون أكثر طبيعية
- إضافة طبقات من المعنى والرمزية
- تحسين البنية السردية

ملاحظة: يُرجى تفعيل الخيارات المتقدمة للحصول على تحليل أعمق ومقترحات أكثر تفصيلاً.`;
  }
}

