import { TaskType } from "@core/types";

import { BaseAgent } from "../shared/BaseAgent";
import {
  StandardAgentInput,
  StandardAgentOutput,
} from "../shared/standardAgentPattern";

import { LITERARY_QUALITY_ANALYZER_AGENT_CONFIG } from "./agent";
import { LITERARY_QUALITY_ANALYZER_INSTRUCTIONS } from "./instructions";

/**
 * Literary Quality Analyzer Agent - وكيل محلل الجودة الأدبية
 * الوحدة 10 - قاضي الجماليات الأدبية
 * يطبق النمط القياسي: RAG → Self-Critique → Constitutional → Uncertainty → Hallucination → Debate
 * إخراج نصي فقط - لا JSON
 */
export class LiteraryQualityAnalyzerAgent extends BaseAgent {
  constructor() {
    super(
      "AestheticsJudge AI",
      TaskType.LITERARY_QUALITY_ANALYZER,
      LITERARY_QUALITY_ANALYZER_AGENT_CONFIG.systemPrompt ?? ""
    );

    // Set agent-specific confidence floor (high due to critical nature)
    this.confidenceFloor = 0.88;
  }

  /**
   * Build prompt for literary quality analysis
   */
  protected buildPrompt(input: StandardAgentInput): string {
    const { input: taskInput, context } = input;

    // Extract relevant context
    const contextObj =
      typeof context === "object" && context !== null ? context : {};
    const originalText =
      ((contextObj)?.originalText as string) || "";
    const styleAnalysis =
      ((contextObj)?.styleAnalysis as string) || "";
    const thematicAnalysis =
      ((contextObj)?.thematicAnalysis as string) ||
      "";
    const previousStations =
      ((contextObj)?.previousStations as Record<
        string,
        string
      >) || {};

    // Build structured prompt
    let prompt = `${LITERARY_QUALITY_ANALYZER_INSTRUCTIONS}\n\n`;
    prompt += `[مهمة محلل الجودة الأدبية - AestheticsJudge AI]\n\n`;

    // Add original text
    if (originalText) {
      prompt += `النص الأصلي للتقييم:\n${originalText}\n\n`;
    }

    // Add style analysis if available
    if (styleAnalysis) {
      prompt += `تحليل الأسلوب السابق:\n${styleAnalysis}\n\n`;
    }

    // Add thematic analysis if available
    if (thematicAnalysis) {
      prompt += `التحليل الموضوعي:\n${thematicAnalysis}\n\n`;
    }

    // Add previous stations context
    if (Object.keys(previousStations).length > 0) {
      prompt += `سياق التحليلات السابقة:\n`;
      for (const [station, analysis] of Object.entries(previousStations)) {
        if (analysis) {
          prompt += `- ${station}: ${String(analysis).substring(0, 300)}...\n`;
        }
      }
      prompt += "\n";
    }

    // Add the specific task
    prompt += `المهمة المحددة:\n${taskInput}\n\n`;

    // Add generation instructions
    prompt += `قدم تقييماً أدبياً شاملاً يتضمن خمسة محاور أساسية:

1. **الجمال اللغوي والبلاغي:**
   - تقييم استخدام اللغة والأساليب البلاغية
   - تحليل بنية الجمل والإيقاع اللغوي
   - تقييم الصور البيانية والاستعارات

2. **الأصالة والابتكار الأسلوبي:**
   - تقييم تفرد الصوت الأدبي
   - كشف الكليشيهات والعبارات المبتذلة
   - تحديد عناصر الابتكار الأسلوبي

3. **التماسك السردي والبنيوي:**
   - تقييم سلامة الحبكة
   - تحليل الإيقاع والتدفق السردي
   - تقييم البنية الدرامية العامة

4. **التأثير العاطفي والفني:**
   - تقييم القدرة على إثارة المشاعر
   - تحديد اللحظات العاطفية المؤثرة
   - قياس عمق الصدى العاطفي

5. **المقارنة بالمعايير الأدبية:**
   - موقع العمل من المعايير الأدبية العالمية
   - نقاط القوة والضعف مقارنة بأعمال مشابهة
   - تقييم شامل للجودة الأدبية

قدم درجة تقييم (من 10) لكل محور مع تبرير واضح.
اكتب بلغة نقدية موضوعية ومهنية.
لا تستخدم تنسيق JSON أو كتل برمجية.`;

    return prompt;
  }

  /**
   * Post-process the literary quality output
   */
  protected override async postProcess(
    output: StandardAgentOutput
  ): Promise<StandardAgentOutput> {
    // Clean up text formatting
    const processedText = this.cleanupText(output.text);

    // Assess evaluation quality
    const qualityMetrics = await this.assessEvaluationQuality(processedText);

    // Adjust confidence based on quality
    const adjustedConfidence =
      output.confidence * 0.5 +
      qualityMetrics.linguisticDepth * 0.15 +
      qualityMetrics.criticalRigor * 0.2 +
      qualityMetrics.comprehensiveness * 0.15;

    return {
      ...output,
      text: processedText,
      confidence: Math.min(1, adjustedConfidence),
      notes: this.generateEvaluationNotes(output, qualityMetrics),
      metadata: {
        ...output.metadata,
        literaryEvaluationQuality: qualityMetrics,
        linguisticDepth: qualityMetrics.linguisticDepth,
        criticalRigor: qualityMetrics.criticalRigor,
        comprehensiveness: qualityMetrics.comprehensiveness,
      },
    };
  }

  /**
   * Clean up text formatting
   */
  private cleanupText(text: string): string {
    // Remove any JSON artifacts
    text = text.replace(/```json[\s\S]*?```/g, "");
    text = text.replace(/```[\s\S]*?```/g, "");
    text = text.replace(/\{[\s\S]*?"[^"]*"\s*:[\s\S]*?\}/g, "");

    // Remove excessive whitespace
    text = text.replace(/\n{3,}/g, "\n\n");
    text = text.trim();

    // Ensure proper section separation
    const lines = text.split("\n");
    const cleaned: string[] = [];

    for (const line of lines) {
      const trimmed = line.trim();
      if (trimmed) {
        cleaned.push(trimmed);
      } else if (cleaned.length > 0 && cleaned[cleaned.length - 1] !== "") {
        cleaned.push("");
      }
    }

    return cleaned.join("\n");
  }

  /**
   * Assess the quality of literary evaluation
   */
  private async assessEvaluationQuality(text: string): Promise<{
    linguisticDepth: number;
    criticalRigor: number;
    comprehensiveness: number;
    overallScore: number;
  }> {
    // Linguistic analysis indicators
    const linguisticTerms = [
      "استعارة",
      "تشبيه",
      "كناية",
      "بلاغة",
      "أسلوب",
      "إيقاع",
      "جملة",
      "تركيب",
      "صورة بيانية",
      "سجع",
      "جناس",
    ];
    const linguisticDepth = this.calculateCoverage(text, linguisticTerms);

    // Critical rigor indicators
    const criticalTerms = [
      "تقييم",
      "تحليل",
      "نقد",
      "ملاحظة",
      "قوة",
      "ضعف",
      "مقارنة",
      "معيار",
      "موضوعي",
      "دليل",
    ];
    const criticalRigor = this.calculateCoverage(text, criticalTerms);

    // Comprehensiveness indicators (checking all five pillars)
    const pillarTerms = [
      "لغوي",
      "بلاغي",
      "أصالة",
      "ابتكار",
      "تماسك",
      "سردي",
      "عاطفي",
      "فني",
      "معايير",
    ];
    const comprehensiveness = this.calculateCoverage(text, pillarTerms);

    const overallScore =
      (linguisticDepth + criticalRigor + comprehensiveness) / 3;

    return {
      linguisticDepth,
      criticalRigor,
      comprehensiveness,
      overallScore,
    };
  }

  /**
   * Calculate coverage of terms in text
   */
  private calculateCoverage(text: string, terms: string[]): number {
    const lowerText = text.toLowerCase();
    let matchCount = 0;

    for (const term of terms) {
      if (lowerText.includes(term.toLowerCase())) {
        matchCount++;
      }
    }

    return Math.min(1, (matchCount / terms.length) * 1.5);
  }

  /**
   * Check for clichés in text
   */
  private detectClicheAnalysis(text: string): boolean {
    const clicheIndicators = [
      "كليشيه",
      "مبتذل",
      "مكرر",
      "نمطي",
      "تقليدي",
      "شائع",
    ];

    return clicheIndicators.some((indicator) =>
      text.toLowerCase().includes(indicator)
    );
  }

  /**
   * Generate notes about the evaluation
   */
  private generateEvaluationNotes(
    output: StandardAgentOutput,
    qualityMetrics: {
      linguisticDepth: number;
      criticalRigor: number;
      comprehensiveness: number;
      overallScore: number;
    }
  ): string[] {
    const notes: string[] = [];

    // Confidence assessment
    if (output.confidence > 0.9) {
      notes.push("ثقة عالية في التقييم الأدبي");
    } else if (output.confidence > 0.75) {
      notes.push("ثقة جيدة في التقييم");
    } else {
      notes.push("ثقة متوسطة - يُنصح بمراجعة نقدية إضافية");
    }

    // Linguistic depth
    if (qualityMetrics.linguisticDepth > 0.7) {
      notes.push("تحليل لغوي وبلاغي عميق");
    } else if (qualityMetrics.linguisticDepth < 0.4) {
      notes.push("يمكن تعزيز التحليل اللغوي");
    }

    // Critical rigor
    if (qualityMetrics.criticalRigor > 0.7) {
      notes.push("دقة نقدية عالية");
    } else if (qualityMetrics.criticalRigor < 0.4) {
      notes.push("يمكن تعميق الحجج النقدية");
    }

    // Comprehensiveness
    if (qualityMetrics.comprehensiveness > 0.8) {
      notes.push("تغطية شاملة للمحاور الخمسة");
    }

    // Cliché detection
    if (this.detectClicheAnalysis(output.text)) {
      notes.push("تم تضمين تحليل الكليشيهات");
    }

    // Add original notes
    if (output.notes) {
      notes.push(...output.notes);
    }

    return notes;
  }

  /**
   * Generate fallback response specific to literary quality analysis
   */
  protected override async getFallbackResponse(
    _input: StandardAgentInput
  ): Promise<string> {
    return `التقييم الأدبي الأولي:

بناءً على النص المقدم، يمكن تقديم ملاحظات أولية حول الجودة الأدبية:

**1. الجمال اللغوي والبلاغي:**
- النص يحتاج إلى تحليل أعمق للأساليب البلاغية المستخدمة
- تقييم أولي: يتطلب مراجعة تفصيلية

**2. الأصالة والابتكار:**
- يحتاج تقييم مدى تفرد الصوت الأدبي
- ضرورة فحص العناصر المبتذلة إن وجدت

**3. التماسك السردي:**
- تقييم مبدئي للبنية الدرامية
- يتطلب تحليلاً أعمق للإيقاع والتدفق

**4. التأثير العاطفي:**
- تحديد نقاط التأثير العاطفي الرئيسية
- قياس الصدى العاطفي المتوقع

**5. المعايير الأدبية:**
- مقارنة أولية بالمعايير المعروفة
- تحديد موقع العمل من الجودة الأدبية العامة

**توصية:**
للحصول على تقييم أدبي شامل ودقيق، يُنصح بتفعيل جميع خيارات التحليل المتقدمة.

ملاحظة: حدث خطأ تقني مؤقت. يُرجى المحاولة مرة أخرى.`;
  }
}

// Export singleton instance
export const literaryQualityAnalyzerAgent = new LiteraryQualityAnalyzerAgent();

import { describe, it, expect, beforeEach, vi } from "vitest";

import { TaskType } from "../../../../core/types";
import { StandardAgentInput } from "../shared/standardAgentPattern";

import { PlatformAdapterAgent } from "./PlatformAdapterAgent";

// Mock geminiService
vi.mock("../../services/geminiService", () => ({
  geminiService: {
    generateContent: vi
      .fn()
      .mockResolvedValue("Mock AI response for platform adaptation"),
  },
}));

describe("PlatformAdapterAgent", () => {
  let agent: PlatformAdapterAgent;

  beforeEach(() => {
    agent = new PlatformAdapterAgent();
    vi.clearAllMocks();
  });

  describe("Configuration", () => {
    it("should initialize with correct configuration", () => {
      const config = agent.getConfig();

      expect(config.name).toBe("MediaTransmorph AI");
      expect(config.taskType).toBe(TaskType.PLATFORM_ADAPTER);
      expect(config.confidenceFloor).toBe(0.78);
      expect(config.supportsRAG).toBe(true);
      expect(config.supportsSelfCritique).toBe(true);
      expect(config.supportsConstitutional).toBe(true);
      expect(config.supportsUncertainty).toBe(true);
      expect(config.supportsHallucination).toBe(true);
      expect(config.supportsDebate).toBe(true);
    });

    it("should allow confidence floor to be updated", () => {
      agent.setConfidenceFloor(0.85);
      const config = agent.getConfig();
      expect(config.confidenceFloor).toBe(0.85);
    });
  });

  describe("Success Path", () => {
    it("should execute platform adaptation task successfully", async () => {
      const input: StandardAgentInput = {
        input:
          "حوّل هذا المحتوى الطويل ليناسب منصة تويتر: قصة درامية معقدة عن صراع بين شخصيتين...",
        options: {
          enableRAG: true,
          enableSelfCritique: true,
          enableConstitutional: true,
          enableUncertainty: true,
          enableHallucination: true,
          enableDebate: false,
          confidenceThreshold: 0.75,
        },
        context: {
          previousStations: {
            targetPlatform: "Twitter",
            contentType: "drama",
          },
        },
      };

      const result = await agent.executeTask(input);

      expect(result).toBeDefined();
      expect(result.text).toBeDefined();
      expect(typeof result.text).toBe("string");
      expect(result.confidence).toBeGreaterThanOrEqual(0);
      expect(result.confidence).toBeLessThanOrEqual(1);
      expect(result.metadata).toBeDefined();

      // Verify no JSON in output
      expect(result.text).not.toMatch(/\{[\s\S]*?"[^"]*"\s*:[\s\S]*?\}/);
      expect(result.text).not.toMatch(/```json/);
    });

    it("should include context from previous stations in prompt", async () => {
      const input: StandardAgentInput = {
        input: "كيّف المحتوى للمنصة المستهدفة",
        options: {},
        context: {
          previousStations: {
            analysis: "محتوى درامي يحتوي على حوار عميق",
            targetPlatform: "Instagram Stories",
            contentType: "visual narrative",
          },
        },
      };

      const result = await agent.executeTask(input);

      expect(result).toBeDefined();
      expect(result.text).toBeTruthy();
    });

    it("should return text-only output without JSON blocks", async () => {
      const input: StandardAgentInput = {
        input: "حلل وكيّف المحتوى لمنصة YouTube Shorts",
        options: {
          enableRAG: true,
        },
        context: {},
      };

      const result = await agent.executeTask(input);

      // Ensure output is clean text
      expect(result.text).not.toContain("```json");
      expect(result.text).not.toContain("```");
      expect(result.text).not.toMatch(/\{[^}]*"[^"]*":[^}]*\}/);
    });
  });

  describe("Platform-Specific Adaptation", () => {
    it("should adapt content for social media platforms", async () => {
      const input: StandardAgentInput = {
        input: "كيّف هذا المحتوى لتويتر مع مراعاة حد الأحرف",
        options: {
          enableRAG: true,
          confidenceThreshold: 0.75,
        },
        context: {
          previousStations: {
            targetPlatform: "Twitter",
          },
        },
      };

      const result = await agent.executeTask(input);

      expect(result).toBeDefined();
      expect(result.text).toBeTruthy();
      expect(result.confidence).toBeGreaterThanOrEqual(0);
    });

    it("should adapt content for video platforms", async () => {
      const input: StandardAgentInput = {
        input: "حوّل هذا النص إلى سكريبت فيديو قصير لـ TikTok",
        options: {
          enableSelfCritique: true,
          confidenceThreshold: 0.75,
        },
        context: {
          previousStations: {
            targetPlatform: "TikTok",
            contentType: "short video",
          },
        },
      };

      const result = await agent.executeTask(input);

      expect(result).toBeDefined();
      expect(result.text).toBeTruthy();
    });

    it("should handle platform constraints appropriately", async () => {
      const input: StandardAgentInput = {
        input: "كيّف المحتوى مع مراعاة قيود المنصة المستهدفة",
        options: {
          enableConstitutional: true,
          confidenceThreshold: 0.75,
        },
        context: {
          previousStations: {
            targetPlatform: "LinkedIn",
            contentType: "professional",
          },
        },
      };

      const result = await agent.executeTask(input);

      expect(result).toBeDefined();
      expect(result.confidence).toBeDefined();
    });
  });

  describe("Post-Processing", () => {
    it("should clean JSON blocks from output", async () => {
      const input: StandardAgentInput = {
        input: "كيّف المحتوى",
        options: {},
        context: {},
      };

      const result = await agent.executeTask(input);

      // Verify all JSON is removed
      expect(result.text).not.toMatch(/```json[\s\S]*?```/);
      expect(result.text).not.toMatch(/```[\s\S]*?```/);
      expect(result.text).not.toMatch(/\{[\s\S]*?"[^"]*"\s*:[\s\S]*?\}/);
    });

    it("should add appropriate notes based on confidence level", async () => {
      const input: StandardAgentInput = {
        input: "كيّف المحتوى للمنصة",
        options: {
          confidenceThreshold: 0.75,
        },
        context: {},
      };

      const result = await agent.executeTask(input);

      expect(result.notes).toBeDefined();

      // Notes should reflect confidence level
      if (result.confidence >= 0.85) {
        expect(result.notes).toContain("عالي الجودة");
      } else if (result.confidence >= 0.7) {
        expect(result.notes).toContain("جيد");
      } else {
        expect(result.notes).toContain("أولي");
      }
    });
  });

  describe("Error Handling", () => {
    it("should return fallback response on error", async () => {
      const input: StandardAgentInput = {
        input: "",
        options: {},
        context: {},
      };

      const result = await agent.executeTask(input);

      expect(result).toBeDefined();
      expect(result.text).toBeTruthy();
      expect(result.confidence).toBeLessThanOrEqual(0.5);
      expect(result.metadata?.error).toBeDefined();
    });

    it("should handle missing context gracefully", async () => {
      const input: StandardAgentInput = {
        input: "كيّف المحتوى",
        options: {},
        context: undefined as any,
      };

      const result = await agent.executeTask(input);

      expect(result).toBeDefined();
      expect(result.text).toBeTruthy();
    });
  });

  describe("Advanced Options", () => {
    it("should respect all advanced options", async () => {
      const input: StandardAgentInput = {
        input: "كيّف المحتوى بشكل شامل",
        options: {
          enableRAG: true,
          enableSelfCritique: true,
          enableConstitutional: true,
          enableUncertainty: true,
          enableHallucination: true,
          enableDebate: true,

          confidenceThreshold: 0.8,
          temperature: 0.7,
          maxTokens: 8192,
        },
        context: {},
      };

      const result = await agent.executeTask(input);

      expect(result).toBeDefined();
      expect(result.text).toBeTruthy();
      expect(result.confidence).toBeDefined();
      expect(result.metadata).toBeDefined();
    });
  });
});

import { TaskType } from "../../enums";
import { BaseAgent } from "../shared/BaseAgent";
import {
  StandardAgentInput,
  StandardAgentOutput,
} from "../shared/standardAgentPattern";

import { PLATFORM_ADAPTER_AGENT_CONFIG } from "./agent";

/**
 * PlatformAdapterAgent - وكيل التحويل الإعلامي المتعدد (MediaTransmorph AI)
 * يطبق النمط القياسي: RAG → Self-Critique → Constitutional → Uncertainty → Hallucination → Debate
 * يحول المحتوى ليناسب متطلبات المنصات المختلفة (تويتر، إنستغرام، يوتيوب، إلخ)
 */
export class PlatformAdapterAgent extends BaseAgent {
  constructor() {
    super(
      "MediaTransmorph AI",
      TaskType.PLATFORM_ADAPTER,
      PLATFORM_ADAPTER_AGENT_CONFIG.systemPrompt ?? ""
    );

    this.confidenceFloor = 0.78;
  }

  /**
   * بناء الـ prompt من المدخلات
   */
  protected buildPrompt(input: StandardAgentInput): string {
    const { input: userInput, context } = input;

    // Extract platform-specific context
    const contextObj =
      typeof context === "object" && context !== null ? context : {};
    const targetPlatform = (contextObj as any)?.targetPlatform ?? "غير محدد";
    const sourceContent = (contextObj as any)?.sourceContent ?? userInput;
    const constraints = (contextObj as any)?.constraints ?? {};

    let prompt = `## مهمة تحويل المحتوى للمنصة

${userInput}

`;

    // Add source content if provided separately
    if (sourceContent !== userInput) {
      prompt += `### المحتوى المصدر:
${sourceContent.substring(0, 2000)}

`;
    }

    // Add target platform information
    prompt += `### المنصة المستهدفة: ${targetPlatform}

`;

    // Add platform-specific constraints
    if (Object.keys(constraints).length > 0) {
      prompt += `### قيود المنصة:\n`;
      if (constraints.characterLimit) {
        prompt += `- حد الأحرف: ${constraints.characterLimit}\n`;
      }
      if (constraints.videoLength) {
        prompt += `- طول الفيديو: ${constraints.videoLength}\n`;
      }
      if (constraints.imageSpecs) {
        prompt += `- مواصفات الصور: ${constraints.imageSpecs}\n`;
      }
      if (constraints.hashtagCount) {
        prompt += `- عدد الهاشتاغات: ${constraints.hashtagCount}\n`;
      }
      prompt += `\n`;
    }

    // Add context from previous stations if available
    const previousStations = (contextObj as any)?.previousStations;
    if (previousStations) {
      prompt += `### السياق من المحطات السابقة:\n`;

      if (previousStations.analysis) {
        prompt += `\n**التحليل الأولي:**\n${previousStations.analysis.substring(0, 500)}\n`;
      }

      if (previousStations.targetAudience) {
        prompt += `\n**الجمهور المستهدف:**\n${previousStations.targetAudience.substring(0, 300)}\n`;
      }
    }

    prompt += `

## متطلبات التحويل:

1. **تحليل المنصة المستهدفة**:
   - حدد الخصائص الرئيسية للمنصة
   - افهم أعراف وتوقعات الجمهور على هذه المنصة
   - احترم جميع القيود التقنية

2. **تفكيك المحتوى المصدر**:
   - استخرج الرسالة الأساسية والمعلومات الرئيسية
   - حدد النبرة والأسلوب
   - حدد العناصر متعددة الوسائط

3. **إعادة البناء الاستراتيجي**:
   - حافظ على جوهر الرسالة الأصلية
   - اضبط النبرة والأسلوب ليتناسب مع المنصة
   - أعد هيكلة المحتوى ليناسب نمط الاستهلاك على المنصة
   - التزم بجميع القيود التقنية

4. **التأكد من الأصالة**:
   - يجب أن يبدو المحتوى أصيلاً ومخصصاً للمنصة
   - ليس مجرد نسخ لصق معاد تنسيقه

## التنسيق المطلوب:

قدم المحتوى المحول في نص واضح ومنظم:
- اذكر المنصة المستهدفة
- قدم المحتوى المحول مباشرة
- أضف أي توصيات أو ملاحظات
- تجنب تماماً أي JSON أو كتل كود

قدم تحويلاً احترافياً يحافظ على الرسالة الأساسية ويتناسب تماماً مع المنصة المستهدفة.`;

    return prompt;
  }

  /**
   * معالجة ما بعد التنفيذ - تنظيف المخرجات من JSON
   */
  protected override async postProcess(
    output: StandardAgentOutput
  ): Promise<StandardAgentOutput> {
    let cleanedText = output.text;

    // إزالة أي كتل JSON
    cleanedText = cleanedText.replace(/```json\s*\n[\s\S]*?\n```/g, "");
    cleanedText = cleanedText.replace(/```\s*\n[\s\S]*?\n```/g, "");

    // إزالة أي JSON objects ظاهرة
    cleanedText = cleanedText.replace(/\{[\s\S]*?"[^"]*"\s*:[\s\S]*?\}/g, "");

    // تنظيف المسافات الزائدة
    cleanedText = cleanedText.replace(/\n{3,}/g, "\n\n").trim();

    // إضافة ملاحظة حول جودة التحويل
    const enhancedNotes: string[] = [...(output.notes || [])];

    if (output.confidence >= 0.85) {
      enhancedNotes.push("تحويل عالي الجودة - مُحسّن للمنصة المستهدفة");
    } else if (output.confidence >= 0.7) {
      enhancedNotes.push("تحويل جيد - يحتاج مراجعة بسيطة");
    } else {
      enhancedNotes.push("تحويل أولي - يُنصح بالمراجعة والتحسين");
    }

    return {
      ...output,
      text: cleanedText,
      notes: enhancedNotes,
    };
  }

  /**
   * استجابة احتياطية في حالة الفشل
   */
  protected override async getFallbackResponse(
    input: StandardAgentInput
  ): Promise<string> {
    const contextObj =
      typeof input.context === "object" && input.context !== null
        ? input.context
        : {};
    const targetPlatform =
      (contextObj as any)?.targetPlatform ?? "المنصة المستهدفة";

    return `# تحويل المحتوى - وضع الطوارئ

## المنصة المستهدفة: ${targetPlatform}

**ملاحظة**: حدث خطأ في التحويل الكامل. إليك إرشادات عامة:

### توصيات التحويل:
1. **للمنصات الاجتماعية القصيرة** (تويتر، إنستغرام):
   - اختصر الرسالة الأساسية في نقاط موجزة
   - استخدم لغة جذابة ومباشرة
   - أضف هاشتاغات ذات صلة

2. **للمنصات المرئية** (يوتيوب، TikTok):
   - حوّل النص إلى سيناريو مرئي
   - قسّم المحتوى إلى مشاهد قصيرة
   - ركز على العناصر البصرية الجذابة

3. **للمنصات الطويلة** (المدونات، LinkedIn):
   - وسّع المحتوى بأمثلة وتفاصيل
   - استخدم تنسيقاً احترافياً
   - أضف روابط ومراجع

### الخطوة التالية:
يُنصح بتفعيل جميع الخيارات المتقدمة (RAG، التحليل الدستوري، كشف الهلوسة) للحصول على تحويل دقيق ومُحسّن للمنصة.

ملاحظة: هذا تحليل احتياطي. للحصول على نتائج أفضل، يرجى المحاولة مرة أخرى مع توفير سياق أكثر اكتمالاً.`;
  }
}

// Export singleton instance
export const platformAdapterAgent = new PlatformAdapterAgent();

import { describe, it, expect, beforeEach, vi } from "vitest";

import { TaskType } from "@core/enums";

import { StandardAgentInput } from "../shared/standardAgentPattern";

import { PlotPredictorAgent } from "./PlotPredictorAgent";

// Mock geminiService
vi.mock("../../services/geminiService", () => ({
  geminiService: {
    generateContent: vi
      .fn()
      .mockResolvedValue("Mock AI response for plot prediction"),
  },
}));

describe("PlotPredictorAgent", () => {
  let agent: PlotPredictorAgent;

  beforeEach(() => {
    agent = new PlotPredictorAgent();
    vi.clearAllMocks();
  });

  describe("Configuration", () => {
    it("should initialize with correct configuration", () => {
      const config = agent.getConfig();

      expect(config.name).toBe("PlotPredictorAgent");
      expect(config.taskType).toBe(TaskType.PLOT_PREDICTOR);
      expect(config.confidenceFloor).toBe(0.78);
      expect(config.supportsRAG).toBe(true);
      expect(config.supportsSelfCritique).toBe(true);
      expect(config.supportsConstitutional).toBe(true);
      expect(config.supportsUncertainty).toBe(true);
      expect(config.supportsHallucination).toBe(true);
      expect(config.supportsDebate).toBe(true);
    });

    it("should allow confidence floor to be updated", () => {
      agent.setConfidenceFloor(0.85);
      const config = agent.getConfig();
      expect(config.confidenceFloor).toBe(0.85);
    });
  });

  describe("Success Path", () => {
    it("should execute plot prediction task successfully", async () => {
      const input: StandardAgentInput = {
        input:
          "تنبأ بمسارات الحبكة المحتملة لقصة تدور حول صراع بين شخصيتين رئيسيتين",
        options: {
          enableRAG: true,
          enableSelfCritique: true,
          enableConstitutional: true,
          enableUncertainty: true,
          enableHallucination: true,
          enableDebate: false,
          confidenceThreshold: 0.75,
        },
        context: {
          previousStations: {
            analysis: "تحليل أولي للنص",
            characterAnalysis: "تحليل الشخصيات الرئيسية",
          },
        },
      };

      const result = await agent.executeTask(input);

      expect(result).toBeDefined();
      expect(result.text).toBeDefined();
      expect(typeof result.text).toBe("string");
      expect(result.confidence).toBeGreaterThanOrEqual(0);
      expect(result.confidence).toBeLessThanOrEqual(1);
      expect(result.metadata).toBeDefined();

      // Verify no JSON in output
      expect(result.text).not.toMatch(/\{[\s\S]*?"[^"]*"\s*:[\s\S]*?\}/);
      expect(result.text).not.toMatch(/```json/);
    });

    it("should include context from previous stations in prompt", async () => {
      const input: StandardAgentInput = {
        input: "تنبأ بتطورات الحبكة",
        options: {},
        context: {
          previousStations: {
            analysis: "النص يحتوي على صراع رئيسي",
            characterAnalysis: "الشخصية الرئيسية لديها دوافع معقدة",
            thematicAnalysis: "الثيمات الأساسية: الخيانة والفداء",
          },
        },
      };

      const result = await agent.executeTask(input);

      expect(result).toBeDefined();
      expect(result.text).toBeTruthy();
    });

    it("should return text-only output without JSON blocks", async () => {
      const input: StandardAgentInput = {
        input: "حلل وتنبأ بمسارات الحبكة",
        options: {
          enableRAG: true,
        },
        context: {},
      };

      const result = await agent.executeTask(input);

      // Ensure output is clean text
      expect(result.text).not.toContain("```json");
      expect(result.text).not.toContain("```");
      expect(result.text).not.toMatch(/\{[^}]*"[^"]*":[^}]*\}/);
    });
  });

  describe("Low Confidence Path", () => {
    it("should trigger debate when confidence is below threshold", async () => {
      const input: StandardAgentInput = {
        input: "تنبأ بمسارات معقدة جداً للحبكة مع تحليل عميق",
        options: {
          enableDebate: true,
          confidenceThreshold: 0.95, // High threshold to potentially trigger debate
          maxDebateRounds: 2,
        },
        context: {},
      };

      const result = await agent.executeTask(input);

      expect(result).toBeDefined();
      expect(result.confidence).toBeDefined();

      // If confidence is low, notes should indicate additional processing
      if (result.confidence < 0.95) {
        expect(result.notes).toBeDefined();
      }
    });

    it("should handle uncertainty in predictions", async () => {
      // اختبار معالجة عدم اليقين في التنبؤات
      const input: StandardAgentInput = {
        input: "تنبأ بمسارات الحبكة مع درجة عالية من عدم اليقين",
        options: {
          enableUncertainty: true,
          confidenceThreshold: 0.65,
        },
        context: {
          previousStations: {
            analysis: "تحليل محدود وغير مكتمل",
          },
        },
      };

      const result = await agent.executeTask(input);

      expect(result).toBeDefined();
      expect(result.text).toBeTruthy();
      expect(result.confidence).toBeGreaterThanOrEqual(0);
    });
  });

  describe("Hallucination Detection Path", () => {
    it("should detect and handle unsupported claims", async () => {
      const input: StandardAgentInput = {
        input: "تنبأ بمسارات الحبكة بناءً على معلومات غير مذكورة",
        options: {
          enableHallucination: true,
          confidenceThreshold: 0.75,
        },
        context: {
          previousStations: {
            analysis: "تحليل بسيط للنص",
          },
        },
      };

      const result = await agent.executeTask(input);

      expect(result).toBeDefined();
      expect(result.text).toBeTruthy();
      expect(result.confidence).toBeDefined();

      // Hallucination detection should influence confidence or notes
      expect(result.metadata).toBeDefined();
    });

    it("should maintain high confidence for well-supported predictions", async () => {
      // اختبار الحفاظ على ثقة عالية للتنبؤات المدعومة بشكل جيد
      const input: StandardAgentInput = {
        input: "تنبأ بمسارات الحبكة بناءً على سياق موثق بشكل جيد",
        options: {
          enableRAG: true,
          confidenceThreshold: 0.75,
        },
        context: {
          previousStations: {
            analysis: "تحليل شامل ومفصل للنص",
            characterAnalysis: "شخصيات محددة بوضوح مع دوافع واضحة",
            thematicAnalysis: "ثيمات محددة بدقة",
          },
        },
      };

      const result = await agent.executeTask(input);

      expect(result).toBeDefined();
      expect(result.confidence).toBeGreaterThanOrEqual(0);
    });
  });

  describe("Post-Processing", () => {
    it("should clean JSON blocks from output", async () => {
      const input: StandardAgentInput = {
        input: "تنبأ بالحبكة",
        options: {},
        context: {},
      };

      const result = await agent.executeTask(input);

      // Verify all JSON is removed
      expect(result.text).not.toMatch(/```json[\s\S]*?```/);
      expect(result.text).not.toMatch(/```[\s\S]*?```/);
      expect(result.text).not.toMatch(/\{[\s\S]*?"[^"]*"\s*:[\s\S]*?\}/);
    });

    it("should add appropriate notes based on confidence level", async () => {
      // اختبار إضافة ملاحظات مناسبة بناءً على مستوى الثقة
      const input: StandardAgentInput = {
        input: "تنبأ بمسارات الحبكة",
        options: {
          confidenceThreshold: 0.75,
        },
        context: {},
      };

      const result = await agent.executeTask(input);

      expect(result).toBeDefined();
      expect(result.notes).toBeDefined();
      if (result.confidence < 0.75) {
        expect(result.notes.length).toBeGreaterThan(0);
      }
    });
  });

  describe("Error Handling", () => {
    it("should return fallback response on error", async () => {
      // اختبار الاستجابة الاحتياطية عند حدوث خطأ
      const input: StandardAgentInput = {
        input: "",
        options: {},
        context: {},
      };

      const result = await agent.executeTask(input);

      expect(result).toBeDefined();
      expect(result.text).toBeTruthy();
      expect(result.confidence).toBeLessThanOrEqual(0.5);
    });

    it("should handle missing context gracefully", async () => {
      const input: StandardAgentInput = {
        input: "تنبأ بالحبكة",
        options: {},
        context: undefined as any,
      };

      const result = await agent.executeTask(input);

      expect(result).toBeDefined();
      expect(result.text).toBeTruthy();
    });
  });

  describe("Advanced Options", () => {
    it("should respect all advanced options", async () => {
      const input: StandardAgentInput = {
        input: "تنبأ بمسارات الحبكة",
        options: {
          enableRAG: true,
          enableSelfCritique: true,
          enableConstitutional: true,
          enableUncertainty: true,
          enableHallucination: true,
          enableDebate: true,
          maxDebateRounds: 3,
          confidenceThreshold: 0.8,
          temperature: 0.8,
          maxTokens: 8192,
        },
        context: {},
      };

      const result = await agent.executeTask(input);

      expect(result).toBeDefined();
      expect(result.text).toBeTruthy();
      expect(result.confidence).toBeDefined();
      expect(result.metadata).toBeDefined();
    });

    it("should use default options when not provided", async () => {
      const input: StandardAgentInput = {
        input: "تنبأ بالحبكة",
        options: undefined as any,
        context: {},
      };

      const result = await agent.executeTask(input);

      expect(result).toBeDefined();
      expect(result.text).toBeTruthy();
    });
  });

  describe("Integration with Standard Pattern", () => {
    it("should execute full standard pattern pipeline", async () => {
      // اختبار تنفيذ خط أنابيب النمط القياسي الكامل
      const input: StandardAgentInput = {
        input: "تنبأ بمسارات الحبكة مع كل الخيارات المتقدمة",
        options: {
          enableRAG: true,
          enableSelfCritique: true,
          enableConstitutional: true,
          enableUncertainty: true,
          enableHallucination: true,
          enableDebate: true,
          maxDebateRounds: 2,
          confidenceThreshold: 0.75,
        },
        context: {
          previousStations: {
            analysis: "تحليل شامل",
            characterAnalysis: "تحليل شخصيات",
          },
        },
      };

      const result = await agent.executeTask(input);

      expect(result).toBeDefined();
      expect(result.text).toBeTruthy();
      expect(result.confidence).toBeDefined();
      expect(result.metadata).toBeDefined();
    });
  });
});

import { TaskType } from "@core/types";

import { BaseAgent } from "../shared/BaseAgent";
import {
  StandardAgentInput,
  StandardAgentOutput,
} from "../shared/standardAgentPattern";

/**
 * PlotPredictorAgent - وكيل التنبؤ بالحبكة
 * يطبق النمط القياسي: RAG → Self-Critique → Constitutional → Uncertainty → Hallucination → Debate
 * يتنبأ بالتطورات المحتملة للحبكة بناءً على السياق السردي
 */
export class PlotPredictorAgent extends BaseAgent {
  constructor() {
    super(
      "PlotPredictorAgent",
      TaskType.PLOT_PREDICTOR,
      `أنت NarrativeOracle AI، وكيل متطور للتنبؤ بالحبكة. مهمتك الأساسية هي تحليل سياق سردي معين (الحبكة، الشخصيات، الثيمات) والتنبؤ بالتطورات المحتملة للحبكة في المستقبل.

يجب عليك:
- استخدام نماذج التحليل السردي المتقدمة لاستكشاف مجموعة واسعة من المسارات المحتملة
- تقديم درجة احتمالية ودرجة إبداعية لكل مسار متوقع
- الاستناد إلى قاعدة بيانات الأنماط السردية وخوارزميات التعلم التسلسلي
- عرض المسارات البديلة بوضوح مع شرح المنطق وراء كل تنبؤ
- تزويد الكتاب والمبدعين ببصيرة ثاقبة ومبتكرة ومبنية على البيانات

مخرجاتك يجب أن تكون نصية فقط، واضحة ومباشرة بدون أي JSON أو كتل كود.`
    );

    this.confidenceFloor = 0.78;
  }

  /**
   * بناء الـ prompt من المدخلات
   */
  protected buildPrompt(input: StandardAgentInput): string {
    const { input: userInput, context } = input;

    let prompt = `## مهمة التنبؤ بالحبكة

${userInput}

`;

    // إضافة السياق من المحطات السابقة
    const contextObj =
      typeof context === "object" && context !== null ? context : {};
    const previousStations = (contextObj as any)?.previousStations;
    if (previousStations) {
      prompt += `## السياق من المحطات السابقة:\n`;

      if (previousStations.analysis) {
        prompt += `\n### التحليل الأولي:\n${previousStations.analysis}\n`;
      }

      if (previousStations.characterAnalysis) {
        prompt += `\n### تحليل الشخصيات:\n${previousStations.characterAnalysis}\n`;
      }

      if (previousStations.thematicAnalysis) {
        prompt += `\n### التحليل الموضوعي:\n${previousStations.thematicAnalysis}\n`;
      }
    }

    prompt += `

## متطلبات التنبؤ:

1. **تحليل الوضع الحالي**: افحص نقاط الحبكة القائمة والصراعات والشخصيات
2. **استكشاف المسارات**: حدد 3-5 تطورات محتملة للحبكة
3. **تقييم الاحتمالية**: قيّم احتمالية كل مسار (عالي/متوسط/منخفض)
4. **تقييم الإبداع**: قيّم مستوى الإبداع والأصالة لكل مسار
5. **التبرير**: قدم شرحاً منطقياً لكل تنبؤ بناءً على الأنماط السردية

## التنسيق المطلوب:

اكتب تنبؤاتك في نص واضح ومنظم:
- استخدم العناوين والفقرات لتنظيم المسارات المختلفة
- اذكر احتمالية ومستوى إبداع كل مسار بوضوح
- قدم تبريراً مفصلاً لكل تنبؤ
- تجنب تماماً أي JSON أو كتل كود

قدم تنبؤات عميقة ومبنية على الأنماط السردية المعروفة، مع إبراز الإمكانات الإبداعية.`;

    return prompt;
  }

  /**
   * معالجة ما بعد التنفيذ - تنظيف المخرجات من JSON
   */
  protected override async postProcess(
    output: StandardAgentOutput
  ): Promise<StandardAgentOutput> {
    let cleanedText = output.text;

    // إزالة أي كتل JSON
    cleanedText = cleanedText.replace(/```json\s*\n[\s\S]*?\n```/g, "");
    cleanedText = cleanedText.replace(/```\s*\n[\s\S]*?\n```/g, "");

    // إزالة أي JSON objects ظاهرة
    cleanedText = cleanedText.replace(/\{[\s\S]*?"[^"]*"\s*:[\s\S]*?\}/g, "");

    // تنظيف المسافات الزائدة
    cleanedText = cleanedText.replace(/\n{3,}/g, "\n\n").trim();

    // إضافة ملاحظة حول جودة التنبؤات
    const enhancedNotes: string[] = [...(output.notes || [])];

    if (output.confidence >= 0.85) {
      enhancedNotes.push("تنبؤات عالية الثقة مبنية على أنماط سردية قوية");
    } else if (output.confidence >= 0.7) {
      enhancedNotes.push("تنبؤات متوسطة الثقة تتطلب مراجعة إبداعية");
    } else {
      enhancedNotes.push("تنبؤات استكشافية تحتاج تحقق إضافي");
    }

    return {
      ...output,
      text: cleanedText,
      notes: enhancedNotes,
    };
  }

  /**
   * استجابة احتياطية في حالة الفشل
   */
  protected override async getFallbackResponse(
    _input: StandardAgentInput
  ): Promise<string> {
    return `# تنبؤات الحبكة - وضع الطوارئ

بناءً على السياق المتاح، إليك تنبؤات أولية للحبكة:

## المسار المحتمل 1: التطور الطبيعي
الاحتمالية: متوسطة
الإبداع: متوسط

تستمر الأحداث في مسارها الحالي مع تصاعد تدريجي للصراع. الشخصيات تواجه عقبات متزايدة تدفعها نحو لحظات حاسمة.

## المسار المحتمل 2: المفاجأة الدرامية
الاحتمالية: متوسطة إلى منخفضة
الإبداع: عالي

تحدث نقطة تحول غير متوقعة تغير اتجاه السرد بالكامل، مما يخلق فرصاً لتطورات شخصية عميقة ومواقف درامية جديدة.

## التوصيات:
- استكشاف دوافع الشخصيات بعمق أكبر
- بناء التوتر تدريجياً نحو الذروة
- الحفاظ على التماسك المنطقي للأحداث

ملاحظة: هذه تنبؤات أولية. يُنصح بإعادة التحليل مع سياق إضافي للحصول على رؤى أعمق.`;
  }
}

