import { safeCountMultipleTerms } from "@/lib/security/safe-regexp";
import { TaskType } from "@core/types";

import { BaseAgent } from "../shared/BaseAgent";
import {
  StandardAgentInput,
  StandardAgentOutput,
} from "../shared/standardAgentPattern";

import { RHYTHM_MAPPING_AGENT_CONFIG } from "./agent";

interface RhythmMappingContext {
  originalText?: string;
  analysisReport?: any;
  sceneBreakdown?: any[];
  focusAspects?: string[]; // ['pacing', 'beats', 'tempo', 'flow', 'structure']
  identifyPatterns?: boolean;
  analyzeVariation?: boolean;
  compareGenreNorms?: boolean;
  provideOptimization?: boolean;
  genre?: string;
}

/**
 * Rhythm Mapping Agent - وكيل خريطة الإيقاع السردي
 * يطبق النمط القياسي: RAG → Self-Critique → Constitutional → Uncertainty → Hallucination → Debate
 * إخراج نصي فقط - لا JSON
 */
export class RhythmMappingAgent extends BaseAgent {
  constructor() {
    super(
      "RhythmMapper AI",
      TaskType.RHYTHM_MAPPING,
      RHYTHM_MAPPING_AGENT_CONFIG.systemPrompt ?? ""
    );

    this.confidenceFloor = 0.8;
  }

  protected buildPrompt(input: StandardAgentInput): string {
    const { input: taskInput, context } = input;
    const ctx = context as RhythmMappingContext;

    const originalText = ctx?.originalText ?? "";
    const sceneBreakdown = ctx?.sceneBreakdown ?? [];
    const focusAspects = ctx?.focusAspects ?? ["pacing", "tempo", "flow"];
    const identifyPatterns = ctx?.identifyPatterns ?? true;
    const analyzeVariation = ctx?.analyzeVariation ?? true;
    const compareGenreNorms = ctx?.compareGenreNorms ?? false;
    const provideOptimization = ctx?.provideOptimization ?? true;
    const genre = ctx?.genre ?? "غير محدد";

    let prompt = `مهمة رسم خريطة الإيقاع السردي\n\n`;

    if (originalText) {
      prompt += `النص المراد تحليله:\n${originalText.substring(0, 2500)}...\n\n`;
    }

    if (sceneBreakdown.length > 0) {
      prompt += `تفصيل المشاهد:\n`;
      sceneBreakdown.slice(0, 6).forEach((scene: any, idx: number) => {
        const sceneDesc =
          typeof scene === "string"
            ? scene
            : scene.description ?? `مشهد ${idx + 1}`;
        const sceneLength =
          typeof scene === "object" && scene.length
            ? ` (${scene.length} كلمة)`
            : "";
        prompt += `${idx + 1}. ${sceneDesc}${sceneLength}\n`;
      });
      prompt += "\n";
    }

    prompt += `معلومات التحليل:\n`;
    prompt += `- النوع الأدبي: ${genre}\n`;
    prompt += `- جوانب التركيز: ${focusAspects.map(this.translateAspect).join("، ")}\n`;
    prompt += `- تحديد الأنماط: ${identifyPatterns ? "نعم" : "لا"}\n`;
    prompt += `- تحليل التنوع: ${analyzeVariation ? "نعم" : "لا"}\n`;
    prompt += `- مقارنة بمعايير النوع: ${compareGenreNorms ? "نعم" : "لا"}\n`;
    prompt += `- تحسينات مقترحة: ${provideOptimization ? "نعم" : "لا"}\n\n`;

    prompt += `المهمة المطلوبة:\n${taskInput}\n\n`;

    prompt += `التعليمات:

1. **نظرة عامة على الإيقاع** (3-4 جمل):
   - الطابع الإيقاعي العام للنص
   - السرعة الإجمالية (بطيء، متوسط، سريع)
   - مدى التنوع والديناميكية
   - الانطباع العام على القارئ

2. **تحليل الوتيرة** (Pacing):
   - سرعة تطور الأحداث
   - التوازن بين الحركة والسكون
   - المشاهد السريعة مقابل المشاهد البطيئة
   - فعالية الوتيرة في كل قسم
   - الأدلة النصية: أمثلة محددة

3. **النبضات السردية** (Narrative Beats):
   - اللحظات المحورية (Beats) الرئيسية
   - توقيت وتوزيع النبضات
   - كثافة الأحداث في كل قسم
   - النبضات الكبرى (Major Beats) مقابل الصغرى (Minor Beats)

4. **الإيقاع الزمني** (Tempo):
   - التسارع والتباطؤ
   - المقاطع المندفعة والهادئة
   - التحولات في السرعة ومبرراتها
   - الإيقاع المثالي لكل نوع من المشاهد

5. **التدفق والسلاسة** (Flow):
   - الانتقالات بين المشاهد والفصول
   - العوائق أو الانقطاعات في التدفق
   - الاستمرارية والتماسك الإيقاعي
   - السلاسة الزمنية والمكانية

${
  identifyPatterns
    ? `6. **الأنماط الإيقاعية**:
   - الدورات المتكررة (إن وجدت)
   - البنى الإيقاعية (مثل: بطيء-سريع-بطيء)
   - التناوب والتبادل
   - التوازي والتماثل`
    : ""
}

${
  analyzeVariation
    ? `7. **التنوع والديناميكية**:
   - مدى تنوع الإيقاع
   - تجنب الرتابة والملل
   - التباين بين الأقسام
   - المفاجآت الإيقاعية`
    : ""
}

8. **البنية الإيقاعية الكلية**:
   - القوس الإيقاعي للنص بأكمله
   - البداية، الوسط، النهاية إيقاعياً
   - نقاط التحول الإيقاعية الكبرى
   - التصاعد والهبوط العام

${
  compareGenreNorms
    ? `9. **المقارنة بمعايير النوع**:
   - كيف يقارن الإيقاع بما هو معتاد في نوع ${genre}
   - الانحرافات الإيجابية أو السلبية
   - مدى تلبية توقعات القراء`
    : ""
}

${
  provideOptimization
    ? `10. **التحسينات المقترحة**:
   - مواضع تحتاج تسريع
   - مواضع تحتاج إبطاء
   - فرص لتحسين التدفق
   - اقتراحات لزيادة التنوع
   - تعديلات على البنية الإيقاعية`
    : ""
}

11. **الرسم البياني الوصفي**:
    وصف نصي لمنحنى الإيقاع عبر النص:
    - استخدم مؤشرات نصية (▲ للتسارع، ▼ للتباطؤ، ━ للثبات)
    - وصف الموجات الإيقاعية
    - تحديد القمم والقيعان

12. **التقييم النهائي**:
    - فعالية الإيقاع الحالي (درجة من 10)
    - نقاط القوة الإيقاعية
    - المجالات الأكثر حاجة للتحسين

اكتب بشكل نصي تحليلي واضح مع أمثلة محددة من النص.
استخدم وصف نصي للأنماط والمنحنيات.
لا تستخدم JSON أو رسومات معقدة - وصف تحليلي مباشر فقط.`;

    return prompt;
  }

  protected override async postProcess(
    output: StandardAgentOutput
  ): Promise<StandardAgentOutput> {
    const processedText = this.cleanupRhythmText(output.text);

    const analysisComprehensiveness =
      await this.assessAnalysisComprehensiveness(processedText);
    const technicalPrecision =
      await this.assessTechnicalPrecision(processedText);
    const practicalInsight = await this.assessPracticalInsight(processedText);
    const evidenceQuality = await this.assessEvidenceQuality(processedText);

    const qualityScore =
      analysisComprehensiveness * 0.3 +
      technicalPrecision * 0.25 +
      practicalInsight * 0.25 +
      evidenceQuality * 0.2;

    const adjustedConfidence = output.confidence * 0.5 + qualityScore * 0.5;

    return {
      ...output,
      text: processedText,
      confidence: adjustedConfidence,
      notes: this.generateRhythmNotes(
        output,
        analysisComprehensiveness,
        technicalPrecision,
        practicalInsight,
        evidenceQuality
      ),
      metadata: {
        ...output.metadata,
        rhythmAnalysisQuality: {
          overall: qualityScore,
          analysisComprehensiveness,
          technicalPrecision,
          practicalInsight,
          evidenceQuality,
        },
        patternsIdentified: this.countPatterns(processedText),
        beatsIdentified: this.countBeats(processedText),
        optimizationSuggestions: this.countOptimizations(processedText),
      },
    };
  }

  private cleanupRhythmText(text: string): string {
    text = text.replace(/```json[\s\S]*?```/g, "");
    text = text.replace(/```[\s\S]*?```/g, "");
    text = text.replace(/\{[\s\S]*?\}/g, (match) => {
      if (match.includes('"') && match.includes(":")) return "";
      return match;
    });

    return text.replace(/\n{3,}/g, "\n\n").trim();
  }

  private async assessAnalysisComprehensiveness(text: string): Promise<number> {
    let score = 0.5;

    const rhythmTerms = [
      "إيقاع",
      "وتيرة",
      "سرعة",
      "نبض",
      "تدفق",
      "تسارع",
      "تباطؤ",
      "ديناميكية",
    ];
    // SECURITY FIX: Use safe RegExp utility to prevent injection
    const termCount = safeCountMultipleTerms(text, rhythmTerms);
    score += Math.min(0.25, termCount * 0.015);

    const aspectsTerms = [
      "سريع",
      "بطيء",
      "متوسط",
      "هادئ",
      "مندفع",
      "ثابت",
      "متغير",
    ];
    // SECURITY FIX: Use safe RegExp utility to prevent injection
    const aspectsCount = safeCountMultipleTerms(text, aspectsTerms);
    score += Math.min(0.15, aspectsCount * 0.02);

    if (text.length > 1500) score += 0.1;

    return Math.min(1, score);
  }

  private async assessTechnicalPrecision(text: string): Promise<number> {
    let score = 0.6;

    const technicalTerms = [
      "نبضة",
      "beat",
      "tempo",
      "pacing",
      "قوس",
      "منحنى",
      "تصاعد",
      "هبوط",
    ];
    // SECURITY FIX: Use safe RegExp utility to prevent injection
    const techCount = safeCountMultipleTerms(text, technicalTerms);
    score += Math.min(0.25, techCount * 0.03);

    const hasVisualIndicators =
      text.includes("▲") || text.includes("▼") || text.includes("━");
    if (hasVisualIndicators) score += 0.15;

    return Math.min(1, score);
  }

  private async assessPracticalInsight(text: string): Promise<number> {
    let score = 0.5;

    const insightWords = [
      "يمكن",
      "يُنصح",
      "يُفضل",
      "توصية",
      "تحسين",
      "تعديل",
      "فرصة",
      "إمكانية",
    ];
    // SECURITY FIX: Use safe RegExp utility to prevent injection
    const insightCount = safeCountMultipleTerms(text, insightWords);
    score += Math.min(0.3, insightCount * 0.03);

    const hasOptimization = text.includes("تحسين") || text.includes("اقتراح");
    if (hasOptimization) score += 0.2;

    return Math.min(1, score);
  }

  private async assessEvidenceQuality(text: string): Promise<number> {
    let score = 0.6;

    const evidenceMarkers = [
      "مثل",
      "كما في",
      "نرى",
      "يظهر",
      "في المشهد",
      "المقطع",
    ];
    // SECURITY FIX: Use safe RegExp utility to prevent injection
    const evidenceCount = safeCountMultipleTerms(text, evidenceMarkers);
    score += Math.min(0.25, evidenceCount * 0.025);

    const hasExamples = (text.match(/["«]/g) ?? []).length >= 2;
    if (hasExamples) score += 0.15;

    return Math.min(1, score);
  }

  private countPatterns(text: string): number {
    const patternMarkers = text.match(/نمط|دورة|تكرار|تناوب|توازي/gi);
    return patternMarkers ? Math.min(patternMarkers.length, 8) : 0;
  }

  private countBeats(text: string): number {
    const beatMarkers = text.match(/نبضة|beat|لحظة محورية|حدث رئيسي/gi);
    return beatMarkers ? Math.min(beatMarkers.length, 15) : 0;
  }

  private countOptimizations(text: string): number {
    const optMarkers = text.match(/يُنصح|يُفضل|تحسين|اقتراح|تعديل|يمكن/gi);
    return optMarkers ? Math.min(optMarkers.length, 12) : 0;
  }

  private generateRhythmNotes(
    output: StandardAgentOutput,
    comprehensiveness: number,
    precision: number,
    insight: number,
    evidence: number
  ): string[] {
    const notes: string[] = [];

    const avg = (comprehensiveness + precision + insight + evidence) / 4;
    if (avg > 0.8) notes.push("تحليل إيقاعي ممتاز");
    else if (avg > 0.65) notes.push("تحليل جيد");
    else notes.push("يحتاج عمق أكبر");

    if (comprehensiveness > 0.8) notes.push("شمولية عالية");
    if (precision > 0.75) notes.push("دقة تقنية جيدة");
    if (insight > 0.75) notes.push("رؤى عملية ثاقبة");
    if (evidence > 0.75) notes.push("أدلة نصية جيدة");

    if (comprehensiveness < 0.6) notes.push("يحتاج تغطية أوسع");
    if (precision < 0.5) notes.push("يحتاج دقة تقنية أكبر");
    if (insight < 0.6) notes.push("يحتاج مزيد من التوصيات");

    if (output.notes) notes.push(...output.notes);

    return notes;
  }

  private translateAspect(aspect: string): string {
    const aspects: Record<string, string> = {
      pacing: "الوتيرة",
      beats: "النبضات السردية",
      tempo: "الإيقاع الزمني",
      flow: "التدفق والسلاسة",
      structure: "البنية الإيقاعية",
      variation: "التنوع والديناميكية",
      patterns: "الأنماط المتكررة",
    };
    return aspects[aspect] ?? aspect;
  }

  protected override async getFallbackResponse(
    _input: StandardAgentInput
  ): Promise<string> {
    return `نظرة عامة على الإيقاع:
النص يتبع إيقاعاً متوسط السرعة مع تنوع معتدل بين المشاهد السريعة والبطيئة.

تحليل الوتيرة:
الوتيرة العامة متوازنة، مع ميل نحو البطء في المشاهد الوصفية والتسارع في مشاهد الحركة والصراع.

النبضات السردية:
النبضات الرئيسية موزعة بشكل معقول عبر النص، مع كثافة أعلى في الثلث الأخير.

الإيقاع الزمني:
البداية: ━━━━ (ثابت)
الوسط: ━━▲▲━ (تسارع تدريجي)
النهاية: ▲▲▲▼ (تسارع ثم تحرر)

التدفق والسلاسة:
الانتقالات بين المشاهد سلسة عموماً، مع بعض القفزات المفاجئة التي قد تحتاج نعومة أكبر.

الأنماط الإيقاعية:
نمط "تصاعد-ذروة-هبوط" يتكرر عدة مرات بشكل صغير قبل الذروة الكبرى النهائية.

التنوع والديناميكية:
تنوع معتدل. هناك فرص لزيادة التباين بين المشاهد لتجنب الرتابة.

البنية الإيقاعية الكلية:
القوس الإيقاعي يتبع البنية الكلاسيكية: بداية هادئة، تصاعد تدريجي، ذروة، ثم حل سريع نسبياً.

التحسينات المقترحة:
1. تسريع الثلث الأول قليلاً لجذب الانتباه مبكراً
2. إضافة "نبضات صغرى" أكثر في الوسط لكسر الرتابة
3. إبطاء الحل النهائي قليلاً لإعطاء إشباع أكبر
4. تعزيز التباين بين المشاهد السريعة والبطيئة
5. تحسين الانتقالات في 2-3 مواضع محددة

الرسم البياني الوصفي:
البداية (صفحات 1-30): ━━━━ (وتيرة ثابتة، متوسطة)
الصعود (صفحات 31-70): ━━▲▲▲ (تسارع تدريجي)
الذروة (صفحات 71-85): ▲▲▲ (سرعة قصوى، كثافة عالية)
الحل (صفحات 86-100): ▼▼━ (هبوط سريع ثم استقرار)

التقييم النهائي: 7/10
الإيقاع فعال بشكل عام ويخدم القصة، لكن هناك فرص لتحسينه وجعله أكثر ديناميكية وإشباعاً.

نقاط القوة: التصاعد المتزن، الذروة القوية، التوزيع المعقول للنبضات
المجالات المحتاجة تحسين: البداية تحتاج حيوية أكبر، الوسط يحتاج مزيد من التنوع، الحل سريع نسبياً

ملاحظة: يُرجى تفعيل الخيارات المتقدمة وتوفير المزيد من تفاصيل المشاهد والنوع الأدبي للحصول على خريطة إيقاعية أكثر دقة وتفصيلاً مع تحليل عميق للأنماط وتوصيات محددة قابلة للتطبيق.`;
  }
}

export const rhythmMappingAgent = new RhythmMappingAgent();

import { safeCountMultipleTerms } from "@/lib/security/safe-regexp";
import { TaskType } from "@core/types";

import { BaseAgent } from "../shared/BaseAgent";
import {
  StandardAgentInput,
  StandardAgentOutput,
} from "../shared/standardAgentPattern";

import { SCENE_GENERATOR_AGENT_CONFIG } from "./agent";

/**
 * Scene Generator Agent - وكيل مولد المشاهد
 * يطبق النمط القياسي: RAG → Self-Critique → Constitutional → Uncertainty → Hallucination → Debate
 * إخراج نصي فقط - لا JSON
 */
export class SceneGeneratorAgent extends BaseAgent {
  constructor() {
    super(
      "SceneCraft AI",
      TaskType.SCENE_GENERATOR,
      SCENE_GENERATOR_AGENT_CONFIG.systemPrompt ?? ""
    );

    // Set agent-specific confidence floor
    this.confidenceFloor = 0.8;
  }

  /**
   * Build prompt for scene generation
   */
  protected buildPrompt(input: StandardAgentInput): string {
    const { input: taskInput, context } = input;

    // Extract relevant context
    const contextObj =
      typeof context === "object" && context !== null ? context : {};
    const originalText = (contextObj as any)?.originalText ?? "";
    const sceneType = (contextObj as any)?.sceneType ?? "dramatic";
    const characters = (contextObj as any)?.characters ?? [];
    const setting = (contextObj as any)?.setting ?? "";
    const emotionalTone = (contextObj as any)?.emotionalTone ?? "neutral";
    const conflictLevel = (contextObj as any)?.conflictLevel ?? "medium";
    const sceneObjectives = (contextObj as any)?.objectives ?? [];
    const previousScenes = (contextObj as any)?.previousScenes ?? [];

    // Build structured prompt
    let prompt = `مهمة توليد المشهد الدرامي\n\n`;

    // Add original text context
    if (originalText) {
      prompt += `السياق الأصلي:\n${originalText}\n\n`;
    }

    // Add scene specifications
    prompt += `مواصفات المشهد:\n`;
    prompt += `- نوع المشهد: ${this.translateSceneType(sceneType)}\n`;
    prompt += `- النبرة العاطفية: ${this.translateEmotionalTone(emotionalTone)}\n`;
    prompt += `- مستوى الصراع: ${this.translateConflictLevel(conflictLevel)}\n\n`;

    // Add characters
    if (characters.length > 0) {
      prompt += `الشخصيات في المشهد:\n`;
      characters.forEach((character: any, index: number) => {
        prompt += `${index + 1}. ${this.formatCharacter(character)}\n`;
      });
      prompt += "\n";
    }

    // Add setting
    if (setting) {
      prompt += `مكان وزمان المشهد:\n${setting}\n\n`;
    }

    // Add scene objectives
    if (sceneObjectives.length > 0) {
      prompt += `أهداف المشهد:\n`;
      sceneObjectives.forEach((objective: string, index: number) => {
        prompt += `${index + 1}. ${objective}\n`;
      });
      prompt += "\n";
    }

    // Add previous scenes context
    if (previousScenes.length > 0) {
      prompt += `ملخص المشاهد السابقة:\n`;
      previousScenes.slice(-2).forEach((scene: any, index: number) => {
        prompt += `[مشهد ${index + 1}]: ${this.summarizeScene(scene)}\n`;
      });
      prompt += "\n";
    }

    // Add specific task
    prompt += `المهمة المطلوبة:\n${taskInput}\n\n`;

    // Add generation instructions
    prompt += `التعليمات:

1. **وصف المشهد** (2-3 جمل): ابدأ بوصف موجز للمكان والأجواء
2. **الحركة والحوار**: اكتب المشهد بشكل متكامل مع الحوارات والحركات
3. **التوتر الدرامي**: احرص على بناء التوتر وتطوير الصراع
4. **التفاصيل الحسية**: أضف تفاصيل بصرية وسمعية وحسية
5. **النهاية**: اختتم المشهد بشكل يدفع القصة للأمام

اكتب المشهد بأسلوب سينمائي واضح، مع التوازن بين الوصف والحوار والحركة.
لا تستخدم JSON أو رموز البرمجة. اكتب نصاً درامياً صافياً.`;

    return prompt;
  }

  /**
   * Post-process the scene output
   */
  protected override async postProcess(
    output: StandardAgentOutput
  ): Promise<StandardAgentOutput> {
    // Clean and format the scene
    const processedText = this.cleanupSceneText(output.text);

    // Assess scene quality
    const dramaticTension = await this.assessDramaticTension(processedText);
    const dialogueQuality = await this.assessDialogueQuality(processedText);
    const visualClarity = await this.assessVisualClarity(processedText);
    const pacing = await this.assessPacing(processedText);

    // Calculate composite quality score
    const qualityScore =
      dramaticTension * 0.3 +
      dialogueQuality * 0.25 +
      visualClarity * 0.25 +
      pacing * 0.2;

    // Adjust confidence based on quality
    const adjustedConfidence = output.confidence * 0.6 + qualityScore * 0.4;

    return {
      ...output,
      text: processedText,
      confidence: adjustedConfidence,
      notes: this.generateSceneNotes(
        output,
        dramaticTension,
        dialogueQuality,
        visualClarity,
        pacing
      ),
      metadata: {
        ...output.metadata,
        sceneQuality: qualityScore,
        sceneQualityDetails: {
          overall: qualityScore,
          dramaticTension,
          dialogueQuality,
          visualClarity,
          pacing,
        },
        sceneLength: processedText.length,
        dialoguePercentage: this.calculateDialoguePercentage(processedText),
        numberOfCharacters: this.countCharacters(processedText),
      },
    };
  }

  /**
   * Clean up scene text formatting
   */
  private cleanupSceneText(text: string): string {
    // Remove JSON and code artifacts
    text = text.replace(/```json[\s\S]*?```/g, "");
    text = text.replace(/```[\s\S]*?```/g, "");
    text = text.replace(/\{[\s\S]*?\}/g, (match) => {
      if (match.includes('"') && match.includes(":")) return "";
      return match;
    });

    // Format scene elements
    const formatted = this.formatSceneElements(text);

    // Ensure proper scene structure
    const structured = this.structureScene(formatted);

    // Clean up whitespace
    return structured.replace(/\n{3,}/g, "\n\n").trim();
  }

  /**
   * Format scene elements (dialogue, action, description)
   */
  private formatSceneElements(text: string): string {
    const lines = text.split("\n");
    const formatted: string[] = [];

    for (const line of lines) {
      const trimmed = line.trim();
      if (!trimmed) {
        formatted.push("");
        continue;
      }

      // Format character names in dialogue
      if (this.isCharacterName(trimmed)) {
        formatted.push(`\n${trimmed.toUpperCase()}`);
      }
      // Format dialogue
      else if (this.isDialogue(trimmed)) {
        formatted.push(this.formatDialogue(trimmed));
      }
      // Format stage directions
      else if (this.isStageDirection(trimmed)) {
        formatted.push(`(${trimmed})`);
      }
      // Regular description
      else {
        formatted.push(trimmed);
      }
    }

    return formatted.join("\n");
  }

  /**
   * Structure the scene properly
   */
  private structureScene(text: string): string {
    // Extract main components
    const sceneHeading = this.extractSceneHeading(text);
    const description = this.extractDescription(text);
    const action = this.extractAction(text);

    // Rebuild in proper order
    let structured = "";

    if (sceneHeading) {
      structured += `${sceneHeading}\n\n`;
    }

    if (description) {
      structured += `${description}\n\n`;
    }

    if (action) {
      structured += action;
    }

    // If no clear structure, return original
    return structured || text;
  }

  /**
   * Assess dramatic tension in the scene
   */
  private async assessDramaticTension(text: string): Promise<number> {
    let score = 0.5;

    // Check for conflict indicators
    const conflictWords = [
      "لكن",
      "رغم",
      "ضد",
      "تحدي",
      "صراع",
      "مواجهة",
      "رفض",
      "اعتراض",
    ];
    // SECURITY FIX: Use safe RegExp utility to prevent injection
    const conflictCount = safeCountMultipleTerms(text, conflictWords);
    score += Math.min(0.2, conflictCount * 0.02);

    // Check for emotional intensity
    const emotionalWords = [
      "غضب",
      "خوف",
      "حب",
      "كره",
      "قلق",
      "صدمة",
      "دهشة",
      "!",
    ];
    // SECURITY FIX: Use safe RegExp utility to prevent injection
    const emotionCount = safeCountMultipleTerms(text, emotionalWords);
    score += Math.min(0.15, emotionCount * 0.015);

    // Check for turning points
    const turningWords = ["فجأة", "لحظة", "الآن", "أخيراً", "لا يمكن"];
    const hasTurning = turningWords.some((word) => text.includes(word));
    if (hasTurning) score += 0.15;

    return Math.min(1, score);
  }

  /**
   * Assess dialogue quality
   */
  private async assessDialogueQuality(text: string): Promise<number> {
    let score = 0.6;

    // Check for dialogue presence
    const hasDialogue =
      text.includes('"') || text.includes("«") || text.includes(":");
    if (!hasDialogue) return 0.3;

    // Check for varied dialogue lengths
    const dialogueMatches = text.match(/"[^"]+"/g) ?? [];
    if (dialogueMatches.length > 0) {
      const lengths = dialogueMatches.map((d) => d.length);
      const avgLength = lengths.reduce((a, b) => a + b, 0) / lengths.length;
      const variance =
        lengths.reduce((sum, len) => sum + Math.abs(len - avgLength), 0) /
        lengths.length;

      // Higher variance is better (varied dialogue)
      if (variance > 20) score += 0.2;
    }

    // Check for subtext and implication
    const subtextWords = ["ربما", "يبدو", "أظن", "لعل", "..."];
    const hasSubtext = subtextWords.some((word) => text.includes(word));
    if (hasSubtext) score += 0.2;

    return Math.min(1, score);
  }

  /**
   * Assess visual clarity
   */
  private async assessVisualClarity(text: string): Promise<number> {
    let score = 0.5;

    // Check for visual descriptors
    const visualWords = [
      "يرى",
      "ينظر",
      "يشاهد",
      "مشهد",
      "منظر",
      "ضوء",
      "ظلام",
      "لون",
      "حركة",
    ];
    // SECURITY FIX: Use safe RegExp utility to prevent injection
    const visualCount = safeCountMultipleTerms(text, visualWords);
    score += Math.min(0.25, visualCount * 0.025);

    // Check for spatial indicators
    const spatialWords = [
      "أمام",
      "خلف",
      "يمين",
      "يسار",
      "فوق",
      "تحت",
      "بجانب",
      "وسط",
    ];
    // SECURITY FIX: Use safe RegExp utility to prevent injection
    const spatialCount = safeCountMultipleTerms(text, spatialWords);
    score += Math.min(0.15, spatialCount * 0.03);

    // Check for action verbs
    const actionVerbs = [
      "يدخل",
      "يخرج",
      "يقف",
      "يجلس",
      "يمشي",
      "يركض",
      "يلتفت",
      "يمسك",
    ];
    // SECURITY FIX: Use safe RegExp utility to prevent injection
    const actionCount = safeCountMultipleTerms(text, actionVerbs);
    score += Math.min(0.1, actionCount * 0.02);

    return Math.min(1, score);
  }

  /**
   * Assess pacing
   */
  private async assessPacing(text: string): Promise<number> {
    let score = 0.6;

    // Check sentence variety
    const sentences = text.split(/[.!?]/);
    const lengths = sentences.map((s) => s.split(/\s+/).length);

    if (lengths.length > 3) {
      const avgLength = lengths.reduce((a, b) => a + b, 0) / lengths.length;
      const hasShort = lengths.some((l) => l < avgLength * 0.5);
      const hasLong = lengths.some((l) => l > avgLength * 1.5);

      if (hasShort && hasLong) score += 0.2; // Good variety
    }

    // Check for rhythm markers
    const rhythmWords = ["ثم", "بعد", "فجأة", "ببطء", "بسرعة", "في الحال"];
    // SECURITY FIX: Use safe RegExp utility to prevent injection
    const rhythmCount = safeCountMultipleTerms(text, rhythmWords);
    score += Math.min(0.2, rhythmCount * 0.04);

    return Math.min(1, score);
  }

  /**
   * Helper methods
   */
  private isCharacterName(line: string): boolean {
    return /^[أ-ي\s]+:/.test(line) || /^[A-Z\s]+:/.test(line);
  }

  private isDialogue(line: string): boolean {
    return (
      line.includes('"') ||
      line.includes("«") ||
      (line.includes(":") && line.length > 20)
    );
  }

  private isStageDirection(line: string): boolean {
    return (
      line.startsWith("(") ||
      line.includes("[") ||
      line.toLowerCase().includes("يدخل") ||
      line.toLowerCase().includes("يخرج")
    );
  }

  private formatDialogue(text: string): string {
    if (!text.startsWith('"') && !text.includes("«")) {
      return `"${text}"`;
    }
    return text;
  }

  private extractSceneHeading(text: string): string | null {
    const lines = text.split("\n");
    const heading = lines.find(
      (line) =>
        line.includes("INT.") ||
        line.includes("EXT.") ||
        line.includes("داخلي") ||
        line.includes("خارجي") ||
        line.includes("المشهد")
    );
    return heading ?? null;
  }

  private extractDescription(text: string): string | null {
    const paragraphs = text.split("\n\n");
    const description = paragraphs.find(
      (p) => p.length > 100 && !p.includes('"') && !p.includes(":")
    );
    return description ?? null;
  }

  private extractAction(text: string): string {
    // Return everything that's not heading or pure description
    const heading = this.extractSceneHeading(text);
    const description = this.extractDescription(text);

    let action = text;
    if (heading) action = action.replace(heading, "");
    if (description) action = action.replace(description, "");

    return action.trim();
  }

  private calculateDialoguePercentage(text: string): number {
    const dialogueMatches = text.match(/"[^"]+"|«[^»]+»/g) ?? [];
    const dialogueLength = dialogueMatches.join("").length;
    return Math.round((dialogueLength / text.length) * 100);
  }

  private countCharacters(text: string): number {
    const characterNames = new Set<string>();
    const lines = text.split("\n");

    for (const line of lines) {
      if (this.isCharacterName(line)) {
        const name = line.split(":")[0]?.trim();
        if (name) characterNames.add(name);
      }
    }

    return characterNames.size;
  }

  private summarizeScene(scene: any): string {
    if (typeof scene === "string") {
      return scene.substring(0, 200) + "...";
    }
    return "مشهد سابق";
  }

  private formatCharacter(character: any): string {
    if (typeof character === "string") return character;

    const parts: string[] = [];
    if (character.name) parts.push(character.name);
    if (character.role) parts.push(`(${character.role})`);
    if (character.motivation) parts.push(`- الدافع: ${character.motivation}`);

    return parts.join(" ") || "شخصية";
  }

  /**
   * Generate scene notes
   */
  private generateSceneNotes(
    output: StandardAgentOutput,
    tension: number,
    dialogue: number,
    visual: number,
    pacing: number
  ): string[] {
    const notes: string[] = [];

    // Overall quality
    const avgQuality = (tension + dialogue + visual + pacing) / 4;
    if (avgQuality > 0.8) {
      notes.push("مشهد ممتاز الجودة");
    } else if (avgQuality > 0.6) {
      notes.push("مشهد جيد");
    } else {
      notes.push("يحتاج تحسين");
    }

    // Specific strengths/weaknesses
    if (tension > 0.8) notes.push("توتر درامي قوي");
    if (dialogue > 0.8) notes.push("حوارات متميزة");
    if (visual > 0.8) notes.push("وضوح بصري ممتاز");
    if (pacing > 0.8) notes.push("إيقاع متوازن");

    if (tension < 0.5) notes.push("يحتاج مزيد من الصراع");
    if (dialogue < 0.5) notes.push("الحوار يحتاج تطوير");

    // Add original notes
    if (output.notes) {
      notes.push(...output.notes);
    }

    return notes;
  }

  /**
   * Translation helpers
   */
  private translateSceneType(type: string): string {
    const types: Record<string, string> = {
      dramatic: "درامي",
      action: "حركة",
      dialogue: "حواري",
      emotional: "عاطفي",
      comedic: "كوميدي",
      suspense: "تشويق",
      romantic: "رومانسي",
    };
    return types[type] ?? type;
  }

  private translateEmotionalTone(tone: string): string {
    const tones: Record<string, string> = {
      neutral: "محايد",
      tense: "متوتر",
      happy: "سعيد",
      sad: "حزين",
      angry: "غاضب",
      fearful: "خائف",
      hopeful: "متفائل",
      melancholic: "حزين عميق",
    };
    return tones[tone] ?? tone;
  }

  private translateConflictLevel(level: string): string {
    const levels: Record<string, string> = {
      none: "بدون صراع",
      low: "منخفض",
      medium: "متوسط",
      high: "عالي",
      extreme: "شديد جداً",
    };
    return levels[level] ?? level;
  }

  /**
   * Generate fallback response
   */
  protected override async getFallbackResponse(
    input: StandardAgentInput
  ): Promise<string> {
    const sceneType =
      (typeof input.context === "object" && input.context?.sceneType) ??
      "dramatic";

    return `وصف المشهد:
مشهد ${this.translateSceneType(sceneType)} يحتاج إلى تطوير أعمق للشخصيات والصراع.

نموذج مبسط:
[المكان والزمان]
الشخصيات تدخل المشهد. حوار أساسي يعبر عن الموقف.
تطور في الأحداث يدفع القصة للأمام.

ملاحظة: يُرجى تفعيل الخيارات المتقدمة وتوفير المزيد من التفاصيل عن الشخصيات والسياق للحصول على مشهد أكثر عمقاً وتفصيلاً.`;
  }
}

// Export singleton instance
export const sceneGeneratorAgent = new SceneGeneratorAgent();

import { TaskType } from "@core/types";

import { log } from "../../services/loggerService";
import { platformGenAIService } from "../../services/platformGenAIService";

import {
  StandardAgentInput,
  StandardAgentOptions,
  StandardAgentOutput,
 executeStandardAgentPattern } from "./standardAgentPattern";


/**
 * Base Agent Class - النمط القياسي لجميع الوكلاء
 * يطبق: RAG → Self-Critique → Constitutional → Uncertainty → Hallucination → Debate
 * إخراج نصي فقط - لا JSON في الواجهة
 */
export abstract class BaseAgent {
  protected name: string;
  protected taskType: TaskType;
  protected systemPrompt: string;
  protected confidenceFloor = 0.7;

  constructor(name: string, taskType: TaskType, systemPrompt: string) {
    this.name = name;
    this.taskType = taskType;
    this.systemPrompt = systemPrompt;
  }

  /**
   * Execute task with standard agent pattern
   * Input: { input, options, context }
   * Output: { text, confidence, notes } - نصي فقط
   */
  async executeTask(input: StandardAgentInput): Promise<StandardAgentOutput> {
    log.info("Starting task execution", { agentName: this.name }, "BaseAgent");

    try {
      // Build the base prompt from input
      const basePrompt = this.buildPrompt(input);

      // Merge options with agent defaults
      const options: StandardAgentOptions = {
        temperature: input.options?.temperature ?? 0.7,
        maxTokens: input.options?.maxTokens ?? 48192,
        timeout: input.options?.timeout ?? 30000,
        retries: input.options?.retries ?? 2,
        enableCaching: input.options?.enableCaching ?? true,
        enableLogging: input.options?.enableLogging ?? true,
      };

      // Execute standard pattern
      const result = await executeStandardAgentPattern(basePrompt, options, {
        ...(typeof input.context === "object" ? input.context : {}),
        taskType: this.taskType,
        agentName: this.name,
        systemPrompt: this.systemPrompt,
      });

      // Add agent-specific post-processing if needed
      const processedResult = await this.postProcess(result);

      log.info(
        "Task completed",
        { agentName: this.name, confidence: processedResult.confidence },
        "BaseAgent"
      );

      return processedResult;
    } catch (error) {
      log.error(
        "Task execution failed",
        { agentName: this.name, error },
        "BaseAgent"
      );

      // Return graceful fallback - نص بسيط مع ثقة منخفضة
      return {
        text: await this.getFallbackResponse(input),
        confidence: 0.3,
        notes: [
          `خطأ في التنفيذ: ${error instanceof Error ? error.message : "خطأ غير معروف"}`,
        ],
        metadata: {
          ragUsed: false,
          critiqueIterations: 0,
          constitutionalViolations: 0,
          uncertaintyScore: 1.0,
          hallucinationDetected: false,
          debateRounds: 0,
        },
      };
    }
  }

  /**
   * Build the prompt from input - to be implemented by each agent
   */
  protected abstract buildPrompt(input: StandardAgentInput): string;

  /**
   * Optional post-processing - agents can override this
   */
  protected async postProcess(
    output: StandardAgentOutput
  ): Promise<StandardAgentOutput> {
    // Default: no post-processing
    return output;
  }

  /**
   * Generate fallback response when execution fails
   */
  protected async getFallbackResponse(
    input: StandardAgentInput
  ): Promise<string> {
    try {
      // Try simple generation with system prompt only
      const fallbackPrompt = `${this.systemPrompt}\n\nالمهمة: ${input.input}\n\nقدم إجابة مختصرة ومباشرة.`;

      const response = await platformGenAIService.generateText(fallbackPrompt, {
        temperature: 0.5,
        maxTokens: 4096,
      });

      return response || "عذراً، لم أتمكن من إكمال المهمة المطلوبة.";
    } catch {
      return "عذراً، حدث خطأ في معالجة الطلب. يرجى المحاولة مرة أخرى.";
    }
  }

  /**
   * Get agent configuration
   */
  getConfig() {
    return {
      name: this.name,
      taskType: this.taskType,
      confidenceFloor: this.confidenceFloor,
      supportsRAG: true,
      supportsSelfCritique: true,
      supportsConstitutional: true,
      supportsUncertainty: true,
      supportsHallucination: true,
      supportsDebate: true,
    };
  }

  /**
   * Set confidence floor for this agent
   */
  setConfidenceFloor(threshold: number) {
    this.confidenceFloor = Math.max(0, Math.min(1, threshold));
  }
}

/**
 * وحدة النقد الذاتي - Self-Critique Module
 * يمكن استخدامها من أي وكيل لتحسين مخرجاته
 *
 * Based on Self-Refine and Constitutional AI research
 */

import { SelfCritiqueResult } from "../../core/types";
import { log } from "../../services/loggerService";
import { platformGenAIService } from "../../services/platformGenAIService";

export class SelfCritiqueModule {
  /**
   * تطبيق النقد الذاتي على مخرج
   * Apply self-critique to improve output
   */
  async applySelfCritique(
    output: string,
    task: string,
    context: any,
    maxIterations = 3
  ): Promise<SelfCritiqueResult> {
    log.info("Starting self-critique", { maxIterations }, "SelfCritiqueModule");

    let currentOutput = output;
    const critiques: string[] = [];
    let iteration = 0;

    for (let i = 0; i < maxIterations; i++) {
      iteration = i + 1;
      log.debug(
        "Self-critique iteration started",
        { iteration, maxIterations },
        "SelfCritiqueModule"
      );

      // Reflection phase: نقد المخرج الحالي
      const critique = await this.generateCritique(
        currentOutput,
        task,
        context
      );
      critiques.push(critique);

      // Check if improvement is needed
      const needsImprovement = await this.needsImprovement(
        currentOutput,
        critique
      );

      if (!needsImprovement) {
        log.info(
          "Self-critique output accepted",
          { iteration },
          "SelfCritiqueModule"
        );
        break;
      }

      // Refinement phase: تحسين المخرج
      currentOutput = await this.refineOutput(
        currentOutput,
        critique,
        task,
        context
      );
    }

    // Calculate improvement score
    const improvementScore = await this.calculateImprovement(
      output,
      currentOutput
    );

    log.info(
      "Self-critique complete",
      { improvementScore },
      "SelfCritiqueModule"
    );

    return {
      originalOutput: output,
      critiques,
      refinedOutput: currentOutput,
      improvementScore,
      iterations: iteration,
    };
  }

  /**
   * توليد نقد للمخرج
   * Generate critique for output
   */
  private async generateCritique(
    output: string,
    task: string,
    context: any
  ): Promise<string> {
    const critiquePrompt = `
أنت ناقد محترف متخصص في المحتوى الدرامي.

المهمة الأصلية:
${task}

السياق:
${JSON.stringify(context, null, 2).substring(0, 1000)}

المخرج الحالي:
"""
${output}
"""

قم بتقييم المخرج نقدياً من حيث:
1. **نقاط القوة**: ما الجيد في المخرج؟
2. **نقاط الضعف**: ما الذي يحتاج تحسين؟
3. **التحسينات المقترحة**: كيف يمكن تحسينه؟
4. **الأخطاء**: هل هناك أخطاء أو تناقضات؟

قدم تقييماً نقدياً مفصلاً:
`;

    try {
      return await platformGenAIService.generateText(critiquePrompt);
    } catch (error) {
      log.error("Error generating critique", error, "SelfCritiqueModule");
      return "لا يوجد نقد متاح";
    }
  }

  /**
   * فحص إذا كان المخرج يحتاج تحسين
   * Check if output needs improvement
   */
  private async needsImprovement(
    _output: string,
    critique: string
  ): Promise<boolean> {
    const checkPrompt = `
بناءً على النقد التالي:
"""
${critique}
"""

هل المخرج بحاجة لتحسين إضافي؟

أجب بـ "yes" إذا كان يحتاج تحسين، أو "no" إذا كان جيداً بما فيه الكفاية.
أجب بكلمة واحدة فقط:
`;

    try {
      const result = await platformGenAIService.generateText(checkPrompt);
      return result.trim().toLowerCase().includes("yes");
    } catch (error) {
      log.error("Error checking improvement need", error, "SelfCritiqueModule");
      return false; // Default to no improvement needed on error
    }
  }

  /**
   * تحسين المخرج بناءً على النقد
   * Refine output based on critique
   */
  private async refineOutput(
    output: string,
    critique: string,
    task: string,
    context: any
  ): Promise<string> {
    const refinementPrompt = `
المهمة الأصلية:
${task}

السياق:
${JSON.stringify(context, null, 2).substring(0, 1000)}

المخرج الحالي:
"""
${output}
"""

النقد والملاحظات:
"""
${critique}
"""

قم بتحسين المخرج بناءً على النقد والملاحظات.
احتفظ بالجوانب الجيدة، وحسّن نقاط الضعف.

أعد المخرج المحسّن فقط بدون شروحات:
`;

    try {
      return await platformGenAIService.generateText(refinementPrompt);
    } catch (error) {
      log.error("Error refining output", error, "SelfCritiqueModule");
      return output; // Return original on error
    }
  }

  /**
   * حساب درجة التحسين
   * Calculate improvement score
   */
  private async calculateImprovement(
    original: string,
    refined: string
  ): Promise<number> {
    // Simple comparison - can be enhanced with more sophisticated metrics
    if (original === refined) return 0;

    const assessmentPrompt = `
المخرج الأصلي:
"""
${original.substring(0, 1500)}
"""

المخرج المحسّن:
"""
${refined.substring(0, 1500)}
"""

قيّم مستوى التحسين على مقياس من 0 إلى 1:
- 0 = لا يوجد تحسين أو أسوأ
- 0.5 = تحسين متوسط
- 1 = تحسين ممتاز

أجب برقم فقط (مثال: 0.75):
`;

    try {
      const result = await platformGenAIService.generateText(assessmentPrompt);
      const score = parseFloat(result.trim());
      return isNaN(score) ? 0.5 : Math.min(Math.max(score, 0), 1);
    } catch (error) {
      log.error("Error calculating improvement", error, "SelfCritiqueModule");
      return 0.5; // Default to medium improvement
    }
  }
}

