/**
 * Standard Agent Execution Pattern
 *
 * This module provides a unified execution pattern for all drama analyst agents:
 * RAG → Self-Critique → Constitutional → Uncertainty → Hallucination → (Optional) Debate
 *
 * All agents must follow this pattern to ensure:
 * - Consistent quality
 * - Text-only outputs (no JSON to UI)
 * - Proper confidence tracking
 * - Constitutional compliance
 */

import { callGeminiText, toText } from "@/lib/ai/gemini-core";

import type { ModelId } from "@/lib/ai/gemini-core";

// =====================================================
// Types
// =====================================================

export interface StandardAgentInput {
  input: string;
  options?: StandardAgentOptions;
  context?: string | Record<string, any>;
}

export interface StandardAgentOptions {
  temperature?: number;
  maxTokens?: number;
  timeout?: number;
  retries?: number;
  enableCaching?: boolean;
  enableLogging?: boolean;
  enableRAG?: boolean;
  enableSelfCritique?: boolean;
  enableConstitutional?: boolean;
  enableUncertainty?: boolean;
  enableHallucination?: boolean;
  enableDebate?: boolean;
  confidenceThreshold?: number;
  maxIterations?: number;
}

export interface StandardAgentOutput {
  text: string;
  confidence: number;
  notes: string[];
  metadata?: {
    ragUsed?: boolean;
    critiqueIterations?: number;
    constitutionalViolations?: number;
    uncertaintyScore?: number;
    hallucinationDetected?: boolean;
    debateRounds?: number;
    completionQuality?: number;
    creativityScore?: number;
    sceneQuality?: number;
    worldQuality?: any;
    processingTime?: number;
    [key: string]: any; // Allow additional metadata properties
  };
}

export interface RAGContext {
  chunks: string[];
  relevanceScores: number[];
}

export interface SelfCritiqueResult {
  improved: boolean;
  iterations: number;
  finalText: string;
  improvementScore: number;
}

export interface ConstitutionalCheckResult {
  compliant: boolean;
  violations: string[];
  correctedText: string;
}

export interface UncertaintyMetrics {
  score: number;
  confidence: number;
  uncertainAspects: string[];
}

export interface HallucinationCheckResult {
  detected: boolean;
  claims: { claim: string; supported: boolean }[];
  correctedText: string;
}

// =====================================================
// Default Options
// =====================================================

const DEFAULT_OPTIONS: StandardAgentOptions = {
  temperature: 0.3,
  enableRAG: true,
  enableSelfCritique: true,
  enableConstitutional: true,
  enableUncertainty: true,
  enableHallucination: true,
  enableDebate: false,
  confidenceThreshold: 0.7,
  maxIterations: 3,
};

// =====================================================
// RAG: Retrieval-Augmented Generation
// =====================================================

async function performRAG(
  input: string,
  context?: string
): Promise<RAGContext> {
  if (!context || context.length < 100) {
    return { chunks: [], relevanceScores: [] };
  }

  // Simple chunking strategy
  const chunkSize = 500;
  const overlap = 50;
  const chunks: string[] = [];

  let start = 0;
  while (start < context.length) {
    const end = Math.min(start + chunkSize, context.length);
    chunks.push(context.substring(start, end));
    start = end - overlap;
  }

  // Score chunks by relevance (simple keyword matching)
  const inputKeywords = input
    .toLowerCase()
    .split(/\s+/)
    .filter((w) => w.length > 3);
  const relevanceScores = chunks.map((chunk) => {
    const chunkLower = chunk.toLowerCase();
    let score = 0;
    inputKeywords.forEach((keyword) => {
      if (chunkLower.includes(keyword)) score++;
    });
    return score / Math.max(inputKeywords.length, 1);
  });

  // Sort by relevance and take top 3
  const indexed = chunks.map((chunk, i) => ({
    chunk,
    score: relevanceScores[i],
  }));
  indexed.sort((a, b) => (b.score ?? 0) - (a.score ?? 0));

  const topChunks = indexed.slice(0, 3).map((x) => x.chunk);
  const topScores = indexed.slice(0, 3).map((x) => x.score ?? 0);

  return {
    chunks: topChunks,
    relevanceScores: topScores,
  };
}

function buildPromptWithRAG(
  basePrompt: string,
  ragContext: RAGContext
): string {
  if (ragContext.chunks.length === 0) {
    return basePrompt;
  }

  const contextSection = ragContext.chunks
    .map((chunk, i) => `[سياق ${i + 1}]:\n${chunk}`)
    .join("\n\n");

  return `${basePrompt}\n\n=== سياق إضافي من النص ===\n${contextSection}\n\n=== نهاية السياق ===\n`;
}

// =====================================================
// Self-Critique
// =====================================================

async function performSelfCritique(
  initialText: string,
  _prompt: string,
  _model: ModelId,
  temperature: number,
  maxIterations: number
): Promise<SelfCritiqueResult> {
  let currentText = initialText;
  let iterations = 0;
  let improved = false;

  for (let i = 0; i < maxIterations; i++) {
    iterations++;

    // Generate critique
    const critiquePrompt = `قم بمراجعة النص التالي وحدد نقاط الضعف أو الأخطاء:

النص:
${currentText.substring(0, 2000)}

قدم نقدًا بناءً يحدد:
1. الأخطاء المنطقية
2. التناقضات
3. النقاط غير الواضحة
4. المبالغات أو الادعاءات غير المدعومة

إذا كان النص جيدًا بما فيه الكفاية، قل "لا يوجد تحسينات ضرورية".`;

    const critique = await callGeminiText(critiquePrompt, {
      temperature: 0.2,
    });

    // Check if improvement is needed
    if (
      critique.toLowerCase().includes("لا يوجد تحسينات") ||
      critique.toLowerCase().includes("النص جيد")
    ) {
      improved = i > 0;
      break;
    }

    // Generate improved version
    const improvementPrompt = `بناءً على النقد التالي، قم بتحسين النص:

النص الأصلي:
${currentText.substring(0, 2000)}

النقد:
${critique.substring(0, 1000)}

قدم نسخة محسّنة من النص تعالج نقاط الضعف المذكورة.`;

    const improvedText = await callGeminiText(improvementPrompt, {
      temperature,
    });

    currentText = improvedText;
    improved = true;
  }

  // Calculate improvement score
  const improvementScore = iterations > 1 ? 0.8 : improved ? 0.5 : 1.0;

  return {
    improved,
    iterations,
    finalText: currentText,
    improvementScore,
  };
}

// =====================================================
// Constitutional AI
// =====================================================

const CONSTITUTIONAL_RULES = [
  {
    name: "احترام النص الأصلي",
    description: "يجب عدم تحريف أو تغيير المعنى الأساسي للنص الأصلي",
    check: (text: string) => {
      // Simple heuristic: output shouldn't contradict input
      return (
        !text.toLowerCase().includes("على عكس النص") &&
        !text.toLowerCase().includes("خلافًا لما ورد")
      );
    },
  },
  {
    name: "عدم المبالغة",
    description: "تجنب الادعاءات المبالغ فيها أو غير المدعومة",
    check: (text: string) => {
      const exaggerations = [
        "دائمًا",
        "أبدًا",
        "كل",
        "لا شيء",
        "مستحيل",
        "حتمًا",
      ];
      const lowerText = text.toLowerCase();
      const count = exaggerations.filter((word) =>
        lowerText.includes(word)
      ).length;
      return count < 3;
    },
  },
  {
    name: "الوضوح والدقة",
    description: "يجب أن يكون التحليل واضحًا ودقيقًا",
    check: (text: string) => {
      return text.length > 50 && !text.includes("...") && !text.includes("إلخ");
    },
  },
  {
    name: "الموضوعية",
    description: "تجنب الأحكام الشخصية المفرطة",
    check: (text: string) => {
      const subjective = ["أعتقد", "في رأيي", "أظن", "ربما"];
      const lowerText = text.toLowerCase();
      const count = subjective.filter((phrase) =>
        lowerText.includes(phrase)
      ).length;
      return count < 2;
    },
  },
  {
    name: "الاحترام والأدب",
    description: "تجنب اللغة المسيئة أو غير المحترمة",
    check: (text: string) => {
      const offensive = ["سخيف", "غبي", "تافه", "عديم القيمة"];
      const lowerText = text.toLowerCase();
      return !offensive.some((word) => lowerText.includes(word));
    },
  },
];

async function performConstitutionalCheck(
  text: string,
  _input: string,
  _model: ModelId,
  temperature: number
): Promise<ConstitutionalCheckResult> {
  const violations: string[] = [];

  // Check each rule
  for (const rule of CONSTITUTIONAL_RULES) {
    if (!rule.check(text)) {
      violations.push(rule.name);
    }
  }

  if (violations.length === 0) {
    return {
      compliant: true,
      violations: [],
      correctedText: text,
    };
  }

  // Generate corrected version
  const correctionPrompt = `النص التالي يحتوي على انتهاكات للمبادئ الدستورية:

الانتهاكات: ${violations.join(", ")}

النص:
${text.substring(0, 2000)}

قم بتصحيح النص مع الحفاظ على المعنى الأساسي ولكن معالجة الانتهاكات المذكورة.`;

  const correctedText = await callGeminiText(correctionPrompt, {
    temperature,
  });

  return {
    compliant: false,
    violations,
    correctedText,
  };
}

// =====================================================
// Uncertainty Quantification
// =====================================================

async function measureUncertainty(
  text: string,
  prompt: string,
  _model: ModelId,
  temperature: number
): Promise<UncertaintyMetrics> {
  // Generate alternative versions
  const alternatives: string[] = [text];

  for (let i = 0; i < 2; i++) {
    const alt = await callGeminiText(prompt, {
      temperature: temperature + 0.2,
    });
    alternatives.push(alt);
  }

  // Calculate consistency
  const avgLength =
    alternatives.reduce((sum, t) => sum + t.length, 0) / alternatives.length;
  const lengthVariance =
    alternatives.reduce(
      (sum, t) => sum + Math.pow(t.length - avgLength, 2),
      0
    ) / alternatives.length;

  const consistency = 1 - Math.min(lengthVariance / (avgLength * avgLength), 1);
  const uncertaintyScore = 1 - consistency;
  const confidence = Math.max(0.5, consistency);

  // Identify uncertain aspects (simple heuristic)
  const uncertainPhrases =
    text.match(/ربما|قد يكون|محتمل|من الممكن|غالبًا/gi) ?? [];

  return {
    score: uncertaintyScore,
    confidence,
    uncertainAspects: uncertainPhrases.slice(0, 3),
  };
}

// =====================================================
// Hallucination Detection
// =====================================================

async function detectHallucinations(
  text: string,
  input: string,
  _model: ModelId
): Promise<HallucinationCheckResult> {
  // Extract claims
  const claimsPrompt = `استخرج الادعاءات الرئيسية من النص التالي، كل ادعاء في سطر:

${text.substring(0, 1500)}

قدم قائمة بالادعاءات فقط، كل ادعاء في سطر منفصل.`;

  const claimsText = await callGeminiText(claimsPrompt, {
    temperature: 0.1,
  });

  const claims = claimsText
    .split("\n")
    .map((line: string) => line.trim())
    .filter((line: string) => line.length > 0)
    .slice(0, 5);

  // Check each claim against input
  const checkedClaims = await Promise.all(
    claims.map(async (claim: string) => {
      const checkPrompt = `هل الادعاء التالي مدعوم بالنص الأصلي؟

النص الأصلي:
${input.substring(0, 2000)}

الادعاء:
${claim}

أجب بـ "نعم" أو "لا" فقط.`;

      const result = await callGeminiText(checkPrompt, {
        temperature: 0.1,
      });

      return {
        claim,
        supported: result.toLowerCase().includes("نعم"),
      };
    })
  );

  const unsupportedClaims = checkedClaims.filter(
    (c: { claim: string; supported: boolean }) => !c.supported
  );
  const detected = unsupportedClaims.length > 0;

  let correctedText = text;
  if (detected) {
    const correctionPrompt = `قم بتصحيح النص التالي بإزالة أو تصحيح الادعاءات غير المدعومة:

النص:
${text.substring(0, 2000)}

الادعاءات غير المدعومة:
${unsupportedClaims.map((c) => `- ${c.claim}`).join("\n")}

قدم نسخة محسنة بدون ادعاءات غير مدعومة.`;

    correctedText = await callGeminiText(correctionPrompt, {
      temperature: 0.2,
    });
  }

  return {
    detected,
    claims: checkedClaims,
    correctedText,
  };
}

// =====================================================
// Standard Agent Execution
// =====================================================

export async function executeStandardAgentPattern(
  taskPrompt: string,
  options: StandardAgentOptions,
  context?: Record<string, unknown>
): Promise<StandardAgentOutput> {
  const mergedOptions = { ...DEFAULT_OPTIONS, ...options };
  const notes: string[] = [];
  let currentText = "";
  let confidence = 0.7;

  const metadata = {
    ragUsed: false,
    critiqueIterations: 0,
    constitutionalViolations: 0,
    uncertaintyScore: 0,
    hallucinationDetected: false,
    debateRounds: 0,
  };

  try {
    // Step 1: RAG
    let finalPrompt = taskPrompt;
    if (mergedOptions.enableRAG && context?.originalText) {
      const ragContext = await performRAG(
        taskPrompt,
        context.originalText as string
      );
      finalPrompt = buildPromptWithRAG(taskPrompt, ragContext);
      metadata.ragUsed = ragContext.chunks.length > 0;
      if (metadata.ragUsed) {
        notes.push(`استخدم RAG: ${ragContext.chunks.length} أجزاء ذات صلة`);
      }
    }

    // Initial generation
    currentText = await callGeminiText(finalPrompt, {
      temperature: mergedOptions.temperature ?? 0.3,
    });

    // Step 2: Self-Critique
    if (options.enableSelfCritique) {
      const critiqueResult = await performSelfCritique(
        currentText,
        finalPrompt,
        "gemini-1.5-flash",
        mergedOptions.temperature ?? 0.3,
        mergedOptions.maxIterations ?? 3
      );
      currentText = critiqueResult.finalText;
      metadata.critiqueIterations = critiqueResult.iterations;
      confidence *= critiqueResult.improvementScore;
      if (critiqueResult.improved) {
        notes.push(`تم التحسين عبر ${critiqueResult.iterations} دورة نقد ذاتي`);
      }
    }

    // Step 3: Constitutional Check
    if (options.enableConstitutional) {
      const constitutionalResult = await performConstitutionalCheck(
        currentText,
        taskPrompt,
        "gemini-1.5-flash",
        mergedOptions.temperature ?? 0.3
      );
      currentText = constitutionalResult.correctedText;
      metadata.constitutionalViolations =
        constitutionalResult.violations.length;
      if (!constitutionalResult.compliant) {
        notes.push(
          `تصحيح دستوري: ${constitutionalResult.violations.join(", ")}`
        );
        confidence *= 0.9;
      }
    }

    // Step 4: Uncertainty Quantification
    if (options.enableUncertainty) {
      const uncertaintyMetrics = await measureUncertainty(
        currentText,
        finalPrompt,
        "gemini-1.5-flash",
        mergedOptions.temperature ?? 0.3
      );
      metadata.uncertaintyScore = uncertaintyMetrics.score;
      confidence = Math.min(confidence, uncertaintyMetrics.confidence);
      if (uncertaintyMetrics.uncertainAspects.length > 0) {
        notes.push(
          `جوانب غير مؤكدة: ${uncertaintyMetrics.uncertainAspects.length}`
        );
      }
    }

    // Step 5: Hallucination Detection
    if (options.enableHallucination) {
      const hallucinationResult = await detectHallucinations(
        currentText,
        taskPrompt,
        "gemini-1.5-flash"
      );
      metadata.hallucinationDetected = hallucinationResult.detected;
      if (hallucinationResult.detected) {
        currentText = hallucinationResult.correctedText;
        const unsupported = hallucinationResult.claims.filter(
          (c) => !c.supported
        ).length;
        notes.push(`تصحيح هلوسة: ${unsupported} ادعاء غير مدعوم`);
        confidence *= 0.85;
      }
    }

    // Step 6: Debate (Optional - if confidence is low)
    if (
      mergedOptions.enableDebate &&
      confidence < (mergedOptions.confidenceThreshold ?? 0.7)
    ) {
      notes.push("الثقة منخفضة - يُوصى بتفعيل النقاش متعدد الوكلاء");
      // Debate would be handled at orchestration level
    }

    // Final output
    return {
      text: toText(currentText),
      confidence: Math.round(confidence * 100) / 100,
      notes,
      metadata,
    };
  } catch (error) {
    const errorMsg = error instanceof Error ? error.message : "خطأ غير معروف";
    return {
      text: `حدث خطأ في التنفيذ: ${errorMsg}`,
      confidence: 0,
      notes: [`خطأ: ${errorMsg}`],
      metadata,
    };
  }
}

// =====================================================
// Helper: Format output for display (text only, no JSON)
// =====================================================

export function formatAgentOutput(
  output: StandardAgentOutput,
  agentName: string
): string {
  const sections = [
    `=== ${agentName} - التقرير ===`,
    "",
    `الثقة: ${(output.confidence * 100).toFixed(0)}%`,
    "",
    "--- التحليل ---",
    output.text,
    "",
  ];

  if (output.notes.length > 0) {
    sections.push("--- ملاحظات ---");
    output.notes.forEach((note) => sections.push(`• ${note}`));
    sections.push("");
  }

  if (output.metadata) {
    sections.push("--- معلومات إضافية ---");
    if (output.metadata.ragUsed) sections.push("✓ استخدم RAG");
    if ((output.metadata.critiqueIterations ?? 0) > 0) {
      sections.push(`✓ نقد ذاتي: ${output.metadata.critiqueIterations} دورات`);
    }
    if ((output.metadata.constitutionalViolations ?? 0) > 0) {
      sections.push(
        `⚠ انتهاكات دستورية: ${output.metadata.constitutionalViolations}`
      );
    }
    if (output.metadata.hallucinationDetected) {
      sections.push("⚠ تم اكتشاف وتصحيح هلوسات");
    }
  }

  sections.push("");
  sections.push("=".repeat(50));

  return sections.join("\n");
}

import { TaskType } from "@core/types";

import { BaseAgent } from "../shared/BaseAgent";
import {
  StandardAgentInput,
  StandardAgentOutput,
} from "../shared/standardAgentPattern";

import { STYLE_FINGERPRINT_AGENT_CONFIG } from "./agent";

interface StyleFingerprintContext {
  originalText?: string;
  analysisReport?: any;
  compareWithText?: string;
  analysisDepth?: string; // 'basic', 'detailed', 'comprehensive'
  focusAreas?: string[]; // ['lexical', 'syntactic', 'rhetorical', 'thematic']
  authorSamples?: string[];
}

/**
 * Style Fingerprint Agent - وكيل بصمة الأسلوب
 * يطبق النمط القياسي: RAG → Self-Critique → Constitutional → Uncertainty → Hallucination → Debate
 * إخراج نصي فقط - لا JSON
 */
export class StyleFingerprintAgent extends BaseAgent {
  constructor() {
    super(
      "AuthorDNA AI",
      TaskType.STYLE_FINGERPRINT,
      STYLE_FINGERPRINT_AGENT_CONFIG.systemPrompt ?? ""
    );

    this.confidenceFloor = 0.85;
  }

  protected buildPrompt(input: StandardAgentInput): string {
    const { input: taskInput, context } = input;
    const ctx = context as StyleFingerprintContext;

    const originalText = ctx?.originalText ?? "";
    const compareWithText = ctx?.compareWithText ?? "";
    const analysisDepth = ctx?.analysisDepth ?? "detailed";
    const focusAreas = ctx?.focusAreas ?? [
      "lexical",
      "syntactic",
      "rhetorical",
    ];
    const authorSamples = ctx?.authorSamples ?? [];

    let prompt = `مهمة استخراج بصمة الأسلوب الأدبي\n\n`;

    if (originalText) {
      prompt += `النص المراد تحليله:\n${originalText.substring(0, 2500)}...\n\n`;
    }

    if (authorSamples.length > 0) {
      prompt += `نماذج إضافية من نفس المؤلف:\n`;
      authorSamples.slice(0, 2).forEach((sample, idx) => {
        prompt += `[نموذج ${idx + 1}]: ${sample.substring(0, 300)}...\n`;
      });
      prompt += "\n";
    }

    prompt += `مستوى العمق: ${this.translateDepth(analysisDepth)}\n`;
    prompt += `مجالات التركيز: ${focusAreas.map(this.translateFocusArea).join("، ")}\n\n`;

    if (compareWithText) {
      prompt += `نص للمقارنة:\n${compareWithText.substring(0, 1000)}...\n\n`;
    }

    prompt += `المهمة المطلوبة:\n${taskInput}\n\n`;

    prompt += `التعليمات:

1. **التحليل المعجمي** (Lexical Analysis):
   - غنى المفردات وتنوعها
   - توزيع تكرار الكلمات
   - استخدام الكلمات النادرة أو المميزة
   - طول الكلمات المتوسط والنطاق

2. **التحليل النحوي** (Syntactic Analysis):
   - بنية الجمل (بسيطة، مركبة، معقدة)
   - طول الجمل المتوسط والتباين
   - أنماط علامات الترقيم
   - الصيغ النحوية المفضلة (مبني للمعلوم/مجهول)

3. **التحليل البلاغي** (Rhetorical Analysis):
   - اللغة المجازية (استعارات، تشبيهات)
   - الأدوات البلاغية (جناس، طباق، سجع)
   - الأساليب الإنشائية (استفهام، أمر، نداء)
   - التكرار والتوازي

4. **التحليل الموضوعي والأسلوبي**:
   - النبرة العامة (رسمية، عامية، شعرية)
   - الحقول الدلالية المهيمنة
   - استراتيجيات السرد (راوي أول شخص، ثالث شخص)
   - الإيقاع والموسيقى اللغوية

5. **البصمة المميزة**:
   - العناصر الأسلوبية الفريدة للمؤلف
   - التوقيع اللغوي المميز
   - العادات الكتابية المتكررة

اكتب بشكل نصي تحليلي واضح ومفصل.
قدم أمثلة محددة من النص لتدعم كل نقطة.
لا تستخدم JSON أو جداول معقدة - نص تحليلي مباشر فقط.`;

    return prompt;
  }

  protected override async postProcess(
    output: StandardAgentOutput
  ): Promise<StandardAgentOutput> {
    const processedText = this.cleanupStyleText(output.text);

    const analyticalDepth = await this.assessAnalyticalDepth(processedText);
    const specificity = await this.assessSpecificity(processedText);
    const comprehensiveness = await this.assessComprehensiveness(processedText);
    const evidenceQuality = await this.assessEvidenceQuality(processedText);

    const qualityScore =
      analyticalDepth * 0.3 +
      specificity * 0.25 +
      comprehensiveness * 0.25 +
      evidenceQuality * 0.2;

    const adjustedConfidence = output.confidence * 0.5 + qualityScore * 0.5;

    return {
      ...output,
      text: processedText,
      confidence: adjustedConfidence,
      notes: this.generateStyleNotes(
        output,
        analyticalDepth,
        specificity,
        comprehensiveness,
        evidenceQuality
      ),
      metadata: {
        ...output.metadata,
        styleAnalysisQuality: {
          overall: qualityScore,
          analyticalDepth,
          specificity,
          comprehensiveness,
          evidenceQuality,
        },
        dimensionsAnalyzed: this.countDimensions(processedText),
        examplesProvided: this.countExamples(processedText),
      },
    };
  }

  private cleanupStyleText(text: string): string {
    text = text.replace(/```json[\s\S]*?```/g, "");
    text = text.replace(/```[\s\S]*?```/g, "");
    text = text.replace(/\{[\s\S]*?\}/g, (match) => {
      if (match.includes('"') && match.includes(":")) return "";
      return match;
    });

    text = text.replace(/\|[\s\S]*?\|/g, "");

    return text.replace(/\n{3,}/g, "\n\n").trim();
  }

  private async assessAnalyticalDepth(text: string): Promise<number> {
    let score = 0.5;

    const analyticalTerms = [
      "يتميز",
      "يلاحظ",
      "يظهر",
      "يكشف",
      "يوضح",
      "يدل",
      "يشير",
      "يعكس",
      "نلاحظ",
      "نجد",
    ];
    // SECURITY FIX: Use safe string matching to prevent ReDoS
    const termCount = analyticalTerms.reduce((count, term) => {
      // Use simple string matching instead of regex to prevent ReDoS
      const occurrences = text.split(term).length - 1;
      return count + occurrences;
    }, 0);
    score += Math.min(0.25, termCount * 0.02);

    const technicalTerms = [
      "المعجم",
      "النحو",
      "البلاغة",
      "الصرف",
      "الأسلوب",
      "التركيب",
      "الدلالة",
    ];
    // SECURITY FIX: Use safe string matching to prevent ReDoS
    const techCount = technicalTerms.reduce((count, term) => {
      // Use simple string matching instead of regex to prevent ReDoS
      const occurrences = text.split(term).length - 1;
      return count + occurrences;
    }, 0);
    score += Math.min(0.15, techCount * 0.03);

    if (text.length > 1500) score += 0.1;

    return Math.min(1, score);
  }

  private async assessSpecificity(text: string): Promise<number> {
    let score = 0.6;

    const hasQuotes = (text.match(/["«]/g) ?? []).length;
    score += Math.min(0.2, hasQuotes * 0.02);

    const hasExamples = text.includes("مثال") || text.includes("مثل");
    if (hasExamples) score += 0.1;

    const hasNumbers = (text.match(/\d+%|\d+\.\d+|نسبة|معدل|متوسط/g) ?? [])
      .length;
    score += Math.min(0.1, hasNumbers * 0.02);

    return Math.min(1, score);
  }

  private async assessComprehensiveness(text: string): Promise<number> {
    let score = 0.5;

    const dimensions = ["معجم", "نحو", "بلاغ", "أسلوب", "إيقاع", "نبرة"];
    const dimensionsCovered = dimensions.filter((dim) =>
      text.toLowerCase().includes(dim)
    ).length;
    score += (dimensionsCovered / dimensions.length) * 0.3;

    const sections = text.split("\n\n").filter((s) => s.trim().length > 100);
    if (sections.length >= 4) score += 0.2;

    return Math.min(1, score);
  }

  private async assessEvidenceQuality(text: string): Promise<number> {
    let score = 0.6;

    const evidenceWords = [
      "مثل",
      "كما في",
      "نجد",
      "يظهر ذلك",
      "على سبيل المثال",
      "مثلاً",
    ];
    // SECURITY FIX: Use safe string matching to prevent ReDoS
    const evidenceCount = evidenceWords.reduce((count, word) => {
      // Use simple string matching instead of regex to prevent ReDoS
      const occurrences = text.split(word).length - 1;
      return count + occurrences;
    }, 0);
    score += Math.min(0.25, evidenceCount * 0.05);

    const hasDirectQuotes = (text.match(/["«][^"»]{10,}["»]/g) ?? []).length;
    if (hasDirectQuotes >= 3) score += 0.15;

    return Math.min(1, score);
  }

  private countDimensions(text: string): number {
    const dimensionMarkers = ["معجمي", "نحوي", "بلاغي", "موضوعي", "أسلوبي"];
    return dimensionMarkers.filter((marker) =>
      text.toLowerCase().includes(marker)
    ).length;
  }

  private countExamples(text: string): number {
    const exampleMarkers = text.match(/مثال|مثل:|على سبيل المثال|كما في|["«]/g);
    return exampleMarkers ? Math.min(exampleMarkers.length, 20) : 0;
  }

  private generateStyleNotes(
    output: StandardAgentOutput,
    depth: number,
    specificity: number,
    comprehensiveness: number,
    evidence: number
  ): string[] {
    const notes: string[] = [];

    const avg = (depth + specificity + comprehensiveness + evidence) / 4;
    if (avg > 0.8) notes.push("تحليل أسلوبي ممتاز");
    else if (avg > 0.65) notes.push("تحليل جيد");
    else notes.push("يحتاج مزيد من العمق");

    if (depth > 0.8) notes.push("عمق تحليلي عالي");
    if (specificity > 0.8) notes.push("أمثلة محددة");
    if (comprehensiveness > 0.75) notes.push("شمولية جيدة");
    if (evidence > 0.8) notes.push("أدلة قوية");

    if (depth < 0.5) notes.push("يحتاج عمق أكبر");
    if (specificity < 0.5) notes.push("يحتاج أمثلة أكثر");
    if (comprehensiveness < 0.6) notes.push("يحتاج تغطية أوسع");

    if (output.notes) notes.push(...output.notes);

    return notes;
  }

  private translateDepth(depth: string): string {
    const depths: Record<string, string> = {
      basic: "أساسي",
      detailed: "مفصل",
      comprehensive: "شامل ومعمق",
    };
    return depths[depth] ?? depth;
  }

  private translateFocusArea(area: string): string {
    const areas: Record<string, string> = {
      lexical: "معجمي",
      syntactic: "نحوي",
      rhetorical: "بلاغي",
      thematic: "موضوعي",
      stylistic: "أسلوبي",
    };
    return areas[area] ?? area;
  }

  protected override async getFallbackResponse(
    _input: StandardAgentInput
  ): Promise<string> {
    return `التحليل المعجمي:
النص يظهر تنوعاً معجمياً يعكس مستوى لغوي متوسط إلى مرتفع.

التحليل النحوي:
الجمل متوسطة الطول مع تنوع في البنية بين البسيطة والمركبة.

التحليل البلاغي:
استخدام معتدل للأساليب البلاغية مع بعض الصور المجازية.

البصمة الأسلوبية:
الأسلوب يتميز بـ[خصائص عامة تحتاج تفصيل أكثر].

ملاحظة: يُرجى تفعيل الخيارات المتقدمة وتوفير نص أطول للحصول على تحليل أسلوبي أكثر دقة وشمولاً.`;
  }
}

export const styleFingerprintAgent = new StyleFingerprintAgent();

