 * Tension Optimizer Agent - وكيل تحسين التوتر الدرامي
 * يطبق النمط القياسي: RAG → Self-Critique → Constitutional → Uncertainty → Hallucination → Debate
 * إخراج نصي فقط - لا JSON
 */
export class TensionOptimizerAgent extends BaseAgent {
  constructor() {
    super(
      "TensionMaster AI",
      TaskType.TENSION_OPTIMIZER,
      TENSION_OPTIMIZER_AGENT_CONFIG.systemPrompt ?? ""
    );

    this.confidenceFloor = 0.81;
  }

  protected buildPrompt(input: StandardAgentInput): string {
    const { input: taskInput, context } = input;
    const ctx = context as TensionOptimizerContext;

    // Extract context with defaults
    const originalText = ctx?.originalText ?? "";
    const sceneBreakdown = ctx?.sceneBreakdown ?? [];
    const currentTensionLevel = ctx?.currentTensionLevel ?? "medium";
    const targetTensionLevel = ctx?.targetTensionLevel ?? "high";
    const tensionType = ctx?.tensionType ?? "suspense";
    const pacePreference = ctx?.pacePreference ?? "steady";
    const provideRecommendations = ctx?.provideRecommendations ?? true;
    const identifyPeaks = ctx?.identifyPeaks ?? true;
    const analyzeRelease = ctx?.analyzeRelease ?? true;

    // Build prompt sections
    let prompt = `مهمة تحسين وتحليل التوتر الدرامي\n\n`;
    prompt += buildOriginalTextSection(originalText);
    prompt += buildSceneBreakdownSection(sceneBreakdown);
    prompt += buildTensionInfoSection(
      currentTensionLevel,
      targetTensionLevel,
      tensionType,
      pacePreference,
      identifyPeaks,
      analyzeRelease,
      provideRecommendations,
      this.translateLevel.bind(this),
      this.translateTensionType.bind(this),
      this.translatePace.bind(this)
    );
    prompt += `المهمة المطلوبة:\n${taskInput}\n\n`;
    prompt += getBaseInstructions();
    prompt += buildConditionalInstructions(
      identifyPeaks,
      analyzeRelease,
      provideRecommendations
    );
    prompt += getMiddleInstructions();
    prompt += getClosingInstructions();

    return prompt;
  }

  protected override async postProcess(
    output: StandardAgentOutput
  ): Promise<StandardAgentOutput> {
    const processedText = this.cleanupTensionText(output.text);

    const analysisDepth = await this.assessAnalysisDepth(processedText);
    const techniqueIdentification =
      await this.assessTechniqueIdentification(processedText);
    const practicalValue = await this.assessPracticalValue(processedText);
    const insightfulness = await this.assessInsightfulness(processedText);

    const qualityScore =
      analysisDepth * 0.3 +
      techniqueIdentification * 0.25 +
      practicalValue * 0.25 +
      insightfulness * 0.2;

    const adjustedConfidence = output.confidence * 0.5 + qualityScore * 0.5;

    return {
      ...output,
      text: processedText,
      confidence: adjustedConfidence,
      notes: this.generateTensionNotes(
        output,
        analysisDepth,
        techniqueIdentification,
        practicalValue,
        insightfulness
      ),
      metadata: {
        ...output.metadata,
        tensionAnalysisQuality: {
          overall: qualityScore,
          analysisDepth,
          techniqueIdentification,
          practicalValue,
          insightfulness,
        },
        peaksIdentified: this.countPeaks(processedText),
        techniquesIdentified: this.countTechniques(processedText),
        recommendationsProvided: this.countRecommendations(processedText),
      },
    };
  }

  private cleanupTensionText(text: string): string {
    text = text.replace(/```json[\s\S]*?```/g, "");
    text = text.replace(/```[\s\S]*?```/g, "");
    text = text.replace(/\{[\s\S]*?\}/g, (match) => {
      if (match.includes('"') && match.includes(":")) return "";
      return match;
    });

    return text.replace(/\n{3,}/g, "\n\n").trim();
  }

  private async assessAnalysisDepth(text: string): Promise<number> {
    let score = 0.5;

    const tensionTerms = [
      "توتر",
      "تشويق",
      "ترقب",
      "قلق",
      "خوف",
      "ذروة",
      "تصاعد",
      "تراكم",
    ];
    // SECURITY FIX: Use safe string matching to prevent ReDoS
    const termCount = tensionTerms.reduce((count, term) => {
      // Use simple string matching instead of regex to prevent ReDoS
      const occurrences = text.split(term).length - 1;
      return count + occurrences;
    }, 0);
    score += Math.min(0.25, termCount * 0.02);

    const analyticalTerms = [
      "يتطور",
      "يتصاعد",
      "ينخفض",
      "يبلغ",
      "يحافظ",
      "يبني",
      "يخفف",
    ];
    // SECURITY FIX: Use safe string matching to prevent ReDoS
    const analyticCount = analyticalTerms.reduce((count, term) => {
      // Use simple string matching instead of regex to prevent ReDoS
      const occurrences = text.split(term).length - 1;
      return count + occurrences;
    }, 0);
    score += Math.min(0.15, analyticCount * 0.03);

    if (text.length > 1500) score += 0.1;

    return Math.min(1, score);
  }

  private async assessTechniqueIdentification(text: string): Promise<number> {
    let score = 0.5;

    const techniques = [
      "تأخير",
      "تعليق",
      "غموض",
      "صراع",
      "وقت",
      "رهان",
      "تنبؤ",
      "تلميح",
      "مفاجأة",
    ];
    // SECURITY FIX: Use safe string matching to prevent ReDoS
    const techCount = techniques.reduce((count, tech) => {
      // Use simple string matching instead of regex to prevent ReDoS
      const occurrences = text.split(tech).length - 1;
      return count + occurrences;
    }, 0);
    score += Math.min(0.35, techCount * 0.04);

    const hasTechniqueSection =
      text.includes("تقنيات") || text.includes("أساليب");
    if (hasTechniqueSection) score += 0.15;

    return Math.min(1, score);
  }

  private async assessPracticalValue(text: string): Promise<number> {
    let score = 0.6;

    const practicalTerms = [
      "يمكن",
      "يُنصح",
      "يُفضل",
      "توصية",
      "اقتراح",
      "بدلاً من",
      "الأفضل",
    ];
    // SECURITY FIX: Use safe string matching to prevent ReDoS
    const practicalCount = practicalTerms.reduce((count, term) => {
      // Use simple string matching instead of regex to prevent ReDoS
      const occurrences = text.split(term).length - 1;
      return count + occurrences;
    }, 0);
    score += Math.min(0.25, practicalCount * 0.03);

    const hasExamples = text.includes("مثال") || text.includes("مثل");
    if (hasExamples) score += 0.15;

    return Math.min(1, score);
  }

  private async assessInsightfulness(text: string): Promise<number> {
    let score = 0.5;

    const insightWords = [
      "يكشف",
      "يوضح",
      "الأهمية",
      "التأثير",
      "الفرصة",
      "الإمكانية",
      "نلاحظ",
    ];
    // SECURITY FIX: Use safe string matching to prevent ReDoS
    const insightCount = insightWords.reduce((count, word) => {
      // Use simple string matching instead of regex to prevent ReDoS
      const occurrences = text.split(word).length - 1;
      return count + occurrences;
    }, 0);
    score += Math.min(0.3, insightCount * 0.03);

    const hasEvaluation =
      text.includes("فعال") || text.includes("ناجح") || text.includes("ضعيف");
    if (hasEvaluation) score += 0.2;

    return Math.min(1, score);
  }

  private countPeaks(text: string): number {
    const peakMarkers = text.match(/ذروة|قمة|أقصى|الذروة|نقطة/gi);
    return peakMarkers ? Math.min(peakMarkers.length, 8) : 0;
  }

  private countTechniques(text: string): number {
    const techMarkers = text.match(/تقنية|أسلوب|طريقة|استخدام|يستخدم/gi);
    return techMarkers ? Math.min(techMarkers.length, 10) : 0;
  }

  private countRecommendations(text: string): number {
    const recMarkers = text.match(/يُنصح|يُفضل|توصية|اقتراح|يمكن تحسين/gi);
    return recMarkers ? Math.min(recMarkers.length, 12) : 0;
  }

  private generateTensionNotes(
    output: StandardAgentOutput,
    depth: number,
    techniques: number,
    practical: number,
    insight: number
  ): string[] {
    const notes: string[] = [];

    const avg = (depth + techniques + practical + insight) / 4;
    if (avg > 0.8) notes.push("تحليل توتر ممتاز");
    else if (avg > 0.65) notes.push("تحليل جيد");
    else notes.push("يحتاج عمق أكبر");

    if (depth > 0.8) notes.push("عمق تحليلي عالي");
    if (techniques > 0.75) notes.push("تحديد تقنيات شامل");
    if (practical > 0.75) notes.push("توصيات عملية");
    if (insight > 0.75) notes.push("رؤى ثاقبة");

    if (depth < 0.5) notes.push("يحتاج تحليل أعمق");
    if (techniques < 0.5) notes.push("يحتاج تحديد تقنيات أوضح");
    if (practical < 0.6) notes.push("يحتاج مزيد من التوصيات");

    if (output.notes && Array.isArray(output.notes)) {
      notes.push(...output.notes);
    }

    return notes;
  }

  private translateLevel(level: string): string {
    const levels: Record<string, string> = {
      none: "معدوم",
      low: "منخفض",
      medium: "متوسط",
      high: "عالي",
      critical: "حرج/ذروة",
      extreme: "شديد جداً",
    };
    return levels[level] ?? level;
  }

  private translateTensionType(type: string): string {
    const types: Record<string, string> = {
      suspense: "تشويق وترقب",
      conflict: "صراع",
      anticipation: "توقع وانتظار",
      mystery: "غموض",
      dread: "خوف وقلق",
      urgency: "إلحاح وضيق وقت",
    };
    return types[type] ?? type;
  }

  private translatePace(pace: string): string {
    const paces: Record<string, string> = {
      "slow-burn": "تصاعد بطيء ومستمر",
      steady: "ثابت ومتزن",
      rapid: "سريع ومتصاعد",
      explosive: "انفجاري ومفاجئ",
      variable: "متغير ومتذبذب",
    };
    return paces[pace] ?? pace;
  }

  protected override async getFallbackResponse(
    _input: StandardAgentInput
  ): Promise<string> {
    return `تقييم التوتر الحالي:
النص يحتوي على مستوى توتر متوسط يحتاج إلى تعزيز وتحسين لتحقيق التأثير الدرامي المطلوب.

تحليل منحنى التوتر:
التوتر يبدأ بمستوى معتدل ويتصاعد تدريجياً، لكن التصاعد ليس حاداً بما يكفي. هناك لحظات واعدة يمكن استغلالها بشكل أفضل.

نقاط الذروة:
ذروة رئيسية واحدة في [موضع تقريبي] حيث يبلغ التوتر أقصاه، لكن البناء نحو هذه الذروة يحتاج تقوية.

لحظات التحرر:
التحرر يأتي سريعاً نوعاً ما بعد الذروة. يمكن إطالة لحظة التوتر القصوى قليلاً لتعزيز التأثير.

تقنيات بناء التوتر:
- التأخير: مستخدم بشكل محدود
- الغموض: موجود لكن يحتاج تعميق
- تصاعد الرهانات: فرصة غير مستغلة بالكامل

التوصيات:
1. تعزيز التلميحات المبكرة للخطر أو الصراع
2. إطالة لحظات الترقب قبل الكشف
3. رفع الرهانات تدريجياً عبر المشاهد
4. إضافة عناصر ضيق الوقت لزيادة الإلحاح
5. تأخير التحرر قليلاً بعد الذروة

التقييم النهائي: 6/10
التوتر موجود وفعال جزئياً، لكن هناك إمكانات كبيرة غير مستغلة لتحويله إلى تجربة أكثر إثارة وإشباعاً.

ملاحظة: يُرجى تفعيل الخيارات المتقدمة وتوفير المزيد من تفاصيل المشاهد للحصول على تحليل توتر أكثر دقة مع توصيات محددة وقابلة للتطبيق.`;
  }
}

export const tensionOptimizerAgent = new TensionOptimizerAgent();

/**
 * Prompt builder utilities for TensionOptimizerAgent
 * Extracted to reduce buildPrompt complexity
 */

/**
 * Build original text section
 */
export function buildOriginalTextSection(originalText: string): string {
  if (!originalText) return "";
  return `النص المراد تحليله:\n${originalText.substring(0, 2500)}...\n\n`;
}

/**
 * Build scene breakdown section
 */
export function buildSceneBreakdownSection(sceneBreakdown: any[]): string {
  if (sceneBreakdown.length === 0) return "";

  let section = `تفصيل المشاهد:\n`;
  sceneBreakdown.slice(0, 5).forEach((scene: any, idx: number) => {
    const sceneDesc =
      typeof scene === "string"
        ? scene
        : scene.description ?? `مشهد ${idx + 1}`;
    section += `${idx + 1}. ${sceneDesc}\n`;
  });
  section += "\n";
  return section;
}

/**
 * Build tension information section
 */
export function buildTensionInfoSection(
  currentLevel: string,
  targetLevel: string,
  tensionType: string,
  pacePreference: string,
  identifyPeaks: boolean,
  analyzeRelease: boolean,
  provideRecommendations: boolean,
  translateLevel: (level: string) => string,
  translateTensionType: (type: string) => string,
  translatePace: (pace: string) => string
): string {
  let section = `معلومات التوتر:\n`;
  section += `- المستوى الحالي: ${translateLevel(currentLevel)}\n`;
  section += `- المستوى المستهدف: ${translateLevel(targetLevel)}\n`;
  section += `- نوع التوتر: ${translateTensionType(tensionType)}\n`;
  section += `- تفضيل الوتيرة: ${translatePace(pacePreference)}\n`;
  section += `- تحديد القمم: ${identifyPeaks ? "نعم" : "لا"}\n`;
  section += `- تحليل التحرر: ${analyzeRelease ? "نعم" : "لا"}\n`;
  section += `- تقديم توصيات: ${provideRecommendations ? "نعم" : "لا"}\n\n`;
  return section;
}

/**
 * Get base instructions template
 */
export function getBaseInstructions(): string {
  return `التعليمات:

1. **تقييم التوتر الحالي** (3-4 جمل):
   - حدد مستوى التوتر العام في النص
   - أين يكون التوتر فعالاً وأين يكون ضعيفاً
   - مدى ملاءمة التوتر للنوع الدرامي والجمهور

2. **تحليل منحنى التوتر**:
   - كيف يتطور التوتر عبر النص
   - الارتفاعات والانخفاضات
   - التدرج والتصاعد
   - العلاقة بين التوتر وبنية الحبكة

`;
}

/**
 * Build conditional instructions sections
 */
export function buildConditionalInstructions(
  identifyPeaks: boolean,
  analyzeRelease: boolean,
  provideRecommendations: boolean
): string {
  let instructions = "";

  if (identifyPeaks) {
    instructions += `3. **نقاط الذروة** (Tension Peaks):
   - حدد اللحظات ذات التوتر الأقصى
   - ما الذي يجعلها فعالة (أو غير فعالة)
   - توقيتها في البنية السردية
   - مدى إشباعها للتوقعات

`;
  }

  if (analyzeRelease) {
    instructions += `4. **لحظات التحرر** (Tension Release):
   - أين وكيف يتم تخفيف التوتر
   - هل التحرر مناسب أم سابق لأوانه
   - التوازن بين البناء والتحرر
   - الفرص الضائعة لتعزيز التوتر

`;
  }

  if (provideRecommendations) {
    instructions += `7. **التوصيات والتحسينات**:
   - كيفية رفع مستوى التوتر إلى المستوى المستهدف
   - مواضع محددة تحتاج تعزيز
   - تقنيات يمكن تطبيقها
   - أمثلة على تعديلات محتملة
   - تحذيرات من الإفراط أو المبالغة

`;
  }

  return instructions;
}

/**
 * Get middle instructions
 */
export function getMiddleInstructions(): string {
  return `5. **تقنيات بناء التوتر المستخدمة**:
   - التأخير والتعليق (Suspense)
   - المعلومات الناقصة (Mystery)
   - تصاعد الصراع
   - ضيق الوقت (Ticking Clock)
   - الرهانات المتزايدة (Rising Stakes)
   - التضارب والتناقض
   - التنبؤ والتلميح (Foreshadowing)

6. **تحليل الوتيرة والإيقاع**:
   - سرعة تصاعد التوتر
   - التوازن بين لحظات الهدوء والتوتر
   - الإيقاع العام (بطيء، سريع، متقطع)

`;
}

/**
 * Get closing instructions
 */
export function getClosingInstructions(): string {
  return `8. **التقييم النهائي**:
   - فعالية التوتر الحالي (درجة من 10)
   - الإمكانات غير المستغلة
   - التوقعات للقارئ/المشاهد

اكتب بشكل نصي تحليلي مباشر مع أمثلة محددة من النص.
لا تستخدم JSON أو رسوم بيانية معقدة - تحليل نصي واضح فقط.`;
}

import { safeCountMultipleTerms } from "@/lib/security/safe-regexp";
import { TaskType } from "@core/types";

import { BaseAgent } from "../shared/BaseAgent";
import {
  StandardAgentInput,
  StandardAgentOutput,
} from "../shared/standardAgentPattern";

import { THEMATIC_MINING_AGENT_CONFIG } from "./agent";

interface ThematicMiningContext {
  originalText?: string;
  analysisReport?: any;
  genre?: string;
  culturalContext?: string;
  extractionDepth?: string; // 'surface', 'intermediate', 'deep'
  themeCategories?: string[]; // ['universal', 'social', 'personal', 'philosophical']
  minimumThemes?: number;
  includeSymbols?: boolean;
  includeMotifs?: boolean;
}

/**
 * Thematic Mining Agent - وكيل استخراج الثيمات
 * يطبق النمط القياسي: RAG → Self-Critique → Constitutional → Uncertainty → Hallucination → Debate
 * إخراج نصي فقط - لا JSON
 */
export class ThematicMiningAgent extends BaseAgent {
  constructor() {
    super(
      "ThemeMiner AI",
      TaskType.THEMATIC_MINING,
      THEMATIC_MINING_AGENT_CONFIG.systemPrompt ?? ""
    );

    this.confidenceFloor = 0.8;
  }

  protected buildPrompt(input: StandardAgentInput): string {
    const { input: taskInput, context } = input;
    const ctx = context as ThematicMiningContext;

    const originalText = ctx?.originalText ?? "";
    const genre = ctx?.genre ?? "غير محدد";
    const culturalContext = ctx?.culturalContext ?? "";
    const extractionDepth = ctx?.extractionDepth ?? "intermediate";
    const themeCategories = ctx?.themeCategories ?? ["universal", "social"];
    const minimumThemes = ctx?.minimumThemes ?? 3;
    const includeSymbols = ctx?.includeSymbols ?? true;
    const includeMotifs = ctx?.includeMotifs ?? true;

    let prompt = `مهمة استخراج الثيمات والموضوعات الأدبية\n\n`;

    if (originalText) {
      prompt += `النص المراد تحليله:\n${originalText.substring(0, 2500)}...\n\n`;
    }

    prompt += `معلومات السياق:\n`;
    prompt += `- النوع الأدبي: ${genre}\n`;
    if (culturalContext) {
      prompt += `- السياق الثقافي: ${culturalContext}\n`;
    }
    prompt += `- عمق الاستخراج: ${this.translateDepth(extractionDepth)}\n`;
    prompt += `- فئات الثيمات المطلوبة: ${themeCategories.map(this.translateCategory).join("، ")}\n`;
    prompt += `- الحد الأدنى للثيمات: ${minimumThemes}\n`;
    prompt += `- استخراج الرموز: ${includeSymbols ? "نعم" : "لا"}\n`;
    prompt += `- استخراج الموتيفات: ${includeMotifs ? "نعم" : "لا"}\n\n`;

    prompt += `المهمة المطلوبة:\n${taskInput}\n\n`;

    prompt += `التعليمات:

1. **نظرة عامة** (2-3 جمل): لخص الطابع الموضوعي العام للنص

2. **الثيمات الرئيسية**: استخرج وحلل الثيمات الأساسية (${minimumThemes} على الأقل)
   لكل ثيمة، قدم:
   - **اسم الثيمة**: عنوان واضح ومباشر
   - **الوصف**: شرح الثيمة وكيف تتجلى في النص
   - **الأدلة النصية**: أمثلة محددة من النص تدعم وجود هذه الثيمة
   - **التطور**: كيف تتطور هذه الثيمة عبر النص
   - **الأهمية**: لماذا هذه الثيمة مركزية للعمل

3. **الثيمات الثانوية**: ثيمات فرعية أو داعمة (إن وجدت)

${includeSymbols ? `4. **الرموز**: الرموز الأدبية المستخدمة ودلالاتها` : ""}

${includeMotifs ? `5. **الموتيفات المتكررة**: الأنماط والعناصر المتكررة وأهميتها` : ""}

6. **التكامل الموضوعي**: كيف تتشابك الثيمات المختلفة وتخدم الرسالة الكلية

7. **الرسالة الجوهرية**: ما الرسالة أو الفكرة الأساسية التي يريد النص إيصالها

اكتب بشكل نصي تحليلي مباشر مع أمثلة نصية محددة.
لا تستخدم JSON أو قوائم برمجية. نص تحليلي أدبي واضح.`;

    return prompt;
  }

  protected override async postProcess(
    output: StandardAgentOutput
  ): Promise<StandardAgentOutput> {
    const processedText = this.cleanupThematicText(output.text);

    const thematicDepth = await this.assessThematicDepth(processedText);
    const evidenceQuality = await this.assessEvidenceQuality(processedText);
    const insightfulness = await this.assessInsightfulness(processedText);
    const coherence = await this.assessCoherence(processedText);

    const qualityScore =
      thematicDepth * 0.3 +
      evidenceQuality * 0.25 +
      insightfulness * 0.25 +
      coherence * 0.2;

    const adjustedConfidence = output.confidence * 0.5 + qualityScore * 0.5;

    return {
      ...output,
      text: processedText,
      confidence: adjustedConfidence,
      notes: this.generateThematicNotes(
        output,
        thematicDepth,
        evidenceQuality,
        insightfulness,
        coherence
      ),
      metadata: {
        ...output.metadata,
        thematicQuality: {
          overall: qualityScore,
          thematicDepth,
          evidenceQuality,
          insightfulness,
          coherence,
        },
        themesIdentified: this.countThemes(processedText),
        symbolsIdentified: this.countSymbols(processedText),
        evidenceExamplesCount: this.countEvidenceExamples(processedText),
      },
    };
  }

  private cleanupThematicText(text: string): string {
    text = text.replace(/```json[\s\S]*?```/g, "");
    text = text.replace(/```[\s\S]*?```/g, "");
    text = text.replace(/\{[\s\S]*?\}/g, (match) => {
      if (match.includes('"') && match.includes(":")) return "";
      return match;
    });

    return text.replace(/\n{3,}/g, "\n\n").trim();
  }

  private async assessThematicDepth(text: string): Promise<number> {
    let score = 0.5;

    const thematicTerms = [
      "ثيمة",
      "موضوع",
      "فكرة",
      "رسالة",
      "مغزى",
      "دلالة",
      "معنى",
      "قيمة",
    ];
    // SECURITY FIX: Use safe RegExp utility to prevent injection
    const termCount = safeCountMultipleTerms(text, thematicTerms);
    score += Math.min(0.25, termCount * 0.015);

    const abstractTerms = [
      "الحرية",
      "العدالة",
      "الحب",
      "الموت",
      "الهوية",
      "الصراع",
      "التضحية",
      "الخيانة",
    ];
    // SECURITY FIX: Use safe RegExp utility to prevent injection
    const abstractCount = safeCountMultipleTerms(text, abstractTerms);
    score += Math.min(0.15, abstractCount * 0.03);

    if (text.length > 1500) score += 0.1;

    return Math.min(1, score);
  }

  private async assessEvidenceQuality(text: string): Promise<number> {
    let score = 0.6;

    const evidenceMarkers = [
      "مثل",
      "كما في",
      "نرى",
      "يظهر",
      "نجد",
      "على سبيل المثال",
      "في المشهد",
      "عندما",
    ];
    // SECURITY FIX: Use safe RegExp utility to prevent injection
    const evidenceCount = safeCountMultipleTerms(text, evidenceMarkers);
    score += Math.min(0.25, evidenceCount * 0.025);

    const hasQuotes = (text.match(/["«]/g) ?? []).length;
    score += Math.min(0.15, hasQuotes * 0.015);

    return Math.min(1, score);
  }

  private async assessInsightfulness(text: string): Promise<number> {
    let score = 0.5;

    const insightWords = [
      "يكشف",
      "يوضح",
      "يعكس",
      "يدل على",
      "يشير إلى",
      "نستنتج",
      "نلاحظ",
      "الأهمية",
      "التأثير",
    ];
    // SECURITY FIX: Use safe RegExp utility to prevent injection
    const insightCount = safeCountMultipleTerms(text, insightWords);
    score += Math.min(0.3, insightCount * 0.03);

    const hasAnalysis =
      text.includes("لماذا") ||
      text.includes("السبب") ||
      text.includes("نتيجة");
    if (hasAnalysis) score += 0.2;

    return Math.min(1, score);
  }

  private async assessCoherence(text: string): Promise<number> {
    let score = 0.7;

    const connectiveWords = [
      "بالإضافة",
      "كما",
      "أيضاً",
      "علاوة",
      "من جهة أخرى",
      "بالمقابل",
      "وهكذا",
    ];
    // SECURITY FIX: Use safe RegExp utility to prevent injection
    const connectiveCount = safeCountMultipleTerms(text, connectiveWords);
    score += Math.min(0.2, connectiveCount * 0.04);

    const hasStructure =
      text.includes("أولاً") || text.includes("ثانياً") || (/\d\./.exec(text));
    if (hasStructure) score += 0.1;

    return Math.min(1, score);
  }

  private countThemes(text: string): number {
    const themeMarkers = text.match(
      /ثيمة|الموضوع|الفكرة الرئيسية|الثيمة الأولى|الثيمة الثانية/gi
    );
    return themeMarkers ? Math.min(themeMarkers.length, 10) : 0;
  }

  private countSymbols(text: string): number {
    const symbolMarkers = text.match(/رمز|يرمز|رمزية|الدلالة الرمزية/gi);
    return symbolMarkers ? Math.min(symbolMarkers.length, 8) : 0;
  }

  private countEvidenceExamples(text: string): number {
    const exampleMarkers = text.match(/مثل|مثال|كما في|نرى|يظهر|["«]/g);
    return exampleMarkers ? Math.min(exampleMarkers.length, 20) : 0;
  }

  private generateThematicNotes(
    output: StandardAgentOutput,
    depth: number,
    evidence: number,
    insight: number,
    coherence: number
  ): string[] {
    const notes: string[] = [];

    const avg = (depth + evidence + insight + coherence) / 4;
    if (avg > 0.8) notes.push("تحليل موضوعي ممتاز");
    else if (avg > 0.65) notes.push("تحليل جيد");
    else notes.push("يحتاج عمق أكبر");

    if (depth > 0.8) notes.push("عمق موضوعي قوي");
    if (evidence > 0.8) notes.push("أدلة نصية غنية");
    if (insight > 0.75) notes.push("رؤى ثاقبة");
    if (coherence > 0.8) notes.push("تماسك ممتاز");

    if (depth < 0.5) notes.push("يحتاج استكشاف أعمق");
    if (evidence < 0.5) notes.push("يحتاج مزيد من الأدلة");
    if (insight < 0.6) notes.push("يحتاج تحليل أعمق");

    if (output.notes && Array.isArray(output.notes)) {
      notes.push(...output.notes);
    }

    return notes;
  }

  private translateDepth(depth: string): string {
    const depths: Record<string, string> = {
      surface: "سطحي - الثيمات الظاهرة",
      intermediate: "متوسط - تحليل متوازن",
      deep: "عميق - استكشاف شامل",
    };
    return depths[depth] ?? depth;
  }

  private translateCategory(category: string): string {
    const categories: Record<string, string> = {
      universal: "عالمية",
      social: "اجتماعية",
      personal: "شخصية",
      philosophical: "فلسفية",
      political: "سياسية",
      existential: "وجودية",
      moral: "أخلاقية",
    };
    return categories[category] ?? category;
  }

  protected override async getFallbackResponse(
    _input: StandardAgentInput
  ): Promise<string> {
    return `نظرة عامة:
النص يحمل طابعاً موضوعياً يستكشف قضايا إنسانية وفكرية متنوعة.

الثيمة الرئيسية الأولى:
[ثيمة عامة] - تظهر من خلال الأحداث والشخصيات وتتطور عبر النص.
الأدلة: [أمثلة من النص تحتاج تحديد أدق]

الثيمة الرئيسية الثانية:
[ثيمة ثانوية] - تدعم الثيمة الأولى وتضيف بعداً إضافياً.
الأدلة: [أمثلة تحتاج تفصيل]

الرسالة الجوهرية:
النص يسعى لإيصال رسالة حول [موضوع عام يحتاج تحديد].

ملاحظة: يُرجى تفعيل الخيارات المتقدمة وتوفير نص أطول للحصول على استخراج موضوعي أكثر عمقاً ودقة مع أمثلة نصية محددة.`;
  }
}

export const thematicMiningAgent = new ThematicMiningAgent();

