// Sentry configuration for production monitoring
export const initObservability = () => {
  const dsn = process.env["NEXT_PUBLIC_SENTRY_DSN"] ?? "";
  const environment = process.env.NODE_ENV;
  const isProduction = environment === "production";

  if (dsn) {
    log.info(
      "🔍 Initializing Sentry observability...",
      { environment },
      "Observability"
    );

    Sentry.init({
      dsn,
      environment,

      // Performance Monitoring
      tracesSampleRate: isProduction ? 0.1 : 1.0, // 10% in prod, 100% in dev
      replaysSessionSampleRate: isProduction ? 0.1 : 1.0,
      replaysOnErrorSampleRate: 1.0,

      // Error Filtering
      beforeSend(event, hint) {
        // Filter out non-critical errors in production
        if (isProduction) {
          const error = hint.originalException;

          // Skip common browser errors
          if (error instanceof Error) {
            if (error.message.includes("ResizeObserver loop limit exceeded")) {
              return null;
            }
            if (error.message.includes("Non-Error promise rejection")) {
              return null;
            }
            if (error.message.includes("Script error")) {
              return null;
            }
          }

          // Skip network errors for failed resources
          if (event.exception) {
            const errorMessage = event.exception.values?.[0]?.value ?? "";
            if (
              errorMessage.includes("Failed to fetch") ||
              errorMessage.includes("NetworkError") ||
              errorMessage.includes("Load failed")
            ) {
              return null;
            }
          }
        }

        // Add custom context
        event.tags = {
          ...event.tags,
          component: "drama-analyst",
          version: process.env["NEXT_PUBLIC_APP_VERSION"] ?? "1.0.0",
        };

        event.user = {
          ...event.user,
          id: getUserId(),
          session_id: getSessionId(),
        };

        return event;
      },

      // Integrations
      integrations: [
        Sentry.replayIntegration({
          maskAllText: false,
          blockAllMedia: false,
          networkDetailAllowUrls: [
            /^https:\/\/api\.gemini\.google\.com(?:\/|$)/,
            /^https:\/\/fonts\.googleapis\.com(?:\/|$)/,
