export const ragService = new RAGService();

/**
 * Sanitization Service for XSS Protection
 * Provides safe input/output sanitization for the frontend
 */

// =====================================================
// Sanitization Utilities
// =====================================================

/**
 * Sanitize HTML content to prevent XSS attacks
 */
import DOMPurify from "dompurify";

/**
 * Sanitize HTML content to prevent XSS attacks
 * SECURITY: Uses iterative approach to handle incomplete/nested tags
 * Fixed: Properly handles multi-character sanitization to prevent bypass attacks
 */
export const sanitizeHTML = (input: string): string => {
  if (!input || typeof input !== "string") {
    return "";
  }

  // Use DOMPurify if available (client-side)
  if (typeof window !== "undefined") {
    return DOMPurify.sanitize(input);
  }

  // Server-side fallback: safely escape angle brackets so no HTML is interpreted
  // Avoid regex-based tag stripping to prevent incomplete multi-character sanitization issues
  const result = input.replace(/</g, "&lt;").replace(/>/g, "&gt;");
  return result;
};

/**
 * Sanitize text content by escaping HTML entities
 */
export const sanitizeText = (input: string): string => {
  if (!input || typeof input !== "string") {
    return "";
  }

  return input
    .replace(/&/g, "&amp;")
    .replace(/</g, "&lt;")
    .replace(/>/g, "&gt;")
    .replace(/"/g, "&quot;")
    .replace(/'/g, "&#x27;")
    .replace(/\//g, "&#x2F;");
};

/**
 * Sanitize file names to prevent directory traversal
 */
export const sanitizeFileName = (fileName: string): string => {
  if (!fileName || typeof fileName !== "string") {
    return "unknown.txt";
  }

  // Remove dangerous characters and paths
  return fileName
    .replace(/[/\\:*?"<>|]/g, "_") // Replace dangerous chars with underscore
    .replace(/\.\./g, "_") // Prevent directory traversal
    .replace(/^\.+/, "") // Remove leading dots
    .trim()
    .substring(0, 255); // Limit length
};

/**
 * Sanitize URL to prevent open redirects and XSS
 * SECURITY: Validates URL scheme and rejects dangerous protocols
 */
export const sanitizeURL = (url: string): string => {
  if (!url || typeof url !== "string") {
    return "";
  }

  // First, check for dangerous schemes before parsing
  // This catches cases where URL parsing might fail but the scheme is dangerous
  const lowerUrl = url.toLowerCase().trim();
  const dangerousSchemes = [
    "javascript:",
    "data:",
    "vbscript:",
    "file:",
    "blob:",
  ];

  if (dangerousSchemes.some((scheme) => lowerUrl.startsWith(scheme))) {
    return "";
  }

  try {
    const urlObj = new URL(url);

    // Only allow http and https protocols
    if (!["http:", "https:"].includes(urlObj.protocol)) {
      return "";
    }

    return urlObj.toString();
  } catch {
    // If URL parsing fails, it might be a relative URL or malformed
    // Return empty string for safety
    return "";
  }
};

/**
 * Sanitize object properties recursively
 */
export const sanitizeObject = <T>(obj: T): T => {
  if (obj === null || obj === undefined) {
    return obj;
  }

  if (typeof obj === "string") {
    return sanitizeText(obj) as T;
  }

  if (Array.isArray(obj)) {
    return obj.map(sanitizeObject) as T;
  }

  if (typeof obj === "object") {
    const sanitized = {} as T;
    for (const [key, value] of Object.entries(obj)) {
      const sanitizedKey = sanitizeText(key);
      (sanitized as any)[sanitizedKey] = sanitizeObject(value);
    }
    return sanitized;
  }

  return obj;
};

/**
 * Validate and sanitize user input for AI requests
 */
export const sanitizeAIRequest = (request: any) => {
  if (!request || typeof request !== "object") {
    throw new Error("Invalid request format");
  }

  const sanitized = { ...request };

  // Sanitize agent name
  if (sanitized.agent && typeof sanitized.agent === "string") {
    sanitized.agent = sanitizeText(sanitized.agent);
  }

  // Sanitize parameters
  if (sanitized.parameters && typeof sanitized.parameters === "object") {
    sanitized.parameters = sanitizeObject(sanitized.parameters);
  }

  // Sanitize files
  if (sanitized.files && Array.isArray(sanitized.files)) {
    sanitized.files = sanitized.files.map((file: any) => {
      if (file && typeof file === "object") {
        return {
          ...file,
          name: sanitizeFileName(file.name ?? ""),
          content:
            typeof file.content === "string"
              ? sanitizeText(file.content)
              : file.content,
        };
      }
      return file;
    });
  }

  return sanitized;
};

/**
 * Sanitize AI response content
 */
export const sanitizeAIResponse = (response: any) => {
  if (!response || typeof response !== "object") {
    return response;
  }

  const sanitized = { ...response };

  // Sanitize raw content
  if (sanitized.raw && typeof sanitized.raw === "string") {
    sanitized.raw = sanitizeHTML(sanitized.raw);
  }

  // Sanitize parsed content if it exists
  if (sanitized.parsed && typeof sanitized.parsed === "object") {
    sanitized.parsed = sanitizeObject(sanitized.parsed);
  }

  return sanitized;
};

// =====================================================
// React-specific utilities
// =====================================================

/**
 * Safe HTML renderer for React components
 */
export const createSafeHTML = (html: string): { __html: string } => {
  return {
    __html: sanitizeHTML(html),
  };
};

/**
 * Validation utilities
 */
export const isValidTextInput = (input: any): boolean => {
  return typeof input === "string" && input.length > 0 && input.length < 10000;
};

export const isValidFileName = (fileName: any): boolean => {
  if (typeof fileName !== "string") return false;
  const sanitized = sanitizeFileName(fileName);
  return sanitized.length > 0 && sanitized !== "unknown.txt";
};

export const isValidFileSize = (size: any): boolean => {
  return typeof size === "number" && size > 0 && size <= 20 * 1024 * 1024; // 20MB
};

// =====================================================
// Export all sanitization functions
// =====================================================

export const sanitization = {
  html: sanitizeHTML,
  text: sanitizeText,
  fileName: sanitizeFileName,
  url: sanitizeURL,
  object: sanitizeObject,
  aiRequest: sanitizeAIRequest,
  aiResponse: sanitizeAIResponse,
  createSafeHTML,
  validation: {
    isValidTextInput,
    isValidFileName,
    isValidFileSize,
  },
};

/**
 * خدمة قياس عدم اليقين
 * Uncertainty Quantification Service
 *
 * يقيس مستوى الثقة في مخرجات الوكلاء ويحدد متى تحتاج المراجعة البشرية
 */

import { UncertaintyMetrics } from "../core/types";

import { log } from "./loggerService";
import { platformGenAIService } from "./platformGenAIService";

export class UncertaintyService {
  /**
   * قياس عدم اليقين باستخدام Monte Carlo Dropout
   * Measure uncertainty using Monte Carlo Dropout
   *
   * يقوم بتشغيل النموذج عدة مرات ويقيس الاتساق بين المخرجات
   */
  async measureUncertaintyMC(
    prompt: string,
    iterations = 5
  ): Promise<UncertaintyMetrics> {
    const outputs: string[] = [];

    // Generate multiple outputs
    log.info(
      "Running uncertainty iterations",
      { iterations },
      "UncertaintyService"
    );
    for (let i = 0; i < iterations; i++) {
      const output = await platformGenAIService.generateText(
        prompt + `\n\n[تكرار ${i + 1}/${iterations}]`
      );
      outputs.push(output);
    }

    // Calculate consistency/variance
    const consistency = this.calculateConsistency(outputs);
    const confidence = consistency;

    // Identify uncertain aspects
    const uncertainAspects = this.identifyUncertainAspects(outputs);

    // Sanitized confidence logging for security
    if (confidence > 0.5) {
      log.info(
        "Uncertainty analysis completed",
        { confidence },
        "UncertaintyService"
      );
    } else {
      log.warn(
        "Uncertainty analysis completed with low confidence",
        { confidence },
        "UncertaintyService"
      );
    }

    return {
      confidence,
      needsReview: confidence < 0.7,
      uncertainAspects,
      method: "monte_carlo",
    };
  }

  /**
   * قياس عدم اليقين باستخدام Ensemble
   * Measure uncertainty using Ensemble methods
   */
  async measureUncertaintyEnsemble(
    prompt: string,
    models: string[] = ["gemini-1.5-pro", "gemini-1.5-pro"]
  ): Promise<UncertaintyMetrics> {
    const outputs: string[] = [];

    // Generate outputs from multiple models/configurations
    // Note: Currently using same model multiple times for ensemble
    for (const _model of models) {
      const output = await platformGenAIService.generateText(prompt);
      outputs.push(output);
    }

    const consistency = this.calculateConsistency(outputs);
    const uncertainAspects = this.identifyUncertainAspects(outputs);

    return {
      confidence: consistency,
      needsReview: consistency < 0.7,
      uncertainAspects,
      method: "ensemble",
    };
  }

  /**
   * حساب الاتساق بين المخرجات
   * Calculate consistency between outputs
   */
  private calculateConsistency(outputs: string[]): number {
    if (outputs.length < 2) return 1.0;

    // Calculate pairwise similarities
    let totalSimilarity = 0;
    let pairs = 0;

    for (let i = 0; i < outputs.length - 1; i++) {
      for (let j = i + 1; j < outputs.length; j++) {
        const output1 = outputs[i];
        const output2 = outputs[j];
        if (output1 && output2) {
          totalSimilarity += this.calculateSimilarity(output1, output2);
          pairs++;
        }
      }
    }

    return pairs > 0 ? totalSimilarity / pairs : 0;
  }

  /**
   * حساب التشابه بين نصين باستخدام Jaccard Similarity
   * Calculate similarity between two texts using Jaccard Similarity
   */
  private calculateSimilarity(text1: string, text2: string): number {
    const words1 = new Set(text1.toLowerCase().split(/\s+/));
    const words2 = new Set(text2.toLowerCase().split(/\s+/));

    const intersection = new Set([...words1].filter((x) => words2.has(x)));
    const union = new Set([...words1, ...words2]);

    return union.size > 0 ? intersection.size / union.size : 0;
  }

  /**
   * تحديد الجوانب غير المؤكدة
   * Identify uncertain aspects
   */
  private identifyUncertainAspects(outputs: string[]): string[] {
    // Find parts where outputs diverge
    const uncertainAspects: string[] = [];

    const allWords = outputs.flatMap((o) => o.split(/\s+/));
    const wordCounts = new Map<string, number>();

    allWords.forEach((word) => {
      wordCounts.set(word, (wordCounts.get(word) ?? 0) + 1);
    });

    // Words that appear in some but not all outputs might indicate uncertainty
    wordCounts.forEach((count, word) => {
      if (count > 1 && count < outputs.length && word.length > 5) {
        uncertainAspects.push(word);
      }
    });

    return uncertainAspects.slice(0, 5); // Top 5 uncertain aspects
  }

  /**
   * تقييم شامل للثقة
   * Comprehensive confidence assessment
   */
  async assessConfidence(output: string, context: any): Promise<number> {
    const assessmentPrompt = `
قم بتقييم مستوى الثقة في المخرج التالي على مقياس من 0 إلى 1.

المخرج:
"""
${output.substring(0, 2000)}
"""

السياق:
"""
${JSON.stringify(context, null, 2).substring(0, 1000)}
"""

معايير التقييم:
1. الاتساق المنطقي
2. الاستناد إلى المصادر
3. الوضوح والدقة
4. عدم التناقضات
5. الكمال والشمولية

أجب برقم فقط بين 0 و 1 (مثال: 0.85)
`;

    try {
      const result = await platformGenAIService.generateText(assessmentPrompt);
      const confidence = parseFloat(result.trim());
      return isNaN(confidence) ? 0.5 : Math.min(Math.max(confidence, 0), 1);
    } catch (error) {
      log.error("Error assessing confidence", error, "UncertaintyService");
      return 0.5; // Default to medium confidence on error
    }
  }
}

