// Uptime Monitoring Service for Drama Analyst
// Monitors application uptime, health, and performance metrics

import { log } from "./loggerService";
// No-op replacement for missing GA function
const sendGAEvent = (..._args: any[]) => {};
import { addBreadcrumb, reportError } from "./observability";

interface UptimeConfig {
  enableGA4: boolean;
  enableSentry: boolean;
  enableConsoleLog: boolean;
  healthCheckInterval: number; // in milliseconds
  performanceCheckInterval: number; // in milliseconds
  debug: boolean;
}

interface HealthMetrics {
  uptime: number; // in seconds
  memoryUsage: number; // in MB
  performanceScore: number; // 0-100
  errorCount: number;
  requestCount: number;
  lastHealthCheck: Date;
  status: "healthy" | "degraded" | "unhealthy";
}

interface PerformanceMetrics {
  loadTime: number; // in milliseconds
  renderTime: number; // in milliseconds
  interactionTime: number; // in milliseconds
  memoryLeaks: boolean;
  slowOperations: string[];
}

class UptimeMonitoringService {
  private config: UptimeConfig;
  private startTime: number;
  private healthMetrics: HealthMetrics;
  private performanceMetrics: PerformanceMetrics;
  private healthCheckInterval: NodeJS.Timeout | null = null;
  private performanceCheckInterval: NodeJS.Timeout | null = null;
  private errorCount = 0;
  private requestCount = 0;

  constructor(config: Partial<UptimeConfig> = {}) {
    this.config = {
      enableGA4: true,
      enableSentry: true,
      enableConsoleLog: process.env.NODE_ENV === "development",
      healthCheckInterval: 30000, // 30 seconds
      performanceCheckInterval: 60000, // 1 minute
      debug: process.env.NODE_ENV === "development",
      ...config,
    };

    this.startTime = Date.now();
    this.healthMetrics = this.initializeHealthMetrics();
    this.performanceMetrics = this.initializePerformanceMetrics();

    this.init();
  }

  private initializeHealthMetrics(): HealthMetrics {
    return {
      uptime: 0,
      memoryUsage: 0,
      performanceScore: 100,
      errorCount: 0,
      requestCount: 0,
      lastHealthCheck: new Date(),
      status: "healthy",
    };
  }

  private initializePerformanceMetrics(): PerformanceMetrics {
    return {
      loadTime: 0,
      renderTime: 0,
      interactionTime: 0,
      memoryLeaks: false,
      slowOperations: [],
    };
  }

  private init(): void {
    if (typeof window === "undefined") {
      log.warn(
        "⚠️ Uptime monitoring: window not available",
        null,
        "UptimeMonitoringService"
      );
      return;
    }

    log.info(
      "📊 Initializing Uptime monitoring...",
      {
        enableGA4: this.config.enableGA4,
        enableSentry: this.config.enableSentry,
        healthCheckInterval: this.config.healthCheckInterval,
        performanceCheckInterval: this.config.performanceCheckInterval,
      },
      "UptimeMonitoringService"
    );

    // Start health monitoring
    this.startHealthMonitoring();

    // Start performance monitoring
    this.startPerformanceMonitoring();

    // Track uptime monitoring initialization
    this.trackEvent("uptime_monitoring_initialized", {
      config: this.config,
      timestamp: Date.now(),
    });

    // Set up error tracking
    this.setupErrorTracking();

    // Set up performance tracking
    this.setupPerformanceTracking();
  }

  private startHealthMonitoring(): void {
    if (this.healthCheckInterval) {
      clearInterval(this.healthCheckInterval);
    }

    this.healthCheckInterval = setInterval(() => {
      this.performHealthCheck();
    }, this.config.healthCheckInterval);

    // Perform initial health check
    this.performHealthCheck();
  }

  private startPerformanceMonitoring(): void {
    if (this.performanceCheckInterval) {
      clearInterval(this.performanceCheckInterval);
    }

    this.performanceCheckInterval = setInterval(() => {
      this.performPerformanceCheck();
    }, this.config.performanceCheckInterval);

    // Perform initial performance check
    this.performPerformanceCheck();
  }

  private performHealthCheck(): void {
    try {
      const currentTime = Date.now();
      const uptime = (currentTime - this.startTime) / 1000; // in seconds

      // Get memory usage
      const memoryUsage = this.getMemoryUsage();

      // Calculate performance score
      const performanceScore = this.calculatePerformanceScore();

      // Update health metrics
      this.healthMetrics = {
        uptime,
        memoryUsage,
        performanceScore,
        errorCount: this.errorCount,
        requestCount: this.requestCount,
        lastHealthCheck: new Date(),
        status: this.determineHealthStatus(performanceScore, memoryUsage),
      };

      // Log health status
      if (this.config.enableConsoleLog) {
        log.info(
          "🏥 Health Check",
          {
            status: this.healthMetrics.status,
            uptime_seconds: Math.round(uptime),
            memory_mb: Math.round(memoryUsage),
            performance_score: performanceScore,
            error_count: this.errorCount,
            request_count: this.requestCount,
          },
          "UptimeMonitoringService"
        );
      }

      // Track health metrics
      this.trackEvent("health_check", {
        status: this.healthMetrics.status,
        uptime: Math.round(uptime),
        memory_usage: Math.round(memoryUsage),
        performance_score: performanceScore,
        error_count: this.errorCount,
        request_count: this.requestCount,
      });

      // Report to Sentry if unhealthy
      if (this.healthMetrics.status !== "healthy") {
        this.reportHealthIssue();
      }
    } catch {
      log.error("❌ Health check failed", null, "UptimeMonitoringService");
    }
  }

  private performPerformanceCheck(): void {
    try {
      // Check for memory leaks
      const memoryLeaks = this.checkMemoryLeaks();

      // Check for slow operations
      const slowOperations = this.checkSlowOperations();

      // Update performance metrics
      this.performanceMetrics = {
        ...this.performanceMetrics,
        memoryLeaks,
        slowOperations,
      };

      // Log performance status
      if (this.config.enableConsoleLog) {
        log.info(
          "⚡ Performance Check",
          {
            memory_leaks: memoryLeaks,
            slow_operations_count: slowOperations.length,
            // Remove detailed operation information for security
          },
          "UptimeMonitoringService"
        );
      }

      // Track performance metrics
      this.trackEvent("performance_check", {
        memory_leaks: memoryLeaks,
        slow_operations_count: slowOperations.length,
        slow_operations: slowOperations,
      });

      // Report performance issues
      if (memoryLeaks || slowOperations.length > 0) {
        this.reportPerformanceIssue();
      }
    } catch {
      log.error("❌ Performance check failed", null, "UptimeMonitoringService");
    }
  }

  private getMemoryUsage(): number {
    if ("memory" in performance) {
      const memory = (performance as any).memory;
      return memory.usedJSHeapSize / 1024 / 1024; // Convert to MB
    }
    return 0;
  }

  private calculatePerformanceScore(): number {
    let score = 100;

    // Penalize based on memory usage
    const memoryUsage = this.getMemoryUsage();
    if (memoryUsage > 100)
      score -= 20; // Over 100MB
    else if (memoryUsage > 50) score -= 10; // Over 50MB

    // Penalize based on error count
    if (this.errorCount > 10)
      score -= 30; // Over 10 errors
    else if (this.errorCount > 5)
      score -= 15; // Over 5 errors
    else if (this.errorCount > 0) score -= 5; // Any errors

    // Penalize based on performance metrics
    if (this.performanceMetrics.memoryLeaks) score -= 25;
    if (this.performanceMetrics.slowOperations.length > 0) score -= 15;

    return Math.max(0, score);
  }

  private determineHealthStatus(
    performanceScore: number,
    memoryUsage: number
  ): "healthy" | "degraded" | "unhealthy" {
    if (performanceScore < 50 || memoryUsage > 200 || this.errorCount > 20) {
      return "unhealthy";
    } else if (
      performanceScore < 75 ||
      memoryUsage > 100 ||
      this.errorCount > 10
    ) {
      return "degraded";
    } else {
      return "healthy";
    }
  }

  private checkMemoryLeaks(): boolean {
    // Simple memory leak detection
    const memoryUsage = this.getMemoryUsage();
    const uptime = (Date.now() - this.startTime) / 1000 / 60; // in minutes

    // If memory usage is high and uptime is long, possible memory leak
    return memoryUsage > 50 && uptime > 10;
  }

  private checkSlowOperations(): string[] {
    const slowOperations: string[] = [];

    // Check for long tasks
    if ("PerformanceObserver" in window) {
      const observer = new PerformanceObserver((list) => {
        list.getEntries().forEach((entry) => {
          if (entry.duration > 50) {
            // Tasks longer than 50ms
            slowOperations.push(`Long task: ${entry.duration.toFixed(2)}ms`);
          }
        });
      });

      try {
        observer.observe({ entryTypes: ["longtask"] });
        // Clean up observer after a short time
        setTimeout(() => observer.disconnect(), 1000);
      } catch {
        // PerformanceObserver might not be supported
      }
    }

    return slowOperations;
  }

  private setupErrorTracking(): void {
    // Track unhandled errors
    window.addEventListener("error", (event) => {
      this.errorCount++;
      this.trackEvent("unhandled_error", {
        message: event.message,
        filename: event.filename,
        lineno: event.lineno,
        colno: event.colno,
        error: event.error?.toString(),
      });
    });

    // Track unhandled promise rejections
    window.addEventListener("unhandledrejection", (event) => {
      this.errorCount++;
      this.trackEvent("unhandled_rejection", {
        reason: event.reason?.toString(),
        promise: event.promise?.toString(),
      });
    });
  }

  private setupPerformanceTracking(): void {
    // Track page load performance
    window.addEventListener("load", () => {
      const loadTime = performance.now();
      this.performanceMetrics.loadTime = loadTime;

      this.trackEvent("page_load", {
        load_time: Math.round(loadTime),
        timestamp: Date.now(),
      });
    });

    // Track user interactions
    let interactionStartTime = 0;

    ["click", "keydown", "scroll"].forEach((eventType) => {
      document.addEventListener(eventType, () => {
        if (interactionStartTime === 0) {
          interactionStartTime = performance.now();
        }

        const interactionTime = performance.now() - interactionStartTime;
        this.performanceMetrics.interactionTime = interactionTime;

        if (interactionTime > 100) {
          // Slow interaction
          this.trackEvent("slow_interaction", {
            event_type: eventType,
            interaction_time: Math.round(interactionTime),
            timestamp: Date.now(),
          });
        }

        interactionStartTime = 0;
      });
    });
  }

  private trackEvent(eventName: string, eventData: Record<string, any>): void {
    try {
      // Track in GA4
      if (this.config.enableGA4) {
        sendGAEvent(eventName, {
          ...eventData,
          uptime: Math.round((Date.now() - this.startTime) / 1000),
          memory_usage: Math.round(this.getMemoryUsage()),
          performance_score: this.calculatePerformanceScore(),
        });
      }

      // Track in Sentry
      if (this.config.enableSentry) {
        addBreadcrumb(eventName, "uptime-monitoring", eventData);
      }

      // Log to console
      if (this.config.enableConsoleLog) {
        log.debug(
          `📊 Uptime event: ${eventName}`,
          eventData,
          "UptimeMonitoringService"
        );
      }
    } catch {
      log.error(
        "❌ Failed to track uptime event",
        null,
        "UptimeMonitoringService"
      );
    }
  }

  private reportHealthIssue(): void {
    if (this.config.enableSentry) {
      reportError(
        new Error(`Health issue detected: ${this.healthMetrics.status}`),
        {
          health_status: this.healthMetrics.status,
          performance_score: this.healthMetrics.performanceScore,
          uptime_seconds: Math.round((Date.now() - this.startTime) / 1000),
          // Removed detailed metrics for security
        }
      );
    }
  }

  private reportPerformanceIssue(): void {
    if (this.config.enableSentry) {
      reportError(new Error("Performance issue detected"), {
        memory_leaks: this.performanceMetrics.memoryLeaks,
        slow_operations_count: this.performanceMetrics.slowOperations.length,
        uptime_seconds: Math.round((Date.now() - this.startTime) / 1000),
        // Removed detailed performance metrics for security
      });
    }
  }

  // Public methods
  public getHealthMetrics(): HealthMetrics {
    return { ...this.healthMetrics };
  }

  public getPerformanceMetrics(): PerformanceMetrics {
    return { ...this.performanceMetrics };
  }

  public getUptime(): number {
    return Math.round((Date.now() - this.startTime) / 1000);
  }

  public incrementRequestCount(): void {
    this.requestCount++;
  }

  public incrementErrorCount(): void {
    this.errorCount++;
  }

  public getStatus(): "healthy" | "degraded" | "unhealthy" {
    return this.healthMetrics.status;
  }

  public destroy(): void {
    // Clear intervals
    if (this.healthCheckInterval) {
      clearInterval(this.healthCheckInterval);
      this.healthCheckInterval = null;
    }

    if (this.performanceCheckInterval) {
      clearInterval(this.performanceCheckInterval);
      this.performanceCheckInterval = null;
    }

    log.info(
      "🔒 Uptime monitoring service destroyed",
      null,
      "UptimeMonitoringService"
    );
  }
}

// Create singleton instance
let uptimeMonitoringService: UptimeMonitoringService | null = null;

export const initUptimeMonitoring = (config?: Partial<UptimeConfig>) => {
  if (uptimeMonitoringService) {
    log.warn(
      "⚠️ Uptime monitoring service already initialized",
      null,
      "UptimeMonitoringService"
    );
    return uptimeMonitoringService;
  }

  uptimeMonitoringService = new UptimeMonitoringService(config);
  return uptimeMonitoringService;
};

export const getUptimeMonitoringService = () => uptimeMonitoringService;

export const destroyUptimeMonitoring = () => {
  if (uptimeMonitoringService) {
    uptimeMonitoringService.destroy();
    uptimeMonitoringService = null;
  }
};

// Export types
export type { UptimeConfig, HealthMetrics, PerformanceMetrics };

// Web Vitals Service for Drama Analyst
// Monitors Core Web Vitals and performance metrics

import { onCLS, onINP, onFCP, onLCP, onTTFB, Metric } from "web-vitals";

import { log } from "./loggerService";
import { reportError, addBreadcrumb } from "./observability";
// No-op replacement for missing GA function
const sendGAEvent = (..._args: any[]) => {};

interface WebVitalsConfig {
  enableGA4: boolean;
  enableSentry: boolean;
  enableConsoleLog: boolean;
  customEndpoint?: string;
  debug: boolean;
}

interface CustomMetric extends Metric {
  customData?: Record<string, any>;
}

class WebVitalsService {
  private config: WebVitalsConfig;
  private metrics = new Map<string, CustomMetric>();
  private observers = new Set<PerformanceObserver>();

  constructor(config: Partial<WebVitalsConfig> = {}) {
    this.config = {
      enableGA4: true,
      enableSentry: true,
      enableConsoleLog: process.env.NODE_ENV === "development",
      debug: process.env.NODE_ENV === "development",
      ...config,
    };

    this.init();
  }

  private init(): void {
    if (typeof window === "undefined") {
      log.warn(
        "⚠️ Web Vitals service: window not available",
        null,
        "WebVitalsService"
      );
      return;
    }

    log.info(
      "📊 Initializing Web Vitals monitoring...",
      null,
      "WebVitalsService"
    );

    // Initialize Core Web Vitals
    this.initCoreWebVitals();

    // Initialize custom performance metrics
    this.initCustomMetrics();

    // Initialize navigation timing
    this.initNavigationTiming();

    // Initialize resource timing
    this.initResourceTiming();

    // Initialize long task monitoring
    this.initLongTaskMonitoring();

    log.info("✅ Web Vitals monitoring initialized", null, "WebVitalsService");
  }

  private initCoreWebVitals(): void {
    // Cumulative Layout Shift (CLS)
    onCLS((metric) => {
      this.handleMetric("CLS", metric);
    });

    // Interaction to Next Paint (INP) - replaces FID
    onINP((metric) => {
      this.handleMetric("INP", metric);
    });

    // First Contentful Paint (FCP)
    onFCP((metric) => {
      this.handleMetric("FCP", metric);
    });

    // Largest Contentful Paint (LCP)
    onLCP((metric) => {
      this.handleMetric("LCP", metric);
    });

    // Time to First Byte (TTFB)
    onTTFB((metric) => {
      this.handleMetric("TTFB", metric);
    });
  }

  private initCustomMetrics(): void {
    // Custom metrics for Drama Analyst specific functionality
    this.measureAppLoadTime();
    this.measureFileProcessingTime();
    this.measureAPICallTime();
    this.measureComponentRenderTime();
  }

  private initNavigationTiming(): void {
    if (!("PerformanceNavigationTiming" in window)) {
      return;
    }

    const observer = new PerformanceObserver((list) => {
      list.getEntries().forEach((entry) => {
        if (entry.entryType === "navigation") {
          const navEntry = entry as PerformanceNavigationTiming;

          const customMetric: CustomMetric = {
            name: "TTFB",
            value: navEntry.loadEventEnd - navEntry.fetchStart,
            delta: navEntry.loadEventEnd - navEntry.fetchStart,
            id: `nav-${Date.now()}`,
            navigationType: navEntry.type as any,
            rating: "good",
            entries: [],
            customData: {
              domContentLoaded:
                navEntry.domContentLoadedEventEnd -
                navEntry.domContentLoadedEventStart,
              loadComplete: navEntry.loadEventEnd - navEntry.loadEventStart,
              dnsLookup: navEntry.domainLookupEnd - navEntry.domainLookupStart,
              tcpConnect: navEntry.connectEnd - navEntry.connectStart,
              request: navEntry.responseStart - navEntry.requestStart,
              response: navEntry.responseEnd - navEntry.responseStart,
              domProcessing:
                navEntry.domComplete - ((navEntry as any).domLoading ?? 0),
            },
          };

          this.handleMetric("TTFB", customMetric);
        }
      });
    });

    observer.observe({ entryTypes: ["navigation"] });
    this.observers.add(observer);
  }

  private initResourceTiming(): void {
    const observer = new PerformanceObserver((list) => {
      list.getEntries().forEach((entry) => {
        if (entry.entryType === "resource") {
          const resourceEntry = entry as PerformanceResourceTiming;

          // Track slow resources
          if (resourceEntry.duration > 1000) {
            // Resources taking longer than 1 second
            const customMetric: CustomMetric = {
              name: "SlowResource" as any,
              value: resourceEntry.duration,
              delta: resourceEntry.duration,
              id: `resource-${Date.now()}`,
              navigationType: "navigate",
              rating: "good",
              entries: [],
              customData: {
                url: resourceEntry.name,
                size: resourceEntry.transferSize,
                type: this.getResourceType(resourceEntry.name),
                initiatorType: resourceEntry.initiatorType,
              },
            };

            this.handleMetric("SlowResource", customMetric);
          }
        }
      });
    });

    observer.observe({ entryTypes: ["resource"] });
    this.observers.add(observer);
  }

  private initLongTaskMonitoring(): void {
    if (!("PerformanceObserver" in window)) {
      return;
    }

    const observer = new PerformanceObserver((list) => {
      list.getEntries().forEach((entry) => {
        if (entry.entryType === "longtask") {
          const customMetric: CustomMetric = {
            name: "LongTask" as any,
            value: entry.duration,
            delta: entry.duration,
            id: `longtask-${Date.now()}`,
            navigationType: "navigate",
            rating: "good",
            entries: [],
            customData: {
              startTime: entry.startTime,
              name: entry.name,
            },
          };

          this.handleMetric("LongTask", customMetric);
        }
      });
    });

    try {
      observer.observe({ entryTypes: ["longtask"] });
      this.observers.add(observer);
    } catch (error) {
      log.warn(
        "⚠️ Long task monitoring not supported",
        error,
        "WebVitalsService"
      );
    }
  }

  private measureAppLoadTime(): void {
    if (document.readyState === "loading") {
      document.addEventListener("DOMContentLoaded", () => {
        this.measureCustomMetric("AppLoadTime", performance.now());
      });
    } else {
      this.measureCustomMetric("AppLoadTime", performance.now());
    }
  }

  private measureFileProcessingTime(): void {
    // This will be called when file processing starts/ends
    const originalMeasure = performance.measure.bind(performance);

    // Override performance.measure to track file processing
    performance.measure = (
      name: string,
      startMark?: string,
      endMark?: string
    ) => {
      const result = originalMeasure(name, startMark, endMark);

      if (name.includes("file-processing")) {
        const customMetric: CustomMetric = {
          name: "FileProcessingTime" as any,
          value: result.duration,
          delta: result.duration,
          id: `file-processing-${Date.now()}`,
          navigationType: "navigate",
          rating: "good",
          entries: [],
          customData: {
            fileName: name.split("-").pop(),
            startTime: result.startTime,
          },
        };

        this.handleMetric("FileProcessingTime", customMetric);
      }

      return result;
    };
  }

  private measureAPICallTime(): void {
    // This will be called when API calls are made
    const originalFetch = window.fetch.bind(window);

    window.fetch = async (...args) => {
      const startTime = performance.now();
      const url = args[0]?.toString() || "unknown";

      try {
        const response = await originalFetch(...args);
        const endTime = performance.now();

        const customMetric: CustomMetric = {
          name: "APICallTime" as any,
          value: endTime - startTime,
          delta: endTime - startTime,
          id: `api-${Date.now()}`,
          navigationType: "navigate",
          rating: "good",
          entries: [],
          customData: {
            url,
            status: response.status,
            method: args[1]?.method ?? "GET",
          },
        };

        this.handleMetric("APICallTime", customMetric);

        return response;
      } catch (error) {
        const endTime = performance.now();

        const customMetric: CustomMetric = {
          name: "APICallError" as any,
          value: endTime - startTime,
          delta: endTime - startTime,
          id: `api-error-${Date.now()}`,
          navigationType: "navigate",
          rating: "good",
          entries: [],
          customData: {
            url,
            error: error instanceof Error ? error.message : "Unknown error",
          },
        };

        this.handleMetric("APICallError", customMetric);

        throw error;
      }
    };
  }

  private measureComponentRenderTime(): void {
    // Track React component render times using performance marks and measures
    if (!("PerformanceObserver" in window) || !window.performance?.mark) {
      log.warn(
        "⚠️ Performance API not available for component render tracking",
        null,
        "WebVitalsService"
      );
      return;
    }

    try {
      // Observe performance measures for component renders
      const observer = new PerformanceObserver((list) => {
        list.getEntries().forEach((entry) => {
          if (entry.entryType === "measure") {
            // Track measures that match component render patterns
            // Common patterns: "Component.render", "⚛ ComponentName", etc.
            const isComponentMeasure =
              entry.name.includes("Component") ||
              entry.name.includes("⚛") ||
              entry.name.includes("render");

            if (isComponentMeasure) {
              const customMetric: CustomMetric = {
                name: "ComponentRender" as any,
                value: entry.duration,
                delta: entry.duration,
                id: `component-${Date.now()}`,
                navigationType: "navigate",
                rating: entry.duration < 16 ? ("good") : ("poor"), // 16ms = 60fps
                entries: [],
                customData: {
                  componentName: entry.name,
                  duration: entry.duration,
                  startTime: entry.startTime,
                  detail: (entry as any).detail,
                },
              };

              // Only track slow renders (> 16ms for 60fps)
              if (entry.duration > 16) {
                this.handleMetric("ComponentRender", customMetric);
              }
            }
          }
        });
      });

      observer.observe({ entryTypes: ["measure"] });
      this.observers.add(observer);

      log.info(
        "✅ Component render time tracking initialized",
        null,
        "WebVitalsService"
      );
    } catch (error) {
      log.error(
        "❌ Failed to initialize component render tracking",
        error,
        "WebVitalsService"
      );
    }
  }

  /**
   * Public method to mark component render start
   * Usage: webVitalsService.markComponentRenderStart('MyComponent')
   */
  public markComponentRenderStart(componentName: string): void {
    if (typeof window !== "undefined" && window.performance) {
      try {
        performance.mark(`${componentName}-render-start`);
      } catch {
        // Silently fail if marking fails
      }
    }
  }

  /**
   * Public method to mark component render end and measure duration
   * Usage: webVitalsService.markComponentRenderEnd('MyComponent')
   */
  public markComponentRenderEnd(componentName: string): void {
    if (typeof window !== "undefined" && window.performance) {
      try {
        const endMark = `${componentName}-render-end`;
        const startMark = `${componentName}-render-start`;

        performance.mark(endMark);

        // Create a measure between start and end marks
        try {
          performance.measure(`⚛ ${componentName} render`, startMark, endMark);

          // Clean up marks to avoid memory leaks
          performance.clearMarks(startMark);
          performance.clearMarks(endMark);
        } catch {
          // Start mark might not exist, which is fine
        }
      } catch {
        // Silently fail if marking fails
      }
    }
  }

  /**
   * Public method to measure a component render directly
   * Usage: webVitalsService.measureComponentRender('MyComponent', () => { ... })
   */
  public async measureComponentRender<T>(
    componentName: string,
    renderFn: () => T | Promise<T>
  ): Promise<T> {
    this.markComponentRenderStart(componentName);
    try {
      const result = await renderFn();
      return result;
    } finally {
      this.markComponentRenderEnd(componentName);
    }
  }

  private handleMetric(name: string, metric: CustomMetric): void {
    // Store metric
    this.metrics.set(metric.id, metric);

    // Log to console if enabled
    if (this.config.enableConsoleLog) {
      log.info(
        `📊 ${name}: ${metric.value.toFixed(2)}${this.getMetricUnit(name)}`,
        null,
        "WebVitalsService"
      );
    }

    // Send to Google Analytics 4
    if (this.config.enableGA4) {
      this.sendToGA4(name, metric);
    }

    // Send to Sentry
    if (this.config.enableSentry) {
      this.sendToSentry(name, metric);
    }

    // Send to custom endpoint
    if (this.config.customEndpoint) {
      this.sendToCustomEndpoint(name, metric);
    }

    // Add breadcrumb
    addBreadcrumb(`Web Vital: ${name}`, "performance", {
      value: metric.value,
      ...metric.customData,
    });

    // Check for performance issues
    this.checkPerformanceThresholds(name, metric);
  }

  private sendToGA4(name: string, metric: CustomMetric): void {
    try {
      // Send detailed Web Vitals data to GA4 using our analytics service
      sendGAEvent("web_vitals", {
        metric_name: metric.name,
        metric_value: Math.round(metric.value),
        metric_delta: Math.round(metric.delta),
        metric_rating: metric.rating,
        metric_id: metric.id,
        navigation_type: metric.navigationType,
        // Add performance thresholds for analysis
        is_good: metric.rating === "good",
        is_needs_improvement: metric.rating === "needs-improvement",
        is_poor: metric.rating === "poor",
        // Add timing context
        timestamp: Date.now(),
        user_agent: navigator.userAgent,
        connection_type:
          (navigator as any).connection?.effectiveType ?? "unknown",
        // Add custom data
        ...metric.customData,
      });

      // Send individual metric events for better segmentation
      sendGAEvent(`web_vital_${metric.name.toLowerCase()}`, {
        value: Math.round(metric.value),
        rating: metric.rating,
        delta: Math.round(metric.delta),
        id: metric.id,
        ...metric.customData,
      });

      if (this.config.debug) {
        log.debug(
          `📊 GA4 Web Vitals event sent: ${name}`,
          metric,
          "WebVitalsService"
        );
      }
    } catch {
      log.error("❌ Failed to send to GA4", null, "WebVitalsService");

      // Fallback to direct gtag if available
      if (typeof window !== "undefined" && (window as any).gtag) {
        try {
          (window as any).gtag("event", name, {
            event_category: "Web Vitals",
            event_label: metric.id,
            value: Math.round(metric.value),
            custom_map: metric.customData,
          });
        } catch {
          log.error("❌ Fallback GA4 also failed", null, "WebVitalsService");
        }
      }
    }
  }

  private sendToSentry(name: string, metric: CustomMetric): void {
    try {
      // Add breadcrumb for Sentry
      addBreadcrumb(`Web Vitals: ${name}`, "web-vitals", {
        value: metric.value,
        delta: metric.delta,
        rating: metric.rating,
        id: metric.id,
        navigationType: metric.navigationType,
        ...metric.customData,
      });

      // Report performance issues to Sentry
      if (metric.rating === "poor") {
        reportError(new Error(`Poor Web Vital: ${name}`), {
          metric: {
            name: metric.name,
            value: metric.value,
            rating: metric.rating,
            delta: metric.delta,
            id: metric.id,
            navigationType: metric.navigationType,
            customData: metric.customData,
          },
        });
      }

      if (this.config.debug) {
        log.debug(
          `📊 Sentry Web Vitals event sent: ${name}`,
          metric,
          "WebVitalsService"
        );
      }
    } catch {
      log.error("❌ Failed to send to Sentry", null, "WebVitalsService");
    }
  }

  private sendToCustomEndpoint(name: string, metric: CustomMetric): void {
    if (!this.config.customEndpoint) return;

    fetch(this.config.customEndpoint, {
      method: "POST",
      headers: {
        "Content-Type": "application/json",
      },
      body: JSON.stringify({
        name,
        value: metric.value,
        delta: metric.delta,
        id: metric.id,
        timestamp: Date.now(),
        url: window.location.href,
        userAgent: navigator.userAgent,
        ...metric.customData,
      }),
    }).catch(() => {
      log.error(
        `Failed to send metric to custom endpoint`,
        null,
        "WebVitalsService"
      );
    });
  }

  private checkPerformanceThresholds(name: string, metric: CustomMetric): void {
    const thresholds = {
      CLS: 0.25,
      FID: 100,
      FCP: 1800,
      LCP: 2500,
      TTFB: 800,
      APICallTime: 3000,
      FileProcessingTime: 5000,
      LongTask: 50,
    };

    const threshold = thresholds[name as keyof typeof thresholds];
    if (threshold && metric.value > threshold) {
      const message = `⚠️ Performance threshold exceeded: ${name} = ${metric.value.toFixed(2)} (threshold: ${threshold})`;

      if (this.config.enableSentry) {
        reportError(new Error(message), {
          metric: name,
          value: metric.value,
          threshold,
          ...metric.customData,
        });
      }

      if (this.config.enableConsoleLog) {
        log.warn(message, null, "WebVitalsService");
      }
    }
  }

  private measureCustomMetric(
    name: string,
    value: number,
    customData?: Record<string, any>
  ): void {
    const customMetric: CustomMetric = {
      name: name as any,
      value,
      delta: value,
      id: `${name.toLowerCase()}-${Date.now()}`,
      navigationType: "navigate",
      rating: "good",
      entries: [],
      ...(customData ? { customData } : {}),
    };

    this.handleMetric(name, customMetric);
  }

  private getMetricUnit(name: string): string {
    const units: Record<string, string> = {
      CLS: "",
      INP: "ms",
      FCP: "ms",
      LCP: "ms",
      TTFB: "ms",
      NavigationTiming: "ms",
      SlowResource: "ms",
      LongTask: "ms",
      APICallTime: "ms",
      FileProcessingTime: "ms",
      AppLoadTime: "ms",
    };

    return units[name] ?? "ms";
  }

  private getResourceType(url: string): string {
    if (url.includes(".js")) return "javascript";
    if (url.includes(".css")) return "stylesheet";
    if (
      url.includes(".png") ||
      url.includes(".jpg") ||
      url.includes(".jpeg") ||
      url.includes(".webp")
    )
      return "image";
    if (url.includes(".woff") || url.includes(".ttf")) return "font";
    if (url.includes("api")) return "api";
    return "other";
  }

  // Public methods
  public getMetrics(): Map<string, CustomMetric> {
    return new Map(this.metrics);
  }

  public getMetric(name: string): CustomMetric | undefined {
    return Array.from(this.metrics.values()).find(
      (metric) => metric.name === name
    );
  }

  public getPerformanceScore(): number {
    const metrics = Array.from(this.metrics.values());
    let score = 100;

    // Penalize based on Core Web Vitals
    metrics.forEach((metric) => {
      switch (metric.name) {
        case "CLS":
          if (metric.value > 0.25) score -= 20;
          else if (metric.value > 0.1) score -= 10;
          break;
        case "INP":
          if (metric.value > 200) score -= 20;
          else if (metric.value > 100) score -= 10;
          break;
        case "LCP":
          if (metric.value > 2500) score -= 20;
          else if (metric.value > 1800) score -= 10;
          break;
        case "FCP":
          if (metric.value > 1800) score -= 10;
          break;
        case "TTFB":
          if (metric.value > 800) score -= 10;
          break;
      }
    });

    return Math.max(0, score);
  }

  public destroy(): void {
    // Clean up observers
    this.observers.forEach((observer) => {
      observer.disconnect();
    });
    this.observers.clear();

    // Clear metrics
    this.metrics.clear();

    log.info("🔒 Web Vitals service destroyed", null, "WebVitalsService");
  }
}

// Create singleton instance
let webVitalsService: WebVitalsService | null = null;

export const initWebVitals = (config?: Partial<WebVitalsConfig>) => {
  if (webVitalsService) {
    log.warn(
      "⚠️ Web Vitals service already initialized",
      null,
      "WebVitalsService"
    );
    return webVitalsService;
  }

  webVitalsService = new WebVitalsService(config);

  // Track Web Vitals initialization in analytics
  try {
    sendGAEvent("web_vitals_initialized", {
      config: {
        enableGA4: config?.enableGA4,
        enableSentry: config?.enableSentry,
        enableConsoleLog: config?.enableConsoleLog,
        debug: config?.debug,
      },
      timestamp: Date.now(),
    });
  } catch {
    log.error(
      "❌ Failed to track Web Vitals initialization",
      null,
      "WebVitalsService"
    );
  }

  return webVitalsService;
};

export const getWebVitalsService = () => webVitalsService;

export const destroyWebVitals = () => {
  if (webVitalsService) {
    webVitalsService.destroy();
    webVitalsService = null;
  }
};

// Export types
export type { WebVitalsConfig, CustomMetric };

/**
 * Performance and Battery Detection Utility
 *
 * Detects device capabilities including:
 * - Battery status and charging state
 * - CPU cores and device memory
 * - Network connection quality
 * - Rendering capabilities
 * - Overall device performance level
 */

export interface DeviceCapabilities {
  // Battery info
  batteryLevel: number; // 0-1
  isCharging: boolean;
  chargingTime: number; // seconds
  dischargingTime: number; // seconds
  hasBattery: boolean;

  // Hardware info
  cpuCores: number;
  deviceMemory: number; // GB
  maxTouchPoints: number;

  // Network info
  effectiveType: "4g" | "3g" | "2g" | "slow-2g" | "unknown";
  downlink: number; // Mbps
  rtt: number; // milliseconds
  saveData: boolean;

  // Rendering capabilities
  maxFrameRate: number;
  canUseWebGL: boolean;
  canUseWebGL2: boolean;
  supportsOffscreenCanvas: boolean;
  supportsSharedArrayBuffer: boolean;

  // Performance level (0-10)
  performanceScore: number;
  deviceType:
    | "high-end"
    | "mid-range"
    | "low-end"
    | "mobile"
    | "tablet"
    | "desktop";
}

export interface ParticleConfig {
  maxParticles: number;
  particleSize: number;
  updateFrequency: number; // FPS
  enableBlur: boolean;
  enableGlow: boolean;
  enableShadows: boolean;
  textureQuality: "high" | "medium" | "low";
}

class PerformanceDetector {
  private capabilities: DeviceCapabilities | null = null;
  private batteryManager: any = null;
  private connectionInfo: any = null;
  private observers = new Set<(caps: DeviceCapabilities) => void>();

  constructor() {
    this.initializeBatteryAPI();
    this.initializeConnectionAPI();
    this.setupListeners();
  }

  private initializeBatteryAPI(): void {
    if ("getBattery" in navigator) {
      (navigator as any).getBattery().then((battery: any) => {
        this.batteryManager = battery;
        this.updateCapabilities();
        battery.addEventListener("levelchange", () =>
          this.updateCapabilities()
        );
        battery.addEventListener("chargingchange", () =>
          this.updateCapabilities()
        );
        battery.addEventListener("chargingtimechange", () =>
          this.updateCapabilities()
        );
        battery.addEventListener("dischargingtimechange", () =>
          this.updateCapabilities()
        );
      });
    }
  }

  private initializeConnectionAPI(): void {
    if ("connection" in navigator) {
      this.connectionInfo = (navigator as any).connection;
      this.updateCapabilities();
      this.connectionInfo.addEventListener("change", () =>
        this.updateCapabilities()
      );
    }
  }

  private setupListeners(): void {
    window.addEventListener("resize", () => this.updateCapabilities());
    document.addEventListener("visibilitychange", () =>
      this.updateCapabilities()
    );
  }

  private getBatteryInfo() {
    if (!this.batteryManager) {
      return {
        batteryLevel: 0.8,
        isCharging: false,
        chargingTime: Infinity,
        dischargingTime: Infinity,
        hasBattery: false,
      };
    }

    return {
      batteryLevel: this.batteryManager.level ?? 0.8,
      isCharging: this.batteryManager.charging ?? false,
      chargingTime: this.batteryManager.chargingTime ?? Infinity,
      dischargingTime: this.batteryManager.dischargingTime ?? Infinity,
      hasBattery: true,
    };
  }

  private getNetworkInfo() {
    if (!this.connectionInfo) {
      return {
        effectiveType: "4g" as const,
        downlink: 10,
        rtt: 50,
        saveData: false,
      };
    }

    return {
      effectiveType: (this.connectionInfo.effectiveType ?? "4g"),
      downlink: this.connectionInfo.downlink ?? 10,
      rtt: this.connectionInfo.rtt ?? 50,
      saveData: (this.connectionInfo.saveData ?? false) as boolean,
    };
  }

  private getHardwareInfo() {
    return {
      cpuCores: (navigator as any).hardwareConcurrency ?? 4,
      deviceMemory: (navigator as any).deviceMemory ?? 8,
      maxTouchPoints: navigator.maxTouchPoints || 0,
    };
  }

  private getRenderingCapabilities() {
    let canUseWebGL = false;
    let canUseWebGL2 = false;

    try {
      const canvas = document.createElement("canvas");
      canUseWebGL = !!canvas.getContext("webgl");
      canUseWebGL2 = !!canvas.getContext("webgl2");
    } catch {
      // WebGL not supported
    }

    return {
      maxFrameRate: this.getDeviceRefreshRate(),
      canUseWebGL,
      canUseWebGL2,
      supportsOffscreenCanvas: typeof OffscreenCanvas !== "undefined",
      supportsSharedArrayBuffer: typeof SharedArrayBuffer !== "undefined",
    };
  }

  private getDeviceRefreshRate(): number {
    if ("screen" in window && "refreshRate" in window.screen) {
      return (window.screen as any).refreshRate ?? 60;
    }
    return 60;
  }

  private calculatePerformanceScore(caps: Partial<DeviceCapabilities>): number {
    let score = 5; // Start at 5/10

    // Battery impact
    if (caps.hasBattery) {
      if (caps.batteryLevel! < 0.2) {
        score -= 2; // Low battery penalty
      } else if (caps.isCharging) {
        score += 1; // Charging bonus
      }
    }

    // CPU cores
    if (caps.cpuCores! >= 8) {
      score += 2;
    } else if (caps.cpuCores! >= 4) {
      score += 1;
    } else if (caps.cpuCores! <= 2) {
      score -= 1;
    }

    // Device memory
    if (caps.deviceMemory! >= 16) {
      score += 2;
    } else if (caps.deviceMemory! >= 8) {
      score += 1;
    } else if (caps.deviceMemory! <= 4) {
      score -= 1;
    }

    // Network
    if (caps.effectiveType === "4g") {
      score += 1;
    } else if (caps.effectiveType === "3g") {
      score -= 1;
    } else if (
      caps.effectiveType === "2g" ||
      caps.effectiveType === "slow-2g"
    ) {
      score -= 2;
    }

    // Rendering
    if (caps.canUseWebGL2) {
      score += 1;
    } else if (!caps.canUseWebGL) {
      score -= 1;
    }

    // Touch device
    if (caps.maxTouchPoints! > 0) {
      score -= 1; // Mobile devices typically have more constraints
    }

    return Math.max(0, Math.min(10, score));
  }

  private getDeviceType(): DeviceCapabilities["deviceType"] {
    const isMobile =
      /Android|webOS|iPhone|iPad|iPod|BlackBerry|IEMobile|Opera Mini/i.test(
        navigator.userAgent
      );
    const isTablet = /iPad|Android(?!.*Mobi)/i.test(navigator.userAgent);

    if (isTablet) return "tablet";
    if (isMobile) return "mobile";
    return "desktop";
  }

  public updateCapabilities(): DeviceCapabilities {
    const battery = this.getBatteryInfo();
    const network = this.getNetworkInfo();
    const hardware = this.getHardwareInfo();
    const rendering = this.getRenderingCapabilities();

    const capabilities: DeviceCapabilities = {
      ...battery,
      ...network,
      ...hardware,
      ...rendering,
      performanceScore: 0, // Will be calculated next
      deviceType: this.getDeviceType(),
    };

    capabilities.performanceScore =
      this.calculatePerformanceScore(capabilities);
    this.capabilities = capabilities;

    // Notify observers
    this.observers.forEach((observer) => observer(capabilities));

    return capabilities;
  }

  public getCapabilities(): DeviceCapabilities {
    if (!this.capabilities) {
      this.updateCapabilities();
    }
    return this.capabilities!;
  }

  public subscribe(observer: (caps: DeviceCapabilities) => void): () => void {
    this.observers.add(observer);
    return () => this.observers.delete(observer);
  }

  public getParticleConfig(): ParticleConfig {
    const caps = this.getCapabilities();

    // Base config
    const baseConfig: ParticleConfig = {
      maxParticles: 400,
      particleSize: 15,
      updateFrequency: 60,
      enableBlur: true,
      enableGlow: true,
      enableShadows: true,
      textureQuality: "high",
    };

    // Adjust based on performance score
    if (caps.performanceScore >= 9) {
      // High-end devices
      return {
        ...baseConfig,
        maxParticles: 800,
        particleSize: 20,
        updateFrequency: 120,
        textureQuality: "high",
      };
    } else if (caps.performanceScore >= 7) {
      // Mid-range devices
      return {
        ...baseConfig,
        maxParticles: 400,
        particleSize: 15,
        updateFrequency: 60,
        textureQuality: "high",
      };
    } else if (caps.performanceScore >= 5) {
      // Average devices
      return {
        ...baseConfig,
        maxParticles: 250,
        particleSize: 12,
        updateFrequency: 30,
        textureQuality: "medium",
      };
    } else if (caps.performanceScore >= 3) {
      // Low-end devices
      return {
        ...baseConfig,
        maxParticles: 150,
        particleSize: 10,
        updateFrequency: 24,
        enableShadows: false,
        enableGlow: false,
        textureQuality: "low",
      };
    } else {
      // Very low-end devices
      return {
        ...baseConfig,
        maxParticles: 50,
        particleSize: 8,
        updateFrequency: 12,
        enableBlur: false,
        enableShadows: false,
        enableGlow: false,
        textureQuality: "low",
      };
    }
  }

  public shouldDisableParticles(): boolean {
    const caps = this.getCapabilities();

    // Disable on very low battery
    if (caps.hasBattery && caps.batteryLevel < 0.15 && !caps.isCharging) {
      return true;
    }

    // Disable on very slow networks
    if (caps.effectiveType === "2g" || caps.effectiveType === "slow-2g") {
      return true;
    }

    // Disable on extremely low-end devices
    if (caps.performanceScore < 2) {
      return true;
    }

    // Disable when user prefers reduced motion
    if (window.matchMedia("(prefers-reduced-motion: reduce)").matches) {
      return true;
    }

    return false;
  }

  public shouldReduceQuality(): boolean {
    const caps = this.getCapabilities();
    return caps.performanceScore <= 5;
  }

  public getTargetFrameRate(): number {
    const caps = this.getCapabilities();
    const config = this.getParticleConfig();

    return Math.min(config.updateFrequency, caps.maxFrameRate);
  }
}

// Create singleton instance
export const performanceDetector = new PerformanceDetector();

// Export for testing
export { PerformanceDetector };

import type { Project as ApiProject } from "./api-types";

/**
 * Project store for managing current project state
 */

export interface Project extends ApiProject {
  name?: string;
  description?: string;
}

let currentProject: Project | null = null;

export function getCurrentProject(): Project | null {
  if (typeof window !== "undefined") {
    const stored = sessionStorage.getItem("currentProject");
    if (stored) {
      return JSON.parse(stored);
    }
  }
  return currentProject;
}

export function setCurrentProject(project: Project): void {
  currentProject = project;
  if (typeof window !== "undefined") {
    sessionStorage.setItem("currentProject", JSON.stringify(project));
  }
}

export function clearCurrentProject(): void {
  currentProject = null;
  if (typeof window !== "undefined") {
    sessionStorage.removeItem("currentProject");
  }
}

