// Utility function
const clamp = (value: number, min: number, max: number) => {
  return Math.max(min, Math.min(max, value));
};

// ====== SDF Functions ======

const sdBox = (
  px: number,
  py: number,
  bx: number,
  by: number,
  r: number
): number => {
  const dx = Math.abs(px) - bx;
  const dy = Math.abs(py) - by;
  return (
    Math.sqrt(Math.max(dx, 0) ** 2 + Math.max(dy, 0) ** 2) +
    Math.min(Math.max(dx, dy), 0) -
    r
  );
};

const sdCircle = (
  px: number,
  py: number,
  cx: number,
  cy: number,
  r: number
): number => {
  return Math.hypot(px - cx, py - cy) - r;
};

const sdRing = (
  px: number,
  py: number,
  cx: number,
  cy: number,
  r: number,
  thickness: number
): number => {
  return Math.abs(sdCircle(px, py, cx, cy, r)) - thickness;
};

const sdSegment = (
  px: number,
  py: number,
  ax: number,
  ay: number,
  bx: number,
  by: number,
  r: number
): number => {
  const pax = px - ax;
  const pay = py - ay;
  const bax = bx - ax;
  const bay = by - ay;
  const h = clamp((pax * bax + pay * bay) / (bax * bax + bay * bay), 0, 1);
  const dx = pax - bax * h;
  const dy = pay - bay * h;
  return Math.sqrt(dx * dx + dy * dy) - r;
};

const sdArc = (
  px: number,
  py: number,
  cx: number,
  cy: number,
  r: number,
  startAngle: number,
  endAngle: number,
  thickness: number
): number => {
  const dx = px - cx;
  const dy = py - cy;
  const angle = Math.atan2(dy, dx);

  let normAngle = angle;
  while (normAngle < startAngle) normAngle += Math.PI * 2;
  while (normAngle > endAngle + Math.PI * 2) normAngle -= Math.PI * 2;

  const clampedAngle = clamp(normAngle, startAngle, endAngle);
  const targetX = cx + Math.cos(clampedAngle) * r;
  const targetY = cy + Math.sin(clampedAngle) * r;

  return Math.hypot(px - targetX, py - targetY) - thickness;
};

// SDF boolean operations
const opUnion = (a: number, b: number): number => Math.min(a, b);
const opSubtract = (a: number, b: number): number => Math.max(a, -b);

// Character definitions
const STROKE_WIDTH = 0.035;
const BASELINE = 0.0;
const X_HEIGHT = 0.35;
const ASCENDER_HEIGHT = 0.65;
const DESCENDER_DEPTH = -0.25;
const ARABIC_HEIGHT = 0.45;

// Letters SDF definitions
const dist_t = (px: number, py: number): number => {
  const x = -1.7;
  const stem = sdSegment(
    px,
    py,
    x,
    BASELINE + ASCENDER_HEIGHT - 0.05,
    x,
    BASELINE,
    STROKE_WIDTH
  );
  const crossbar = sdSegment(
    px,
    py,
    x - 0.15,
    BASELINE + ASCENDER_HEIGHT,
    x + 0.15,
    BASELINE + ASCENDER_HEIGHT,
    STROKE_WIDTH
  );
  return opUnion(stem, crossbar);
};

const dist_h = (px: number, py: number): number => {
  const x = -1.25;
  const stem = sdSegment(
    px,
    py,
    x,
    BASELINE + ASCENDER_HEIGHT,
    x,
    BASELINE,
    STROKE_WIDTH
  );
  const shoulder = sdArc(
    px,
    py,
    x,
    BASELINE + X_HEIGHT * 0.8,
    0.22,
    -Math.PI / 2,
    0,
    STROKE_WIDTH
  );
  const rightLeg = sdSegment(
    px,
    py,
    x + 0.22,
    BASELINE + X_HEIGHT * 0.8,
    x + 0.22,
    BASELINE,
    STROKE_WIDTH
  );
  return opUnion(opUnion(stem, shoulder), rightLeg);
};

const dist_e = (px: number, py: number): number => {
  const cx = -0.6;
  const cy = BASELINE + X_HEIGHT * 0.5;
  const r = 0.2;
  let ring = sdRing(px, py, cx, cy, r, STROKE_WIDTH);
  const cutBox = sdBox(px - (cx + r * 0.5), py - cy, 0.15, 0.14, 0);
  ring = opSubtract(ring, cutBox);
  const bar = sdSegment(px, py, cx - r, cy, cx + r * 0.7, cy, STROKE_WIDTH);
  return opUnion(ring, bar);
};

const dist_c = (px: number, py: number): number => {
  const cx = 0.0;
  const cy = BASELINE + X_HEIGHT * 0.5;
  const r = 0.2;
  const ring = sdRing(px, py, cx, cy, r, STROKE_WIDTH);
  const cutBox = sdBox(px - (cx + r * 0.5), py - cy, 0.15, 0.14, 0);
  return opSubtract(ring, cutBox);
};

const dist_o = (px: number, py: number): number => {
  const cx = 0.5;
  const cy = BASELINE + X_HEIGHT * 0.5;
  const r = 0.2;
  return sdRing(px, py, cx, cy, r, STROKE_WIDTH);
};

const dist_p = (px: number, py: number): number => {
  const x = 1.0;
  const cy = BASELINE + X_HEIGHT * 0.5;
  const stem = sdSegment(
    px,
    py,
    x,
    BASELINE + X_HEIGHT,
    x,
    BASELINE + DESCENDER_DEPTH,
    STROKE_WIDTH
  );
  const bowl = sdRing(px, py, x + 0.2, cy, 0.17, STROKE_WIDTH);
  return opUnion(stem, bowl);
};

const dist_y = (px: number, py: number): number => {
  const x = 1.9;
  const top = BASELINE + X_HEIGHT;
  const mid = BASELINE + X_HEIGHT * 0.2;
  const leftArm = sdSegment(px, py, x - 0.15, top, x, mid, STROKE_WIDTH);
  const rightArm = sdSegment(px, py, x + 0.15, top, x, mid, STROKE_WIDTH);
  const descender = sdSegment(
    px,
    py,
    x,
    mid,
    x + 0.05,
    BASELINE + DESCENDER_DEPTH,
    STROKE_WIDTH
  );
  return opUnion(opUnion(leftArm, rightArm), descender);
};

const dist_dash = (px: number, py: number): number => {
  const x = 2.4;
  return sdSegment(
    px,
    py,
    x - 0.1,
    BASELINE + X_HEIGHT * 0.5,
    x + 0.1,
    BASELINE + X_HEIGHT * 0.5,
    STROKE_WIDTH * 0.8
  );
};

const dist_alef = (px: number, py: number): number => {
  const x = 2.9;
  const stem = sdSegment(
    px,
    py,
    x,
    BASELINE + ARABIC_HEIGHT * 0.95,
    x,
    BASELINE,
    STROKE_WIDTH * 1.2
  );
  const base = sdSegment(
    px,
    py,
    x - 0.03,
    BASELINE,
    x + 0.03,
    BASELINE,
    STROKE_WIDTH * 1.5
  );
  return opUnion(stem, base);
};

const dist_lam = (px: number, py: number): number => {
  const x = 3.3;
  const stem = sdSegment(
    px,
    py,
    x,
    BASELINE + ARABIC_HEIGHT * 0.95,
    x,
    BASELINE + 0.08,
    STROKE_WIDTH * 1.2
  );
  const hook = sdArc(
    px,
    py,
    x - 0.12,
    BASELINE + 0.08,
    0.12,
    0,
    Math.PI / 2,
    STROKE_WIDTH * 1.1
  );
  const hookEnd = sdSegment(
    px,
    py,
    x - 0.24,
    BASELINE,
    x - 0.15,
    BASELINE,
    STROKE_WIDTH
  );
  return opUnion(opUnion(stem, hook), hookEnd);
};

const dist_noon = (px: number, py: number): number => {
  const x = 3.75;
  const cy = BASELINE + ARABIC_HEIGHT * 0.4;
  const mainArc = sdArc(
    px,
    py,
    x,
    cy,
    0.18,
    -Math.PI * 0.15,
    Math.PI * 0.85,
    STROKE_WIDTH * 1.1
  );
  const connector = sdSegment(
    px,
    py,
    x - 0.17,
    cy - 0.05,
    x - 0.08,
    BASELINE + 0.02,
    STROKE_WIDTH
  );
  const base = sdSegment(
    px,
    py,
    x - 0.08,
    BASELINE + 0.02,
    x + 0.1,
    BASELINE,
    STROKE_WIDTH
  );
  const dot = sdCircle(px, py, x, cy + 0.28, 0.035);
  return opUnion(opUnion(opUnion(mainArc, connector), base), dot);
};

const dist_seen = (px: number, py: number): number => {
  const x = 4.25;
  const baseY = BASELINE + 0.02;
  const toothHeight = ARABIC_HEIGHT * 0.35;
  const baseLine = sdSegment(
    px,
    py,
    x - 0.28,
    baseY,
    x + 0.28,
    baseY,
    STROKE_WIDTH * 1.1
  );
  const tooth1 = sdArc(
    px,
    py,
    x - 0.18,
    baseY + toothHeight * 0.6,
    0.1,
    Math.PI * 0.9,
    Math.PI * 0.1,
    STROKE_WIDTH
  );
  const tooth2 = sdArc(
    px,
    py,
    x,
    baseY + toothHeight * 0.8,
    0.12,
    Math.PI * 0.9,
    Math.PI * 0.1,
    STROKE_WIDTH
  );
  const tooth3 = sdArc(
    px,
    py,
    x + 0.18,
    baseY + toothHeight * 0.6,
    0.1,
    Math.PI * 0.9,
    Math.PI * 0.1,
    STROKE_WIDTH
  );
  const connect1 = sdSegment(
    px,
    py,
    x - 0.18,
    baseY,
    x - 0.18,
    baseY + toothHeight * 0.5,
    STROKE_WIDTH * 0.8
  );
  const connect2 = sdSegment(
    px,
    py,
    x,
    baseY,
    x,
    baseY + toothHeight * 0.7,
    STROKE_WIDTH * 0.8
  );
  const connect3 = sdSegment(
    px,
    py,
    x + 0.18,
    baseY,
    x + 0.18,
    baseY + toothHeight * 0.5,
    STROKE_WIDTH * 0.8
  );
  return opUnion(
    opUnion(
      opUnion(
        opUnion(opUnion(opUnion(baseLine, tooth1), tooth2), tooth3),
        connect1
      ),
      connect2
    ),
    connect3
  );
};

const dist_khaa = (px: number, py: number): number => {
  const x = 4.75;
  const cy = BASELINE + ARABIC_HEIGHT * 0.4;
  const mainArc = sdArc(
    px,
    py,
    x,
    cy,
    0.2,
    Math.PI * 0.6,
    Math.PI * 2.4,
    STROKE_WIDTH * 1.1
  );
  const rightConnect = sdSegment(
    px,
    py,
    x + 0.15,
    cy - 0.12,
    x + 0.12,
    BASELINE,
    STROKE_WIDTH
  );
  const leftConnect = sdSegment(
    px,
    py,
    x - 0.15,
    cy - 0.12,
    x - 0.08,
    BASELINE,
    STROKE_WIDTH
  );
  const dot = sdCircle(px, py, x, cy + 0.28, 0.035);
  return opUnion(opUnion(opUnion(mainArc, rightConnect), leftConnect), dot);
};

const dist_taa_marbouta = (px: number, py: number): number => {
  const x = 5.2;
  const cy = BASELINE + ARABIC_HEIGHT * 0.4;
  let circle = sdRing(px, py, x, cy, 0.17, STROKE_WIDTH * 1.1);
  const opening = sdBox(px - x, py - (cy - 0.05), 0.08, 0.08, 0);
  circle = opSubtract(circle, opening);
  const dot1 = sdCircle(px, py, x - 0.07, cy + 0.28, 0.03);
  const dot2 = sdCircle(px, py, x + 0.07, cy + 0.28, 0.03);
  return opUnion(opUnion(circle, dot1), dot2);
};

// Combine all letters
const dist_all = (px: number, py: number): number => {
  return Math.min(
    dist_t(px, py),
    dist_h(px, py),
    dist_e(px, py),
    dist_c(px, py),
    dist_o(px, py),
    dist_p(px, py),
    dist_y(px, py),
    dist_dash(px, py),
    dist_alef(px, py),
    dist_lam(px, py),
    dist_noon(px, py),
    dist_seen(px, py),
    dist_khaa(px, py),
    dist_taa_marbouta(px, py)
  );
};

// ====== Particle Generation Logic ======

function generateParticles(config: GenerateParticlesMessage["config"]) {
  const { numParticles, thickness, minX, maxX, minY, maxY, maxAttempts } =
    config;

  const positions = new Float32Array(numParticles * 3);
  const colors = new Float32Array(numParticles * 3);

  let generatedCount = 0;
  let attempts = 0;
  let lastProgressReport = 0;

  while (generatedCount < numParticles && attempts < maxAttempts) {
    attempts++;

    const x = Math.random() * (maxX - minX) + minX;
    const y = Math.random() * (maxY - minY) + minY;
    const z = Math.random() * thickness - thickness / 2;

    const d = dist_all(x, y);
    const threshold = x > 2.5 ? 0.015 : 0.01;

    if (d <= threshold) {
      const idx = generatedCount * 3;
      positions[idx] = x;
      positions[idx + 1] = y;
      positions[idx + 2] = z;
      colors[idx] = 1;
      colors[idx + 1] = 1;
      colors[idx + 2] = 1;
      generatedCount++;

      // Report progress every 10%
      const progress = (generatedCount / numParticles) * 100;
      if (progress - lastProgressReport >= 10) {
        lastProgressReport = progress;
        self.postMessage({
          type: "progress",
          progress,
          count: generatedCount,
        });
      }
    }
  }

  // Fallback if not enough particles generated
  if (generatedCount < 200) {
    const fallbackCount = Math.min(numParticles, 3000);
    for (let j = 0; j < fallbackCount; j++) {
      const idx = j * 3;
      positions[idx] = (Math.random() - 0.5) * 6;
      positions[idx + 1] = (Math.random() - 0.5) * 3.5;
      positions[idx + 2] = (Math.random() - 0.5) * 0.3;
      colors[idx] = 1;
      colors[idx + 1] = 1;
      colors[idx + 2] = 1;
    }
    generatedCount = fallbackCount;
  }

  // Create final arrays
  const finalPositions = positions.slice(0, generatedCount * 3);
  const finalColors = colors.slice(0, generatedCount * 3);
  const originalPositions = positions.slice(0, generatedCount * 3);
  const phases = new Float32Array(generatedCount);
  const velocities = new Float32Array(generatedCount * 3);

  for (let j = 0; j < generatedCount; j++) {
    phases[j] = Math.random() * Math.PI * 2;
  }

  return {
    positions: finalPositions,
    colors: finalColors,
    count: generatedCount,
    originalPositions,
    phases,
    velocities,
  };
}

// ====== Worker Message Handler ======

function isTrustedWorkerMessage(event: MessageEvent<unknown>): boolean {
  return event.origin === "" || event.origin === self.location.origin;
}

self.addEventListener(
  "message",
  (event: MessageEvent<GenerateParticlesMessage>) => {
    if (!isTrustedWorkerMessage(event)) {
      return;
    }

    const { type, config } = event.data;

    if (type === "generate") {
      try {
        const result = generateParticles(config);

        self.postMessage(
          {
            type: "complete",
            ...result,
          },
          {
            transfer: [
              result.positions.buffer,
              result.colors.buffer,
              result.originalPositions.buffer,
              result.phases.buffer,
              result.velocities.buffer,
            ],
          }
        );
      } catch (error) {
        self.postMessage({
          type: "error",
          error: error instanceof Error ? error.message : "Unknown error",
        });
      }
    }
  }
);

export {};

/**
 * Web Worker for particle physics calculations
 * Offloads position, velocity, and color calculations from main thread
 */

interface ParticlePosition {
  px: number;
  py: number;
  pz: number;
}

interface ParticleVelocity {
  vx: number;
  vy: number;
  vz: number;
}

interface EffectConfig {
  effectRadius: number;
  repelStrength: number;
}

type Effect = "default" | "spark" | "wave" | "vortex";

interface UpdateParticlesMessage {
  type: "update";
  positions: Float32Array;
  velocities: Float32Array;
  originalPositions: Float32Array;
  colors: Float32Array;
  particleCount: number;
  config: {
    effect: Effect;
    effectRadius: number;
    repelStrength: number;
    attractStrength: number;
    damping: number;
    intersectionPoint: { x: number; y: number; z: number } | null;
    time: number;
  };
}

interface UpdateParticlesResult {
  type: "updated" | "error";
  positions?: Float32Array;
  velocities?: Float32Array;
  colors?: Float32Array;
  error?: string;
}

// ====== Physics Functions ======

function applySparkEffect(
  particle: ParticlePosition,
  intersection: { x: number; y: number; z: number },
  velocity: ParticleVelocity,
  config: EffectConfig
): ParticleVelocity {
  const dx = particle.px - intersection.x;
  const dy = particle.py - intersection.y;
  const dz = particle.pz - intersection.z;
  const distSq = dx * dx + dy * dy + dz * dz;

  if (distSq < config.effectRadius * config.effectRadius && distSq > 0.0001) {
    const dist = Math.sqrt(distSq);
    const force = (1 - dist / config.effectRadius) * config.repelStrength * 3;
    return {
      vx: velocity.vx + (dx / dist) * force,
      vy: velocity.vy + (dy / dist) * force,
      vz: velocity.vz + (dz / dist) * force,
    };
  }

  return velocity;
}

function applyWaveEffect(
  particle: ParticlePosition,
  intersection: { x: number; y: number; z: number },
  velocity: ParticleVelocity,
  config: EffectConfig,
  time: number
): ParticleVelocity {
  const dx = particle.px - intersection.x;
  const dy = particle.py - intersection.y;
  const dz = particle.pz - intersection.z;
  const distSq = dx * dx + dy * dy + dz * dz;

  if (distSq < config.effectRadius * config.effectRadius) {
    const dist = Math.sqrt(distSq);
    const wavePhase = time * 8 - dist * 12;
    const waveStrength = 0.12;
    const waveForce =
      Math.sin(wavePhase) * waveStrength * (1 - dist / config.effectRadius);
    if (dist > 0.001) {
      return {
        vx: velocity.vx + (dx / dist) * waveForce,
        vy: velocity.vy + (dy / dist) * waveForce,
        vz: velocity.vz + waveForce * 0.5,
      };
    }
  }

  return velocity;
}

function applyVortexEffect(
  particle: ParticlePosition,
  intersection: { x: number; y: number; z: number },
  velocity: ParticleVelocity,
  config: EffectConfig
): ParticleVelocity {
  const dx = particle.px - intersection.x;
  const dy = particle.py - intersection.y;
  const dz = particle.pz - intersection.z;
  const distSq = dx * dx + dy * dy + dz * dz;
  const dist = Math.sqrt(distSq);

  if (distSq < config.effectRadius * config.effectRadius && dist > 0.05) {
    const vortexStrength = 0.15;
    const spiralForce = vortexStrength * (1 - dist / config.effectRadius);

    const tangentX = -dy;
    const tangentY = dx;
    const tangentLength = Math.sqrt(tangentX * tangentX + tangentY * tangentY);

    let newVx = velocity.vx;
    let newVy = velocity.vy;

    if (tangentLength > 0.001) {
      newVx += (tangentX / tangentLength) * spiralForce;
      newVy += (tangentY / tangentLength) * spiralForce;
    }

    const pullStrength = spiralForce * 0.3;
    newVx -= (dx / dist) * pullStrength;
    newVy -= (dy / dist) * pullStrength;

    return {
      vx: newVx,
      vy: newVy,
      vz: velocity.vz,
    };
  }

  return velocity;
}

function applyDefaultEffect(
  particle: ParticlePosition,
  intersection: { x: number; y: number; z: number },
  velocity: ParticleVelocity,
  config: EffectConfig
): ParticleVelocity {
  const dx = particle.px - intersection.x;
  const dy = particle.py - intersection.y;
  const dz = particle.pz - intersection.z;
  const distSq = dx * dx + dy * dy + dz * dz;
  const dist = Math.sqrt(distSq);

  if (distSq < config.effectRadius * config.effectRadius && distSq > 0.0001) {
    const force = (1 - dist / config.effectRadius) * config.repelStrength;
    return {
      vx: velocity.vx + (dx / dist) * force,
      vy: velocity.vy + (dy / dist) * force,
      vz: velocity.vz + (dz / dist) * force,
    };
  }

  return velocity;
}

function applyParticleEffect(
  effect: Effect,
  position: ParticlePosition,
  intersection: { x: number; y: number; z: number },
  velocity: ParticleVelocity,
  config: EffectConfig,
  time: number
): ParticleVelocity {
  switch (effect) {
    case "spark":
      return applySparkEffect(position, intersection, velocity, config);
    case "wave":
      return applyWaveEffect(position, intersection, velocity, config, time);
    case "vortex":
      return applyVortexEffect(position, intersection, velocity, config);
    case "default":
      return applyDefaultEffect(position, intersection, velocity, config);
  }
}

function applyAttraction(
  position: ParticlePosition,
  target: { x: number; y: number; z: number },
  velocity: ParticleVelocity,
  attractStrength: number
): ParticleVelocity {
  return {
    vx: velocity.vx + (target.x - position.px) * attractStrength,
    vy: velocity.vy + (target.y - position.py) * attractStrength,
    vz: velocity.vz + (target.z - position.pz) * attractStrength,
  };
}

function applyDamping(
  velocity: ParticleVelocity,
  damping: number
): ParticleVelocity {
  return {
    vx: velocity.vx * damping,
    vy: velocity.vy * damping,
    vz: velocity.vz * damping,
  };
}

function updatePosition(
  position: ParticlePosition,
  velocity: ParticleVelocity
): ParticlePosition {
  return {
    px: position.px + velocity.vx,
    py: position.py + velocity.vy,
    pz: position.pz + velocity.vz,
  };
}

// ====== Color Calculation Functions ======

function calculateWaveColor(
  particle: ParticlePosition,
  intersection: { x: number; y: number; z: number },
  effectRadius: number,
  time: number
): { r: number; g: number; b: number } {
  const dx = particle.px - intersection.x;
  const dy = particle.py - intersection.y;
  const dz = particle.pz - intersection.z;
  const distSq = dx * dx + dy * dy + dz * dz;
  const dist = Math.sqrt(distSq);

  if (distSq < effectRadius * effectRadius) {
    const wavePhase = time * 8 - dist * 15;
    const intensity =
      Math.abs(Math.sin(wavePhase)) * (1 - dist / effectRadius) + 1;
    return {
      r: intensity * 0.5 + 0.8,
      g: intensity * 0.8 + 0.6,
      b: intensity * 1.2 + 0.4,
    };
  }

  return { r: 1, g: 1, b: 1 };
}

function calculateVortexColor(
  particle: ParticlePosition,
  intersection: { x: number; y: number; z: number },
  effectRadius: number,
  time: number
): { r: number; g: number; b: number } {
  const dx = particle.px - intersection.x;
  const dy = particle.py - intersection.y;
  const dz = particle.pz - intersection.z;
  const distSq = dx * dx + dy * dy + dz * dz;
  const dist = Math.sqrt(distSq);

  if (distSq < effectRadius * effectRadius) {
    const angle = Math.atan2(dy, dx) + time * 5;
    const intensity = (1 - dist / effectRadius) * 2 + 1;
    return {
      r: (Math.sin(angle) * 0.5 + 0.5) * intensity,
      g: (Math.sin(angle + (Math.PI * 2) / 3) * 0.5 + 0.5) * intensity,
      b: (Math.sin(angle + (Math.PI * 4) / 3) * 0.5 + 0.5) * intensity,
    };
  }

  return { r: 1, g: 1, b: 1 };
}

function calculateParticleColor(
  effect: Effect,
  position: ParticlePosition,
  intersection: { x: number; y: number; z: number } | null,
  effectRadius: number,
  time: number
): { r: number; g: number; b: number } {
  if (!intersection) {
    return { r: 1, g: 1, b: 1 };
  }

  if (effect === "wave") {
    return calculateWaveColor(position, intersection, effectRadius, time);
  }
  if (effect === "vortex") {
    return calculateVortexColor(position, intersection, effectRadius, time);
  }

  return { r: 1, g: 1, b: 1 };
}

// ====== Main Update Function ======

function updateParticles(message: UpdateParticlesMessage) {
  const {
    positions,
    velocities,
    originalPositions,
    colors,
    particleCount,
    config,
  } = message;

  const {
    effect,
    effectRadius,
    repelStrength,
    attractStrength,
    damping,
    intersectionPoint,
    time,
  } = config;

  const effectConfig: EffectConfig = {
    effectRadius,
    repelStrength,
  };

  // Process all particles
  for (let j = 0; j < particleCount; j++) {
    const idx = j * 3;

    // Get current position
    const position: ParticlePosition = {
      px: positions[idx] ?? 0,
      py: positions[idx + 1] ?? 0,
      pz: positions[idx + 2] ?? 0,
    };

    // Get target (original) position
    const target = {
      x: originalPositions[idx] ?? 0,
      y: originalPositions[idx + 1] ?? 0,
      z: originalPositions[idx + 2] ?? 0,
    };

    // Get current velocity
    let velocity: ParticleVelocity = {
      vx: velocities[idx] ?? 0,
      vy: velocities[idx + 1] ?? 0,
      vz: velocities[idx + 2] ?? 0,
    };

    // Apply effect if mouse is hovering
    if (intersectionPoint) {
      velocity = applyParticleEffect(
        effect,
        position,
        intersectionPoint,
        velocity,
        effectConfig,
        time
      );
    }

    // Attract back to original position
    velocity = applyAttraction(position, target, velocity, attractStrength);
    velocity = applyDamping(velocity, damping);

    // Update position
    const newPos = updatePosition(position, velocity);
    positions[idx] = newPos.px;
    positions[idx + 1] = newPos.py;
    positions[idx + 2] = newPos.pz;

    // Update velocity
    velocities[idx] = velocity.vx;
    velocities[idx + 1] = velocity.vy;
    velocities[idx + 2] = velocity.vz;

    // Calculate and apply color
    const color = calculateParticleColor(
      effect,
      newPos,
      intersectionPoint,
      effectRadius,
      time
    );
    colors[idx] = color.r;
    colors[idx + 1] = color.g;
    colors[idx + 2] = color.b;
  }

  return {
    positions,
    velocities,
    colors,
  };
}

// ====== Worker Message Handler ======

function isTrustedWorkerMessage(event: MessageEvent<unknown>): boolean {
  return event.origin === "" || event.origin === self.location.origin;
}

self.addEventListener(
  "message",
  (event: MessageEvent<UpdateParticlesMessage>) => {
    if (!isTrustedWorkerMessage(event)) {
      return;
    }

    const { type } = event.data;

    if (type === "update") {
      try {
        const result = updateParticles(event.data);

        self.postMessage(
          {
            type: "updated",
            ...result,
          },
          {
            transfer: [
              result.positions.buffer,
              result.velocities.buffer,
              result.colors.buffer,
            ],
          }
        );
      } catch (error) {
        self.postMessage({
          type: "error",
          error: error instanceof Error ? error.message : "Unknown error",
        });
      }
    }
  }
);

export {};

import { logger } from "@/lib/ai/utils/logger";

/**
 * Pipeline Agent Manager
 * Manages background worker for pipeline execution
 */

import type {
  ExecutePipelineMessage,
  ExecuteStepMessage,
  CancelPipelineMessage,
  PipelineAgentResult,
  PipelineAgentPool,
  PipelineExecutionCallback,
} from "./pipeline-agent-types";
import type { PipelineStep } from "@/orchestration/executor";

export class PipelineAgentManager {
  private workerPool: PipelineAgentPool = {
    worker: null,
  };

  private callbacks = new Map<string, PipelineExecutionCallback>();

  /**
   * Initialize the pipeline agent worker
   */
  async initialize(): Promise<void> {
    try {
      this.workerPool.worker = new Worker(
        new URL("./pipeline-agent.worker.ts", import.meta.url),
        { type: "module" }
      );

      this.workerPool.worker.addEventListener(
        "message",
        this.handleWorkerMessage.bind(this)
      );
      this.workerPool.worker.addEventListener(
        "error",
        this.handleWorkerError.bind(this)
      );
    } catch (error) {
      logger.error("Failed to initialize pipeline agent worker");
      throw error;
    }
  }

  /**
   * Handle messages from worker
   */
  private handleWorkerMessage(event: MessageEvent<PipelineAgentResult>) {
    const result = event.data;

    switch (result.type) {
      case "progress":
        this.handleProgress(result);
        break;
      case "complete":
        this.handleComplete(result);
        break;
      case "step-complete":
        this.handleStepComplete(result);
        break;
      case "error":
        this.handleError(result);
        break;
      case "cancelled":
        this.handleCancelled(result);
        break;
    }
  }

  /**
   * Handle worker errors
   */
  private handleWorkerError(error: ErrorEvent) {
    logger.error("Pipeline agent worker error:", error);

    // Notify all active callbacks
    this.callbacks.forEach((callback) => {
      if (callback.onError) {
        callback.onError(error.message);
      }
    });
  }

  /**
   * Handle progress updates
   */
  private handleProgress(
    result: Extract<PipelineAgentResult, { type: "progress" }>
  ) {
    const callback = this.callbacks.get(result.executionId);
    if (callback?.onProgress) {
      callback.onProgress(
        result.progress,
        result.completedSteps,
        result.status
      );
    }
  }

  /**
   * Handle completion
   */
  private handleComplete(
    result: Extract<PipelineAgentResult, { type: "complete" }>
  ) {
    const callback = this.callbacks.get(result.executionId);
    if (callback?.onComplete) {
      callback.onComplete(result.results);
    }
    this.callbacks.delete(result.executionId);
  }

  /**
   * Handle step completion
   */
  private handleStepComplete(
    result: Extract<PipelineAgentResult, { type: "step-complete" }>
  ) {
    const callback = this.callbacks.get(result.executionId);

    if (result.success && callback?.onStepComplete && result.result) {
      callback.onStepComplete(result.stepId, result.result);
    } else if (!result.success && callback?.onError && result.error) {
      callback.onError(result.error);
    }
  }

  /**
   * Handle errors
   */
  private handleError(result: Extract<PipelineAgentResult, { type: "error" }>) {
    if (result.executionId) {
      const callback = this.callbacks.get(result.executionId);
      if (callback?.onError) {
        callback.onError(result.error);
      }
      this.callbacks.delete(result.executionId);
    } else {
      logger.error("Pipeline agent error:", result.error);
    }
  }

  /**
   * Handle cancellation
   */
  private handleCancelled(
    result: Extract<PipelineAgentResult, { type: "cancelled" }>
  ) {
    const callback = this.callbacks.get(result.executionId);
    if (callback?.onCancel) {
      callback.onCancel();
    }
    this.callbacks.delete(result.executionId);
  }

  /**
   * Execute pipeline in background worker
   */
  executePipeline(
    executionId: string,
    steps: PipelineStep[],
    inputData: Record<string, any>,
    callback?: PipelineExecutionCallback
  ): void {
    if (!this.workerPool.worker) {
      throw new Error("Pipeline agent worker not initialized");
    }

    if (callback) {
      this.callbacks.set(executionId, callback);
    }

    const message: ExecutePipelineMessage = {
      type: "execute-pipeline",
      executionId,
      steps,
      inputData,
    };

    this.workerPool.worker.postMessage(message);
  }

  /**
   * Execute single step in background worker
   */
  executeStep(
    executionId: string,
    step: PipelineStep,
    inputData: Record<string, any>,
    callback?: PipelineExecutionCallback
  ): void {
    if (!this.workerPool.worker) {
      throw new Error("Pipeline agent worker not initialized");
    }

    if (callback) {
      this.callbacks.set(executionId, callback);
    }

    const message: ExecuteStepMessage = {
      type: "execute-step",
      executionId,
      step,
      inputData,
    };

    this.workerPool.worker.postMessage(message);
  }

  /**
   * Cancel pipeline execution
   */
  cancelExecution(executionId: string): void {
    if (!this.workerPool.worker) {
      return;
    }

    const message: CancelPipelineMessage = {
      type: "cancel",
      executionId,
    };

    this.workerPool.worker.postMessage(message);
    this.callbacks.delete(executionId);
  }

  /**
   * Terminate worker and cleanup
   */
  terminate(): void {
    if (this.workerPool.worker) {
      this.workerPool.worker.terminate();
      this.workerPool.worker = null;
    }
    this.callbacks.clear();
  }

  /**
   * Check if worker is initialized
   */
  isInitialized(): boolean {
    return !!this.workerPool.worker;
  }
}

// Singleton instance
export const pipelineAgentManager = new PipelineAgentManager();

/**
 * Type definitions for Pipeline Agent Worker
 */

import type { PipelineStep } from "@/orchestration/executor";

// ====== Pipeline Agent Worker Messages ======

export interface ExecutePipelineMessage {
  type: "execute-pipeline";
  executionId: string;
  steps: PipelineStep[];
  inputData: Record<string, any>;
}

export interface ExecuteStepMessage {
  type: "execute-step";
  executionId: string;
  step: PipelineStep;
  inputData: Record<string, any>;
  previousResults?: Record<string, any>;
}

export interface CancelPipelineMessage {
  type: "cancel";
  executionId: string;
}

export type PipelineAgentMessage =
  | ExecutePipelineMessage
  | ExecuteStepMessage
  | CancelPipelineMessage;

// ====== Pipeline Agent Worker Results ======

export interface ProgressResult {
  type: "progress";
  executionId: string;
  progress: number;
  completedSteps: number;
  status: string;
}

export interface CompleteResult {
  type: "complete";
  executionId: string;
  results: Record<string, any>;
  success: true;
}

export interface StepCompleteResult {
  type: "step-complete";
  executionId: string;
  stepId: string;
  result?: any;
  success: boolean;
  error?: string;
}

export interface ErrorResult {
  type: "error";
  error: string;
  executionId?: string;
}

export interface CancelledResult {
  type: "cancelled";
  executionId: string;
}

export type PipelineAgentResult =
  | ProgressResult
  | CompleteResult
  | StepCompleteResult
  | ErrorResult
  | CancelledResult;

// ====== Pipeline Agent Manager Types ======

export interface PipelineAgentPool {
  worker: Worker | null;
}

export interface PipelineExecutionCallback {
  onProgress?: (
    progress: number,
    completedSteps: number,
    status: string
  ) => void;
  onStepComplete?: (stepId: string, result: any) => void;
  onComplete?: (results: Record<string, any>) => void;
  onError?: (error: string) => void;
  onCancel?: () => void;
}

/**
 * Background Agent Worker for Pipeline Execution
 * Handles heavy AI pipeline processing off the main thread
 */

import type {
  PipelineAgentMessage,
  PipelineAgentResult,
} from "./pipeline-agent-types";

function isTrustedWorkerMessage(event: MessageEvent<unknown>): boolean {
  return event.origin === "" || event.origin === self.location.origin;
}

// Worker message handler
self.addEventListener(
  "message",
  async (event: MessageEvent<PipelineAgentMessage>) => {
    if (!isTrustedWorkerMessage(event)) {
      return;
    }

    const message = event.data;

    try {
      switch (message.type) {
        case "execute-pipeline":
          await executePipeline(message);
          break;
        case "execute-step":
          await executeStep(message);
          break;
        case "cancel":
          handleCancel(message.executionId);
          break;
        default:
          sendError("Unknown message type");
      }
    } catch (error) {
      sendError(
        error instanceof Error ? error.message : "Worker execution failed"
      );
    }
  }
);

// Active execution tracking
const activeExecutions = new Map<string, AbortController>();

/**
 * Execute full pipeline in background
 */
async function executePipeline(
  message: Extract<PipelineAgentMessage, { type: "execute-pipeline" }>
) {
  const { executionId, steps, inputData } = message;
  const controller = new AbortController();
  activeExecutions.set(executionId, controller);

  try {
    sendProgress(executionId, 0, steps.length, "started");

    const results = new Map<string, any>();
    const executedSteps = new Set<string>();

    for (let i = 0; i < steps.length; i++) {
      if (controller.signal.aborted) {
        sendCancelled(executionId);
        return;
      }

      const step = steps[i];
      if (!step) {
        sendError(`Missing step at index ${i}`);
        return;
      }

      // Check dependencies
      const canExecute =
        !step.dependencies ||
        step.dependencies.every((dep) => executedSteps.has(dep));

      if (!canExecute) {
        sendError(`Dependencies not satisfied for step ${step.id}`);
        return;
      }

      // Execute step
      const stepResult = await executeStepLogic(step, inputData, results);
      results.set(step.id, stepResult);
      executedSteps.add(step.id);

      // Send progress
      const progress = ((i + 1) / steps.length) * 100;
      sendProgress(executionId, progress, i + 1, "running");
    }

    // Send completion
    sendComplete(executionId, results);
  } catch (error) {
    sendError(
      error instanceof Error ? error.message : "Pipeline execution failed"
    );
  } finally {
    activeExecutions.delete(executionId);
  }
}

/**
 * Execute single step in background
 */
async function executeStep(
  message: Extract<PipelineAgentMessage, { type: "execute-step" }>
) {
  const { executionId, step, inputData } = message;

  try {
    const result = await executeStepLogic(step, inputData, new Map());

    const response: PipelineAgentResult = {
      type: "step-complete",
      executionId,
      stepId: step.id,
      result,
      success: true,
    };

    self.postMessage(response);
  } catch (error) {
    sendStepError(
      executionId,
      step.id,
      error instanceof Error ? error.message : "Step execution failed"
    );
  }
}

/**
 * Core step execution logic
 */
async function executeStepLogic(
  step: any,
  inputData: Record<string, any>,
  previousResults: Map<string, any>
): Promise<any> {
  const startTime = Date.now();

  // Simulate API call with timeout
  const timeout = step.timeout ?? 60000;

  const executionPromise = new Promise((resolve) => {
    // In real implementation, this would call the API endpoint
    // For now, simulate processing
    setTimeout(() => {
      resolve({
        stepId: step.id,
        data: {
          analysis: `Processed ${step.name}`,
          inputSize: JSON.stringify(inputData).length,
          previousSteps: Array.from(previousResults.keys()),
        },
        duration: Date.now() - startTime,
      });
    }, 1000); // Simulate 1s processing
  });

  const timeoutPromise = new Promise((_, reject) => {
    setTimeout(() => reject(new Error(`Step ${step.id} timed out`)), timeout);
  });

  return Promise.race([executionPromise, timeoutPromise]);
}

/**
 * Handle cancellation
 */
function handleCancel(executionId: string) {
  const controller = activeExecutions.get(executionId);
  if (controller) {
    controller.abort();
    activeExecutions.delete(executionId);
    sendCancelled(executionId);
  }
}

/**
 * Send progress update
 */
function sendProgress(
  executionId: string,
  progress: number,
  completedSteps: number,
  status: string
) {
  const response: PipelineAgentResult = {
    type: "progress",
    executionId,
    progress,
    completedSteps,
    status,
  };
  self.postMessage(response);
}

/**
 * Send completion
 */
function sendComplete(executionId: string, results: Map<string, any>) {
  const response: PipelineAgentResult = {
    type: "complete",
    executionId,
    results: Object.fromEntries(results),
    success: true,
  };
  self.postMessage(response);
}

/**
 * Send error
 */
function sendError(error: string) {
  const response: PipelineAgentResult = {
    type: "error",
    error,
  };
  self.postMessage(response);
}

/**
 * Send step error
 */
function sendStepError(executionId: string, stepId: string, error: string) {
  const response: PipelineAgentResult = {
    type: "step-complete",
    executionId,
    stepId,
    success: false,
    error,
  };
  self.postMessage(response);
}

/**
 * Send cancellation
 */
function sendCancelled(executionId: string) {
  const response: PipelineAgentResult = {
    type: "cancelled",
    executionId,
  };
  self.postMessage(response);
}

